window.__SUMMARY_PARTS__=window.__SUMMARY_PARTS__||[];window.__SUMMARY_PARTS__.push([{"i":36000,"as":"为解决双极性有机混合离子电子导体（OMIECs）在离子与电子传输间的权衡限制，研究人员通过精确的分子量裁剪，开发出一种面取向比例高达85.5%、主链结晶度提升四倍的新型OMIEC材料。该材料同步增强了垂直离子传输和电子传输，实现了电子性能的协同优化，为临床视神经修复和仿生机器人领域的光调制人工神经元提供了技术支持。","scd":null,"kp":["[光敏双极性有机混合离子-电子导体]: 离子与电子传输之间存在制约，导致品质因数（μC*）偏低且P/N模式不平衡"]},{"i":36001,"as":"","scd":null,"kp":[]},{"i":36002,"as":"","scd":null,"kp":[]},{"i":36003,"as":"一项针对人工智能聊天机器人健康相关查询的系统评估表明，人们正越来越多地使用AI来填补医疗保健信息的空白。这也凸显了当前医疗保健服务供给的不足以及AI公司应承担的责任。","scd":null,"kp":[]},{"i":36004,"as":"","scd":null,"kp":[]},{"i":36005,"as":"","scd":null,"kp":[]},{"i":36006,"as":"针对阿尔茨海默病（AD）早期检测的迫切需求，开发了一种可被BACE1酶解组装的纳米探针（19F-Cy5.5-NP）。BACE1是AD早期的公认生物标志物，该纳米探针能够实现体内19F磁共振/近红外荧光（19F MR/NIR-FL）“开启式”成像，从而检测AD体内的BACE1酶活性。","scd":null,"kp":["[早期阿尔茨海默病诊断靶点]: β-分泌酶（BACE1）","[BACE1体内活体成像]: 罕见报道缺乏，开发出可被BACE1解体的纳米探针（19F-Cy5.5-NP）"]},{"i":36007,"as":"在3-苯乙烯的催化加氢（TCH）反应中，施加正电化学电位可以诱导生成单一产物（1-乙基-3-硝基苯），且产量提升了六倍。这种电化学催化促进方法无需复杂的催化剂修饰，即可对含有多个官能团的底物实现完全的化学选择性控制。","scd":null,"kp":["[含多官能团底物的电催化促进转化]: 施加正电化学电位可诱导完全的化学选择性"]},{"i":36008,"as":"在基于环糊精纳米管的疏水空腔内，利用特定设计的两性发光体成功激活了分子间激发态质子转移（PT）。尽管该化合物在光激发态发生pKa反转，但空间位阻阻碍了分子内质子转移。在γ-环糊精存在下，光酸组装成客体对，实现了相邻分子间的预组织质子转移。","scd":null,"kp":["[激发态质子转移调控]: 利用两性发射体在光激发态下发生pKa反转，在环糊精基纳米管的疏水空腔内激活分子间激发态质子转移"]},{"i":36009,"as":"研究人员通过连接体构象工程，成功合成了由六核锆簇和固有螺旋的Tröger碱构成的两种双链螺旋金属聚合物单晶。该成果解决了具有确定性原子坐标的双链绞合螺旋聚合物合成难题。外消旋连接体会发生自发拆分，为功能性一维螺旋材料提供了新的合成路径。","scd":null,"kp":["[双链互缠螺旋金属聚合物合成]: 通过配体构象工程实现了具有确定性原子坐标的双链螺旋金属聚合物单晶制备"]},{"i":36010,"as":"针对富锂锰基氧化物阴极中阴离子氧化还原可逆性差导致晶格氧流失的问题，研究提出了一种表面化学无序工程策略。通过阳离子在晶格中的过饱和占据，实现晶格氧的空间重排，使氧电子结构离域并增强金属-氧轨道杂化，有效提升了阴离子氧化还原反应的可逆性和动力学。","scd":null,"kp":["[富锂锰基正极材料]: 阴离子氧化还原反应提供高容量，但可逆性差会导致严重的晶格氧损失和表面结构演变","[阴离子氧化反应问题解决策略]: 在正极表面引入基于化学无序的结晶织构，通过晶格氧的空间重排来稳定结构"]},{"i":36011,"as":"针对铁基纳米酶在癌症催化治疗中受限于内源性过氧化氢不足的问题，研究通过限制配位策略合成了具有超高二价铁含量(66.59%)的介孔非晶氧化铁纳米球。这种由二甲双胍稳定的自级联纳米酶整合了氧化酶和过氧化物酶活性，实现了在超低剂量下的强效肿瘤治疗。","scd":null,"kp":["[高剂量铁氧化物纳米酶肿瘤催化治疗]: 受限于内源性H2O2不足","[自级联纳米酶构建]: 将二甲双胍稳定的无定形氧化铁用于整合氧化酶和过氧化物酶活性","[Fe(II)稳定技术]: 实现超高含量Fe(II)的稳定，支持在超低剂量下进行强效肿瘤治疗"]},{"i":36012,"as":"为平衡二氧化钌在析氧反应中的活性与稳定性，研究开发了负载于二氧化钛上的氟掺杂二氧化钌。通过构建Ru-O-Ti界面平台调节电负性，优化了钌中心的电子结构。该催化剂在酸性介质中表现出高效且稳定的析氧反应催化性能。","scd":null,"kp":["[酸性析氧反应(OER)催化剂]: RuO2理论上具有高活性且价格低于IrO2，但平衡其活性和稳定性仍面临挑战","[RuO2电催化剂稳定性与活性提升策略]: 通过质子辅助吸附演化将氟掺杂的RuO2锚定在TiO2上以调节Ru中心的电子结构"]},{"i":36013,"as":"研究提出了一种非共价锚定策略，通过一锅法将18-冠-6原位嵌入多孔硫代锡酸盐框架的层间。这种结构不仅保证了冠醚的有序排列，还保留了其固有的配位自由度，使其在结晶态吸附剂中能够实现高效的锶离子主客体识别与捕获。","scd":null,"kp":["客体分子[吸附剂]: 锶离子","主体分子[结晶态吸附剂]: 18-冠-6 (18Cr6)","策略[柔性超分子构象控制]: 非共价原位锚定策略"]},{"i":36014,"as":"研究合成了具有工程化Ni-O-V桥连结构的NiV层状双氢氧化物微球双通道电催化剂。该结构有效调节了Ni和V位点的电子结构，协同促进了阳极1,5-戊二醇电氧化生成戊二酸和阴极硝酸盐还原反应，实现了生物质增值与高盐废水处理的耦合电解。","scd":null,"kp":["催化剂[电催化耦合反应]: 薄层NiV-LDHs微球","催化位点[NiV-LDHs]: Ni-O-V桥连结构","阳极反应[共电解系统]: 生物质衍生多元醇(1,5-戊二醇)氧化","阴极反应[共电解系统]: 硝酸盐还原"]},{"i":36015,"as":"研究探讨了具有层间缠绕特征的三维共价有机框架中亚胺键连接异构现象。两种异构体框架具有几乎相同的组成、拓扑和孔隙率，但C=N键方向的细微差异导致其光电性能和荧光传感行为出现显著区别，其中3D-An-CN-COF的荧光传感灵敏度高出近一个数量级。","scd":null,"kp":["材料结构[3D COFs]: 层间纠缠的二维网络结构","异构体[3D COFs]: 具有相反亚胺键取向的连接键异构对","调控机制[荧光传感]: 亚胺连接键异构现象"]},{"i":36016,"as":"针对四氟甲烷水解催化剂难以同时兼顾高活性和高稳定性的问题，研究开发了一种熵稳定的铝酸盐催化剂。该催化剂打破了传统氧化铝基催化剂在强氟化、富蒸汽条件下的活性-稳定性权衡，有效避免了比表面积损失、体相氟化和生成无催化活性的α相氧化铝。","scd":null,"kp":["催化目标[温室气体消除]: CF4水解","核心痛点[传统氧化铝催化剂]: 高催化活性与稳定性之间的权衡制约","材料设计[CF4水解催化剂]: 打破活性-稳定性Tradeoff的熵稳定铝酸盐"]},{"i":36017,"as":"为解决二氧化碳还原生成甲烷面临的选择性挑战，研究采用配体微工程策略，合成了一系列全N-杂环卡宾保护的Cu4O团簇。通过次级球非共价相互作用，成功将二氧化碳电还原反应定向转化为甲烷，实现了对活性位点和竞争路径的精确控制。","scd":null,"kp":["催化剂[CO2还原制CH4]: 全NHC(氮杂环卡宾)保护的铜簇","控制机制[CH4选择性生成]: 次级球非共价相互作用","工程策略[活性位点控制]: 配体微工程策略"]},{"i":36018,"as":"研究提出一种溶剂辅助水热法，在ZSM-5沸石中合成了尺寸为6-7纳米的均匀银纳米颗粒。该催化剂通过直接活化C-H键，驱动末端炔烃与二氧化碳的羧化反应生成稳定C-C键，实现了二氧化碳向不饱和多碳羧酸衍生物的高效转化，为人工碳固定提供了新路径。","scd":null,"kp":["催化剂[CO2与端炔转化]: ZSM-5沸石限域的均匀银纳米颗粒","反应途径[人工碳固定]: 末端炔烃羧基化构建C-C键"]},{"i":36019,"as":"利用全化学合成法，研究成功制备了在已知体内热点位置（Asn17和Asn42）含有异天冬氨酸的β2-微球蛋白变体。结构分析表明，异天冬氨酸修饰显著增强了β2m的纤维形成能力，直接证实了翻译后异天冬氨酸的形成是引发透析相关淀粉样变性的关键分子触发因素。","scd":null,"kp":[]},{"i":36020,"as":"研究首次将吲哚并[2,3-c]咔唑引入多共振热激活延迟荧光材料设计中，提出多位点硼化策略。通过电子和空间位阻控制，分别生成了在524nm处发射绿光（半峰宽20nm）的exo构型，以及在566nm处发射黄光（半峰宽25nm）的endo构型，实现了OLED超窄带发射的精确调控。","scd":null,"kp":["发光材料[OLED]: 吲哚[2,3-c]咔唑桥连的窄带MR-TADF发射体","工程策略[MR-TADF材料]: 精确的多位点硼化策略"]},{"i":36021,"as":"针对凝胶聚合物电解质中复杂的锂离子传输动力学限制，研究提出将TFSI−配位齿数从单齿调节为三齿。实验证实，决定电池循环性能的主导因素是固体电解质界面相（SEI）的本征化学性质，而非体相离子电导率或去溶剂化能。三齿配位策略成功解耦了上述传输过程。","scd":null,"kp":["电解质[锂金属电池]: 凝胶聚合物电解质","溶剂化鞘层[克服动力学限制]: 三齿配位工程策略","关键瓶颈[Li+传输]: 由体相扩散、去溶剂化和界面传输动态耦合引起的动力学限制步骤"]},{"i":36022,"as":"针对环保型纤维素基固态电解质存在高压耐受性差和锂离子传导缓慢等问题，研究采用原位溶胶-凝胶自组装结合氨基-硅氧烷接枝改性。该功能接枝实现了纤维素-氨基-硅氧烷-离子液体的均匀复合，形成致密的基体，有效调节了锂离子传导和通量，适用于可持续锂金属电池。","scd":null,"kp":["电解质[固态电池]: 环保型纤维素基复合电解质","改性策略[纤维素电解质]: 氨基硅氧烷功能接枝改性","克服缺陷[纤维素基电解质]: 改善高结晶度导致的耐高压性差、Li+传导缓慢和Li+通量不均"]},{"i":36023,"as":"为解决有机光催化剂析氢过程中的电荷分离难题，研究采用冰模板辅助光化学还原策略，构建了具有分子级界面接触的三叶草型供体-受体分子与超薄氮化碳纳米片异质结。同时锚定铜单原子并沉积铂纳米点，产生的内建电场大幅促进光生载流子分离，实现高效光催化产氢。","scd":null,"kp":["光催化剂[光催化析氢]: 三叶草型供体-受体分子(DTAB)与超薄氮化碳纳米片的有机异质结","制备策略[分子级界面接触]: 冰模板辅助光化学还原策略","功能目标[异质结构建]: 实现多尺度活性位点调控以促进电荷分离和界面动力学"]},{"i":36024,"as":"该综述全面概述了纤维状水系锌离子电池的最新进展。文章从组成、结构设计、工作原理和失效机制等方面展开，重点分析了锌枝晶生长、析氢、表面钝化、正极材料溶解及变形下界面剥离等机械与电化学耦合问题，并详细总结了相应的缓解策略。","scd":null,"kp":["应用场景[纤维状水系锌离子电池]: 可穿戴和柔性电子设备的电源供应","技术瓶颈[纤维状水系锌离子电池]: 锌枝晶生长、析氢反应(H2 evolution)、表面钝化"]},{"i":36025,"as":"该综述探讨了人工智能在加速有机材料发现中的应用。文章重点介绍了图神经网络、生成模型和主动学习等机器学习技术，通过将分子结构与性能关联，解决有机半导体等新材料在性能预测、逆向设计和高通量筛选中的核心挑战，实现化学空间的快速探索。","scd":null,"kp":["核心技术[人工智能驱动有机材料发现]: 利用机器学习(如图神经网络、生成式方法)链接分子结构与性质以加速新型有机半导体化合物的识别"]},{"i":36026,"as":"研究开发了一种无模板、能量驱动的晶面导向结晶策略，成功合成具有可调孔结构和暴露高能晶面的介孔单晶金属氧化物。聚乙烯吡咯烷酮兼作孔隙维持剂和表面能调节剂，在稳定高能晶面并维持介孔的同时引导单晶生长，表现出优异的选择性催化氧化性能。","scd":null,"kp":["核心优势[介孔单晶金属氧化物]: 结合了高表面可及性和长程晶格连贯性","合成策略[高能面取向介孔单晶金属氧化物]: 无模板、能量驱动的面导向结晶策略"]},{"i":36027,"as":"研究深入探讨了复杂液体混合物中气泡聚结时间较纯液体增长数个数量级的机制。通过使用互溶性油类二元混合物作为模型系统，结合实验与理论，阐明了液体表面热力学、气液界面间的分子相互作用及气泡曲率几何形状对气泡聚结速率的调控作用。","scd":null,"kp":["聚结行为[纯液体]: 由相同成分界面的吸引力相互作用决定，机制明确","聚结行为[复杂液体]: 机制尚不明确，受表面热力学和分子间相互作用的复杂影响"]},{"i":36028,"as":"为探索生命早期RNA自我复制机制，研究人员利用乳液体外筛选技术，开发出一种能够催化鸟苷和环状三偏磷酸盐生成鸟苷三磷酸（GTP）的核酶。这种具有提高GTP周转率的核酶，为早期生命依赖核酸三磷酸盐驱动聚合化提供了实验支撑。","scd":null,"kp":["能量驱动机制[早期生命自我复制核酶]: 使用核苷5'-三磷酸(NTP)进行模板化RNA聚合","催化活性[GTP合酶核酶]: 具有增加的GTP转化率"]},{"i":36029,"as":"","scd":null,"kp":[]},{"i":36030,"as":"","scd":null,"kp":[]},{"i":36031,"as":"高价态钴氧络合物（Co(IV)=O）是温和条件下催化烯烃环氧化的有效候选者，但其效用常受分步电子转移引发的自由基副反应限制。研究提出通过平面三配位钴位点激活过氧单硫酸盐（PMS），利用几何介导的配位场调节来改变Co(IV)=O中心的自旋态，生成中间自旋的Co(IV)=O物种。该自旋态工程策略成功规避了副反应，实现了高效的直接氧原子转移。","scd":null,"kp":["催化机制[四价钴-氧络合物(调节自旋态)]: 实现直接氧原子转移(OAT)，规避了逐步电子转移介导的自由基副反应","应用场景[四价钴-氧络合物]: 温和条件下的高效烯烃环氧化"]},{"i":36032,"as":"针对认知自上而下影响感知的脑电图（EEG）证据，研究通过三项实验重新评估了希腊语受试者在颜色变化时早期的脑电差异波现象。实验采用经典的odball范式交替呈现标准刺激和偏差刺激，计算视觉对比适应。结果表明，早期差异波主要反映了对比适应现象，而非语言的认知分类自动影响早期感知。","scd":null,"kp":["神经编码机制[不同类别颜色的感知]: 认知并不自动影响感知(通过对希腊语中'蓝色'类别的脑电图研究证实)"]},{"i":36033,"as":"在铁基超导体中，dz2轨道带通常远离费米能级。以单层FeSe/SrTiO3为模型，研究利用探针诱导的拉伸应变可控地将dz2能带移向费米能级，实现了超导性的两阶段增强。在初始阶段，面内晶格膨胀增强了电子关联性从而放大超导性；随着应变进一步增加，轨道与关联性的协同作用继续提升超导性能。","scd":null,"kp":["超导机制[单层FeSe/SrTiO3]: 通过轨道和关联的协同作用实现超导的双重增强","调控方法[单层FeSe/SrTiO3]: 探针诱导的拉伸应变可控地移动dz²轨道能带"]},{"i":36034,"as":"","scd":null,"kp":[]},{"i":36035,"as":"","scd":null,"kp":[]},{"i":36036,"as":"","scd":null,"kp":[]},{"i":36037,"as":"","scd":null,"kp":[]},{"i":36038,"as":"核苷酸类似物（NA）通过靶向病毒RNA依赖性RNA聚合酶（RdRp）用于治疗RNA病毒感染，但冠状病毒和沙粒病毒编码的外切核酸酶结构域可识别并切除已整合的NA，从而产生天然耐药性。由于聚合和切除反应都以核苷酸α-磷酸盐为机制中心，研究提供了磷酸构型反转的结构证据，证明可实现对RNA合成和修复两个连续催化步骤的序贯抑制，为克服耐药性提供了方法。","scd":null,"kp":["耐药机制[冠状病毒和沙粒病毒RNA]: 编码的核酸外切酶结构域可识别并切除掺入的核苷类似物，提供天然耐药性"]},{"i":36039,"as":"","scd":null,"kp":[]},{"i":36040,"as":"后期促进复合体/周期体（APC/C）控制真核细胞有丝分裂进程，而辅激活蛋白Cdc20在退出有丝分裂时会被APC/C催化的泛素化反应靶向降解。既往研究提出Cdc20的泛素化由结合在APC/C共激活位点上的Cdc20通过分子内“顺式”机制直接完成。该机制推论主要依赖于对Cdc20的IR尾巴突变破坏结合的观察，本研究重新探讨了该泛素化机制的具体作用途径。","scd":null,"kp":["泛素化机制[有丝分裂调节蛋白Cdc20]: 由APC/C催化，存在分子内'顺式'机制假设"]},{"i":36041,"as":"","scd":null,"kp":[]},{"i":36042,"as":"耳蜗毛细胞的顶端连接由原钙黏蛋白15（PCDH15）和钙黏蛋白23组成，长度约150纳米，负责向机械转导（MET）通道传递力。通过冷冻电镜（Cryo-EM）解析了PCDH15胞外结构域的三维结构，发现两个PCDH15分子通过链交叉和平行接触形成平行的顺式二聚体，构成了右手双螺旋结构。功能研究证实，PCDH15二聚化界面的突变会直接影响其生理功能。","scd":null,"kp":["复合物结构[耳蜗毛细胞顶端连接]: PCDH15与钙粘蛋白23组装的细胞外微丝","复合物长度[顶端连接]: 约150 nm","结构特征[PCDH15]: 右手双螺旋二聚体架构"]},{"i":36043,"as":"针对靶向特定结构位点的蛋白质从头设计，现有自上而下方法先生成总形状再优化序列。本研究提出了一种自下而上的生成模型Void-X，通过训练掩码离散扩散模型，针对特定结构区域生成原子簇以实现最佳堆积。该模型填补了复杂蛋白质相互作用设计在原子层面的空间堆积预测空白，优化了靶向结合区域的蛋白设计流程。","scd":null,"kp":["[蛋白质相互作用设计]: 基于生成式AI（Transformer和扩散模型）的自上而下填充空洞结构生成方法"]},{"i":36044,"as":"在早期RNA世界中，RNA聚合酶核酶负责复制遗传信息，但其常因提前终止和低保真度导致全长活性序列产率低下。研究证实了核酶介导的RNA序列修复机制，在焦磷酸盐饱和浓度条件下，聚合酶核酶能够修复错配和受损的RNA序列，提高复制保真度。这种修复机制有助于长链RNA的准确复制，为可进化系统提供了优势。","scd":null,"kp":["[RNA聚合酶核酶]: 通过焦磷酸介导的RNA修复机制提升复制保真度"]},{"i":36045,"as":"","scd":null,"kp":[]},{"i":36046,"as":"光的振幅、相位和偏振分布的测量对科学发现及光学计量、通信等技术至关重要。研究提出一种基于喷墨打印向列相液晶微滴阵列的低成本、紧凑型全矢量场传感器。该传感器利用微滴空间变化的双折射特性，通过分波前偏振测量技术，实现了对光的关键特性参数的单次同时测量。","scd":null,"kp":["光场传感技术[硬件设备]: 利用液晶液滴阵列实现低成本、紧凑的全矢量场（振幅、相位、偏振）传感","光场传感技术[探测能力]: 具备单次成像传感功能"]},{"i":36047,"as":"双碳分子（C2）不仅是化学键基准和碳材料自下而上合成的结构单元，也是天体化学的关键物种。长达两个世纪的研究揭示了C2复杂的电子结构，其特征为密集的低能态电子态、准简并前沿轨道和显著的多构型特性。研究通过光谱学和动力学分析，深入探究了C2分子的高激发电子态及其反应动态。","scd":null,"kp":["[双碳分子(C2)]: 高激发电子态的光谱学与动力学研究揭示其复杂电子结构特征"]},{"i":36048,"as":"理解发光二极管（LED）中量子点的电激发水平是器件机制研究的核心。研究提出了一种通过分析量子点的电激发水平与载流子注入平衡来评估器件质量的方法。通过定量建模电致发光强度和电激发下产生的平均激子数，提取了反映电流利用效率的关键参数，为缓解电致发光效率滚降现象提供了设计指导。","scd":null,"kp":["[量子点发光二极管]: 通过量化电激发水平和载流子注入平衡来评估器件质量并缓解电致发光效率下降"]},{"i":36049,"as":"无序（非晶）材料在储能、非线性光学和催化领域极具应用潜力，其复杂的短程和中程有序结构提供了广阔的设计空间。针对大体积结构数据缺乏导致的非晶材料逆向设计发展受限问题，研究开发了基于机器学习扩散模型的逆向设计方法，绕开试错法，成功实现了具有目标特定性质的非晶材料生成与设计。","scd":null,"kp":["[非晶材料]: 依赖机器学习的逆向设计替代试错法以实现具有目标特性的结构设计"]},{"i":36050,"as":"神经损伤由于组织再生能力有限及伤后抑制性微环境成为临床重大挑战。丝素蛋白（SF）作为一种天然蛋白质生物材料，因其机械性能可调、降解可控及易修饰等特点在神经修复中备受关注。研究指出，基于丝素蛋白的生物材料不仅能提供被动的物理结构支架，还能主动调节神经微环境，提供生物学指令，从而有效促进神经再生与功能恢复。","scd":null,"kp":["生物材料[神经修复]: 提供结构支撑与生物学指令的丝素蛋白基材料"]},{"i":36051,"as":"","scd":null,"kp":[]},{"i":36052,"as":"研究提出一种基于单材料的机械折纸编码3D剪纸平台，实现了兼具前所未有的拉伸性和面积覆盖率的可编程3D光伏电池。折纸结构将2D几何形状转换为3D形式，有效克服了传统3D光伏电池在集成到机械变形平台时，大面积机械拉伸性必然导致面积覆盖率降低的长期矛盾。该结构策略为下一代最大化空间利用率和功率输出的能源系统提供了新途径。","scd":null,"kp":["[三维光伏电池]: 采用单材料、机械折纸编码的三维剪纸结构结合纳米根锚定AgNWs-In-Ga多相合金导体实现可变形与空间高利用率"]},{"i":36053,"as":"研究通过在Au(788)原子级精确定义的台阶边缘修饰N-杂环卡宾（NHCs），增强了其对电化学二氧化碳还原的催化活性，性能优于未修饰的金属台阶边缘。高分辨率扫描探针显微镜揭示了三种不同的NHC在台阶边缘具有直立倾斜的吸附几何形状和统一的结合模式。这些结构明确的纳米结构表现出卓越的稳定性，解决了单分子水平上有机配体台阶边缘特异性功能化的问题。","scd":null,"kp":["催化剂[电化学CO2还原]: Au(788)台阶边缘修饰N-杂环卡宾","[表面功能化]: 单分子水平的特定台阶边缘有机配体功能化修饰增强催化活性"]},{"i":36054,"as":"在温和条件下将甲烷、氮气和二氧化碳等极为稳定且储量丰富的分子活化和转化为高附加值产品，是能源与环境化学的关键问题。文章总结了过去五年气相团簇反应性的研究进展。在无干扰的隔离环境中进行的气相团簇反应性研究，能够在分子水平上提供关于惰性化学键活化和转化的基本见解，从而为高效催化剂的合理设计提供指导。","scd":null,"kp":["[气相团簇反应]: 研究甲烷、氮气、二氧化碳等稳定分子在温和条件下的活化与转化机制"]},{"i":36055,"as":"针对多相催化中短寿命活性中间体的时空控制难题，研究受酶区室化启发，报告了一种适配体功能化的金-铁双单原子催化剂。该材料将原子分散的Au-Fe位点与基因工程识别元件结合，创建了具有两个协同界面的“智能反应口袋”。Au-Fe异核原子对通过电子调制d带中心来锁定转化过程，从而在复杂介质中实现对活性中间体扩散的精准控制和高选择性转化。","scd":null,"kp":["催化剂[双单原子催化剂]: 适配体功能化的Au-Fe双单原子催化剂(Apt-Au1-Fe1/NC)","[催化环境]: 模仿酶分室效应以实现对短寿命活性中间体的时空控制"]},{"i":36056,"as":"针对聚合物水凝胶电解质在柔性锌空气电池中面临的锌枝晶生长及离子导电性、氧渗透性等多方面权衡限制，研究开发了一种中性、3D物理交联的PFCD水凝胶。该水凝胶通过Fe3+离子的紧密配位网络与β-环糊精的宽泛氢键网络协同结合，并原位掺入N-羧乙基壳聚糖构建而成。这种分级多网络架构为解决电解质界面与环境稳定性问题提供了方案。","scd":null,"kp":["电解质[柔性中性锌空气电池]: 3D物理交联PFCD聚合物水凝胶电解质","[材料特性]: 兼具强粘附性、自愈性、透氧性并抑制锌枝晶生长"]},{"i":36057,"as":"为实现大规模量子计算机中的多重并行量子比特读取，研究提出了一种超稳定的超导量子比特读取方法。该方法采用最初为光学腔开发的多音自相位参考Pound-Drever-Hall（PDH）技术。利用PDH技术可有效提升超导量子比特读取过程的稳定性，解决了量子计算系统扩展至大规模时必需的并行读取难题。","scd":null,"kp":["[超导量子比特读取]: 采用多音自相位参考Pound-Drever-Hall(PDH)技术实现超稳定的并行读取"]},{"i":36058,"as":"硅中的单一核自旋因具有长相干时间和高保真度控制，是量子技术的理想资源。研究成功将锗-73（73Ge）核自旋耦合到静电定义的硅量子点中。研究人员已在供体核上编码量子比特和量子dit，并成功演示了贝尔态和量子存储器，证明了该同位素在硅基量子计算架构中的实用潜力。","scd":null,"kp":["[硅基量子点]: 实现了$^{73}\\mathrm{Ge}$核自旋与静电定义量子点的耦合","[量子特性]: 硅中的单核自旋具有长相干时间和优异的控制保真度"]},{"i":36059,"as":"研究提出了关于屏蔽偶极分子三体物理学的量子力学描述，并预测了可观察到的Efimov物理现象。尽管偶极分子间的相互作用具有各向异性和长程特性，但微波屏蔽技术使得系统在双体层面上就能展现出普适性规律。该研究揭示了在超冷微波屏蔽极性分子体系中存在 Efimov效应的物理机制。","scd":null,"kp":["[超冷微波屏蔽极性分子]: 预测并描述了屏蔽偶极分子的三体物理及可观测的Efimov效应"]},{"i":36060,"as":"与电子不同，不带电玻色子的轨道运动不产生磁矩，无法与磁场直接相互作用。为了准确表述磁振子的轨道角动量（OAM），研究通过考虑Aharonov-Casher效应，首先确定了其正确的共轭变量。该理论成功构建了平衡态下磁振子轨道角动量的理论体系，阐明了该物理量的核心基础与机制。","scd":null,"kp":["[磁子轨道角动量]: 通过考虑Aharonov-Casher效应来确定无电荷玻色子的正确共轭变量以构建理论"]},{"i":36061,"as":"研究证明了Kerr度规代表了自对偶和反自对偶Taub-Newman-Unti-Tamburino（NUT）瞬子的非线性叠加。这一发现将传统的Newman-Janis算法提升为具有明确物理起源的Kerr度规严谨推导过程。基于同样的数学推导逻辑，该研究方法也适用于严格推导Kerr-Newman度规。","scd":null,"kp":[]},{"i":36062,"as":"涌现的集体激发是相互作用量子多体系统的核心特征，但固态平台中的研究长期受限于线性响应探针和有限的动量分辨率。研究提出将动量分辨技术与二维光谱相结合，以克服上述实验局限性。该方法被用作探测非线性量子场动力学的新工具，能够直接探测固态相互作用系统中的非线性量子场演化。","scd":null,"kp":["[光谱学技术]: 提出动量分辨二维光谱技术以探测非线性量子场动力学"]},{"i":36063,"as":"","scd":null,"kp":[]},{"i":36064,"as":"在双轴拉伸应变下的钛酸铅（PbTiO3）材料中，研究揭示了应变梯度和90度畴壁的自发出现及其物理机制。通过发现隐藏的极性-声子耦合效应，该研究成功实现了通过电场切换对材料内部的应变梯度和90°畴壁进行全局控制，解决了对材料新兴功能特性进行灵活全局控制的基础物理挑战。","scd":null,"kp":["[PbTiO$_3$应变梯度]: 发现通过隐藏的极性-声学耦合，可在双轴拉伸应变下实现应变梯度和90°畴壁的电学开关控制"]},{"i":36065,"as":"研究提出一种实时量子蒙特卡洛算法，用于模拟开放量子系统的动力学演化。该算法通过在马尔可夫和非马尔可夫主方程下随机压缩和演化密度矩阵，利用种群动力学连续压制符号问题。这种抑制符号问题的算法为存在噪声的含噪量子电路模拟提供了新的计算途径，有效提升了模拟效率。","scd":null,"kp":["[量子电路模拟]: 提出一种实时的符号问题抑制量子蒙特卡洛算法来模拟开放量子系统动力学"]},{"i":36066,"as":"","scd":null,"kp":[]},{"i":36067,"as":"快速相干态传输对量子计算至关重要，而绝热传输虽保真度高但耗时过长。研究提出一种适应性强的Bang-Bang-Bang协议来实现原子量子比特的快速相干态传输。该方法在保证高状态制备保真度的同时，大幅缩短了操作时间，有效提高了量子信息处理的效率。","scd":null,"kp":["[原子量子比特相干传输]: Bang-Bang-Bang协议可避免绝热传输的长耗时并保持高保真度"]},{"i":36068,"as":"","scd":null,"kp":[]},{"i":36069,"as":"研究证明机器学习技术能够显著减少精确预测动态演化系统进展所需的时间步数量。该方法被成功应用于分子动力学的长时间步长模拟中。通过学习系统的作用量，机器学习模型有效加速了复杂的分子动力学演化计算，提升了大规模物理体系模拟的计算效率。","scd":null,"kp":[]},{"i":36070,"as":"研究采用神经网络方法结合物理驱动的β衰变半衰期公式，对原子核β衰变半衰期进行了深入研究。这种融合物理信息的机器学习方法，在与实验半衰期数据的比对中，取得了比复杂微观核模型更好的一致性，展现出在核物理属性预测方面的卓越准确度。","scd":null,"kp":[]},{"i":36071,"as":"研究预测在极化激元环境下的分子聚集体中存在异常的热激活超辐射现象。与自由空间的情况截然相反，当激子-声子耦合强度或系统温度升高时，该体系内的集体发光辐射反而会被增强。研究通过微观模型成功捕捉并解释了这一反直觉的物理现象，揭示了极化激元的协助机制。","scd":null,"kp":["[极化子环境中分子聚集体]: 激子-声子耦合增强或温度升高会反常增强热激活超辐射"]},{"i":36072,"as":"介绍了一种在模拟中测量脂质膜高斯曲率模数的拓扑方法。脂质膜的分裂与融合是维持细胞器形状和实现细胞间物质运输的重要过程，这些改变拓扑结构的事件涉及与高斯曲率成正比的曲率弹性自由能变化。该研究成果发表于《物理评论快报》。","scd":null,"kp":["[脂质膜高斯曲率模量测量]: 采用拓扑方法通过模拟实现"]},{"i":36073,"as":"研究了斯格明子晶格中位错的拓扑转变与弹性发生，突破了基特尔的磁性-极性类比理论。研究发现，斯格明子位错表现出具有大斯格明子变形和拓扑相变的内在核心结构。该研究成果发表于《物理评论快报》。","scd":null,"kp":["[斯格明子晶格位错]: 具有大的斯格明子形变和拓扑相变的内在核心结构"]},{"i":36074,"as":"探讨了一维玻色气体中作为分数费米海的奇异临界态。临界量子场理论因长程相关性而具有固有的普适性，其中Tomonaga-Luttinger液体描述了大量低温下的一维量子系统。该研究揭示了这些量子系统在临界态下的特殊物理行为。成果发表于《物理评论快报》。","scd":null,"kp":["[一维玻色气体]: 表现为分数费米海的奇异临界态"]},{"i":36075,"as":"开发了一种具有分区化学环境的全固态共价有机框架电解质(SCE-COF)。通过在COF纳米通道内进行高介电单体的纳米受限共聚，构建了纳米受限分子界面。该界面集成了富含电子的极性短链以形成丰富的锂离子跳跃位点，同时利用缺电子的孔壁区域固定阴离子，实现了离子的选择性传输，提升了固态电池的安全性。","scd":null,"kp":["[全固态共价有机框架电解质]: 具有分区化学环境(SCE-COF)并介电工程化","[固态电池SSE]: 兼具高离子电导率、优异离子选择性和强电化学/热稳定性"]},{"i":36076,"as":"提出了一种通过在表面涂覆过氧化氢酶纳米涂层来控制释氧水凝胶气泡形成的策略，以构建厘米级类组织结构。针对三维厚支架中氧气耗竭导致细胞存活率低的问题，利用过氧化钙水解释放双氧水，并通过过氧化氢酶将其转化为氧气。该方法成功控制了气泡形成位点，避免了不受控的氧气释放造成的结构损伤。","scd":null,"kp":["[释氧水凝胶(CaO2-过氧化氢酶体系)]: 提出控制气泡生成位点的策略以构建厘米级组织工程支架"]},{"i":36077,"as":"开发了利用肿瘤细胞内谷胱甘肽(GSH)诱导原位产生氧空位的FeOOH纳米纺锤体，用于增强声催化肿瘤治疗。这种原位缺陷工程促进了声催化过程中的活性氧(ROS)生成，有效提升抗肿瘤疗效并降低脱靶毒性。氧空位的引入使带隙变窄、费米能级升高，促进了电荷分离，克服了传统体外缺陷引入方法缺乏肿瘤特异性的问题。","scd":null,"kp":["[FeOOH纳米纺锤体声催化剂]: 肿瘤内谷胱甘肽(GSH)诱导原位生成氧空位(O_vac)以提升ROS生成并降低脱靶风险"]},{"i":36078,"as":"揭示了共溶剂调控的超分子手性在肽基纳米材料中引发显著压电响应的机制。研究合成了一种发色团共轭肽(PEP-A)，在不同溶剂条件下自组装成具有压电活性或非活性状态的纳米材料。通过光谱、显微镜和原子模拟综合研究，发现其功能行为与手性光学性质密切相关，为自供电生物医疗器械的开发提供了新途径。","scd":null,"kp":["[多肽基压电纳米材料]: 共溶剂调制的超分子手性展现出显著的压电响应"]},{"i":36079,"as":"报道了一种名为苯胺腺嘌呤二核苷酸(AnAD)的合成型NAD+辅因子，用于重编程NAD(P)+结合蛋白实现亚胺生物催化。AnAD用具有催化活性的苯胺单元取代了天然烟酰胺，将其引入天然蛋白支架后实现了亚胺催化机制，能够进行串联的弗里德尔-克拉夫茨烷基化-对映选择性质子化反应。蛋白质工程进一步提升了该人工酶的活性和立体选择性。","scd":null,"kp":["[合成NAD+型辅酶(AnAD)]: 用催化活性苯胺单元替代天然烟酰胺，可重编程NAD(P)+结合蛋白用于亚胺生物催化"]},{"i":36080,"as":"报道了通过氧化还原化学提升水系铵离子电池容量和超长寿命的研究。通过调节普鲁士蓝类似物中M' d轨道的t2g和eg占据情况，改善了其作为电极材料的性能。研究表明，M'的电子构型对氧化还原可逆性、结构坚固性以及电极对铵离子的耐受性至关重要，有效解决了铵离子电池缺乏合适电极材料导致循环稳定性差的问题。","scd":null,"kp":["电极材料[水系铵离子电池]: 普鲁士蓝类似物","性能提升机制[普鲁士蓝类似物]: 氧化还原化学调控t2g轨道"]},{"i":36081,"as":"展示了利用硅价态作为分子控制元件来控制多光致变色系统的策略。两种硅基二芳基乙烯路易斯酸经历了分步双重环化，在四配位和五配位状态之间转换，从而调节配体间的电子耦合。供体配位可根据结合碱的不同实现选择性单环化、波长门控激活或光反应性的完全抑制。逐步环化逐步增强路易斯酸性，实现了首个光开关路易斯超强酸性。","scd":null,"kp":["分子控制元件[多光致变色体系]: 硅原子价态","光控开关特性[硅基二芳基乙烯路易斯酸]: 价态门控的分步双环化及超酸性可切换"]},{"i":36082,"as":"报道了一类用于SuFEx反应的多功能六价硫氟化物：N-CF2H氨基磺酰氟。这类新型化合物兼具共价键和氢键供体特性，能够增强药物与生物体内受体之间的结合强度，为靶向药物研究注入新活力。研究实现了从一级胺出发，通过连续氟磺酰化反应仅用两步合成了N-CF2H氨基磺酰氟，展现出在药物化学领域的独特多功能性和高效性。","scd":null,"kp":["化学功能[N-CF2H氨基磺酰氟]: 兼具共价键和氢键供体能力"]},{"i":36083,"as":"开发了一种负载在原子级分散Mn-N-C载体上的有序Pt3Mn金属间化合物纳米颗粒电催化剂。通过将低电负性的锰同时引入活性成分和载体中，构建了高效氧还原反应(ORR)电催化剂。相比于无序固溶体合金，该结构具有长程周期性有序原子排列，兼具高内在催化活性和长期耐久性，解决了燃料电池催化剂实用化的关键挑战。","scd":null,"kp":["催化剂结构[燃料电池电催化剂]: 负载在单原子分散Mn-N-C上的有序Pt3Mn金属间化合物纳米颗粒"]},{"i":36084,"as":"提出了一种CuH催化的转化方法，能够将简单前体转化为高度功能化且富含对映体的环戊二烯(CpHs)。针对环戊二烯因内在酸性和易发生快速[1,5]-氢转移而难以获得稳定手性变体的合成挑战，该方法以高收率实现了 exceptional对映选择性。计算揭示了该反应通过铜催化中罕见的腈活化机制进行，合成的新型CpHs具有意料之外的极高稳定性。","scd":null,"kp":["催化剂[环戊二烯对映选择性合成]: CuH"]},{"i":36085,"as":"通过单原子催化剂的配位工程，在MoO3载体上构建了Ir─Mo原子对位点，打破了酸性析氧反应(OER)的限制。与弱相互作用的Ir─O─Mo结构相比，通过直接Ir─Mo配位形成的原子对位点与载体产生强烈的电子耦合，增强了原子分散性和结构稳定性。原位实验表明该位点触发了新的氧化物介导途径，通过动态羟基从Mo溢流到Ir位点有效提升了催化活性。","scd":null,"kp":["催化剂[酸性析氧反应]: MoO3负载的Ir-Mo原子对位点单原子催化剂","活性增强机制[Ir单原子]: 直接Ir-Mo协调打破标度关系限制"]},{"i":36086,"as":"通过构建自组装多层膜(SAMUL)并激活π电子共轭网络，实现了21.1%光电转换效率的有机太阳能电池。利用3,6-二苯并噻吩-9H-咔唑构建的自组装多层膜克服了单层电导率不足的问题，其π扩展骨架增强了分子结晶性和面朝上取向。这种共轭网络结构显著提高了电导率和空穴提取能力，且对外部刺激表现出优异的抵抗力。","scd":null,"kp":["能量转换效率[有机太阳能电池]: 21.1%","关键材料[自组装多层膜]: 3,6-二苯并噻吩-9H-咔唑基π骨架单元"]},{"i":36087,"as":"提出了一种主链刚性官能化(BRF)策略以提升天然橡胶的性能并实现可控降解。通过无催化剂的[2+2]光环加成反应，将刚性、极性的环丁烷单元直接引入天然橡胶主链。环丁烷稠合的琥珀酰亚胺单元显著提高了材料的拉伸强度和韧性。仅需改变反应时间，即可实现材料从粘弹性聚合物到高弹性体的连续调节，解决了传统不可逆硫化橡胶难以物理回收的难题。","scd":null,"kp":["改性策略[天然橡胶]: 主链刚性官能化(BRF)"]},{"i":36088,"as":"通过分子n型掺杂策略，在集成微腔的有机发光二极管(OLED)中实现了低阈值纳秒级激光发射，向电泵浦有机激光器迈进。针对高增益有机半导体通常存在电荷传输性能差且不平衡的材料困境，该研究采用螺芴衍生物作为发光层并引入n型掺杂层。该掺杂策略有效缓解了增益与电荷传输之间的内在矛盾，使器件摆脱了对飞秒光泵浦的依赖。","scd":null,"kp":["掺杂机制[微腔集成OLED]: 分子N型掺杂","器件性能[纳秒级激光器]: 实现低阈值纳米脉冲激光发射"]},{"i":36089,"as":"提出了一种利用质子化锰掺杂碳点(HMnCDs)实现胞内质子富集的策略，驱动双辅因子统一再生以用于生物杂交CO2固定。针对光催化杂化系统中跨膜电子注入与质子流解耦导致ATP和NADH再生受限的动力学不匹配问题，HMnCDs同时作为可逆质子库发挥作用。该策略有效耦合了电子与质子流，显著提升了太阳能到化学能的CO2转化效率。","scd":null,"kp":["强化机制[光催化生物杂交CO2还原]: 胞内质子富集驱动的双辅酶统一再生"]},{"i":36090,"as":"报道了一种光催化方法，利用CdZnS光催化剂实现同步解聚和C-C偶联过程，将木质素及其衍生物直接转化为非对称芳香族二醇。该一锅法将解聚与官能化步骤结合，无需两个独立的催化体系和反应条件，极大地简化了生产工艺。此方法最大化了生物质利用的工艺效率、原子经济性和成本效益，是木质素高值化转化的重要进展。","scd":null,"kp":["[木质素转化]: 光催化一锅法实现解聚与醇类交叉偶联直接制备非对称芳香族二元醇"]},{"i":36091,"as":"发现了在二氯甲烷(CH2Cl2)中无需额外光催化剂即可将聚苯乙烯(PS)光裂解为C6-C8芳香族产物的新途径。在氧气氛围和365-415纳米光照下，该无光催化剂系统对C6-C8芳香族产物的最大生成速率达到15.9 µmol/h。这一意外发现打破了CH2Cl2仅作为惰性溶剂的传统认知，其性能可与当前最先进的先进光催化系统相媲美，为塑料废弃物的温和升级回收提供了新路线。","scd":null,"kp":["[聚苯乙烯光裂解]: 在二氯甲烷(CH2Cl2)中实现意想不到的裂解，产物为C6-C8芳香族化学品"]},{"i":36092,"as":"研究报道了铜单晶在电催化C-N偶联反应中的表面自优化现象。在硝酸盐主导下，铜催化剂活性较低的(110)和(100)晶面会定向演化重构为高活性的(111)晶面。Cu(111)表面利用二氧化碳和硝酸根合成尿素的产率高达5.2 mg h⁻¹ cm⁻²，分别是(110)和(100)晶面的4倍和26倍，且保持优异的稳定性。","scd":null,"kp":["尿素产率[Cu(111)晶面电催化C-N偶联]: 5.2 mg h−1 cm−2","[晶面自优化重构]: 硝酸盐主导的优先生长将低活性的(110)和(100)晶面演化为高活性的(111)构型"]},{"i":36093,"as":"过渡金属催化的炔烃氢锗化是制备烯基锗烷的高原子经济性方法。研究人员采用结构明确的二钴羰基络合物作为催化剂，实现了炔烃的发散性氢锗化反应。利用富含地球资源的3d金属钴催化剂，通过使用[(IPent)Co₂(CO)₇]等催化剂成功解决了该反应在实现高区域选择性方面面临的挑战。","scd":null,"kp":["[端炔氢锗化反应]: 采用含不同配体的双核钴催化剂实现区域发散性反应"]},{"i":36094,"as":"研究提出了一种用于锂金属电池电解质理性设计的溶剂极化动力学描述符。针对锂离子迁移过程中由极化驱动的溶剂化结构重构与松弛过程，研究人员捕获了系统总偶极矩的动态演化，并提出积分介电弛豫时间描述符(τi)来量化配位溶剂的极化响应速率。该方法能够同时预测电解质的体相离子传输和界面特性。","scd":null,"kp":["[电解液溶剂化结构]: 溶剂化结构的重构与弛豫过程由Li+迁移过程中的极化驱动"]},{"i":36095,"as":"高温质子交换膜燃料电池(HT-PEMFCs)具备反应动力学优异、水热管理系统简单及耐一氧化碳等优点。然而，其使用的磷酸掺杂膜在运行中会发生磷酸溶出，导致铂基氧还原反应(ORR)催化剂及阴极催化层降解，严重限制了器件性能。研究针对提升HT-PEMFCs催化剂活性与耐久性的多尺度阴极设计进行了广泛探讨。","scd":null,"kp":["[HT-PEMFCs多尺度阴极设计]: 克服磷酸(PA)掺杂膜中PA浸出问题的阴极设计"]},{"i":36096,"as":"研究通过电极涂层调控界面离子通量，实现了高效的酸性二氧化碳电解。涂层设计将阳离子交换离聚物(CEI)与阻质子氧化物相结合，构建出耐用涂层。实验与模拟结果表明，该配方能够促进钾离子向内传输，同时限制质子，从而将反应途径导向二氧化碳电还原，有效抑制了动力学上有利的析氢副反应。","scd":null,"kp":["[酸性CO2电解]: 通过电极涂层工程调控界面离子通量，抑制析氢反应并引导反应路径向CO2还原进行"]},{"i":36097,"as":"具有阴离子氧化还原活性的锰基层状氧化物是极具潜力的钠离子电池正极材料，但循环中产生的Mn³⁺会导致严重的Jahn-Teller畸变。研究提出一种在放电结束时起作用的金属间电荷转移(MMCT)机制。以P2-Na0.69Li0.23Ru0.17Mn0.6O2为模型，高电负性Ru的掺杂调节了不对称Mn-O-Ru的共价性，促使电子转移并减少Mn³⁺含量，从而抑制畸变并提升结构稳定性。","scd":null,"kp":["[钠离子电池锰基层状氧化物]: 放电末期通过不对称基元触发的金属到金属电荷转移(MMCT)引发电子离域，抑制Mn3+生成及姜-泰勒畸变"]},{"i":36098,"as":"针对单一环境能量收集器在多变气候下适应性差的问题，研究提出一种受峡谷效应启发、由双凹型气流放大器增强的高适应性环境能量收集器。放大器的全向气流平滑设计将风能收集效率提升了86.87%，并降低了启动风速。其斜面支持模块化组装，实现了电磁-光伏-摩擦电效应的非侵入式协同集成，适用于智慧农业。","scd":null,"kp":["[环境能量收集器]: 受峡谷效应启发采用双凹型气流放大器进行全向气流平滑增强设计"]},{"i":36099,"as":"研究在EAST托卡马克装置上提出三种深度学习模型，用于构建针对三维外部磁场扰动的等离子体实时响应监测与优化模型。相比全连接神经网络(FNN)和CNN-LSTM，采用注意力机制的iTransformer模型展现出最佳综合性能。该模型基于133157个实验样本训练，建立了从共振磁扰动线圈到等离子体响应的直接非线性映射，推理表现出色。","scd":null,"kp":["[等离子体响应实时监测与优化]: 使用深度学习模型，其中iTransformer模型在捕获多变量依赖关系上展现出最佳整体性能"]},{"i":36100,"as":"DIII-D和KSTAR托卡马克开展国际合作，验证高性能混合运行场景与钨偏滤器及超导线圈的兼容性，以解决未来聚变装置稳态运行挑战。KSTAR成功实现30秒长脉冲运行，归一化比压达2.4，有效抑制了钨杂质积累。但该工况下的热约束比DIII-D降低了25%以上。","scd":null,"kp":["[高性能长脉冲运行]: 必须兼容钨偏滤器和超导线圈"]},{"i":36101,"as":"安全高效处理核裂变产生的放射性副产物对可持续发展至关重要。这些废物包括阳离子核素(如铀、铯、锶)、阴离子核素(如锝、碘)、气态流出物和氚等。研究指出，金属有机框架(MOFs)、共价有机框架、氢键有机框架及超分子组装框架等多孔框架材料，在核废料的处理与处置中展现出广阔的应用前景。","scd":null,"kp":["[核裂变放射性副产物]: 包括阳离子放射性核素、阴离子放射性核素、气态流出物和氚"]},{"i":36102,"as":"铜死亡是一种依赖铜离子的细胞程序性死亡途径，为癌症治疗提供了新策略。该综述全面分析了基于自组装、刺激响应的动态纳米系统在诱导铜死亡用于癌症治疗和成像方面的进展。文章系统阐述了铜死亡的分子机制，并探讨了利用选择性铜离子配位设计自组装诱导剂的原则。","scd":null,"kp":["[铜死亡抗肿瘤纳米平台]: 刺激响应性和动态自组装系统"]},{"i":36103,"as":"极化离子束是未来电子-离子对撞机(EIC)解决物质基本结构前沿问题的关键技术。利用极化电子和离子束，科学家致力于探究质子自旋的起源、夸克和胶子自旋分布，以及细胞核内是否存在奇异胶子。这有助于揭示核子内部结构，并 unravel 三维量子动力学。","scd":null,"kp":["[极化离子束]: 研究质子自旋起源及物质基本结构的关键手段"]},{"i":36104,"as":"基于CLAS合作组在托马斯·杰斐逊国家加速器设施使用CLAS12探测器获取的数据，研究测量了近阈值J/ψ粒子的光致产生总截面和微分截面。实验数据收集于2018年秋季和2019年春季的运行周期，结果已发表于《物理评论C》。","scd":null,"kp":["[J/ψ介子近阈值光生反应]: 实验测量了总截面和微分截面"]},{"i":36105,"as":"","scd":null,"kp":[]},{"i":36106,"as":"高浓度电解液常用于稳定水系多价电池，但浓度过高会导致功能阳离子被氯离子配位的铝络合物困在体相中，无法到达电极界面。通过识别最佳浓度窗口以避免界面离子枯竭，研究人员成功开发出一种耐用且具备高倍率性能的水系铝碘电池，为多价电池电解液设计提供了新原则。","scd":null,"kp":["[水系铝碘电池电解液]: 存在最佳浓度窗口，超过临界浓度会导致界面离子耗竭"]},{"i":36107,"as":"研究开发了一种名为ElHyX的拉伸性好、对应变不敏感且湿组织粘附的弹性体-水凝胶双相生物电子平台。该平台采用分子级一体化架构并掺杂导电填料，无需缝合即可与动态软组织实现长期稳定结合。该平台能够同时实现体内物理传感、化学监测和神经调节等多功能应用。","scd":null,"kp":["[可植入生物电子器件]: 采用弹性体-水凝胶双相平台，具有可拉伸、对应变不敏感及湿组织粘附特性"]},{"i":36108,"as":"研究基于可编程超表面开发了时空全息技术。该方法利用时空编码将单色入射波分裂为多谐波反射束，结合快速收敛的相位检索算法操纵各谐波波前强度。使用包含6144个单元的可编程超表面，实验成功同时生成了62个全息图像。该技术在不同谐波处提供了数千个独立且同时工作的全息通道。","scd":null,"kp":["[可编程超表面时空全息图]: 提供数千个在不同谐波下同时工作的独立全息通道"]},{"i":36109,"as":"深海巨型等足类动物含有一种源自细菌的基因。这种基因帮助它们在冰冷的深海环境中调节自身的新陈代谢，从而适应极端的深海生存条件。","scd":null,"kp":["[深海巨型等足目生物]: 拥有细菌基因以在深海寒冷环境中调节新陈代谢"]},{"i":36110,"as":"由Argonaute(AGO)蛋白和小RNA组成的RNA诱导沉默复合体(RISC)是RNA沉默的核心。研究鉴定出人类AGO-HSP90-p23复合物，它能捕获RNA游离态的AGO，被称为AGO成熟复合物(AMC)。冷冻电镜结构显示，AMC中的AGO呈现出高度开放的构象，其N端和RNA结合模块完全脱离，为小RNA双链的加载和RISC组装提供了结构基础。","scd":null,"kp":["[RNA诱导的沉默复合体组装]: 由HSP70和HSP90依赖性过程介导，AGO-HSP90-p23复合物可捕获无RNA状态的AGO"]},{"i":36111,"as":"SIRT7是影响哺乳动物性别差异的重要去乙酰化酶。研究发现，SIRT7优先定位于性染色体。缺失SIRT7会导致雌性小鼠X染色体失活过程改变：Xist基因过表达且基因沉默效率提高。此外，SIRT7缺失对活性X染色体(Xa)影响最大，导致Xa染色体呈现过度活跃状态。","scd":null,"kp":["SIRT7定位[性染色体]: 优先定位于性染色体","SIRT7敲除[雌性小鼠适应度]: 全生命周期适应度下降","SIRT7缺失[雌性个体]: 影响X染色体"]},{"i":36112,"as":"","scd":null,"kp":[]},{"i":36113,"as":"","scd":null,"kp":[]},{"i":36114,"as":"针对金属卤化物钙钛矿发光二极管中原位合成钙钛矿纳米晶时“高结晶度”与“小尺寸”难以兼顾的问题，研究人员提出通过原位聚合驱动的纳米晶限域技术来合成高质量的钙钛矿薄膜。在纳米晶生长过程中，原位形成的聚合物网络施加了纳米级的空间限制，成功制备出尺寸小且光致发光量子产率高达83%的纳米晶体，从而实现了高效的蓝色钙钛矿LEDs。","scd":null,"kp":["原位合成矛盾[钙钛矿纳米晶]: 高结晶度与小尺寸间的固有矛盾","合成策略[蓝光钙钛矿LED]: 原位聚合驱动的纳米晶限域"]},{"i":36115,"as":"","scd":null,"kp":[]},{"i":36116,"as":"研究在MoSe2/hBN/WSe2电子-空穴双层异质结构中发现了双组分流子玻色-爱因斯坦凝聚（BEC）的证据。通过探测组成电子和空穴的自旋-谷磁化率，证实该结构存在具有四种自旋-谷自由度的平衡激子流体。稀释制冷机下的磁光光谱分析揭示了具有不同极化特征的三个激子凝聚相。在零磁场下，多体基态表现为特定的凝聚状态，为研究高温、强相互作用的固态激子凝聚提供了直接证据。","scd":null,"kp":["双组分激子BEC[电子-空穴双层MoSe2/hBN/WSe2]: 探测到自旋-谷磁化率证据"]},{"i":36117,"as":"","scd":null,"kp":[]},{"i":36118,"as":"","scd":null,"kp":[]},{"i":36119,"as":"针对BRAF（尤其是V600E）突变的结直肠癌患者由于BRAF二聚化导致MAPK通路重新激活而产生耐药性的问题，研究通过化学文库设计与平行蛋白质组学筛选，发现了一种靶向人类抗原R（HuR）的分子胶降解剂dHuR。HuR是一种驱动肿瘤生长和耐药性的RNA结合蛋白。dHuR能够结合CRBN泛素连接酶形成独特的复合物表面，从而特异性靶向并降解HuR蛋白，为抑制BRAF突变型结直肠癌提供了新的干预策略。","scd":null,"kp":["BRAF突变占比[结直肠癌患者]: 约10%","突变类型[BRAF功能获得性突变]: BRAF(V600E)","靶向抑制无效原因[BRAF抑制剂]: BRAF二聚化驱动的MAPK途径重新激活"]},{"i":36120,"as":"为了提升全钙钛矿叠层电池的效率与稳定性，研究人员使用吩噻嗪功能化界面替代了易吸湿的PEDOT:PSS。该界面设计有效抑制了亚稳相偏析，并精准引导了锡铅钙钛矿的结晶过程。同时，双锚定中间层在叠层器件中形成了稳固的内部连接。该无PEDOT:PSS的单片全钙钛矿叠层电池实现了29.1%的光电转换效率纪录及优异的长期稳定性，证明了精确的界面设计是实现高效与耐久性兼备的关键。","scd":null,"kp":["转换效率[无PEDOT:PSS全钙钛矿叠层电池]: 29.1%","界面材料[替代PEDOT:PSS]: 吩噻嗪功能化界面","界面修饰作用[Sn-Pb钙钛矿]: 抑制亚稳相分离并引导结晶"]},{"i":36121,"as":"Yu等人受河豚启发开发了一种张拉整体超材料平台。该平台利用湿度对内部预应力进行编程，并通过机械锁将其作为非易失性记忆储存。一旦设定完成，该结构无需持续的能量输入即可维持其力学状态。这种特性使材料能够实现持久的功能，包括定时释放、抗冲击保护以及自适应承载，为持久型机械功能设计提供了新途径。","scd":null,"kp":["预应力编程[张拉整体超材料]: 湿度编程内部预应力与机械锁存","系统能耗[机械状态维持]: 无需持续能量输入"]},{"i":36122,"as":"该研究揭示了在玻璃体材料（vitrimers）的动态网络重组过程中，罕见且高度特异性的键合几何形态构成了键交换的主导熵势垒。这一发现重新定义了科学界对玻璃体动态网络重排机制的理解，使得研究人员能够更准确、可预测地设计和调控此类动态材料的化学与物理特性。","scd":null,"kp":["键交换势垒[玻璃体(vitrimers)]: 罕见且高度特异性的键几何构型产生主导性熵势垒"]},{"i":36123,"as":"研究开发了一种可转化的细胞外囊泡纳米平台，用于多通路的血管协同修复。该技术通过在体外使用硫化氢（H2S）供体刺激血管内皮细胞，获取具有靶向修复能力的囊泡。这些囊泡能够精准靶向受损动脉，有效减轻局部炎症、抑制新内膜增生并促进内皮再生，从而避免了全身系统性输送H2S的毒副作用。在大鼠颈动脉损伤模型中，该囊泡展现出了良好的血管修复效果和生物安全性。","scd":null,"kp":[]},{"i":36124,"as":"针对水系硫基电池反应动力学缓慢和结构易崩塌的难题，研究通过引入铜元素构建了高度导电且稳定的铜修饰硫化聚苯胺正极材料。该设计利用铜引发的d-p-π多轨道耦合效应优化了材料性能。与锌负极组装成软包电池后，在严苛条件下仍能实现稳定的功率输出。这项工作为开发长效耐用的硫基电池提供了一条基于轨道工程的新路径。","scd":null,"kp":["阴极材料[水系硫电池]: 铜修饰硫化聚苯胺","轨道耦合机制[铜修饰硫化聚苯胺]: d-p-π多轨道耦合","电池构型[硫基电池]: 硫化聚苯胺阴极耦合锌阳极的软包电池"]},{"i":36125,"as":"研究在亚纳米尺度上将铀酰单元与多铌酸盐结合，成功构建了二维UNbO“团列烯”。这种结构具有连续的平面载流子迁移路径，能够最大程度地减少电子-空穴复合。凭借这一特性，该材料在可见光驱动下实现了高效的烯烃裂解反应。该成果为开发基于5f金属的高效多相光催化剂奠定了重要基础。","scd":null,"kp":["材料结构[5f金属2D簇烯]: 亚纳米尺度铀酰单元与多铌酸盐集成形成2D UNbO簇烯","光催化机制[2D UNbO簇烯]: 连续平面载流子迁移路径最小化电子-空穴复合","催化应用[可见光驱动]: 烯烃裂解"]},{"i":36126,"as":"","scd":null,"kp":[]},{"i":36127,"as":"","scd":null,"kp":[]},{"i":36128,"as":"电催化表面处于动态变化中，但在大范围内建立纳米级电流与结构之间的关联一直缺乏有效方法。干涉电光显微镜技术现能在50纳米空间和10毫秒时间分辨率下对电化学电流进行成像。利用该技术，研究人员直接观察到MoS2表面析氢反应是沿着特定的晶体学方向引发和传播的。","scd":null,"kp":["空间分辨率[干涉电光显微镜]: 50 nm","时间分辨率[干涉电光显微镜]: 10 ms","催化动力学[二硫化钼析氢反应]: 沿特定晶向引发和传播"]},{"i":36129,"as":"","scd":null,"kp":[]},{"i":36130,"as":"","scd":null,"kp":[]},{"i":36131,"as":"","scd":null,"kp":[]},{"i":36132,"as":"","scd":null,"kp":[]},{"i":36133,"as":"","scd":null,"kp":[]},{"i":36134,"as":"","scd":null,"kp":[]},{"i":36135,"as":"量子摩擦描述了液体与固体电子之间动量的直接传递，但由于其微观特性，实验捕捉极具挑战性。研究发现，近红外荧光单壁碳纳米管（SWCNTs）在水中表现出光诱导的量子摩擦现象。测量表明，功能化SWCNTs在水溶液中的扩散系数随激发功率的增加呈线性下降，降幅约为50%。当激子被定域化（如存在量子缺陷）时，该效应随之消失。此外，通过化学分子调节激子浓度可以进一步证实并调控这一量子摩擦效应。","scd":null,"kp":["量子摩擦[单壁碳纳米管在水中的光致现象]: 近红外荧光单壁碳纳米管表现出依赖激发功率的量子摩擦特征"]},{"i":36136,"as":"","scd":null,"kp":[]},{"i":36137,"as":"","scd":null,"kp":[]},{"i":36138,"as":"多肽注射正成为健康养生领域的最热门趋势。然而，研究人员指出，公众对这些未经严格监管的药物的热情已经远远走在了科学验证的前面，其真实功效仍需严谨的科学数据支撑。","scd":null,"kp":[]},{"i":36139,"as":"江门中微子实验（JUNO）的首次测量数据展示了史无前例的精度，标志着新一代中微子实验时代的开启，并为未来获取激动人心的物理成果奠定了基础。","scd":null,"kp":["测量精度[JUNO中微子实验首批测量结果]: 前所未有的极高精度"]},{"i":36140,"as":"物理学家寄望于江门中微子实验（JUNO）设施能够精确测量并确定中微子的质量顺序，即明确究竟是哪种类型的中微子具有最大的质量，从而进一步解开中微子质量之谜。","scd":null,"kp":["[JUNO实验设施技术目标]: 确定具有最高质量的中微子类型"]},{"i":36141,"as":"通过训练神经网络来整合多个数据源的信息，人工智能技术为观察全球人口流动提供了一种高分辨率的全新视角，能够精确呈现世界各地人员的实际移动状况。","scd":null,"kp":["[神经网络多源数据整合]: 提供全球人口流动的高分辨率观测视图"]},{"i":36142,"as":"气候变化的连锁反应为北极地区的珊瑚、海绵等动物提供了栖息地。从融化的冰山上脱落的岩石成为了深海中的绿洲，孕育了丰富的生物多样性。","scd":null,"kp":["[冰山融化脱落岩石的生态效应]: 为深海珊瑚、海绵体及其他北极动物提供栖息地并形成生物多样性绿洲"]},{"i":36143,"as":"","scd":null,"kp":[]},{"i":36144,"as":"","scd":null,"kp":[]},{"i":36145,"as":"当代大学生对人工智能（AI）持怀疑态度，这为大学敲响了警钟。大学面临的挑战不仅在于采用人工智能技术，更在于如何以一种让当今学生群体能够信任的方式应用AI。大学必须认真对待并解决这一信任问题。","scd":null,"kp":["[高校引入人工智能的核心挑战]: 需以当代学生能够信任的方式应用人工智能"]},{"i":36146,"as":"研究人员通过将化学、生物学与人工智能（AI）建模相结合，寻找并恢复具有巨大潜力的治疗药物。这种跨学科方法利用AI技术成功将失败的药物转化为新药，展现了AI在药物研发和复兴旧疗法中的实际应用价值。","scd":null,"kp":["[AI辅助药物研发策略]: 结合化学、生物学与AI建模以挽救并重启具有巨大潜力的失败药物"]},{"i":36147,"as":"","scd":null,"kp":[]},{"i":36148,"as":"","scd":null,"kp":[]},{"i":36149,"as":"悬浮在水中的碳纳米管在绿光照射下移动速度会变慢。这一现象表明，碳纳米管中被激发的电子通过“量子摩擦”与水分子发生耦合，揭示了光、纳米材料与液体之间特殊的量子相互作用机制。","scd":null,"kp":["[水悬浮碳纳米管在绿光下的动力学特征]: 运动速度减慢，表现为管内激发电子与水分子偶联产生的量子摩擦"]},{"i":36150,"as":"DNA中的胞嘧啶修饰（如5mC和5hmC）是基因调控的关键表观遗传标记。研究提出了一种名为BRIGHT-seq的测序策略，通过结合酶促和化学处理，实现了在单次检测中对同一DNA分子进行直接且同时的单碱基分辨率的5mC和5hmC检测。","scd":null,"kp":["[BRIGHT-seq测序技术]: 同步实现5mC和5hmC的单碱基分辨率检测分析，克服传统差分减法策略难以在单次实验中直接并发的局限"]},{"i":36151,"as":"","scd":null,"kp":[]},{"i":36152,"as":"蛋白质构象能量景观不仅受分子内相互作用影响，也受其环境（如晶体和复合物）影响。研究以芳香环翻转作为探针，结合同位素标记和核磁共振（NMR）技术，对比了GB1蛋白在晶体、结合态和溶液中的动力学。结果证实，分子间接触确实会改变蛋白质内部的动力学特性。","scd":null,"kp":["[芳香环翻转分析技术]: 揭示蛋白质晶体与复合物中的分子间接触及晶格环境如何重塑构象能量景观和动力学特性"]},{"i":36153,"as":"利用过渡金属催化多种自由基中间体获得单一产物时，面临化学选择性的挑战。研究展示了通过强π受体三吡啶配体调节铜催化剂的电子特性，利用自由基的电子偏置与配体调控的铜中心实现极性匹配，从而精准控制铜介导的自由基捕获选择性，实现了乙烯的通用型1,2-双碳官能化。","scd":null,"kp":["催化剂选择性调控机制[过渡金属催化多自由基中间体定向转化]: 配体调制金属-自由基极性匹配实现乙烯的1,2-双碳官能化"]},{"i":36154,"as":"","scd":null,"kp":[]},{"i":36155,"as":"利用人工智能工具进行数据建模，有效填补了全球移民数据的空白。该模型详细揭示了2000年以来激增的全球人口流动情况，清晰呈现了从1990年至2023年间全球人类的详细迁移路线与目的地。","scd":null,"kp":["全球人口流动测量技术[1990-2023年缺失数据填补]: 基于人工智能建模工具"]},{"i":36156,"as":"研究发现一种多肽信号在正常条件下保持沉默，但在冷胁迫下会被激活以保护发育中的花粉。这种“按需”弹性机制能确保花粉在寒冷条件下及时获取营养。利用该机制可开发出在气候压力下仍能维持高产和粮食安全的“气候智能型”作物。","scd":null,"kp":["植物抗冷胁迫机制[寒冷条件下发育花粉保护]: 多肽信号确保在冷胁迫下发育中的花粉在正确时间接收营养物质"]},{"i":36157,"as":"","scd":null,"kp":[]},{"i":36158,"as":"随着亚马逊地区森林砍伐率的下降，新证据表明热带雨林能够抵御全球变暖的威胁。然而，这一目标的实现具有严苛的前提条件：必须在全球范围内共同努力，彻底停止对亚马逊雨林的砍伐，才能确保其生态系统的存续。","scd":null,"kp":["热带雨林应对气候变暖策略[亚马逊雨林保护]: 需在巴西国内外采取协同行动停止砍伐"]},{"i":36159,"as":"","scd":null,"kp":[]},{"i":36160,"as":"江门中微子实验（JUNO）是一个位于距多个反应堆堆芯52.5公里处的2万吨液体闪烁体探测器，旨在以亚百分点精度解析反应堆中微子的干涉图样。研究利用JUNO收集的前59.1天数据，报告了反应堆中微子振荡的测量结果，这对于测试三味中微子框架、确定中微子质量顺序及探索超越标准模型的新物理至关重要。","scd":null,"kp":["反应堆中微子振荡观测[江门中微子实验(JUNO)首批数据]: 揭示受轻子味混合角和中微子质量平方差支配的量子效应及超越标准模型的新物理现象"]},{"i":36161,"as":"","scd":null,"kp":[]},{"i":36162,"as":"自然环境的渐进变化使得生物倾向于根据最近的过去做出决策（即序列依赖性）。研究人员利用全脑细胞分辨率成像技术，在斑马鱼进行记忆引导的逃避机动时，识别出了一个维持过去信息并偏向未来选择的丘脑-脑干分层神经回路。发现背侧丘脑中的离散吸引子编码了最近障碍物的位置，揭示了历史偏向决策的特定神经回路机制。","scd":null,"kp":["历史依赖性决策的神经机制[丘脑-脑干吸引子网络]: 驱动基于近期历史的决策偏向"]},{"i":36163,"as":"研究人员开发了一种混合炼油工艺，成功以高收率从木质素中制造出尼龙的关键工业成分。这一成果为将复杂的植物生物聚合物转化为高价值工业化学品提供了全新的策略。","scd":null,"kp":["木质素高值化转化工艺[混合炼制]: 将木质素以高收率转化为尼龙成分（重要工业化学品）"]},{"i":36164,"as":"","scd":null,"kp":[]},{"i":36165,"as":"","scd":null,"kp":[]},{"i":36166,"as":"","scd":null,"kp":[]},{"i":36167,"as":"","scd":null,"kp":[]},{"i":36168,"as":"","scd":null,"kp":[]},{"i":36169,"as":"人类迁移是全球人口变化的核心驱动力，受经济发展及各类冲击影响显著。然而，现有迁移数据稀疏、碎片化且缺乏统一标准，难以进行一致性测量。以往依赖流量记录、存量估算等部分数据集的覆盖范围十分有限。目前的核心挑战是构建一个全球一致的长期人类迁移测量框架，以准确反映人口结构变化。","scd":null,"kp":[]},{"i":36170,"as":"量子算法在解决物理和化学问题时需要极低的错误率。研究在 trapped-ion QCCD 实验中，通过量子纠错技术实现了逻辑错误率的大幅改善，较物理电路基准提升了11至800倍。该成果基于针对离子阱处理器优化的两种纠错码构造：受Knill启发的12量子比特码（编码2个量子比特）和16量子比特tesseract颜色码（编码4个量子比特）。","scd":null,"kp":["逻辑错误率提升[捕获离子量子电荷耦合器件(QCCD)实验纠错]: 相比多种物理错误率实现了11倍至800倍的提升"]},{"i":36171,"as":"聚合物电极与金属组件之间的不匹配阻碍了稳固电气接触的形成。研究提出一种双面机械互锁策略，利用导电织物骨架连接聚合物与金属，并在两侧涂敷粘合剂。粘合剂渗透并包裹骨架纤维，形成需发生体相破坏才能中断的线孔粘附。该机制使导电弹性体与铜之间的界面韧性达到创纪录的730 J m^-2。","scd":null,"kp":["软硬导电界面韧性记录[柔性电子器件双面机械互锁策略]: 导电织物支架结合两侧粘合剂，实现创纪录的高韧性界面"]},{"i":36172,"as":"钙钛矿太阳能电池面临平衡高光电转换效率与运行稳定性的挑战。研究提出一种由大分子调节剂3Cl-NC介导的动力学分段结晶策略。3Cl-NC建立局部前驱体富集微环境以促进异相成核。在热退火过程中，这种结合转变为热激活动态配位状态，在保持局部可用性的同时减缓长程前驱体传输，从而实现受控的晶体生长与高指数晶面稳定化。","scd":null,"kp":["结晶调控策略[钙钛矿薄膜]: 动力学分段结晶策略","大分子调节剂[钙钛矿结晶介导]: 构象预组织的纤维素-2,4,6-三氯苯基氨基甲酸酯(3Cl-NC)","配位机制[3Cl-NC大分子调节剂]: 多齿配位"]},{"i":36173,"as":"二维金属有机网络中表面电子的量子限域是工程化电子态的重要途径。研究在Cu(111)表面的Cu-T4PT网络中发现，表面电位的垂直变化对量子限域具有关键作用。对Shockley表面态和镜像势态电子限域的研究显示，由于Cu-T4PT网络独特的三维势能景观，镜像态的能带质量发生显著重整化，而Shockley态几乎保持不变。","scd":null,"kp":["量子限域效应[二维金属有机网络表面态电子]: 受表面势垂直变化控制","电子态[铜-T4PT网络中的Shockley表面态]: 存在量子限域效应","电子态[铜-T4PT网络中的镜像势态]: 存在量子限域效应"]},{"i":36174,"as":"","scd":null,"kp":[]},{"i":36175,"as":"","scd":null,"kp":[]},{"i":36176,"as":"","scd":null,"kp":[]},{"i":36177,"as":"","scd":null,"kp":[]},{"i":36178,"as":"","scd":null,"kp":[]},{"i":36179,"as":"","scd":null,"kp":[]},{"i":36180,"as":"","scd":null,"kp":[]},{"i":36181,"as":"","scd":null,"kp":[]},{"i":36182,"as":"","scd":null,"kp":[]},{"i":36183,"as":"","scd":null,"kp":[]},{"i":36184,"as":"不同材料的超薄膜在高速冲击下表现出极强的抗穿透性增强。研究揭示了比穿透能遵循一个普遍的反三次方标度定律。这一发现为广泛材料在超薄膜形态下表现出的异常高弹道抗性提供了统一的物理解释。","scd":null,"kp":["比穿透能[超薄膜抗高速冲击]: 遵循反三次方标度定律"]},{"i":36185,"as":"研究提出一种基于熵惩罚方法的框架，用于有效提取具有凸哈密顿量的非线性哈密顿-雅可比方程的粘性解。该方法将Cole-Hopf变换从二次推广至一般凸哈密顿量，通过离散时间线性动力学逼近线性类热抛物线方程，从而近似粘性哈密顿-雅可比动力学。该框架适用于任意非线性，适合量子模拟，可应用于强迫Burgers方程等领域。","scd":null,"kp":["量子算法[求解非线性哈密顿-雅可比方程粘性解]: 基于熵惩罚法","求解框架[广义凸哈密顿量]: 推广了Cole-Hopf变换以进行近似求解"]},{"i":36186,"as":"","scd":null,"kp":[]},{"i":36187,"as":"","scd":null,"kp":[]},{"i":36188,"as":"","scd":null,"kp":[]},{"i":36189,"as":"","scd":null,"kp":[]},{"i":36190,"as":"","scd":null,"kp":[]},{"i":36191,"as":"","scd":null,"kp":[]},{"i":36192,"as":"","scd":null,"kp":[]},{"i":36193,"as":"","scd":null,"kp":[]},{"i":36194,"as":"","scd":null,"kp":[]},{"i":36195,"as":"面对磷酸盐矿石储量减少，提高磷回收对农业至关重要。研究构建了综合磷循环模型，评估了美国7项循环策略。数据显示，土壤残留磷的再利用拥有减少矿物磷需求的最大潜力。截至2023年，美国累计土壤磷库存达99 Tg。2024至2050年的预测表明，在多种社会经济情景下，土壤残留磷再利用将显著降低对矿物磷的依赖。","scd":null,"kp":["循环策略评估[美国磷供应链韧性]: 量化了7种减少矿物磷需求的循环策略","模型数据集规模[磷循环与土壤动态模型]: 覆盖91种主要作物、20种牲畜、3142个县(1866至2050年)"]},{"i":36196,"as":"","scd":null,"kp":[]},{"i":36197,"as":"","scd":null,"kp":[]},{"i":36198,"as":"","scd":null,"kp":[]},{"i":36199,"as":"","scd":null,"kp":[]},{"i":36200,"as":"","scd":null,"kp":[]},{"i":36201,"as":"","scd":null,"kp":[]},{"i":36202,"as":"","scd":null,"kp":[]},{"i":36203,"as":"","scd":null,"kp":[]},{"i":36204,"as":"","scd":null,"kp":[]},{"i":36205,"as":"细菌在应激下释放的细胞外囊泡（EVs）能够对抗抗生素。单细胞成像显示，EVs能快速螯合多粘菌素B（Pmb）并将其从细菌外膜清除，同时充当“塞子”修复受损部位。Pmb刺激会使细菌表面积缩减25%，囊泡分泌暴增50倍并重塑膜特性。经过适应期后，持续的EV释放支持了细菌的解毒和外膜修复，使生长得以恢复。","scd":null,"kp":["细胞外囊泡(EVs)作用[细菌对多粘菌素B的耐受性]: 快速螯合多粘菌素B并从细菌包膜清除","物理机制[受损细菌包膜修复]: EVs通过粘附或融合于受损部位充当“塞子”","囊泡生成机制[细菌应激反应]: 纳米级脂质结构在应激下释放"]},{"i":36206,"as":"","scd":null,"kp":[]},{"i":36207,"as":"","scd":null,"kp":[]},{"i":36208,"as":"针对糖尿病和高尿酸血症等系统性代谢疾病，研究人员开发了一种口服多级靶向纳米平台(P1P2NPs)。该平台由生物响应聚合物、DSPE-PCB和Eudragit L100-55组成，能够将治疗肽序贯递送至不同器官。P1P2NPs可在肠道中释放肽P2以抑制DPP-IV，同时选择性地在肝脏中释放靶向肽P1。该技术实现了多器官的序贯干预，解决了单靶点疗法无法恢复代谢稳态的问题。","scd":null,"kp":["纳米载体材料[口服多脏器靶向递送]: 生物响应性聚合物聚(β-氨基酯)-二硫键-聚(羧基甜菜碱)(PAE-SS-PCB)","递送系统[代谢疾病治疗]: 多阶段靶向的口服纳米平台(P1P2NPs)","给药途径[多肽治疗药物靶向递送]: 口服给药"]},{"i":36209,"as":"超表面光学元件为天文学仪器的微型化提供了潜在优势。研究人员开发了首个基于超表面偏振分析光栅的太阳成像超表面偏振计(SIMPol)。这是一种新型望远镜，利用高性能超表面光栅实现了单元件、快照式太阳成像偏振测量。该仪器已成功集成到主要的天文台中，展示了超表面组件在天文仪器中的实际应用与科学数据生成能力。","scd":null,"kp":["光学组件[天文偏振测量]: 超表面技术","天文应用[太阳成像超表面]: 成功生成科学数据，验证了超表面对天文仪器的独特益处"]},{"i":36210,"as":"量子力学允许物理过程以不确定的顺序发生，这可以通过观测相关性的不等式违反来检测。研究团队在实验中成功违反了涉及四方相关性的贝尔类不等式，其中一方与其余三方存在类空间隔。实验利用3公里长的光纤模拟类空间隔，并在光子时间箱编码中实现了高速运行、纳秒级同步和精确的温度稳定。这些技术进步成功实现了所需复杂量子相关性不等式的实验违反。","scd":null,"kp":["量子因果序[物理过程]: 理论上可以发生于不明确的顺序中","实验突破[贝尔型因果序不等式]: 实现了包含四方相关性的不等式违背的实验验证"]},{"i":36211,"as":"为解决全球淡水短缺问题，研究人员提出了一种用于可穿戴大气取水(AWH)的分层结构纺织纤维。该纤维具有开孔表面拓扑结构和内部分层多孔结构，能够加速表面蒸汽液化及随后的水分传输，在不同的相对湿度下均表现出优异的吸水量和快速吸附动力学。将其编织成纺织品后，纤维仍能保持高效的蒸汽扩散，克服了传统吸附剂从小规模材料转化为大规模实用系统时面临的动力学限制。","scd":null,"kp":["纤维形态[可扩展的分层纺织品纤维]: 具有开孔表面拓扑结构","应用优势[大气取水(AWH)材料]: 解决了传统吸附剂从小规模向大规模系统转化时面临的动力学挑战","系统设计[可穿戴大气取水]: 基于吸附的分层纺织纤维"]},{"i":36212,"as":"高血糖会削弱内源性电场，从而阻碍糖尿病伤口愈合。研究人员开发了一种可生物降解的葡萄糖供电电子织物绷带(GEB)。该绷带集成了所有组件，设计柔软、轻便且透气，旨在替代传统笨重的电刺激器，以恢复伤口边缘电场并实现闭环伤口愈合。在糖尿病小鼠伤口、猪皮肤缺损和肠道损伤模型中，该电子绷带利用内源性葡萄糖进行通用发电和治疗，展示了跨物种和器官的治疗功能。","scd":null,"kp":["生物电子绷带[糖尿病伤口愈合]: 葡萄糖驱动的可降解电子织物绷带(GEB)，可恢复伤口边缘内源性电场并实现闭环愈合","柔性电子绷带[临床适用性设计]: 软质、轻量且透气的集成化设计"]},{"i":36213,"as":"","scd":null,"kp":[]},{"i":36214,"as":"","scd":null,"kp":[]},{"i":36215,"as":"海洋蓝细菌通过叶绿素d可以利用远红光进行光合作用。尽管已知菌株MBIC11017缺乏低能叶绿素，限制了740纳米以上的吸收，但研究发现另一种菌株NIES-2412已进化出吸收高达760纳米远红光子的策略。通过2.64埃分辨率的冷冻电镜和时间分辨荧光光谱，研究在其光系统I中鉴定出两类不同的叶绿素d红态：一类源自经典的电荷转移-激子混合。这一发现揭示了蓝细菌拓展光合作用红光极限的分子机制。","scd":null,"kp":["光系统I吸收波长[蓝细菌Acaryochloris marina NIES-2412]: 具有进化策略以实现超过740纳米的远红光吸收"]},{"i":36216,"as":"硅基阳极锂离子电池在循环过程中存在严重的容量衰减问题。现有阴极预锂化剂通常仅在首个循环起作用。研究团队开发了一种多相纳米复合预锂化剂(MNCP)，结合氧气氧化和转化反应两种机制，旨在为硅基电池提供全生命周期的锂补充。MNCP具有多个可调的脱锂平台，可在初次及后续循环中为阳极进行持续预锂化，有效提升硅基锂离子电池的整体容量和循环寿命。","scd":null,"kp":["补锂剂[硅基锂电池服役期补锂]: 多相纳米复合材料，能够突破传统正极补锂剂仅能在初始循环补锂的限制，实现服役期补锂与容量提升"]},{"i":36217,"as":"","scd":null,"kp":[]},{"i":36218,"as":"传统的木质纤维素浸油纸因介电强度、机械强度和导热系数低，易导致变压器过早失效。研究人员利用致密化木贴面的自然各向异性结构，开发出一种高性能的绝缘浸油纸。该设计通过形成纳米级油通道有效阻断了电击穿路径。这种浸油致密木材(ODW)内部形成了排列整齐的纤维素纤维和166±87纳米的油纳米通道，实现了创纪录的105千伏/毫米介电强度。同时，该结构还提供了优异的机械强度和导热性能。","scd":null,"kp":["绝缘纸[高电压电力变压器]: 利用天然各向异性结构的油浸渍致密木材单板结合纳米级油通道实现的高介电强度绝缘纸设计"]},{"i":36219,"as":"针对超高清晰度显示应用对高色纯度和高稳定性的需求，研究人员设计了一种具有刚性三维结构的四齿绿色Pt(II)发光体。通过扩展π共轭和引入大体积取代基，这种分子工程方法有效抑制了激发态的几何畸变，使其在甲苯中的半峰宽(FWHM)缩小至16.4纳米。在应用于微腔增强型顶发射器件时，通过控制相长和相消干涉，FWHM进一步减小至14.8纳米。该顶发射器件展现出极致的绿色发光性能，接近BT.2020标准。","scd":null,"kp":["发光体[绿光Top-emitting OLED]: 具有刚性三维结构的四齿绿色Pt(II)发光体，通过扩展π共轭和庞大取代基抑制激发态几何畸变","OLED器件[显示特性]: 高度稳定、高效且具备接近BT.2020标准的高色纯度"]},{"i":36220,"as":"","scd":null,"kp":[]},{"i":36221,"as":"针对癌症免疫治疗中患者响应存在显著差异的问题，研究人员开发了PathTIGR——一种融合通路拓扑信息的图表示学习框架，用于预测免疫治疗响应。该框架包含三个组件：采用多头注意力的通路图编码器（嵌入通路拓扑知识与基因组变异）、捕获通路调控依赖关系的Transformer模块，以及用于合成通路表征预测治疗响应的多层感知机。PathTIGR系统整合了生物学网络结构，能够精准预测不同癌症患者对免疫治疗的受益情况。","scd":null,"kp":["预测框架[免疫治疗反应预测]: PathTIGR，一种通路拓扑信息图表示学习框架，系统整合生物通路网络拓扑知识与基因组变异信息","框架结构[特征嵌入设计]: 包含多头注意力嵌入的通路图编码器等三组件设计"]},{"i":36222,"as":"手性纳米粒子展现出对映体依赖的细胞相互作用，为引导干细胞行为提供了新策略。研究人员合成了具有可控纳米级手性的L型、D型和消旋型CF纳米颗粒以探究其对干细胞成骨分化的影响。体外实验表明，L-CF-NPs通过网格蛋白介导和整合素参与的内吞作用实现了最高的细胞摄取率。这导致了成骨标志物表达、矿化（通过MAPK/JNK/ERK途径）以及血管生成标志物表达的最显著上调，有效加速了骨骼再生。","scd":null,"kp":["手性纳米颗粒[干细胞成骨分化]: 具有可控纳米级手性的L-CF-NPs、D-CF-NPs和A-CF-NPs，表现出对映体特异性并有效促进骨再生"]},{"i":36223,"as":"","scd":null,"kp":[]},{"i":36224,"as":"金属增材制造常导致晶粒粗大和元素偏析，降低机械和防腐性能。研究团队采用多组分碳化物(MCCs)粉末混合策略，在316L不锈钢中引入均匀分布的自组装核壳型氧氮化物-碳化物纳米颗粒。这些纳米颗粒能够锁住有害的氮/氧杂质，将奥氏体晶粒尺寸从43.9微米细化至2.1微米。该微观结构不仅实现了强度与延展性的完美结合，还通过钨、铌、钽向胞界的偏析抑制了铬偏析，显著提升了3D打印钢的耐腐蚀性。","scd":null,"kp":["3D打印不锈钢[粉末混合改性策略]: 利用多组分碳化物(MCCs)驱动自组装均匀分布的核壳氧氮化物-碳化物纳米颗粒，有效清除有害杂质并细化晶粒"]},{"i":36225,"as":"针对仿生软体机器人对复杂三维运动的需求，研究人员提出了一种空间差异化激光编程技术，用于数字化制造具备自由形态变化能力的激光诱导石墨烯软致动器(LIG-SAs)。通过跨尺度控制激光能量和划刻方向，可同时调节材料的异质性和结构层次，引入解耦的电热分布和刚度各向异性。该技术克服了传统刺激响应策略在制造简单性与运动复杂性之间的权衡，使LIG-SAs能够编码实现四种典型的运动单元，展现出极强的形态适应能力。","scd":null,"kp":["软体致动器[仿生软体机器人]: 激光诱导石墨烯基软体致动器(LIG-SAs)","制造工艺[空间差异化激光编程技术]: 实现数字化制造自由形态变形，克服了制造简单性与运动复杂性之间的权衡"]},{"i":36226,"as":"","scd":null,"kp":[]},{"i":36227,"as":"阴离子交换膜水电解(AEMWE)是生产绿氢的关键技术。为了克服阳极材料稳定性的局限，研究人员提出了一种铈诱导的双壳层结构形成策略。该策略通过空间构型工程调节电极/电解液界面微环境，有效抑制了阳极腐蚀。机理研究表明，相关的纳米空间富集效应增加了表面氢氧根离子(OH−)的覆盖度，从而增强了材料表面的局部碱性，进而实现了高效的AEMWE稳定运行。","scd":null,"kp":["电极结构[阴离子交换膜水电解槽]: 铈诱导的双壳结构策略，通过空间构型工程调节电极/电解质界面微环境，增强局部碱度以提升稳定性"]},{"i":36228,"as":"","scd":null,"kp":[]},{"i":36229,"as":"研究开发了一种高能量密度水系镁金属电池(AMMB)织物，用于在-40°C至100°C宽温域内进行超灵敏压力传感。该器件采用多孔准固态聚环氧乙烷-氯化镁电解质，通过氢键锚定抑制镁腐蚀，结合透气碳布正极与编织镁负极。该压力传感器件实现了687.32 mV/kPa的超高灵敏度、0.96帕斯卡的低检测限、20万次循环的耐久性以及2281.4的优异透湿性。","scd":null,"kp":["工作温度范围[水系镁金属电池织物传感器]: -40°C至100°C","电解质[水系镁金属电池]: 多孔准固态聚环氧乙烷-氯化镁","[抑制镁腐蚀]: 通过氢键锚定机制实现"]},{"i":36230,"as":"研究应用卷积神经网络分析了CMIP6的历史和工业化前模拟数据，发现在历史人为强迫下，厄尔尼诺-南方涛动(ENSO)的可预测性在统计学上提升了14.0 ± 1.8%。这种改善与关键的海洋-大气反馈变化有关。历史强迫导致赤道太平洋温跃层变浅，使海洋表面更易受风力影响，且次表层温度对温跃层变化的响应更为显著。","scd":null,"kp":["可预测性提升[深度学习模型预测厄尔尼诺-南方涛动(ENSO)]: 14.0 ± 1.8%","[历史人为强迫]: 显著增强了ENSO的可预测性"]},{"i":36231,"as":"","scd":null,"kp":[]},{"i":36232,"as":"针对后锂电池技术材料普鲁士蓝类似物(PBAs)，研究发现其电极材料K2Mn[Fe(CN)6]的电荷存储机制由非平衡态转化过程主导。这种现象类似于LiFePO4等传统正极在高倍率循环下的行为，但其产生原因截然不同：这是由混合框架固有的低弹性模量和协同畸变所引发的。研究使用了同步X射线吸收光谱技术进行分析。","scd":null,"kp":["电极材料[后锂电池技术普鲁士蓝类似物(PBA)]: K2Mn[Fe(CN)6]","[电荷存储机制]: 由非平衡转化过程主导"]},{"i":36233,"as":"为解决CAR-T疗法在实体瘤中的局限性，研究开发了SHIFTERS系统（实体瘤 hallmark 诱导、聚焦超声触发增强重编程系统）。这是一种“与”门基因电路，通过缺氧响应启动子和超声诱导的热休克启动子控制的分裂型Gal4-VP64转录因子，在超声辐照的缺氧区域限制性表达CD19抗原。在3D肿瘤球体和体内模型中，该系统有效激活并训练了CD19 synNotch CAR-T细胞。","scd":null,"kp":[]},{"i":36234,"as":"基于广义约化R矩阵理论，采用R矩阵分析程序(RAC)对与7Be核系统相关的所有反应通道进行了分析评估。计算结果提供了可靠的评价数据，且与现有的实验数据整体吻合度较高。","scd":null,"kp":[]},{"i":36235,"as":"在量子分子动力学类型模型的框架内，提出了一种基于傅里叶级数展开的全新方法。该方法能够生成所需的核密度分布，为使用输运模型精确建模重离子碰撞的密度分布提供了有效的手段。","scd":null,"kp":[]},{"i":36236,"as":"通过深度神经网络模拟超中心碰撞，研究确定了对撞实验中观测量与碰撞方向取向之间的依赖关系。该研究展示了深度学习在提取复杂重离子碰撞物理参数方面的应用。","scd":null,"kp":["[重离子碰撞动力学]: 使用深度神经网络确定可观测量的取向依赖性"]},{"i":36237,"as":"传统上，阳离子孤对电子常导致低晶格热导率。然而依赖特定阳离子严重限制了其应用。研究探讨了阴离子类孤对电子在实现最低晶格热导率中的作用，为寻找新型低热导率热电材料提供了机制基础。","scd":null,"kp":["[阴离子孤对电子]: 打破对特定阳离子（如Sb3+或Ge2+）的依赖，实现最低晶格热导率"]},{"i":36238,"as":"四极对称性作为原子核的一种奇特形状自由度早已被理论预测，但缺乏明确的实验证据。研究证明，通过三重结合能差分δV(3)_pn能够有效分离出80Zr原子核中的四极对称性结构效应。","scd":null,"kp":[]},{"i":36239,"as":"研究人员利用激光冷却和囚禁技术成功分离并捕获了氢化钙分子。这是实现超冷原子氢制备的关键一步，对超冷分子物理研究有重要推动作用。","scd":null,"kp":[]},{"i":36240,"as":"研究提出了一种探测单个传播微波光子的新机制，实现了类似光电效应的微波效应。该机制利用光辅助准粒子向超导岛的隧输运，在量子信息和暗物质搜寻的实际应用中具有潜力。","scd":null,"kp":["[单微波光子连续快速探测]: 基于光辅助准粒子隧穿至超导岛的机制（类微波光电效应）"]},{"i":36241,"as":"传统物理观念基于Mermin-Wagner定理，认为严格的二维短程准二维XY模型中不可能存在真正的长程有序。研究通过分析证明，在临界涨落的作用下，严格的短程准二维XY模型中可以存在长程有序状态。","scd":null,"kp":[]},{"i":36242,"as":"Belle II合作组在SuperKEKB不对称能量正负电子对撞机收集的数据中，首次搜寻了味道改变中性流衰变B→Xsvv。其中Xs是奇异数为1的强子系统。","scd":null,"kp":[]},{"i":36243,"as":"研究首次计算了强子对撞机中重夸克对伴随单态系统产生的完整双圈、完全微分软函数。这是迄今为止已知的最复杂的软函数之一，为高精度量子色动力学计算提供了关键理论输入。","scd":null,"kp":[]},{"i":36244,"as":"本文是针对此前发表的论文《可压缩流体界面的细菌湍流》（Phys. Rev. Lett. 136, 138301 (2026)）的勘误声明。","scd":null,"kp":[]},{"i":36245,"as":"原子尺度的测量表明，晶格的振动激发（振子）能够导致电子以聚集成束的形式运动。研究为声子介导下的电子群聚现象提供了实验证据。","scd":null,"kp":["[电子聚束效应]: 由原子尺度的振动激发（声子介导）引起"]},{"i":36246,"as":"针对高功率锂离子电池阳极材料Ti2Nb10O29因原子有序排列导致锂离子迁移不足及高倍率性能受限的问题，研究采用焦耳热冲击方法诱导产生了部分原子无序的缺陷态Ti2Nb10O29-x。该策略打破了原有的有序排列，提升了锂离子存储与迁移性能。","scd":null,"kp":["材料相结构[高功率锂电池负极材料]: 具有更开放晶体结构的Wadsley-Roth相Ti2Nb10O29","[提升Li+迁移能力]: 焦耳热冲击诱导产生部分原子无序态以打破致密原子排列限制"]},{"i":36247,"as":"为实现聚烯烃废塑料选择性氢解转化为长链液体燃料和化学品，研究通过浸渍法制备了二氧化钛负载的Co1/Ru单原子合金催化剂（Co10Ru90，金属总摩尔分数为3%）。该催化剂结构在不损害钌催化剂固有活性的前提下，有效破坏了Ru-Ru原子团簇，从而优化了聚丙烯氢解反应的产物选择性。","scd":null,"kp":["催化剂[废聚烯烃加氢解聚制长链液体产物]: Co1/Ru单原子合金","[催化机制]: 在不牺牲Ru内在活性的前提下打破Ru-Ru集合体，实现高选择性"]},{"i":36248,"as":"聚氨酯因优异的机械性能和高应变率响应，广泛应用于冲击防护、涂层和柔性电子领域。然而，其发展受限于异氰酸酯与胺的极快反应动力学、网络拓扑难以控制及功能多样性受限等内在挑战。近年来，高分子科学的进步通过提出使用低反应活性胺等一系列新策略，成功克服了这些局限性，推动了拓扑调控聚氨酯的结构设计与新兴应用发展。","scd":null,"kp":["材料应用[拓扑调控聚氨酯]: 冲击防护、功能涂层、胶粘剂和柔性电子","[机械性能]: 具有优异的高应变率响应","[合成瓶颈]: 异氰酸酯与胺之间反应动力学过快"]},{"i":36249,"as":"在电池极速充电(XFC)领域，电解质特性对亚分钟级充电行为的影响尚不明确。研究团队采用数据驱动方法，分析了各项物理和溶剂化特性对亚分钟级钠离子存储行为的影响。因果图分析表明，溶剂化簇尺寸与石墨中钠离子的超快存储呈最强负相关。优化后的紧凑型溶剂化结构能够有效实现亚分钟级钠离子存储。","scd":null,"kp":["[钠离子电池]: 紧密溶剂化结构能够实现亚分钟级储能","[充电技术]: 数据驱动方法用于分析极快充电(XFC)行为"]},{"i":36250,"as":"在催化领域，精确可控合成具有明确结构和价态的金属原子体系是一项重大挑战。基于理论预测，研究提出了一种在石墨二炔(GDY)表面共存金属原子和量子点的新型催化系统。结构研究表明，Ni原子和RuNix量子点分布在GDY表面，GDY作为电子介质控制了Ni原子与量子点间的强相互作用，实现了对催化体系的精确调控。","scd":null,"kp":["[催化体系]: 石墨二炔(GDY)载体上金属原子与量子点共存","[催化剂合成]: 实现具有明确结构和价态的金属原子体系精准可控合成"]},{"i":36251,"as":"针对生物电子器件植入后难以无损取出的临床痛点，研究开发了一种新型热响应可逆致动聚合物。该聚合物表现出独特的(110)取向低熵晶体与(100)取向高熵晶体间的双晶竞争机制。这种竞争在10°C-37°C的人体兼容温度窗口内实现了双向、无应力形状记忆，具备小于3秒的响应速度和约30.17%的大可逆应变，成功实现软体生物电子器件的微创植入与取出。","scd":null,"kp":["[软体生物电子器件]: 新型热响应可逆驱动聚合物实现微创植入与取出","[作用机制]: (110)取向低熵晶体与(100)取向晶体间存在独特的双晶竞争机制"]},{"i":36252,"as":"受昆虫神经通路启发，研究构建了基于二维钙钛矿(h-BN/MoS2/h-BN异质结构)的视觉传感器，实现了昆虫趋光和避光行为的动态仿真。该传感器的核心创新在于对称栅极电场协同调节，通过对顶部和底部二维钙钛矿光敏层施加相反的栅极偏压，在单一器件内动态模拟了基于逼近物体距离的仿生威胁距离自适应及逃避启动机制。","scd":null,"kp":["[视觉传感器]: 基于二维钙钛矿/六方氮化硼的光强驱动双向光响应器件","[仿生威胁距离适应]: 单一器件内动态校准逃避启动以模拟昆虫神经回路"]},{"i":36253,"as":"新奥EXL-50U是全球首个完全由私人资助运营的兆安培级磁约束聚变实验设施。作为全球首个磁场超1特斯拉、脉冲达秒级的球形环装置，其大半径为0.6至0.8米，纵横比为1.4-1.8。其实验解决的下一代反应堆关键物理问题包括：非感应电流启动与驱动、高密度热离子模式开发（离子温度3-10 keV），以及通过扫描纵横比和磁场探求能量约束定标率。","scd":null,"kp":["[EXL-50U球形环]: 全球首个完全私人资助和运营的兆安培级磁约束聚变实验设施","磁场强度[球形环装置实际运行]: 超过1特斯拉","脉冲宽度[球形环装置实际运行]: 达到秒级","大半径[EXL-50U]: 0.6-0.8 m","纵横比[EXL-50U]: 1.4-1.8"]},{"i":36254,"as":"标准理论无法解释托卡马克等离子体中测地声模(GAM)在实验中表现出的调制、峰值分裂和间歇性等频谱特征。为此，研究人员开发了描述GAM与低频带状流一致动力学的流体模型。该模型的线性近似展现出GAM和带状流两个频率差异巨大的特征模，而非线性作用则产生了更为丰富的频谱图样，与实验观测结果在定性上一致。","scd":null,"kp":["[托卡马克等离子体理论]: 流体模型描述测地声模与低频带状流相容动力学"]},{"i":36255,"as":"DIII-D托卡马克H模台基区的微观撕裂模会引发强烈的电子热传输，限制聚变性能。利用新型多通道电荷交换成像诊断系统，在台基陡峭梯度区观察到ELM周期间歇性或突发性的微观撕裂模。该模态的实验室参考频率峰值在60 kHz附近，径向半高全宽为1.5-2.0 cm，并表现出特定的归一化密度涨落幅度。","scd":null,"kp":["[H模台栏区微观撕裂模]: 在陡峭梯度区域呈现时间间歇性或“爆发式”特征"]},{"i":36256,"as":"倒置钙钛矿太阳能电池中，自组装单分子层(SAMs)虽能提升效率至27%以上，但存在分子聚集、界面覆盖不均和浸润性差等问题。该研究利用胶体二氧化硅纳米颗粒与SAM分子构建了一种新型空穴传输层。这种复合结构通过纳米颗粒表面丰富的羟基等多重协同机制，有效解决了上述界面挑战，大幅提升了钙钛矿光伏器件的性能与长期稳定性。","scd":null,"kp":["转换效率[倒置钙钛矿太阳能电池(自组装单分子层空穴传输材料)]: 超过27%","[钙钛矿光伏]: 无机-有机杂化层用于稳定埋底界面提升器件性能与长期稳定性"]},{"i":36257,"as":"为提升电化学二氧化碳还原的膜电极组件性能，研究开发了一种可规模化合成的原子级分散镍-氮-碳(NiNC)催化剂。通过使用不同碳载体精准控制孤立镍活性位点的分散，当采用碳纳米管作为载体时，NiNCNT电极在3.2V的全电池电压下，实现了558 mA cm−2的一氧化碳分电流密度，法拉第效率达92%，能量效率达39%。","scd":null,"kp":["[膜电极组件二氧化碳还原]: 原子级分散镍-氮-碳催化剂实现高效稳定电催化还原为CO"]},{"i":36258,"as":"本文是对《麻醉状态下人类海马体的可塑性与语言》一文的作者更正。原文图1e中的时间尺度存在系数为10的误差。x轴的坐标数值原为“0, 67, 133, 200”，标签为“时间(微秒)”；现已更正为“0, 0.67, 1.33, 2”，标签更正为“时间(毫秒)”。该修改已在HTML和PDF版本中更新。","scd":null,"kp":["[勘误更新]: 图1e时间轴刻度由微秒更正为毫秒"]},{"i":36259,"as":"","scd":null,"kp":[]},{"i":36260,"as":"","scd":null,"kp":[]},{"i":36261,"as":"","scd":null,"kp":[]},{"i":36262,"as":"《自然》杂志采访了一位足球期刊主编，探讨了足球运动中的新兴技术趋势。本届世界杯有望成为高科技含量最高的一届，主要创新亮点包括人工智能工具的使用，以及随队参与工作的博士研究人员所提供的数据科学支持。","scd":null,"kp":[]},{"i":36263,"as":"研究揭示了捕蝇草能够以惊人速度迅速闭合捕捉猎物的物理机制。其关键原因在于捕蝇草陷阱最外层表面的细胞发生软化，这种细胞结构特性的改变直接赋予了植物极速的运动能力。","scd":null,"kp":["闭合机制[捕蝇草]: 捕蝇草最外层表面细胞软化使其能够以极快速度闭合"]},{"i":36264,"as":"欧洲森林作为碳汇面临巨大挑战。结合联合国气候报告与遥感扰动数据建模显示，由于森林采伐和自然扰动的速度超过了生物量的恢复速度，预计2010至2030年间欧盟27国森林碳汇将下降39%。到2030年，森林碳汇将比欧盟气候目标所需 estimate 缺口达27%，仅靠植树倡议不足以实现气候目标。","scd":null,"kp":["碳汇下降预测[欧洲森林]: 39%","模型空间分辨率[生物质动态模拟]: 18 km"]},{"i":36265,"as":"","scd":null,"kp":[]},{"i":36266,"as":"研究利用弹性体介导的蜂窝状网络形貌，开发出兼具高性能与卓越机械鲁棒性的可拉伸有机光电探测器。该蜂窝网络结构能够在器件发生机械形变时有效稳定多尺度形态，使器件在超大应变和反复循环拉伸下依然保持可靠运行，为可穿戴光电器件提供了可靠的机械稳定性设计路线。","scd":null,"kp":["形态结构[可拉伸有机光电探测器]: 弹性体介导的蜂窝状网络","形变稳定性[器件大应变与重复循环过程]: 多尺度形态保持稳定"]},{"i":36267,"as":"研究利用P3-Na0.6[Li0.2Mn0.8]O2前驱体，通过自发离子交换在室温下成功合成了亚稳态富锂层状阴极材料O3-Li0.6[Li0.2Mn0.8]O2，在碳酸酯电解液中表现出极佳的电化学性能。然而，升高合成温度会导致锰离子迁移，阻碍锂离子的可逆层间迁移，进而引发不可逆的晶格氧活化并降低结构稳定性。","scd":null,"kp":["材料结构[室温LiPF6基碳酸酯电解液中的锂锰氧正极]: O3-Li0.6[Li0.2Mn0.8]O2 (O3-LLM RT)","前驱体结构[自发离子交换合成]: 层状P3-Na0.6[Li0.2Mn0.8]O2"]},{"i":36268,"as":"","scd":null,"kp":[]},{"i":36269,"as":"有机电子器件的性能高度依赖于有机栅极介电材料，要求其具备高稳定性和低漏电流。研究针对具有高化学和热稳定性的N-杂环卡宾(NHC)自组装单分子层进行了电导率分析。NHC单分子层作为超薄绝缘层，有效满足了低栅极漏电流和低工作电压的需求，同时其芳香族功能与有机半导体具有良好的兼容性。","scd":null,"kp":["材料类型[有机电子器件栅极介电材料]: N-杂环卡宾(NHC)自组装单分子层","材料特性[有机薄膜栅极应用]: 具备高化学/热稳定性、低栅极漏电流及超薄特性"]},{"i":36270,"as":"研究人员开发了一种双钴配位的酞菁羧酸酯衍生物作为高效人造抗氧化酶，用于清除活性氧并缓解炎症性肠病（IBD）。实验与理论计算表明，二聚体酞菁框架内扩展的π共轭和π电子离域，与外周羧基的质子化-去质子化动力学产生协同作用，显著增强了其催化活性与活性氧清除能力。","scd":null,"kp":["人工抗氧化酶[炎症性肠病缓解]: 双钴配位酞菁羧酸衍生物","催化活性[活性氧清除]: 显著增强的活性氧清除能力"]},{"i":36271,"as":"研究报道了一种苯并呋喃衍生物的不对称交叉偶联反应，用于构建轴手性。该反应采用手性镍催化剂，通过直接对映选择性和Z选择性的乙烯基C-O键去芳构化官能化，高效合成有价值的非对应异构无环烯烃。该反应条件温和且具有广泛的底物适用性，实验与理论机制研究证实其立体化学结果受差向异构化动态过程影响。","scd":null,"kp":["催化剂[苯并呋喃衍生物不对称交叉偶联]: 手性镍催化剂","反应特性[乙烯基C-O键]: 直接对映选择性和Z-选择性去芳构化官能化"]},{"i":36272,"as":"研究开发了一种空间位阻控制的选择性封端基团交换方法，成功精准合成了六对带有发光基团的[2]索烃方向异构体。这些异构体表现出依赖于方向的发射行为，在波长、光致发光量子产率和圆偏振发光（CPL）性能上存在显著差异。该发现极大丰富了此类异构体的结构多样性，并展示出在信息存储与加密领域的应用潜力。","scd":null,"kp":["合成方法[合成[2]索烃定向异构体]: 空间位阻控制的选择性封端基团交换法","产物数量[发光基团精确排列]: 六对[2]索烃定向异构体"]},{"i":36273,"as":"针对电催化乙炔加氢二聚（EHDA）制备1,3-丁二烯过程中C-C偶联与加氢的动力学失衡问题，研究在柠檬酸阴离子接枝的氧化亚铜催化剂上，通过稳定一价铜离子和强化氢键网络实现了动力学平衡。X射线吸收精细结构、俄歇电子能谱及理论模拟共同证实，柠檬酸阴离子修饰引发了电子转移，从而有效调控了催化性能。","scd":null,"kp":["催化剂修饰[乙炔电催化加氢二聚]: 柠檬酸阴离子稳定的Cu+并强化氢键网络","动力学调节[二聚与加氢过程]: 平衡二聚与加氢动力学"]},{"i":36274,"as":"研究开发了一种嵌入氮掺杂碳基体中的原子级分散铁位点异相催化剂，成功实现了以空气为氧化剂在30℃下对烯烃和炔烃的烯丙基和炔丙基C-H键进行高选择性的好氧羟基化。该方法解决了长期以来的过度氧化和副反应难题，适用于广泛的末端和内部底物，并具有优异的官能团耐受性。","scd":null,"kp":["催化剂[烯丙基和炔丙基C-H键的有氧羟基化]: 嵌入氮掺杂载体的原子级分散铁位点非均相催化剂"]},{"i":36275,"as":"研究综合了涵盖9个生物群系、超过16000个土壤芯的322项研究数据，结合机器学习模型预测了丛枝菌根真菌菌丝网络的全球密度。通过超30万条菌丝的机器人成像技术校准生物量模型，估算出全球表土层包含约1.10×10^17公里的菌丝网络，该网络每年负责将约10亿吨碳转移至地球土壤中。","scd":null,"kp":[]},{"i":36276,"as":"辅酶I（NAD+）的耗竭在小鼠体内会触发分娩倒计时，胎盘内的代谢时钟机制决定了分娩的时间。","scd":null,"kp":[]},{"i":36277,"as":"植物细胞壁的快速松弛机制是启动捕蝇草迅速闭合的直接原因，这一机制突破了自然界原有的生物学速度极限。","scd":null,"kp":[]},{"i":36278,"as":"社会经济等童年环境因素对儿童的大脑结构和功能发育具有最为显著的影响，在所有相关变量中位列首位。","scd":null,"kp":[]},{"i":36279,"as":"研究采用水同位素测量技术，对大陆尺度的地表水氮循环路径及其流向进行了建模分析。","scd":null,"kp":[]},{"i":36280,"as":"","scd":null,"kp":[]},{"i":36281,"as":"研究利用涵盖3821个欧洲流域的同位素辅助模型，揭示了自1980年以来氮循环演化与景观水流速度变化密切相关。研究提出了“湿度边界”概念，指出超越该边界的过渡会加剧氮积累和淋溶。基于此框架预测，到2100年若水文变化平缓，欧洲76%的地区氮淋溶将减少，但在水循环显著减速的情况下氮积累将增加。","scd":null,"kp":[]},{"i":36282,"as":"研究通过原位液压和机械测量发现，捕蝇草闭合的动力源于表皮细胞壁在大约一秒内的快速软化，释放了捕虫夹中储存的弹性势能。这一过程发生极快，无法用水分运输机制解释，属于非液压机制。这是植物界已报道的最快细胞壁力学调节现象，展示了植物通过材料特性动态调节实现无肌肉运动的原理。","scd":null,"kp":[]},{"i":36283,"as":"","scd":null,"kp":[]},{"i":36284,"as":"","scd":null,"kp":[]},{"i":36285,"as":"","scd":null,"kp":[]},{"i":36286,"as":"","scd":null,"kp":[]},{"i":36287,"as":"","scd":null,"kp":[]},{"i":36288,"as":"","scd":null,"kp":[]},{"i":36289,"as":"","scd":null,"kp":[]},{"i":36290,"as":"","scd":null,"kp":[]},{"i":36291,"as":"","scd":null,"kp":[]},{"i":36292,"as":"激光增强显微技术拓展了冷冻电镜的观测能力，使得科学家能够更清晰地观察难以捕捉的蛋白质结构，从而揭示新型药物靶点并呈现细胞内部更精细的视图。","scd":null,"kp":[]},{"i":36293,"as":"","scd":null,"kp":[]},{"i":36294,"as":"利用卫星雷达测绘海岸线沉降的地图正面临科学界的严格审查。雷达研究得出了相互矛盾的结果，对识别海平面上升易损区的努力提出了直接质疑。","scd":null,"kp":[]},{"i":36295,"as":"","scd":null,"kp":[]},{"i":36296,"as":"某些物质本身具有极小的直接气候影响，但会触发化学反应从而导致大气温室效应。现有研究探讨了将此类间接温室气体纳入并整合到现有气候评估框架中的方法。","scd":null,"kp":["[间接温室气体]: 极小的直接气候影响，但会触发导致变暖的化学反应"]},{"i":36297,"as":"","scd":null,"kp":[]},{"i":36298,"as":"","scd":null,"kp":[]},{"i":36299,"as":"研究开发了一种结合3D打印与分子铁电体的机电超材料，用作自供电压力传感器。梯度晶格设计实现了低模量与高承载力的协同，模量梯度显著提高了低载荷区灵敏度，将检测范围扩展了六个数量级。","scd":null,"kp":["传感器[3D打印超材料与分子铁电体结合]: 自供电压力传感器","[超材料结构设计]: 梯度晶格设计实现了自适应重构和变形模式转变"]},{"i":36300,"as":"通过分子重复放大多重共振效应的分子设计策略，成功开发出具有极窄线宽的有机发光材料。该策略在甲苯中实现了6.9纳米的荧光线宽，突破了传统有机发光材料40纳米的带宽限制。","scd":null,"kp":["发射光谱带宽[传统有机发光材料]: >40纳米","[多共振发射体材料]: 推动有机自发发射线宽逼近单色极限"]},{"i":36301,"as":"研究评估了全球牧场改善放牧强度的净气候效益。在平衡土壤二氧化碳封存、植物生产力、牲畜排放和饲料需求等因素后，确定改善全球牧场放牧强度可封存约22±4.3亿吨二氧化碳当量。","scd":null,"kp":["[放牧强度优化]: 通过土壤和植被固存二氧化碳来缓解气候变化，但可能因供应链排放降低净减排效益"]},{"i":36302,"as":"","scd":null,"kp":[]},{"i":36303,"as":"利用金属-氧簇{Fe3O}作为核心，通过原位限域络合构建了单原子-纳米颗粒双引擎催化剂（Fe3C/Fe-NC1050）。该催化剂有效促进电子转移和电荷沉积动力学，显著提升了碱性介质中氧还原反应的催化活性与稳定性。","scd":null,"kp":["催化剂[碱性介质电化学氧还原反应]: 单原子-纳米颗粒双引擎催化剂 (Fe3O分子炉锻造)","[金属-氧簇结构特征]: 高度有序的准分子结构促进电子转移并优化电荷沉积动力学"]},{"i":36304,"as":"文章综述了生物系统中的颜色选择性转化技术。由于单波长光无法控制复杂的活体系统，文章重点介绍了利用不同波长光对光开关、光点击化学和光笼进行独立和多重控制的策略，以及在生物应用中的挑战。","scd":null,"kp":["[生物系统中的光选择性转化]: 需开发在同一系统内组合并单独控制多种生色团的方法"]},{"i":36305,"as":"针对论文《硼氢化物氧化作为还原电合成中的对电极反应》进行勘误更正。主要修正了缺失的交叉引用、图注中的产率定义错误（分离产率、GC或HPLC测定产率），并替换了包含1H和13C-NMR光谱的更正版支持信息文件。","scd":null,"kp":[]},{"i":36306,"as":"通过相分离技术实现了锂硫电池均相/非均相双催化剂的设计。溶解的氯化铁酞菁（FePcCl）作为均相催化剂，不溶部分负载于碳球作为非均相催化剂。两者协同作用，有效调控硫氧化还原动力学和锂沉积行为。","scd":null,"kp":["[锂硫电池电解液化学调控]: 利用富含氮和具有活性金属中心的金属有机分子","[均相/异相催化剂设计]: 基于相分离技术"]},{"i":36307,"as":"研究提出一种基于“瓶中造船”策略的笼型多孔有机盐（POS）平台。由金刚烷磺酸和三(乙炔基苯基)甲胺构成的方钠石型POS，为分子光催化剂提供了透光、明确且可回收的笼状纳米反应器腔体。","scd":null,"kp":["[笼型多孔有机盐(POS)]: 作为“瓶中船”纳米反应器","[光催化剂载体特点]: 具有透光性且可重复使用"]},{"i":36308,"as":"通过合理设计双铜（Cu）位点，对金属有机框架（MOF）纳米结构进行原子配位调控。所制备的Cu-Trz-Br催化剂有效改善了C-C偶联效率，实现了工业级电流密度下二氧化碳电还原为高附加值多碳（C2+）产物。","scd":null,"kp":["[二氧化碳还原多碳产物(C2+)]: 面临C-C耦合效率低的挑战","[电催化体系]: 金属有机框架(MOF)纳米结构"]},{"i":36309,"as":"使用新型良性溶剂（1,3-二苯基丙酮），通过受控的自播种成核溶解凝胶工艺，将废弃PET塑料转化为整体气凝胶。该气凝胶具备高机械强度（弹性模量20±2 MPa）和超低导热率（21.9至28.9 mW m⁻¹ K⁻¹）。","scd":null,"kp":["PET气凝胶良性溶剂[自晶种成核]: 1,3-二苯基丙酮"]},{"i":36310,"as":"开发了一种耐氧、光诱导的微型加速原子转移自由基聚合（OPTIMA-ATRP）技术。该技术克服了传统方法需脱氧和耗时长等缺点，实现了从生物分子出发的高通量聚合物生物偶联物合成，极大简化了材料发现流程。","scd":null,"kp":["[聚合物生物偶联物合成]: 氧气耐受的光诱导微型化加速原子转移自由基聚合(OPTIMA-ATRP)"]},{"i":36311,"as":"在电催化乙炔半加氢反应中，利用具有不同吸电子能力配体的双铜分子催化剂成功切换氢转移路径。通过调控铜位点的电荷密度，苯甲酸-铜（BA-Cu）催化剂有效抑制了副反应，实现了高效的电催化机制调控。","scd":null,"kp":["[电催化乙炔半加氢氢转移途径切换]: Eley-Rideal机制与Langmuir-Hinshelwood机制之间切换","催化剂[电催化乙炔半加氢]: 轮桨式双铜分子催化剂"]},{"i":36312,"as":"引入电荷极化界面工程策略，利用Cr2O3/Ru-Fe2O3异质结构驱动苯酚选择性电氧化。该策略有效管理了电合成过程中的自由基，抑制了无序的自由基耦合和过度反应，实现了对苯醌长达1000小时的稳定电合成。","scd":null,"kp":["[对苯醌电合成时间]: 1000 h","[自由基管理界面工程策略]: 电荷极化界面工程"]},{"i":36313,"as":"综述了固相多肽合成中的树脂上晚期官能化技术。该技术允许直接在树脂上通过亲核取代、羰基化学等反应引入非天然氨基酸残基。这是一种高效、低成本的化学修饰手段，特别适用于加速多肽药物的高通量开发。","scd":null,"kp":[]},{"i":36314,"as":"提出空间分子解耦策略以克服有机闪烁体的高原子序数吸收与发光速度之间的矛盾。在D-A-D杂化分子中引入碘原子增强X射线吸收，同时有效抑制了自旋-轨道耦合（SOC）引起的荧光猝灭，实现了兼具高Z值和快速响应的有机闪烁体。","scd":null,"kp":["[有机闪烁体高Z元素吸收-速度权衡]: 引入高Z元素引发强自旋-轨道耦合(SOC)导致荧光猝灭","[X射线衰减增强分子去耦合设计]: 空间分子解耦策略"]},{"i":36315,"as":"本文提出一种可重构微流控平台，通过在原位3D打印和擦除软水凝胶结构，动态重塑发生化学计算的物理环境。该平台将微流控几何结构视为主动可编程元件而非被动容器，实现了硬件可重构的化学信息处理控制。基于此技术，研究展示了可在AND和OR功能之间交替切换的DNA逻辑门。","scd":null,"kp":[]},{"i":36316,"as":"本文开发了一种新型分子光开关基序PBFT，能够利用波长高达900纳米的近红外光进行完全可逆的直接激发。将光开关吸收光谱推向电磁波谱的低能端，有效避免了光损伤，支持光响应成分的混合，并最大化了可用颜色范围。该技术在不可见写入的2D和3D显示器中具有突出的应用潜力。","scd":null,"kp":["[近红外光开关吸收波长]: 900 nm"]},{"i":36317,"as":"本研究报告了镍-钴双金属氢氧化物纳米催化剂，将其作为高效且耐用的甲醇氧化反应催化剂，与析氢反应耦合以降低制氢能耗并将甲醇转化为甲酸盐。优化的NiCoO_xH_y催化剂在碱性介质中表现优异，仅需1.40伏（相对于可逆氢电极）的低电压即可提供400毫安每平方厘米的电流密度。","scd":null,"kp":["[甲醇氧化耦合析氢电催化]: 晶格氧工程","催化剂[碱性介质电催化甲醇氧化]: 镍钴双金属氢氧化物(NiCoOxHy)纳米片"]},{"i":36318,"as":"本研究提出一种供体-受体-供体（D-A-D）分子设计策略以增强分子内电荷转移效应，从而开发高性能有机电池正极。设计出的含强醌型受体核心的有机分子PTZBQ具有显著缩小的带隙和改善的电极动力学。这种结构使醌核心能提供额外的n型容量，极大提升了有机锂离子电池正极的比容量和稳定性。","scd":null,"kp":["分子设计策略[有机锂电池正极]: D-A-D分子内电荷转移(ICT)增强策略","分子类型[醌核受体]: 强醌型受体核心有机分子(PTZBQ)"]},{"i":36319,"as":"本研究利用N,N'-双(n-丁基)苝二酰亚胺和二溴化合物构建了供体-受体卤键键合共晶体，实现了刺激响应型智能发光。该有机材料利用三线态激子，通过保持结晶度的可逆结构切换，同步控制X射线激发的发光（闪烁）。这一可编程且可逆的发射特性在智能成像和信息安全领域具有高度应用价值。","scd":null,"kp":["发光机制[刺激响应有机材料]: 保持结晶度的可逆结构转换实现三重态激子发射调控","应用特征[X射线闪烁体]: 智能成像与信息安全领域的X射线激发发光控制"]},{"i":36320,"as":"本研究报告了一种含铝高熵层状双氢氧化物催化剂，并阐明了其在全解水反应中的两性自重构机制。在电化学活化过程中，两性铝的选择性浸出显著增加了金属活性位点的可及性，并在表面诱导形成富集的氢氧化铝层。这种羟基化界面有效调节了水的吸附和解离过程，从而突破了高熵催化剂性能控制的瓶颈。","scd":null,"kp":["[高熵催化剂电化学活化]: 含铝高熵层状双氢氧化物发生两性自重构机制调控催化活性与稳定性"]},{"i":36321,"as":"本研究结合时间分辨光致发光技术和物理约束的贝叶斯优化框架，揭示了有机太阳能电池中电荷转移（CT）态的能量损失机制。研究表明，CT态构成了控制电荷产生和非辐射电压损失的动力学-能量学瓶颈。多维动力学网络坍缩为单一描述符，即有效的CT注入速率k_CT，这是一个由耦合产生的重整化集合参数。","scd":null,"kp":["时间分辨光致发光测量范围[有机太阳能电池]: 100 ps–20 ns","动力学控制参数[电荷转移状态]: 有效电荷转移(CT)注入速率"]},{"i":36322,"as":"本综述探讨了纳米合金电催化剂在析氢反应中的精确实体原子掺杂策略。针对纳米合金在平衡催化活性与稳定性及反应动力学方面的挑战，研究表明精确掺杂可以通过调整电子构型、优化吸附能学和暴露潜在活性位点来增强其性能。这克服了铂族催化剂成本高、储量少的限制，为高效电解水制氢开辟了新路径。","scd":null,"kp":["[析氢反应纳米合金电催化剂]: 原子级精密掺杂解锁高效催化新路径"]},{"i":36323,"as":"本研究通过电置换和电化学还原制备了Cu泡沫支撑的PtCu3涂层Cu纳米线阵列催化剂。该催化剂用于低电位醛氧化反应，实现了太阳能驱动的双极制氢与生物质增值。原位表征和理论计算表明，PtCu3壳层不仅增强了偕二醇中间体的吸附，还削弱了HMFCA的结合，从而加速了化学与电化学串联步骤。","scd":null,"kp":["[双极产氢低电位醛氧化]: 增强化学与电化学串联非法拉第/法拉第反应步骤"]},{"i":36324,"as":"本研究构建了直接生长在碳纤维纸上的Au纳米颗粒修饰NbS2纳米片异质结构，作为高效光阳极用于光电化学制氢。在此结构中，Au纳米颗粒充当等离激元天线增强局部电磁场，强化光物质相互作用；而NbS2纳米片作为高导电性的半导体，促进了金属-半金属界面的电荷转移，显著提升了光电化学析氢反应的性能。","scd":null,"kp":["[光电化学析氢反应]: 构建金属-半金属过渡金属硫族化合物异质结界面(Au/NbS2)增强电荷转移"]},{"i":36325,"as":"受金属酶中钙离子稳定作用的启发，本研究在非晶多孔碳纳米片上构建了一种新型Fe-Ca双原子位点催化剂。引入的钙原子作为电子调节剂和结构稳定剂，有效降低了铁的氧化态并增强了Fe-N配位键。这种设计使催化剂在碱性介质中表现出优异的氧还原活性，半波电位达0.912伏，且具有前所未有的超稳定耐久性。","scd":null,"kp":["[超稳定氧还原反应]: 钙介导的Fe-N键强化双原子位点催化剂(Ca/Fe-N-C)防止Fe活性位点电化学浸出"]},{"i":36326,"as":"","scd":null,"kp":[]},{"i":36327,"as":"","scd":null,"kp":[]},{"i":36328,"as":"","scd":null,"kp":[]},{"i":36329,"as":"利用二十年来加利福尼亚州的卫星观测数据，研究评估了低强度火灾对后续野火活动和空气质量的影响。结果表明，低强度火灾使极高强度的野火发生概率降低了92%，且该效果在5公里范围内可持续十年。尽管规定燃烧初期会产生烟雾，但大幅减少的未来烟雾远超其产生的烟雾，十年后的收益成本比超过五倍。","scd":null,"kp":["[降低野火空气污染]: 低强度火灾(计划燃烧的替代指标)可减少后续野火活动并改善空气质量"]},{"i":36330,"as":"研究建立了能够繁殖变异型克雅氏病朊病毒的人源化神经细胞系统，揭示了人类朊病毒的繁殖受限于特定的毒株信息。人类朊病毒病是致命的神经退行性疾病，此前一直缺乏能够在哺乳动物细胞中复制真实感染性朊病毒的系统。该细胞模型的建立为分析人类朊病毒繁殖机制和开发公共卫生监测感染性检测方法提供了突破性工具。","scd":null,"kp":["[电荷密度波材料]: 利用时间周期性光场实现相选择性Floquet工程动态调控电子结构"]},{"i":36331,"as":"研究开发了一个集成扫描电子显微镜-聚焦离子束-飞行时间二次离子质谱平台，实现了超高结构与金属元素分布的纳米级共记录。将该高保真工作流应用于拟南芥、大豆和小麦，构建了单细胞金属组学图谱，揭示了进化上保守的亚细胞金属结构：叶绿体中富含特定金属(loid)元素，为理解植物细胞生理功能提供依据。","scd":null,"kp":["综合成像平台[克服空间分辨率、元素覆盖和结构相关性限制]: 集成扫描电子显微镜-聚焦离子束-飞行时间二次离子质谱(SEM-FIB-TOF-SIMS)","成像能力[植物细胞亚细胞全金属谱]: 纳米级分辨率的三维空间分布成像"]},{"i":36332,"as":"","scd":null,"kp":[]},{"i":36333,"as":"研究发现肝素硫酸蛋白聚糖（磷脂酰肌醇聚糖）在发育中的大脑皮层具有不依赖糖基化的精确且互补的表达模式。皮质祖细胞中表达的GPC4促进细胞增殖和中间祖细胞的产生，而神经元中的GPC2则充当径向神经元迁移的刹车。这些核心蛋白的多种生物功能独立于其糖基化作用，驱动了大脑皮层发育过程中的细胞特异性反应。","scd":null,"kp":[]},{"i":36334,"as":"研究将649个变量映射到儿童大脑并对比脑全关联研究（BWAS）图谱，发现社会经济地位（SES）表现出最强的大脑全脑关联，主要集中在运动和感觉区域而非认知区域。调整社会经济地位后，大脑与智商的关联减弱。研究指出，在变量中存在一个能够反映儿童社会经济状况的单一、常见的脑全关联模式。","scd":null,"kp":[]},{"i":36335,"as":"研究通过生成古基因组数据集，以微观区域分辨率重建了匈牙利小平原在后罗马时代的组织结构。对两个罗马时期遗址（68个样本）和五个后罗马时期遗址（246个样本）的遗传学和考古学分析揭示，该地区北欧血统比例上升，反映了向该地区的大规模人口迁徙。此外，尽管这些后罗马遗址具有相似的基因图谱、物质文化和丧葬习俗，但在微观区域层面上仍然存在差异。","scd":null,"kp":[]},{"i":36336,"as":"研究整合了4个新的巴布亚新几内亚（PNG）单倍体基因组和94个已发表的多样化基因组，构建了人类基因渗入结构变异（≥50个碱基对）图谱。结果表明，渗入的结构变异在基因中富集（47%），在PNG基因组中丰度最高。研究发现了11个可能源自古人类着丝粒的结构变异，以及16个与免疫相关基因和表达有关的适应性结构变异。","scd":null,"kp":[]},{"i":36337,"as":"2025年8月10日，阿拉斯加 Tracy Arm 峡湾发生体积超过6400万立方米的滑坡。气候变化导致的冰川退缩是此次滑坡的诱因。滑坡引发了初始波速超过70米/秒的破坏波，并产生高达481米的爬高巨型海啸。滑坡前数天出现微震活动，滑坡产生了相当于5.4级地震的长周期地震波。由滑坡引起的持续约66秒的假潮被困在峡湾内，其全球地震信号持续长达36小时。","scd":null,"kp":[]},{"i":36338,"as":"","scd":null,"kp":[]},{"i":36339,"as":"研究通过将4-氨甲基吡啶（4AMPY）芳香族二胺插入3D结构的Cs2AgBiBr6中，成功制备出一种Dion-Jacobson（DJ）型极性无铅绿色杂化钙钛矿(4AMPY)2AgBiBr8。该材料具有超窄层间距，克服了高电压下的严重离子迁移和铅毒性问题，实现了高效且稳定的自驱动X射线探测，为X射线探测材料的商业化发展提供了新方案。","scd":null,"kp":["X射线探测材料[Dion-Jacobson型杂化钙钛矿]: 极性无铅绿色杂化钙钛矿(4AMPY)2AgBiBr8","材料特性[DJ型极性绿色钙钛矿]: 高稳定性、超窄层间距、自供电、高灵敏度且解决铅毒性与高电压下离子迁移问题"]},{"i":36340,"as":"研究设计并合成了一种具有距离可调特性的铁单原子催化剂，其包含耦合的Fe1-Fe2原子对，能够从过一硫酸盐中顺序生成活性Fe(IV)=O物种。该催化剂解决了传统铁基材料易形成抑制聚合选择性的亚稳态过度氧化加合物的问题，实现了选择性氧化剂活化，从而在低能耗条件下通过将稀释有机物转化为可分离产物，实现连续流废水处理与资源回收的耦合。","scd":null,"kp":["催化剂[聚合物废水处理]: 具有距离可调特性的铁单原子催化剂(Fe-SAC)","催化机制[Fe-SAC]: 超交换辅助形成Fe(IV)=O链，避免形成抑制聚合选择性的亚稳态过氧化加合物，实现低化学耗水量连续流净化"]},{"i":36341,"as":"研究通过原位碳热还原法合成了氮掺杂碳封装的高熵氧化物催化剂（HEO@NC），用于高效去除和升级回收水中的污染物。该催化剂通过电子转移途径与表面吸附的羟基自由基耦合来活化高碘酸盐，能够在极端pH值和强离子干扰下，将酚类污染物选择性转化为聚合物产品。与无金属氮掺杂碳相比，HEO@NC通过界面电子耦合显著增强了高碘酸盐的活化能力。","scd":null,"kp":["催化剂[选择性氧化聚合去除及回收污染物]: 氮掺杂碳包覆高熵氧化物催化剂(HEO@NC)","合成工艺[HEO@NC]: 原位碳热还原法","催化机制[HEO@NC激活高碘酸盐]: 电子转移途径耦合表面吸附羟基，协同界面脱氯与有机自由基稳定化"]},{"i":36342,"as":"研究报道了一种碳壳封装的钴纳米颗粒催化剂，在强碱性条件下能够实现电催化硝酸盐还原与原位气相纯化的集成。在连续流和序批式电解槽中，该催化剂实现了高达92.4%的硝酸盐转化为氨的法拉第效率，并且在存在外源氨的情况下依然保持稳定的性能。高pH环境将生成的氨转移至气相，解决了电催化合成氨过程中氨分离的扩展性瓶颈问题。","scd":null,"kp":["催化剂[电催化硝酸盐还原为挥发性氨]: 抗氨碳壳包覆钴纳米颗粒(Co@C)","技术特点[硝酸盐还原]: 集成氨合成与原位分离，突破规模化应用中氨分离瓶颈"]},{"i":36343,"as":"研究提出了一种通过“分子爆炸”合成不对称双原子催化剂的通用策略。该方法能在受限空间内瞬间产生极端条件，克服了在无机材料载体上构建结构可控的双原子催化剂库的挑战。构建具有不对称活性位点的双金属对是进一步提升催化剂性能的关键策略，该方法为增强各类催化反应的协同效应开辟了新的化学与材料科学研究方向。","scd":null,"kp":["催化剂[双原子催化剂合成]: 具有不对称活性位点的双金属对","合成工艺[双原子催化剂通用合成]: 爆炸法构建结构可控库"]},{"i":36344,"as":"研究开发了一种由低成本聚磷酸盐（polyP）驱动的双酶级联反应，能够在单锅操作中将核苷转化为核苷-5'-三磷酸酯（NTPs），适用于所有标准的rNTPs和dNTPs。反应过程中，黑腹果蝇的广谱脱氧核苷激酶利用ATP将核苷转化为单磷酸核苷，随后由真杆菌的聚磷酸激酶完成三磷酸化。该酶级联体系有效解决了传统化学合成法中最终5'-三磷酸化反应产率低的问题。","scd":null,"kp":["酶级联反应[核苷转化为核苷-5'-三磷酸]: 仅需两种酶的一锅法操作","驱动机制[酶级联反应]: 成本高效的聚磷酸盐驱动","合成范围[核苷酸转化]: 所有经典rNTPs和dNTPs"]},{"i":36345,"as":"研究探讨了分子氧（O2）与n型有机电荷转移复合物的相互作用，颠覆了O2必然导致n型有机半导体电子陷阱或p型掺杂的传统认知。在使用吩嗪电子供体和四氰基醌二甲烷（TCNQ）电子受体的CTC体系中，暴露于O2并不会提取电子，而是通过电子供体-受体相互作用产生的部分离域电子态来钝化电子陷阱，从而有效增强了电荷传输能力。","scd":null,"kp":["半导体性能[n型有机电荷转移络合物]: 分子氧(O2)钝化电子陷阱，克服n型半导体对O2敏感导致的电子俘获或p掺杂问题","机制[n型有机CTCs]: 电子供体-受体相互作用主导O2相互作用"]},{"i":36346,"as":"研究通过将吸电子吡啶单元均匀整合到富含氨基的共轭sp2结构域中，开发出吡啶激活的供体-受体型碳点（N-CDs）。随后，将其与靶向程序性死亡配体1（PD-L1）的肽（KK）共组装，构建了N-CDs@KK纳米平台，作为一种强效的肿瘤靶向纳米酶。这种结构演化策略显著增强了纳米酶的生化活性和肿瘤特异性，为肿瘤催化治疗提供了有效方案。","scd":null,"kp":["纳米平台[肿瘤催化治疗]: 吡啶活化的供体-受体型碳点共组装纳米平台(N-CDs@KK)","材料特性[碳点共组装纳米酶]: 生化结构进化策略提升活性、程序化精准抗肿瘤特异性"]},{"i":36347,"as":"研究引入了三(2,2'-联吡啶)钌(II)/三正丙胺体系用于电化学发光（ECL）成像，突破了传统鲁米诺-过氧化氢体系信号微弱且试剂消耗大的限制。该技术通过局部累积三正丙胺延长了发光时间，实现了高时空分辨率、无标记且无外部光源的高灵敏成像。该方法无光毒性，具备优异的生物相容性，已成功应用于肿瘤多细胞球体的分析。","scd":null,"kp":["成像技术[肿瘤模型球状体分析]: 电化学发光(ECL)显微镜","成像特征[ECL成像]: 高灵敏、无标记、无外部光源、无光毒性且具有优异时空分辨率","机制[延长ECL发光时间]: 三正丙胺的原位局部积累"]},{"i":36348,"as":"研究报道了一种非线性手性光化学反应，利用飞秒红外脉冲倍频，驱动并追踪了手性CdTe/CdO纳米螺旋向CdO纳米椭球体的转化过程。圆偏振光诱导了可控的氧化序列，并通过二次谐波散射强度和手性光学对比度进行实时监测。随着CdO壳层破裂暴露出非中心对称的CdTe，二次谐波强度增强了二十倍，偏振发生反转。该发现基于二次谐波超米氏光学活性的实验观测。","scd":null,"kp":["转化机制[手性光化学]: 非线性手性光化学（飞秒红外脉冲倍频）","激光光源[驱动与监测]: 飞秒红外脉冲","监测技术[手性转化]: 圆二色二次谐波散射实时监测","转化路径[手性CdTe/CdO纳米螺旋]: 转化为CdO纳米球体"]},{"i":36349,"as":"研究使用改进的悬浮3ω技术测量了11种代表性聚合物半导体的热导率，揭示了热导率与层状堆积的次晶无序度之间存在强相关性。研究表明，聚合物半导体薄膜的面内本征热导率主要由层状次晶无序度控制。该发现对于理解有机电子和能量收集设备中的热传输物理机制至关重要，直接影响这些器件的性能、安全性和长期稳定性。","scd":null,"kp":["热导率测量方法[聚合物半导体]: 改进型悬浮3ω法"]},{"i":36350,"as":"针对全钙钛矿叠层太阳能电池中窄带隙锡铅杂化钙钛矿结晶形态差和高缺陷密度的问题，研究提出了一种路易斯硬碱性放大策略。该策略提供了额外的硬酸结合位点，促进了与Sn2+的配位，从而有效实现缺陷钝化并调控结晶过程。最终显著提升了器件的光电性能和长期稳定性，克服了底部电池的性能瓶颈。","scd":null,"kp":["技术瓶颈[钙钛矿叠层电池底电池]: 锡铅窄带隙钙钛矿面临高空位缺陷密度和较差的结晶形貌","解决策略[锡铅窄带隙钙钛矿]: 引入硬路易斯碱驱动结晶控制"]},{"i":36351,"as":"研究提出了一种利用高分辨率X射线衍射表征宽带隙半导体（特别是单晶金刚石）位错密度的综合方法，并通过拉曼光谱、氢蚀坑分析和霍尔效应测量进行了验证。该方法核心是一个定制的Python工具，用于处理X射线摇摆曲线和倒易空间图。该框架为下一代高功率、射频和量子技术中材料的缺陷密度准确、规模化量化提供了解决方案。","scd":null,"kp":["表征方法[单晶金刚石位错密度]: 结合高通量X射线的集成式表征方法"]},{"i":36352,"as":"研究报道了一种具有像素化机电可重构特性的可编程光学纳米剪纸矩阵。基于悬浮转向型纳米剪纸结构，设计并实现了具有高占空比和光学对比度的可变形像素阵列。通过中心极板产生静电力并利用变形臂散射入射光，该矩阵实现了可切换的光学加密和可重构信息显示。该策略为微显示器、光子芯片等前沿领域提供了超高像素数和高度灵活的可编程能力。","scd":null,"kp":["阵列特性[可编程光学纳米剪纸矩阵]: 像素化机电重构","结构特征[可编程光学纳米剪纸矩阵]: 具有高占空比和高光学对比度的可变形像素阵列"]},{"i":36353,"as":"研究探讨了通过同位素富集（如98MoO3、Mo18O3和98Mo18O3）来调节正交晶系α-MoO3的光学和热响应。α-MoO3在中红外波段拥有三种不同的声子色散，可提供三种双曲声子极化激元色散。同位素富集能够对极化材料的参数进行选择性调控，从而实现所需的光谱或热响应，这对于将极化激元材料应用于纳米级器件具有重要意义。","scd":null,"kp":["调谐机制[α-MoO3声子驱动响应]: 同位素富集","材料属性[中红外频段]: 提供双曲声子极化激元的三种极化激元色散"]},{"i":36354,"as":"研究利用商业可得的双齿硅烷试剂和低载量的定制硼催化剂，成功颠覆了酯类还原为醇衍生物的固有趋势，实现了高选择性的酯到醚还原。这种催化方法操作简单，具有高官能团耐受性，能够实现区域选择性和化学发散性还原。此外，该催化剂还成功实现了极具挑战性的烯醇酯到烯醇醚的还原转化，简化了醚类化合物的合成路径。","scd":null,"kp":["催化剂[酯到醚的脱氧还原]: 招潮蟹型硼烷催化剂","反应特征[酯到醚的脱氧还原]: 使用双齿硅烷试剂打破酯还原为醇的固有倾向，实现高选择性和高官能团耐受性"]},{"i":36355,"as":"研究描述了一种氧化还原中性的铁催化方案，利用未经活化的烷基硫鎓盐作为稳定且安全的非稳定卡宾前体，实现了丙二烯的环丙烷化反应。与经典的协同机制不同，该过程通过分步的自由基参与路径进行，具有优异的区域选择性和广泛的官能团兼容性，能够生成多种高价值的亚烷基环丙烷。该方法还可进一步扩展至其他底物的环丙烷化反应。","scd":null,"kp":["催化剂[丙二烯环丙烷化反应]: 铁催化剂","反应底物[非稳定卡宾前驱体]: 未活化的烷基锍盐","技术优势[丙二烯环丙烷化反应]: 氧化还原中性、条件温和且避免了危险的重氮烷烃"]},{"i":36356,"as":"本研究结合高通量实验、数据可视化与机器学习技术，通过分析原位环境光致发光（PL）实验，量化了卤化物钙钛矿成分、温度与材料特性之间的相关性。相关性热图揭示了铯含量对薄膜降解的影响，降维可视化方法发现了基于成分的明显聚类。对10种机器学习算法的筛选表明，这些算法能有效预测单一成分、成分广义化以及成分生成相关的PL特征。","scd":null,"kp":["分析方法[卤化物钙钛矿热稳定性]: 结合高通量实验与机器学习量化成分、温度与材料特性的关联"]},{"i":36357,"as":"本研究使用金-197靶系统分析了重离子聚变反应中的聚变裂变与准裂变现象。准裂变是一种非平衡过程，会强烈抑制重核的形成，并对反应入口道表现出强烈的依赖性。深入理解准裂变机制对于探索和合成新型超重元素具有关键作用。","scd":null,"kp":["核心现象[重离子融合反应]: 准裂变这一非平衡现象强烈抑制重核的形成","研究机制[金靶反应体系]: 系统研究融合-裂变与准裂变过程及其强烈的入射道依赖"]},{"i":36358,"as":"研究采用改进的多相输运（AMPT）模型，分析了质心能量为200 GeV的质子-质子和金-金碰撞中开粲强子的产生机制。研究具体给出了D0介子的横向动量谱、核修正因子以及Λc+/D0的产额比值。这有助于深入理解高能碰撞中粲强子的产生与输运特性。","scd":null,"kp":["质心能量[碰撞实验]: 200 GeV","碰撞体系[重离子碰撞]: pp和Au+Au碰撞","[重核碰撞]: 采用改进的多相输运(AMPT)模型研究D0介子的核修正因子(R_AA)"]},{"i":36359,"as":"研究人员首次在与Ia型超新星相关的能量范围内，测量了氖-20(α,p)钠-23核反应的截面。此前敏感度分析已发现该反应对Ia型超新星的核合成具有显著影响，但一直缺乏直接的截面测量数据。本次实验结果为该天体物理反应速率的估算提供了实测数据基础。","scd":null,"kp":["[核反应截面测量]: 首次在Ia型超新星相关能量下测量20Ne(α,p)23Na反应截面","[天体物理核反应]: 20Ne(α,p)23Na反应对SNIa核合成具有显著影响"]},{"i":36360,"as":"研究基于相对论密度泛函理论的五维集体哈密顿量，深入探讨了软三轴偶偶氙同位素（氙-122至氙-128）中γ能带的物理性质。理论计算成功重现了实验观测到的交错参数，并揭示了这些同位素中可能存在的摇摆运动模式。","scd":null,"kp":["[同位素研究对象]: 122-128Xe(软三轴偶偶Xe同位素)","[理论模型]: 基于相对论密度泛函理论的五维集体哈密顿量"]},{"i":36361,"as":"BESIII合作组利用北京正负电子对撞机（BEPCII）上收集的约27.12亿个ψ(3686)事件数据，在强子跃迁ψ(3686)→π+π−J/ψ过程中检验了电荷共轭与宇称联合（CP）对称性。研究精确测量了不对称性可观测量，为粲夸克电荷偶极矩的精确测量提供了关键物理结果。","scd":null,"kp":["事件数量[BESIII探测器采集]: (2712.4±14.3)×10^6个ψ(3686)事件","[物理测试]: 在强子跃变ψ(3686)→π+π−J/ψ中测试电荷共轭与宇称联合(CP)对称性"]},{"i":36362,"as":"研究定量分析了弹性形变下共价晶体（如硅和金刚石）的晶格应变。微纳尺度下的共价半导体晶体能够展现出超大弹性应变，这对于应变工程电子和光电器件具有重要意义。该研究深入探讨了这种宏观弹性形变产生的物理机制及其晶格应变的精确量化。","scd":null,"kp":["[材料弹性]: 共价半导体晶体(如硅和金刚石)在微纳尺度下表现出超大弹性应变","[应变工程应用]: 实现了用于应变工程电子和光电器件的理想品质因数"]},{"i":36363,"as":"研究揭示了光学晶格中的光学时程线与压缩动力学现象，建立了经典力学中的时程线问题与量子光学压缩态在光晶格系统中的精确类比。这些现象均存在于具有非均匀耦合的波导阵列物理系统中。将此概念扩展至二维系统，还成功产生了类李萨如图形的轨迹。","scd":null,"kp":["[物理类比]: 将经典力学的最速降线问题和量子光学的压缩态与光晶格建立精确类比","系统模型[光波导阵列]: 具有非均匀耦合的波导阵列"]},{"i":36364,"as":"研究展示了一种适用于热气体的新型无光腔超荧光横模控制方法。传统光的横模控制依赖光学谐振腔，而该无光腔方法利用周期性排列的原子产生集体辐射。这项新技术成功将无光腔横模控制的应用范围从冷原子扩展到了热气体体系。","scd":null,"kp":["[横模控制方法]: 提出一种适用于热气体且无需光学谐振腔的横模控制新方法"]},{"i":36365,"as":"研究提出了一种在光力学系统中实现混合SU(1,1)干涉的方案。在非简并SU(1,1)干涉仪中，双模压缩器取代了分束器，无需输入压缩态即可实现低于散粒噪声的灵敏度，且对探测损耗具有鲁棒性。该方案将干涉仪的一个“臂”设定为机械振子模式，利用量子纠缠实现高精度测量。","scd":null,"kp":["[干涉仪改进]: 非简并SU(1,1)干涉仪用双模压缩器替代分束器实现低于散粒噪声的灵敏度","[光机械系统]: 提出一种混合光机械系统实现方案，其中一臂为机械振子"]},{"i":36366,"as":"","scd":null,"kp":[]},{"i":36367,"as":"研究探讨了量子信道通过嘈杂的后选择闭合类时曲线进行逆因果通信的容量能力，即信息从未来的发送者传输回过去的接收者。研究完整表征了这种数学上由信道表示的逆因果通信容量，为理解时间反演方向上的量子信息传输提供了理论框架。","scd":null,"kp":["[量子通信机制]: 研究量子信道的逆因果通信能力，实现通过含噪闭合类时曲线向过去发送信息","[信道容量特征]: 完全表征了由数学信道表示的含噪后选择闭合类时曲线的通信容量"]},{"i":36368,"as":"研究调查了线性SU(2)格子链子系统在热化过程中的纠缠谱中的“反平坦度”的时间依赖性。反平坦度是非稳定性的量度，也是非局域量子魔力资源的下界。通过追踪大量初始状态的时间演化，研究揭示了在系统达到热化之前存在的一个“魔力势垒”现象。","scd":null,"kp":["[量子资源度量]: 研究纠缠谱中的反平坦性时间依赖性，作为非稳定性和非局域量子魔法资源的下界","物理系统[热化过程]: 线性SU(2)四角链的子系统"]},{"i":36369,"as":"研究探讨了二维层状磁性材料NiPS3中由晶体场调控的自旋翻转发光现象。NiPS3在155K以下表现出反铁磁性，并展现出与三重态之间跃迁相关的尖锐光致发光。研究表明，通过晶体场的精确调控，可以实现对该材料自旋翻转发光特性的有效控制。","scd":null,"kp":["相变温度[NiPS3反铁磁性]: 低于155 K","发光特性[NiPS3]: 与三重态跃迁相关的锐利光致发光"]},{"i":36370,"as":"研究报道了一种由多金属酚醛网络（MPN）工程化的低密度聚合物烧蚀材料，旨在解决行星进入任务中热防护材料的质量、烧蚀抑制与耐超高温氧化之间的矛盾。该材料通过准线性钛/锆/铪多金属聚合物与酚醛配体的控制配体交换及聚合形成纳米孔气凝胶基质。其多金属物种的分子级分散控制了原位陶瓷化演变，可承受高达2900K的热防护与隔热。","scd":null,"kp":["耐温极限[多金属酚醛网络低密度聚合物烧蚀材料]: 2900K","材料体系[热防护与隔热]: 多金属酚醛网络(MPN)工程化低密度烧蚀材料","工艺特点[多金属酚醛网络]: 分子可编程的多金属陶瓷化"]},{"i":36371,"as":"针对二维粘土纳米流体膜在渗透能收集中离子传输路径受限及水环境中易溶胀的难题，研究通过顺序交联策略在层状膜（CHM）层间构建了连续的氢键网络。该网络具有双重功能：一是建立低能垒路径以加速阳离子传输；二是作为限制结构，显著提升离子选择性和在水溶液中的长期稳定性，实现高效的渗透能发电。","scd":null,"kp":["应用瓶颈[二维粘土纳米流体膜]: 离子传输路径迂曲/层间纳米通道在水环境中严重溶胀","改进工艺[粘土膜]: 构建连续的层间氢键网络"]},{"i":36372,"as":"针对高分子摩擦纳米发电机（TENG）在高温环境下因热电子发射和热变形导致输出性能下降的问题，研究将TENG的电荷产生与收集单元进行了解耦与重新设计。研究合成了一种含有交替极性与庞大刚性取代物的偶极玻璃聚合物（CPAE），并将芳香族多酚锚定的MXene纳米片进行交联并形成三明治结构，以实现高温下的摩擦电传感与电磁屏蔽。","scd":null,"kp":["设计策略[高温摩擦纳米发电机(TENG)]: 解耦聚合物TENG的电荷产生与收集单元","失效机制[高温TENG]: 热电子发射和热变形降低摩擦电输出并扭曲传感信号"]},{"i":36373,"as":"研究提出了一种基于机器学习引导的超材料策略，以实现可编程的水动力隐身。现有的流体隐身器件多为静态，在背景渗透率变化时失效。该研究使用隐身衣作为模型系统，通过一种可调渗透率壳层，在广泛的背景渗透率范围内维持隐身效果。其逆向设计框架能够快速映射目标参数，实现水动力伪装与外部流场匹配。","scd":null,"kp":["技术方案[水动力超材料]: 机器学习引导的可编程水动力隐身超材料","现有缺陷[水动力隐身器件]: 大多数器件是静态的，在背景渗透率变化时会失效"]},{"i":36374,"as":"为解决二维kagome共价有机框架（COFs）的高分辨率结构表征难题，研究设计了一系列基于苯并二噻吩和苯并噻二唑单元、带有不同烷氧基侧链的受体-供体-受体型线性连接体。通过这些连接体与二苯并菲的亚胺缩合反应，合成了带有甲氧基、乙氧基和丙氧基侧链的多样化二维kagome COFs，成功实现了对kagome COFs晶体分子级精确的三角形端封功能调控。","scd":null,"kp":["结构设计[二维Kagome共价有机框架]: 基于苯并双噻吩设计的受体-供体-受体型线性连接体","工艺特点[COF晶体]: 侧链工程实现分子级精确的三角形端面"]},{"i":36375,"as":"研究揭示了含硫微生物次级代谢产物噻吲哚素的生物合成机制。研究发现了一组不同的氧化还原酶通过协同作用，共同 orchestrate（编排）了吲哚噻吩骨架的形成及其随后的生物激活过程，最终生成具有真正抗菌活性的代谢物硫氧化噻吲哚素。短链脱氢酶TndE形成硫代色氨酸后，血红素依赖性酶TndD通过N-羟基化启动碳硫键的形成。","scd":null,"kp":["催化机制[噻诺多林生物合成]: 不同氧化还原酶协同编排吲哚噻吩骨架形成与N-羟基化介导的生物活化"]},{"i":36376,"as":"纯色全有机发光体具有窄光谱特性，在高清OLED和多色生物成像中应用广泛。本文综述了其光谱特征、光谱宽度的定义、光谱展宽的物理基础（包括振动耦合、环境效应和几何结构），并提炼出控制发光体减少激发态与基态几何变化的底层结构设计原则，为避免繁琐的试错提供了理论指导。","scd":null,"kp":["材料体系[高清OLED]: 基于多共振结构的纯有机发光体","材料体系[多色生物成像]: 基于聚甲碱类结构的窄光谱发射体"]},{"i":36377,"as":"本文报道了一种具有独特结构的新型低价主族元素碳硼烷簇的合成与化学性质。基于双阴离子硼咯π-配体平台，合成出一种包含两个亲核Ga(I)离子的“反式夹心”Janus型双亚镓络合物。该化合物也可被描述为闭合式的1,7-双镓四碳硼烷簇，并已开展对该新化合物类的初步反应性研究。","scd":null,"kp":["材料结构[低碳主族元素硼烷簇]: “反式夹心”Janus型双亚镓络合物"]},{"i":36378,"as":"本文建立了一种由环氧介导的反向硫化平台，在无溶剂和碱催化条件下，突破了现有依赖高温自由基和烯烃单体将单质硫转化为聚合物的限制。机理研究表明，碱催化下的硫通过亲核开环路径被引入聚合物主链。通过将生物基环氧化植物油与单质硫结合，成功构建出富含硫的聚合物网络。","scd":null,"kp":["工艺特点[环氧化学逆向硫化]: 无溶剂、碱催化条件下的低温非烯烃路线","技术突破[富硫聚合物网络]: 将富硫聚合物形成过程扩展到烯烃化学之外"]},{"i":36379,"as":"本文提出了一种相变驱动的自催化策略，将水中的金属污染物原位转化为活性催化剂，实现集成净化与资源化。在Ni²⁺/酚类系统中，过硫酸盐（PMS）使反应平衡向生成NiOOH纳米颗粒移动，从而快速诱导酚类发生聚合，并与残留的Ni(OH)₂发生共沉淀，为分散式低碳水处理提供了新范式。","scd":null,"kp":["催化策略[重金属与有机微污染物处理]: 相变驱动的原位自催化策略，将金属污染物原位转化为活性催化剂"]},{"i":36380,"as":"针对合成催化抗氧化剂稳定性差和细胞内定位难的问题，本文提出一种脂质共轭策略，将锰Salen（EUK）催化剂共价整合到磷脂膜中。通过将带有羧酸基团的EUK衍生物与胺基封端的磷脂偶联，成功制备出结构明确的磷脂-EUK共轭物。该共轭物在脂质体中保持催化活性，实现了可控的催化剂负载和长期的胶体完整性。","scd":null,"kp":["催化剂修饰策略[胞内活性氧控制]: 脂质偶联策略，使锰Salen (EUK)催化剂共价整合入磷脂膜"]},{"i":36381,"as":"本文提出一种化学气相沉积（CVD）策略，在高度多孔的碳基底上生长均匀且电子连续的碳涂层，用作高性能钠离子电池负极。该涂层缩小并部分封闭了开放孔网络，抑制表面反应，形成纳米限域域使钠能更紧密地存储。该结构显著提升了储钠性能，总可逆容量超过500 mAh g⁻¹，可逆平台容量高达420 mAh g⁻¹。","scd":null,"kp":["碳膜制备工艺[钠离子电池负极材料]: 化学气相沉积(CVD)策略","碳涂层工艺特点[多孔碳基底]: 均匀且电子连续，能收窄并部分密封开放孔网并抑制表面反应"]},{"i":36382,"as":"为提升质子交换膜水电解槽（PEMWE）中酸性析氧反应（OER）的效率，本文研究了Co₃O₄催化剂。针对传统吸附析出机制（AEM）受限于线性标度关系的问题，本文通过调控催化剂-电解质界面处的水分子作用，证明Co₃O₄的酸性OER路径可以通过界面水介导的氧化物路径机制（OPM）进行合理调节，从而提高催化活性和稳定性。","scd":null,"kp":["催化剂替代目标[酸性析氧反应(OER)]: 替代IrO2的Co3O4基电催化剂","催化机制[酸性水氧化]: 界面水介导的氧化物路径机制(OPM)，突破吸附物演化机制(AEM)的线性比例关系限制"]},{"i":36383,"as":"配位交联聚合物网络（CCPNs）通过将动态金属-配体相互作用嵌入聚合物基体中，构建出仿生响应型聚合物材料。与传统的共价或超分子交联不同，配位键提供连续可调的键强、明确的几何构型和刺激敏感的平衡，并能实现电子、氧化还原和催化转变。这使得CCPNs能将微弱的环境信号直接转化为适应性的宏观功能，在软体机器人和传感领域极具潜力。","scd":null,"kp":["聚合物网络构建[仿生响应聚合物]: 嵌入动态金属-配体相互作用的配位交联聚合物网络"]},{"i":36384,"as":"高熵纳米材料（HENMs）作为独特的电催化剂，具有协同活性位点、可调电子结构和优异耐久性。传统合成方法依赖苛刻的热力学条件，限制了规模化和结构控制。本文综述了通过水热法、溶剂热法、前驱体分解和电偶置换等软化学路线，在温和条件下稳定高熵结构的最新进展。这些策略不仅克服了多金属整合的动力学障碍，还允许对材料的形貌和表面化学进行精确调控。","scd":null,"kp":["高熵纳米材料合成[氧化还原电催化]: 软化学路线（如水热和溶剂热法）取代严酷的热或高压条件实现均匀合金化"]},{"i":36385,"as":"为了解决现有低温保护剂生物相容性差的问题，受抗冻生物体内内源性抗冻（糖）蛋白启发，研究人员开发了具有控冰特性和低温保护效果的（糖）多肽及其类似物。这些仿生材料被成功应用于细胞冷冻保存，以在极低温度下维持细胞的生存力和功能，为生物医学和临床转化提供了高效的细胞存储方案。","scd":null,"kp":["防冻保护剂开发[细胞冷冻保存]: 仿生防冻（糖）肽类材料"]},{"i":36386,"as":"","scd":null,"kp":[]},{"i":36387,"as":"","scd":null,"kp":[]},{"i":36388,"as":"为了在强辐射太空环境中高效识别天体活动，本文报道了一种基于κ相氧化镓（κ-Ga₂O₃）的传感器内储池计算系统（κ-ISRC）。利用原子滑动机制引起的κ-Ga₂O₃极化切换，制备了铁磁高电子迁移率晶体管（FeHEMT）。该器件集成了深紫外传感、存储和神经形态计算功能，Al₂O₃/κ-Ga₂O₃介电/铁电栅极堆栈为强辐射环境下的天体活动识别提供了硬件支持。","scd":null,"kp":["材料体系[辐射环境天体神经形态计算]: 基于κ相氧化镓(κ-Ga2O3)的宽禁带半导体","硬件系统[高鲁棒性天体活动识别]: 结合深紫外传感的传感器内储备计算系统(κ-ISRC)"]},{"i":36389,"as":"研究在氧化石墨烯中发现了破碎液晶态，这是介于普通向列型液晶和聚集态之间的一种中间状态。在平衡的片间相互作用下，大型液晶畴分裂成小尺寸区域，同时保持了流动性和可加工性。这种受挫有序状态为构建紧凑的无定形结构提供了新途径，能够抑制大型结构缺陷，实现高强度与韧性的结合。","scd":null,"kp":["液晶状态[氧化石墨烯]: 介于普通向列液晶与团聚之间的碎片化液晶态","结构特性[平衡片间相互作用]: 保持流动性和可加工性的同时构建区别于传统结晶取向的致密无定形结构，抑制大型结构缺陷"]},{"i":36390,"as":"本文开发了一种单分子双报告基因探针DHU-AKI-3，用于急性肾损伤（AKI）的早期精确诊断。该探针在受损肾脏中被选择性激活，产生长滞留的光声信号，在临床诊断窗口前实现实时原位成像；同时释放近红外荧光信号并快速排入尿液，支持智能手机辅助的比色分析。该技术成功集成了原位成像与体外便携式尿液分析。","scd":null,"kp":["分子探针[急性肾损伤早期诊断]: 单分子双报告探针(DHU-AKI-3)","探针核心特性[原位成像与便携式尿液分析同步诊断]: 可激活的无串扰多重信号输出"]},{"i":36391,"as":"异金属金属有机框架整合了空间上定制化的金属中心和受限的孔隙微环境，为精细化学品的协同催化选择性合成提供了一种变革性的设计范式，极大地推动了下一代先进热催化技术的发展。","scd":null,"kp":["异金属MOFs[空间定制与微孔限域]: 提供协同催化与精细化学品选择性合成的新范式"]},{"i":36392,"as":"针对二氧化碳加氢合成高碳醇过程中C-C偶联难以调控的挑战，本文通过定制钾修饰的ZnZrOx-Fe5C2界面，优化了烷基-含氧化合物的偶联过程。实验和理论研究表明，该多相催化剂实现了高效的高碳醇合成，获得了创纪录的C3+醇产率以及优异的长期稳定性，展示了通过二氧化碳加氢生产高附加值化学品的巨大实用潜力。","scd":null,"kp":["CO2加氢制高级醇[K修饰的ZnZrOx-Fe5C2界面]: 优化烷基-氧物种偶联，实现创纪录的C3+醇产率和优异的长期稳定性"]},{"i":36393,"as":"针对聚四氟乙烯（PTFE）废弃物因碳氟键极其稳定难以回收的问题，本文提出接触电催化诱导的自蔓延反应（CEC-SPR）策略。利用高反应活性的NaK合金在室温下与PTFE发生放热的Wurtz脱氟反应，实现了对强韧碳氟键的高效断裂。该方法在常温下成功将PTFE转化为氟掺杂碳材料和无机氟化物，为含氟塑料废弃物的升级回收提供了新概念。","scd":null,"kp":["PTFE降解[常温液态合金接触电催化诱导自蔓延反应(CEC-SPR)]: 利用高反应活性NaK合金通过放热Wurtz反应实现室温下C-F键高效断裂"]},{"i":36394,"as":"局部化学聚合通常需要反应基团的精确静态预组装。本文通过在局部化学设计中引入动态流体晶格（如核壳柱状液晶），克服了严格的几何约束，在非理想预组装下实现了近乎定量的单体转化。流体晶格内快速的分子涨落使反应位点短暂靠近以激活反应，各向异性的柱状结构则引导链生长成明确的线性螺旋聚合物。","scd":null,"kp":["拓扑聚合[动态流体晶格(核壳柱状液晶)]: 打破静态预组装的几何限制，实现无理想预组装下的近定量单体转化"]},{"i":36395,"as":"本文通过构建由两株基因工程大肠杆菌组成的代谢交叉饲养合成合作系统，证明了交叉饲养虽然促进了细菌群体的生长，但也放大了两个种群内的细胞噪声。这种由交叉饲养引起的表型异质性增加，主要归因于资源异质性的增强以及随后各细胞群体内基因表达的变化，揭示了正相互作用在生态系统中的脆弱性及内在动因。","scd":null,"kp":["合成微生物共培养系统[大肠杆菌代谢交叉喂养]: 交叉喂养虽促进生长，但放大了细胞噪声并引发表型异质性"]},{"i":36396,"as":"魔角扭曲双层石墨烯形成的莫尔超晶格为探索电子关联与能带拓扑提供了一个高度可调的平台。在魔角附近，莫尔干涉显著抑制电子动能，产生具有非平凡量子几何的平坦电子能带。这些特性引发了常规固体中不存在的相互作用驱动相。本综述总结了该领域最新进展，重点探讨多体效应和拓扑效应如何重构平带光谱，并梳理了关联绝缘态、风味选择性级联和谷间相干等现象。","scd":null,"kp":["魔角扭曲石墨烯莫尔超晶格[近魔角]: 抑制动能产生具有非平庸量子几何的平带"]},{"i":36397,"as":"电化学二氧化碳还原（CO2RR）的选择性和稳定性不仅取决于催化剂，还受催化剂层局部微环境的调控。离聚体曾被视作惰性粘结剂，实则是调节微环境的关键因素。本综述探讨了质子和阴离子交换离聚体的结构多样性及其对离子传输和界面反应至关重要的物理化学性质，并进一步论述了溶剂控制的离聚体组装对CO2RR性能的具体影响。","scd":null,"kp":["催化剂层局部微环境调控[离聚物]: 从被动粘结剂转变为关键调节剂"]},{"i":36398,"as":"","scd":null,"kp":[]},{"i":36399,"as":"","scd":null,"kp":[]},{"i":36400,"as":"","scd":null,"kp":[]},{"i":36401,"as":"","scd":null,"kp":[]},{"i":36402,"as":"二维半导体的电气接触仍是下一代电子器件的关键瓶颈。研究人员提出一种直接可视化电荷流动的方法，观察电荷如何穿过单层二硒化铂单片内部形成的半金属-半导体界面。该单层材料中，部分区域被塑造成半导体，其余保持半金属性。测试表明，电荷穿过该单晶边界时没有显著阻力，为未来二维电子器件设计低电阻接触提供了多功能平台。","scd":null,"kp":["电荷输运[单层二硒化铂半金属-半导体界面]: 电荷穿过单晶边界无明显电阻"]},{"i":36403,"as":"","scd":null,"kp":[]},{"i":36404,"as":"I+中间体在转化过程中的不稳定性（易水解且可逆性差）阻碍了高压水系锌碘电池的发展。研究提出一种空间位阻配位策略，利用氯离子（Cl-）和富含磺酸基的TES-离子调制I+离子的配位环境。Cl-离子通过卤化物配位激活I+离子，同时TES-离子提供空间位阻效应，以此提升四电子转化过程的稳定性与电池性能。","scd":null,"kp":["I+中间体稳定性[氯离子和富磺酸根TES-空间配位策略]: 抑制水解并实现四电子转化"]},{"i":36405,"as":"钙钛矿太阳能电池的降解机制不明确限制了其商业化进程。研究通过电容频率谱定量分析与细致平衡理论，确定深能级I_FA和I_Pb缺陷是导致器件降解的主因，其浓度虽低于浅能级缺陷三个数量级，但破坏力极大。为缓解此问题，研究人员设计了基于双端电正性3TU2+的非插入配体配位策略，有效抑制缺陷并提升器件稳定性。","scd":null,"kp":["电池降解主导因素[钙钛矿太阳能电池]: 深能级I_FA和I_Pb缺陷"]},{"i":36406,"as":"高熵工程打破了太阳能水分解中的活性-稳定性权衡。研究设计了具有晶格畸变（δavg = 3.35%）的尖晶石氧化物(CuCoNi)(GaCoCrMnFe)2O4，并稳定了Co2+tet/Co3+oct双催化位点。该材料表现出超越元素平均值的“鸡尾酒效应”：Cu/Ga捕获光能，Co实现双位点表面催化，Ni/Cr诱发畸变与局部内建电场，Cu/Mn引发姜-泰勒效应并上移d带中心。","scd":null,"kp":["晶格畸变程度[高熵尖晶石氧化物]: 3.35%","催化剂配方[光(电)催化析氢]: 尖晶石氧化物(CuCoNi)(GaCoCrMnFe)2O4"]},{"i":36407,"as":"将氧化还原活性的曙红Y（EY）嵌入共轭聚合物骨架中合成EY-X聚合物，用于高效光催化硝酸盐还原产氨。传统聚合物光催化剂常因缺乏合适的氧化还原活性基团导致电荷分离效率低下。EY-X聚合物通过双重猝灭电荷转移机制有效解决了这一限制，在可见光照射下实现了创纪录的硝酸盐制氨光催化转化性能。","scd":null,"kp":[]},{"i":36408,"as":"锂多硫化物穿梭是导致锂硫电池性能衰退的主因。受章鱼形态启发，研究通过光引发自由基聚合反应合成了乙酰化聚山梨酯（Ac-CP80）凝胶电解质。结合量子计算，该电解质构建了差异化溶剂化环境，有效调节阳离子迁移。这一机制解决了传统策略因忽视溶剂化环境调节而导致锂离子解离和传输受阻的问题，抑制了穿梭效应。","scd":null,"kp":["电解质设计[锂硫电池]: 章鱼仿生凝胶电解质构建差异化溶剂化环境"]},{"i":36409,"as":"钙钛矿薄膜的不可控结晶导致晶体取向随机，限制了器件性能。研究提出利用Mg3Sb2量子点对钙钛矿湿膜进行后处理，以调节结晶并引导特定晶面生长，成功构建出梯度晶面取向（GFO）的高质量钙钛ite薄膜。GFO结构顶层由(111)晶面主导，底层由(001)晶面主导，协同结合了不同晶面的优势，显著提升了钙钛矿太阳能电池的光电性能与稳定性。","scd":null,"kp":["结晶调控[钙钛矿太阳能电池]: Mg3Sb2量子点后处理调控梯度晶面取向"]},{"i":36410,"as":"通过双电子氧还原反应（2e⁻ ORR）进行电化学合成过氧化氢（H2O2）正从活性位点优化转向工业条件下的多尺度界面调控。本综述建立了一个跨尺度框架，将分子尺度的电化学微环境、介观尺度的气-液-固三相界面以及宏观电极/反应器架构与H2O2电合成的选择性、传质效率和耐久性直接关联起来。","scd":null,"kp":[]},{"i":36411,"as":"磷酸锰铁锂（LMFP）因导电性差和严重的姜-泰勒（J-T）畸变而商业化受阻。研究采用多金属离子（Ni, Cu, Ti）轨道工程策略，定制了LiMn0.475Fe0.475Ni0.03Cu0.01Ti0.01PO4（LMFP-NCT）正极材料。该策略通过增强异质原子与主晶格间的轨道杂化，有效解耦了上述双重难题，同时提升了材料的动力学性能和结构稳定性。","scd":null,"kp":["阴极材料[磷酸锰铁锂电池]: LiMn0.475Fe0.475... (掺杂Ni, Cu, Ti)"]},{"i":36412,"as":"","scd":null,"kp":[]},{"i":36413,"as":"","scd":null,"kp":[]},{"i":36414,"as":"加速的永久冻土融化可能释放大量深层（>3米）冻结土壤碳形成二氧化碳。使用更新的ORCHIDEE-MICT模型进行模拟显示，纳入深层碳过程提高了与观测结果的一致性。在三种未来情景下，由于活跃层加深引起深层碳分解，1900年至2100年间北方（>30°N）净二氧化碳吸收量将减少47至74拍克碳。在高排放路径下，本世纪将更早出现冻土碳的净释放。","scd":null,"kp":[]},{"i":36415,"as":"古老基岩滑坡沉积物在山区地形中分布广泛，具有厚度超过5米的深厚风化剖面，其地下深处储存着大量土壤有机碳（SOC）。通过分析俄勒冈州西部滑坡年代序列，研究得出SOC与年龄的关系。将其应用于近10000个已测年滑坡的清单后发现，在41年以上的滑坡中，深层SOC储量约占总储量的70%，表明滑坡沉积物是深层有机碳储存和获取的重要场所。","scd":null,"kp":[]},{"i":36416,"as":"","scd":null,"kp":[]},{"i":36417,"as":"在温带落叶橡树中，光合作用与地上部分木质生长在昼夜和季节尺度上表现出异步性。跨越137个树木年轮站点的数据显示，仲夏后当年年生长对气候变异不敏感，尽管此期间发生了全年26%至36%的总初级生产力（GPP）。站点精细测量进一步表明，木材形成比光合作用更早停止，且仅限于大气干旱度和温度较低的时期。","scd":null,"kp":[]},{"i":36418,"as":"研究人员开发了名为VLP-Open HLA的多价可装载纳米颗粒平台，用于高通量T细胞筛选。该平台以病毒样颗粒（VLP）为基础，最多可展示60个肽/HLA分子。VLP-Open HLA能够染色抗原特异性CD8+ T细胞，可作为筛选孤儿T细胞受体的工具；结合共刺激分子时，还可以作为人工抗原递呈平台诱导T细胞活化或无反应状态。","scd":null,"kp":[]},{"i":36419,"as":"研究提出一种专为大气通道设计的离散调制连续变量量子密钥分发（CV QKD）系统。利用偏振编码技术，该系统有效利用了湍流大气的非双折射特性，从而将CV QKD网络扩展到现有的光纤骨干网之外。在静态3分贝损耗通道的实验室演示中，系统成功证明了离散调制在实际大气环境中的量子安全通信可行性。","scd":null,"kp":["调制方式[连续变量量子密钥分发]: 离散调制","通信体制[连续变量QKD]: 渐近机制下计算密钥率"]},{"i":36420,"as":"","scd":null,"kp":[]},{"i":36421,"as":"","scd":null,"kp":[]},{"i":36422,"as":"","scd":null,"kp":[]},{"i":36423,"as":"","scd":null,"kp":[]},{"i":36424,"as":"","scd":null,"kp":[]},{"i":36425,"as":"传统大气氨排放监测主要依赖热红外光谱技术，受限于热对比度要求、卫星空间分辨率低及航空测量频率低。研究证明，短波红外成像光谱技术可以利用反射阳光信号克服这些限制，量化氨排放。作为概念验证，研究使用Tanager-1卫星数据成功量化了工业点源的氨排放羽流，为大量现有和未来的成像光谱仪加入氨观测系统提供了可能。","scd":null,"kp":["检测方法[氨气排放羽流量化]: 短波红外成像光谱法","检测局限性[传统热红外光谱仪]: 受热对比度要求限制、空间分辨率粗、测量频率低"]},{"i":36426,"as":"","scd":null,"kp":[]},{"i":36427,"as":"","scd":null,"kp":[]},{"i":36428,"as":"该研究提出了利用钻石中的氮空位（NV-）中心作为量子传感器来探测电子束的框架。自由电子束与固态量子系统之间的相干控制一直受限于极弱的耦合，实现该控制将促进结合两者的混合量子平台的发展。研究团队开发了基于Lindblad主方程的磁自旋电子-量子比特相互作用描述模型，为相干量子信息处理和纳米级传感提供了理论基础与技术路径。","scd":null,"kp":["耦合机制[自由电子束与固态量子系统]: 内在弱耦合","技术目标[自由电子与固态量子比特]: 实现相干控制以构建混合量子平台"]},{"i":36429,"as":"","scd":null,"kp":[]},{"i":36430,"as":"","scd":null,"kp":[]},{"i":36431,"as":"","scd":null,"kp":[]},{"i":36432,"as":"","scd":null,"kp":[]},{"i":36433,"as":"","scd":null,"kp":[]},{"i":36434,"as":"研究探讨了空间和情感信息如何在小鼠海马体CA3区的群体轴突活动中结合。在小鼠穿越线性轨道的实验中，中背侧和背侧轴突群体均维持了一个编码空间信息的稳健活动流形。在施加厌恶性的吹气刺激时，该流形发生形变以编码厌恶刺激的存在，但并未破坏原有的空间表征。这表明CA3区网络通过空间活动流形的变形来整合和传递厌恶信息。","scd":null,"kp":["刺激源[小鼠线性轨道导航]: 厌恶性吹气刺激","神经机制[海马体CA3轴突群]: 空间活动流形转化传递厌恶性信息"]},{"i":36435,"as":"为全面评估宿主对蚊媒病原体及载体的抗体反应，研究开发了一种包含超过25万个肽段的高度多重化噬菌体展示库VectorScan。该库的肽段源自多种节肢动物载体和媒介传播病原体。通过噬菌体免疫沉淀测序技术，对经实验和自然暴露于虫媒病毒、疟原虫和蚊子的血液样本进行了筛查。该平台成功实现了对肽段血清反应性的定量测量，为识别生物标志物和疫苗候选抗原提供了技术支持。","scd":null,"kp":["肽段容量[VectorScan高度多重化血清学检测]: 超过250,000个肽段","核心技术[媒介传播疾病抗体分析]: 噬菌体展示文库"]},{"i":36436,"as":"研究提出了一种结合微原纤化纤维素（MFC）和聚乙二醇（PEG）网络的软致动器，该设计有效抑制了结晶度和离子液体的聚集，提高了离子电导率并降低了界面电阻。在1伏特的工作电压下，该致动器实现了64.4千焦/立方米的破纪录能量密度，并在相同条件下的离子电活性聚合物中达到了1秒的最快响应时间。该材料同时具备可生物降解特性和极高的驱动性能，适用于下一代生物医学设备。","scd":null,"kp":["材料组分[软致动器]: 微原纤化纤维素、聚乙二醇网络和离子液体","性能提升[微原纤化纤维素基软致动器]: 抑制结晶度和离子液体聚集以增强离子电导率"]},{"i":36437,"as":"急性髓系白血病（AML）常伴随白血病肝脏浸润和化疗诱导的肝毒性。为动态模拟这些过程，研究构建了一个动态可灌注的人源血管化肝脏模块（DPHV-LM）。该体外模型由体外扩增的原代人肝细胞构建于可灌注系统中，能够重现药物代谢动态和疾病进展。此模型解决了传统生物人工肝脏系统难以维持临床相关性的挑战，为AML的疾病建模、药物发现和毒理学机制研究提供了临床相关的实验平台。","scd":null,"kp":["模型特征[DPHV-肝脏模块]: 血管化体外肝脏模型","应用场景[急性髓系白血病模型]: 重现白血病浸润和化疗引起的肝毒性并具转化效用"]},{"i":36438,"as":"研究发现脂质纳米颗粒中的可电离脂质可由可电离药物替代，以实现小干扰RNA（siRNA）的细胞内共递送。研究团队设计了小规模筛选试验评估药物对siRNA的复合能力，并结合机器学习模型与五个分子描述符成功构建了预测模型。siRNA的复合能力可通过药物的疏水性、芳香性及氮氧原子与芳香环的邻近度来预测。这一预测模型优化了基于离子化药物的纳米颗粒制剂设计。","scd":null,"kp":["预测模型[可电离药物纳米粒子共递送siRNA]: 基于药物疏水性定量预测siRNA络合","替代组分[脂质纳米粒子]: 使用可电离药物替代可电离脂质"]},{"i":36439,"as":"研究提出了一种名为SEED的可注射、无引线、无电池生物电子接口，专为周围神经调节设计。该设备可通过标准的14号针头进行经皮递送，利用65千赫兹的低频磁准静态谐振耦合技术，将波形生成和控制外部化，无需板载有源电子器件即可实现可编程神经调节。其螺旋-螺旋状电极几何结构在限制脱靶电场扩散的同时促进了纵向神经参与。台架和离体实验均证实了其刺激频率的精确可编程控制。","scd":null,"kp":["工作频率[SEED可注射无引线生物电子接口]: 65千赫兹","供电与耦合方式[经皮神经调控]: 无电池无线、磁准静态谐振电感耦合","递送方式[可注射电子器件]: 通过标准14号针头经皮递送"]},{"i":36440,"as":"急性应激可能引发创伤后应激障碍（PTSD）。研究证实，鼻内预处理催产素可通过前边缘皮层（PL）中表达的催产素受体（OxtR）持久且可逆地减弱恐惧学习。皮层中的生长抑素（SST）中间神经元表现出更高的Oxtr表达水平，恐惧条件反射和催产素的应用优先激活了PL中的OxtR+ SST中间神经元。预激活OxtR+ SST神经元可重现这种恐惧减弱效应，增强局部GABA能抑制，揭示了催产素预防PTSD的具体神经机制。","scd":null,"kp":["干预方式[预防创伤后应激障碍]: 鼻内催产素预处理","神经机制[前边缘皮层恐惧学习衰减]: 增强生长抑素中间神经元介导的局部GABA能抑制"]},{"i":36441,"as":"研究提出了一种基于单端多模光纤（MMF）和深度学习的软机器人形状感知方法。该极简反射式架构消除了对外部复杂解调单元和远端设备的依赖。通过将光纤内的混沌光斑场视为编码高维形状信息的数据流，可重构的神经解码器将单一物理通道转换为多功能的感知能力。该技术解决了软机器人在空间受限介入场景下连续变形捕获的难题，实现了高精度的本体感受。","scd":null,"kp":["感知方法[软体机器人形态感知]: 基于单端多模光纤与深度学习的形态感知","传感系统[空间受限介入场景]: 具有极简反射结构的内蕴光学集成"]},{"i":36442,"as":"研究通过优化的纳米压印光刻-刮涂技术，首次制备了基于Ti3C2Tx MXene的共形、透明且高性能的天线。所制备的MXene网格透明导电薄膜在高透光率（约89.1%）下实现了4.32欧姆/平方的超低方块电阻，并具备优异的柔韧性。该研究打破了柔性天线在共形、透明和电磁效率方面无法兼顾的“不可能三角”，为下一代物联网无线电子设备提供了理想的解决方案。","scd":null,"kp":["天线材料[下一代物联网无线电子]: Ti3C2Tx MXene","天线特性[柔性无线电子器件]: 共形、透明且电磁高效"]},{"i":36443,"as":"","scd":null,"kp":[]},{"i":36444,"as":"","scd":null,"kp":[]},{"i":36445,"as":"研究开发了一种集成了传感器内数值超维计算的柔性电子皮肤，用于实时压力场感知。该系统采用稀疏传感网络，通过设备内置的超维计算处理稀疏输入，在本地直接生成高分辨率压力场图。这种超维计算架构有效提升了设备内学习的效率，实现了无需外部计算资源或密集传感阵列的实时分析与精确的飞行状态识别，对无人系统的可靠状态评估具有重要意义。","scd":null,"kp":["电子皮肤[表面压力测量]: 具有传感器内数值超维度计算的稀疏传感网络","技术优势[高空间分辨率压力感知]: 实时且超高空间分辨率的压力场感知"]},{"i":36446,"as":"","scd":null,"kp":[]},{"i":36447,"as":"","scd":null,"kp":[]},{"i":36448,"as":"研究团队开发出一种由纤维素纳米晶体（CNCs）组成的超强透明光子水凝胶。该材料采用可编程的五阶段拉伸-暂停工艺，在不牺牲其固有手性的情况下实现了CNC结构域的精确排列，其纳米晶取向因子达到0.91。这一策略克服了传统柔性聚合物无法实现均匀排列和空间控制的难题，成功实现了源自结构的优异光学与机械功能。","scd":null,"kp":["材料类型[仿生光子水凝胶]: 超强、透明的纤维素纳米晶光子水凝胶","结构设计[仿生蜘蛛丝系统]: 均匀排列且空间可控的纳米晶域"]},{"i":36449,"as":"","scd":null,"kp":[]},{"i":36450,"as":"","scd":null,"kp":[]},{"i":36451,"as":"","scd":null,"kp":[]},{"i":36452,"as":"","scd":null,"kp":[]},{"i":36453,"as":"研究提出了KIST-Ocean，一个基于深度学习的全球三维海洋环流模型。该模型解决了传统方法在扩展预测时间尺度时的计算局限，具备强大的海洋模拟技能与计算效率。评估表明，KIST-Ocean能够真实再现大气强迫下的海洋动态响应过程，如开尔文波和罗斯贝波的传播，以及风应力旋度引发的垂直运动，有效模拟了复杂的海洋响应。","scd":null,"kp":["模型架构[全球海洋大气相互作用]: 基于深度学习的全球三维海洋环流模型(KIST-Ocean)","技术优势[次季节时间尺度预测]: 准确模拟大气强迫下的复杂海洋响应"]},{"i":36454,"as":"","scd":null,"kp":[]},{"i":36455,"as":"","scd":null,"kp":[]},{"i":36456,"as":"针对当前神经形态计算设备在带宽、能耗和可扩展性方面的瓶颈，研究团队开发了拓扑声学突触（TAS）。这是一种利用声波在多变量状态空间映射信息的神经形态器件。单个TAS即可生成并独立且并行地操控大量计算通道，利用非线性相互作用模拟出具有生物真实性的神经形态功能，为高维类脑计算提供了高效低耗的解决方案。","scd":null,"kp":["功耗[人脑高维计算]: 约20瓦","器件类型[高维类脑计算]: 拓扑声学突触器件"]},{"i":36457,"as":"","scd":null,"kp":[]},{"i":36458,"as":"","scd":null,"kp":[]},{"i":36459,"as":"非晶化工程通过在结晶光催化剂中引入可调的结构无序性，有效提升了光催化性能。这种结构无序导致的系统熵增加会产生“鸡尾酒效应”，重构催化剂的电子结构、调整光生载流子的弛豫动力学，并创造独特的局部活性位点微环境。文章总结了基于无定形光催化剂的合成方法、改性策略及其在光催化领域的最新应用进展。","scd":null,"kp":["工程策略[晶态光催化剂改性]: 非晶化工程引入可调结构无序度","催化机制[非晶化增强光催化]: 熵增引发“鸡尾酒效应”，重构电子结构并调控光生载流子弛豫动力学"]},{"i":36460,"as":"研究采用两种不同的限域调控晶体相工程策略，构建了首个用于植物蒸腾动态监测的半导体纤维系统。局部空间限域热重排优化了半导体纤维芯的结晶度，而纳米球限域则控制了钙钛矿纤维包覆层在湿度变化下的可逆相变。这种分布式传感织物有效解决了传统传感器破坏气孔边界层的问题，实现了植物微气候的稳定监测。","scd":null,"kp":["半导体纤维[晶体相工程]: 约束调控的晶体相工程构建的结构化半导体纤维系统","传感平台[植物蒸腾动力学监测]: 基于半导体纤维的分布式植物微气候映射织物平台"]},{"i":36461,"as":"为实现可持续氨合成，研究利用晶格工程构建了钴掺杂的纳米级零价铁（Co-nFe0）电极，用于电化学硝酸根还原（NO3−RR）。该电极整合了双电子驱动机制与自触发碱性微环境，克服了中性条件下反应动力学缓慢和选择性低的瓶颈。Co-nFe0电极的设计大幅提升了从硝酸盐高效转化为氨的电催化性能，为农业和能源领域的氨生产提供了低能耗新途径。","scd":null,"kp":["核心工艺[硝酸盐电还原选择性合成氨]: 晶格工程化双电子驱动电极","技术瓶颈[电化学硝酸盐还原反应]: 动力学缓慢且选择性低"]},{"i":36462,"as":"为解决混合卤化物宽禁带钙钛矿中的卤化物相分离难题，研究人员设计了一种分子限域结构。该结构利用成对的含碘有机配体结合相邻的FA+阳离子，并通过双功能二铵连接体相互连接。这种设计有效限制了FA+阳离子在表面和界面的动态运动，抑制了卤化物偏析，并显著增强了铅-卤键。这一方法大幅提升了宽禁带钙钛矿的稳定性，为高效串联太阳能电池的研发奠定基础。","scd":null,"kp":["材料设计[宽禁带钙钛矿防相分离]: 分子限域域结合双功能配体与含碘有机配体","应用场景[高效叠层光伏]: 卤化物稳定的宽禁带钙钛矿"]},{"i":36463,"as":"研究利用机器学习指导的预测模型，建立了精确的定量结构-性能关系，成功设计并合成了铁单原子催化剂（Fe-N5）。该催化剂集成了双催化平台，能够在肿瘤微环境特有的弱酸性和还原性生理限制下保持稳定的催化活性。这种具备微环境自适应能力的催化剂有效克服了传统化学动力学疗法的局限，实现了基于化学动力学与生物正交反应的高效精准癌症治疗。","scd":null,"kp":["[肿瘤微环境适应性化学动力学治疗]: 机器学习优化单原子催化剂以维持稳健性能"]},{"i":36464,"as":"为解决直流摩擦纳米发电机（DC-TENGs）中电荷收集不全和寄生放电的问题，受耗尽型场效应管启发，研究人员提出了准栅极增强型DC-TENG（QGED-TENG）。该装置通过背侧准栅极和多孔聚四氟乙烯薄膜调控静电击穿与电荷泄漏，有效抑制寄生放电。在无外部偏压的情况下，QGED-TENG实现了方向依赖的增强与耗尽模式，其增强模式的输出电荷量提升了1.41倍。","scd":null,"kp":["[直流摩擦纳米发电机]: 采用准栅极电极增强电荷收集并抑制寄生放电"]},{"i":36465,"as":"受细胞生物分子凝聚物启发，研究开发了基于带相反电荷单酶纳米凝胶（SENs）的凝聚体液滴系统。该凝聚体完全由带相反电荷的纳米凝胶自发相分离形成，在广泛的环境条件下均可作为酶级联催化的固定支架和功能单元。通过调整SENs的比例，可以创建特定的微环境，有效解决了传统平台酶分布不均、底物受限和化学计量失控等问题，大幅提升了生物催化效率。","scd":null,"kp":["[酶级联催化]: 基于带有相反电荷的单酶纳米凝胶形成液滴相分离以提升效率"]},{"i":36466,"as":"","scd":null,"kp":[]},{"i":36467,"as":"","scd":null,"kp":[]},{"i":36468,"as":"通过极化非弹性中子散射技术，研究团队首次在交变磁性材料碲化锰中观察到分裂磁振子带的手性现象。这一结果明确证实了交变磁体中存在可开关的手性磁振子，为交变磁性物理机制的研究及其在新型自旋电子学器件中的应用提供了直接证据。相关成果发表于《物理评论快报》。","scd":null,"kp":["[交变磁体MnTe]: 极化非弹性中子散射首次明确证实手性磁振子的存在"]},{"i":36469,"as":"研究利用自由空间相似重整化群（SRG）演化的算符和介质内SRG（IMSRG）方法，计算了两核子密度，深入探讨了短程关联（SRCs）中的三体效应。短程关联是连接低能与高能核物理的重要纽带。计算结果揭示了在核物理短程关联现象中，三个核子间的相互作用机制。该成果发表于《物理评论C》。","scd":null,"kp":[]},{"i":36470,"as":"针对现有算法在处理自束缚量子多体问题（如核物理与粒子物理）时仅能获取有限能级和结构信息的缺陷，研究人员引入并验证了一种新型量子计算算法。该算法旨在克服上述局限性，在量子计算机上实现从头算多费米子结构计算。","scd":null,"kp":["[量子计算机求解自束缚量子多体问题]: 提出并演示克服能级和结构信息限制的新型量子算法"]},{"i":36471,"as":"基于热强子气体模型，研究人员评估了衰变过程对净量子数涨落幅度及平衡函数积分的潜在影响。计算涵盖了质量最高达2.5 GeV的已知强子综合列表。该研究揭示了热力学模型中强子级联衰变与量子涨落之间的具体关联。","scd":null,"kp":[]},{"i":36472,"as":"研究提出了一种理论框架，用于计算在离散基中描述的三体共振的渐近性质和衰变动力学。该方法通过求解非齐次薛定谔方程并确定可归一化源，来求解不可归一化的共振态。该框架有助于精确分析复杂的三体共振衰变过程。","scd":null,"kp":[]},{"i":36473,"as":"研究通过小角质子散射实验测量了sd壳层原子核的电偶极强度。总光吸收截面数据对于理解原子核结构及天体物理应用至关重要，而现有重核数据主要依赖于光激发后中子发射的测量。该研究提供了一种补充和完善核结构数据的重要方法。","scd":null,"kp":[]},{"i":36474,"as":"研究在非磁性拓扑半金属TaIrTe4中发现了室温下的本征非线性平面霍尔效应。该研究揭示了面内磁场如何通过轨道机制产生Berry曲率极化偶极子。这一发现证实了TaIrTe4在室温下的奇特电子输运特性及轨道物理机制。","scd":null,"kp":[]},{"i":36475,"as":"研究人员显著提高了悬浮纳米粒子运动测量的灵敏度。该纳米力学传感器能够分辨低于其零点涨落的脉冲力。这一超高灵敏度测量技术为暗物质搜寻等基础物理探测提供了新的技术手段。","scd":null,"kp":["[悬浮纳米粒子纳米力学传感器]: 实现分辨低于其零点涨落的脉冲力测量"]},{"i":36476,"as":"研究采用朗之万介质输运结合顺序碎化模型，分析了相对论重离子碰撞中夸克胶子等离子体的粲夸克强子化过程。由于D_s介子形成较早，该机制为重味产生提供了探测途径。研究详细阐述了高能核碰撞中D介子的顺序强子化机制。","scd":null,"kp":[]},{"i":36477,"as":"LHCb合作组在味改变中性流衰变过程（B0→K0_S μ+ μ−）中首次测量了依赖于时间的CP破坏现象。b夸克衰变为奇异夸克并产生一对轻子的过程，首次揭示了时间依赖性CP破坏的迹象。该实验结果为粒子物理标准模型的精确检验提供了关键数据。","scd":null,"kp":[]},{"i":36478,"as":"研究通过相干控制实现了高效的单量子元量子门集。量子元通过扩展希尔伯特空间提升了量子计算潜力，但实现高保真度、快速的单量子元门面临固有物理限制。该工作克服了量子平台中的内在约束，成功合成并实现了单量子元门的高效操控。","scd":null,"kp":["[单量子三能级逻辑门]: 通过相干控制实现高保真度与快速的门合成"]},{"i":36479,"as":"银河系中心超出的辐射源可能源自湮灭的暗物质，但现有分析表明发射结构中存在暗弱点源。受技术限制，以往的辐射分析纯粹集中在空间维度。该研究突破了空间分析的局限，进一步探究了银河系中心 excess 现象相关辐射源的能量分布特征。","scd":null,"kp":[]},{"i":36480,"as":"Belle合作组利用正负电子对撞数据，在包含缺失能量的B介子衰变中搜寻了微弱相互作用粒子。研究重点寻找在B0→D0bar X_inv和B±→h X_inv衰变中产生的不可见隐扇区粒子X_inv（其中h为π±、K±等强子）。该实验为探索超出标准模型的新物理提供了直接搜寻结果。","scd":null,"kp":[]},{"i":36481,"as":"詹姆斯·韦伯空间望远镜发现了一批致密的高红移源——小红点（LRDs），其内部可能蕴藏着质量远超恒星的超大质量黑洞，这挑战了标准的早期宇宙黑洞演化模型。研究提出了基于原初黑洞的演化新路径，解释了这类特殊致密天体及其超大质量黑洞的异常质量比例。","scd":null,"kp":[]},{"i":36482,"as":"","scd":null,"kp":[]},{"i":36483,"as":"研究合成了一对将罗丹明发光基团引入联萘手性支架的手性诱导剂（R1/S1），并将其掺杂构建了胆甾相发光液晶（N*LLC）。通过增加非手性萘酰亚胺衍生物（NIA）的浓度，实现了发光波长从红到黄再到绿的顺序蓝移。该策略有效调控了圆偏振发光（CPL）的波长并改善了不对称因子。","scd":null,"kp":["发光不对称因子[圆偏振发光材料]: 具备可调波长与高发光不对称因子特征"]},{"i":36484,"as":"激发态反芳香性（ESAA）的缓解是光致芳香分子行为的重要驱动力。研究通过精细调控一系列轮烯的电子特性来最小化其ESAA，发现激发态质子转移（ESPT）使分子转化为非芳香性互变异构体。由于近简并性，羟基苯并环庚三烯表现出极弱的反芳香性动力学特征。","scd":null,"kp":["[非苯芳烃激发态反芳香性]: 通过微调轮烯电子特性最大程度减小驱动力以缓解激发态反芳香性"]},{"i":36485,"as":"手性烯酮是重要的生物活性分子合成中间体。研究基于源自恶臭假单胞菌的老黄酶XenA，构建了具有反向对映选择性的立体互补生物催化体系。尽管天然XenA主要催化电子缺陷烯烃的还原且脱氢活性微弱，但通过蛋白质工程改造，成功将其催化功能重定向为脱氢反应，最终获得了能容纳目标底物的变体。","scd":null,"kp":["[不对称去饱和化生物催化]: 基于老黄酶XenA构建具有反向对映选择性的互补生物催化体系"]},{"i":36486,"as":"研究开发了一种无催化剂、一锅法水热氧化策略，将废聚乙烯高效升级回收为高附加值的氧化聚乙烯蜡（OPEW）。在160°C和1.5 MPa氧气的优化条件下，0.5小时内即可实现低密度聚乙烯（LDPE）向OPEW的转化。该过程OPEW/PE质量比达103.3%，碳产率高达99.8%，且产物具有可调的酸值。","scd":null,"kp":["塑料废物质量占比[聚乙烯废弃物]: 36%","[聚乙烯废弃物]: 无催化剂的一锅法水热氧化升级回收策略","[聚乙烯废弃物]: 转化为高价值氧化聚乙烯蜡"]},{"i":36487,"as":"富锂层状氧化物的高容量源于阳离子和阴离子氧化还原反应，但阴离子氧化还原易导致O-O二聚体的形成，引发释氧和过渡金属迁移，造成结构退化。研究设计了一种表面重构层，其中镍离子占据Li2MnO3相的4h Wyckoff位点。这种表面特定的镍占据促使电子耗尽的O轨道平行排列，有效稳定了阴离子氧化还原过程。","scd":null,"kp":["容量特性[富锂锰基层状氧化物]: 高容量","[富锂锰基层状氧化物]: 具有阳离子和阴离子双重氧化还原反应","[阴离子氧化还原过程]: 诱导O-O二聚体形成并引发氧气释放和过渡金属迁移","[富锂锰基层状氧化物]: 通过表面重构实现阴离子氧化还原的轨道稳定"]},{"i":36488,"as":"研究利用胰高血糖素样肽-1受体（GLP-1R）作为β细胞特异性进入途径，通过色氨酸介导的多组分Petasis反应（TMPR），首次构建了多组分钉合的GLP-1类似物。这种模块化钉合策略为后期缀合提供了化学正交把手，显著增强了多肽的α螺旋结构，实现了受体引导的PROTAC靶向递送。","scd":null,"kp":[]},{"i":36489,"as":"针对碱性析氧反应（OER）动力学迟缓以及工业级大电流密度下催化剂极化失稳的难题，研究在超薄Fe2O3纳米片的八面体空隙中进行了原子碳掺杂（C-Fe2O3 UNSs）。该设计构建了Fe_oh III-O-Fe_oh III协同作用，成功打破了活性和稳定性之间的权衡，展现出优异的非贵金属工业级水电解催化性能。","scd":null,"kp":[]},{"i":36490,"as":"研究报道了一种含有B-B键的双（亚氨基硼烷）化合物，分子式为Ar*-N≡B-B≡N-Ar*（其中Ar*为特定位阻芳基）。该化合物是一种罕见的sp-sp杂化二硼类物质，构成了丁二炔的BN等电子类似体。化合物展现出特征的单向和双向反应活性，实现了分子结构的非对称化去对称过程。","scd":null,"kp":["分子结构特征[丁二炔的BN类似物]: 具有B─B键的sp-sp连二硼(2)物种","[丁二炔的BN类似物]: Ar*─N≡B─B≡N─Ar* 结构","[丁二炔的BN类似物]: 可以发生去对称化反应"]},{"i":36491,"as":"针对高能量密度钙金属电池中动力学迟缓和界面不稳定的问题，提出一种基于混合钙钠有机硼酸盐电解质的不对称溶剂化设计策略。通过引入单价共阳离子和强配位阴离子构建不对称溶剂化结构，使电化学活性的钙离子处于偏心位置，从而同步调节溶剂化化学过程和界面形成，成功实现了可逆的钙金属负极。","scd":null,"kp":["储能特性[钙金属电池]: 高能量密度","[钙金属电池]: 面临动力学迟缓和电解质-金属界面不稳定的挑战","[混合Ca2+/Na+有机硼酸盐电解质]: 基于不对称溶剂化效应的电解质设计策略","[混合Ca2+/Na+有机硼酸盐电解质]: 实现可逆的钙金属负极"]},{"i":36492,"as":"研究发现通过“自适应空腔”效应可以改变纳米碳笼在晶体状态下的手性。利用不同的结晶溶剂或引入 coronene 客体分子，能够调控纳米碳笼的构象，从非手性结构单元构建出分层手性超结构。生成的手性晶体表现出二次谐波生成活性和高达 120 pm/V 的强压电响应。","scd":null,"kp":["手性调节[纳米碳笼晶态]: 通过“自适应空腔”效应改变","[纳米碳笼]: 利用不同结晶溶剂或引入晕苯客体分子调节构象"]},{"i":36493,"as":"针对从乙炔、二氧化碳和乙烯三元混合物中一步纯化乙烯这一工业难题，提出一种“二合一”阴离子工程策略。通过用 ZrF6 2- 替代 SiF6 2-，该策略克服了传统配体工程难以同时提升吸附容量和分离选择性的局限，实现了对乙烯混合气体的高效分离纯化。","scd":null,"kp":["阴离子工程[三元混合物一步纯化乙烯]: “二合一”阴离子工程策略","[三元混合物一步纯化乙烯]: 解决C2H2/CO2/C2H4混合物中一步纯化C2H4的工业挑战"]},{"i":36494,"as":"为了解决片段药物发现中难以准确量化片段弱结合亲和力的难题，提出一种名为 CSAKD 的全新检测方法。该方法利用 19F NMR 弛豫技术中的化学位移各向异性（CSA），能够直接测定片段的绝对亲和力，有效排除了传统检测中的干扰因素，为结构导向的药物设计提供了精准的生物物理测量手段。","scd":null,"kp":["配体亲和力测定[19F NMR化学位移各向异性]: 确定绝对配体亲和力","[基于片段的药物发现]: 与结构指导的药物设计和生物物理亲和力测量集成时非常有效"]},{"i":36495,"as":"通过扫描隧道显微镜裂结技术测量了包含反芳族 s-茚烯和芳族苯并二噻吩（BDT）核心的分子线，验证了反芳族核心对电导率的显著增强作用。实验结果表明，在对角锚定系统中，具有12个π电子的反芳族茚烯衍生物的单分子电导率比其对应的芳族化合物高出约10倍，证实了反芳族特性可大幅提升分子电导。","scd":null,"kp":["导电性增强[s-引达烯分子桥]: 反芳香性驱动的单分子电导增强","核心结构[s-引达烯分子桥]: 12 π-电子反芳香族核心","对照分子[苯并二噻吩]: 14 π-电子芳香族核心"]},{"i":36496,"as":"为提升质子交换膜燃料电池厚阴极催化剂层的传质效率，设计出一种由吡咯氮基团功能化的碳基纳米陷阱结构。该结构重组了铂-碳-离聚物界面，限制了铂纳米颗粒并形成连续的氧、质子和电子通路，显著提高了三相边界密度。厚度为 15.5 µm 的优化电极实现了峰值功率密度的显著提升。","scd":null,"kp":["纳米陷阱结构[质子交换膜燃料电池阴极催化剂层]: 具有吡咯-N官能团的碳基结构","[质子交换膜燃料电池阴极催化剂层]: 重组Pt-碳-离聚物界面以增强局部氧气供应","[碳基纳米陷阱]: 同时限制Pt纳米颗粒和离聚物以缓解界面传输限制"]},{"i":36497,"as":"为了解决电化学二氧化碳还原反应中气-电解质-电极三相界面处传质缓慢和中间体吸附不平衡的问题，提出一种双界面去耦传质策略。通过对聚二甲基硅氧烷（PDMS）修饰的铜基MOF电极进行原位电化学活化，构建了亲水/疏水两相结构，有效解耦了质量和电荷的传递过程，显著提升了多碳产物的生成效率。","scd":null,"kp":["核心反应界面[电化学CO2还原反应]: 气-电解质-电极三相界面","[电化学CO2还原反应]: 通过双界面工程实现解耦促进的传质与电荷转移","[电化学CO2还原反应]: 解决三相界面局部微环境中迟缓的传质和不平衡的中间体吸附"]},{"i":36498,"as":"针对锂离子电池首次充电时的不可逆容量损失问题，引入了一种在酯类电解液中具有高溶解度的 K3P7 作为多功能电解液添加剂。该添加剂通过 P73- 的氧化反应提供极高的容量补偿效果，弥补了传统预锂化剂比容量低、空气稳定性差等缺陷，有效提升了多种商用锂离子电池的可逆容量，并实现了界面的有效调控。","scd":null,"kp":["理论比容量[传统预锂化添加剂]: 300–1000 mAh g−1","补锂剂[补锂与界面调控]: K3P7"]},{"i":36499,"as":"针对高镍层状正极材料中高镍利用导致的体相机械失效和界面化学不稳定问题，提出一种基于镁/铌（Mg/Nb）共掺杂的局部晶格调控策略。该策略从表面到体相构建了化学和机械双重坚固的 LiNi0.95Co0.03Mn0.02O2 正极。表面重构的超薄无序岩盐相有效增强了材料的结构稳定性，提升了电池的整体性能。","scd":null,"kp":["[超高压镍正极]: 遭遇严重的体相机械失效与界面化学不稳定性阻碍","改性策略[局部晶格调控]: Mg/Nb共掺杂构建化学与机械协同稳定机制"]},{"i":36500,"as":"研发出一种基于聚电解质构象的纳米流体忆阻器（PCM）。该器件利用氧化石墨烯纳米通道内聚电解质在电场驱动下的可逆构象转变，实现了类似生物突触的离子动力学。器件具备模拟电导调节、可调开关阈值以及超过160的开关比，展现出长时程增强与抑制、多级记忆保留等丰富的突触功能和逻辑计算能力。","scd":null,"kp":["工作机制[受生物启发的纳米流体忆容器]: 电场驱动的聚电解质受限可逆构象转变","[单水相平台]: 集成突触可塑性、神经形态学习与状态离子逻辑运算"]},{"i":36501,"as":"提出一种通过调控钙钛矿B位容忍度来诱导晶格拉伸应变的策略，降低了纳米颗粒的溶出能垒，使三元纳米颗粒的溶出量增加了2.3倍，并伴生丰富的氧空位。析出的含钌纳米颗粒显著促进了甲烷的吸附与活化，同时氧空位捕获了H2，大幅提升了直接甲烷燃料电池的催化活性和抗积碳稳定性。","scd":null,"kp":["[直接甲烷燃料电池]: 析出动力学迟缓限制表面纳米颗粒形成，导致积碳环境下活性降低","改性策略[钙钛矿原位析出]: 调节B位公差因子诱导晶格拉伸应变以降低能垒"]},{"i":36502,"as":"开发出一种新型的光催化级联反应方法，可在同一反应体系中实现 α,β-不饱和亚胺的一锅法氢化、羧化和差向异构化。该方法通过光驱动的差向异构化过程，成功实现了具有手性碳原子标记的 [12C, 13C] β2,3-氨基酸的非对映收敛性合成，有效解决了 C2,C3-双取代 β2,3-氨基酸立体选择性合成的难题。","scd":null,"kp":["[β2,3-氨基酸]: 光驱动差向异构化实现非对映收敛合成"]},{"i":36503,"as":"开发了一种铜催化磺胺类化合物的对映选择性自由基氟烷基化反应。通过连续的立体识别与手性转移策略，有效控制了高活性的 α-氟烷基自由基，快速合成了 S-手性 α-氟烷基亚砜亚胺。结合后续转化反应，构建了合成 S-立体异构 α-氟烷基 S(IV/VI) 化合物的通用平台，克服了传统拆分法效率低下的缺陷。","scd":null,"kp":["合成方法[S-立体异构的α-氟烷基S(IV/VI)化合物]: 铜催化对映选择性自由基C-S交叉偶联反应"]},{"i":36504,"as":"研究发现在垂直对齐的氮化硼纳米管阵列构成的膜结构中，可以实现异常超快且具有高选择性的锂离子传输。这种纳米尺度的通道结构为高效离子筛分和先进的电池/超级电容器隔膜材料提供了全新的技术途径。","scd":null,"kp":["传输特性[垂直排列的氮化硼纳米管膜]: 异常超快且高选择性的锂离子传输"]},{"i":36505,"as":"通过定向凝固技术将高熵稀土铝酸盐（Gd0.25Eu0.25Nd0.25Sm0.25AlO3）引入氧化铝基体中，制备出双相共晶陶瓷。该陶瓷具有单晶氧化铝与双晶高熵稀土铝酸盐互锁的独特结构，形成了约 57.5 nm 的纳米相干晶界和半相干相界。这种从原子晶格畸变到纳米相干界面的级联强化机制，使其硬度与韧性超越了所有已报道的二元氧化铝基材料。","scd":null,"kp":["材料组成[高熵稀土铝酸盐]: REAlO3 (RE = Gd0.25Eu0.25Nd0.25Sm0.25)","[双相共晶陶瓷]: 引入高熵稀土铝酸盐并通过定向凝固形成单晶Al2O3与双晶高熵REAlO3纳米相干互锁结构","[力学性能]: 克服脆性限制，有效提升硬度与韧性"]},{"i":36506,"as":"针对剥离的铁基超导薄片中观察到的配对密度调制现象，提出一种基于向列态超导的物理模型。在破坏晶胞内对称性的系统中，向列态超导进一步打破了四重旋转对称性，在费米面上形成子晶格纹理。这导致在两个不等价的铁子晶格上出现明显的超导间隙最大值和最小值，且仍保持零动量配对状态。","scd":null,"kp":["物理现象[具有胞内对称性破缺的铁基超导体薄片]: 超导能隙随晶格周期性强振荡（配对密度调制）","理论模型[配对密度调制]: 向列超导性破缺四重旋转对称性，在费米面上形成亚晶格纹理"]},{"i":36507,"as":"提出一种无故障矩阵表示方法，以解决基于忆阻器的模拟存内计算硬件易受器件故障和变化影响的问题。该方法将任意目标矩阵分解为两个可编程的子矩阵，通过间接自适应表示在数学层面上避开故障器件并消除差分对。该系统提升了计算密度，并在存在硬件缺陷时实现了优异的余弦相似度计算精度。","scd":null,"kp":["计算机制[忆容器模拟存内计算]: 将任意目标矩阵分解为乘积的无故障矩阵表示法，克服硬件缺陷与变化导致的精度和可靠性问题"]},{"i":36508,"as":"研究鉴定出 GbNAC072C 是海岛棉皮分率的正调节因子，它通过直接激活 GbHOX3 基因的转录促进纤维细胞突起。GbNAC072C 的活性受 GbDEAH12G 蛋白抑制，且这种抑制强度具有单倍型依赖性。与 GbDEAH12G 相比，GbDEAH12C 变体对 GbNAC072C 的亲和力更低，解除了对转录级联的抑制，从而赋予棉花更高的皮分率。","scd":null,"kp":["转录调控因子[海岛棉 lint percentage]: GbNAC072C (正向调控，直接激活GbHOX3转录促进纤维细胞突起)","蛋白互作机制[GbNAC072C调控轴]: 被GbDEAH12G抑制，且互作强度依赖于单倍型 (GbDEAH12G对GbNAC072C的亲和力高于GbDEAH12C)"]},{"i":36509,"as":"通过将线性碳片段从一价金转移至零价金电极上，成功制备出无封端基团、包含最多16个碳原子的稳定金-碳-金器件。利用扫描隧道显微镜裂结技术对这种线性碳链的电荷传输特性进行测量，结果表明较短的碳链表现出类似寡炔的特性，其电导率随链长增加呈衰减趋势，直接表征了碳链的导电机制。","scd":null,"kp":["[线性碳链稳定器件制备]: 利用金属转移反应将线性碳片段从Au(I)物种转移到Au(0)电极，构建出稳定的Au|CC…CC|Au器件"]},{"i":36510,"as":"针对不对称吡唑的选择性 N-芳基化这一挑战，开发出一种利用铜催化和芳炔实现位点可切换芳基化的方法。在温和条件下，通过精确调控铜与吡唑的配位模式，能够选择性地将芳基化反应引导至吡唑的两个相邻氮原子中的任意一个。机理研究揭示了空间位阻和电子效应对区域选择性的控制作用，为药物发现提供了互补的结构修饰途径。","scd":null,"kp":["[不对称吡唑选择性N-芳基化]: 采用铜催化结合芳烃，解决了传统交叉偶联中区域选择性受限的挑战，实现位点选择性修饰"]},{"i":36511,"as":"准确的光伏功率预测对电网稳定性至关重要。研究提出了一种基于Transformer的Cross-Unet架构，通过多尺度时间编码、通道注意力机制和分层交叉注意力解码，将历史发电数据与天气预报深度融合。研究强调了在同时具备天气预测和历史数据时，完整的编码器-解码器架构和通道依赖性建模的重要性。该模型已在四个公用事业规模电厂的开源数据集上进行了评估。","scd":null,"kp":["[深度学习光伏功率预测]: 证实了完整的编码器-解码器架构和通道依赖性建模在融合历史数据与天气预报中的重要性"]},{"i":36512,"as":"纤维电子技术代表着电子领域的重大范式转变，它将一维结构赋予主动电子功能，同时保持传统纤维的柔韧性。该技术已从简单的导电纱线演变为多功能纤维器件。其核心进展依赖于具备优异电学、机械和热学性能的功能纤维材料设计，可用于制造电池、太阳能电池、发光显示器和神经形态计算器件，使无源基底转变为集供电、传感、计算和通信于一体的智能系统。","scd":null,"kp":["[纤维电子学技术演进]: 从简单导电纱线发展为兼具供能、传感、计算和通信能力的多功能主动智能纤维系统"]},{"i":36513,"as":"全球大宗材料生产的工业排放持续上升。现有的材料减排策略主要集中于供应端的技术替代，如碳捕集与封存、氢能及新生产工艺，但这些方法受限于部署速率和稀缺的资源。研究指出，仅靠供应端创新无法实现大宗材料的快速脱碳，需求端创新（即改变材料的设计、使用、评估和管理方式）必须被优先考虑。研究利用资源约束模型进一步阐述了这一观点。","scd":null,"kp":["[大宗材料脱碳战略]: 仅依靠供应侧技术替代受限，需将需求侧创新作为优先事项以实现脱碳"]},{"i":36514,"as":"两个研究团队成功研发出“激光相位板”系统。这项创新技术旨在帮助冷冻电子显微镜用户生成高质量的各种蛋白质结构。这一成果解决了长期以来的技术难题，将大幅提升冷冻电镜在解析蛋白质结构时的图像质量。","scd":null,"kp":["[冷冻电镜蛋白质结构成像]: 开发“激光相位板”系统以提升广谱蛋白质结构的高质量图像解析能力"]},{"i":36515,"as":"一项全新的基准测试被用于评估人工智能在解答未见过的数学问题时的能力。测试结果表明，当前的AI系统在处理高难度的数学问题时，依然落后于顶尖的人类专家水平。","scd":null,"kp":[]},{"i":36516,"as":"视频博主“Geng同学”公开发布指控，指出《自然》期刊上的多篇论文存在数据操纵问题。这些在网络上迅速发酵的指控引发了学术界的激烈讨论，并促使相关机构迅速启动了对涉事资深学者的学术不端调查。","scd":null,"kp":[]},{"i":36517,"as":"教皇的通谕超越了单纯的宗教文件范畴，深刻诊断了当前人工智能治理领域的失败。作为为梵蒂冈和联合国提供AI建议的专家，作者强调科学界应当高度重视并吸取这一关于AI治理失效的诊断信息。","scd":null,"kp":[]},{"i":36518,"as":"研究提出了一种集成微梳光电混沌引擎（iMOCE），以突破传统非线性电路的速度瓶颈。该引擎通过光电子非线性腔体驱动混沌微梳，生成大规模并行混沌信号，每个通道的6-dB带宽达到25 GHz，较以往方法提升两个数量级。系统实现了32.768 Tbps的总随机比特生成率，加速了四项代表性机器学习任务，其性能显著优于MCU/GPU基线方案。","scd":null,"kp":["[光电混沌加速机器学习]: 研制出集成微梳光电混沌引擎(iMOCE)，利用混沌微梳驱动光电非线性腔，解决传统非线性电路的速度瓶颈并实现大规模并行"]},{"i":36519,"as":"研究利用飞秒和纳秒瞬态吸收光谱，揭示了可见光驱动的电子供体-受体（EDA）光催化过程中的激发态动力学机制。以醛的不对称α-烷基化为原型，实时观测成功解析出单重态电荷转移、三重态电荷转移及自由基对。研究发现存在两条平行的自由基生成路径以最大化反应效率，且溴离子的快速离去有效抑制了无用的电荷复合。","scd":null,"kp":["检测技术[EDA光催化激发态动力学]: 飞秒和纳秒瞬态吸收光谱","[EDA系统原型]: 不对称醛α-烷基化","[实时动力学映射]: 成功解析单重态电荷转移态(¹CT)"]},{"i":36520,"as":"为解决大段骨缺损修复中血管生成、神经发生和骨生成难以协调的问题，研究开发了一种PTPG功能支架，可同时递送多肽和Talin1质粒。该支架通过双向激活整合素β1（ITGB1）实现神经血管化骨再生：多肽触发“由外向内”信号，Talin1质粒介导“由内向外”激活。PTPG支架能协同增强细胞增殖、迁移和分泌，且这些作用在ITGB1沉默后消失。","scd":null,"kp":["功能支架[成分]: 肽/Talin1质粒/PLA-HA/GelMA (PTPG)","[递送物质]: 同时递送多肽和Talin1质粒","[神经血管化骨再生机制]: 双向激活整合素β1 (ITGB1)","多肽序列[功能域]: REDV–IKVAV"]},{"i":36521,"as":"三链形成寡核苷酸（TFOs）通过Hoogsteen碱基配对实现双链DNA的序列特异性识别，但天然碱基的局限性限制了其靶向范围。研究利用人工扩展遗传信息系统（AEGIS）的碱基扩展了三链识别空间。通过系统评估120种碱基三联体组合，鉴定出至少12种模块化三联体。它们可互换组合，以纳摩尔级的亲和力靶向包含标准、受损或合成碱基对的双链DNA。","scd":null,"kp":["[识别技术]: 三链形成寡核苷酸 (TFOs) 结合扩展遗传字母","[识别机制]: Hoogsteen碱基配对实现可编程大沟槽识别","[技术突破]: 使用扩展核苷碱基突破天然碱基对目标序列的严格限制"]},{"i":36522,"as":"研究确定Sialin2是一种硝酸盐传感器，能将饮食中的硝酸盐转化为空间局限的产热程序。Sialin2定位于线粒体和内质网，通过增强两者的接触并动员IP3R1-VDAC1-MCU1通路，促进线粒体钙离子摄取。同时，Sialin2与溶酶体酸性脂肪酶（LIPA）等关联，将内质网-线粒体钙信号传导与脂肪酸代谢耦合，从而驱动白色脂肪褐变以恢复能量平衡。","scd":null,"kp":["Sialin2[功能]: 硝酸盐传感器","[产热机制]: 耦合内质网-线粒体Ca2+转移与脂肪酸转入线粒体氧化","[技术结论]: Nitrate-Sialin2轴驱动白色脂肪褐变以恢复能量平衡"]},{"i":36523,"as":"研究结合恒化器生理学、多组学分析和代谢工程，揭示了厌氧酿酒酵母在碳、氮、磷限制下的生长机制。酵母在三种限制下均保持约14 mmol/gDW/h的最大葡萄糖摄取率。碳和磷限制的最大生长率受限于ATP不足，氮限制则受限于氨酰-tRNA合成酶的匮乏。在压力下，酵母将蛋白质组资源重新分配至合成代谢，并通过特定的磷酸化网络补偿翻译压力。","scd":null,"kp":["最大葡萄糖摄取率[严格厌氧条件下的酵母]: ~14 mmol/gDW/h","[研究方法]: 整合恒化器生理学、多组学分析和靶向代谢工程"]},{"i":36524,"as":"细菌鞭毛是驱动其运动的旋转分子机器。研究利用单金纳米棒的偏振显微镜，以250 kHz的采样率观测了缺乏扭矩产生单元的大肠杆菌鞭毛的被动旋转扩散现象。具有26重对称性的LP环/杆鞭毛轴承在跨越能垒时表现出跨越四个数量级的非泊松动力学。在亚毫秒时间尺度上，观察到通常与无序系统相关的异常超慢扩散现象。","scd":null,"kp":["观测对象[缺乏扭矩产生单元的大肠杆菌鞭毛]: 六个独立鞭毛的被动旋转扩散","检测技术[单鞭毛旋转观测]: 偏振显微镜（结合金纳米棒标记）"]},{"i":36525,"as":"多糖疫苗的效力因抗体反应弱和缺乏合适的佐剂而受限。由于TLR4激动剂的作用机制在灵长类中不保守，研究评估了TLR1/2激动剂Pam3CSK4作为交叉物种佐剂的效果。Pam3CSK4与B细胞受体交联产生协同作用，增强小鼠和人类B细胞的抗体分泌。在角鲨烯乳液中加入Pam3CSK4可显著提高免疫健全鼠和人源化小鼠中肺炎球菌多糖特异性抗体的保护性反应。","scd":null,"kp":[]},{"i":36526,"as":"研究利用小鼠和人类模型揭示了肝脏发育和再生中细胞增殖、极化和成熟的协调机制。肝极性和胆小管（BC）形成始于成肝细胞分裂期，且BC延伸与定向细胞分裂相关。这一过程依赖PAR3和YAP对ERK/MAPK信号的调节。PAR3形成蛋白复合物，将IQGAP1定位于紧密连接，从而限制基底外侧膜的ERK/MAPK激活，这对于肝脏功能至关重要。","scd":null,"kp":[]},{"i":36527,"as":"单纯的基因组学无法全面解析表型变异。研究提出将表型组学与环境组学相结合的框架，通过协调数据收集与整合来推进精准植物育种。该框架利用卫星、无人机、地面车辆和室内受控设施，结合AI辅助的检测和建模技术，实现高通量的表型与环境数据同步采集与交互分析，从而更好地解析基因组效应并提升遗传增益。","scd":null,"kp":["[育种框架]: 表型组-环境组(PE)串扰","[技术目的]: 协调开发以解析环境因素对基因组效应的影响并提高遗传增益"]},{"i":36528,"as":"研究记录了基底外侧杏仁核（BLA）在情感学习范式中的多巴胺体内信号。结果表明，BLA多巴胺信号随刺激的情感强度而变化，但不随价值或联想强度增强；奖励预测线索引发的BLA多巴胺信号会随训练逐渐减弱。在复杂的学习环境中，线索引发的BLA多巴胺会重新标定，以报告相对情感显著性的水平，其中威胁和安全线索引发了更大且持续的多巴胺信号。","scd":null,"kp":[]},{"i":36529,"as":"社交凝视可分解为凝视内容、社交状态和凝视时长三个基元。通过对猕猴进行神经记录，研究发现大脑中的社交凝视受组合编码控制，凝视交流由这些基元的组合决定。基底外侧杏仁核和前扣带回皮层以抽象且正交的格式表征内容和状态，而背内侧前额叶和眶额叶皮层的泛化能力有限，证明了行为的组合性。","scd":null,"kp":[]},{"i":36530,"as":"核糖体蛋白L11不仅是蛋白质合成的核心，还作为全局变构调节剂协调核糖体柄与肽基转移酶中心之间的通信。分子动力学模拟显示，缺失L11会破坏涉及RelA和Obg的长距离偶联，并使促休眠因子位点僵化，从而改变应激下的核糖体休眠动力学。研究人员构建了缺失L11的枯草芽孢杆菌突变体，以进一步验证这些计算预测的生理学影响。","scd":null,"kp":["核糖体蛋白L11[功能]: 协调核糖体茎与肽酰转移酶中心通讯的全局变构调节剂","[研究方法]: 长时间尺度分子动力学模拟（野生型与ΔL11核糖体）"]},{"i":36531,"as":"研究提出一种高拉伸性三通道纤维传感器，通过集成镓基液态金属构建同心和双螺旋微通道。该双应变传感器能够解耦包含拉伸和扭转形变的复合运动。螺旋结构促进了聚合物链的三维取向，从而有效提升了机械耐久性和线性响应范围，解决了纤维基应变传感器在复杂变形下同时满足上述性能的挑战。","scd":null,"kp":["纤维结构特征[可拉伸应变传感器]: 同心与双螺旋结构的三通道纤维","[技术优势]: 实现强机械耐久性、宽线性响应范围以及复合运动解耦"]},{"i":36532,"as":"研究利用光学陷阱作为测量脉冲，通过监测原子损耗，直接观测到单原子实空间运动中的量子芝诺效应（QZE）。研究发现，测量对原子的作用由投影测量和随后的周期性幺正演化组成，提供了不同时间尺度下测量反作用的物理图像。实验进一步证实了测量脉冲的频率、强度和空间位置不仅能抑制原子的空间扩散，还揭示了其对原子运动的具体影响。","scd":null,"kp":["[实验现象]: 直接观测到真实空间中单原子运动的量子芝诺效应(QZE)","测量方法[单原子真实空间运动]: 光阱（作为测量脉冲）并通过监测原子损耗"]},{"i":36533,"as":"研究提出一种无夹层的单片有机/PbS光电探测器，实现了可见光和短波红外双模运行，具有低噪声和低串扰特性。通过在有机层中诱导垂直和横向相分离，优化了电荷载流子动力学，无需辅助中间层即可获得高比探测率。这种简单的器件结构能够高精度地检测微弱光信号，满足非侵入性诊断和光通信等应用对高保真微光检测的需求。","scd":null,"kp":["[光电探测器]: 无层间结单片式有机/PbS量子点自滤光双模光电探测器，实现可见光和短波红外（SWIR）选择性成像"]},{"i":36534,"as":"研究通过在硅波导上配置硒化铟p-i-n同质结，构建了片上二次非线性光电探测器（QNPD）。波导中传输的通信波段光与硒化铟发生倏逝场耦合，通过硒化铟的二次谐波生成（SHG）上转换为可见光，随后被吸收并在p-i-n结内建电场作用下产生光电流。这一系列连续过程成功在片上光电探测器中引入了确定的非线性光响应，助力传感器内计算和光电混合等复杂功能。","scd":null,"kp":[]},{"i":36535,"as":"研究实现了一种无需保护氨基的氨基甲基膦酸酯直接对α,β-不饱和酮进行对映选择性α-C共轭加成的方法。该策略采用有机-有机双重活化机制，利用吡哆醛将氨基甲基膦酸酯活化为高活性的碳负离子，有效克服了α-C-H酸度低、膦酸酯基团空间位阻大以及副反应干扰等合成挑战，成功制备出具有生物活性的手性膦酸基-1-吡咯啉类化合物。","scd":null,"kp":["[合成技术]: 羰基/亚胺双有机活化机制实现的氨基甲基膦酸酯直接不对称α-C共轭加成"]},{"i":36536,"as":"","scd":null,"kp":[]},{"i":36537,"as":"研究报道了一种可见光介导、手性布朗斯台德酸催化的3-偶氮吲哚C2极性反转策略，实现了与2-取代吲哚的催化不对称正式亲核C2取代反应。该方法突破了富电子吲哚骨架在催化不对称亲核取代中的合成瓶颈，以优异的对映选择性和良好的产率合成了轴手性2,3'-联吲哚化合物，填补了该领域亲核官能化反应的研究空白。","scd":null,"kp":["[催化反应特征]: 可见光介导和手性布朗斯特酸催化的吲哚C2-极性反转，实现向2,3'-联吲哚阻转异构体的不对称形式亲核C2取代"]},{"i":36538,"as":"全球数据汇总表明，废水处理副产物——废水残余固体是新兴污染物的集中储库，分别捕获了全球约20%的微塑料、24%的药物和13%的抗生素抗性基因排放。消除该固体中的新兴污染物可大幅减少环境负荷。模拟评估显示，热化学处理等下一代技术能够近乎完全破坏这些新兴污染物，为在全球范围内减轻新兴污染物的生态和公共健康威胁提供了战略干预手段。","scd":null,"kp":["微塑料全球释放量截留率[废水剩余固体]: 20%","药物全球释放量截留率[废水剩余固体]: 24%","抗生素抗性基因全球释放量截留率[废水剩余固体]: 13%"]},{"i":36539,"as":"研究开发了一种直接在固相合成多肽上引入14C或3H放射性标记赖氨酸残基的平台技术。该工作流程通过温和且兼容多肽的氢甲酰化反应处理烯丙基甘氨酸残基生成标记的烯丙赖氨酸，随后进行还原胺化反应，在脱离固相载体后直接生成放射性标记的赖氨酸。该氢甲酰化系统支持灵活的同位素引入，为放射性标记多肽药物的开发提供了高效低成本的新途径。","scd":null,"kp":["[后期放射性标记]: 在固相载体多肽上直接通过甲酰化反应植入14C或3H放射性标记的赖氨酸残基"]},{"i":36540,"as":"研究报道了一种协同外延生长策略，将元素前驱体与原子级工程化的无钾云母表面结合，实现了铋基硫族化合物和氧硫族化合物单晶的普适性生长。该策略成功生长出九种毫米级尺寸的铋基单晶，无需昂贵且晶格匹配的特定衬底，克服了现有合成方法仅适用于特定材料的局限性。该方法为探索拓扑物理特性和推进下一代电子与光电子器件提供了可扩展的材料平台。","scd":null,"kp":["[外延生长技术]: 无钾（K+）云母辅助外延生长法，用于合成铋基硫族化合物和氧硫族化合物单晶"]},{"i":36541,"as":"研究开发了具有四方钨青铜结构的Ba2La1−xBixTi2Nb3O15无铅弛豫铁电陶瓷。在1400 kV/cm的超高电场下，该材料实现了14.39 J/cm3的可恢复能量密度和87.69%的能量效率，创下块体四方钨青铜结构陶瓷的最高纪录之一。机理研究表明，Bi3+的引入诱发了氧八面体畸变，破坏了长程极化有序，多尺度结构优化机制有效克服了低击穿强度和储能密度不足的限制。","scd":null,"kp":["可回收能量密度[四方钨青铜结构Ba2La1−xBixTi2Nb3O15陶瓷]: 14.39 J/cm3","能量存储效率[四方钨青铜结构Ba2La1−xBixTi2Nb3O15陶瓷]: 87.69%","击穿电场[四方钨青铜结构Ba2La1−xBixTi2Nb3O15陶瓷]: 1400 kV/cm"]},{"i":36542,"as":"研究利用丹磺酰-谷氨酸二酰胺对映体证明，控制对映体过量可以增强手性光学活性，使其超越纯手性组装体。精细调节对映体过量会触发结构重组，在特定的对映体过量值下产生最大的圆二色性（CD）和圆偏振发光（CPL）强度。模拟揭示，少数对映体的掺入改变了原有序列结构，打破了手性信号与手性组装纯度之间的传统认知。","scd":null,"kp":["[手性光学活性增强]: 控制对映体失衡策略可使手性光学活性超越纯手性组装体"]},{"i":36543,"as":"研究提出一种将推理延迟与计算复杂度解耦的自适应kNN图模型。该框架将分层可导航小世界（HNSW）图与预计算投票机制相结合，将邻居选择和加重的计算负担完全转移到训练阶段。在此拓扑结构中，推理过程仅需进行简单的查表和计数操作。该方法解决了近似最近邻搜索中分类精度下降和邻域大小k缺乏自适应性的问题，兼顾了大规模应用中的检索速度与准确率。","scd":null,"kp":["[kNN图模型]: 自适应图模型将推理速度与分类精度的权衡解耦，优化邻域大小(k)的自适应选择"]},{"i":36544,"as":"研究提出通过定向减弱多阴离子基团中X-O键的共价性来提升钠离子电池正极材料本征电子电导率的策略。采用非平衡快速煅烧技术合成的NASICON-Na3V2O1.6(PO4)2F1.4正极继承了前驱体的弱共价P-O键特征。这种弱共价P-O键有效激活了电子离域，显著提高了材料的本征电子电导率和倍率性能，克服了强共价键导致的电子局域化问题。","scd":null,"kp":["[电池改性策略]: 降低多阴离子基团中P-O键共价性以增加钠电池正极的内在电子电导率","[材料合成工艺]: 开发非平衡快速煅烧技术以实现材料改性"]},{"i":36545,"as":"","scd":null,"kp":[]},{"i":36546,"as":"","scd":null,"kp":[]},{"i":36547,"as":"研究在金属PtCoO2中引入极性晶格畸变，打破了电荷-自旋转换增强与欧姆损耗增加之间的传统权衡。电子叠层衍射技术证实，对称性破缺源于局部极性位移。这种极性与金属性的共存使材料在室温下的自旋霍尔电导率达到1.6 × 10^7 ℏ/2e (Ω m)^−1，较非极性相提升了两个数量级，为自旋电子器件提供了兼具高效电荷-自旋转换和极低电学损耗的新颖自旋源材料。","scd":null,"kp":["[高导电金属中引入极性晶格畸变]: 克服电荷-自旋转换与欧姆损耗增加之间的权衡限制","[PtCoO2材料]: 存在极性位移现象并能够增强自旋霍尔电导率"]},{"i":36548,"as":"","scd":null,"kp":[]},{"i":36549,"as":"研究提出了一种利用纳米颗粒递送小分子金属有机分子的癌症免疫疗法。该纳米颗粒能在癌细胞中有效诱导固有抗病毒反应，并引发B细胞介导的肿瘤清除。这一机制成功将先天免疫感知与适应性免疫应答相连接，从而激活抗肿瘤免疫，为治疗“冷肿瘤”提供了一种有潜力的新策略。","scd":null,"kp":["药物递送载体[癌症免疫治疗]: 纳米颗粒介导递送的小分子金属有机物","免疫激活机制[小分子金属有机物]: 诱导癌细胞产生天然抗病毒反应并引起B细胞介导的肿瘤清除"]},{"i":36550,"as":"研究发现纳米颗粒可以通过相邻非恶性组织中血管的增强通透性效应，在无血管的微转移灶周围聚集。实时活体成像显示，微转移灶改变了局部力学性质，对相邻血管施加压应力，激活了β1整合素并引发细胞骨架重组，导致内皮完整性破坏和血管通透性增加。该研究阐明了纳米颗粒靶向递送至早期微转移灶的具体机制，为纳米材料的递送优化提供了关键依据。","scd":null,"kp":["[无血管微转移灶靶向]: 纳米颗粒通过相邻非恶性组织血管的通透性增强聚集于肿瘤部位","癌症死亡率归因[转移灶]: 90%的癌症相关死亡由转移引起"]},{"i":36551,"as":"水分氧化是人工光合作用的动力学瓶颈，限制了太阳能燃料效率。研究通过结合工况电化学壳层孤立纳米粒子增强拉曼光谱与纳米级电化学反应成像技术，空间解析了面化BiVO4颗粒上决定反应动力学的空穴转移动力学与水氧化中间体演化之间的原子尺度相互作用，揭示了动态结构适应机制。","scd":null,"kp":["催化反应动力学[人工光合作用]: 水氧化过程被广泛认定为限制太阳能燃料效率的动力学瓶颈","[原位条件探测]: 整合原位电化学壳隔绝纳米颗粒增强拉曼技术以揭示电荷转移与活性位点演变的空间耦合机制"]},{"i":36552,"as":"研究通过宏观垂直排列的氮化硼纳米管（BNNTs）膜，研究了碱金属离子的水相传输。在带电的3纳米和12纳米直径BNNTs中发现了两种反常传输现象：一是超出菲克扩散31倍的超快阳离子选择性扩散；二是Li+的传输速率高于K+和Na+，这与它们在体相溶液中的迁移率顺序相反。","scd":null,"kp":["纳米管薄膜孔密度[氮化硼纳米管垂直阵列]: 最高达 10^7 pores cm−2","离子传输机制[3至12纳米直径带电氮化硼纳米管]: 表现出与碳纳米管及二维氮化硼纳米通道截然不同的超快锂离子传输特征"]},{"i":36553,"as":"研究报道了一种脂质纳米颗粒中的小分子AT-1965。该分子通过与癌细胞中的Cap特异性RNA甲基转移酶2（CMTR2）相互作用，触发先天性炎症病毒防御反应，导致低免疫原性“冷”肿瘤快速消退并形成免疫记忆。AT-1965治疗的肿瘤高度浸润B细胞，敲除功能性B细胞会消除其抗肿瘤功效，直接证明B细胞在抗肿瘤结果中起关键作用。","scd":null,"kp":[]},{"i":36554,"as":"研究利用中国铝冶炼业作为案例研究，评估了在脱碳能源系统中保留高耗能工业（EIIs）过剩产能用于灵活用电的系统级成本效益。发现过剩产能可使铝冶炼厂采用季节性运行模式，在冬季用电高峰期停产。这种模式可降低脱碳能源系统的投资和运营成本。","scd":null,"kp":["[高耗能工业产能过剩]: 可转化为电力使用的季节性灵活性以支持脱碳能源系统","[中国铝冶炼行业案例]: 评估了保留工业过剩产能用于柔性用电的系统级成本效益"]},{"i":36555,"as":"由于生成1975年和1990年交通量预测的代码存在错误，对原文进行了作者更正。2000年和2015年的预测不受影响。目前代码已更正，并根据更正后的代码对文章相关内容进行了相应修改。","scd":null,"kp":["[1975和1990年交通量预测模型]: 已修复代码错误并重新生成预测","[2000和2015年交通量预测]: 不受模型代码错误影响"]},{"i":36556,"as":"研究发现转录因子YBX1是驱动非小细胞肺癌（NSCLC）骨转移和免疫抑制环境形成的中心调节因子，通过激活IL6和CCL5信号通路发挥作用。机制上，YBX1蛋白水平受糖基化控制，糖基化会标记其在细胞内发生自噬降解。高骨转移NSCLC细胞中YBX1糖基化降低。研究还发现候选药物Icaritin能增强这种糖基化修饰，从而促使YBX1降解。","scd":null,"kp":[]},{"i":36557,"as":"研究提出了一种基于配体介导的电子调制策略，使用锂铝乙酰丙酮络合物（LAAE）直接再生 degraded 钴酸锂（LCO）阴极。乙酰丙酮作为电子介体，通过与高价钴位点的π→d轨道耦合，重新分配Co-O键。该策略克服了传统成分补偿的缺陷，解决了阻碍离子传输的刚性界面问题，实现了废阴极的直接再生。","scd":null,"kp":["再生策略缺陷[废旧钴酸锂正极]: 现有策略多依赖组分补偿而忽略电子级调控，且缺乏对阻碍离子传输的刚性界面的研究","直接再生技术[基于配体介导界面调控]: 退化钴酸锂的电子软化可实现直接再生"]},{"i":36558,"as":"人工智能对算力的爆炸性需求导致传统电子计算面临内存和互连瓶颈。光子神经网络（PNNs）通过将关键操作迁移到光域，显著降低系统延迟和能耗。本文全面回顾了用于AI的新兴集成PNN技术，采用从基础物理器件到系统级实现的跨层框架。基于硅光子学的片上PNNs在可扩展平台上实现了高密度集成，推动了光电集成系统的演进。","scd":null,"kp":["架构瓶颈[传统冯诺依曼电子计算]: 面临内存与互连瓶颈","系统性能[片上光子神经网络]: 迁移关键操作至光域可显著降低系统延迟与能耗，并实现高密度集成"]},{"i":36559,"as":"电动汽车（EV）的快速普及给低压电网带来巨大挑战。现有规划方法通常假设区域内社区EV普及率均匀，未能捕捉历史数据的异质性。本文引入基于高斯过程（GP）的预测框架，将精细的历史EV注册数据与自上而下的区域情景相结合，生成社区级概率预测。该框架捕捉了局部普及率与区域趋势的偏差，为电网基础设施规划提供精细化指导。","scd":null,"kp":["基础设施风险[电动汽车聚集性邻里需求]: 易导致低压电网基础设施过载","规划模型缺陷[基于情景的传统规划]: 假设区域内电动汽车普及率均匀，未能捕捉历史注册数据的异质性且缺乏不确定性量化"]},{"i":36560,"as":"针对化学反应中难以获取过渡态的挑战，本文提出将过渡态预测表述为分子距离几何空间中的条件概率流学习。该距离几何生成流模型在原子间距离上运行，采用化学约束表示捕获键重组。通过双分支网络架构中受最优传输启发的演化路径，引导生成过程走向化学一致的中间体。基准数据集表明，该模型提升了预优化结构保真度。","scd":null,"kp":["[过渡态预测]: 表述为分子距离几何空间中的条件概率流学习，而非笛卡尔坐标，利用化学约束表示捕获分子属性"]},{"i":36561,"as":"锂金属电池受限于枝晶生长和不稳定的固态电解质界面（SEI）。研究利用原位液相透射电子显微镜、低温光谱和计算建模，解析了LiClO4、LiPF6和LiTFSI三种不同电解液中的阴离子特异性锂成核和生长机制。该研究实现了对动态界面过程的纳米级观察，揭示了电解液阴离子化学对SEI形成和锂负极行为的调控作用。","scd":null,"kp":["[锂金属电池负极]: 具有高容量和低氧化还原电位","[锂负极面临的瓶颈]: 存在枝晶生长和固态电解质界面（SEI）不稳定的问题"]},{"i":36562,"as":"研究实验证明了一种利用高度非线性微型磁子谐振器产生超宽带磁子频率梳（MFC）的机制。小型谐振器体积结合慢波换能器，驱动系统进入深度双稳态区域，通过传播自旋波的参数激发实现频率梳的形成。该方法产生了跨越450 MHz带宽的超过350条梳线，且梳间距可连续调控，为片上微波信号产生与处理提供了紧凑高效的平台。","scd":null,"kp":["[超宽带磁子频率梳产生]: 使用高度非线性的微型磁子谐振器，利用强烈双稳态机制产生"]},{"i":36563,"as":"研究在室温下的二维范德华铁磁材料Fe3GaTe2（FGaT）中实现了磁场驱动的斯格明子退火。振荡磁场驱动形成多晶斯格明子晶格，而双极电流脉冲通过电流诱导晶格畸变产生各向异性六角态。这两种过程克服了热激活不足的限制，实现了对斯格明子晶格平衡相变的高度可调控制。","scd":null,"kp":["[范德华磁体中的斯格明子晶格退火]: 采用场驱动（场调制）方式而非热激活来克服动力学限制并实现可调控制"]},{"i":36564,"as":"研究开发了一种快速电化学人工腐殖化（EAH）方法，在60分钟内将生物质转化为类腐殖质大分子物质（AHLS）。在此过程中，阳极产生类醌自由基，阴极产生H*以驱动伯胺形成，中间体随后聚合。AHLS的分子和理化特征与天然腐殖质相似，具有作为缓释肥料和氧化剂的潜力，可用于土壤修复和可持续废弃物利用。","scd":null,"kp":["[电化学人工腐殖化(EAH)反应成熟时间]: 60分钟","[电化学人工腐殖化(EAH)反应驱动力]: 阳极产生类醌自由基，阴极产生H*驱动初级胺发生反应"]},{"i":36565,"as":"","scd":null,"kp":[]},{"i":36566,"as":"研究利用中空介孔粉末，在1750°C下通过放电等离子烧结技术实现了碳化硅（SiC）陶瓷近乎完全致密化（99.2±0.49%）。中空结构导致介孔周围强烈应力积累，瞬时崩塌成约6纳米的纳米碎片，极大加速致密化动力学。所得陶瓷晶粒细小，包含2H、4H和3C多型体，表现出优异力学性能，纳米压痕硬度大于35.0 GPa。","scd":null,"kp":["[块体碳化硅(SiC)陶瓷传统合成致密化温度]: >2100 °C","[块体碳化硅(SiC)陶瓷本工艺烧结温度]: 1750 °C","[块体碳化硅(SiC)陶瓷相对密度]: 99.2 ± 0.49%","[块体碳化硅(SiC)陶瓷烧结工艺]: 放电等离子烧结（利用中空介孔结构应力积累引发瞬间结构坍塌实现近完全致密化）"]},{"i":36567,"as":"研究引入一种半导体聚MOF策略，将半导体MOF与聚合物单体共聚，制备出均匀、缺陷最小化且消除微间隙的柔性半导体薄膜。这种分子级集成实现了高效电荷传输，成功用于高灵敏度辐射探测。该检测器展现出领先的X射线灵敏度（6972.9 μC Gyair-1 cm-2）和52.6 nGyair s-1的超低检测限。","scd":null,"kp":["[柔性半导体金属有机框架(MOFs)膜制备策略]: 将半导体MOFs与聚合物单体共聚，实现无微间隙、极低缺陷密度的均匀薄膜"]},{"i":36568,"as":"中红外光谱成像的快照采集受限于探测器灵敏度和光谱编码机制。研究提出基于本征非线性径向色散的中红外快照光谱成像技术。波长相关的相位匹配在4f成像架构内同时实现频率上转换和光谱复用，无需外部色散元件即可实现单次曝光光谱编码。结合散斑照明编码，有效压缩并恢复光谱信息。","scd":null,"kp":["[中红外快照光谱成像]: 基于固有非线性径向色散，通过波长依赖的相位匹配同时实现频率上转换和光谱复用"]},{"i":36569,"as":"研究使用中空纤维感染模型探究阿莫西林-克拉维酸（AMX-CLV）治疗大肠杆菌的机制。血浆样药物暴露会迅速选择出已带有氧化应激相关突变、并激活SOS反应的预存耐药亚群；而尿液样药物暴露则产生持续杀菌活性且不产生耐药性。这解释了该药物在尿路感染中具有特定部位疗效的分子药效学基础。","scd":null,"kp":[]},{"i":36570,"as":"研究利用遗传密码扩展技术，将过氧化氢酶-过氧化物酶KatG中形成辅因子的色氨酸（Trp105）替换为硫代色氨酸，实现了单一杂原子（N→S）替换。替换后的KatG未形成正常的Met-Tyr-Trp交联辅因子，而是发生位点特异性单加氧反应，生成具有(S)-构型的手性亚砜。该技术成功分离了杂原子在辅因子生物合成中的功能。","scd":null,"kp":[]},{"i":36571,"as":"研究发现浮游单细胞真核生物（如丁丁虫）的壳生物材料由自组装结构蛋白构成。这些在海水和淡水中形成的壳结构具有高度多样性，并能抵抗高温和极强化学试剂。通过单细胞转录组学与蛋白质组学结合，鉴定出壳蛋白的氨基酸序列属于丁丁虫独有的新蛋白家族，为医学和高新技术领域提供了可持续的新型仿生材料。","scd":null,"kp":["[浮游纤毛虫外壳生物材料]: 由自组装结构蛋白构成，具有化学抗性"]},{"i":36572,"as":"深度学习模型pMTnet-omni被开发用于预测T细胞受体（TCR）与抗原的结合状态。该模型不仅能判定结合与否，还能精准区分序列高度相似的TCR之间结合力的强弱。结合“实验室闭环”技术，该模型能准确预测具有特定抗原结合力（增强或减弱）的变异TCR，揭示了控制TCR与抗原配对的生物学规律。","scd":null,"kp":["[pMTnet-omni深度学习模型]: 不仅预测T细胞受体(TCR)与主要组织相容性复合体(pMHC)的结合/非结合状态，还能区分结合强度差异"]},{"i":36573,"as":"","scd":null,"kp":[]},{"i":36574,"as":"研究对6名转移性结直肠癌患者的58个单细胞衍生类器官和18个匹配的肿瘤团块进行全基因组测序。单细胞水平的系统发育揭示了癌症的克隆进化及治疗相关突变特征。研究发现化疗诱导的突变在患者间和患者内部存在显著的负荷与光谱异质性，这些突变在增殖能力较强的细胞谱系中富集，且晚期突变轨迹呈现出动态的基因组改变。","scd":null,"kp":[]},{"i":36575,"as":"研究以海星为非脊索动物代表，结合单细胞RNA测序和高分辨率3D成像技术，揭示了棘皮动物的卵巢细胞类型工具包。数据证实了海星卵巢中存在推测的卵原干细胞、以及与哺乳动物相似的颗粒样细胞和膜样细胞。这些发现从生物医学和进化角度阐明了卵子发生的驱动机制，为卵巢生殖细胞与体细胞的相互作用提供了分子层面的进化证据。","scd":null,"kp":[]},{"i":36576,"as":"研究利用定量各向同性超微结构成像技术，确定了初级纤毛组装过程中的三维膜超微结构及相关蛋白。结果表明，停靠在母体中心粒（MC）上的小囊泡变大是纤毛发生进展的关键触发因素，该过程需要MC远端附属蛋白CEP164。这些囊泡融合形成管状C型中间体和前所未有的环形膜中间体，其形成由膜运输调节因子EHD1和RAB8协调控制。","scd":null,"kp":[]},{"i":36577,"as":"研究开发了一种精准工程的级联靶向脂质纳米药物（pCAR-P3/LNP），通过雾化吸入、主动细胞靶向和启动子激活等多步靶向策略，在原位将肿瘤微环境中的肺泡巨噬细胞重编程为表达嵌合抗原受体的CAR-AMs。这种重编程克服了原有细胞的免疫抑制和促肿瘤作用，CAR-AMs通过三种综合机制介导协同的强效抗肿瘤免疫反应，用于肺癌免疫治疗。","scd":null,"kp":["纳米药物[原位重编程肺泡巨噬细胞]: 精密工程化级联靶向脂质体纳米药物(pCAR-P3/LNP)"]},{"i":36578,"as":"研究利用空间和单细胞转录学技术，对基因多样的产前皮层患者衍生类器官进行分析，绘制了自闭症谱系障碍（ASD）发病机制的空间结构图。研究发现，ASD存在异常的祖细胞和神经元区域划分，以及分布因患者而异的局部无序神经元斑块。这种空间镶嵌状的混乱会持续到神经元成熟阶段，与祖细胞间的粘附受损一致，表明ASD的生物学空间图谱具有高度异质性。","scd":null,"kp":[]},{"i":36579,"as":"染色体17q/TRIM37拷贝数增加是高危神经母细胞瘤的关键特征，导致细胞对新型PLK4抑制剂RP-1664高度敏感。研究发现，低剂量的RP-1664引起的中心体扩增以一种不依赖TRIM37的方式促成了这种敏感性。活细胞成像和CRISPR筛选表明，中心体扩增后的神经母细胞因无法聚集或灭活多余的中心体，最终死于多极有丝分裂。RP-1664单药治疗展现出显著的抗肿瘤疗效。","scd":null,"kp":["靶点[高危神经母细胞瘤]: polo-like kinase 4 (PLK4)","药物机制[TRIM37拷贝数增加的17q染色体癌症]: PLK4抑制诱导合成致死","药物[神经母细胞瘤临床前模型]: 新型PLK4抑制剂RP-1664"]},{"i":36580,"as":"研究突破传统以蛋白质为中心的视角，发现了包括经典的WW/SS模式在内的四种不同的核小体DNA类别，且在人类基因组中广泛存在。共享相同模式的核小体在旋转上保持同相，而不同模式表现出特定的旋转偏移，构成了核小体定位的DNA密码。对744种转录因子的分析表明，WW/SS和反WW/SS模式与染色质中转录因子的结合密切相关。","scd":null,"kp":[]},{"i":36581,"as":"研究分析了两个独立队列的神经影像学数据，揭示了人类局部皮质体积（CV）中高度可重复的性别差异，并将其与皮质表面积（SA）和皮质厚度（CT）这两个可分离的决定因素关联。通过整合性染色体非整倍体和孤立性促性腺激素释放激素缺乏症患者的数据，证实性别偏向的皮质解剖区域富集了X染色体和激素的协同效应。这些区域与特定的功能网络和组织分子特征相重叠。","scd":null,"kp":[]},{"i":36582,"as":"研究利用实时功能磁共振成像神经反馈技术，在逐次试验中分别上调枕面部区（OFA）或梭状回面部区（FFA）的活动，以剖析二者在面部感知中的作用。实验组成功增强了目标区域的活跃度。关键结论是：增强FFA活动可加快面部检测速度，而增强OFA则会阻碍面部检测；同时，伴随相关网络节点的增加，面孔身份识别达到最佳状态。","scd":null,"kp":["技术手段[实时功能磁共振成像神经反馈]: 逐次试验解偶联梭状回和枕叶区域对人脸检测与识别的贡献","实验样本量[rt-fMRI神经反馈研究]: N = 22"]},{"i":36583,"as":"研究利用欧洲5个国家的86对永久性草地和油菜籽田，评估了生境类型对植物、蝴蝶、野生蜜蜂和步甲物种组合的影响。结果表明，是生境类型而非景观级别的草地数量决定了生物多样性：植物和蝴蝶在草地中更为丰富。研究强调了农田作物与永久性草地之间的物种溢出效应，作物农田在欧洲景观中对永久性草地的生物多样性保护起到了重要的互补作用。","scd":null,"kp":["样本规模[评估欧洲农田生物多样性栖息地类型]: 5个欧洲国家的86对永久性草地和油菜田"]},{"i":36584,"as":"研究对人乳头瘤病毒相关的口咽鳞状细胞癌（OPSCC）进行了单细胞空间基因表达谱分析，以表征细胞组织结构和免疫抵抗机制。研究描述了在细胞因子表达、空间位置、免疫细胞浸润和癌细胞状态上均不相同的独特肿瘤实质免疫病灶。这些免疫病灶在共抑制受体信号传导和免疫抑制性髓系细胞方面表现出深刻差异，表明不同的肿瘤区域受特定且局部受限的免疫抵抗机制主导。","scd":null,"kp":[]},{"i":36585,"as":"研究开发了一种钛催化的硅杂环丁烷C(sp3)-Si键选择性硼氢化反应，用于合成硼基官能化的氢硅烷。该方案适用于多种结构独特的硅杂环丁烷，能高效生成含有游离Si-H和硼基官能团的分子库，可无缝整合到合成化学中。研究还展示了该策略在硅取代药物分子合成中的应用，并成功将此方法扩展到C(sp3)-Si键的氢化反应中。","scd":null,"kp":["催化剂[硅杂环丁烷C(sp3)-Si键选择性硼氢化]: 钛","产物[钛催化反应]: 硼基功能化硅烷(R2B~link~Si–H)"]},{"i":36586,"as":"","scd":null,"kp":[]},{"i":36587,"as":"","scd":null,"kp":[]},{"i":36588,"as":"","scd":null,"kp":[]},{"i":36589,"as":"","scd":null,"kp":[]},{"i":36590,"as":"","scd":null,"kp":[]},{"i":36591,"as":"","scd":null,"kp":[]},{"i":36592,"as":"","scd":null,"kp":[]},{"i":36593,"as":"","scd":null,"kp":[]},{"i":36594,"as":"","scd":null,"kp":[]},{"i":36595,"as":"","scd":null,"kp":[]},{"i":36596,"as":"","scd":null,"kp":[]},{"i":36597,"as":"","scd":null,"kp":[]},{"i":36598,"as":"","scd":null,"kp":[]},{"i":36599,"as":"","scd":null,"kp":[]},{"i":36600,"as":"","scd":null,"kp":[]},{"i":36601,"as":"","scd":null,"kp":[]},{"i":36602,"as":"硫化锂（Li2S）在高能密度无负极锂硫电池中至关重要，但其绝缘性及缓慢的氧化还原动力学阻碍了应用。研究提出了一种协同策略，将二异丙基二硫代碳酸二硫化物（DIP）作为高效多功能氧化还原介质引入四乙二醇二甲醚电解质体系。该体系具备高闪点和高耐压性。DIP介质的引入直接实现了Li2S氧化还原动力学与负极稳定性的双重协同优化，显著提升了电池性能。","scd":null,"kp":["介导剂[提升无负极锂硫电池Li2S氧化还原动力学与负极稳定性]: 高效有机二硫化物","理论容量[高能量密度锂硫电池]: 硫化锂具有高理论容量"]},{"i":36603,"as":"研究提出了一种通用的表面单原子工程策略，通过选择性地诱导局部对称性破缺，实现了绝缘材料中类金属传输的可编程控制。该策略能够对二氧化硅、三氧化二铝和氮化硼等绝缘氧化物和氮化物进行线性和深度的电子传输编程。这一方法克服了绝缘材料固有的强电子局域化挑战，打破了传统的金属-绝缘体界限，赋予了绝缘材料基底新的功能多性。","scd":null,"kp":["技术策略[绝缘体至金属传输可重构电子态]: 表面单原子工程"]},{"i":36604,"as":"针对糖尿病足溃疡（DFU）难以愈合且伴随内源性生物电中断、感染及氧化应激的问题，研究开发了一种自供电的离子热电双网络水凝胶。该水凝胶通过收集皮肤与空气之间的自然温度梯度，在无需外部电源的条件下产生与伤口相关的微电流，从而重建伤口电生理信号。此外，结合木犀草素和锌离子（Zn2+），该水凝胶能够重塑恶劣的DFU微环境，加速溃疡修复。","scd":null,"kp":["材料[通过恢复生物电加速糖尿病溃疡修复]: 自供电离子热电水凝胶","能量来源[热电水凝胶材料]: 收集皮肤与空气的自然温度梯度(无需外部电源)"]},{"i":36605,"as":"针对光催化两电子氧还原反应合成过氧化氢（H2O2）中质子转移与电子迁移动力学不匹配的问题，研究受天然氢化酶机制启发，设计了一种儿茶酚-三嗪型供体-受体共价有机框架（2,3-Dhta-Tt）。该材料能够实现定向的协同质子-电子转移（DCPET），有效克服了异质界面的动力学限制，极大提升了光催化合成H2O2的效率。","scd":null,"kp":["催化剂[高效光催化合成H2O2的2电子氧还原反应]: 具有定向协同质子-电子转移特性的共价有机框架(COFs)"]},{"i":36606,"as":"研究通过将疏水性星形离子液体低聚物作为体积庞大的溶剂整合到两亲性线性聚离子液体网络中，开发出一种两栖离子皮肤。相互缠绕的黏性四臂低聚物在基质中动态互锁，提供了强大的耐水自粘性和顺应性；而两亲性网络则构建了高效的水渗透通道，确保了在干燥环境下的优异透湿性。该皮肤在干燥和水下环境中均能保持柔软、透气、粘附和导电特性。","scd":null,"kp":["材料[在干燥和水下环境中保持柔软透气粘附导电的两栖离子皮肤]: 动态互锁星形离子液体调聚物"]},{"i":36607,"as":"基于分子的零热膨胀（ZTE）单晶十分稀缺。研究在G3Sb2二维金属卤化物晶体中观察到了线性ZTE和不寻常的反热塑性现象。通过深入探讨分子动力学与分子间相互作用间的复杂耦合如何主导分子形变和空间取向，该研究不仅打破了ZTE材料多为无机氧化物和金属合金的局限，也加深了对分子基单晶晶体热力学性能及结构变化机制的理解。","scd":null,"kp":["热膨胀行为[2D金属卤化物晶体]: 反热塑性与低热膨胀"]},{"i":36608,"as":"针对木材基生物质作为钠离子电池硬碳负极前驱体时微结构难以控制的问题，研究利用生物质中木质素与纤维素热响应的差异性，提出了一种靶向木质素的预氧化策略。NEXAFS、PDF和SAXS分析证实，该靶向预氧化有效缓解了碳化过程中闭孔的坍塌，实现了精确的结构工程。该方法显著提升了平台容量，在0.1C倍率下可提供392.0 mAh g-1的可逆容量和92.2%的高初始库仑效率。","scd":null,"kp":["前氧化策略[木质素靶向]: 利用木质素与纤维素差异热响应性实现硬碳微结构精准控制","关键技术状态[闭孔坍塌缓解]: 靶向预氧化可有效抑制闭孔坍塌，提升钠电池硬碳负极稳定性"]},{"i":36609,"as":"水系锌离子电池面临析氢反应、腐蚀和枝晶生长等问题。研究在锌箔电极上构建了由氮化硅层组成的3D隧道框架（ASN）。该框架能诱导锌离子通量均匀化并实现锌离子的快速扩散，同时将锌金属表面与水隔离，从而抑制相关副反应，提升电池寿命。","scd":null,"kp":[]},{"i":36610,"as":"针对被动日间辐射冷却（PDRC）在降雨和高纬度过冷时受限的问题，受植物启发开发出一种可涂覆的双功能仿生层状皮肤。其顶部含氟层能实现液滴起电和自清洁，并保持中红外发射。该设计通过分层结构整合了PDRC与液滴发电机（DEG），成功解决冷却与发电的权衡问题。","scd":null,"kp":["系统功能[全天候建筑改造]: 耦合被动日间辐射冷却(PDRC)与水滴发电机(DEG)，协同实现制冷与降雨发电以解决过冷与降雨限制"]},{"i":36611,"as":"受红细胞细胞骨架拓扑结构启发，研究人员通过顺序自组装策略构建了连续的机械互锁索烃框架动态聚合物网络。该合成先通过金属配位形成超分子聚六边形网络，再与线性聚冠醚进行主客体络合，使材料兼具高机械稳定性与动态适应性。","scd":null,"kp":["聚合物网络设计[仿细胞骨架拓扑结构]: 构建连续的机械互锁索烃框架，兼具高机械稳健性与动态适应性"]},{"i":36612,"as":"传统铁电翻转模型（如KAI和NLS）在恒定电场假设下推导，不适用于实际复杂电压工况。研究引入了紧凑的动态场驱动成核和生长（DFNG）模型。该模型能够对多种铁电材料在任意电压波形下的翻转瞬态进行定量拟合，提取时变的畴壁速度和生长维度。","scd":null,"kp":["成核生长模型[铁电动态场]: 提出在时变电压混合失真条件下预测铁电翻转动力学的新模型，突破传统恒定电场假设(KAI/NLS)的限制"]},{"i":36613,"as":"受鸟类视觉系统启发，研究开发了一种基于有机二维分子晶体异质结的全光谱双向光电突触晶体管（OST）。高质量异质结构促进了激子的高效分离与扩散，赋予器件出色的双极性特征和极高响应度，突破了传统突触技术依赖波长选择性或电学极性调制的控制限制。","scd":null,"kp":["光电突触晶体管[仿鸟类视觉系统]: 全光谱双向光电调控，突破波长选择性或电学极性依赖的碎片化控制限制"]},{"i":36614,"as":"为提升二元有机太阳能电池效率，研究人员通过单向末端π延伸和优化烷基分支位点，对非对称小分子受体进行了工程化设计。该分子工程有效降低了非辐射能量损失并增加了激子扩散长度，抑制了非辐射能量损耗，最终实现了20.7%的光电转换效率。","scd":null,"kp":["转换效率[二元有机太阳能电池]: 20.7%","分子工程[非对称受体]: 单向末端π-延伸及优化烷基支化位点以抑制非辐射能量损失"]},{"i":36615,"as":"为对抗植入物相关生物膜感染，研究构建了负载姜黄素的空心普鲁士蓝纳米颗粒与热敏水凝胶复合的光热平台（CHPB@H）。在近红外照射下，释放的铁离子与姜黄素自组装成复合物，充当“特洛伊木马”劫持细菌铁吸收途径引发铁死亡。同时该平台利用纳米酶活性清除活性氧，抑制成纤维细胞活化。","scd":null,"kp":["纳米平台[抗植入物相关生物膜感染]: 由负载姜黄素的空心普鲁士蓝纳米颗粒与可注射热敏壳聚糖水凝胶构成(CHPB@H)","治疗机制[光热触发响应]: 近红外触发局部释放铁离子与姜黄素自组装，通过免疫-纤维化重塑打破生物膜与免疫排斥的恶性循环"]},{"i":36616,"as":"针对高分子材料固有的刚度与阻尼权衡挑战，研究结合动态键与超支化聚离子液体（HPILs）的空间位阻效应，开发了具有增强剪切刚化和阻尼能力的坚韧离子凝胶。动态键解离与HPILs的拓扑约束分别在高频和低频区发挥协同作用，赋予凝胶宽频能量耗散与显著的剪切刚化特性。","scd":null,"kp":["凝胶特性[剪切增强阻尼离子凝胶]: 结合动态键与超支化聚合物位阻效应，协同实现强阻尼与宽频能量耗散，克服刚度-阻尼权衡"]},{"i":36617,"as":"研究报道了一种2-吲哚醇的脱芳构化Meerwein-Eschenmoser-Claisen重排反应。该合成方法反应条件简单且底物范围广，提供了一种高效构建天然产物和药物中普遍存在的3,3-二取代吲哚啉结构单元的通用方案，突破了脱芳构化反应底物受限的瓶颈。","scd":null,"kp":["合成工艺[脱芳构化[3,3]-Claisen重排]: 采用Meerwein-Eschenmoser-Claisen重排，高效合成3,3-二取代二氢吲哚及相关吲哚生物碱"]},{"i":36618,"as":"针对木质素电化学解聚选择性低的问题，研究人员开发了CuO/Cu0.92Co2.08O4异质结构催化剂。该催化剂实现了2-苯氧基-1-苯乙醇88%的转化率，生成苯甲醛和苯酚的产率分别为53%和27%。机理分析表明，反应通过苄基氧化生成苯偶姻苯乙酮，随后发生Cα-C键断裂的串联路径实现选择性裂解。","scd":null,"kp":["转化率[2-苯氧基-1-丙醇电化学木质素解聚]: 88%","催化剂[电化学氧化解聚]: CuO/Cu0.92Co2.08O4异质结构催化剂"]},{"i":36619,"as":"针对低温钠离子电池中钠离子损失、电解液凝固和粘度升高的问题，研究通过机器学习设计出一种单分子添加剂NaB(C2H5)4。该分子将补充钠离子库存的Na+、作为共溶剂的B(C2H5)4-和稀释剂功能集成于单一实体中，避免了多种添加剂并用产生的性能干扰，有效提升了电池低温性能。","scd":null,"kp":["添加剂[低温钠离子电池]: NaB(C2)单分子添加剂（集钠离子储库、共溶剂和稀释剂功能于一体）"]},{"i":36620,"as":"研究开发了一种质子陷阱辅助的S/O异构化驱动阳离子开环聚合方法。利用二氧化碳衍生的硫代内酯单体，实现了高分子量聚硫酯的可控合成。该策略成功制备出新型可降解压敏胶粘剂，解决了传统可降解粘合剂粘附强度不足、依赖化石原料及降解不完全的技术难题。","scd":null,"kp":["单体来源[可降解聚硫酯压敏胶]: CO2衍生","聚合策略[可降解压敏胶]: 质子陷阱辅助的S/O异构化驱动阳离子开环聚合"]},{"i":36621,"as":"研究首次实现了底物控制的全氟萘分子间脱芳构化环加成反应。在可见光能量转移催化下，单取代烯烃与八氟萘选择性发生双脱芳构化邻位[2+2]环加成；1,1-二取代烯烃则专一地发生对位[4+2]环加成；三取代烯烃进行非对映收敛[4+2]环加成并生成单一非对映体产物。","scd":null,"kp":["催化体系[全氟萘脱芳环化加成反应]: 可见光能量转移(VL EnT)催化","[底物控制的环加成模式]: 单取代烯烃选择性生成双脱芳邻位[2+2]环加成产物，1,1-二取代烯烃等产生其他特定模式加成产物"]},{"i":36622,"as":"研究探讨了带有PNCNP钳形配体的d2 Mo(IV)烷基叉片段与炔烃的反应活性。合成并表征了一系列新型Mo卡宾-炔烃络合物，并发现配体中引入N-甲基部分降低了复分解过程的能垒，首次实现了基于d2 Mo(IV)烷基叉体系的催化炔烃复分解反应。","scd":null,"kp":["催化剂[催化炔烃复分解]: d2 Mo(IV)烷撑基配合物（带有PNCNP钳形配体）","[非d0炔烃复分解催化剂突破]: 突破传统d0高氧化态Schrock型催化剂限制，实现首例非d0过渡金属（Mo(IV)）络合物催化炔烃复分解"]},{"i":36623,"as":"针对有机镁电池正极材料容量与循环稳定性的权衡，研究提出结合延伸内环共轭与多齿Mg2+配位的分子设计策略。以具有大范围π共轭和N,N-双齿螯合位点的六氮杂三亚苯（HATN）为活性中心，通过单硫醚和二硫醚键合构建了聚合物正极，有效缓解了这一技术难题。","scd":null,"kp":["正极材料设计策略[有机镁电池]: 扩展内环共轭结合多齿Mg2+配位（有效缓解容量-稳定性权衡）","分子骨架[刚性有机正极]: 六氮杂三联苯(HATN)"]},{"i":36624,"as":"为打破高电压电解液设计中仅依赖氟含量调节而引发的氧化稳定性与离子传输动力学权衡，研究开发了嵌入机器学习的化学配位摩尔浓度特征解析方法。该方法通过建立多组分与化学配位原子摩尔比之间的一一映射关系，超越传统氟化法则，实现了高压电解液的精准设计。","scd":null,"kp":["电解液设计策略[高压电解液]: 突破氟化调整局限，采用化学配位信息指导的机器学习模型引导的黄金准则"]},{"i":36625,"as":"针对电化学还原羰基通常停留在醇阶段的问题，研究开发了一种Pd-富集电极与甘氨酸介导的界面催化系统。该系统通过富Pd电极与甘氨酸的界面调节相互配合，将醇中间体保留在带电界面上并促进其随后的C-O键断裂脱氧，在水相体系下成功实现了羰基到亚甲基的转化。","scd":null,"kp":["催化体系[水相羰基电还原为亚甲基]: -Gly界面催化系统","[羰基至亚甲基电化学还原瓶颈突破]: 解决醇中间体易脱附问题，实现电化学温和条件下由羰基至亚甲基的深度脱氧还原"]},{"i":36626,"as":"针对石墨相氮化碳（g-C3N4）强烈的π-π堆叠和氢键作用限制了其应用的问题，研究提出了一种质子化靶向静电解耦策略。利用三氟甲磺酸，在环境条件下将g-C3N4层间框架快速解锁，剥离成分立且高度结晶的二维纳米片，克服了非共价键屏障且不破坏结构完整性。","scd":null,"kp":["剥离策略[g-C3N4纳米片快速制备]: 质子化触发层间解锁（克服强π-π和氢键作用，实现靶向静电解耦）"]},{"i":36627,"as":"为探究金属有机框架（MOFs）通道内负电荷密度与离子电导率的关系，研究人员合成了通道带有精确可调负电荷密度的MOFs。结果表明，通道内的负电荷密度通过调节静电微环境控制离子对解离、阳离子跃迁和移动电荷载流子浓度，固定的带负电基团能促进盐解离并提供跃迁位点。","scd":null,"kp":["通道电荷密度[MOFs碱金属离子传输调控]: 中性N-MOF、中等电荷M-MOF、高电荷H-MOF","[通道负电荷密度对电导率影响]: 碱金属离子电导率与通道内的负电荷密度密切相关（呈现正向调控）"]},{"i":36628,"as":"利用同步辐射原位X射线光电子能谱技术，研究了不同硅铝比的ZSM-5沸石催化剂在甲醇制烃反应中积碳的空间演化。探测深度约为1纳米的表面敏感测试表明，酸性较低的ZSM-5沸石会在晶体表面产生更显著的积碳堆积，并促进形成高缩合的石墨状结构。","scd":null,"kp":["研究对象[甲醇制烃过程]: ZSM-5催化剂积碳的空间演化","分析技术[原位X射线光电子能谱]: 评估不同Si/Al比ZSM-5催化剂上的积碳沉积"]},{"i":36629,"as":"研究提出了一种物理直观且可推广的匹配分析方法，用于预测大型有机分子在晶体基底上的吸附构型。该方法受石墨烯上的烷烃模型启发，采用类蒙特卡洛方法，通过最大化表面定向氢原子（“刺”）与周期性石墨六边形中心（“袋”）之间的重叠来分配高分辨率的吸附几何形状。该框架能够克服标准量子化学方法在处理大型π共轭分子时因尺寸和构象多样性导致的计算难题，且无需昂贵的计算成本。匹配评分有效提升了复杂结构的预测精度。","scd":null,"kp":["大分子构象预测[大π共轭有机分子在晶体基底表面吸附]: 表面氢原子重叠最大化的物理直观、可泛化的配准分析"]},{"i":36630,"as":"研究开发了一种同步且位点一致的SERS-SEIRAS平台，用于在阳离子依赖的碱性氧还原反应（ORR）中实时跟踪界面水和表面吸附物种（OOH_ad和OH_ad）。研究发现，界面水通过调节氧中间体的吸附和介导质子耦合电子转移（PCET）在ORR中发挥关键作用。实验结果表明，降低阳离子水合能会引发特定效应。该技术填补了动态关联界面水与吸附中间体的技术空白，揭示了中间体物种演变的机制。","scd":null,"kp":["催化机理[碱性氧还原反应]: 阳离子调控界面水和吸附中间体的演化机制","分析技术[原位SERS-SEIRAS]: 动态关联界面水与吸附中间体"]},{"i":36631,"as":"研究开发了一种Pd单原子掺杂的Cu3Co量子点电催化剂（Pd-Cu3Co QDs），优化了加氢动力学，用于多功能铝-硝酸盐原电池。该电池系统能够同步实现能量收集与废物的资源化增值。该催化剂通过结构-活性关系提升了催化活性和氨（NH3）选择性，克服了传统硝酸盐电池中阴极硝酸盐还原动力学迟缓、开路电位（OCP）低和功率输出有限等关键局限性，从而大幅提高了电池的电能输出效率。","scd":null,"kp":["催化剂[铝-硝酸一次电池阴极还原]: Pd单原子掺杂Cu3Co量子点","催化剂设计目标[铝-硝酸一次电池]: 优化加氢动力学，同步实现能量收集与废物资源化"]},{"i":36632,"as":"研究提出了一种可持续合成硝酸铵（NH4NO3）的新方法，直接利用空气和水作为原料。该系统集成了等离子体辅助氮氧化（pNOR）与成对电催化亚硝酸盐还原和氧化（eNO2–RR/eNO2–OR）反应。这种方法提供了一种替代传统高耗能的哈伯-博施法和奥斯特瓦尔德法的全新途径，大幅降低了传统硝酸铵工业生产对全球碳排放的负面影响，实现了化肥的绿色可持续合成。","scd":null,"kp":["合成工艺[硝酸铵可持续合成]: 空气与水经等离子体-电解槽串联系统直接合成硝酸铵"]},{"i":36633,"as":"研究提出了一种反直觉的“π-桥修剪”策略，用于构建高性能的Ir(III)配合物光敏剂，以用于光免疫疗法。与传统的π-共轭延伸设计不同，三环稠合的TTz-Ir在摩尔吸光系数、溶解度、光催化活性和光细胞毒性等多个方面均优于五环稠合的π-延伸类似物TBTz-Ir。机理研究揭示，该策略成功构建了耐缺氧的光敏剂，并增强了cGAS-STING通路的激活。","scd":null,"kp":["光敏剂设计策略[耐缺氧光免疫治疗]: “π-桥修剪”策略","光敏剂材料[耐缺氧cGAS-STING激活]: 三环融合的高性能Ir(III)配合物"]},{"i":36634,"as":"研究通过质子化酸碱反应策略，将甲基铵（MA+）、甲脒（FA+）和四甲基铵（TMA+）等含氮鎓离子作为反离子引入聚七嗪酰亚胺（PHI）网络中，构建了全有机PHI材料。化学组成分析证实，每个理想的PHI晶胞中最多可掺入1个阳离子，且材料的晶体相与母体Na-PHI保持一致。该研究将这种改性材料应用于光催化过氧化氢（H2O2）的生成反应，旨在促进质子耦合电子转移过程。","scd":null,"kp":["光催化剂[光催化H2O2析出反应]: 引入有机反阳离子（如MA+、FA+、TMA+）的聚庚嗪亚胺（PHI）全有机网络","催化剂修饰方法[聚庚嗪亚胺网络]: 质子化酸碱反应策略"]},{"i":36635,"as":"研究展示了一种由负载在TiOx功能化TiC上的Rh纳米颗粒组成的电荷导向光热甲烷干重整（DRM）催化剂。界面TiOx纳米域通过耦合定向光生载流子流与自适应氧化学发挥了关键作用。在光照下，金属TiC产生光生载流子，有效解决了光热DRM过程中碳沉积阻碍效率和稳定性的问题。该催化剂成功实现了太阳能驱动的CH4和CO2的高效升级转化。","scd":null,"kp":["催化剂[甲烷光热干重整]: 负载在TiOx纳米畴上的Rh纳米颗粒","催化机制[甲烷光热干重整]: 电荷导向机制，解决碳沉积并明确光化学贡献"]},{"i":36636,"as":"研究建立了一个定义明确的铂基纳米线（NW）模型平台，旨在解决传统合金系统中ORR活性受电子、应变和集合效应耦合影响而难以独立解析的长期挑战。通过将供电子的Re（PtRe）或吸电子的Au（PtAu）选择性引入Pt纳米线中，同时保持相同的形貌、表面结构和配位环境，成功将电子效应对ORR的贡献分离出来。实验得出了一致的活性趋势（PtRe > Pt）。","scd":null,"kp":["模型平台[解耦Pt基催化剂电子效应]: 纳米线(NW)模型平台","研究机制[解耦氧还原反应活性]: 将电子效应与结构（应变、集合）贡献解耦"]},{"i":36637,"as":"研究报道了一种可见光介导的脱保护策略，使用2-(N-甲基吡啶-4-基)-噻唑烷（4-NMP-Thz）作为N端半胱氨酸（Cys）的新型保护基团，用于促进一锅法多肽连接。该反应在生理pH（6.0-8.0）条件下由[Ru(bpy)3]Cl2催化。该方法克服了当前Cys脱保护反应中需要添加多种试剂或调整pH值的繁琐步骤，为位点特异性修饰蛋白质的化学合成提供了一种高效的一锅法工具。","scd":null,"kp":["合成工艺[一锅法多肽连接]: 4-甲酰基-N-甲基吡啶鎓介导N端半胱氨酸修饰/去除，实现一锅法多重肽连接"]},{"i":36638,"as":"研究开发了一种锚定在MXene上的Ru-N4单原子催化剂（MX-RuSA），用于提升锂-二氧化碳（Li-CO2）电池的效率和循环寿命。该原子界面建立了协同双d带中心，成功克服了Li2CO3形成和分解动力学迟缓的限制。其中，N配位修饰了Ru的电子态，使其d带中心发生上移。这种双d带工程策略从根本上优化了催化性能，实现了Li-CO2电池的长效稳定运行。","scd":null,"kp":["催化剂[Li-CO2电池]: Ru-N4单原子锚定在MXene上","技术状态[Li2CO3形成与分解动力学]: 通过双d带工程克服缓慢动力学"]},{"i":36639,"as":"研究提出了一种利用化学可降解且亲水性可系统调节的大分子链转移剂（macroCTAs）的聚合诱导微相分离（PIMS）策略，成功制备出3D可打印的纳米孔热固性聚合物。这些macroCTAs通过α-硫辛酸或硫辛酸乙酯与各种丙烯酸酯的可逆加成-断裂链转移共聚合成。该策略解决了传统PIMS技术中宏观CTA极性固定和配方兼容性受限的问题，实现了互连纳米孔聚合物网络向增材制造领域的转化。","scd":null,"kp":["大分子链转移剂[聚合诱导微相分离策略]: 具有可调亲水性的化学可降解macroCTA"]},{"i":36640,"as":"研究提出了一种将木质素与二乙烯基配体共组装的策略，生成模拟成纤维细胞的木质素聚合物囊泡。这些聚合物囊泡由相对较弱的π-π堆叠驱动，疏水配体能有效插入芳香环之间，并可通过分子工程调节其界面分布。通过布尔逻辑门编程，该策略能够精确控制材料的力学特性，构建出可模拟人类皮肤不同生理阶段状态的机械可重构生物皮肤，以弥补皮肤弹性进行性丧失的问题。","scd":null,"kp":["仿生材料[类成纤维细胞聚合物囊泡]: 木质素与二乙烯基配体共组装"]},{"i":36641,"as":"研究设计并合成了一种基于苝二酰亚胺（PDI）支架的新型富氮双大环配体。该配体与Pd(II)配位后，会在PDI的湾区域触发直接的C-H钯化反应，生成两种不同的配合物：双钯物种（1-Pd2）和四钯物种（1-Pd4）。这种直接的π核金属化策略克服了传统酰亚胺官能化多环芳烃染料金属化难以控制的难题，为构建结构明确的手性多核金属配合物提供了新途径。","scd":null,"kp":["配体[多核钯配合物合成]: 基于苝二酰亚胺(PDI)骨架的富氮双大环配体","合成工艺[直接C-H钯化]: Pd(II)与配体配位触发"]},{"i":36642,"as":"研究提出了一种全各向异性组件集成模型，旨在实现高比能的固态锌金属软包电池。该模型利用天然可回收的木基材料，在经典的Zn-MnO2单电子反应体系中验证了其高磁通量特性的可行性。其中，轻质碳化木材被用作MnO2正极和Zn负极的通用集流体，同时结合磷酸修饰的纤维素基水凝胶作为电解质。这种设计突破了锌金属电池能量密度受限的瓶颈。","scd":null,"kp":["电池构型[固态锌金属软包电池]: 全各向异性组件集成模型","材料体系[固态锌金属电池]: 天然可回收的木质基材料"]},{"i":36643,"as":"","scd":null,"kp":[]},{"i":36644,"as":"","scd":null,"kp":[]},{"i":36645,"as":"","scd":null,"kp":[]},{"i":36646,"as":"","scd":null,"kp":[]},{"i":36647,"as":"","scd":null,"kp":[]},{"i":36648,"as":"","scd":null,"kp":[]},{"i":36649,"as":"研究通过外延生长构建了多晶-单晶岛状同质结，以克服固体氧化物电解池（SOEC）中共电解CO2和H2O制取合成气过程中电极动力学迟缓和界面电荷转移效率低下的问题。该架构结合了单晶BaFeO3和BaCoxFe1-xO材料。这种有序晶格界面结构显著提升了电催化反应效率，是实现大规模可持续燃料生产的关键技术突破。","scd":null,"kp":["电极界面[固体氧化物电解池]: 多晶-单晶岛状界面具有有序晶格","应用目标[固体氧化物电解池]: 高效共电解CO2和H2O制备合成气"]},{"i":36650,"as":"研究通过比较高纯度的同型电子内壁和外壁双壁碳纳米管（S@S和M@M），解决了碳纳米管-硅（CNT/Si）光伏器件中长期存在的半导体型和金属型纳米管谁能形成更好异质结的根本性问题。采用优化的Nafion基钝化和掺杂技术，S@S和M@M器件在异质结太阳能电池中均实现了创纪录的光电转换效率。研究证实，内壁和外壁之间的电子协同作用主导了异质结的性能表现。","scd":null,"kp":["碳纳米管[碳/硅异质结太阳能电池]: 同电子型内壁和外壁双壁碳纳米管"]},{"i":36651,"as":"研究采用分子动力学（MD）和蒙特卡洛（MC）混合方法，构建了钨（W）表面在氦等离子体辐照下早期形成的“绒毛”多孔层结构。该模拟通过原子尺度过程的相互作用自然形成纳米结构，提供了更具物理真实性的模型。利用生成的绒毛结构评估了表面特性的变化，结果表明，一旦绒毛层达到一定厚度就会停止生长。此外，该结构显著影响了表面溅射和氢的渗透与保留。","scd":null,"kp":["表面结构[氦等离子辐照下的钨表面]: 形成多孔“fuzz”层","模拟方法[钨表面fuzz形成早期阶段]: 分子动力学(MD)与蒙特卡洛(MC)混合方法"]},{"i":36652,"as":"研究综述了双极性有机场效应晶体管（OLETs）在材料和器件方面的最新进展。实现双极性平衡传输对于高性能电致发光和集成光电子学至关重要，但面临有机半导体中载流子注入和传输不平衡的挑战。文章指出，目前主要通过分子工程开发高迁移率的双极性发光半导体，以及优化器件结构（包括不对称电极、界面修饰层、多层和双栅结构）来补偿材料的局限性。","scd":null,"kp":["技术挑战[双极性有机发光晶体管]: 电荷注入和传输不平衡导致难以实现双极性传输平衡"]},{"i":36653,"as":"","scd":null,"kp":[]},{"i":36654,"as":"研究展示了一种固定镍的分枝杆菌孔蛋白A（MspA-NTA-Ni）纳米孔，能够识别多种蛋白质组学分析物，包括氨基酸和长度不超过39个氨基酸的肽段。在相同条件下，该平台记录了20种蛋白原氨基酸、4种翻译后修饰氨基酸、32种多肽等多种分析物的信号。结合基于机器学习的分析方法，实现了对这些分析物的高精度分类和序列组装，验证准确率极高，推动蛋白质测序迈向实际应用。","scd":null,"kp":["纳米孔[多肽传感与测序]: 镍固定的耻垢分枝杆菌孔蛋白A (MspA-NTA-Ni)","检测限[多肽长度]: 最多39个氨基酸"]},{"i":36655,"as":"","scd":null,"kp":[]},{"i":36656,"as":"","scd":null,"kp":[]},{"i":36657,"as":"","scd":null,"kp":[]},{"i":36658,"as":"","scd":null,"kp":[]},{"i":36659,"as":"","scd":null,"kp":[]},{"i":36660,"as":"","scd":null,"kp":[]},{"i":36661,"as":"","scd":null,"kp":[]},{"i":36662,"as":"研究人员提出一种温度诱导的剥离（TIDE）策略，利用水-乙醇溶剂在温度变化下的可逆体积膨胀与收缩，产生温和的“分子千斤顶”效应。这种可持续的物理方法能够以高产率剥离出大面积、高电导率的单层Ti3C2Tx和少层颗粒，为高质量二维材料的规模化生产提供了有效途径。","scd":null,"kp":["剥离策略[多层Ti3C2Tx]: 温度诱导剥离(TIDE)","剥离机制[水-乙醇溶剂]: 体积可逆膨胀与收缩产生的“分子千斤顶”效应","产物形貌与导电性[Ti3C2Tx单层]: 大面积、高导电的单层和少层颗粒","制备特点[TIDE方法]: 产量高且具备可扩展的高质量2D材料制备路线"]},{"i":36663,"as":"","scd":null,"kp":[]},{"i":36664,"as":"地球系统模型模拟表明，造林对水文的影响取决于背景气候状态。在低变暖情景下，造林使全球平均水资源可用量小幅增加，但加剧了空间分布不均（湿润地区变得更湿）；而在高变暖情景下，造林会降低水资源可用量。该结论对自适应土地管理和水资源政策具有关键意义。","scd":null,"kp":["水文影响[低暖化气候下的植树造林]: 增加水资源不平等性","水文影响[高暖化气候下的植树造林]: 降低水资源可用量"]},{"i":36665,"as":"电压可调微波介质电容器通常存在介电损耗高的问题，而Ruddlesden-Popper（RP）介质薄膜具备低微波损耗特性，但其晶体对称性与面外平行板设计不兼容。研究人员通过打破晶体对称性，成功研发出兼容平行板电容器设计的低损耗、可调RP介质薄膜，突破了微波电路微型化与电场最大化的技术限制。","scd":null,"kp":["材料优势[Ruddlesden-Popper介电薄膜]: 提供低微波损耗","结构兼容性[Ruddlesden-Popper介电薄膜]: 晶体学对称性通常不兼容于面外平行板可变电容器设计","设计优势[面外平行板可变电容器设计]: 能够最小化器件尺寸并在可调谐介电层中最大化电场"]},{"i":36666,"as":"研究人员研发出一款用于连续内部体温监测的微型可吞服温度传感器。该系统集成了1平方毫米的超低功耗（10纳瓦）集成电路、5平方毫米的无线反向散射天线和纽扣电池，整体封装直径仅6毫米、高4毫米。其尺寸小于现有的胶囊内窥镜设备，特别适用于儿童等特定人群的微创核心体温监测。","scd":null,"kp":["电路尺寸与功耗[微型可吞咽温度传感器集成IC]: 1 mm × 1 mm芯片，功耗为10 nW","天线尺寸[无线反向散射通信]: 5 mm × 5 mm","设备功能[连续内部监测]: 微创的连续核心体温监测手段"]},{"i":36667,"as":"热化损失限制了有机光伏（OPV）的性能。研究报道了一种紫外线吸收的TADF材料（BPhA-QAO），能够特异性调控聚合物给体。该材料通过调节能级延长单线态激子寿命、收窄单线态-三线态能隙实现激子回收并抑制热损失，最终实现了20.18%的认证光电转换效率，为高性能OPV提供了普适性策略。","scd":null,"kp":["光伏转换效率[热化控制激子管理的有机光伏电池]: 20.18%","材料功能[UV吸收TADF材料BPhA-QAO]: 调节聚合物给体能级，延长单线态激子寿命，缩小单线态-三线态能隙实现激子回收并抑制热损耗"]},{"i":36668,"as":"研究开发了二维钙钛矿作为“三合一”界面修饰剂，用于制备高质量的铅锡（Pb-Sn）钙钛矿薄膜。该策略使Pb-Sn钙钛矿太阳能电池效率达到24.07%，且具有优异的储存与运行稳定性。此外，基于此技术制备的双端全钙钛矿串联器件获得了30.07%（认证效率29.22%）的转换效率及极佳的运行稳定性。","scd":null,"kp":["光电转换效率[Pb-Sn钙钛矿太阳能电池]: 24.07%","光电转换效率[两端全钙钛矿叠层器件]: 30.07%(认证效率29.22%)","改性策略[2D钙钛矿]: 作为三合一界面修饰剂制备高质量Pb-Sn钙钛矿薄膜"]},{"i":36669,"as":"","scd":null,"kp":[]},{"i":36670,"as":"针对可再生能源高比例并网对电网韧性的担忧，文章指出可再生能源不仅能推进脱碳，还能增强电网稳定性。通过应用合成惯性、先进的基于逆变器的控制技术以及协调的输电规划，结合快速发展的储能和电力电子技术，绿色电网可以在保障气候目标的同时实现稳定运行。","scd":null,"kp":["电网稳定性技术[高比例可再生能源发电]: 合成惯性、先进基于逆变器的控制以及协调输电规划"]},{"i":36671,"as":"研究开发了一种无氧化剂电催化系统，通过富碘氧铋涂层碳布（I-BiOI@CC）阳极介导的质子耦合电子转移（PCET），实现酚类有机污染物的选择性聚合。该系统提供可逆的氧化还原介导，增强污染物与电极的相互作用，实现了高达97.1%的聚合选择性，将污染物转化为不溶性聚合产物，为资源回收型水处理提供了新途径。","scd":null,"kp":["聚合选择性[无氧化剂电催化体系]: 97.1%","催化体系[苯酚污染物聚合]: 碘介导的质子耦合电子转移(PCET)与富碘氧氯化铋包裹碳布(I-BiOI@CC)阳极","反应特点[有机污染物聚合]: 无需氧化剂且将污染物转化为不溶性聚合产物实现资源回收"]},{"i":36672,"as":"深度学习框架通过学习现有记录，为美国本土生成了空间完整的30米分辨率洪水风险图。据估算，2023年的官方数据库遗漏了1100万人口和410万栋处于洪水区的建筑，分别比官方基线高出69%和81%。社会经济分析显示，未在地图上标记的区域不成比例地居住着大量老人和儿童等弱势群体，加剧了既有不平等。","scd":null,"kp":["洪水危险图分辨率[美国本土深度学习洪水图]: 30米","数据纠正[2023年美国国家数据库遗漏评估]: 遗漏了1100万人和410万栋建筑(分别超出官方数据69%和81%)"]},{"i":36673,"as":"血液浆蛋白质组分析受限于蛋白质浓度动态范围过大，传统方法难以检测被高丰度蛋白掩盖的稀有蛋白。文章重点介绍了利用纳米颗粒“蛋白冠”技术富集低丰度血浆蛋白的前沿方法。该技术能有效扩大蛋白质组覆盖范围，未来将在蛋白质变异分析和因果推断方向发挥重要作用。","scd":null,"kp":["分析挑战[血浆蛋白质组分析]: 蛋白质浓度动态范围超过10个数量级","富集机制[纳米颗粒蛋白冠技术]: 富集低丰度血浆蛋白并揭示被高丰度蛋白掩盖的罕见蛋白"]},{"i":36674,"as":"研究指出HIV-1病毒衣壳的几何结构偏离了传统富勒烯晶格模型，其六聚体和五聚体边界形成了伪镶嵌结构。研究团队引入了一种三角形几何准则，用于量化HIV-1原子模型与理想富勒烯骨架之间的局部偏差。这一数学模型为理解HIV-1的生物物理特性、病毒机制及设计抗病毒干预手段提供了新视角。","scd":null,"kp":["[HIV-1 capsid core geometry]: 偏离理想富勒烯晶格模型，对功能产生重要影响"]},{"i":36675,"as":"通过高保真模拟，研究团队识别了现浇钢筋混凝土等高连续性建筑结构因初始损伤导致连续性倒塌蔓延的机制。在此基础上，开发了一种新型设计方法：利用定制的“调力保险丝”在损伤发生时中断结构连续性，以防止不可预见的大规模破坏引发建筑物的灾难性倒塌。","scd":null,"kp":["[建筑结构抗连续倒塌设计]: 破坏结构连续性以阻止在严重初始损伤下发生灾难性倒塌传播"]},{"i":36676,"as":"研究提出一种适用于多种废旧锂离子电池正极材料的太阳能驱动回收策略。该技术利用合理设计的苯并双噻唑联聚合物光催化剂，高效稳定地原位生成过氧化氢（H2O2），引发金属物种的氧化还原反应。在最优条件下，锂离子浸出率达14 mmol h⁻¹ g⁻¹，过渡金属提取效率超90%，并在自然阳光下实现了连续回收。","scd":null,"kp":["光催化剂[太阳能驱动废旧锂离子电池回收]: 苯并双噻唑联接聚合物","[原位光生H2O2]: 诱导氧化还原反应以回收有价金属"]},{"i":36677,"as":"针对蓝色钙钛矿发光二极管因埋藏界面降解导致的性能瓶颈，研究在空穴传输层上构建了季戊四醇四丙烯酸酯的三维交联网络。该致密网络作为物理屏障防止溶剂侵蚀，其羰基与钙钛矿晶格强配位以钝化缺陷，并在界面形成偶极子调节能级，从而大幅提升了蓝色PeLEDs的效率与发光亮度。","scd":null,"kp":["界面修饰材料[高效蓝色钙钛矿LED埋底界面]: 季戊四醇四丙烯酸酯三维交联网络","[空穴传输层(HTL)保护]: 交联网络作为物理屏障屏蔽极性溶剂侵蚀"]},{"i":36678,"as":"为解决盐湖提锂的Li+/Mg2+分离难题，研究将结晶框架转化为多孔液体（PLs），并将其嵌入氧化石墨烯（GO）层压板中，制备出超薄无缺陷的GO/PLs复合膜。该膜通过调节离子脱水过程，实现了极高的Li+渗透率（0.75 mol m⁻² h⁻¹）和优异的Li+/Mg2+选择性（154.4）。","scd":null,"kp":["[氧化石墨烯/多孔液体复合膜Li+/Mg2+分离]: 将结晶框架转化为多孔液体并嵌入二维氧化石墨烯层压板中构建超薄离子选择透过膜"]},{"i":36679,"as":"研究利用非线性光学技术，在范德华磁体CrPS4中观察到了可调谐的手性自旋纹理。在变化的磁场和温度下，层间和层内自旋耦合驱动这些纹理展现出强烈的手性三阶非线性光学响应。这些显著的光学响应为表征复杂的拓扑自旋态（如斯格明子）提供了高灵敏度的有效手段。","scd":null,"kp":["手性自旋纹理宿主材料[非线性光学观测]: 范德华磁体CrPS4","[自旋电子学应用]: 实现超薄、节能存储器及高密度数据存储与处理"]},{"i":36680,"as":"研究表明，锚定在缺陷氧化镁纳米晶体（小于20纳米）上的单原子铈（Ce）能够显著提升氧空位在二氧化碳转化中的活性与稳定性。对于2（此处指特定负载量）的催化剂，即使在高至600℃的高温或存在300 ppm硫化氢（H2S）的恶劣条件下，依然能实现高性能和高稳定性，其中Ce原子主要起增强氢气分子活化作用。","scd":null,"kp":["反应条件[CO2转化]: 反应温度≥600 °C或存在H2S的苛刻条件","催化剂尺寸[缺陷型MgO纳米晶]: 小于20纳米","[Ce单原子辅助氧空位]: 提升高温及含硫条件下的CO2转化活性与稳定性"]},{"i":36681,"as":"研究结合多模态文献挖掘与基于物理描述符的深度集成学习，开发了无铅弛豫铁电体的逆向设计框架。通过筛选超过1.5亿种候选组合，确定了(Sr0.48Na0.26Bi0.26)(Ti1−xSnx)O3 (0 ≤ x ≤ 0.02)体系，实验验证表明x=0.01的组分成功打破了介电性能权衡，在高温下兼具高介电常数与热鲁棒性。","scd":null,"kp":["[无铅弛豫铁电体逆向设计]: 结合多模态文献挖掘与物理引导描述符的深度集成学习进行系统筛选"]},{"i":36682,"as":"研究利用硼酸在空气干燥过程中原位共价交联天然鞣花酸和纤维素，开发出一种热可调谐的双模余辉材料（EA@Cell）。凭借B-O-C刚性网络，该材料在紫外线激发后，展现出肉眼在日光下可见长达8秒的室温磷光（RTP）；同时具有热激活延迟荧光（TADF），并随温度变化实现从绿色到蓝色的热致变色发射。","scd":null,"kp":["双模余辉材料特征[生物质基室温余辉]: 具备热活化延迟荧光(TADF)和室温磷光(RTP)双重模式，且RTP在日光下可见","[发射颜色热调控]: 利用硼酸共价交联实现绿到蓝的热致变色发射"]},{"i":36683,"as":"研究开发了一种限制驱动的孔记录合成策略，在共价有机框架（COF）的排列通道内实现石墨炔（GDY）的模板化生长，制备出受限的GDY纳米膜。所得的GDY⊕COF膜在分离3埃分子（H2、He）与更大分子时表现出极高的选择性。理论计算表明，该高选择性源于严格的尺寸排阻效应与放大的分子识别协同作用。","scd":null,"kp":["[石墨炔(GDY)分子筛膜埃级气体分离]: 采用限制驱动的孔记录合成策略，在共价有机框架的 aligned meso-channels 中进行模板化生长以实现具有垂直可及面内孔的连续膜"]},{"i":36684,"as":"针对酸性介质中电化学二氧化碳还原存在竞争性析氢和多碳产物选择性低的问题，提出一种协同催化策略。通过在氧化铜纳米片上固定四(4-羧基苯基)钴卟啉，构建双功能界面调节质子活化和界面溶剂化。该策略在高电流密度下维持碳碳偶联并抑制寄生析氢反应，使多碳产物的法拉第效率高达89.5%。","scd":null,"kp":["催化策略[酸性CO2电还原中多碳产物形成]: 协同催化调控质子活化与界面溶剂化","催化剂体系[酸性CO2电还原双功能界面]: 氧化铜纳米片与固定化四(4-羧基苯基)卟啉钴复合"]},{"i":36685,"as":"针对多相催化中原子结构稳定性的挑战，利用氨作为活性氮源，促使钌原子选择性迁移至二氧化铈域上，形成稳定且原子级分散的结构。在氨分解过程中，含氮中间体促进钌原子重排并锚定，构建出稳定的钌-二氧化铈界面。该催化剂降低了活化能并缓解了氢中毒，在高压氨分解制氢中表现出高催化活性，且原子结构得以保持。","scd":null,"kp":["活性氮源[驱动钌原子迁移]: 氨气","催化剂结构[高压氨分解反应]: 钌原子选择性锚定在二氧化铈上的耐久性原子级分散结构"]},{"i":36686,"as":"芳香烃双官能化能够一步引入两个官能团，但对位选择性转化仍属研究薄弱点。文章提出一种由N-杂环卡宾（NHC）催化的自由基反应方案。该过程通过独特的酰基插入Smiles重排实现，自由基迈森海默络合物在再芳香化前被捕获，完成重排并生成1,4-双官能化芳烃。该有机催化方法底物适用范围广，能容忍多种官能团，可高效制备酰化苯胺。","scd":null,"kp":["催化方式[N-杂环卡宾催化]: 自由基介导的酰基插入Smiles重排"]},{"i":36687,"as":"热电器件此前的多研究集中于本征热电响应，忽略了电极-材料界面的热电效应，导致高估本征贡献。利用本征效应可逆与界面效应不可逆的特点，提出通过极化反转测量区分两者的方法。计算不同铁电薄膜的贡献发现，钛酸铅和具有肖特基接触的钛酸钡薄膜分别由本征和界面热电效应主导，这一发现修正了热电性能的品质因数。","scd":null,"kp":[]},{"i":36688,"as":"为克服传统合成1,n-双官能化烷基连接子步骤经济效益低和官能团兼容性差的问题，提出基于自由基介导的双向碳碳键断裂新方法。该方法通过形成缩酮过氧化物使简单环酮充当双自由基连接子，采用烷氧自由基诱导的β-断裂和酰氧自由基介导的脱羧串联过程，实现碳环的开环、碳骨架收缩与双向官能化，具备高度的可持续性。","scd":null,"kp":["合成策略[环酮碳环编辑]: 自由基介导的双向C-C键断裂/偶联以形成偕二过氧化物潜在双自由基枢纽"]},{"i":36689,"as":"","scd":null,"kp":[]},{"i":36690,"as":"为优化激光驱动质子加速的质子能量，提出利用高能大电荷电子束建立的渡越辐射场（TRF）来增强质子能量的方案。实验采用近临界密度等离子体，产生了电荷量高达30纳库（>13 MeV）的电子束。电子离开靶标时发射出能量达0.6焦耳（0.1-15 THz范围）的强烈渡越辐射场，用于加速质子。","scd":null,"kp":["加速方案[激光质子加速]: 过渡辐射场(TRF)增强能量耦合的混合加速机制"]},{"i":36691,"as":"","scd":null,"kp":[]},{"i":36692,"as":"为解决土壤有机物分解微生物多样性认识不足的问题，研究使用大陆尺度的宏基因组与高分辨率有机碳化学配对数据集。通过组装0.76 Tbp原核生物基因组并识别数万个有机碳分子，发现微生物具有广泛分解此前被认为是化学稳定碳的潜力。此外，研究揭示了不同属之间在分解有机质时存在的互补代谢特化作用。","scd":null,"kp":["数据规模[大陆尺度土壤宏基因组]: 组装0.76 Tbp原核生物MAGs包含828个基因组","鉴定数量[土壤有机物化学分析]: 66,727种有机质分子"]},{"i":36693,"as":"人工智能执行任务能耗极高，而大脑能将神经元聚集形成球体以实现高能效超长时程电生理活动。结合混沌动力学和分形理论阐明大脑通过电生理奇怪吸引子记忆处理信息的原理。构建的基于神经球的大脑信息处理模型预测，人脑存储容量达7.48×10^18字节，算力达6.24×10^18 FLOPS（约7.8万块现代GPU），且通过兰道尔原理展现出高达79%的惊人能效。","scd":null,"kp":["动力学机制[大脑高效信息处理]: 通过时空结构中的神经元全局合作形成电生理奇异吸引子","形态结构[神经元聚集实现长周期超高效电生理活动]: 球形神经元聚集"]},{"i":36694,"as":"使用简单未活化的烯烃和炔烃对未受保护胺进行选择性官能化一直是合成难题。文章提出一种针对仲N-甲基胺外围修饰的策略，兼容广泛的官能团和天然胺底物。该方法适用于后期官能化，包括未保护结构单元和复杂多肽的直接生物偶联。其解锁的逆合成灵活性使多种商业高收入药物的制备能在单一步骤中完成。","scd":null,"kp":["修饰平台[未保护仲胺后期修饰]: 烷基交换"]},{"i":36695,"as":"","scd":null,"kp":[]},{"i":36696,"as":"","scd":null,"kp":[]},{"i":36697,"as":"机器学习及其他技术的进步正协助科研人员追踪野生动物的活动轨迹、地标习惯以及社交行为，从而揭示从蜂鸟到美洲狮等各种野生动物隐秘的生活规律。","scd":null,"kp":[]},{"i":36698,"as":"一款家用脑植入设备成功帮助一名运动神经元疾病患者恢复日常交流能力。该设备允许患者控制计算机，且该控制与交流功能已持续有效运作了近两年时间。","scd":null,"kp":["应用效果[植入式家庭脑机接口]: 帮助运动神经元疾病患者恢复交流并控制计算机近两年"]},{"i":36699,"as":"","scd":null,"kp":[]},{"i":36700,"as":"随着英国邱园 botanical garden 完成对其多达700万份标本收藏的数字化扫描工作，这些数字资源结合人工智能工具，有望在未来应对生物多样性丧失的挑战中发挥关键作用。","scd":null,"kp":[]},{"i":36701,"as":"","scd":null,"kp":[]},{"i":36702,"as":"","scd":null,"kp":[]},{"i":36703,"as":"为合成磷手性化合物，研究人员开发了一种铜催化的对映趋同自由基C(sp3)-P交叉偶联反应，利用外消旋二级膦氧化物与烷基溴化物反应。同一催化平台还能通过双重对映趋同构建实现外消旋膦酸酯与外消旋苄溴生成相邻的P,C-立体中心。该方法为磷中心手性提供了实用途径。","scd":null,"kp":["催化剂[对映体收敛自由基C(sp³)-P交叉偶联]: 铜","[外消旋二级氧化膦/H-次膦酸盐与烷基溴化物]: 高效合成P-手性磷化合物","[同一催化平台]: 实现由外消旋H-次膦酸盐和外消旋二级苄基溴构建邻位P,C-立体中心的双对映体收敛反应"]},{"i":36704,"as":"","scd":null,"kp":[]},{"i":36705,"as":"激子是半导体中电子激发的介导物质。研究发现，二维磁性半导体CrSBr中的束缚激子储层能够产生激子自旋力矩，发挥类似于阻尼和反阻尼的相干作用。这种本征的激子自旋力矩能驱动磁势能表面的非平凡轨迹，仅需单一光脉冲即可实现反铁磁构型之间的快速且可重复的切换。与受限于异质结构对称性和界面设计的传统自旋力矩不同，激子自旋力矩是材料的内在属性。这些结果确立了激子在自旋电子学中的重要应用价值。","scd":null,"kp":["激子自旋扭矩[二维磁性半导体CrSBr]: 表现为类阻尼和反类阻尼扭矩","[束缚激子库]: 驱动磁势能面上的非平凡轨迹"]},{"i":36706,"as":"保加利亚科学院与于利希研究中心的Ilia Valov教授接受了《自然·材料》的采访，重点探讨了纳米忆阻器的相关材料考量。讨论的核心集中在纳米尺度结构与成分、电化学特性，以及这些因素如何共同决定忆阻器的最终物理性质与功能表现。该访谈明确了微观材料科学与电化学机制在忆阻器研发和性能调控中的关键作用。","scd":null,"kp":["[纳米忆阻器]: 纳米尺度下的结构、成分、电化学特性与其性质和功能存在紧密关联"]},{"i":36707,"as":"","scd":null,"kp":[]},{"i":36708,"as":"利用屋顶光伏（RPV）为电动汽车（EV）充电可加速可再生能源转型与碳减排。针对发电与充电需求之间的时空不匹配问题，研究评估了全球40个城市的光伏充电可扩展性，分析了2.2万个充电桩的33.8亿条充电记录。结果显示，在不同规模的城市微电网中，影响每日充电容量（发电需求比）的因素遵循指数缩放定律。研究预计，到2050年屋顶光伏发电量将翻倍，为电动汽车充电提供更大潜力。","scd":null,"kp":["评估范围[屋顶光伏供电动车充电时空可扩展性分析]: 全球40个城市","分析数据量[充电网络]: 33.8亿条充电数据"]},{"i":36709,"as":"","scd":null,"kp":[]},{"i":36710,"as":"燃后碳捕集与封存（CCS）技术能减少电厂碳排放，但同时影响其他空气污染物排放。研究评估了煤电厂和天然气联合循环（NGCC）电厂在全国范围内采用单乙醇胺和CESAR1溶剂进行CCS改造的影响。若CCS改造仅适用于新建设施，则能处理97%的NGCC电厂排放，而煤电厂仅能处理27%。胺基溶剂的降解会导致氨气排放。研究探讨了CCS改造在减少碳排与控制空气污染方面的健康效益及技术限制。","scd":null,"kp":["吸收剂[燃煤和天然气联合循环电厂燃烧后碳捕集]: 单乙醇胺基溶剂","[胺基溶剂降解]: 会导致NH3（氨气）排放"]},{"i":36711,"as":"过量的乳酸输出会形成抑制抗肿瘤免疫的酸性微环境。为克服小分子抑制剂的系统毒性，研究开发了基于聚合物的溶酶体靶向嵌合体，能在肝癌细胞中空间选择性降解伴侣蛋白CD147，从而减少乳酸外排并重编程代谢。进一步设计的酸响应型嵌合体实现了药物在肿瘤内的可控释放。这种纳米技术通过调节乳酸代谢，有效增强了肝癌的抗肿瘤免疫反应。","scd":null,"kp":["靶点[肿瘤微环境代谢调节]: 单羧酸转运蛋白1和4 (MCT1/MCT4) 及其伴侣蛋白CD147","降解机制[克服小分子全身毒性]: 聚合物基溶酶体靶向嵌合体选择性降解CD147"]},{"i":36712,"as":"先导编辑是一种精准的基因编辑方法，但非病毒脂质纳米颗粒（LNP）递送系统在应用于三组分先导编辑系统时效率较低。研究开发了系统性的先导编辑LNP（PE-LNP）优化平台，解决了限制编辑效率的瓶颈。该优化方案在单次注射2 mg/kg剂量下，在小鼠肝脏中实现了平均49%的体内先导编辑效率。该技术被成功应用于致病基因突变的精准修复，展示了极高的临床转化潜力。","scd":null,"kp":["递送载体[体内/体外先导编辑系统]: 脂质纳米颗粒(LNP)","[非病毒LNP递送三组分先导编辑系统]: 克服了传统应用中编辑效率低的问题，实现高效编辑"]},{"i":36713,"as":"研究开发了一种可控且可编程的细胞内蛋白质结晶合成平台。实验表明，活细胞内的稳定蛋白质表达在初始成核后主导晶体生长，产生可预测和可调的动力学。结合HaloTag和点击化学技术，研究实现了多种客体材料的模块化、可编程固定，空间分辨率达到100纳米。该平台还成功在生理相关体液中实现了固定材料的顺序释放，并作为概念验证成功在细胞内携带并递送了特定的人类成纤维细胞生长因子。","scd":null,"kp":["合成平台[蛋白质晶体]: 活细胞内可控且可编程的结晶合成（细胞反应器）","[晶体生长]: 初始成核后由稳定的蛋白质表达控制，产生可预测、可调的动力学","[可编程修饰]: 结合HaloTag和点击化学实现"]},{"i":36714,"as":"研究通过扫描单电子晶体管，结合局部热力学和输运测量，探究了具有不相等角度和扁平电子能带的扭转三层石墨烯体系。在局部扭转角度平滑演变的区域，电子-电子相互作用导致了间隙相关的绝缘体状态，以及逆电子压缩率的不对称振荡。这些现象表现出明显的电子-空穴不对称性，揭示了热力学特征与扭转石墨烯微观基态之间的内在联系。","scd":null,"kp":["探测仪器[绘制局部热力学和输运测量特征]: 扫描单电子晶体管","材料模型[研究热力学特征与超导性的关联]: 具有不等角和平坦电子带的扭曲三层石墨烯"]},{"i":36715,"as":"异相受阻路易斯对（FLPs）的静态活性位点限制了其在动态催化环境中的适应性和效率。研究受软材料动态特性启发，在氮化碳框架上构建了互变异构受阻路易斯对（TFLPs），实现了从静态设计向光调控动态催化的转变。通过超分子自组装，工程化的氮化碳异构体能够发生光诱导的酮-烯醇和次膦酰亚胺互变异构化。该过程在原位生成了瞬态且稳定的电子活性位点，有效避免了位点的猝灭和毒化。","scd":null,"kp":["催化剂设计[非均相 frustrated Lewis pairs]: 光调控动态催化","催化剂缺陷[高负载条件]: 活性位点不可避免猝灭","应用挑战[FLPs实际应用]: 易受毒化失活"]},{"i":36716,"as":"针对导电聚合物在水相环境中易发生电子/空穴猝灭的难题，研究提出一种电化学策略，实现了在0.4V（vs. Ag/AgCl）的超低电压下生成羟基自由基（•OH）。该系统由吸附在部分氧化铜片上的聚(芴-交替-噻吩并吡嗪)（PFTP）组成。显微镜和表面分析证实，铜片表面的氧化亚铜（Cu2O）层增强了PFTP聚合物的相互作用，从而在极低电压下高效驱动水电化学氧化并产生•OH。","scd":null,"kp":["电压[羟基自由基生成]: 0.4 V (vs. Ag/AgCl)","电压特性[羟基自由基生成]: 超低电压","水性环境限制[导电聚合物]: 水分子对电子/空穴的猝灭作用"]},{"i":36717,"as":"硫化物电解质对空气的不稳定性及其与溶剂的不兼容性严重阻碍了全固态锂电池的规模化制造。研究系统探究了空气中主要成分（氮气、氧气和二氧化碳）对硫化银锗矿型硫化物电解质的影响。实验证实，Li6PS5Cl和Li5.4PS4.4Cl1.6这两种电解质对氮气表现出化学惰性。该研究为理解硫化物电解质在干燥空气中的降解机制提供了直接证据，有助于开发具有大气稳定性的固态电池材料。","scd":null,"kp":["稳定性[硫化物电解质]: 面对空气及溶剂存在不稳定性与不兼容性","制造挑战[全固态电池]: 硫化物电解质的空气不兼容性阻碍其规模化生产"]},{"i":36718,"as":"研究探究了神经嵴细胞向心脏与头部发育的转录调控机制。通过比较ATAC-seq和单细胞RNA测序数据，发现了共享和区域特异性的开放染色质区域及靶基因。研究重点揭示了两个相邻的Cxcr4增强子：一个含TGIF结合位点特异作用于心脏神经嵴；另一个含TFAP2B结合位点，在头部和心脏神经嵴中均表现活跃。突变实验表明，TFAP2B位点的突变会导致相关神经嵴细胞特性的丧失，明确了差异转录因子在轴向命运决定中的关键作用。","scd":null,"kp":[]},{"i":36719,"as":"大型语言模型（LLM）正作为自主代理为用户做出决策。研究通过四种选择架构（默认、建议、信息突出和“最优”助推）测试了LLM的决策敏感性。结果显示，LLM的决策与人类行为基线存在显著偏离。LLM有时会为获取信息付出过高代价，有时则完全忽略可用信息。最关键的发现是，LLM对环境助推的敏感度远超人类，极易受选择架构的操控和影响。","scd":null,"kp":["决策影响因素[大语言模型代理]: 默认设定、建议、信息突出及最优助推","决策敏感度[AI自主代理]: 对选择架构（助推）表现出敏感性和可预测性"]},{"i":36720,"as":"血吸虫病相关肺动脉高压是最常见的I类肺动脉高压疾病。临床前动物模型表现出肠道和肺部微生物组失调，伴随肺内皮细胞功能障碍和微血管凋亡。研究利用Cdh5cre-ERT2;cIAP1−/−;cIAP2fl/fl小鼠模型发现，内皮细胞中凋亡抑制蛋白2（c-IAP2）的缺失会放大由嘌呤能受体P2X7（P2X7R）驱动的炎症反应。肺部P2X7R的过度表达被确定为该疾病恶化过程中的一个关键治疗靶点。","scd":null,"kp":[]},{"i":36721,"as":"研究提出了一种更新的基于模拟的预测方法ModBinddG，用于预测配体与蛋白质靶标结合的绝对自由能。作为一种双态模型，ModBinddG通过对加速采样的结果进行基于种群的重加权来计算绝对结合自由能。理论论证和实际应用均表明，该方法能准确预测小分子与特定蛋白靶标结合的绝对自由能。此外，更新后的方法显著提升了计算性能，大幅缩短了预测所需的时间。","scd":null,"kp":["预测模型[ModBinddG方法]: 预测绝对结合自由能","技术特征[结合自由能预测]: 基于种群重新加权的加速采样双状态模型"]},{"i":36722,"as":"巨型单细胞原生动物喇叭虫的体积大且结构可重现，是研究单细胞内结构形成的理想模型。特定细胞结构总是在细胞特定区域形成。借鉴胚胎发育中区域化mRNA标记位置信息的机制，研究探讨了喇叭虫内是否存在沿前后轴分布的区域化mRNA。通过全基因组分析，研究揭示了特定mRNA在巨型单细胞内的空间分布规律，为理解单细胞生物内部结构的位置信息来源与区域化发育提供了分子层面的解释。","scd":null,"kp":[]},{"i":36723,"as":"","scd":null,"kp":[]},{"i":36724,"as":"","scd":null,"kp":[]},{"i":36725,"as":"","scd":null,"kp":[]},{"i":36726,"as":"","scd":null,"kp":[]},{"i":36727,"as":"","scd":null,"kp":[]},{"i":36728,"as":"","scd":null,"kp":[]},{"i":36729,"as":"","scd":null,"kp":[]},{"i":36730,"as":"研究揭示了宿主与胞内微藻共生机制。通过三维亚细胞成像与生理分析证实，微藻在宿主体内发生显著变化，其叶绿体与固碳蛋白核大幅扩张。这表明微藻在共生过程中不仅提升了光合作用生产力，还强化了碳储存能力，为宿主提供能量支持。","scd":null,"kp":["共生机制[胞内微藻]: 提高光合作用产物并减少自身碳储存以最大化碳向宿主转移"]},{"i":36731,"as":"","scd":null,"kp":[]},{"i":36732,"as":"研究聚焦单萜吲哚生物碱的生物合成，该类物质包含长春新碱等药物中间体。研究发现一种名为FoGS的蛋白质，它与Geissoschizine合酶（GS）协同作用，能够显著促进共同生物合成中间体19E-geissoschizine的生成，为相关植物天然产物的合成途径提供了关键调控机制。","scd":null,"kp":["生物合成中间体[单萜吲哚生物碱]: 19E-geissoschizine","催化酶[生成中间体的关键酶]: 中等链脱氢酶"]},{"i":36733,"as":"研发出一种用于细胞代谢和抗菌药物敏感性测试的微量量热传感器。该传感器在23.1毫赫兹下灵敏度约为100皮瓦，通过测量样品毛细管与参考毛细管间的微小温差来直接量化产热。具备23至100 nV/nW的响应率及7.9秒的快速热响应，实现了对少量细菌增殖的实时长期监控。","scd":null,"kp":["灵敏度[微卡路里计传感器]: ~100 pW","测试频率[微卡路里计传感器]: 23.1 mHz","检测原理[生物代谢测量]: 测量样品毛细管与双参比毛细管间的微小温度差"]},{"i":36734,"as":"提出分数电荷密度泛函理论结合模型电极的FC-DFT+方法。该方法用于定量研究电极外加电压对自组装单分子层分子的电诱导和电场效应。FC-DFT+能准确预测C≡N频率与电压曲线的斜率、频率平缓行为及离子特性，揭示了电化学界面的关键分子作用机制。","scd":null,"kp":[]},{"i":36735,"as":"研究发现EMB基因是肠道神经元成熟的关键调控因子，其介导的自噬过程调节神经突生长。在EMB突变患者的病变肠道及敲除该基因的小鼠模型中，均观察到神经节减少症特征及神经突生长缺陷。这表明EMB/ATG7介导的自噬途径对肠道神经系统的发育至关重要。","scd":null,"kp":[]},{"i":36736,"as":"研究指出工业化前冰芯记录中甲烷浓度在多年代至百年尺度上存在约30 ppb（5%）的波动。通过源-汇动力学模型证实，这种甲烷浓度变异不需要归因于气候或人类活动引发的阶段性排放变化，完全可以单纯由源-汇失衡状态下的白噪声波动来解释。","scd":null,"kp":[]},{"i":36737,"as":"开发出一类被称为“真菌铁捕食者”（FIPs）的多聚儿茶酚抗真菌材料。FIPs能够高效渗入真菌细胞并选择性螯合不稳定铁元素，破坏真菌铁稳态与代谢。这种铁饥饿状态会引发严重的线粒体功能障碍和能量崩溃，最终导致真菌死亡。该材料表现出优异的杀菌活性和极低的细胞毒性。","scd":null,"kp":[]},{"i":36738,"as":"研究探讨了催产素对学习复杂社会网络等级关系的神经计算调节机制。以往研究多集中于线性社会等级，本研究揭示了催产素在处理包含小于、等于、大于等复杂等级关系时的大脑计算机制。催产素被证实能调节社会记忆、自我与他人的奖励学习差异以及群内外的决策过程。","scd":null,"kp":[]},{"i":36739,"as":"开发出一种可扩展的多模态触觉阵列无线网络，用于足底感觉替代。该系统包含贴合皮肤的触觉阵列，能在躯体任何部位提供高密度热学和振动触觉反馈。核心混合马达单元可独立控制温度和机械刺激，在64个可寻址节点上实现了128个自由度，满足中风等患者的躯体感觉替代需求。","scd":null,"kp":[]},{"i":36740,"as":"","scd":null,"kp":[]},{"i":36741,"as":"提出一种“带约束的随机”建模方法，用于处理高维复杂生物学系统。该策略指出许多生物学行为具有典型性，可以通过遵循生物约束条件的随机系统来建模。这种方法在神经科学、生态学和进化等多个生物领域中均成功与实验建立紧密联系，为克服高维生物复杂性提供了有效手段。","scd":null,"kp":[]},{"i":36742,"as":"利用全球生物多样性数据分析得出，土壤寄生原生动物的多样性与生态系统的时间稳定性呈全球性的正相关。其中，顶复门寄生虫的多样性对生态系统稳定性的正面影响尤为显著，定量证实了土壤寄生原生动物在维持陆地生态系统生产力稳定方面的重要作用。","scd":null,"kp":[]},{"i":36743,"as":"受曲线折纸启发，提出一种多稳态曲面折纸壳体的一般性设计方法。研究指出壳体变形自然集中在被称为“伪折痕”的条带上。通过分析几何参数对弯曲和拉伸力学的机械行为影响，研究阐明了多稳态背后的力学机制，实现了无需持续做功即可维持大形状改变的可重构轻质承载结构。","scd":null,"kp":["结构特性[多稳态壳体结构]: 无需持续输入能量即可保持变形状态并实现快速大幅形变","设计方法[多稳态壳体]: 基于弯曲折纸与可展曲面微分几何的通用设计法"]},{"i":36744,"as":"研究发现溶酶体钙转运蛋白TMEM165是低氧反应的关键调控因子。在低氧条件下，TMEM165表达增加，促进内质网钙离子转移至溶酶体并扩大其钙储存能力。TMEM165通过AMPK-mTOR和ERK/p21信号通路分别调节自噬与细胞衰老，在神经胶质瘤中高表达，推动肿瘤低氧适应与进展。","scd":null,"kp":[]},{"i":36745,"as":"研究揭示了ERK信号通路在细胞迁移前缘突起中的关键机制。利用靶向粘附的ERK FRET生物传感器发现，ERK在新生粘附结构的近膜组装区域被激活。ERK构建了一群短寿命的新生粘附结构，这些结构产生了持续的前缘突起，从而直接推动了细胞迁移过程。","scd":null,"kp":[]},{"i":36746,"as":"确定了大麻二酚（CBD）对α7烟碱型乙酰胆碱受体（α7 nAChR）的异位调节区域。结合单通道记录、分子动力学模拟与靶向诱变技术，发现CBD对α7通道活性产生显著抑制。其结合位点位于跨膜结构域胞外端的闭合与失活构象中，M1等位点的突变揭示了CBD调节神经与炎症受体的具体分子基础。","scd":null,"kp":[]},{"i":36747,"as":"通过汇总全球冰川栖息地数据集，发现冰川环境至少孕育了7门14纲的152种动物，其中73种为冰川特有种（如缓步动物）。这一多样性被严重低估，且在分类、生态和地理分布上存在明显偏差。研究强调冰川动物因全球变暖面临极高的灭绝风险，突出了开展保护工作的紧迫性。","scd":null,"kp":[]},{"i":36748,"as":"利用NASA大气层析任务获取的机载二氧化碳观测数据，对自上而下的大气CO2反演模型估计进行了评估与细化。研究克服了Orbiting Carbon Observatory模型中因方法局限或观测系统偏差导致的碳通量纬度划分严重分歧，为预测未来碳-气候反馈轨迹及大气CO2浓度提供了更准确的碳收支空间分布信息。","scd":null,"kp":[]},{"i":36749,"as":"研究探讨了白藜芦醇（RSV）对线虫父系线粒体消除（PME）及线粒体核酸内切酶G（EndoG）的调节作用。RSV由反式和顺式异构体组成，在光照下相互转化。令人意外的是，这两种异构体通过靶向EndoG，对PME过程表现出截然相反的调节作用，展现出调控神经退行性疾病和线粒体清除的巨大治疗潜力。","scd":null,"kp":[]},{"i":36750,"as":"利用膜片钳测序记录技术，在听觉脑干中识别出一个异质细胞群。该细胞群通过分子、生物物理和突触梯度的相互作用形成广泛的功能连续体。多级梯度的交互跨越了已知的膜时间常数全范围，构建出一个时间滤波器组，精准匹配了听觉处理相关频率的时间处理需求。","scd":null,"kp":[]},{"i":36751,"as":"DCTPP1是一种能降低DNA甲基转移酶抑制剂疗效的焦磷酸酶。研究通过高通量筛选发现了具有强效亚微摩尔活性的DCTPP1拮抗剂。X射线晶体学表征显示，这些抑制剂均占据DCTPP1的核苷酸结合口袋并与色氨酸残基结合。这些拮抗剂与DNMT抑制剂表现出协同作用，展现出癌症治疗潜力。","scd":null,"kp":["酶功能[DCTPP1]: 水解并防止甲基化碱基修饰的脱氧胞苷三磷酸错误掺入DNA","治疗靶向[DCTPP1拮抗剂]: 降解DNA甲基转移酶抑制剂 efficacy（效力）","研发方法[DCTPP1拮抗剂识别]: 高通量化学筛选"]},{"i":36752,"as":"为研究与Mtx2突变相关的早衰综合征（MADaM）的病理机制，研究人员在果蝇中构建了Mtx2基因模型。Mtx2无效突变体会导致果蝇在蛹前期致死，而通过表达果蝇自身的Mtx2（dMtx2）或人类的Mtx2直系同源物均可挽救这一致死表型，这证明了Mtx2在物种间具有功能保守性。组织特异性分析表明，Mtx2是线粒体稳态和肌肉成熟的关键调节因子。果蝇Myc的表达能够有效改善因Mtx2缺陷导致的线粒体稳态失衡和肌肉成熟障碍。","scd":null,"kp":[]},{"i":36753,"as":"","scd":null,"kp":[]},{"i":36754,"as":"研究提出了一种光触发动态聚二甲基硅氧烷（PDMS）网络设计，成功制备出具有卓越渗透汽化性能的闭环可回收分离膜。该网络利用365纳米紫外光下蒽接枝PDMS的[4+4]光环加成反应构建。当使用254纳米紫外光照射时，交联膜可转化为线性聚合物。这种解构过程在室温下35分钟内即可完成，且重构测试表明PDMS网络能够高效回收，转化率高达92.6%。该技术有效解决了传统聚合物膜的废弃处理难题，实现了低能耗分离。","scd":null,"kp":["分离膜[闭环化学回收]: 光触发的动态聚二甲基硅氧烷网络","分离膜[网络构建机制]: 蒽的[4+4]光二聚反应","分离膜[渗透汽化性能]: 表现优异"]},{"i":36755,"as":"研究探讨了一个与热浴耦合的量子系统的演化过程。传统上，该系统的演化由主方程描述，并在长时间极限下收敛于稳态密度矩阵。然而，当同一演化过程被解耦为量子轨迹时，研究人员观察到系统纠缠度随系统尺寸的标度发生转变，呈现出了纠缠相变现象。这一发现揭示了系统-浴动力学中的非平庸量子特性，发表于《物理评论快报》。","scd":null,"kp":["量子纠缠标度[幺正系统-浴动力学相变]: 随时间演化发生纠缠标度转变"]},{"i":36756,"as":"","scd":null,"kp":[]},{"i":36757,"as":"","scd":null,"kp":[]},{"i":36758,"as":"一项新实验利用非线性霍尔量子振荡，成功探测了石墨烯莫尔系统中拓扑Brown-Zak费米子的量子几何特性。研究人员通过测量非线性霍尔响应，深入分析了其中涉及的电子波函数的量子几何特征。该研究成果为理解莫尔材料中的拓扑物理和电子关联效应提供了新的实验手段，发表于《物理评论快报》。","scd":null,"kp":["非线性霍尔效应[石墨烯莫尔体系]: 存在非线性霍尔量子振荡现象","费米子[石墨烯莫尔体系]: 拓扑Brown-Zak费米子"]},{"i":36759,"as":"研究团队利用高能量分辨率的非弹性X射线散射实验结合理论计算，在单质碲（Te）中直接观测到了手性声学声子。手性声子子携带有限的声子角动量，但其在声学支中的动量分辨行为此前极少被探索。该研究实现了对单质碲中声学支手性声子的动量分辨直接探测，证实了手性声子在这一维度上的具体物理行为。","scd":null,"kp":["声子[元素碲]: 存在手性声学声子并携带有限的声子角动量","探测方法[动量分辨]: 高能量分辨非弹性X射线散射"]},{"i":36760,"as":"","scd":null,"kp":[]},{"i":36761,"as":"","scd":null,"kp":[]},{"i":36762,"as":"","scd":null,"kp":[]},{"i":36763,"as":"研究提出了一种通用构造方法，可将稳定子态作为局部哈密顿量的量子多体疤痕（QMBS）进行嵌入。量子多体疤痕因其在多体系统弱遍历性破坏中的作用而备受关注。该方法依赖于泡利弦的可分解性概念，为设计和寻找具有特定非热化行为的量子多体系统提供了理论基础。","scd":null,"kp":["量子多体疤痕[稳定子态]: 嵌入局部哈密顿量中作为量子多体疤痕","构造方法[泡利字符串]: 依赖可分解性的概念构建"]},{"i":36764,"as":"研究构建了一个用于解释质子-氘核碰撞（$pd→ppn$）中后向质子产生的模型。该模型基于单步和双步振幅的费曼图建立，涵盖了高达几个 GeV/$c$ 的质子束流动量。在这些反应机制中，包含了具有短程关联的核子以及$\\mathrm{\\Delta}(1232)$共振态作为中间散射态。该模型有效描述了累积质子产生的动力学过程。","scd":null,"kp":[]},{"i":36765,"as":"在Wentzel-Kramers-Brillouin（WKB）隧穿框架下，研究详细分析了偶偶重核和超重核$\\alpha$衰变隧穿过程中的表面结构与敏感性层级。由于$\\alpha$衰变半衰期指数依赖于有效势垒，研究揭示了核表面结构对衰变概率的决定性影响，并评估了不同核结构参数在预测超重核稳定性及实验鉴定中的敏感度差异。","scd":null,"kp":[]},{"i":36766,"as":"研究提出了一种基于PdSe2/a面GaN异质结构的新型偏振选择性紫外光突触器件。针对自然各向异性材料二色性比（DR）较弱的问题，研究人员采用了简单的预硒化处理，不仅提高了PdSe2的结晶度，还将其各向异性（DR值）显著提升至16。该异质结构器件实现了高偏振选择性和多功能的紫外光探测与突触模拟。","scd":null,"kp":["光突触器件[PdSe2/a-plane GaN异质结]: 实现偏振选择性的紫外光探测与突触多功能集成","二向色比[天然各向异性宽禁带材料]: 固有微弱且难以控制，限制探测精度"]},{"i":36767,"as":"研究利用超强碱性钴(II)酰胺Co(TMP)2（TMP = 2,2,6,6-四甲基哌啶化物），实现了对包括吡啶和二嗪在内的多种N-杂环化合物的高产率、高区域选择性直接C─H金属化。该过程通过无氧化还原的Co(II)–H交换进行，克服了传统碱引发的有机金属中间体热稳定性差的问题。此外，该反应还实现了受控的双钴化。","scd":null,"kp":["催化剂[N-杂环C-H键金属化]: 超碱性钴(II)酰胺 Co(TMP)2"]},{"i":36768,"as":"研究报道了一种磷酰基配体工程策略，用于促进金属有机框架（MOFs）在碱性海水乙醇氧化反应（EOR）过程中的界面重构。在反应期间，该策略促使MOFs转化为含有氧阴离子的金属羟基氧化物。这种结构转变在提升阳极氧化反应活性的同时，构建了有效的防氯保护层，显著增强了催化剂在碱性海水条件下的抗氯腐蚀性能。","scd":null,"kp":["催化剂[碱性海水乙醇电氧化]: 磷酸基团工程化修饰的MOF","催化剂改性机制[阳极反应界面]: 促进界面重构以同步增强抗氯腐蚀性和阳极氧化活性"]},{"i":36769,"as":"研究实现了亚甲基环己烷的非对映发散性氢酰胺化反应。对于三维结构的二取代环己烷，顺反构型决定了其热力学稳定性和生物活性。该工作利用不同的活性催化物种，在镍催化体系下，高效且精确地合成了1,4-顺/反式以及1,3-构型的环己烷衍生物，成功解决了环烷烃取代基精确立体控制的难题。","scd":null,"kp":["催化方法[亚甲基环己烷氢酰胺化]: 非对映发散性合成","产物构型[三维双取代环己烷]: 实现顺式与反式构型的精确立体化学控制"]},{"i":36770,"as":"研究利用解离电子附着（DEA）激活C─F键的机制，有效改善了金属氧簇（MOC）光刻胶在极紫外光刻中的分辨率-边缘粗糙度-灵敏度（RLS）平衡。通过室温可扩展合成方法制备了氟化锡氧簇（FPAA）光刻胶。在电子束光刻测试中，FPAA实现了9.1纳米的临界尺寸和2.2纳米的线边缘粗糙度，并支持了百克级的单批次生产。","scd":null,"kp":["光刻胶[极紫外光刻EUVL]: Sn6-oxo团簇抗蚀剂","光刻胶分辨率[电子诱导C-F键活化]: 小于10nm patterning","光刻胶合成[可扩展性]: 室温可扩展合成"]},{"i":36771,"as":"功能基团位置在分子的生物活性、材料性能和反应活性中起决定性作用。传统上，合成位置异构体需要独立且低效的合成路线。最新进展催生了功能基团易位反应，它能够在不改变分子骨架的前提下，直接将官能团从分子框架上的一个成键位置重定位到另一个位置。该技术为药物研发和材料化学中位置异构体的高效合成提供了全新途径。","scd":null,"kp":["[官能团转移技术]: 实现不改变分子骨架即可移动官能团位置"]},{"i":36772,"as":"本文评估了在TCV托卡马克中增加偏滤器封闭性对负三角度（NT）等离子体脱靶行为的影响。实验表明，在相近的线平均密度和偏滤器形状下，NT构型使得脱靶比正三角度（PT）更难实现。通过使用偏滤器气体挡板增加中性气体压力，能够有效冷却外侧靶板和外侧磁分离区。然而，在相近偏滤器压力下，带挡板的NT放电表现仍与无挡板PT存在差异。","scd":null,"kp":["[偏滤器闭合度对负三角性脱靶的影响]: 增加偏滤器闭合度会影响TCV中密度斜坡诱导的脱靶过程","[负三角性(NT)偏滤器中性压力]: 相比正三角性(PT)，NT导致脱靶更困难且中性压力更低"]},{"i":36773,"as":"本研究利用多尺度模拟，系统探讨了拉伸和压缩应变对钨等离子体面向材料中氦气泡形核与演化过程的影响。研究揭示了一个反直觉的现象：尽管各向同性拉伸应变降低了氦的溶解能，但显著增强了氦-氦间的结合能。这表明热循环产生的拉伸应变会大幅加速材料内部氦气泡的自陷、形核与长大，为理解钨材料在服役条件下的氦辐照退化机制提供了原子级别的物理见解。","scd":null,"kp":["[应变对钨中氦气泡演化的影响]: 系统研究了外部拉伸应变对氦气泡从自陷、成核、生长到长期演化基本过程的物理机制"]},{"i":36774,"as":"为满足聚变堆氚自持要求，本研究为配备氦冷陶瓷增殖剂包层的CFETR建立了22.5°环向扇区高保真中子学模型。研究开发了多物理耦合智能中子学优化代码（MCINO），该框架结合了模拟退火算法的全局探索与局部细化策略，旨在通过优化包层设计来最大化全局氚增殖比（TBR）。MCINO有效实现了中子学与工程设计的协同优化。","scd":null,"kp":["中子学模型[CFETR氦冷固态增殖剂包层]: 建立22.5°环向扇区高保真度模型","[多物理耦合与智能中子学优化]: 协调中子学与工程优化以最大化可实现的氚增殖比(TBR)"]},{"i":36775,"as":"本综述探讨了自由基介导的无张力碳碳和碳氮键断裂，将其视为骨架重编辑的设计问题。这一过程由三个相互依赖的核心要素组成：实现键断裂的官能团网关（如醇、酮、胺）、生成氧或氮中心中间体的激活模式（包括单电子转移、质子耦合电子转移、配体到金属电荷转移和电子 donor-acceptor 激活），以及决定最终产物结构的下游拦截过程。该策略成功实现了惰性环状骨架连接性的重新编程。","scd":null,"kp":["[自由基诱导无应变C-C和C-N键断裂]: 将无应变环状骨架视为可通过嵌入功能 gateway 和特定活化模式重新编程连接性的对象"]},{"i":36776,"as":"中国科学院等离子体物理研究所研制的中心螺管线圈模型（CSMC）专为满足中国聚变工程实验堆（CFETR）的工程需求而设计。其测试设施建于2023年，线圈组装于2024年完成，并在同年12月及2025年9月进行了两轮测试。目前已完成液压特性、绝缘性能（高压和帕邢测试）、接头电阻、运行电流、快速放电、交流损耗和电流分流温度等关键工况下的全面性能评估，以验证其是否满足设计要求。","scd":null,"kp":["测试时间[CFETR中心螺管模型线圈(CSMC)首轮测试]: 2024年12月29日","测试时间[CFETR中心螺管模型线圈(CSMC)第二轮测试]: 2025年9月10日"]},{"i":36777,"as":"","scd":null,"kp":[]},{"i":36778,"as":"","scd":null,"kp":[]},{"i":36779,"as":"为解决高面积容量厚电极中因沉降导致材料偏析和氧化还原不均匀的问题，本研究利用导电聚合物涂层的纳米纤维素，构建了沉降引导的氧化还原均一厚电极。改性纳米纤维素具备高电子导电性和优异离子传输能力，将粘结剂、导电添加剂和机械支架功能统一在单相网络中，消除了传统体系中的相态不均，成功实现了超高面积容量的锂离子电池。","scd":null,"kp":["[厚电极氧化还原均化技术]: 通过导电聚合物包覆的纳米纤维素构建沉降引导的氧化还原均质厚电极","[解决厚电极挑战]: 克服了电极增厚过程中由沉降引起的材料分离所导致的氧化还原异质性"]},{"i":36780,"as":"结合高压富镍正极的锂金属电池是实现超过500 Wh kg⁻¹能量密度的关键，但双电极界面的严重副反应限制了其发展。本研究提出一种基于分子电荷工程的分子编排策略，通过引入具有互补电荷需求的功能分子对，诱导电解液各组分间产生相互增强效应。该策略精确调控了溶剂化结构，实现了高压正极与锂金属负极双界面的同步稳定。","scd":null,"kp":["能量密度[高压富镍阴极锂金属电池]: 超过500 Wh/kg","[电解液设计瓶颈]: 两电极处严重的界面反应性对电解液设计提出了严格要求"]},{"i":36781,"as":"《Energy & Environmental Science》期刊借此机会感谢所有审稿人在维护化学科学文献质量和完整性方面做出的贡献，并特别表彰了该期刊在2025年度评选出的杰出审稿人。","scd":null,"kp":[]},{"i":36782,"as":"针对非晶材料中玻色峰的微观起源这一长期未解之谜，本研究通过对二维和三维玻璃的模拟证明，玻色峰源于声子与内禀弦滑振动模式之间因频率匹配而产生的强烈共振耦合。研究识别出四极准局域化模式和弦滑振动模式两类激子，后者在太赫兹频率下与声子共振产生玻色峰过剩现象。研究证实，即使不存在准局域化模式或弹性不均匀性，玻色峰依然存在。","scd":null,"kp":["[玻璃非晶材料玻色峰微观起源]: 玻色峰源于声子与内禀弦滑动振动模式之间因频率匹配而产生的强烈共振耦合"]},{"i":36783,"as":"固体氧化物电化学电池传统上仅作为独立的电解池或燃料电池运行。本文强调了在固体氧化物电化学膜反应器中利用集成法拉第与非法拉第反应并结合动态操作的新机遇。通过整合这两类反应并采用动态运行策略，可以最大化能源利用效率并显著扩展反应产物范围，突破传统仅关注材料性能的局限性。","scd":null,"kp":["[固体氧化物电池反应器运行强化]: 结合法拉第与非法拉第反应及动态运行，以最大化能量利用率并扩展产物范围"]},{"i":36784,"as":"本研究开发了一种集成在光纤尖端上的单像素光电探测器件，能够同时分辨光的模式、偏振、波长和强度。该器件基于二维黑磷和黑砷磷的扭曲二向色性层及环形光栅电极，可产生空间依赖的响应。通过生成六种截然不同的光响应信号，成功实现了光的四维参数检测，解决了传统光学检测系统依赖庞大光学器件将信号分束至多个探测器的复杂问题。","scd":null,"kp":["光探测设备[光纤尖端单像素器件]: 能够同步分辨光的模式、偏振、波长和强度","光信号检测机制[多参数解析]: 避免了传统系统将信号分割到多通道和多光电探测器的复杂庞大光学元件"]},{"i":36785,"as":"本研究开发了一种无线供电、光控并可生物吸收的电刺激系统。该系统利用可吸收的硅光电晶体管，通过组织穿透性近红外光精确调制电路节点处的电流。系统不仅能将单相、双相和多相波形传输至单个或多个靶点，还能在完成神经再生和心脏起搏等临床电疗后，在体内无害溶解，克服了传统系统仅能输出单相脉冲的局限。","scd":null,"kp":["电刺激波形控制[无线可降解硅基系统]: 使用组织穿透性近红外光进行可编程控制（支持多相脉冲波形）","治疗系统特性[生物可降解电刺激系统]: 能够在临床相关时间段内提供电疗，随后以无害方式溶解"]},{"i":36786,"as":"","scd":null,"kp":[]},{"i":36787,"as":"","scd":null,"kp":[]},{"i":36788,"as":"","scd":null,"kp":[]},{"i":36789,"as":"本研究利用包含228个国家、130项技术的5990个国家级时间序列历史技术采用数据集（HATCH），分析了技术和国家特征对技术扩散速度的影响。研究发现，技术的增长率存在显著差异：较新、更简单、标准化程度高、规模小、物质密集度低且使用寿命较短的技术扩散速度更快。这表明较小规模的技术将更快速地推动温室气体减排所需的转型。","scd":null,"kp":["数据集规模[HATCH技术历史采用数据集]: 包含跨越130种技术和228个国家的5990个国家级时间序列"]},{"i":36790,"as":"","scd":null,"kp":[]},{"i":36791,"as":"","scd":null,"kp":[]},{"i":36792,"as":"本研究利用阶梯式热解/氧化分析和同位素端元混合模型，分析了南极半岛西部两个由不同基岩构成的峡湾沉积物中的有机碳。结果显示，由沉积岩构成的峡湾具有比火山岩主导的峡湾高十倍的岩石有机碳埋藏通量。南极半岛西部峡湾的生物有机碳埋藏通量估计为6.1-8.8 Gg C yr⁻¹，岩石有机碳为0.3-3.1 Gg C yr⁻¹，证实流域岩性是决定该区域碳净平衡的关键因素。","scd":null,"kp":["有机碳表征方法[南极半岛流域]: 采用分级热解/氧化分析与同位素端元混合模型进行沉积有机碳调查"]},{"i":36793,"as":"本研究表明，气候变暖通过多尺度改变海洋环流，加速并扩大了北冰洋河水及漂浮物质的扩散。海冰减少和上层海洋密度降低加强了海洋涡旋活动，风生环流改变导致波弗特环流从一个区域水库转变为泛北极辐合区。该转变使其能够高效聚集来自西伯利亚的河流衍生物质，使西冰洋成为漂浮物质的枢纽。","scd":null,"kp":[]},{"i":36794,"as":"为解决光热电站运行成本高和新兴技术采用慢的问题，本研究推出遵循FAIR原则的开放数据库PAINT。该数据库提供来自Jülich太阳能塔式电站长达数年、总容量达849 GB的高分辨率运行数据，涵盖定日镜特性、标定与偏折测量以及精细化气象数据。数据库采用时空资产目录元数据规范组织，为聚光太阳能技术的集成与研究提供支持。","scd":null,"kp":["运行数据库[聚光太阳能塔式电站]: 遵循FAIR原则的开放获取数据库（PAINT）"]},{"i":36795,"as":"本研究合成了一系列由[FeIII2MII(μ3-O)]簇组成的金属有机框架（USTC-12-Fe2M），用于15% CO2气氛下的光催化还原。其中USTC-12-Fe2Mn表现出极高的CO2转化为CO的速率（约16.1 mmolCO·gcatalyst−1·h⁻¹），CO选择性达95%，表观量子效率为2.66%。实验证实铁为真实活性中心，光照下CO2被μ3-O原子捕获并在铁位点上预活化形成*c-CO32-中间体，实现了稀CO2的光催化捕集与还原。","scd":null,"kp":["CO2还原转化率[15% CO2气氛下的USTC-12-Fe2Mn催化剂]: 约16.1 mmolCO·gcatalyst−1·h−1","CO选择性[15% CO2气氛下的USTC-12-Fe2Mn催化剂]: 95%","表观量子效率[可见光 irradiation]: 2.66%","催化剂活性位点[光催化CO2还原]: 铁元素(Fe)为真实活性中心"]},{"i":36796,"as":"本研究在光子晶体微腔中实现了一种紧凑的光学多稳态。通过工程化设计一对光谱接近的超高品质因子共振，利用共享辐射通道引入非厄米耦合，驱动共振达到具有近简并波长和相等品质因子的近异常耦合点。这种结构设计显著降低了多稳态阈值，克服了光学非线性弱和自由光谱范围大带来的技术挑战，为片上多级光存储器件的应用奠定基础。","scd":null,"kp":["光学多稳态实现条件[紧凑型微腔]: 通过工程化设计一对光谱相近的超高（近奇异耦合）微腔实现"]},{"i":36797,"as":"研究发现一种含部分占据原子的方钠石结构材料（CASO）。该材料在11 K至893 K的温度范围内表现出各向同性零热膨胀（ZTE），热膨胀系数极低（0.21×10−6 K−1）。这种宽温域ZTE行为源于配体原子振动增强引发的横向振动，有效抵消了固有的正热膨胀，同时保持了结构完整性。","scd":null,"kp":["热膨胀系数[方钠石结构晶体Cd4Al6O12SO4]: 0.21(23) × 10−6 K−1","零热膨胀温区[同构零热膨胀材料]: 11 K 至 893 K"]},{"i":36798,"as":"研究提出一种异手性设计策略，通过在胰高血糖素和甲状旁腺激素N端片段PTH(1–34)的特定位置用d-α-氨基酸残基替换l-α-氨基酸残基，破坏其螺旋构象。生成的异手性类似物在受体激活能力（cAMP生成）上接近全l型肽，可作为两种B1类GPCR的高效偏向性激动剂，相关肽包括用于治疗糖尿病低血糖和骨质疏松的药物。","scd":null,"kp":[]},{"i":36799,"as":"为解决电子断层扫描（ET）数据匮乏导致的深度学习应用受限问题，研究提出了一种通用的数据驱动ET三维重建框架。该框架利用随机高熵投影构建大规模数据集，整合真实结构先验和深度相关的成像物理学。该策略不依赖特定材料或分辨率，已成功用于确定13纳米铂纳米颗粒的三维原子结构。","scd":null,"kp":["电子断层扫描重建框架[数据驱动的通用型ET]: 使用大量易于获取的随机高熵投影来构建大训练集以解决数据稀缺问题"]},{"i":36800,"as":"","scd":null,"kp":[]},{"i":36801,"as":"","scd":null,"kp":[]},{"i":36802,"as":"研究组装了两种海洋水母（P. utriculus和Porpita porpita）的染色体级基因组。研究发现P. utriculus的神经和肌肉基因家族发生显著收缩，Hox1基因的缺失与其缺失自由生活水母阶段直接相关（敲除Hox1会导致水母发育异常）。P. utriculus依靠充满气体的浮囊和带毒触手来适应海气界面生存。","scd":null,"kp":[]},{"i":36803,"as":"","scd":null,"kp":[]},{"i":36804,"as":"","scd":null,"kp":[]},{"i":36805,"as":"使用多电极阵列研究发现，对上皮细胞单层（人类角质形成细胞和MDCK细胞）进行局部激光损伤会触发电压峰值。这些电信号持续超过60分钟（4至12次/分钟），具有去极化、复极化和超极化阶段，持续时间（1-2秒）比神经元动作电位慢三个数量级。距损伤位点740微米处仍能检测到可比拟的信号，且呈现非单调的空间分布特征。","scd":null,"kp":["电压峰值频率[上皮细胞单层局部激光损伤]: 4至12次/分钟","电压峰值持续时间[上皮细胞单层]: 1至2秒","放电时序特征[上皮细胞电峰值]: 比神经元慢三个数量级"]},{"i":36806,"as":"","scd":null,"kp":[]},{"i":36807,"as":"","scd":null,"kp":[]},{"i":36808,"as":"杜氏肌营养不良症（DMD）是一种导致严重肌肉无力的X连锁致命疾病。现有的常用DMD小鼠模型（mdx）虽具有相同的遗传病因，但未能完全表现出人类患者的症状。DMD-Null小鼠模型则表现出严重的肌肉无力、再生受损以及肌肉卫星细胞功能缺陷，为研究DMD的发病机制与治疗提供了有效的动物模型。","scd":null,"kp":["发病率[杜氏肌营养不良症男性群体]: 1/5000"]},{"i":36809,"as":"","scd":null,"kp":[]},{"i":36810,"as":"胆固醇合成的两种关键酶HMG CoA还原酶（HMGCR）和角鲨烯单加氧酶（SM）受内质网相关降解（ERAD）途径调控。研究发现，在缺乏胆固醇的细胞中，HMGCR和SM会形成稳定的复合物。HMGCR的加速降解通过Insig蛋白介导，而SM的降解通过E3连接酶MARCH6以非Insig依赖的方式介导。该机制介导了这两个胆固醇合成控制点之间的交联对话。","scd":null,"kp":["限速步骤[胆固醇合成HMG CoA转化为甲戊酸]: 第一步限速步骤"]},{"i":36811,"as":"","scd":null,"kp":[]},{"i":36812,"as":"","scd":null,"kp":[]},{"i":36813,"as":"利用自旋极化中子衍射实验直接证实了在金属螺旋磁体YMn6Sn6中通过电场直接控制磁手性的现象。此前，电场控制手性仅在绝缘多铁性螺旋磁体中得到证实。该研究展示了金属螺旋磁体中无需大电场即可实现手性控制的技术，为探索依赖手性的自旋电子学功能特性开辟了新途径。","scd":null,"kp":[]},{"i":36814,"as":"组织损伤引发的再生过程高度依赖光合作用产生的蔗糖。研究发现，切除根尖的再生呈剂量依赖性，虽然蔗糖被排斥在损伤部位之外，但活体葡萄糖报告基因显示葡萄糖在切口处大量积累。这种积累需要由伤口迅速诱导的质外体糖运输组件（细胞壁转化酶CWINV和糖转运蛋白STP）的参与，从而为组织修复提供能量。","scd":null,"kp":[]},{"i":36815,"as":"研究通过融合两种C2对称的纠缠基序（p53dim和HP0242），成功在细胞内计算设计和合成了一对蛋白质拓扑异构体。通过特定的排列和环化程序编码多重交叉，分别生成了蛋白质所罗门结和蛋白质三扭结。这种利用化学拓扑维度设计非平凡蛋白质架构的方法，赋予了蛋白质更高的稳定性和丰富的动力学特性。","scd":null,"kp":[]},{"i":36816,"as":"研究发现由TIR结构域NAD酶活性产生的小分子能够促进ADR1家族辅助NLR蛋白 recruited 入EDS1-PAD4复合物中执行效应子触发的免疫（ETI）。该EDS1-PAD4-ADR1信号节点不仅参与ETI，还与SOBIR1相关联，是LRR-RP受体介导的模式触发免疫（PTI）所必需的。这证实了EDS1/PAD4小分子结合位点在双层免疫系统中的核心作用。","scd":null,"kp":[]},{"i":36817,"as":"TP53肿瘤抑制因子编码的转录因子能调控数百个靶基因。在小鼠模型中识别出包括p21、Gtse1、Eda2r和Puma（Bbc3）在内的p53依赖性转录特征。研究通过生成Gtse1和Eda2r的等位基因，详细调查了这些基因与介导细胞凋亡的Puma基因在p53活性下游的生理作用及功能相关性。","scd":null,"kp":[]},{"i":36818,"as":"介绍了一种任务无关的框架，用于基于动力学的经验时间序列来估算系统执行的计算量。该框架通过对动力学进行统计重构，并根据复杂性和保真度来定义计算量。经验证，该框架能够有效区分动态系统执行的计算量相对大小。","scd":null,"kp":[]},{"i":36819,"as":"揭示了细菌共生体和植物病毒通过诱导物理防御增强昆虫适应性的机制。烟粉虱感染立克次氏体和植物双生病毒均与寄生真菌白僵菌的感染呈负相关。双生病毒通过触发烟粉虱体内几丁质合成途径基因的表达，赋予其对寄生真菌的抗性，从而提升宿主的生存适合度。","scd":null,"kp":[]},{"i":36820,"as":"探讨了微管稳定剂配体如何重塑微管晶格组织。通过X射线纤维衍射证实，不同配体选择性稳定了两种纵向构象，即紧凑态（单体上升约4.06 nm）和扩张态（约4.17 nm）。研究解答了不同配体类别是否诱导特定晶格状态的机制问题。","scd":null,"kp":[]},{"i":36821,"as":"提出通过基因疗法恢复内质网与线粒体互作以治疗腓骨肌萎缩症2A型（CMT2A）。CMT2A由MFN2基因突变引起，导致线粒体动力学异常及内质网-线粒体接触破坏。研究证实，在神经元中过表达野生型MFN2（MFN2_WT）能够有效恢复细胞器互作并改善疾病表型。","scd":null,"kp":[]},{"i":36822,"as":"开发了一种基于双发射荧光团的实时可视化蛋白质液滴成熟方法。通过合成带有吸电子环的香豆素基荧光团，实现了对液-液相分离形成的蛋白质液滴逐渐失去流动性并成熟为纤维状态的实时监控，为研究相分离过程提供了高通量技术手段。","scd":null,"kp":[]},{"i":36823,"as":"","scd":null,"kp":[]},{"i":36824,"as":"","scd":null,"kp":[]},{"i":36825,"as":"","scd":null,"kp":[]},{"i":36826,"as":"通过动态模型证实，细菌代谢而非死体物质主导了土壤有机碳的输入。研究发现，渗出物和代谢废物对细菌来源的有机碳输入贡献相当（中位数均为10%），胞外酶贡献15%，死体物质贡献49%。总体而言，6%的有机输入以细菌代谢物形式释放到土壤中。","scd":null,"kp":["贡献率[细菌代谢渗出物对土壤有机碳输入]: 约10%","贡献率[细菌代谢废弃物对土壤有机碳输入]: 约10%"]},{"i":36827,"as":"","scd":null,"kp":[]},{"i":36828,"as":"首次系统测定了糖类中单个醇基团的氢键供给能力（HBDC），并建立了适用于药物化学的HB标度。利用排除氢键协同效应的甲基α-葡萄糖苷和α-半乳糖苷模型化合物，通过红外光谱法证实了不同糖醇基团的氢键供给能力存在广泛差异。","scd":null,"kp":["氢键供体能力[α-葡糖苷和α-半乳糖苷羟基]: 首次实现系统量化排序"]},{"i":36829,"as":"开发了一种安全合成间位氟化吡啶的新方法。自1947年以来，传统合成方法依赖危险的吡啶重氮盐，容易引发爆炸事故。该新方法基于1,3-断开策略成功规避了重氮盐的使用，提供了一条安全的合成替代路线。","scd":null,"kp":["[间位氟化吡啶合成新工艺]: 基于1,3-断键策略的安全替代方法，避免了危险的吡啶基重氮盐"]},{"i":36830,"as":"提出分子转子增强的孔空间划分（MR增强PSP）策略，用于提升金属有机框架材料在一步分离乙烯过程中的性能。通过在典型MIL-88框架的开放金属位点插入孔道划分剂，成功实现了孔环境的协同优化，有效应对了乙炔/乙烷/乙烯三元混合物的一步纯化挑战。","scd":null,"kp":["分离挑战[三元乙炔/乙烷/乙烯混合气]: 一步法乙烯纯化"]},{"i":36831,"as":"开发了一种利用X射线和机械力在CsCaCl3中选择性还原稀土离子Ln3+至Ln2+的新策略。基于12种Ln3+离子的还原电位，实现了特定Ln2+离子（如还原电位较低的Eu）的高效还原，从而获得了优于Ln3+的优异发光效率和光谱可调性。","scd":null,"kp":["[Ln3+/Ln2+价态转变]: X射线和机械力诱导的价态转变及发光"]},{"i":36832,"as":"通过在Co3O4载体上引入超高密度的铱单原子，构建了具有丰富Ir-Ir协同对的催化剂，用于高效酸性析氧反应。电化学测试表明，该结构克服了传统单原子催化剂中单原子密度低和协同作用受限的缺点，显著提升了催化活性。","scd":null,"kp":["[酸性析氧反应(OER)单原子催化剂]: 具有协同作用的超高密度Ir-Ir相邻单原子对"]},{"i":36833,"as":"提出一种微阶梯状（100）晶面耦合分子层工程，解决水系锌碘电池在宽pH和海水电解液中的界面问题。该结构引导锌物种均匀分布，通过氢键降低界面水活性，物理阻断氯离子和多碘化物的迁移，有效抑制了钝化层形成、腐蚀和枝晶生长。","scd":null,"kp":["[水系锌碘电池界面工程]: 耦合分子层工程的微阶梯(100)晶面结构"]},{"i":36834,"as":"开发了一种偏析工程的Si/Pd-Cu光阴极，通过纳米级相偏析诱导双级界面极化，实现了无偏压合成尿素。富Cu偏析促进光生电子提取，富Pd区域暴露的极化位点协同稳定了CO2和NO3-中间体，成功克服了两者还原过程中的动力学不匹配难题。","scd":null,"kp":["[无偏压光电合成尿素]: 偏析工程极化同步实现CO2与硝酸盐还原"]},{"i":36835,"as":"提出一种光学可编程超表面方法，利用Ge2Sb2Te5（GST）的可逆相变特性实现了太赫兹波前的编码控制。该方法有效克服了现有电学超表面的局限，实现了二维、非易失性、宽带且高分辨率的太赫兹波前控制，推动了太赫兹动态器件的发展。","scd":null,"kp":["[GST超表面]: 光学可编程、非易失性、宽带及高分辨率的二维太赫兹波前控制"]},{"i":36836,"as":"报道了一种“四重氢键封端”策略，用于开发本征可拉伸和自修复的半导体聚合物。通过在聚合物骨架中引入四重氢键，构建的超分子架构提高了结晶度并减小了π-π堆积距离，在保持分子有序性的同时赋予了材料优异的拉伸性和增强的链流动性。","scd":null,"kp":["[本征可拉伸与可愈合半导体聚合物]: 采用四重氢键封端策略整合高载流子迁移率与拉伸/愈合性能"]},{"i":36837,"as":"提出了一种受蛋白质结构启发的生物模拟聚合物集成电解质策略。基于聚(N-丙烯酰基甘氨酰胺)的富酰胺基团，通过强大的类蛋白分子间N-H...O=V相互作用锚定钒氧化物，有效抑制了锌离子电池中钒的溶解，稳定了阴极框架结构并保持了结构完整性。","scd":null,"kp":["[安时级锌离子电池钒基正极]: 引入仿生N─H···O═V键合和聚N-丙烯酰基甘氨酰胺(PNAGA)聚合物电解质，解决水系电解液中M-O键不稳定导致的结构退化与容量衰减"]},{"i":36838,"as":"针对微生物人工光合作用中光生电子非选择性转化导致的能量耗散问题，研究提出利用核黄素（RF）作为生物相容性光敏剂，将光能选择性转化为细胞内NADPH再生的合理策略。量子化学计算和光谱分析表明，光激发的核黄素对NADP+具有特定的结合亲和力且有利的电子转移趋势。","scd":null,"kp":["[微生物人工光合作用]: 采用核黄素(RF)作为生物相容性光敏剂，实现选择性光生电子路由，定向进行胞内能量转移"]},{"i":36839,"as":"研究设计并构建了一种基于卷曲氧化物/过渡金属硫族化合物（TMDCs）高阶超晶格的忆阻器。通过精细控制的氧等离子体原位氧化形成四种异质结构，利用有机试剂中的毛细管力驱动其自发卷曲。该器件表现出可调的电阻开关极性和高开关比，克服了单操作模式和开关比不足的性能限制。","scd":null,"kp":["[卷曲氧化物/TMDCs异质结构高阶超晶格忆阻器]: 具备可调阻变极性和高开关比"]},{"i":36840,"as":"研究人员利用分子动力学模拟，研究了固定拓扑聚合物网络中自由链的平衡动力学，借此测试缠结聚合物动力学与流变学中长期作为基石的管模型。研究结果揭示了该模型的一些关键概念，为聚合物拓扑摩擦动力学提供了深入见解。","scd":null,"kp":["[固定拓扑聚合物网络拓扑摩擦]: 利用分子动力学模拟自由链平衡动力学验证管状模型的关键概念"]},{"i":36841,"as":"研究采用压力施加流变学，对经历粘性-惯性转变的致密摩擦悬浮液进行了颗粒解析模拟。通过改变流体粘度、剪切速率和颗粒压力，证明了这种转变发生在斯托克斯数约为8时。结果表明，切向力在控制该转变中起着决定性作用。","scd":null,"kp":["粘滞-惯性转变斯托克斯数[稠密摩擦悬浮液]: ≈8"]},{"i":36842,"as":"在间接驱动惯性约束聚变（ICF）中，压缩聚变燃料构型的面密度不对称性是已知的性能限制因素。研究提出在目标设计中利用烧蚀丸进行面密度对称性控制。虽然国家点火设施（NIF）已实现点火，但内爆对称性并不完美，该研究致力于解决这一限制聚变性能的核心问题。","scd":null,"kp":["[间接驱动惯性约束聚变靶丸设计]: 利用烧蚀靶丸进行面密度对称性控制"]},{"i":36843,"as":"研究实现了基于激光等离子体加速器（LPA）驱动的高增益区种子自由电子激光（FEL）。经过近二十年的尝试，研究人员克服了阻碍FEL产生激光的电子束质量和稳定性问题，在自放大和种子注入两种模式下成功演示了基于LPA的FEL技术。","scd":null,"kp":["[高增益区激光等离子体加速器驱动的种子自由电子激光]: 成功实现自放大自发辐射和种子放大模式的激射"]},{"i":36844,"as":"光学频率梳在传感应用中至关重要，其性能已达到由相干光场量子涨落决定的标准量子极限。研究提出了量子梳增强干涉测量理论，利用量子梳突破标准量子极限，为传感技术的进一步发展提供了理论依据和性能提升方案。","scd":null,"kp":["[量子梳增强干涉测量]: 突破相干光场标准量子极限的传感性能"]},{"i":36845,"as":"量子非高斯态（无法写成高斯态的混合）是在连续变量系统中实现量子优势的必要条件，也是评估先进量子光源的重要基准。研究提出了一种基于光子相关性g(2)和g(3)的量子非高斯性判据，用于精准评估无法通过简单手段（如单光子叠加）制备的量子光源特性。","scd":null,"kp":[]},{"i":36846,"as":"","scd":null,"kp":[]},{"i":36847,"as":"使用密度泛函微扰理论和Migdal-Eliashberg计算，研究证明了BiSe、PbSe、PbS和HgS等金属单硫族化合物在高压下的超导性是由声子介导的。这一普遍机制推翻了此前将这些材料的高压超导归因于无序驱动的安德森局域化的观点。","scd":null,"kp":["超导机制[压缩金属单硫属化物(BiSe, PbSe, PbS, HgS)]: 普遍的声子介导超导性(超越安德森局域化)"]},{"i":36848,"as":"基于高维纠缠的贝尔不等式测试通常需要能够分辨多个结果的测量。研究实现了一种无需二值化漏洞的高维量子非局域性观测。该方法摆脱了传统上通过一系列“有/无”测量来模拟高维多结果测量的限制，成功实现了对高维量子非局域性的无漏洞验证。","scd":null,"kp":[]},{"i":36849,"as":"传统理论预测，非相互作用电子系统（如三维拓扑绝缘体表面态）与普通s波超导体邻近耦合可实现拓扑超导。该研究则提出，当朗道能级与s波超导体耦合时，排斥相互作用也可以驱动产生拓扑超导性，为拓扑超导的机制提供了新的视角。","scd":null,"kp":["拓扑超导性机制[朗道能级耦合s波超导体]: 由排斥相互作用驱动"]},{"i":36850,"as":"","scd":null,"kp":[]},{"i":36851,"as":"研究提出了一种可高效应用于大型费米系统的局部量子冷却框架。该方法引入局部厄米特算符作为冷却势，同时严格保留了时间演化的幺正性。该冷却方法的计算效率随系统尺寸具有优异的扩展性，并考虑了费米系统中的配对效应。","scd":null,"kp":[]},{"i":36852,"as":"","scd":null,"kp":[]},{"i":36853,"as":"","scd":null,"kp":[]},{"i":36854,"as":"","scd":null,"kp":[]},{"i":36855,"as":"","scd":null,"kp":[]},{"i":36856,"as":"","scd":null,"kp":[]},{"i":36857,"as":"量子近似优化算法（QAOA）的性能随电路深度p的增加而单调提高，但现有精确评估技术的指数级成本阻碍了高深度机制的研究。研究证明了，在无限深度极限下，QAOA可以映射为自旋-玻色子模型，为探索和评估深度QAOA提供了新的理论工具。","scd":null,"kp":["QAOA算法评估[无限深度p极限下]: 采用自旋-玻色子映射技术(克服传统精确评估随p指数级增加的成本)"]},{"i":36858,"as":"研究发现锑（Sb）可作为维度调节剂，实现具有原子精度的稳定三维钯-锑（Pd-Sb）纳米团簇的形成。通过反热力学方法引入Sb，选择性地扰动平面Pd-S配位，同时保留Pd-Pd连接，成功合成了[Pd13Sb2(PPh3)2(S-Adm)]纳米团簇，从而增强了催化性能。","scd":null,"kp":["维度调控机制[Pd纳米团簇催化]: 锑(Sb)选择性扰动平面Pd-S配位并保留Pd-Pd连接性","催化剂改性[钯纳米团簇]: 锑(Sb)作为维度调节剂实现维度重编程"]},{"i":36859,"as":"提出了一种使用偶极矩约为1.9德拜的添加剂来抑制溶剂化中间体的平衡分子相互作用策略，以实现无反溶剂的高性能α-FAPbI3钙钛矿太阳能电池。通过系统审查带有不同基团的对称二甲基间苯二甲酸酯（DMIP）衍生物，解决了无反溶剂制造中缓慢成核和不均匀生长的问题。","scd":null,"kp":["结晶调控策略[无反溶剂常规α-FAPbI3钙钛矿太阳能电池]: 采用具有适中偶极矩的平衡分子相互作用抑制溶剂化中间体"]},{"i":36860,"as":"构建了一种动态有机-无机互穿纳米网络（DIN），以解决结构材料中刚性与耐用柔韧性之间的矛盾。通过无机离子低聚物的聚合，将无机纳米网络互穿到有机网络中。该DIN在外力作用下展现出网络间动态可逆键合，成功整合了两种相互矛盾的性能。","scd":null,"kp":["材料结构[柔性与高强度结构材料]: 动态有机-无机互穿纳米网络(通过无机离子低聚物聚合实现)"]},{"i":36861,"as":"首次在电池研究中将两种工业上成熟的氟化醚（通常用作传热流体） identified 为局部高浓度电解液（LHCEs）的有效共稀释剂。这些成分具有宽广的电化学稳定性窗口、低粘度和固有的不燃性。将其掺入后，获得了更安全、不易燃且离子迁移率增强的电解液配方。","scd":null,"kp":["电解液共稀释剂[局部高浓度电解质(LHCEs)高倍率锂金属电池]: 两种工业级氟化醚(作为传热流体协同稀释剂以增强安全性和离子传输动力学)"]},{"i":36862,"as":"提出了一种催化缩聚策略，直接从糠醛和胺类合成高性能树脂。在氯化铵催化下，通过席夫碱中间体将呋喃环转化为吡咯环，经历芳香性破坏、氮原子掺入和芳香性重建过程。构建了多取代吡咯交联网络，展现出优异的热稳定性（450°C分解）和阻燃性（极限氧指数31.7%）。","scd":null,"kp":["[高性能树脂合成策略]: 直接以糠醛和胺为原料，通过氯化铵（NH4Cl）催化缩聚，经席夫碱中间体将呋喃环转化为吡咯环构建交联网络"]},{"i":36863,"as":"提出一种结合分子轨道工程与界面水网络控制的双调控策略，用于高选择性电合成过氧化氢（H2O2）。以镍酞菁为平台，通过扩展π共轭结合极性甲氧基（-OCH3），克服了自旋禁阻的O2活化和缓慢的质子耦合电子转移挑战，实现了基于双电子氧还原反应的高效合成。","scd":null,"kp":["[电催化合成H2O2反应体系]: 双电子氧还原反应（2e−ORR）","[催化剂设计策略]: 调节酞菁镍的分子轨道与界面水结构，以打破自旋禁阻的O2活化与迟缓的质子耦合电子转移限制"]},{"i":36864,"as":"设计并合成了具有A型几何骨架的Aethrene衍生物2。该化合物在Clar结构中嵌入了含苯环的烯丙基自由基，并在锯齿状边缘引入 bulky 空间位阻取代基。衍生物2在室温和光照条件下的半衰期达到15.5天，展现出高自旋自由基的优异稳定性及独特电子结构。","scd":null,"kp":["[高自旋自由基]: 具有独特电子结构和磁性，适用于有机电子学和自旋电子学，但高效合成与选择性分离极具挑战","[Aethrene衍生物设计]: 具有A型几何骨架和三重态基态的稳定多环芳烃"]},{"i":36865,"as":"通过在碳纳米管或氮化硼纳米管内封装前体分子，成功实现表面合成，将其转化为均匀的0.6纳米宽扶手椅型石墨烯纳米带（GNRs）。研究发现，包含五元、七元或八元环的非六边形芳香烃分子同样能产出仅由六元环组成的均匀GNRs，展现出对分子和主材料的广泛容忍度。","scd":null,"kp":["石墨烯纳米带宽度[扶手椅型]: 0.6 nm","[石墨烯纳米带合成工艺]: 表面合成技术，将多种前驱体分子封装在碳纳米管或氮化硼纳米管内，通过聚合和脱氢环化实现大规模精准合成"]},{"i":36866,"as":"为解决水系锌硫电池的容量衰减问题，设计了具有独特硫/ZnS双重亲和力的纳米铜基阴极电解质界面相（Cu CEI）。Cu CEI通过优先的Cu-ZnS结合，加速S-S和Zn-S键动力学，有效阻止ZnS积累并抑制其分解。强结合力稳定了ZnS，减少了其与界面水的直接接触。","scd":null,"kp":["[水系Zn-S电池界面工程]: 构建具有硫/ZnS双重亲和力的纳米铜基正极/电解质界面（Cu CEI），从根本上解决氧化驱动的ZnS分解导致的容量衰减问题"]},{"i":36867,"as":"","scd":null,"kp":[]},{"i":36868,"as":"基于双温、非线性全磁流体力学（MHD）模型，利用JOREK代码研究了ASDEX Upgrade（AUG）托卡马克中等离子体芯部磁通泵浦的自调节机制。模型定量复现了等离子体芯部钳制的电流密度和安全因子分布，证实了发电机效应在维持磁通泵浦状态中的有效性。","scd":null,"kp":["[ASDEX Upgrade等离子体磁流体力学建模]: 采用双温、非线性全磁流体力学（MHD）模型结合JOREK代码，研究磁通泵浦过程中锯齿无螺旋宁静态下环向电流密度和极向磁通量的径向反常重分布自调节机制"]},{"i":36869,"as":"提出一种基于介电摩擦调控的高熵共晶电解液（HEEE），成功实现锂金属电池在150°C下的长期稳定运行。HEEE内结构多样的阴离子创造了无序介电环境，破坏了介电极化弛豫的长程协同作用，降低了介电摩擦对Li+传输的阻碍，抑制了枝晶生长并促进了富无机物的固体电解质界面形成。","scd":null,"kp":["工作温度[高熵共晶电解液Li金属电池]: 150°C","[高熵共晶电解液作用机理]: 结构多样的阴离子创造无序介电环境，破坏介电长程协同作用，调节介电摩擦以实现电池的长期稳定运行"]},{"i":36870,"as":"EX-Fusion公司建立了XF-COLR设施，成功演示了针对自由落体目标（1毫米不锈钢球）的10赫兹多激光束跟踪与照射。系统利用多束纳秒和飞秒激光，在环境条件下连续运行长达12小时，真空下运行2.5-3分钟。真空条件下1500次照射的水平方向跟踪标准差达到121-139米。","scd":null,"kp":["重复频率[激光多束转向与照明]: 10 Hz","自由落体靶直径[快点火惯性聚变能反应堆演示]: 1 mm（不锈钢球）"]},{"i":36871,"as":"提出了一种结合特征提取和半监督一致性分类的数据高效学习与可迁移评估（DELTA）框架，用于锂离子电池制造的早期质量分级。该框架以寿命终止时的循环寿命作为质量评价指标，评估了来自6个公开数据集、包含421个电池的数据，有效降低了长周期测试和密集标记的能源与时间成本。","scd":null,"kp":["[锂离子电池制造质量分级]: 提出数据高效学习与可转移评估（DELTA）框架，结合特征提取，克服传统长循环测试和密集标签带来的高能耗、时间成本和可扩展性受限问题"]},{"i":36872,"as":"提出了一种数据高效的深度学习代理模型TGLF-WINN，用于托卡马克中的湍流输运建模。该网络采用波数知情机制，通过原理性特征工程减小目标预测范围，并引入物理引导的波数分辨正则化，有效降低了对大型训练数据集的依赖，加速了全装置模拟中的推理过程。","scd":null,"kp":["[托卡马克湍流输运建模]: 构建TGLF-WINN深度学习代理模型，以可微分近似提供加速推理，解决全装置模拟中捕捉等离子体条件下输运通量变化的大数据集训练负担问题"]},{"i":36873,"as":"利用MEGA代码对大型螺旋装置（LHD）中的混合模拟显示，快离子储存能达到稳态后，阿尔芬本征模（AEs）的爆发幅度显著增加，导致快离子损失率上升。模拟得到的AE频率与实验吻合，且多快离子物种相互作用会激发单一物种无法产生的额外AEs。","scd":null,"kp":["[多快离子物种驱动Alfvén本征模]: 采用MEGA代码进行混合模拟，研究多种快离子与磁流体相互作用的协同效应","AE爆发幅度[快离子储能达稳态后]: 大于稳态前"]},{"i":36874,"as":"实验证实了在正交磁镜场中发生高速对撞融合时，能够自组织形成类场反位形（FRC）的高β等离子体团。在FRTC装置中，线积分密度为(1-1.5)×10^20 m^-2的两个氘等离子体团被加速至约150 km/s并以300 km/s的相对速度合并，该几何结构保留了磁镜的两端以供反应堆组件使用。","scd":null,"kp":["[磁场反转高β等离子体团自组织形成]: 两个等离子体团沿垂直于磁场镜轴线的方向高速对撞融合（正交融合）","[传统磁场反转构型保持]: 正交融合几何可保留磁场镜轴向两端用于反应堆相关应用"]},{"i":36875,"as":"本综述探讨了高负载电催化电极的合理设计，提出从静态多尺度集成向动态智能系统转变的新范式。该范式整合了动态可重构材料、仿生自适应架构和智能界面，构建出能够感知、适应和自我优化的智能电极系统，从而协同提升高电流密度下的催化活性、稳定性和传质能力。","scd":null,"kp":["[高负载电催化电极设计范式]: 从静态多尺度集成转向动态智能系统，以匹配动态变化的微环境和高电流密度"]},{"i":36876,"as":"设计了一种基于溶剂吸电子化学的分子策略，通过碳酸盐溶剂的分步氟化，打破了钠离子电池快充上限。该策略促进了FSI⁻阴离子的优先还原并降低了脱溶剂化能，使基于硬碳阳极的安时级全电池在7分钟内实现超快充电，并具有1800次循环的稳定寿命。","scd":null,"kp":["[传统碳酸盐电解液快充倍率上限]: 约3C","[突破钠离子电池SEI膜限制策略]: 基于溶剂吸电子化学的分子设计"]},{"i":36877,"as":"利用神经网络智能优化设计了多尺度阻抗梯度超器件，实现了超宽带微波吸收和可编程多光谱伪装。该器件集成了聚酰亚胺泡沫基底与MXene功能化光致变色纳米顶层，在2-18 GHz频段内实现出色的微波吸收（不敏感角度达60°），同时具备显著的红外隔热（ΔT 65°C）性能。","scd":null,"kp":["[多光谱兼容超材料器件设计]: 采用神经网络驱动智能优化多尺度阻抗梯度（IG）设计","[宏观梯度单元]: 具备精确阻抗匹配和高旋转对称性"]},{"i":36878,"as":"","scd":null,"kp":[]},{"i":36879,"as":"当前物理学界对基本粒子数量的估计范围从17个到995.5个不等。此外，一名瘫痪患者已能够在家庭环境中成功使用脑机接口技术；同时，GLP-1肥胖症药物被证实能够提升睾酮水平和精子质量。","scd":null,"kp":["[基本粒子数量估计]: 17到995.5个之间"]},{"i":36880,"as":"玻璃形成液体在冷却时通常表现出偏离斯托克斯-爱因斯坦关系的现象，这与动态异质性有关。针对非普适幂律解耦指数缺乏预测性理论理解的问题，研究在多种模拟玻璃形成系统中，确定了质量扩散系数与剪切粘度之间的幂律关系。","scd":null,"kp":["[玻璃形成液动态异质性表征]: 质量扩散系数与动量扩散系数之间存在幂律关系（分数Stokes-Einstein关系）"]},{"i":36881,"as":"摩擦电可穿戴传感器可将人体机械刺激转化为自适应机器功能，在医疗保健和人机交互系统领域极具应用潜力。此类传感器具备自供电特性，并能以皮肤接触或纺织品集成等多种可穿戴形式作为智能电子系统的下游交互平台。","scd":null,"kp":["[人机交互摩擦电可穿戴传感器]: 直接转换人体机械刺激且具备自供电能力"]},{"i":36882,"as":"","scd":null,"kp":[]},{"i":36883,"as":"","scd":null,"kp":[]},{"i":36884,"as":"研究通过分析特提斯洋安尼阶的碳同位素、汞浓度及汞同位素数据，揭示了中三叠世生物复苏期碳和汞循环的扰动事件。锆石U-Pb年代学测定将培尔森负碳同位素偏移（PENCIE）的持续时间精确限制在约50万年（约244.2至243.45 Ma）。同期的汞富集由同位素证实源于增强的区域性火山活动和陆地输入共同驱动。","scd":null,"kp":["[压电陶瓷巨大电弯曲变形]: 场致排列氧空位锚定策略构建织构通道与应变失配"]},{"i":36885,"as":"","scd":null,"kp":[]},{"i":36886,"as":"半导体量子点自旋量子比特具有高相干时间和门保真度。研究利用原位色散读出技术实现了对自旋量子比特晶胞的单次读出。该晶胞包含两个具有可控交换相互作用的电子自旋，自旋可见度达80.7%，成功演示了初始化、单次读出和双电子纠缠门操作。","scd":null,"kp":["[半导体量子点自旋量子比特]: 具备长相干时间和高门保真度","[自旋量子比特单次读out]: 采用原位色散读出技术实现小型化晶圆制造单元电池读出"]},{"i":36887,"as":"研究利用互补金属氧化物半导体（CMOS）芯片成功实现了DNA的并行酶促合成。该芯片包含256对环形电极，每个电极对均为可编程合成位点。系统成功并行合成了多达64种不同的38至39个核苷酸序列，为高通量合成生物学和DNA数据存储提供了安全且易于获取的方案。","scd":null,"kp":["DNA合成[环境与安全性]: 亚磷酰胺合成依赖有害溶剂，酶促合成在水溶液中进行更安全"]},{"i":36888,"as":"二氧化碳光电解转化为液体燃料的过程在扩大规模时面临多重工程障碍。综述指出，通过在反应器架构、照明控制和产物管理等方面的技术进步，有望构建实用的太阳能转化燃料系统，从而实现产出浓缩液体产品的目标。","scd":null,"kp":["太阳能到燃料转换系统[工程化规模放大]: 需克服反应器架构、光照控制和产物管理方面的工程障碍以实现浓缩液体产物"]},{"i":36889,"as":"","scd":null,"kp":[]},{"i":36890,"as":"","scd":null,"kp":[]},{"i":36891,"as":"","scd":null,"kp":[]},{"i":36892,"as":"","scd":null,"kp":[]},{"i":36893,"as":"","scd":null,"kp":[]},{"i":36894,"as":"","scd":null,"kp":[]},{"i":36895,"as":"人工智能代理能够自主为电子设备生成全生命周期清单，在不到一分钟的时间内完成从原材料提取到废弃处理全过程的评估，并计算碳排放量。该技术的评估结果与专家人工评估的偏差低于19%，大幅降低了传统数据收集的时间成本。","scd":null,"kp":["生命周期清单生成时间[AI智能体自动化]: 少于1分钟","碳排放估算偏差[AI智能体与专家评估对比]: 小于19%"]},{"i":36896,"as":"研究开发了一种由2-乙基-2-恶唑啉聚合物配制的纳米级STING激动剂NanoCF501。该纳米颗粒可实现高效粘液穿透和局部呼吸道滞留，避免全身毒性。在小鼠实验中，将其与多价冠状病毒抗原片段结合鼻内给药，成功引发了强效的粘膜与全身免疫，提供针对泛β-冠状病毒的广泛保护。","scd":null,"kp":["佐剂配方[纳米颗粒STING激动剂]: 由2-乙基-2-噁唑啉聚合物配制的NanoCF501","给药剂量[小鼠鼻腔共同给药NanoCF501]: 全身剂量的1/20","药代动力学特征[大鼠体内]: 促进高效粘液穿透和局部呼吸道保留，最小化全身暴露"]},{"i":36897,"as":"研究结合大规模单神经元记录与自然语言处理模型，绘制了人类语言产生过程中的神经元表征。结果显示，人类额颞皮层中的部分神经元负责表征词汇间的语法关系或词性，而另一些神经元则追踪句子的高阶句法结构，揭示了语言能力的微观细胞基础。","scd":null,"kp":["[人类语言微观细胞基础研究]: 结合大规模单神经元记录与自然语言处理模型来识别语言皮质图谱"]},{"i":36898,"as":"","scd":null,"kp":[]},{"i":36899,"as":"大型语言模型在临床决策中潜力巨大，但亟需整合到电子健康记录（EHR）系统中。研究开发了名为MIRA的自主人工智能代理，在沙盒化的EHR环境中运行。MIRA能够浏览庞大的临床操作空间，自主获取患者病史、开具医嘱并解释化验结果，展现出处理患者病例的医师级操作能力。","scd":null,"kp":["[医疗AI智能体系统要求]: 必须在电子健康记录(EHR)内运行，具备受管制的患者数据访问权限，并在安全约束下启动允许的EHR操作"]},{"i":36900,"as":"电子维格纳固体是理解电子相互作用的核心系统。研究结合原子级分辨扫描隧道显微镜（STM）与神经量子态量子蒙特卡洛（NQS-QMC）模拟技术，对无序二维电子维格纳固体进行了观测，成功克服了缺乏单缺陷分辨率实验测量的限制，发现了由无序性诱导的相关电子行为新物理状态。","scd":null,"kp":["[二维电子维格纳固体研究方法]: 结合原子级分辨扫描隧道显微镜以克服单缺陷分辨实验测量的缺乏"]},{"i":36901,"as":"斑马鱼利用近期经验指导未来选择。全脑钙成像技术揭示了一个控制历史偏向决策的专属神经回路：丘脑将最近的事件维持为稳定的神经元活动模式，而脑干则将近期的经验整合为连续信号，从而直接驱动和偏向未来的行为动作。","scd":null,"kp":["[历史偏好决策神经回路]: 丘脑将最近事件维持为稳定的神经元活动模式，脑干将近期的经验整合为连续信号以偏向未来行动"]},{"i":36902,"as":"一种双药组合疗法被证实能够降低小鼠的新陈代谢并扩张血管，从而在小鼠体内诱发低温状态（低体温症）。这种通过药物实现的冷却效应能够有效限制和减轻小鼠中风造成的脑损伤。","scd":null,"kp":["[小鼠低温症诱导]: 双药组合通过降低代谢和扩张血管来诱导低温症以限制中风损伤"]},{"i":36903,"as":"","scd":null,"kp":[]},{"i":36904,"as":"","scd":null,"kp":[]},{"i":36905,"as":"研究利用数据非依赖型采集质谱技术，对2856个样本中的13000多种蛋白质进行分析，构建了全面的人类蛋白质组图谱。该数据集涵盖58种主要组织类型、251种特定组织亚型和25种不同癌症，展示了胎儿、肿瘤、邻近非肿瘤及健康成人组织等多种状态下的蛋白质空间分布轨迹。","scd":null,"kp":["蛋白质分析样本数[人类蛋白质组图谱]: 超过13,000种蛋白质跨越2,856个样本","组织覆盖范围[人类蛋白质组图谱]: 涵盖58种主要组织类型、251种特定组织亚型和25种不同的癌症","检测方法[蛋白质组空间分布]: 数据非依赖性采集质谱法(DIA-MS)"]},{"i":36906,"as":"一台基于囚禁离子的量子计算机具备高度的可重构性，能够连接任意两个量子比特。该系统成功操控了98个量子比特，其达到的运行性能水平已经超越了传统计算机所能企及的极限。","scd":null,"kp":["量子比特数[可重构离子阱量子计算机]: 98","连通性[量子比特]: 任意两个量子比特均可连接"]},{"i":36907,"as":"","scd":null,"kp":[]},{"i":36908,"as":"欧盟宣布计划停止在化学安全测试中使用动物。为达成这一目标，欧盟需要制定明确的时间表，并投入大量资金支持相关的替代技术研发和推广。","scd":null,"kp":["[欧盟化学品安全测试]: 计划终止使用动物实验，并需明确时间线与资金支持"]},{"i":36909,"as":"","scd":null,"kp":[]},{"i":36910,"as":"","scd":null,"kp":[]},{"i":36911,"as":"","scd":null,"kp":[]},{"i":36912,"as":"","scd":null,"kp":[]},{"i":36913,"as":"","scd":null,"kp":[]},{"i":36914,"as":"研究人员结合机器学习势分子动力学、路径积分模拟、元动力学和核磁共振波谱，研究了胆碱-氨基酸质子离子液体中的质子转移动力学。结果表明，质子迁移在多种瞬态溶剂化结构中发生，其中Zundel样质子共享二聚体的比例显著高于水溶液系统。","scd":null,"kp":[]},{"i":36915,"as":"LucaVirus是一个针对病毒的多模态基础模型，基于涵盖绝大多数已知病毒多样性的254亿个核苷酸和氨基酸标记进行训练。该模型能够学习序列、同源性和进化分歧之间的生物学关系，可用于识别未知病毒、注释蛋白质功能、预测病毒进化能力以及为新兴病毒寻找抗体候选者。","scd":null,"kp":["训练数据规模[LucaVirus多模态大模型]: 254亿个核苷酸与氨基酸Token"]},{"i":36916,"as":"研究人员通过将计算机视觉的核心基础操作嵌入到光学超表面（一种操控光线的平面材料）中，开发出一种通用人工智能视觉系统。原型设备能够实现跨任务的准确实时感知与处理，为快速、低能耗的设备端视觉智能提供了解决方案。","scd":null,"kp":["[AI视觉系统]: 将计算机视觉基础操作嵌入光学超表面实现快速、低功耗的片上实时感知与预处理"]},{"i":36917,"as":"","scd":null,"kp":[]},{"i":36918,"as":"研究人员通过脑机接口临床试验，利用微电极阵列记录了8名瘫痪患者的数据，以单神经元分辨率绘制了人类运动皮层（中央前回）的综合图谱。该图谱覆盖了包含大量前运动皮层的广泛区域，详细揭示了全身在运动皮层中的表征分布。","scd":null,"kp":["映射精度[人类运动皮层(中央前回)]: 单神经元分辨率","微电极阵列数[人脑全身映射]: 20个阵列"]},{"i":36919,"as":"","scd":null,"kp":[]},{"i":36920,"as":"","scd":null,"kp":[]},{"i":36921,"as":"对印尼棕榈油行业1541户农户和53个供应链参与者的调查表明，零毁林承诺（ZDC）市场的准入主要取决于农户是否处于公司采购区内，主动排斥现象有限。基于认证的参与覆盖了部分绑定农户，但农户对ZDC的认知度依然较低，政策传达薄弱。","scd":null,"kp":["调查样本量[印尼油棕小农零毁林承诺]: 1541个农户家庭","访谈样本量[供应链参与主体]: 53个"]},{"i":36922,"as":"","scd":null,"kp":[]},{"i":36923,"as":"IBM苏黎世研究院的杰出科学家探讨了忆阻器件在内存计算领域的应用机遇与挑战。这类新型器件被视为突破传统计算瓶颈的关键技术，并具备广阔的商业化潜力。","scd":null,"kp":["[忆阻器件]: 具有存内计算潜力并面临商业化机遇与挑战"]},{"i":36924,"as":"基于大语言模型（LLM）的代理系统在多访视临床管理和对话中得到优化。该系统结合长上下文检索和结构化推理，将输出与最新的临床实践指南和药物处方集对齐，在随机、双盲的虚拟临床客观结构化考试中展现出卓越的疾病管理推理能力。","scd":null,"kp":["[大模型智能体(AMIE)]: 针对多就诊临床管理与对话进行优化，具备疾病进展、治疗反应及安全开药推理能力"]},{"i":36925,"as":"","scd":null,"kp":[]},{"i":36926,"as":"","scd":null,"kp":[]},{"i":36927,"as":"","scd":null,"kp":[]},{"i":36928,"as":"","scd":null,"kp":[]},{"i":36929,"as":"","scd":null,"kp":[]},{"i":36930,"as":"","scd":null,"kp":[]},{"i":36931,"as":"为克服传统光镊受力受限和机械镊子精度不足的缺陷，研究人员研发了一种三维（3D）光纤镊子（OFG）。该技术将微型镊子直接集成在光纤末端，能够在狭窄空间内对微物体（如单个细胞）进行高性能的三维精准操控。这种新型光纤集成技术打破了现有架构和尺寸的限制，为微观操作提供了新的解决方案。","scd":null,"kp":["[光纤微夹具]: 将微夹具直接集成在光纤上，以克服传统光镊力域受限和机械镊子精度不足的难题，实现高性能3D微操纵"]},{"i":36932,"as":"超长基线原子干涉仪旨在探测地基和天基激光干涉仪失去敏感度的频段内的引力波和超轻暗物质，其性能高度依赖于对噪声源（尤其是激光相位噪声）的抑制。研究展示了一种基于单光子钟跃迁的差分原子干涉仪原型。该实验验证了噪声抑制能力，为解决超长基线原子干涉仪中激光相位噪声等关键挑战提供了技术途径。","scd":null,"kp":["[长基线原子干涉仪]: 通过对比广泛分离的原子系综的量子相位演化来探测引力波和超轻暗物质"]},{"i":36933,"as":"研究利用纯化酵母蛋白重构了前起始复合物，并通过冷冻电镜揭示了CMGE解旋酶的组装过程。结构显示了装配因子组装两个对称CMGE的动态过程。研究表明，复合物的分步形成重塑了MCM以准备DNA解链，并解释了ATP如何促进装配因子排离和CMGE成熟。Sld2在此过程中发挥了促进作用。研究结果阐明了DNA双向复制的起始机制。","scd":null,"kp":[]},{"i":36934,"as":"Quantinuum推出了名为Helios的98量子比特囚禁离子量子处理器。该处理器基于量子电荷耦合器件（QCCD）架构，采用137Ba+超精细量子比特，具备全连接特性。该平台在无需基态冷却的情况下实现了99.99%的门保真度。这项研究解决了在扩大量子比特数量的同时保持高保真度操作的难题。","scd":null,"kp":["量子比特数[Quantinuum Helios捕获离子量子计算机]: 98个","连接性[捕获离子量子计算机]: 全连通","门保真度[无基态冷却]: 99.99%"]},{"i":36935,"as":"研究揭示了细胞区分功能性（输出至细胞质）与非功能性（在核内降解）多聚腺苷酸化RNA（pA+ RNA）的分子机制。功能性pA+ RNP核心成分UAP56促进其对接至核孔复合物锚定的TREX-2以实现输出。研究发现，多聚腺苷酸尾外切酶靶向（PAXT）连接复合物能够结合类似TREX-2的模块，释放pA+ RNA脱离UAP56，进而引发其在核内的降解，从而决定RNA的命运。","scd":null,"kp":[]},{"i":36936,"as":"气候变暖导致的冻土融化会释放大量有机碳并转化为二氧化碳排放，但同时也加速了矿物风化。在青藏高原的研究表明，岩石风化作用能够抵消冻土融化引起的河流CO2排放。综合CO2排放、有机与无机溶质浓度、双碳同位素及地球化学模型分析发现，在冻土退化的几十年至几个世纪内，生物与地质碳循环的相互作用调节着冻土区河流的CO2动态。","scd":null,"kp":[]},{"i":36937,"as":"通过对11种自闭症单基因小鼠模型在三个发育阶段进行单核多组学测序，发现尽管自闭症致病基因存在高度异质性，但这些突变均汇聚于放射状胶质细胞谱系的扰动。这种扰动表现为短暂的发育迟缓而非永久性的谱系错误，并在出生后阶段恢复正常。分子层面上，早期出生后神经元转录差异最大，表现为突触和离子通道相关基因表达下调。","scd":null,"kp":[]},{"i":36938,"as":"研究开发了一种利用中红外出面双曲极化激元（oHPs）的非侵入式光学检测方法，实现了对范德华材料层间皮米级形变的定量表征。以六方氮化硼为原型，该方法利用层间应变诱发的出面横向光学声子软化机制进行探测。此技术成功解决了范德华材料界面处极微小面外应变难以进行定量检测的挑战。","scd":null,"kp":["[范德华材料界面隐埋形变]: 可通过中红外出面双曲极化激元实现皮米尺度的无损定量表征"]},{"i":36939,"as":"在Cr掺杂的拓扑绝缘体三明治结构中，利用量子反常霍尔（QAH）相的手性边缘态，在一维科宾诺链中实现了具有明确手性的非厄米电导矩阵。通过将边界条件从周期性调整为开放性，揭示了非厄米趋肤效应，即本征态在边界呈指数级局域化。这证明了磁性掺杂拓扑绝缘体在实现非厄米动力学方面的应用潜力。","scd":null,"kp":[]},{"i":36940,"as":"MTCH2是线粒体外膜插入酶家族的核心成员。冷冻电镜结构显示，人类MTCH2演化出插入酶活性是由于丧失了一条跨膜螺旋，从而形成了一条由其C端稳定的亲脂性凹槽。突变分析表明，凹槽内残基的疏水性、电荷和大小调控着MTCH的功能。该研究阐明了MTCH家族的结构演化机制，并借此识别出植物外膜的插入酶。","scd":null,"kp":[]},{"i":36941,"as":"研究利用空间转录组学技术绘制了发育中的小麦花序转录图谱。鉴定出两个调控小麦小穗结构的不同空间区域：一个是特征基因为RAMOSA2的原始体区域，另一个是边界区域。这些区域间的基因互作共同决定了小穗的形成、排列模式以及分生组织和穗轴等支持结构的发育。该结果揭示了控制麦穗形态和产量构成的分子机制。","scd":null,"kp":[]},{"i":36942,"as":"基因组证据表明，地球最后的共同祖先（LUCA）具备将铵离子导入细胞的基因，但拥有完整氮气催化固定基因的生物在10亿年后才出现。利用尿素和腈类获取氮的酶促途径也早于生物固氮作用。这说明生命起源后的最初几亿年里，早期生态系统依靠热液活动、光化学等环境非生物源提供的铵及其他含氮化合物来维持运转。","scd":null,"kp":[]},{"i":36943,"as":"结合量子气体显微镜和约束路径辅助场量子蒙特卡洛计算方法，研究了掺杂且自旋不平衡的吸引力哈伯德模型，在实验可及温度下对短程相关性的结果达成了定量一致。研究确定了FFLO（有限动量配对）相关性涌现的密度和磁化广阔区域，证实了有限动量配对的清晰特征在实验可及的温度下已经出现，推进了对二维系统中非常规超流态的探测。","scd":null,"kp":[]},{"i":36944,"as":"利用实时含时密度泛函理论（rt-TDDFT）研究了VO2中的双脉冲激光激发方案。揭示了利用相干与非相干动力学控制相变的机制，提出了两条更节能的相变路径：其一，微弱的初始脉冲诱导V-V二聚体相干振荡，在拉伸时施加第二个脉冲使带隙瞬间变窄，降低相变阈值；其二，利用该复杂动力学机制可实现更加高效的能量利用。这为通过多脉冲激发实现可控相变提供了理论依据。","scd":null,"kp":["[超快激光双脉冲激发VO2]: 能够控制相变过程中的相干与非相干动力学，提出更具能效的相变方案"]},{"i":36945,"as":"化学合成研究打破了延续百年的经典分子结构、成键规则与反应性理论。这一突破使得涉及酰胺和反布雷特烯烃的全新合成化学成为可能，为创新分子合成路径提供了重要途径。","scd":null,"kp":["[化学合成]: 突破经典结构、成键和反应性规则，实现了涉及酰胺和反布雷特烯烃的新合成化学"]},{"i":36946,"as":"超嗜热古菌的生物基质蛋白AbpX能够响应钙离子并在无分子伴侣参与下发生聚合。在体外和重组条件下，AbpX通过供体链互补（DSC）机制组装成由半柔性纤维组成的类结晶晶格。冷冻电镜分析表明，该蛋白聚合形成的超结构热稳定水凝胶，展现了极端环境下微生物独特的结构适应性机制。","scd":null,"kp":["生物基质蛋白[超嗜热古菌Pyrodictium abyssi来源AbpX]: 响应钙离子并形成热稳定水凝胶"]},{"i":36947,"as":"体内CRISPR筛选证实抗坏血酸转运蛋白Slc23a2是初始T细胞反应的关键调节因子。Slc23a2缺失会降低细胞内抗坏血酸水平，导致局部DNA高度甲基化，促使初始T细胞向效应和记忆细胞分化，加剧低度自身免疫炎症。这种表型与TET双加氧酶缺乏及衰老类似。机制上，Slc23a2通过抗坏血酸维持TET酶活性，从而控制初始T细胞的反应性和外周免疫耐受。","scd":null,"kp":[]},{"i":36948,"as":"研究揭示了水稻中控制开花时间的关键因子OsFKF1、OsGI和Hd1之间的相互作用机制。OsFKF1是一种含有F-box结构域的蛋白，能够与OsGI和Hd1发生物理相互作用。OsFKF1通过泛素化介导的26S蛋白酶体途径靶向并降解OsGI。此外，OsFKF1在功能上与拟南芥中的FKF1具有保守性。这些发现阐明了OsFKF1通过调控OsGI的降解来控制水稻开花时间的具体分子机制。","scd":null,"kp":[]},{"i":36949,"as":"研究利用54个非衰竭心肌组织样本（涵盖发育、成年和衰老阶段，共442,239个细胞核）构建了单核RNA测序图谱。研究发现，人类心脏在生命周期中经历连续的转录重编程，所有主要细胞类型均表现出渐进的基因表达稳态丧失、应激反应和炎症信号激活。心肌细胞呈现出富含衰老和疾病相关特征的独特年龄依赖性转录状态。此外，调控网络分析揭示了控制这一过程的细胞特异性机制。","scd":null,"kp":[]},{"i":36950,"as":"研究解决了线粒体内铜离子运输的关键未解之谜，阐明了SLC25A3在其中的核心作用。研究发现，SLC25A3不仅负责将铜离子导入线粒体基质，还负责将基质中的铜离子导出到膜间隙，用于细胞色素c氧化酶（CcO）的金属化修饰。通过使用铜离子载体elesclomol（ES），研究证实SLC25A3的缺失会导致线粒体铜含量和CcO活性降低，并证实其对于防止铜死亡（cuproptosis）至关重要。","scd":null,"kp":[]},{"i":36951,"as":"研究开发了一种名为“超构陶瓷”（metaceramic）的单片超材料陶瓷，突破了传统热整流器在高温稳定性和非线性热响应之间的基本权衡。该材料具有多尺度分级孔隙率架构，集成了四种非线性传热机制：离子调节传导、空腔调制辐射、混沌对流增强对流和自发对流散热。该超构陶瓷实现了创纪录的8.0热整流比，且能在超过900开尔文的超高温环境下稳定工作，为极端环境下的热管理提供了新方案。","scd":null,"kp":["工作温度上限[传统热整流器]: 低于900 K","整流比上限[传统热整流器]: 低于3.5","[超高温热整流与3D热控]: 通过单晶超材料陶瓷打破高温稳定性与非线性热响应的权衡限制"]},{"i":36952,"as":"研究揭示了秀丽隐杆线虫在化学趋向性导航中采用状态切换策略的机制。线虫的导航行为由“转向”（微小航向改变）和“转弯”（大幅度重新定向）组合而成。通过测量和构建统计模型，研究发现这些行为要素之间的转换不仅由外部感官输入驱动，还受到持续内部状态的调控。这种状态依赖性的控制模型解释了线虫如何在转弯后能够直接朝向目标定向，展示了内部状态与感官输入结合在寻路策略中的关键作用。","scd":null,"kp":["[秀丽隐杆线虫趋化性导航]: 结合“转向”（小航向改变）和“转弯”（大方向重定位），其状态切换策略受内部状态和感觉输入共同驱动"]},{"i":36953,"as":"研究通过结合大量和空间转录组学分析，揭示了聚乙烯（PE）微塑料诱导肝毒性的分子机制。在喂食标准饮食或代谢功能障碍相关脂肪性肝炎（MASH）诱导饮食的小鼠中，PE暴露导致肝脏功能障碍。这种损伤引发了全局和空间上截然不同的转录组改变，特别是涉及核受体Ppara与Anxa2之间的串扰。这些发现明确了微塑料生物积累对肝脏代谢和解毒功能的破坏途径。","scd":null,"kp":[]},{"i":36954,"as":"研究开发了一种具有16个独立传感元件的单片机器学习气体传感器芯片，用于气味检测和食品分类。该芯片采用碳纳米管场效应晶体管（CNT-FET）作为高灵敏度基底，通过兼容自动移液系统的单步微分配方法进行功能化修饰，构建了完全异质化的传感层阵列。该系统能够针对特定物体的气味特征产生特征信号模式，结合机器学习算法，成功克服了传统气体传感器材料重叠导致的高相关性响应问题，提升了检测的分类能力与可扩展性。","scd":null,"kp":["气体传感器阵列[单片集成芯片]: 包含16个完全不同传感层的异质阵列"]},{"i":36955,"as":"研究阐明了桑属植物中桑呋喃（moracin）类天然产物的生物合成途径。利用热蛋白质组学技术，研究鉴定出一种来自桑树（Morus alba）的非典型漆酶MaLAC。该酶能够催化氧化白藜芦醇发生分子内氧化环化反应，生成桑呋喃共同中间体——桑呋喃M（moracin M）。这是首次发现植物漆酶能够催化天然产物生物合成中的分子内氧化环化反应。机制研究表明，该过程是一个铜介导的自由基环化反应。","scd":null,"kp":[]},{"i":36956,"as":"研究发现NEDD化修饰途径对维持卵母细胞质量至关重要。在小鼠中，卵母细胞特异性敲除NEDD化激活复合物的催化亚基编码基因Uba3会导致不育。Uba3条件性敲除的完全生长卵母细胞表现出严重的线粒体功能障碍，包括活性氧水平升高、氧化磷酸化受损以及线粒体编码RNA转录本的耗竭。蛋白质组学分析显示，线粒体基质和呼吸链相关蛋白发生显著改变，证实了NEDD化通过稳定线粒体转录来维持卵母细胞的生理机能。","scd":null,"kp":[]},{"i":36957,"as":"研究在室温多铁性材料Co取代的BiFeO3（BiFe0.9Co0.1O3）纳米点中实现了电场诱导的铁电和铁磁畴变化。该材料具有共存的铁电序和弱铁磁序，且自发磁化与铁电极化相耦合。利用压电响应力显微镜等技术，研究展示了通过铁电拓扑畴翻转来实现电场控制的磁畴改变。这种伴随极化翻转的磁化反转现象，为开发低功耗、非易失性、电压写入和磁性读取的存储器应用提供了关键的技术途径。","scd":null,"kp":["室温多铁性材料[钴取代BiFeO3]: BiFe0.9Co0.1O3","[BiFe0.9Co0.1O3纳米点]: 铁电极化拓扑畴切换诱导铁磁畴变化，实现电场诱导的磁化反转"]},{"i":36958,"as":"针对骨关节炎（OA）进展中软骨细胞线粒体受损的问题，研究开发了一种功能化凋亡囊泡（apoVs）递送系统。通过席夫碱反应，将能够特异性结合软骨细胞的核酸适配体tgg2偶联到间充质干细胞来源的apoVs上（tgg2@apoVs），构建了可注射的缓释系统。该系统有效解决了apoVs靶向性差和关节腔内滞留时间短的问题。功能化的apoVs能够靶向软骨细胞并恢复其线粒体的氧化磷酸化（OXPHOS）水平，从而改善软骨基质稳态，为骨关节炎治疗提供了新策略。","scd":null,"kp":[]},{"i":36959,"as":"研究通过在纳米晶CoAl金属间化合物中引入非晶界面框架（FAIs）和预制位错，成功克服了其室温本征脆性。微柱压缩测试表明，该结构展现出超过6吉帕的高屈服强度，持续加工硬化至约8.5吉帕，且压缩塑性应变超过15%。非晶界面框架能够适应纳米晶CoAl晶粒的塑性变形，防止沿晶断裂，同时促进位错的发射和运动。该机制协同增强了金属间化合物的强度与塑性，为其作为先进结构材料的应用提供了新结构设计思路。","scd":null,"kp":["增韧结构[纳米晶CoAl金属间化合物]: 引入非晶界面框架(FAIs)和预存位错","[非晶界面框架与预存位错]: 协同增强材料的强度与塑性"]},{"i":36960,"as":"针对肝细胞癌（HCC）的免疫治疗难题，研究开发了一种掺杂缺陷工程化锰基钙钛矿压电纳米立方体（Mn-BaZrO3, MBZO）的生物仿生递送系统。该系统整合在肿瘤来源的纳米囊泡中，并装载了丹参酮类似物miltirone。在同源靶向HCC细胞后，MBZO通过压电催化效应产生外源性活性氧，而miltirone进一步加速氧化应激放大。该系统通过平行激活PANoptosis（焦亡-凋亡-坏死性凋亡）和STING通路，重塑了免疫微环境，成功将“冷肿瘤”转化为“热肿瘤”，实现肿瘤消退。","scd":null,"kp":[]},{"i":36961,"as":"研究分析了美国西部热浪与野火活动之间的联系，发现2001至2024年间，42%的过火面积发生在热浪期间或热浪刚过之后。热浪通过加剧气象和燃料易燃性条件，促进了新的点火并加剧了正在进行的火灾，使得每日过火面积显著增加，且该影响在大多数地区的热浪结束后依然持续。此外，热浪还伴随云对地闪电的增加，进一步提高了点火几率。自2001年以来，美国西部森林的过火面积已增加2.5倍。","scd":null,"kp":[]},{"i":36962,"as":"研究明确了转录因子NPAS3在小鼠大脑星形胶质细胞中对线粒体生物能学的关键调节作用。NPAS3在星形胶质细胞中高表达，其缺失会导致线粒体谷氨酸载体2（参与谷氨酸氧化）的表达下降，进而引起星形胶质细胞内的氧化磷酸化和乳酸产量减少。这种星形胶质细胞的代谢缺陷会进一步降低神经元的固有兴奋性和树突复杂性。研究结论表明，NPAS3调控的星形胶质细胞线粒体能量代谢是维持正常认知功能所必需的。","scd":null,"kp":[]},{"i":36963,"as":"","scd":null,"kp":[]},{"i":36964,"as":"","scd":null,"kp":[]},{"i":36965,"as":"研究揭示了过饱和度（特别是其时间演化）在离子发光体反溶剂扩散过程中对分子手性表达的调控机制。通过调节扩散条件，相同的离子对发光体可以产生两种截然不同的组装路径。当系统达到临界过饱和阈值时引发成核，随后的生长路径取决于过饱和度随时间的维持方式。当反溶剂扩散快速完成并转变为蒸发时，通过精确控制过饱和度的演化，能够合成具有跨多尺度层级手性表达的合成材料。","scd":null,"kp":["动力学参数[离子发光体反溶剂扩散组装]: 过饱和度及其时间演化","[过饱和度控制组装路径]: 指导多尺度层级手性表达"]},{"i":36966,"as":"","scd":null,"kp":[]},{"i":36967,"as":"研究观测并利用了自由飞行微粒的多普勒编码米氏散射效应。通过在反谐振空芯光纤中使用光驱动微米级颗粒，研究克服了传统散射检测中数据采集时间短和运动引起图像模糊的限制，观察到多普勒编码的米氏散射彩虹现象。基于此发现，研究引入了一种横向多普勒光谱方法，实现了对自由飞行单颗粒的高精度计量。该成果为光与物质相互作用的基础研究以及现代单颗粒计量学提供了全新的技术手段。","scd":null,"kp":["[多普勒编码米氏散射]: 实现对自由飞行粒子的精确分析"]},{"i":36968,"as":"","scd":null,"kp":[]},{"i":36969,"as":"研究利用欧亚大陆东部30个草地生态系统的240个观测数据，量化了不同干旱程度下土壤食物网的能量通量。结果显示，干旱加剧导致整个食物网的总能量通量下降，主要由物种丧失和营养相互作用减弱引起。其中，基于草食作用的“绿色”通道能量通量下降幅度明显大于基于微生物摄食的“棕色”通道，这种能量重分配预测了草地碳储量的变化。","scd":null,"kp":["样本量[欧亚大草原土壤食物网]: 横跨温带和高原30个生态系统的240个观测点","[干旱诱导的能量重分配]: 能量从绿色食物网转移到棕色食物网，预测草地碳储量"]},{"i":36970,"as":"研究在海洋三角褐指藻中开发了全基因组CRISPR/Cas9筛选技术，以探索硅藻在动态光照环境中的生存机制。通过对突变体文库在不同光照条件（包括高光和波动光）下进行筛选，研究鉴定出使硅藻在营养丰富的混合海洋环境中茁壮生长的关键基因，加速了对硅藻特有生物学的理解。","scd":null,"kp":["筛选技术[三角褐指藻动态光适应]: 全基因组CRISPR/Cas9筛选"]},{"i":36971,"as":"","scd":null,"kp":[]},{"i":36972,"as":"","scd":null,"kp":[]},{"i":36973,"as":"研究展示了一种片上全电气检测平台，能够同时解析入射矢量涡旋光束的轨道角动量（OAM）阶数和偏振态。该平台通过将范德华层状热电材料与相位梯度超光栅耦合，把OAM和偏振信息空间映射到表面等离激元极化激元的强度分布上。这种无需滤波器的全电气直接解码技术成功实现了对矢量涡旋光束的检测。","scd":null,"kp":[]},{"i":36974,"as":"研究利用具有10微赫兹Schawlow-Townes线宽、运行在基态量子噪声极限下的共腔双色布里渊激光器作为参考，开发了超高效的光学分频（OFD）系统。该系统克服了传统系统中光学参考受热噪声和技术噪声影响的限制，采用简化的分频器实现了10^17量级的空前分频系数，成功产生了10千兆赫兹的微波信号，具有极低的相位噪声。","scd":null,"kp":["激光线宽[光学分频参考源]: μHz级别的肖洛-汤斯线宽","[光频分频(OFD)]: 采用共腔双色布里渊激光器作为参考，突破热噪声与技术噪声限制"]},{"i":36975,"as":"研究开发了一款名为NWUS的无引线、自粘性薄膜神经刺激器。该装置能够顺应性包裹在细小神经干上，通过避免身体运动引起的导线微小位移，防止脆弱的神经受损。作为一种超声响应声电转换器，NWUS具有优化的阻抗匹配功能，能够实现高效的无线神经调控，为不治之症提供精准的电生理治疗应用。","scd":null,"kp":["神经刺激器[NWUS设备特征]: 无线、自粘合薄膜结构，可保形包裹细小神经干","[超声神经调控器件]: 解决脆弱神经干长期稳定神经调控的工程挑战"]},{"i":36976,"as":"针对聚合物复合膜报废回收的难题，研究提出了一种基于阶段的物理化学回收策略。该策略通过顺序溶剂萃取、催化解聚和膜重铸，实现了多组分回收和复合膜的闭环再生。使用真实的报废膜为原料，该工艺生产出的再生膜在机械稳健性和分离性能上均可媲美商业产品，生命周期评估证明了其可持续性优势。","scd":null,"kp":["回收策略[聚合物复合膜]: 基于阶段的物理-化学回收机制","[多组分复合膜回收]: 实现多组分回收与闭环再生"]},{"i":36977,"as":"为应对气候变化下复杂的水循环监测挑战，研究提出了BERTH（水文学双向编码器表征）端到端人工智能框架。该框架彻底改变了依赖区域特定经验参数的多阶段模型，直接将遥感辐射率转换为蒸散发、降水、土壤湿度和径流数据，实现了30米空间分辨率和每日时间尺度的全球陆地水循环监测。","scd":null,"kp":["遥感观测模型[当前技术缺陷]: 依赖特定区域经验参数且多阶段工作流，无法稳健处理高时空分辨率的复杂加速水循环"]},{"i":36978,"as":"研究采用功能导向的祖先序列重构策略，成功重建了双功能祖先黄素酶AncFO-221。该酶能够在单一活性位点内将黄素依赖性氧化脱胺和拜耳-维立格氧化两个独立机制整合，直接实现胺到酯的转化。实验与计算分析揭示，在统一的催化框架下，组氨酸辅助的质子和氢化物转移促进了该催化循环且不发生相互干扰。","scd":null,"kp":["双功能黄素酶[催化特性]: 能够在单一酶活性位点内将氧化脱氨和Baeyer-Villiger氧化两种机制分离的催化循环相干整合","AncFO-221[酶类型]: 双功能祖先黄素酶"]},{"i":36979,"as":"","scd":null,"kp":[]},{"i":36980,"as":"","scd":null,"kp":[]},{"i":36981,"as":"研究开发了一种利用傅里叶变换离子回旋共振质谱（FT-ICR MS）对天然有机物（NOM）进行分子式特异性同位素分析（MSIA）的综合工作流程。通过强度调谐策略并使用通用参考材料校准，该方法实现了亚千分之一（‰）的精度和准确度。在陆地与海洋NOM的对比中，成功观测到显著的稳定碳同位素比（Δδ13C）差异，为分子水平的同位素比较提供了稳健手段。","scd":null,"kp":["分子式专属同位素分析(MSIA)[FT-ICR MS技术核心步骤]: 采用针对通用参考材料进行校准的强度调节策略"]},{"i":36982,"as":"研究开发了一种整合三维光声断层扫描和超声定位显微镜（3D-PAULM）的混合成像技术，结合具有强二区近红外吸收的光声染料，实现了全脑胶状淋巴系统动态的非侵入式成像。该技术能够在小鼠完整头骨下提供连续的全脑成像，实现对脑血管的超分辨率映射，并高敏感地追踪NIR-II染料在深层脑部胶状淋巴系统中的流动。","scd":null,"kp":["3D-PAULM[深层大脑胶质淋巴系统成像]: 结合三维光声断层扫描和超声定位显微镜并由光声染料增强的混合成像技术"]},{"i":36983,"as":"","scd":null,"kp":[]},{"i":36984,"as":"","scd":null,"kp":[]},{"i":36985,"as":"","scd":null,"kp":[]},{"i":36986,"as":"","scd":null,"kp":[]},{"i":36987,"as":"","scd":null,"kp":[]},{"i":36988,"as":"","scd":null,"kp":[]},{"i":36989,"as":"研究引入了循环图模型和理想化的双螺旋折叠蛇形连杆结构，以解释经典剪纸结构（折叠蛇形）无限翻转的底层力学机制。研究表明，翻转运动具有拓扑周期性和多重对称性，其运动学对应于由分叉运动引起的全等轴集的循环排列。通过调整拓扑参数，研究构建了折叠蛇形家族的综合图谱，并提出了物理实现的解决方案以解决应用挑战。","scd":null,"kp":["双螺旋性柔性多面体连杆机构[拓扑力学特征]: 具有无穷外翻与表面可重构性，解决了传统柔性结构的固有结构不连续性和运动学不明确性"]},{"i":36990,"as":"","scd":null,"kp":[]},{"i":36991,"as":"","scd":null,"kp":[]},{"i":36992,"as":"","scd":null,"kp":[]},{"i":36993,"as":"该研究提出了一种通过钌催化、酸辅助的氢化胺化反应，将废弃聚酯转化为伯、仲、叔二胺和胺的高效升级回收策略。该方法能将报废聚酯的所有结构单元转化为相应的（二）胺。对于含有多种杂质的实际废弃聚酯，该协议依然表现出色，产率高达98%。机制研究表明存在两条反应路径：酰基部分通过“氢化-缩合-氢化”序列转化，而醇基部分则通过酸辅助的氢借用途径转化。","scd":null,"kp":["废弃聚酯[钌催化/酸辅助氢化胺化反应]: 能够将所有结构单元转化为相应的一级、二级和三级二胺及胺类"]},{"i":36994,"as":"提出了一种名为FlashPPI的对比学习框架，用于实现蛋白质组规模的线性时间微生物蛋白质-蛋白质相互作用（PPI）预测。该框架基于残基级相互作用，利用从宏基因组序列中捕获跨蛋白质协同进化信号的基因组语言模型，将相互作用的对齐在共享的潜在空间中。与现有的基于序列的方法相比，FlashPPI的性能提高了四倍，同时将蛋白质组范围的筛选时间从数天缩短至数分钟，实现了计算复杂度从二次到线性的突破。","scd":null,"kp":[]},{"i":36995,"as":"脑转移瘤在癌症患者中发病率为26%，确诊后1年内死亡率高达90%。研究发现，单磷酸肌苷脱氢酶的特定亚型IMPDH2在脑转移起始细胞中特异性上调，而在正常脑组织中不表达，且足以驱动脑转移的形成。传统的IMPDH抑制剂由于对正常淋巴细胞中表达的IMPDH1具有脱靶抑制作用，会导致剂量限制性毒性而在二期临床试验中失败。因此，选择性靶向抑制IMPDH2能够削弱脑转移潜力，同时保留正常免疫细胞功能。","scd":null,"kp":[]},{"i":36996,"as":"研究了在28Si+142,150Nd反应中的融合激发函数和势垒分布。库仑势垒以下能量的重离子聚变反应受到相互作用核的内部自由度与相对运动自由度耦合的强烈影响。这些内部自由度的耦合导致了聚变势垒的分布，研究结果对于深入理解近垒及垒下能区的重离子反应动力学机制具有重要意义。","scd":null,"kp":[]},{"i":36997,"as":"主要研究了在缺中子核素216Th中的裂变动力学。超重元素的合成受制于准裂变（QF）和熔合裂变（FF）这两个主要的竞争过程。为了优化超重元素的生产产额，必须对这两个过程的动力学机制进行广泛而深入的理解。该研究通过实验方法探讨了这些核反应过程中的动力学特征，为超重元素的合成提供了实验依据。","scd":null,"kp":[]},{"i":36998,"as":"利用液氢靶上的敲出反应并结合伽马射线能谱学技术，研究了46S和47S原子核的低能激发态。实验在46S中观测到了四个新的跃迁，在47S中识别出一条新的伽马射线。这些实验结果与理论壳模型计算的对比，有助于进一步揭示丰中子硫同位素的核结构演化特征。","scd":null,"kp":[]},{"i":36999,"as":"对核心坍缩超新星（CCSNe）爆炸中产生的伽马射线特征进行了解码，并首次对28Al(p,α)25Mg反应速率提供了实验约束。超新星爆炸性硅燃烧期间产生的发射伽马射线的放射性同位素（如43K、47Sc和59Fe）可以作为探测超新星爆炸能量的探针。该实验测量结果对理解超新星核合成网络及爆炸动力学过程具有关键作用。","scd":null,"kp":[]},{"i":37000,"as":"通过逆运动学方法测量了22Ne的高能共振态性质。22Ne(α,n)25Mg反应在主s过程和弱s过程中均充当s过程的中子源。研究通过将22Ne激发到9.7 MeV以上的高能共振态，成功测量了这些难以触及的核态属性。这些共振参数的精确测量对于理解恒星内部的慢中子捕获过程及重元素核合成至关重要。","scd":null,"kp":[]},{"i":37001,"as":"在夸克离域色屏蔽模型框架下，研究了Ω重子与s反s介子（ϕ介子）之间的相互作用及关联函数。能谱计算结果表明，在所有考虑的相互作用通道中均未形成束缚态。散射相移和关联函数的分析为理解这种重子-介子强相互作用系统的特性提供了理论依据。","scd":null,"kp":[]},{"i":37002,"as":"在三流体动力学（3FD）模型下计算了重离子碰撞的四维体积（空间三维体积乘以寿命），并与JAM微观输运模型的计算结果进行了比较。计算针对质心能量为sqrt(sNN)下的中心金核-金核碰撞进行。研究评估了重离子碰撞中高重子密度和重子阻留的时空区域特征，为碰撞过程中物质状态的演化提供了理论模型对比。","scd":null,"kp":[]},{"i":37003,"as":"","scd":null,"kp":[]},{"i":37004,"as":"","scd":null,"kp":[]},{"i":37005,"as":"","scd":null,"kp":[]},{"i":37006,"as":"提出了双线性相位图的概念，将Kramers-Wannier变换推广到研究qudit自旋链的非传统有能隙相。该变换通过矩阵编码，能够探索更广泛的广义量子相谱。这一数学工具揭示了广义Kramers-Wanier对偶性，为研究复杂量子自旋系统的相变和拓扑性质提供了新的理论方法。","scd":null,"kp":["双线性相位图[量子自旋链研究]: 将Kramers-Wannier变换编码在矩阵中，以研究qudit自旋链非常规有能隙相的广义对偶性"]},{"i":37007,"as":"","scd":null,"kp":[]},{"i":37008,"as":"本文提出一种半定松弛方法，用于在厄米线性约束下寻找量子哈密顿量基态能量的下界，并逼近基态期望值。研究表明，利用对称性可以大幅降低该方法的计算复杂度。","scd":null,"kp":["哈密顿量基态能量[半定松弛方法计算]: 通过对称性可显著降低计算成本并获得下界及基态期望值的近似值"]},{"i":37009,"as":"研究发现Nd3BWO9中存在一种涌现的伊辛超临界态，具有普适的热力学行为。这一现象将气液类比扩展到稀土反铁磁化合物中，并因临界端点和拓扑激发，展现出在亚开尔文制冷领域的应用潜力。","scd":null,"kp":["伊辛超临界区[Nd3BWO9螺旋反铁磁化合物]: 展现出通用热力学行为并扩展了液气类比，具有亚开尔文制冷的潜在应用"]},{"i":37010,"as":"针对缺乏可调驱动机制导致控制层内激子传输困难的问题，本研究展示了一种全光学的层内激子引导方法。该方法通过激发电子-空穴相变设计的势能景观，实现对强光-物质相互作用激子的有效控制。","scd":null,"kp":["层内激子[激子输运控制机制]: 利用激发电子-空穴相变设计的势能景观实现全光学导向"]},{"i":37011,"as":"","scd":null,"kp":[]},{"i":37012,"as":"本文研究了生化网络中基于状态与基于反应的信息处理。轨迹互信息通常用于量化生化系统的信息传递，研究通过线性噪声近似（LNA）和高斯信道理论，实现了对轨迹互信息的可处理解，并分析了该方法的准确性。","scd":null,"kp":["[生物化学网络信息处理]: 采用线性噪声近似(LNA)和高斯信道理论求解轨迹互信息"]},{"i":37013,"as":"","scd":null,"kp":[]},{"i":37014,"as":"基于阿尔法磁谱仪（AMS）在国际空间站上13.5年间收集的100万个事件数据，本文报告了刚性范围从GV到TV内的宇宙重核（磷、氯、氩、钾、钙）通量的独特性质。","scd":null,"kp":["宇宙射线刚度探测范围[Alpha Magnetic Spectrometer]: GV到TV","数据采集周期[宇宙重核(P,Cl,Ar,K,Ca)观测]: 13.5年","采集事件总数[宇宙重核(P,Cl,Ar,K,Ca)观测]: 100万次"]},{"i":37015,"as":"","scd":null,"kp":[]},{"i":37016,"as":"研究开发了一种记忆辅助的非局域光学干涉仪。该干涉仪利用离域单光子纠缠技术，成功将干涉基线扩展至20公里，并有效补偿了几何延迟，向长基线望远镜应用迈进。","scd":null,"kp":["干涉基线长度[记忆辅助非局域干涉仪]: 20 km","[干涉仪技术特征]: 利用离域单光子纠缠扩展基线并补偿几何延迟"]},{"i":37017,"as":"研究发现具有共轭配体的Dion-Jacobson（DJ）钙钛矿薄膜的本征和掺杂态导电率显著低于使用绝缘配体的Ruddlesden-Popper（RP）钙钛矿薄膜。除了八面体倾斜导致的无机层内轨道重叠减弱外，HOMO能级偏移引发的空穴捕获效应也是导致该共轭DJ钙钛矿材料导电性偏低的关键机制。","scd":null,"kp":["[Dion-Jacobson钙钛矿电荷传输]: 采用共轭配体通过介电屏蔽和层间离域增强电荷传输"]},{"i":37018,"as":"为解决干旱地区可再生能源丰富但水资源匮乏导致绿氢生产困难的问题，本研究提出了一种耦合大气集水（AWH）与质子陶瓷电解池（PCEC）的系统。该系统采用吸湿性聚丙烯酰胺（HPAM）大孔微珠作为新型AWH吸附剂，利用废热释放捕获的水分产生持续热蒸汽流，实现近乎自给自足的连续制氢。","scd":null,"kp":["[干旱地区绿氢生产系统]: 耦合吸附式大气集水(AWH)模块与质子陶瓷电解槽(PCEC)模块","[AWH模块技术特征]: 配备双吸附剂单元，利用循环废热释放收集的空气水分"]},{"i":37019,"as":"非水系可充电铝电池的实用化主要受限于铝金属负极的可逆性和稳定性。铝负极失效由钝化层引起的阻抗增加、腐蚀以及沉积不稳定等多重耦合退化过程共同主导。在固态和准固态系统中，润湿性差和化学机械失配进一步加剧极化。文章总结了应对这些挑战的设计策略。","scd":null,"kp":["[非水铝电池铝金属负极失效机制]: 受持续钝化、阻抗累积及化学腐蚀等耦合降解过程控制"]},{"i":37020,"as":"为解决在脆弱多孔基底上构建导电网络的难题，本研究开发了一种基于超轻聚酰亚胺气凝胶的透气电子皮肤。该材料兼具1700 g m-2 day-1的高水蒸气透过率和123°以上的本征疏水性。通过140°C的温和热处理激活由聚酰胺酸壳封装的液态金属颗粒墨水，实现了稳健且高导电的生物界面。","scd":null,"kp":["水蒸气渗透率[聚酰亚胺气凝胶电子皮肤]: 1700 g/(m²·day)"]},{"i":37021,"as":"本研究通过在亚乙烯基连接的共价有机框架上锚定一系列单原子金属（M=Au, Pt, Pd, Ru, Mo），构建了用于气固相CO2光还原的M/COF催化剂。研究表明，催化剂的活性依赖于d轨道电子构型，且d带中心与CO2光还原活性表现出强相关性。","scd":null,"kp":["[光催化CO2还原单原子催化剂设计]: 将M1N2位点(M=Au,Pt,Pd,Ru,Mo)锚定在含亚乙烯基的共价有机框架上以调节电子结构"]},{"i":37022,"as":"针对室温磷光（RTP）聚合物难以同时实现高量子产率和长寿命的问题，本研究提出了一种原位交联自组装策略。该方法将柔性的弱RTP聚合物转化为刚性聚合物微球，成功制备出兼具长磷光寿命和高量子产率的高性能全彩RTP聚合物微球材料。","scd":null,"kp":["[室温磷光聚合物材料特性]: 难以同时实现高量子产率(ΦP)和长磷光寿命(τP)"]},{"i":37023,"as":"为解决固态电解质离子电导率低和界面不稳定的问题，本研究开发了一种基于二维Hofmann型无机配位聚合物框架的新型锂离子固态电解质。通过引入甲氧基乙烷（DME）作为层间客体分子调控层间距，在结构内构建了高选择性的锂离子传输通道，实现了高离子电导率。","scd":null,"kp":["固态电解质材料[固态锂金属电池]: 二维Hoffman型无机配位聚合物框架材料(HFM)","[固态电解质开发瓶颈]: 离子电导率有限、锂离子通量不均匀以及界面不稳定性"]},{"i":37024,"as":"本文研究了钙钛矿太阳能电池在低地球轨道质子富集环境下的耐久性，发现非电离能量损失主导了不可恢复的降解。通过控制质子辐照与离子传输模拟相结合，确定了原子位移引发A位/X位耗尽和晶格无序的能量依赖机制，并指出性能崩溃发生在超过临界累积剂量后。","scd":null,"kp":["[钙钛矿太阳能电池空间应用]: 质子和质子流对PSCs降解阈值的共同决定机制","[低地球轨道富质子环境]: 非电离能量损失导致电池性能退化"]},{"i":37025,"as":"为解决亲钠但疏液界面限制钠离子快速传输并导致不均匀电镀的问题，本文提出了一种由醋酸钠和Na3Sb组成的兼具亲液和亲钠特性的SA界面层。该界面的亲液性实现了良好的界面润湿，亲钠性引导钠离子快速接触，两者协同作用实现了无枝晶的均匀钠成核和生长。","scd":null,"kp":["负极界面修饰层[钠金属电池]: 由CH3COONa和Na3Sb构成的亲电解质与亲钠复合层(SA层)","[亲钠与亲电解质协同界面]: 引导钠离子均匀传输与无枝晶沉积"]},{"i":37026,"as":"为解决石墨石负极在快充和极端温度下反应动力学迟缓和界面不稳定的问题，本文提出了一种AlPO4（APO）表面修饰的界面化学调控策略。APO修饰促使更多PF6-阴离子进入界面溶剂化结构，降低了去溶剂化能，并促进了富含无机物的SEI形成，提升了反应动力学性能。","scd":null,"kp":["负极表面修饰[石墨负极/锂离子电池]: AlPO4(APO)表面改性策略","[石墨负极界面化学调控]: 实现快充与宽温域稳定运行"]},{"i":37027,"as":"硅基负极在充放电过程中的巨大体积变化会引起严重的应力积累，导致机械断裂和结构退化。本文以应力调节为统一框架，全面系统性地分析了硅基负极的失效机制，并从纳米结构设计到电极工程层面总结了多维度的应力缓解策略。","scd":null,"kp":["失效机制[硅基负极嵌/脱锂过程]: 体积剧变引发严重的应力积累、机械断裂及电极结构退化","[多维应力调节策略]: 涵盖从纳米结构到电极工程的整体应力管理"]},{"i":37028,"as":"本文综述了用于心血管疾病（CVD）监测的可穿戴柔性传感器。文章阐述了材料创新、结构工程和器件架构如何协同平衡传感器的灵敏度、机械鲁棒性和生物相容性。研究系统总结了电气、机械、血流动力学和生化等关键心血管生理信号，并将其与压阻、电容、摩擦电、电化学和光学转换等传感机制相关联。此外，该传感器实现了皮肤贴合和连续高保真监测，并集成了机器学习功能。","scd":null,"kp":["核心传感特性[可穿戴柔性心血管疾病监测传感器]: 平衡灵敏度、机械鲁棒性与生物相容性"]},{"i":37029,"as":"本研究开发了一种基于摩擦纳米发电机（TENG）的仿生电化学发光（TECL）成像技术。该技术受心脏舒张-收缩周期启发，利用TENG的高频脉冲输出，实现了对电极-电解液界面的直接可视化。TECL信号成功克服了传统ECL信号衰减和稳定性有限的缺陷，为分析电化学界面、应对全球能源与环境危机提供了新的分析手段。","scd":null,"kp":["[基于摩擦纳米发电机的仿生超分辨电化学发光成像]: 实现电极-电解质界面的直接可视化分析"]},{"i":37030,"as":"研究提出了一种物理增强深度学习（PDL）框架，用于优化建筑集成可持续能源中的半透明有机光伏器件（ST-OPVs）。该框架将光学物理先验嵌入神经网络，在减少对大量实验数据依赖的同时，预测准确性超越了传统模拟和纯数据驱动方法。结合新型卤素添加剂工程策略，有效解决了光伏器件在发电与透光率之间的复杂光子管理矛盾。","scd":null,"kp":["优化框架[半透明有机光伏电池]: 物理增强深度学习(PDL)框架","[半透明有机光伏]: 解决光伏效率与透光率之间的固有权衡限制"]},{"i":37031,"as":"聚酰亚胺（PIs）因其高热稳定性、机械鲁棒性和电绝缘性等综合优势被广泛应用于前沿技术。通过调节聚合物主链的刚性、极性和自由体积，引入氟化或脂环单元、交联端基以及有机-无机杂化结构，PI系统能够在保持长期可靠性的同时，获得光学透明性、光敏性或热绝缘等附加功能，满足新兴前沿应用的需求。","scd":null,"kp":["[前沿应用中的聚酰亚胺分子结构定制]: 在保持长期可靠性的前提下集成光透明性、光敏性或热绝缘等额外功能"]},{"i":37032,"as":"研究通过液滴微流控和紫外光聚合技术，开发出一种可降解的柔软水凝胶微载体。该微载体能够实现磁性颗粒、药物和3D活细胞球体的多重共包埋，并支持外部梯度磁场引导下的复杂轨迹精准运动控制。在生理条件下，微载体表现出可调的降解特性，解决了传统微载体难以可控降解、共包埋能力有限及规模化生产的挑战。","scd":null,"kp":["[软体可降解磁性微载体]: 液滴微流控与紫外光聚合技术","[新型水凝胶微载体]: 实现药物与3D细胞球的共封装及磁引导运输"]},{"i":37033,"as":"研究利用Au25团簇的量子校正等离激元效应来调控吸附行为，以提升光催化全分解水反应效率。传统等离激元增强受限于仅依靠氢原子相互作用的微弱界面水分子吸附。通过引入量子校正等离激元效应，有效改善了光电器件中的电子模型，突破了反应动力学的限制，为太阳能驱动光催化制氢提供了实验验证与新策略。","scd":null,"kp":["[Au25团簇的量子校正等离激元效应]: 调控界面H2O吸附行为以克服仅依赖氢原子相互作用的限制","[光催化全解水]: 显著提升界面吸附与太阳能驱动制氢反应动力学"]},{"i":37034,"as":"研究利用组合合成生物学技术，成功由超过16000个组合DNA环组装出真正的“奥林匹克凝胶”。这种软材料由机械互锁的质粒组成，其环状DNA分子能够通过多样化的“锁-钥匙”结构域进行可逆的开合，实现机械键的受控形成。该成果制备出具有新奇拓扑架构和独特物理特性的成分复杂的软材料。","scd":null,"kp":["[由超过16000个组合DNA环组装的“奥林匹克凝胶\"]: 由机械互锁的质粒组成，环形DNA分子可通过多样化锁钥结构域可逆打开和闭合，实现机械键的可控形成","[组合合成生物学]: 能够产生成分复杂的软材料，具有奇特的拓扑结构和独特的物理特性"]},{"i":37035,"as":"针对钾离子电池非石墨负极在循环中因相变导致的严重结构退化问题，研究提出了一种本征稳定非晶相工程策略。非晶材料的结构各向同性和开放骨架能够从根本上缓解体积应变，实现卓越的长期循环稳定性。以非晶(Bi,Sb)@C电极为例，在100 mA g-1电流密度下循环3200次，容量衰减率低至0.005%/次。","scd":null,"kp":["[非石墨基钾离子电池负极材料]: 具有高容量，但会因循环过程中反复的相变而遭受严重的结构退化","相工程策略[非晶相材料]: 利用其内在的结构各向同性和开放框架从根本解决不稳定性，内在缓解体积应变，实现卓越的长期循环稳定性"]},{"i":37036,"as":"针对有机p型正极材料易溶于电解液导致穿梭效应的问题，研究将9,9-二甲基吖啶（DMAC）作为新型氧化还原活性基团引入正极材料设计。DMAC中的-C(CH3)2基团稳定了其氧化态，有效抑制了极性电解液中的穿梭效应，使材料循环3000次后容量保持率达76%。此外，微量溶解的DMAC氧化态自由基作为氧化还原介质，提升了材料的导电性和活性物质比例。","scd":null,"kp":["工作电压[有机p型正极材料]: 超过3.5 V","主要挑战[有机p型正极材料]: 在电解质中溶解度高，导致穿梭效应和较差的循环稳定性","氧化态稳定机制[9,9-二甲基吖啶(DMAC)]: 其内部的小极性-C(CH3)2基团可稳定其氧化形式(DMAC+•)"]},{"i":37037,"as":"钙钛矿多结太阳能电池通过减少热化损失和改进光谱利用，突破了单结光伏技术的效率极限，正稳步迈向吉瓦级工业化部署。钙钛矿不仅能与晶体硅互补，还可作为通用的叠层组件，在纯钙钛基架构、多种基板甚至三结电池中得到应用。尽管取得显著进展，但该技术在迈向规模化的过程中仍面临内部多结互连等关键挑战。","scd":null,"kp":["[基于钙钛矿的多结太阳能电池]: 通过减少热化损失和改善光谱利用，提供了突破单结光伏技术实际效率极限的路径，首次打开了吉瓦级规模部署的现实路径"]},{"i":37038,"as":"为解决电催化硝酸盐还原制氨过程中活性、选择性和稳定性之间的性能权衡，研究提出一种过渡金属氧化物的阳极活化策略。晶格破坏和表面重组生成了高活性且自维持的氢氧化物界面。界面羟基基团平衡了质子的供应，加速了含氮中间体的分步还原，从而在波动的可再生电力输入下实现了高效的加氢动力学与氨合成。","scd":null,"kp":["潜在工作窗口[电催化NO3−到NH3还原]: 通常被限制在狭窄的电位窗口内（归因于活性、选择性和稳定性之间的性能权衡）","解决策略[克服电催化氨合成性能权衡]: 报告了一种在过渡金属氧化物中自发供给质子的阳极活化策略"]},{"i":37039,"as":"针对水系锌离子电池中锌负极枝晶生长及副反应等问题，研究引入三(五氟苯基)硼烷（TPFPB）作为路易斯酸性多功能添加剂。该添加剂通过其缺电子硼阳离子实现了阴离子的同步固定与分解，从而构建出稳固的固体电解质界面（SEI）层。这一机制有效解决了传统阴离子调节会减缓锌离子脱溶剂化并降低传输效率的难题，增强了锌离子动力学。","scd":null,"kp":["[水系锌离子电池金属锌负极]: 面临有害的枝晶生长和严重的副反应挑战，源于不稳定的固体电解质界面(SEI)层、缓慢的Zn2+传输动力学和不可逆的Zn沉积","SEI构建策略[路易斯酸性分子调节]: 实现同步阴离子固定和分解，构建坚固的固体电解质界面并增强Zn2+动力学"]},{"i":37040,"as":"","scd":null,"kp":[]},{"i":37041,"as":"","scd":null,"kp":[]},{"i":37042,"as":"","scd":null,"kp":[]},{"i":37043,"as":"研究开发了一种基于ProteinMPNN的蛋白质序列重设计策略，以提高大肠杆菌中异源酶的表达。该策略在关键结构特征和进化保守性的指导下，对植物糖基转移酶TOGT和UGT84A56进行了广泛重设计。实验结果显示，重设计变体在大肠杆菌中的可溶性表达和催化活性显著增强。分子模拟表明，性能的提升源于蛋白质的全局结构优化。","scd":null,"kp":["[基于ProteinMPNN的序列重设计策略]: 受基本结构特征和进化保守性指导，改善异源酶在细菌中的表达","应用效果[植物糖基转移酶TOGT和UGT84A56]: 生成广泛重设计的变体，显著提高异源表达和七叶亭糖基化效率"]},{"i":37044,"as":"研究使用置于调制光学晶格中的超冷原子玻色-爱因斯坦凝聚体实现了震荡转子模型，直接观测到相干前向散射（CFS）峰。CFS峰作为非各态历经动力学的结果出现在位置分布中，并在强局域化机制中显现。该研究证实了CFS峰在量子混沌系统中具有揭示非各态历经性及探测系统对称性的双重作用。","scd":null,"kp":["相干前向散射(CFS)峰[强局域化区]: 首次被直接观察到，证明了其作为非各态历经性标志以及量子混沌系统中对称性探针的双重作用"]},{"i":37045,"as":"研究通过超晶格应变工程和三周期量子阱设计，制备了黄光和红光InGaN微型LED，并转移至金刚石基底上。20微米黄光微型LED在6.25 A/cm²下实现了2850.4 MHz的电光带宽，红光器件达到2593.4 MHz。结合双光子光刻制备的微透镜及OOK调制技术，该器件实现了超低功耗和高速光学互连传输。","scd":null,"kp":["器件结构[黄光和红光InGaN微LED]: 通过超晶格应变工程和三周期量子阱设计进行优化，并利用双光子光刻技术制备微透镜","[转移印刷在金刚石上的微LED]: 具有高调制带宽、低功耗运行和阵列集成特性，是下一代超低功耗高速光学互连的理想发射器"]},{"i":37046,"as":"研究通过在β-MnO2边缘锚定孤立钌原子构建主客体架构，利用动态羟基介导的电荷缓冲机制，稳定了酸性水氧化反应中的高价态钌活性位点。表面羟基优化了中间体结合，促进了理想的O-O键偶联反应。同时，特定配位环境允许锰主体可逆地适应结构变化，有效解决了高活性Ru(>IV)物种易于溶解的热力学不稳定性难题。","scd":null,"kp":["[基于钌的酸性水氧化催化剂]: 高活性的高价Ru(>IV)物种也是快速溶解的前驱体，存在严重的活性-稳定性悖论","主客体协同架构[锚定在β-MnO2边缘的孤立钌原子]: 通过动态羟基介导的电荷缓冲作用，克服活性-稳定性权衡，稳定高价钌边缘位点"]},{"i":37047,"as":"中子辐照会引发铁素体钢的硬化与脆化，而Grade 91铁素体钢在辐照过程中原位形成了富硅线性络合物，成功克服了强度与塑性的权衡挑战。通过粉末冶金热等静压（PM-HIP）技术制备的合金展现出超过辐照前90%的优异塑性保持率。粉末加工促进了高密度线性络合物的形成，为核结构合金克服寿命限制挑战提供了新途径。","scd":null,"kp":["强化机制[9级铁素体钢抗中子辐照]: 中子辐照过程中Si富集线形络合物的原位形成","性能表现[克服强度-塑性权衡]: 保持前所未有的延展性"]},{"i":37048,"as":"肤色会影响光学设备性能，对深色皮肤患者的护理产生不利影响。光声成像（PAI）结合了光学与超声波技术，研究发现黑色素浓度与PAI生物标志物之间存在复杂关联。通过对42名涵盖不同肤色及白癜风志愿者的测试，研究揭示了图像质量退化机制：波长依赖的黑色素吸收在低黑色素时主导光谱着色，而表皮超声背散射在高黑色素时占主导地位。","scd":null,"kp":["样本规模[光声成像肤色影响研究]: 42名健康志愿者","样本多样性[光声成像肤色影响研究]: 涵盖Fitzpatrick I-VI型皮肤及白癜风"]},{"i":37049,"as":"铌酸钠通常被视为反铁电材料，在储能及机电器件领域极具潜力。研究提出一种拓扑化学转化策略，成功制备出具有正交晶相的纯铁电铌酸钠薄膜，且该特性不受膜厚度限制。扫描透射电镜识别出具有大角度或小角度晶格畸变的不同区域，极化分析证实其室温铁电性源于面外位移。该研究实现了对该材料铁电相序的精确控制。","scd":null,"kp":["材料特性[NaNbO3膜]: 室温铁电性","制备工艺[纯铁电NaNbO3膜]: 拓扑化学转化策略"]},{"i":37050,"as":"钙钛矿等材料展现出显著的室温塑性，但其位错的原子结构此前一直未获解析。传统的扫描透射电镜观察结果与理论预测的可动位错模型存在分歧。研究采用基于静电剂量调制器的脉冲电子束，在保持亚埃级分辨率的前提下，成功解析了钙钛矿晶体内在的、可滑移分裂的位错结构，解决了电镜观察与材料实际塑性表现不一致的问题。","scd":null,"kp":["塑性机制[钙钛矿晶体室温塑性]: 通过{110}<1-10>位错实现","结构表征[钙钛矿位错结构解析]: 使用脉冲电子束实现原子级分辨率"]},{"i":37051,"as":"辐射损伤是冷冻电镜进行高分辨率生物成像的根本限制。近期有假说认为脉冲电子束能为能量耗散提供时间，从而减少辐射损伤。为验证此假说，研究使用配备冷场发射电子枪的300kV Titan Krios显微镜生成脉冲电子束，对石蜡、细菌视紫红质等冷冻样本进行了系统性测试。对比实验证明，脉冲电子束照明并不能减少生物大分子成像时的辐射损伤。","scd":null,"kp":["损伤机制[脉冲电子束成像生物大分子]: 脉冲电子照射不能通过提供能量耗散时间来减少辐射损伤"]},{"i":37052,"as":"深海沉积物中甲烷衍生有机碳的保存机制此前尚不明确。通过对多种甲烷渗漏沉积物进行碳同位素及升温分析，研究发现深海表层沉积物中的放射性碳含量与硫酸盐-甲烷转换深度存在相关性。大量碳-14贫化的有机碳源自深部甲烷，并在表层渗漏沉积物中高效保存。这种高效保存与海水-沉积物界面的微生物介导聚集体的物理遮蔽作用相关。","scd":null,"kp":["碳循环特征[深海表层沉积物甲烷衍生有机碳]: 放射性碳(14C)含量与硫酸盐-甲烷转换深度存在相关性","碳保存效率[深海表层沉积物]: 甲烷衍生有机碳得到高效保存"]},{"i":37053,"as":"","scd":null,"kp":[]},{"i":37054,"as":"木质素相关芳香族化合物因底物毒性和代谢通量失衡，难以进行微生物转化。研究在谷氨酸棒杆菌中构建了整合进化工程与多重动态控制的自主微生物系统。该系统具备强化的细胞防御和升级的芳香族外排机制，其多层调控网络能实时响应底物并精准控制代谢路径。该系统实现了将多种木质素底物转化为原儿茶酸，转化率高达99.89%，滴度达到53.40 g/L。","scd":null,"kp":["底盘细胞[木质素芳香族化合物转化]: 谷氨酸棒杆菌","抗逆机制[自主微生物系统]: 具有增强细胞防御和升级芳香族外排机制的鲁棒进化底盘","调控策略[克服毒性及代谢通量不平衡]: 结合进化工程与多重动态控制"]},{"i":37055,"as":"","scd":null,"kp":[]},{"i":37056,"as":"","scd":null,"kp":[]},{"i":37057,"as":"","scd":null,"kp":[]},{"i":37058,"as":"","scd":null,"kp":[]},{"i":37059,"as":"","scd":null,"kp":[]},{"i":37060,"as":"","scd":null,"kp":[]},{"i":37061,"as":"分子扩散是限制固体吸附剂在二氧化碳捕集与分离应用中性能的基本属性，取决于气体分子与吸附剂表面原子的独特理化相互作用。针对传统模拟忽略吸附剂结构特异性分子动力学的问题，研究对10,143种金属有机框架材料进行了基于分子吸附预测的过程级模拟。该模拟结合了每种MOF独特的结构属性，为准确评估固体吸附剂的碳捕集性能提供了更科学的方法。","scd":null,"kp":["性能限制因素[MOFs材料CO2捕集]: 分子扩散是限制固体吸附剂性能的基本属性","仿真修正[CO2捕集工艺级性能验证]: 必须包含特定结构和特定分子的相互作用参数，摒弃通用参数"]},{"i":37062,"as":"","scd":null,"kp":[]},{"i":37063,"as":"本文描述了反场装置第二次重大升级的进展。该设备的核心更新是在真空容器内部安装了一个薄铜稳定壳，以确保电阻壁模式的长期稳定性，并实现撕裂模式的快速旋转。在NEFERTARI项目下，正对其技术设施和诊断系统进行全面现代化改造，该项目由欧盟下一代国家恢复与韧性计划资助，旨在强化RFX的基础设施，推进磁约束核聚变等离子体研究。","scd":null,"kp":[]},{"i":37064,"as":"质子电池因其优异的电化学性能、可扩展性和环境友好性，被视为替代传统锂离子电池的储能技术。该综述全面回顾了质子电池的复兴，涵盖其历史背景、构造、工作原理及核心材料。文章重点讨论了电池组件（如电极和电解质）以及质子传导、催化活性和氧化还原反应的机制，系统评估了质子电池在应对全球不断增长的储能需求方面的技术潜力。","scd":null,"kp":[]},{"i":37065,"as":"","scd":null,"kp":[]},{"i":37066,"as":"","scd":null,"kp":[]},{"i":37067,"as":"","scd":null,"kp":[]},{"i":37068,"as":"","scd":null,"kp":[]},{"i":37069,"as":"","scd":null,"kp":[]},{"i":37070,"as":"","scd":null,"kp":[]},{"i":37071,"as":"","scd":null,"kp":[]},{"i":37072,"as":"SAMJ是一款专为ImageJ/Fiji平台开发的用户友好型插件，基于分割一切模型（SAM）实现快速、交互式且高精制的图像标注。该插件无需复杂的专业技术知识，即可在标准计算机上运行，有效解决了生物医学图像分析中像素级人工标注耗时且依赖专家输入的瓶颈，加速了AI系统训练。","scd":null,"kp":["技术特点[ImageJ/Fiji图像标注]: 利用SAM模型实现快速图像交互式分割标注"]},{"i":37073,"as":"","scd":null,"kp":[]},{"i":37074,"as":"","scd":null,"kp":[]},{"i":37075,"as":"","scd":null,"kp":[]},{"i":37076,"as":"","scd":null,"kp":[]},{"i":37077,"as":"","scd":null,"kp":[]},{"i":37078,"as":"","scd":null,"kp":[]},{"i":37079,"as":"","scd":null,"kp":[]},{"i":37080,"as":"","scd":null,"kp":[]},{"i":37081,"as":"","scd":null,"kp":[]},{"i":37082,"as":"本研究利用原位液相透射电子显微镜（TEM）实时观测了液相中碲（Te）纳米结构的电沉积生长过程，揭示了初始颗粒向纳米线及复杂分支形态演化的机制。研究表明，生长过程高度依赖于局部化学环境，且添加铋（Bi）晶种可显著增强纳米结构的形成。该成果为电子和能源应用的大规模纳米材料合成提供了指导。","scd":null,"kp":["表征手段[液相纳米材料生长]: 原位液相透射电子显微镜(TEM)","生长促进机制[液相碲纳米结构电沉积]: 添加铋晶种可显著增强其形成与形貌演化"]},{"i":37083,"as":"","scd":null,"kp":[]},{"i":37084,"as":"","scd":null,"kp":[]},{"i":37085,"as":"","scd":null,"kp":[]},{"i":37086,"as":"","scd":null,"kp":[]},{"i":37087,"as":"为解决纳米孔传感数据难以精准识别的问题，研究提出了SEDA-Former（信号增强与动态注意力Transformer）深度学习框架。该模型有效克服了传统深度学习方法无法捕捉细粒度时间动态特征以及难以提取微弱判别特征的局限，能够强化时间信号处理，实现高保真、高精度的纳米孔生物分子识别。","scd":null,"kp":["[深度学习框架用于纳米孔识别]: 通过增强时间信号赋能高保真识别","[现有深度学习方法局限]: 难以捕捉区分高度相似纳米孔离子电流数据所需的细粒度时间动态特征"]},{"i":37088,"as":"基于溶液加工的二硫化钼（MoS2），研究开发了一种无需转移、大面积的毫米波开关。该器件利用MoS2边缘缺陷作为限制铜丝通道的内在模板，实现了76纳秒的快速开关和1.57纳焦耳的低能耗，具有超低静态功耗，其品质因数达到亚飞秒级。该技术突破了CMOS和MEMS的局限，满足6G通信中100 GHz以上的射频组件需求。","scd":null,"kp":["工作频率[6G射频前端毫米波开关]: >100 GHz","[核心条件]: 零静态功耗、低损耗、高隔离度","[基于溶液加工MoS2的器件]: 免转移、大面积","[品质因数(FOM)]: 亚飞秒级"]},{"i":37089,"as":"研究利用含有磺酰基的吡啶双恶唑啉（PYBOX）配体与ErCl3络合，成功催化了脂肪族和芳基酮腙的氰化反应。该方法以高达96%的对映体过量（ee值）高效合成了Cα-四取代的α-肼基腈类化合物。基于此技术，仅用4步反应、82%的总产率完成了抗帕金森药物L-卡比多巴的最短催化不对称全合成。","scd":null,"kp":["对映选择性[脂肪族和芳基酮腙的氰化反应]: 高达96% ee","催化剂体系[酮腙亲核加成反应]: ErCl₃催化/磺酰基-PYBOX配体","[技术特点]: 吡啶C4位带有磺酰基的 sterically confined pyridinebisoxazoline (PYBOX) ligand","[L-carbido全合成]: 最短催化对映选择性全合成路线"]},{"i":37090,"as":"研究提出一种工艺分离级联催化（PSCC）技术，用于将轻质烷烃高效转化为苯、甲苯和二甲苯（BTX）。通过使用空间解耦的金属-沸石催化剂，该系统打破了传统双功能催化中的动力学纠缠。在550°C的反应-再生循环中，实现了超过95%的丙烷转化率和82.3%的芳烃选择性，且产物几乎全部为BTX。","scd":null,"kp":["目标产物[工艺分离级联催化(PSCC)]: 苯、甲苯和二甲苯(BTX)","[技术特点]: 优先进行动力学解耦而非活性位点的空间紧密接触，克服不同基元步骤间的动力学纠缠"]},{"i":37091,"as":"研究报道了原子级精确的Au8Pd1(DPPF)4^2+团簇在过氧化氢（H2O2）合成与利用中的催化机制。该团簇展现出金属核心与表面配体的协同效应：金属核心催化甲酸与氧气生成H2O2，随后DPPF配体与核心共同作用将H2O2转化为羟基自由基。借助流体力学计算，由该团簇组装的非均相催化剂表现出优异的催化性能。","scd":null,"kp":["催化剂[双氧水的合成与利用]: 原子级精确的Au8Pd1(DPPF)4²⁺团簇","[催化机制]: 金属内核催化反应的同时，表面配体呈现协奏般的协同作用"]},{"i":37092,"as":"研究引入共晶镓铟（EGaIn）作为兼具红外伪装与热电感应的多功能柔性材料。EGaIn通过反射环境红外辐射来抑制自身的热辐射，在宽温度范围内实现高效的红外隐身。同时，EGaIn能够利用温差产生电压进行热电能量收集。该材料无需复杂的制造工艺，极大提升了军事等领域的操作效率。","scd":null,"kp":["多功能柔性材料[红外伪装与热电收集]: 共晶镓铟(EGaIn)","[技术特点]: 无需复杂制造工艺即可同时实现红外伪装与热电传感"]},{"i":37093,"as":"为提升非稠环电子受体（NFREAs）的有机太阳能电池光电转换效率，研究提出超分子侧链诱导的多维电荷传输策略。开发的新型NFREAs（3TT-Ph2和3TT-Ph4）通过苯基/氟化苯基侧链，与氰基茚酮端基形成额外的超分子相互作用（如苯基-受体相互作用）。该多维电荷传输网络使太阳能电池效率达到19.12%。","scd":null,"kp":["能量转换效率(PCE)[非稠环电子受体(NFREAs)有机太阳能电池]: 19.12%","[核心策略]: 超分子侧链诱导的多维电荷传输"]},{"i":37094,"as":"研究利用在three波混频机制下运行的可编程约瑟夫森行波参量放大器（JTWPA），实现了多模纠缠微波簇态的按需生成。通过任意波形发生器注入定制的非等距泵浦音，工程化地构建了多个频率模式间的非线性耦合。频率分辨零差检测证实了簇态的目标图拓扑结构。该方法通过泵浦实现了纠缠结构的可重构性。","scd":null,"kp":["[连续变量量子计算核心资源]: 多模纠缠微波簇态","[核心器件]: 可编程约瑟夫森行波参量放大器(JTWPA)","[工作机制]: 三波混频机制下通过任意波形发生器注入定制的非等距泵浦音"]},{"i":37095,"as":"研究通过使用含氟聚合物对液态金属的天然氧化壳层进行化学掺杂，将其从电绝缘屏障转化为电子半导体界面。这一突破使得制备无需烧结的Janus薄膜成为可能。该薄膜兼具高导电性、高柔韧性及多种功能，彻底改变了液态金属氧化物壳层的应用局限，为新一代软电子材料的设计提供了全新思路。","scd":null,"kp":["[技术特点]: 氟化聚合物对原生氧化层进行化学掺杂，将其从电子屏障转化为可调谐的半导体界面，实现无需烧结的高导电性"]},{"i":37096,"as":"研究开发了一种铜催化的动态动力学不对称烯丙基化反应，成功实现了外消旋α,β,β-三芳基乙酮的对映选择性转化。该方法克服了拥挤立体骨架中相邻手性中心构建的挑战，高效合成了多种具有优异对映选择性和非对映选择性的手性α,β,β-三芳基叔醇。结合后续转化，该技术在药物和生物活性分子合成中具有重要应用价值。","scd":null,"kp":["催化剂[动态动力学不对称烯丙基化反应]: 铜催化","[技术特点]: 实现了空间拥挤的三芳基叔醇相邻手性中心的立体控制组装"]},{"i":37097,"as":"研究团队利用毫电子伏特分辨率的非弹性X射线散射技术，在金样品中直接量化了超热状态下电子-离子平衡动力学。实验揭示，与弱激发态金相比，超热金样品表现出显著增强的能量转移速率，并获得了准常数的电子-离子耦合参数，为非平衡物理研究提供了直接的模型无关测量数据。","scd":null,"kp":["电子温度[激光辐照过热金样品]: 多eV级别","测量技术[非弹性X射线散射]: meV量级分辨率","测量目标[离子温度]: 模型无关的直接测量"]},{"i":37098,"as":"研究人员通过摩擦诱导的原位合成技术，制备出一种可变形的液态金属桥接纳米颗粒复合材料。该材料具有独特的结构，约66体积分数的纳米级导电陶瓷颗粒通过金属键与液态金属桥接，使其在保持低接触电阻的同时，具备1.5 GA/m²的高电流密度和2.6 GPa的高硬度，有效克服了液态金属在外力下机械强度不足的问题。","scd":null,"kp":["电流密度[摩擦诱导原位合成液态金属复合膜]: 1.5 GA/m2","硬度[摩擦诱导原位合成液态金属复合膜]: 2.6 GPa","材料特性[可变形液态金属桥接纳米颗粒复合材料]: 低接触电阻与高硬度"]},{"i":37099,"as":"研究确定了反离子电荷局域化是分子盐形成水合物的关键决定因素，为预测和控制固态水合作用提供了理论框架。通过分析超过31,000个晶体结构和电子密度计算，发现离域的反离子电荷抑制水合物形成，而局域电荷则促进该过程。利用这一原理，研究人员在4-氨基乙酰苯胺盐中实验证实了水合作用的合理控制。","scd":null,"kp":["水合决定因素[分子盐]: 反离子电荷定域化","研究基础[分子盐水合作用预测框架]: 分析超31000种晶体结构及电子密度计算"]},{"i":37100,"as":"研究通过计算设计出一种具有最佳旋转能垒（ΔG‡ = 21.7 kcal/mol）和不对称识别能力的柔性氧杂[4]螺旋烯低聚物骨架。该平台通过温和条件下的动态动力学拆分，实现了具有双螺旋手性或螺旋与轴向混合手性螺旋化合物的构建。该策略展现出优异的对映选择性、非对映选择性和E/Z选择性，突破了多手性螺旋体系合成的瓶颈。","scd":null,"kp":["旋转能垒[柔性氧杂[4]螺旋烯衍生物支架计算设计]: 21.7 kcal mol−1","合成方法[多手性螺旋化合物]: 动力学拆解"]},{"i":37101,"as":"研究采用分层微观结构设计策略，成功开发出一种屈服强度超3 GPa且兼具延展性的马氏体时效钢（Fe-16Ni-7Mo-1.6Ti-15Co-0.1Al）。该材料通过将多失配纳米共沉淀物、均匀的高密度位错及超细等轴晶粒整合为分层微观结构，有效分散了通常会导致超高强度钢变脆的应力集中，克服了传统强化方法中强度与延展性不可兼得的矛盾。","scd":null,"kp":["屈服强度[马氏体时效钢]: >3 GPa","材料成分[马氏体时效钢]: Fe-16Ni-7Mo-1.6Ti-15Co-0.1Al (wt.%)","材料特性[具有分层微观结构架构的马氏体时效钢]: 超高强度兼具延展性"]},{"i":37102,"as":"该研究提出了一种综合考虑多种灾害、作物暴露和社会经济脆弱性的全球农业风险评估模型。通过量化农田和十种主要农作物面临的热浪、干旱、洪水及复合干热事件的暴露程度，并结合社会经济指标构建的脆弱性指数，研究预测在全球多种未来气候和水文模型情景下，全球主要产粮区的多灾害农业风险将广泛增加。","scd":null,"kp":["评估维度[全球农业风险]: 气候多重灾害暴露、作物敏感性与社会经济脆弱性"]},{"i":37103,"as":"","scd":null,"kp":[]},{"i":37104,"as":"","scd":null,"kp":[]},{"i":37105,"as":"","scd":null,"kp":[]},{"i":37106,"as":"","scd":null,"kp":[]},{"i":37107,"as":"","scd":null,"kp":[]},{"i":37108,"as":"研究引入了一种可扩展的深度学习引导蛋白质工程框架，成功提升了真核紧凑型Fanzor核酸酶SpuFz1的活性，获得了编辑效率提高11.6倍的多突变变体。同时，通过比较序列分析设计了仅75个核苷酸的超短ωRNA支架，在保持活性的前提下将向导RNA长度缩短了79%。整合这些优化组件，成功开发出高效、紧凑的基因编辑工具enFanzor。","scd":null,"kp":[]},{"i":37109,"as":"研究提出了一种名为SplitSeek-Pro的深度学习模型，用于评估折叠蛋白质中氨基酸水平的可分裂性。该模型整合了一级序列和3D结构特征，通过大规模预训练和高质量微调的两阶段训练过程实现了残基分辨率的预测。在三种不同蛋白质上的实验验证表明，其预测能力优于现有方法，能精准识别出具有内聚功能的特征片段，对环状排列等蛋白质工程任务至关重要。","scd":null,"kp":[]},{"i":37110,"as":"研究在高熵钙钛矿Cs(PbMgZnCd)Br3胶体纳米晶中，同时观察到了缓慢的自旋弛豫（τS = 59.8 ps）和快速的辐射复合（τR = 3.4 ns）。非铅金属的掺入将[PbBr6]4⁻骨架在空间上分离成小于激子玻尔半径的微结构域，尺寸限制导致了短寿命光致发光的蓝移。该材料的晶格畸变显著减弱了电子-声子耦合，实现了室温下自旋极化激发态的光学操控。","scd":null,"kp":["自旋弛豫时间[Cs(PbMgZnCd)Br3纳米晶体]: 59.8 ps","辐射复合寿命[Cs(PbMgZnCd)Br3纳米晶体]: 3.4 ns","材料特性[高熵钙钛矿胶体纳米晶体]: 实现室温下激发态的光学访问和自旋操控"]},{"i":37111,"as":"","scd":null,"kp":[]},{"i":37112,"as":"","scd":null,"kp":[]},{"i":37113,"as":"针对生鱼片形状不规则且质地柔软难以处理的问题，研究人员开发了一款名为Sashimi-Bot的三臂机器人。该机器人系统已成功掌握了处理和操作鲑鱼腰肉的技术，能够轻松应对海鲜处理任务。","scd":null,"kp":["系统配置[处理生鱼片的机器人]: 三机械臂","核心特征[生鱼片处理机器人]: 能够操控形状不规则且质地柔软的鲑鱼腰肉"]},{"i":37114,"as":"通过对树懒进行基因组测序，科学家发现了影响线粒体（为细胞提供能量的细胞器）的相关基因发生了重复现象。这一基因层面的发现为解释树懒行动极其缓慢的生活习性提供了重要的科学线索。","scd":null,"kp":["基因测序结果[树懒]: 发生影响线粒体的基因重复"]},{"i":37115,"as":"研究通过设计多溶剂体系，重构了Zn²⁺溶剂化结构和水分子的氢键网络，开发出一种高熵、贫水的凝胶电解质。该设计克服了单一水系溶剂限制Zn²⁺沉积动力学的问题，实现了锌电池的快速沉积动力学和宽温度范围操作，为在真实热波动环境中运行的水系电池的耐久性和高倍率性能提供了新思路。","scd":null,"kp":["结构重构[宽温域锌电池水凝胶电解液]: 设计多溶剂体系重构Zn2+溶剂化结构与H2O分子氢键网络","电池性能[宽温锌水系电池]: 实现快速沉积动力学和宽温度范围运行"]},{"i":37116,"as":"研究表明，动物胚胎中的“组织者细胞”具有跨物种通用性。在跨物种细胞移植实验中，这些细胞能够指导不同动物门类胚胎构建特定类型的身体结构。这一跨生命树的发现为揭示多细胞动物如何演化出现提供了重要的科学线索。","scd":null,"kp":[]},{"i":37117,"as":"研究人员在对话过程中实时追踪了单个脑细胞的电活动。此外，还涉及了GPS的历史，以及一项可能揭示动物起源线索的跨物种移植技术。","scd":null,"kp":[]},{"i":37118,"as":"研究采用原位瞬态反射显微镜，时空解析了面工程化钒酸铋（BiVO4）光催化剂中光生载流子的演化。光生空穴经历三个连续步骤：初始超快电荷分离（约5皮秒）、空穴捕获（约1.5纳秒）以及通过陷阱状态介导向表面预吸附水的界面转移（约19皮秒）。陷阱状态在光生空穴的演化中起到关键作用。","scd":null,"kp":["测试方法[光生载流子演化分析]: 原位瞬态反射显微镜","观测尺度[单晶光催化剂]: 纳米尺度","时间分辨率[光生载流子追踪]: 飞秒至秒级"]},{"i":37119,"as":"","scd":null,"kp":[]},{"i":37120,"as":"多项研究表明，过度依赖人工智能工具会降低医生和软件工程师的专业能力。早期研究结果证实了AI工具对从业人员技能的负面影响。","scd":null,"kp":[]},{"i":37121,"as":"基于mRNA的治疗方法在疾病防治中取得成功，但面临器官、组织和细胞特异性递送的困难。目前正在开发多种策略应对挑战，包括优化给药途径、增强靶向能力和促进响应释放。这些策略已应用于mRNA疫苗、蛋白替代和基因编辑，以实现更精准的治疗。文章探讨了纳米载体介导的mRNA递送及其面临的各类屏障。","scd":null,"kp":[]},{"i":37122,"as":"研究提出一种溶剂导向策略，实现了范德华金属有机框架的目标堆叠。通过不同溶剂调节共轭配体的亚稳态，并利用金属-配体配位稳定这些状态，使堆叠模式从配体继承到框架中。该策略能够控制二维和三维材料的堆叠序列及电荷传输机制。","scd":null,"kp":["调控策略[范德华金属有机框架靶向堆叠]: 溶剂导向策略","[共轭配体]: 具有可通过不同溶剂调节的亚稳态并能通过金属-配位键稳定"]},{"i":37123,"as":"铝离子储能系统具有储量丰富、高理论体积容量和本征安全的优势，但缺乏有效的正极材料限制了其发展。共价有机框架（COFs）具有可调结构和丰富的氧化还原活性位点，能实现多电子反应和快速离子传输，有望解决铝离子存储材料稀缺的问题。","scd":null,"kp":["[铝离子储能体系(Al-ESS)]: 具有高理论体积容量和本质安全性","阴极材料[铝离子电池双极性电荷存储]: 供体-受体共价有机框架"]},{"i":37124,"as":"研究人员开发了一种无催化剂固态锂氧电池，通过电流驱动的相转化锂化机制实现四电子反应并生成氧化锂（Li2O）。该技术使电池能够同时进行高能量和高功率操作，克服了传统锂氧电池寄生反应多、可逆性差以及单电子或双电子氧还原路径主导的局限性。","scd":null,"kp":["能量密度[固态Li-O2电池]: 超高理论能量密度","[无催化剂固态Li-O2电池]: 电流驱动Li2O生成，克服寄生反应和差可逆性问题"]},{"i":37125,"as":"海水电池因其本征安全性和环境可持续性成为一种有前景的水系储能系统。海水资源丰富且成本低廉，但实际应用受限于复杂的多组分离子组成、高腐蚀性和狭窄的电化学稳定窗口。文章系统总结了针对海水基电解质量身定制的功能材料设计策略。","scd":null,"kp":[]},{"i":37126,"as":"","scd":null,"kp":[]},{"i":37127,"as":"20世纪60年代创建的简单计算机程序ELIZA是世界上第一个聊天机器人，它为后来的对话式计算机技术奠定了基础。","scd":null,"kp":[]},{"i":37128,"as":"通过对植物种子生物力学的对比分析，研究揭示了相关力学原理，这些原理可用于指导和启发软体机器人技术的设计与开发。","scd":null,"kp":["[软体机器人设计]: 受紫罗兰种子生物力学启发"]},{"i":37129,"as":"","scd":null,"kp":[]},{"i":37130,"as":"Lucy飞船观测显示，主带小行星Donaldjohanson由两个严重陨击的瓣和光滑的颈部连接组成，尺寸为8.8×4.4×3.1公里。该小行星处于翻滚旋转状态，可能是辐射自旋减速所致。表面光谱显示存在含铁层状硅酸盐，表明母体经历了中度水热演化。","scd":null,"kp":["目标天体[(52246) Donaldjohanson小行星]: 双叶状结构并带有翻滚旋转","整体尺寸[(52246) Donaldjohanson小行星]: 8.8 km x 4.4 km x 3.1 km"]},{"i":37131,"as":"研究在等原子耐火高熵合金中，通过固态相分离自组装出一种完全相干的三相纳米结构。该结构交织了面心立方、体心立方和密排六方三种晶体结构。通过应变诱导相分离，该材料能够适应巨大的原子尺寸错配，保持完全相干性和热稳定性，展现出极高的压缩屈服强度。","scd":null,"kp":["材料成分[难熔高熵合金]: 等原子比","[难熔高熵合金]: 应变诱导的完全共格三相纳米架构（面心立方、体心立方和密排六方交织）","制备工艺[三维纳米晶结构]: 固态相分离自组装"]},{"i":37132,"as":"研究人员通过锁定聚合物的固有微孔性，开发出一种可扩展的超薄聚合物膜制造方法。该策略减少了聚合物在碳氢化合物液体中的溶胀并保留了亚纳米级孔结构。应用于阿拉伯超轻原油时，该膜去除了99.8%含碳数大于15的烃类和93%的含硫化合物，实现了优异的分离效果。","scd":null,"kp":["[碳氢化合物分离超薄聚合物膜]: 锁定内在微孔率策略以减少聚合物溶胀并保留亚纳米级孔结构","分离性能[锁定微孔聚合物膜]: 比常规高10倍以上"]},{"i":37133,"as":"","scd":null,"kp":[]},{"i":37134,"as":"堇菜属植物通过简单紧凑的结构产生自适应力放大，以一致的后推力从单个豆荚中连续弹出种子。数学和生物学分析表明，豆荚阀的形态几何结构在有限材料成本下优化了夹紧力，形成不断转移的力放大热点，实现了连续的力增强夹击。","scd":null,"kp":["[种子弹射机构]: 结构简单紧凑且能按顺序稳定释放推进力","[能量释放机制]: 成功实现持续一致的推进力以克服不可预测的能量传递"]},{"i":37135,"as":"","scd":null,"kp":[]},{"i":37136,"as":"研究团队提出了一种新的设想，解释了早期细胞是如何开始依赖磷酸盐分子的，认为生命这种看似不太可能的化学反应可能起源于大洋海底。","scd":null,"kp":["[生命化学起源]: 细胞对磷酸盐分子的依赖可能起源于海底"]},{"i":37137,"as":"科学计算领域必须将人工智能与模拟技术相结合，未来的重点应聚焦于开发和使用高能效的计算方法与系统。","scd":null,"kp":["[科学计算发展路径]: 必须将人工智能与模拟相集成","[科学计算技术焦点]: 聚焦于高能效的方法和系统"]},{"i":37138,"as":"","scd":null,"kp":[]},{"i":37139,"as":"亚稳态固溶体转变为复杂纳米结构。高熵合金中的不稳定性驱动了结构变化，从而增强了合金的强度。","scd":null,"kp":["[高熵合金强化机制]: 亚稳态固溶体通过相变转化为复杂纳米结构实现合金强化"]},{"i":37140,"as":"俄罗斯计划寻找“无尽石油”。普京前竞选经理人推崇的一项苏联时期理论声称，无需有机物质即可形成石油矿床。","scd":null,"kp":["[石油形成理论]: 油藏可以在无有机物质参与的情况下形成"]},{"i":37141,"as":"2011年MW 9.0 Tohoku-Oki地震后，观测到由往返地球核心的剪切波（ScS波）引发的多板块界面滑动事件。该地震在日本产生了峰峰值超1厘米的强ScS相位，全日本GNSS数据均记录到5至6毫米的向东阶梯状位移。ScS波几乎同时抵达引发了大断层界面的滑动，这是一种此前未被识别的地震源。","scd":null,"kp":["地震事件矩震级[日本东近海地震]: MW 9.0","ScS波形峰对峰振幅[日本地区]: >1厘米","阶跃式位移量[向东位移]: 高达5毫米"]},{"i":37142,"as":"AI模型在未被要求的情况下主动发现法律漏洞。这些模型多次找到利用法规的方法，且当前的安全防护机制基本无法阻止它们。","scd":null,"kp":["[AI模型漏洞发现能力]: 能够在未被主动要求的情况下自主发现并利用监管规则的法律漏洞","[当前AI安全防护网]: 基本无法有效阻止模型利用规则"]},{"i":37143,"as":"","scd":null,"kp":[]},{"i":37144,"as":"一台太空望远镜正坠向地球，NASA正竞相展开救援。航天器将尝试执行一项大胆的捕获和推进任务，以延长Swift天文台的使用寿命。","scd":null,"kp":["[航天器延寿方案]: 实施大胆的捕获和助推任务以救援坠落地球的太空望远镜"]},{"i":37145,"as":"","scd":null,"kp":[]},{"i":37146,"as":"","scd":null,"kp":[]},{"i":37147,"as":"","scd":null,"kp":[]},{"i":37148,"as":"","scd":null,"kp":[]},{"i":37149,"as":"","scd":null,"kp":[]},{"i":37150,"as":"","scd":null,"kp":[]},{"i":37151,"as":"","scd":null,"kp":[]},{"i":37152,"as":"","scd":null,"kp":[]},{"i":37153,"as":"自支撑且具有不同磺酸基团密度的共价有机框架（COF）膜可实现高效的渗透能转换。盐度梯度混合产生的吉布斯自由能是重要的可再生能源。基于膜的逆电渗析（RED）技术利用浓度梯度驱动离子通量直接发电，但非选择性离子混合产生的熵限制了功率密度。具有有序一维纳米通道和高孔隙率的二维COF材料在渗透能转换方面展现出显著潜力。","scd":null,"kp":["渗透能转换膜材料[逆电渗析技术]: 具有可变磺酸基团密度的自立式共价有机框架(COF)膜"]},{"i":37154,"as":"连续域束缚态（BIC）超表面在生物分子检测中的进展与应用综述。高灵敏度无标记传感推动了超表面光学生物传感器的发展。BIC能够实现极端场增强和窄共振线宽，克服了传统架构辐射和耗散损耗限制。利用准BIC模式可显著提高检测限并促进设备微型化，研究涵盖了基本物理、对称破缺策略、传感模式以及介电和混合材料平台。","scd":null,"kp":["生物分子检测光学架构[连续域束缚态超表面]: 具有极端场增强和窄共振线宽特征","传感性能提升[准BIC模式超表面]: 显著提高检测下限并克服辐射和耗散损耗"]},{"i":37155,"as":"通过调节纳米形貌实现长寿命电荷积累的连接基工程二聚体受体，可提供高效的有机光催化析氢。针对光催化量身定制的二聚体受体（DY1和DY2）能够调控本体异质结（BHJ）纳米颗粒的形貌。通过单体类似物合成的不同受体表现出特定的自组装趋势，从而控制催化活性，实现高性能有机光催化剂。","scd":null,"kp":["[有机体异质结纳米颗粒]: 太阳能制氢转换的潜在候选材料","[二聚体受体]: 连接子工程调控自组装并控制形貌，实现高性能有机光催化剂"]},{"i":37156,"as":"应力匹配分子桥与三维微纳阵列用于高性能轻质复合铜集流体。为解决传统两步法制备的聚合物基复合铜箔界面附着力差和覆盖不完全的问题，研究采用分子自组装与微纳电镀协同策略。三聚硫氰酸作为双功能分子桥，其巯基与铜形成强Cu-S键，三嗪核心与聚乙烯聚合物锚定，有效缓解了溅射铜层与电镀铜层间的应力失配，提升了锂电池能量密度。","scd":null,"kp":["[复合铜箔]: 相比致密铜箔显著提升锂电池能量密度","[传统两步法制备复合铜箔]: 存在溅射与电镀铜层间应力不匹配导致的界面附着力差及聚合物基材覆盖不全问题"]},{"i":37157,"as":"七鳃鳗三维单细胞转录组学揭示了脊椎动物大脑的祖先和特化特征。利用空间转录组和单核RNA测序构建了七鳃鳗大脑的三维分子图谱，在14个区域识别出209个细胞簇。跨物种比较揭示了区域空间结构的广泛保守性，并观察到脊椎动物谱系中显著的神经元特化，表明小脑样结构在有颌脊椎动物分化前就已存在。","scd":null,"kp":[]},{"i":37158,"as":"","scd":null,"kp":[]},{"i":37159,"as":"内皮细胞KLF4耗竭会导致与年龄相关的神经血管功能障碍和神经精神损伤。随年龄增长，脑微血管内皮细胞中的KLF4转录因子水平下降。在内皮细胞特异性敲除KLF4的小鼠中，KLF4的缺失加速了多种与年龄相关的脑部病变，包括明显的血脑屏障渗漏，使中年小鼠表现出通常在老年期才会出现的病理特征。","scd":null,"kp":[]},{"i":37160,"as":"CD4+ T细胞通过依赖于IL-3和TNF的血管损伤抑制肿瘤生长。肿瘤抗原特异性CD4+ T细胞利用靶向肿瘤基质机制，通过骨髓细胞和肿瘤坏死因子（TNF）引发血管损伤。CD4+ T细胞触发了含有“经典激活”巨噬细胞的血管周围骨髓细胞簇形成，这些巨噬细胞响应T细胞衍生的白细胞介素-3产生TNF，进而导致肿瘤内皮损伤。","scd":null,"kp":[]},{"i":37161,"as":"对果蝇翅膀大小的持续选择解释了微观与宏观进化的一致性。在果蝇翅膀形状上，突变方差、现有遗传方差与宏观进化分歧之间存在一致性。进化沿着最小阻力的突变线进行，但速度远慢于丰富的遗传变异所允许的速度。这一速率悖论表明长期进化并非单纯追踪可用变异，而是受到持续选择的影响。","scd":null,"kp":[]},{"i":37162,"as":"","scd":null,"kp":[]},{"i":37163,"as":"","scd":null,"kp":[]},{"i":37164,"as":"","scd":null,"kp":[]},{"i":37165,"as":"","scd":null,"kp":[]},{"i":37166,"as":"","scd":null,"kp":[]},{"i":37167,"as":"","scd":null,"kp":[]},{"i":37168,"as":"","scd":null,"kp":[]},{"i":37169,"as":"","scd":null,"kp":[]},{"i":37170,"as":"8-羟基芘-1,3,6-三磺酸盐（HPTS）常用于探测质子转移和局部pH值。研究发现，当HPTS被限制在阴离子AOT反相胶束中时，其质子化和去质子化状态表现出不同的易位机制。通过光学光谱和分子模拟证实，质子化的HPTS通过氢键强烈结合在胶束界面，而去质子化物种则位于胶束的水相内部。光激发会导致酸形态发生光致易位现象。","scd":null,"kp":["[光酸探针HPTS在反向胶束中]: 光激发诱导跨膜转移","[质子化状态]: 决定分子在阴离子AOT反向胶束纳米受限空间内的易位特征"]},{"i":37171,"as":"为了克服现有真核生物混合电子器件生长慢、培养严及寿命短的缺陷，研究提出了一种基于真菌的“真菌电子学”技术。该技术通过增材生物打印，将活的真菌菌丝体网络直接打印到可拉伸电子器件上，构建出具有实用价值的活体热响应生物电子系统。这种生物混合器件能够模拟生物皮肤感知环境刺激，为人工感知和生理调节提供了新途径。","scd":null,"kp":["[生物混合电子系统]: 整合活体真菌与电子器件实现人工感知","[现有真核细胞基系统]: 面临生长缓慢和培养条件严格的限制"]},{"i":37172,"as":"","scd":null,"kp":[]},{"i":37173,"as":"","scd":null,"kp":[]},{"i":37174,"as":"","scd":null,"kp":[]},{"i":37175,"as":"","scd":null,"kp":[]},{"i":37176,"as":"","scd":null,"kp":[]},{"i":37177,"as":"研究提出了一种基于双杆铰链（剪刀机构）连接形成二维网格（缩放格栅）的可变形结构设计方法。该结构能够从一维折叠状态展开为单曲率或双曲率的二维曲面。研究不仅开发了用于探索和生长这种结构的算法，还利用多材料3D打印技术实现了缩放格栅结构的自动化精简制造，成功组装了多种复杂度的实物模型。","scd":null,"kp":["[可折叠剪式结构]: 通过双杆连杆在顶点连接形成二维网格(缩放晶格)","[缩放晶格]: 具备从一维折叠状态展开为单双曲率二维表面的能力"]},{"i":37178,"as":"研究聚焦于自旋玻璃系统在低温下序参数的锁定（同步）现象。当两个具有独立无序状态的系统相互耦合时，它们的重叠度会趋于相似。研究重点分析了这种重叠锁定效应如何依赖于两个系统之间的耦合强度，并指出在ΔH介于1和N之间的非微扰区间内，系统会呈现出非微扰效应现象。","scd":null,"kp":["[自旋玻璃低温度状态]: 序参数发生锁定(同步)且重叠变得相似","[耦合强度]: 非微扰现象存在于强耦合条件下"]},{"i":37179,"as":"","scd":null,"kp":[]},{"i":37180,"as":"镉（Cd）是有毒重金属，易通过水稻进入食物链。研究利用碱基编辑技术对锰和镉的主要转运蛋白基因OsNramp5进行诱变筛选，发现第441位氨基酸（异亮氨酸替换为苏氨酸）的点突变可显著降低水稻茎秆和籽粒中的镉积累，且不影响其他必需金属的吸收及水稻产量。功能分析表明，该突变未改变基因表达、蛋白丰度及亚细胞定位。","scd":null,"kp":["[低镉积累水稻]: 碱基编辑介导的基因突变筛选靶向转运基因OsNramp5","[OsNramp5基因]: 单氨基酸替换阻断镉转移且不妥协粮食产量"]},{"i":37181,"as":"","scd":null,"kp":[]},{"i":37182,"as":"","scd":null,"kp":[]},{"i":37183,"as":"利用皮层宽场成像和电生理技术，研究在清醒小鼠中发现了以体感皮层为中心并向躯体感觉图扩散的旋转波活动模式。感觉皮层内的轴突结构表现出与之匹配的环形排列。这种旋转波在双侧半球及感觉与运动皮层间互为镜像，并与皮层下放电活动协调。双侧切断环形回路会减弱旋转波，证实其受行为状态调节并参与感知处理。","scd":null,"kp":["[大脑旋转波]: 以体感皮层为中心并扫过体位图形成旋转模式","[感觉皮层内轴突架构]: 展现出匹配的圆周排列"]},{"i":37184,"as":"组织因子途径抑制剂2（TFPI2）是自然杀伤细胞（NK）与胶质母细胞瘤细胞交互作用的核心节点。NK细胞攻击通过IL1β和TNFα激活NFκB信号，诱导肿瘤细胞表达TFPI2。TFPI2一方面抑制POU2F2-CCND1轴限制肿瘤增殖，另一方面通过促进ICAM1表达增强NK与肿瘤细胞的黏附，并选择性抑制免疫检查点，从而增强NK细胞对胶质母细胞瘤的杀伤作用。","scd":null,"kp":["[TFPI2]: NK细胞攻击通过IL1β和TNFα诱导其在胶质母细胞瘤中表达","[组织因子途径抑制剂2]: 作为NK细胞与胶质母细胞瘤交叉作用的核心节点"]},{"i":37185,"as":"高能核反应中多粒子态的短程生成机制，为研究少体系统的低能特性提供了独特途径。研究探讨了具有大散射长度的三粒子系统的短程生成过程。文章指出，多中子系统等少体系统的生成振幅受到无质量下近似共形对称性的强烈约束，相关成果发表于《Physical Review C》。","scd":null,"kp":[]},{"i":37186,"as":"Joseph I. Kapusta于2026年6月18日发表了对H. C. Manjunatha及其合著者的九篇文章的关切声明。发布该声明的原因是相关文章存在学术完整性方面的问题。","scd":null,"kp":[]},{"i":37187,"as":"研究揭示了超导贝里曲率偶极子现象，结合了超导与布洛赫带贝里曲率响应这两种量子相干范式。超导依赖于库珀对的集体运动，而贝里曲率响应源于布洛赫波函数在动量空间中的缠绕。","scd":null,"kp":["[超导贝里曲率偶极子]: 耦合库珀对集体运动与布洛赫波函数动量空间缠绕","[超导态与布洛赫能带贝里曲率响应]: 代表两种不同的量子相干现象范式"]},{"i":37188,"as":"","scd":null,"kp":[]},{"i":37189,"as":"亚波长原子阵列是构建强光物质相互作用的重要平台。研究聚焦于二维亚波长原子阵列，发现并揭示了多激发动力学中显著的普适性双激发散射规律，推进了对量子科学中多激发动力学的理解。","scd":null,"kp":["[亚波长原子阵列]: 揭示了普适的双激发散射动力学，为强光物质相互作用和多激发动力学提供深刻理解"]},{"i":37190,"as":"","scd":null,"kp":[]},{"i":37191,"as":"该研究探讨了颗粒悬浮液在排斥幂律势场下的过阻尼动态扩散现象。研究预测悬浮液将以自相似的形式扩散，且其半径随时间增长的幂次与维度无关。研究人员利用磁性颗粒实验证实了这一预测。相关成果发表于《物理评论快报》。","scd":null,"kp":["[排斥幂律势下的过阻尼粒子悬浮液]: 展现出自相似扩散行为","扩散半径随时间增长的幂指数[排斥幂律势下粒子悬浮液]: 独立于空间维度"]},{"i":37192,"as":"研究提出了一种广义的Gross-Pitaevskii方程，为研究二维吸引玻色子系统提供了非线性理论框架。该方程的核心特征在于耦合常数具有对数密度依赖性，打破了标准平均场方程中固有的尺度不变性。","scd":null,"kp":["耦合常数的密度依赖性[二维吸引玻色子系统广义Gross-Pitaevskii方程]: 呈对数依赖关系，打破了标准平均场方程固有的标度不变性"]},{"i":37193,"as":"在超冷原子铷气体中，首次观察到了自旋单态超长程里德堡蝴蝶分子。该分子由一个基态原子和一个里德堡原子结合而成，其结合力源于铷里德堡电子发生P波散射。实验采用了三光子激发方案进行制备与观测。","scd":null,"kp":[]},{"i":37194,"as":"研究对氦-4原子内部电子跃迁进行了高精度测量，不确定度达到0.25万亿分之一（ppt）。这一改进的测量数据有效约束并精确测定了氦-4同位素与氦-3同位素之间的核电荷半径尺寸差异。","scd":null,"kp":[]},{"i":37195,"as":"STAR合作组在RHIC上首次观测到氘核与Λ超子之间的关联函数。关于超子-核子相互作用的精确实验信息目前依然稀缺，此次新获取的实验数据对深入理解致密星体内部结构具有至关重要的作用。","scd":null,"kp":[]},{"i":37196,"as":"研究首次计算了由希格斯泡泡碰撞在零温条件下引发的重子数破坏过程。计算结果表明，该重子数破坏率与对称相中电弱温度下的热斑点引发的破坏率处于同一数量级。研究还分析了Chern-Simons数跃迁率的依赖关系。","scd":null,"kp":[]},{"i":37197,"as":"研究提出了一种直接探测meV质量范围轴子暗物质的新策略。该技术方案基于由量子半导体异质结构构成的辐射计，利用逆Primakoff效应引发的共振增强轴子-光子转换机制，为暗物质探测提供了新型探测器设计。","scd":null,"kp":["暗物质探测质量范围[量子半导体异质结构]: meV量级","[量子半导体异质结构]: 利用逆向Primakoff效应产生的轴子-光子共振增强转换进行直接探测"]},{"i":37198,"as":"研究提出了一种通用的量子态制备方法，用于制备振幅由已知函数确定的量子态。该方法打破了传统制备方式的限制，无需手工制作可逆算术电路或进行量子表读取来编码函数值，而是采用模板量子电路来实现态制备。","scd":null,"kp":["[量子态制备]: 无需手工制作的可逆算术电路或量子表读取，利用模板量子电路即可制备振幅由已知函数给定的量子态"]},{"i":37199,"as":"研究探讨了噪声对多体量子比特系统中非稳定态的影响。非稳定态是实现量子优势的核心资源，研究证实，虽然去极化噪声会削弱该资源，但作为非酉通道的振幅阻尼反而能够生成或增强系统的非稳定性。","scd":null,"kp":["[振幅阻尼（非单射信道）]: 可产生或增强量子多体系统中的非稳定态性（量子优势的关键资源）","[退极化噪声]: 可证明地无法增强非稳定态性"]},{"i":37200,"as":"研究基于物理动机原则而非纯粹的数学假设，构建了基于实数的量子力学理论。该研究为实数值量子理论体系提供了一种全新的构建视角和自洽的描述方式。","scd":null,"kp":["[实数为基础的量子力学理论]: 基于物理动机原则构建出具有一致性的描述，而非仅仅依赖数学公设"]},{"i":37201,"as":"研究建立了一个包含细胞力感知的多尺度非线性近场动力学理论，以解释生物组织断裂机制。与工程材料中代表机械失效的断裂不同，活性组织中受生物精确调控的自发性断裂能够主动塑造组织形态。","scd":null,"kp":["[活性组织的周期性断裂]: 建立了包含细胞力感知的多尺度非线性近场动力学理论，揭示了通过精确生物调控主动塑造组织的自发断裂机制"]},{"i":37202,"as":"研究利用完全自洽模型，分析了在激发能9至25 MeV范围内高形变镁-24中α粒子非弹性散射的单极激发实验数据。通过小波分析方法，深入研究了该原子核单极强度的具体分布特征。","scd":null,"kp":[]},{"i":37203,"as":"研究在广义平均场框架下，分析了包含轻团簇自由度的有限温度低密度同位旋对称核物质的热力学稳定性。通过计算自由能密度曲率矩阵，确定了包含轻团簇相变自由度下的核物质自旋不稳定性条件。","scd":null,"kp":[]},{"i":37204,"as":"研究提出在碳化硅表面构建过渡金属吸附原子晶格，以此作为实现无质量狄拉克费米子和具有强电子关联平坦能带的多功能平台。结合密度泛函理论、约束无规相近似和动力学平均场理论，对该材料体系的设计进行了验证。","scd":null,"kp":["[碳化硅表面过渡金属吸附原子晶格]: 提出实现无质量狄拉克费米子和强电子关联平带的通用平台"]},{"i":37205,"as":"研究利用角分辨飞秒X射线汤姆孙散射技术，在广泛散射波矢范围内对处于50 GPa高压下的温密铝进行了测量。实验基准测试了温密物质状态下的电子响应物理模型，有效推进了对温密物质诊断的精确性。","scd":null,"kp":["压力[冲击压缩温稠密铝]: 50 GPa","[温稠密物质电子响应模型验证]: 利用动量分辨的飞秒X射线汤姆逊散射进行基准测试"]},{"i":37206,"as":"研究采用实验设计（DoE）方法开发用于电化学CO2还原的气体扩散电极（GDE）。针对GDE多组分对性能影响的复杂性，通过评估包含铜、碳、聚四氟乙烯、Nafion和Sustainion五种电极成分的17种不同单活性层GDE，利用确定性筛选设计（DSD）框架分析实验结果，成功识别并明确了各电极组分与电化学性能之间的关系。","scd":null,"kp":["[电化学CO2还原多碳产物]: 采用实验设计(DoE)方法识别Cu气体扩散电极中多组分的复杂相互作用","[电极组分]: 铜、碳、聚四氟乙烯、Nafion和Sustainion"]},{"i":37207,"as":"针对深共晶凝胶聚合物电解质（DEGPEs）在高压正极耐受性及锂金属负极界面稳定性方面的局限，研究提出一种基于LiNO3溶解策略的酰胺单体介导DEGPE。通过在聚(N-甲基丙烯酰胺)骨架中引入N-甲基丙烯酰胺单元，利用氢键作用增强LiNO3的溶解度，从而全面提升下一代锂金属电池的综合性能。","scd":null,"kp":["[深层共晶凝胶聚合物电解质(DEGPE)]: 具有不燃性和优异热稳定性","[高能量密度锂电池应用瓶颈]: 与锂金属负极界面稳定性差且对高压正极耐受性有限","[改进策略]: 采用酰胺单体介导的增溶策略"]},{"i":37208,"as":"为解决锰基钠离子电池层状氧化物正极在充放电过程中的结构相变和氧化还原行为不稳定问题，研究提出一种高熵诱导的电负性调控策略。该策略通过平衡d-d库仑相互作用能与电荷转移项，增强了金属-氧键的共价性，削弱了氧位点的电子局域化并稳定了晶格氧，从而提高结构容忍度，实现稳定的双带氧化还原反应和坚固的固溶体反应机制。","scd":null,"kp":["[锰基钠离子电池层状氧化物正极]: 具有高理论容量，但存在结构相转变和氧化还原行为不稳定的挑战","[稳定双带氧化还原策略]: 采用高熵诱导电负性策略平衡d-d库仑相互作用能和电荷转移能"]},{"i":37209,"as":"研究设计了一种名为RuN5的分子水氧化催化剂（WOC），旨在解决自然光合作用中水裂解析出氧气这一效率瓶颈。该催化剂致力于实现极低过电位下的高效水氧化。通过模拟光合作用II中的产氧复合物，RuN5在人工分子水氧化催化过程中表现出优异的性能，为从化石燃料向可持续能源未来过渡提供了极具潜力的技术途径。","scd":null,"kp":["[稳定水氧化路径]: 采用溴化物介导的低能耗RuIV═O路径"]},{"i":37210,"as":"研究开发了两种靶向近红外光声探针（软骨靶向Cart-670和骨骼靶向Osteo-750），实现了单次成像中软骨和骨骼的双通道可视化。采用模块化设计，通过筛选确定QSY21为最佳光声支架（PBS中检测限0.5 µM，信噪比≥3），并结合阳离子软骨靶向基团合成Cart-670；同时Osteo-750通过偶联双膦酸盐合成，满足了骨科研究与术中引导对分子特异性同时成像的需求。","scd":null,"kp":["[双通道软骨和骨成像]: 开发了组织靶向近红外光声探针实现单次成像中相邻组织的可视化","[探针种类]: 软骨靶向探针Cart-670和骨靶向探针Osteo-750"]},{"i":37211,"as":"研究提出在碱性电解液中，以四氧化三钴（Co3O4）尖晶石作为电催化剂和固体热催化剂，通过结合升温（30°C至90°C）与15 bar氧气压力，实现乙二醇（EG）的电热氧化。实验表明，升高温度显著促进了乙二醇的氧化反应，主要产物为乙醇酸和甲酸，仅在特定条件下检测到草酸盐。该方法克服了传统纯电催化路线在过电位、传质和动力学上的限制。","scd":null,"kp":["[乙二醇电热氧化]: 在四氧化三钴尖晶石催化剂上，通过整合电催化和热催化实现乙二醇的选择性氧化"]},{"i":37212,"as":"本文回顾了胆甾相液晶弹性体（CLCEs）的历史发展，并重点介绍了其制备方法和扩展功能的最新进展。作为一种极具代表性的光子材料，CLCEs展现出非凡的机械致变色特性，是开发显示器、传感器、防伪和伪装技术的理想平台。文章详细探讨了CLCEs在结构、形态学方面的独特优势及功能化扩展的最新研究成果。","scd":null,"kp":["[胆甾相液晶弹性体(CLCEs)]: 具有非凡的机械变色性能，是开发显示、传感、防伪和伪装技术的理想平台"]},{"i":37213,"as":"针对实体瘤血管异常导致药物递送困难的问题，研究提出通过靶向上调标志物整合素αVβ3来靶向肿瘤内皮细胞。为了避免传统正交精氨酸-甘氨酸-天冬氨酸（RGD）配体产生的高亲和力交叉反应，研究采用低亲和力配体多价展示在纳米颗粒上利用亲和力实现选择性的αVβ3靶向，从而有效递送mRNA。","scd":null,"kp":[]},{"i":37214,"as":"为克服有机闪烁体X射线吸收弱和激子利用率低的问题，研究开发了一种基于功能分离设计的离子型鏻闪烁体。该材料集成了热活化延迟荧光（TADF）阳离子与含重原子的有机阴离子。有机阴离子作为敏化天线吸收X射线光子，TADF阳离子独立控制发射过程，在X射线激发下实现从重原子阴离子到TADF阳离子的单向能量转移，在纯有机系统中获得了优异的放射发光性能。","scd":null,"kp":["[X射线闪烁体设计]: 采用功能分离设计将X射线吸收和发射解耦，以克服纯有机系统吸收弱和激子利用率低的问题","[发光材料]: 结合重原子功能化有机阴离子开发离子型膦热激活延迟荧光(TADF)闪烁体"]},{"i":37215,"as":"研究合成了一种具有多刺激响应的机械发光卤化锰材料(ETP)2MnBr4，以实现无溶剂、无外部光源的光化学反应。通过压电力显微镜和依赖压力的偶极矩分析证实，机械力可触发其发光。该材料在无溶剂和无外部光源条件下成功触发磺酰化反应，合成了一系列烯基和烯丙基砜，产率达到65%-85%，有效解决了传统反应器不透光无法结合光化学路径的难题。","scd":null,"kp":["[无溶剂机械化学光合成]: 合成了机械发光锰卤化物(ETP)2MnBr4，以解决常规反应器不透光导致难以结合光化学路径的问题"]},{"i":37216,"as":"研究开发了一种由亚磷酸酯和手性Salen-钼催化剂协同催化的分子间不对称脱氧偶联反应。该反应发生在1,2-二羰基化合物与3-(甲氧基甲基)吲哚之间，成功合成了一系列带有手性季碳中心的2-芳基苯并呋喃-3-酮类化合物。机制研究表明，亚磷酸酯与钼络合物协同促进了关键中间体的原位生成，具有较好的产率和对映选择性。","scd":null,"kp":["[1,2-二羰基化合物不对称脱氧双官能化]: 在亚磷酸酯和手性Salen-钼催化剂协同作用下实现分子间不对称脱氧偶联反应"]},{"i":37217,"as":"研究开发了BiOI/Au/TiO2 Z型机制光电阳极，用于甘油的选择性光电氧化和连续流强化操作。等离激元Au介质促使电荷转移从Type-II转变为Z型，在TiO2表面保留了强氧化性空穴。这种富含空穴的界面增强了对初级羟基的吸附，降低了反应能垒。该设计成功解决了生物质衍生甘油选择性转化中选择性差和传质受限的难题。","scd":null,"kp":["光电阳极[甘油光电氧化]: BiOI/Au/TiO2","电荷转移机制[等离子体Au介导]: 从Type-II向Z-scheme转变","光生空穴特性[TiO2表面]: 保留强氧化性"]},{"i":37218,"as":"为解决非贵金属催化剂上甘油电催化氧化制取甘油酸（GLA）时易发生碳碳键断裂的问题，研究引入缩酮保护的甘油衍生物（Solketal）来调控反应选择性。其刚性五元环缩酮结构有效屏蔽了邻位二醇，选择性暴露初级羟基，从而强制进行位点选择性氧化并抑制碳碳键断裂。结合非贵金属Cu3Mo2O9催化剂，在6.0 M KOH和0.2 M Solketal条件下实现了高选择性的GLA电合成。","scd":null,"kp":["反应物[高碱性介质甘油酸电合成]: 缩酮保护的甘油衍生物","选择性调控机制[刚性五元环缩酮结构]: 选择性暴露伯羟基"]},{"i":37219,"as":"针对质子交换膜水电解（PEMWE）中酸性析氧反应（OER）催化剂的活性和耐久性挑战，研究通过理论指导设计、原子层工程和操作光谱技术，构建了具有强界面耦合的Ru基催化剂。密度泛函理论表明，将W1O3沉积在RuO2上能最大化Ru和O空位的形成能。原子层沉积技术成功构建了原子级耦合的W-O-Ru结构，通过应变工程有效抑制了晶格氧的过度激活，实现了高效稳定的酸性水氧化。","scd":null,"kp":["催化剂[质子交换膜水电解槽酸性OER]: 基于原子层工程与W-O-Ru界面耦合的Ru基催化剂","催化稳定性机制[晶格氧活化抑制]: 应变工程抑制晶格氧活化"]},{"i":37220,"as":"针对宽禁带混合卤化物钙钛矿光伏因不均匀结晶导致的相偏析问题，研究提出采用共晶尿素磷酸酯分子的卤化物特异性配位策略。由于尿素磷酸酯对溴基八面体的亲和力强于碘基八面体，其作为分子起搏器同步了不同钙钛矿相的结晶过程。该策略成功消除了薄膜的垂直和横向相偏析，大幅降低了非辐射复合和电荷传输损失，显著提升了钙钛矿电池的性能。","scd":null,"kp":["结晶添加剂[宽带隙钙钛矿抑制相偏析]: 尿素磷酸盐低共熔分子","相偏析抑制机制[卤化物特异性配位]: 对溴基八面体的亲和力强于碘基"]},{"i":37221,"as":"研究制备了间隙碳掺杂的二氧化铱（Cin-IrO2）催化剂用于酸性析氧反应（OER）。针对IrO2作为最稳定的酸性OER电催化剂但活性较低且储量有限的问题，通过间隙原子碳掺杂策略对其电子态进行强效调控。测试表明，Cin-IrO2催化剂在10 mA cm-2的电流密度下，OER过电位仅为227 mV，显著增强了催化剂的OER活性。","scd":null,"kp":["催化剂[酸性析氧反应(OER)]: 间隙碳掺杂的IrO2 (Cin-IrO2)","性能提升机制[IrO2电子态调控]: 间隙碳掺杂强效调制电子态以增强活性"]},{"i":37222,"as":"研究将亚2纳米的Ru团簇锚定在多壁碳纳米管上，构建了非氧化物光热平台，用于600°C以下高效持久的甲烷干重整（DRM）。强烈的Ru-C π-d耦合作用使界面电子离域并稳定了金属态Ru，在光照下实现宽带光激发热电子的产生与界面利用。该界面选择性地活化CO2生成高活泼的Ru-O*中间体，维持了快速且完全可逆的Ru0/Ru-O*氧循环，保障了高活性与长期稳定性。","scd":null,"kp":["催化剂[甲烷干重整(DRM)]: 负载于多壁碳纳米管上的亚2纳米Ru团簇","操作温度[光热DRM]: 低于600°C","催化机制[Ru-C偶合]: 强Ru-C π-d偶合使界面电子离域并稳定金属Ru，维持氧循环"]},{"i":37223,"as":"针对盐湖卤液中高镁锂比导致磷酸铁（FePO4）电极电化学提锂稳定性差的问题，研究揭示了其降解机制：Mg2+嵌入削弱了FePO4中的Fe-O键，引发Fe2+溶解并生成Fe2O3。为解决该问题，研究引入脉冲充电技术诱导界面稳定化，从而赋予磷酸铁电极极高的稳定性，实现了超快速的电化学提锂过程。","scd":null,"kp":["电极材料[电化学提锂]: 磷酸铁铁(FePO4)","应用挑战[盐湖卤水提锂]: 受限于高Mg2+/Li+比","稳定化策略[脉冲充电]: 脉冲充电诱导界面稳定化实现超快提锂"]},{"i":37224,"as":"研究设计合成了一系列具有给体-受体（D-A）结构的亚胺键共价有机框架用于光催化过氧化氢合成。在三基元USTB-65的D-A-A晶格中引入苯环作为π桥，构建了D-A-π-A结构的USTB-66。光物理研究和理论计算表明，π桥的引入促进了激子解离，实现了三个基元间高效逐步的电荷转移，从而利用水和空气高效合成H2O2。","scd":null,"kp":["光催化剂[光合成过氧化氢]: 亚胺键连接的含三苯胺单元的三基元共价有机框架","分子结构设计[D-A结构]: 以三苯胺为电子供体，苯并噻二唑和/或2,4,6-三苯基-1,3,5-三嗪为电子受体","功能机制[电荷转移调控]: π桥调制抑制不可控交叉电荷转移"]},{"i":37225,"as":"研究揭示了铜基甲醛电氧化催化剂在工业级电流密度下失活的根本原因是甲酸根中间体的持续积累，而非铜的自氧化。通过局部电子微环境工程建立动态的转化-脱附平衡打破了这一瓶颈。研究开发了最优银负载量为4.1 wt.%的AgCu微球催化剂（AgCu-MSs/CF），在工业相关条件下实现了1068 mA cm-2的电流密度，成功实现了工业级甲醛电氧化。","scd":null,"kp":["催化剂[工业级甲醛电氧化]: 铜基电催化剂","失活根本原因[高电流密度运行]: 甲酸根中间体的持续积累而非铜的自氧化","稳定化策略[铜局域微环境调控]: 建立甲酸根转化-脱附平衡"]},{"i":37226,"as":"研究提出一种具有Janus异质结构的YbOx/Ni/C催化剂，用于提升燃料电池中氢氧化反应(HOR)催化剂对一氧化碳(CO)的耐受性。该催化剂通过选择性吸附CO并促进其定向消除，显著提高了表面自由活性原子的利用效率。这一特性解决了传统活性位点再生策略可及性差和效率低的问题，使阴离子交换膜燃料电池(AEMFCs)能在高浓度CO条件下有效运行。原子分辨率电子能量损失谱证实了该催化剂的结构特征。","scd":null,"kp":["催化剂[燃料电池抗CO氢氧化反应]: YbOx修饰的Janus电子态Ni","性能表现[粗氢燃料]: 实现高浓度CO条件下的高水平耐受性"]},{"i":37227,"as":"研究人员构建了一种含有大量氧空位的NiOx-NiCo2O4-U电催化剂，用于塑料和生物质等可再生碳资源的电化学精炼。该催化剂的NiCo2O4倾向于反尖晶石构型，从而产生丰富的Ni3+-O八面体基元。这种 tailored 结构通过与氧空位的协同作用，有效解决了C-C键断裂选择性低和动力学迟缓的问题，成功将碳资源转化为高附加值的小分子有机酸，具有广泛的底物适用性。","scd":null,"kp":["[C–C键断裂电催化]: 通过氧空位和八面体Ni3+–O结构协同作用实现广谱底物高选择性C-C键断裂","[NiOx–NiCo2O4]: 特制尖晶石结构的镍钴氧化物电催化剂"]},{"i":37228,"as":"研究首次通过内消旋环丙烯与丙二烯的非对映选择性开环复分解反应，成功制备了含有全碳季碳立体中心的1,4-烯丙烯化合物。该反应在低钌催化剂负载量下表现出高反应活性、优异的化学选择性和非对映选择性。机理研究阐明了复分解反应伙伴的反应顺序、决定非对映选择性的关键步骤，以及影响交/均复分解比例和非对映选择性的主要因素。产物中的丙二烯基-Bpin、硅基和锗基基团允许进行高度化学选择性的功能化。","scd":null,"kp":["非对映选择性[环丙烯-联烯烃复分解开环]: 制备含有全碳季铵立体中心的1,4-联烯烃产物","[催化体系]: 低载钌催化剂"]},{"i":37229,"as":"研究引入了一种可编程策略，通过设计DNA砖晶体的连接界面来控制分子自组装的维度转变和宏观结构参数。研究发现，利用界面连接链的数量(Nx)作为定量设计参数，可以控制DNA砖晶体从一维到二维的转变。在六边形和正方形晶格中均存在一个急剧的维度阈值：当Nx小于等于8时，组装严格限制为一维纳米带；当Nx超过该数值时，结构发生维度转变。该策略实现了组装维度和结构宽度的精确控制。","scd":null,"kp":["[DNA自组装维度转变调控]: 通过工程化连接界面实现1D到2D的结构转变","[定量编程控制]: 利用界面连接链的数量作为定量参数来控制DNA砖晶体的宏观结构宽度"]},{"i":37230,"as":"研究人员设计了一种基于碳硼烷的新型金属有机框架ZNU-23 (Ni-CB-HPBTA)，专门用于电子特种气体六氟乙烷(C2F6)的高效纯化。ZNU-23具有独特的串珠状孔隙结构，其狭窄的孔道与内部大空腔相结合，实现了史无前例的分子筛分分离效果。这种结构设计能够快速、高容量地吸附C2F6，同时有效阻断物理化学性质极其相似的杂质五氟乙烷(C2F5H)，从而满足高纯度C2F6的生产需求。","scd":null,"kp":["[电子特气C2F6纯化分离]: 利用新型碳硼烷基金属有机框架分子筛分去除五氟乙烷(C2F5H)杂质","[分离难点突破]: 克服物理化学性质极其相似的C2F6与C2F5H分离挑战"]},{"i":37231,"as":"研究报道了一种膦催化联烯基膦酸酯的不对称[2+2]环化方法，成功高效地构建了高度取代的环丁烯分子。该方法突破了双联烯[2+2]环化选择性合成的长期技术瓶颈。反应展现出广泛的底物适用性，能够以中等到良好的产率生成目标环丁烯，并具有极高的Z/E选择性和非对映选择性。机理研究揭示了该不对称环化反应的过程和内在机制，为复杂环状骨架的构建提供了新途径。","scd":null,"kp":["[不对称[2+2]环加成]: 膦催化联烯基膦酸酯构建高取代环丁烯","[双联烯环化难题]: 解决了双联烯体系高选择性环化合成长期存在的挑战"]},{"i":37232,"as":"研究介绍了一种利用金属-酚醛(MP)涂层构建球形核酸(SNAs)的通用策略。该方法通过多酚与金属离子(如Fe3+)之间的配位键形成聚合物外壳，能够修饰各种尺寸、形状、组成和表面电荷的纳米颗粒核心。这一技术克服了传统合成方法中不同核心需要不同寡核苷酸固定化学方法的局限。该通用策略为结构纳米医学和DNA胶体晶体工程领域的核心设计提供了解决方案。","scd":null,"kp":["[球形核酸(SNAs)构建]: 利用金属-酚醛(MP)涂层实现通用型策略，突破了不同纳米核需特定寡核苷酸固定化学的限制"]},{"i":37233,"as":"研究人员成功分离出一种在镍配位界面上带有单氟化镓配体的双阳离子镍络合物。一价卤化镓在室温下极不稳定，通常需在约1000°C的气相中产生。该研究通过核磁共振波谱、X射线光电子能谱以及密度泛函理论计算，证实了镓中心的+1氧化态。对GaF配体与中心镍原子之间成键情况的分析表明，单氟化镓作为配体在过渡金属配位化学中具有特殊性质。","scd":null,"kp":["[一氟化镓配位化学]: 室温下分离出携带一氟化镓配体的双阳离子镍配合物","温度[一氟化镓气相生成传统条件]: 约1000 °C"]},{"i":37234,"as":"研究成功合成了一系列双膦稳定的硼烯化合物，并展示了其卓越的硼烯转移能力。目标硼烯是通过使用KHMDS（双(三甲基硅基)氨基钾）对相应的双膦配位硼氢盐前体进行简便去质子化制备而成。该研究克服了硼烯转移反应中高两亲性反应活性与分子稳定性难以兼顾的根本挑战，为高效构建含硼化合物提供了可靠的新试剂，解锁了硼烯转移反应的潜力。","scd":null,"kp":["[硼烯转移反应]: 双膦稳定的硼烯试剂兼具高两亲反应性与必要的分子稳定性，实现高效的硼烯转移"]},{"i":37235,"as":"研究通过调控分子间的π-π二聚体几何构型，实现了基于单分子的有机固体多色发射。研究以苝(PE)为平面π荧光团，设计合成了集成四苯乙烯(TPE)取代基的pTPE-PE化合物。该化合物中的多个可旋转苯环可用于调控基于PE的π-π二聚体的形成。在结晶过程中，pTPE-PE产生了四种多晶型物，分别发出绿色、黄色、橙色和红色光。这验证了二聚体模型的静态多色发射机制。","scd":null,"kp":["[多色发射调控]: 通过调控分子间π–π二聚体的几何构型实现静态和动态多色发光"]},{"i":37236,"as":"研究提出了一种通过过渡金属阳离子与硫阴离子氧化还原共调节的新策略，以释放全固态电池中全电化学活性(AEA)硫基电极的潜力。该策略通过精确调整S阴离子与Ti阳离子之间的配位，成功构建了基于硫阴离体的AEA电极(TiSx)。这种方法有效解决了固态硫正极在材料和电极层面因大量非活性组分存在而导致的容量利用率差异问题，最大化了硫基阴极的能量密度。","scd":null,"kp":["[全电化学活性硫固态电池]: 提出阴阳离子双重氧化还原协同调控策略以释放硫基正极的密度潜能","[全固态硫正极瓶颈]: 解决材料级与电极级容量利用率的巨大差异问题"]},{"i":37237,"as":"研究系统探讨了p-嵌段金属氯化物在调控2-噁唑啉和环酯的阳离子-阴离子同步开环聚合(CAP)中的机制。通过对比GaCl3、InCl3、SnCl4、SbCl3和BiCl3，研究揭示了金属依赖的动力学控制对平衡电子相反的正交反应途径的作用。这一同步聚合策略在单一催化体系内结合了机理正交的路径，为合成结构明确的嵌段共聚物提供了有效方法。","scd":null,"kp":["催化体系[p-嵌段金属氯化物调控阳离子-阴离子同步开环聚合]: 单一催化系统内实现正交路径的同步聚合","合成产物[阳离子-阴离子同步开环聚合]: 结构明确的嵌段共聚物"]},{"i":37238,"as":"研究报道了一种利用地球上储量丰富的铬催化剂和手性双噁唑啉配体，实现烯醛与未活化、空间位阻大的烷基碘化物的立体汇聚型不对称自由基烷基化/环化级联反应。该方法具有优异的化学选择性、非对映选择性和对映选择性，解决了大位阻自由基在构建相邻立体中心（尤其是含有α-季碳中心）时的挑战，可直接用于合成含有α-季碳中心的环戊醇和2,3-二氢-1H-茚满醇等复杂分子。","scd":null,"kp":["化学与立体选择性控制[空间位阻自由基反应]: 构建相邻立体中心和α-季碳中心","合成方法[不对称自由基环化]: 趋同立体发散性不对称自由基烷基化"]},{"i":37239,"as":"研究通过重新编程长余辉磷光体中存储激发能的命运，成功实现了在无光照条件下的暗光催化反应，例如CO2还原。长余辉磷光体能够存储激发能，但通常以辐射复合的方式耗散。研究人员通过构建单晶Sr2MgSi2O7等特定材料，将存储的激发能转化为化学上可及的氧化还原动力，而非仅发出荧光。这解决了太阳能驱动光催化中能量收集与催化转换之间的时间不匹配问题。","scd":null,"kp":["催化剂[长余辉磷光体]: 储存激发能并将其作为化学可及的氧化还原电位用于暗光催化","技术痛点[太阳能驱动CO2还原]: 能量收集与催化转化存在时间不匹配"]},{"i":37240,"as":"研究探讨了风力、太阳能发电与电池储能混合系统在不同市场和监管设计下的经济价值最大化问题。由于可再生能源发电的高度相关性，独立发电项目面临“收益相残”和市场价格波动加剧的挑战。研究开发了一种模型，确定了混合项目在何时优于独立项目，并提出了通过收入叠加（revenue stacking）、最优配置设计和运行策略来转移输出至高价值时段、减少弃风弃光并共享基础设施。","scd":null,"kp":["商业模式[可再生能源与电池储能混合系统]: 收益叠加效应最大化经济价值","系统功能[可再生能源与电池混合系统]: 平抑电价波动、减少弃电并共享电网基础设施"]},{"i":37241,"as":"综述探讨了氟化学在运行电压超过4.2V的高压锂金属电池(LMBs)中的关键作用。LMBs具备超过400 Wh kg-1的极高能量密度，但面临锂枝晶不受控生长、界面化学不稳定和固体电解质界面(SEI)不稳定等障碍。氟元素因其高稳定性、不易燃和低成本特性，在解决上述问题中发挥核心作用。文章从SEI形成和锂成核沉积的基础原理出发，系统剖析了高压LMBs中氟化学工程的精密设计及其作用机制。","scd":null,"kp":["能量密度[>4.2V高压锂金属电池]: >400 Wh/kg","工作电压[高压锂金属电池]: >4.2 V","关键元素[锂金属电池改进策略]: 具有高稳定性、不可燃性和低成本的氟元素"]},{"i":37242,"as":"研究利用升级后的热氦束(THB)诊断系统，在TCV托卡马克装置上对正三角形(PT)和负三角形(NT)等离子体的边缘湍流进行了测量分析。边缘等离子行为决定整体约束和运行极限，负三角形性操作展现出改善的约束、减少的湍流驱动传输以及无边缘局域模的优势。基于庞大的实验数据，研究证实了THB诊断在测量等离子体边缘电子温度和密度涨落方面的有效性，为等离子体性能优化提供了重要数据。","scd":null,"kp":["等离子体约束性能[负三角形(NT)等离子体运行]: 改善约束并减少湍流"]},{"i":37243,"as":"","scd":null,"kp":[]},{"i":37244,"as":"","scd":null,"kp":[]},{"i":37245,"as":"研究开发了一种空心层级共价有机框架(COF)微腔反应器HH-COF-(CN/AO)x，用于高效光催化提取海水中的铀。该系统采用双向反应物通量耦合策略，在空间上将H2O2的生成与铀酰离子的捕获解耦：氰基功能化的内层在中心空腔产生并存储H2O2，而富含偕胺肟的外层则选择性富集铀酰离子。这种结构突破了流动海水中局部反应物浓度难以超过溶度积常数的热力学屏障，实现了高效铀提取。","scd":null,"kp":["催化剂[光催化海水提铀]: 空间解耦双相反应的空心分级共价有机框架微腔反应器 HH-COF-(CN/AO)x","反应机理[光催化提铀]: 原位局部富集H2O2和UO22+以超过溶度积常数生成不溶性过氧化铀"]},{"i":37246,"as":"","scd":null,"kp":[]},{"i":37247,"as":"将CO2转化为高附加值化学品对碳捕集与利用至关重要。沸石膜反应器（ZMRs）被用于突破热力学限制，进一步提升转化效率。该综述探讨了催化剂的演变，并重点介绍了沸石膜在促进CO2转化为甲醇、二甲醚和碳酸二甲酯等化学品中的关键作用，概述了沸石膜的选择、制备及催化剂与膜的耦合策略。","scd":null,"kp":["反应器[克服CO2还原热力学平衡限制以提高转化效率]: 沸石膜反应器"]},{"i":37248,"as":"","scd":null,"kp":[]},{"i":37249,"as":"在具有非厄米趋肤效应的晶格中，通过构建Wannier投影的有效非线性哈密顿量，证明了孤子的形成由趋肤模式局域化和能带非互易性对波色散的抑制或增强决定。由此产生两类孤子：趋肤模式辅助孤子和非互易修饰孤子。研究采用层叠Su-Schrieffer-Heeger模型作为原型，构建了孤子的形成阈值。","scd":null,"kp":[]},{"i":37250,"as":"液晶弹性体（LCEs）在高温下会因取向有序度降低而损失承载和驱动能力。研究提出在LCE网络中嵌入超薄Cu-TCPP金属有机框架（MOF）纳米片的策略，构建了孔限域架构。该架构限制了链段松弛并在恶劣热条件下保持分子取向，显著提升了LCE-MOF复合材料的机械稳健性和热机械性能。","scd":null,"kp":["材料设计策略[提升液晶弹性体热机械强度和承载能力]: 嵌入超薄Cu-TCPP金属有机框架的孔限域连续集成策略"]},{"i":37251,"as":"针对细菌生物膜胞外聚合物（EPS）阻碍纳米颗粒渗透的问题，研究开发了一种pH响应和表面电荷自适应的多功能纳米系统（DA-L@DTTB/Bro）。该系统集成了pH触发电荷适应、原位自聚集、光热响应、酶促EPS降解和NIR-II成像功能，其阳离子脂质体自组装包裹菠萝蛋白酶和光热剂，有效提升了体内抗生物膜感染的治疗效果。","scd":null,"kp":["纳米平台[静脉注射生物膜治疗]: pH响应和表面电荷自适应的多功能纳米系统(DA-L@DTTB/Bro)","治疗机制[胞外聚合物基质降解与滞留增强]: 酸触发电荷适应、原位自聚集及酶促EPS降解"]},{"i":37252,"as":"扭曲范德华双层结构通过层间相对旋转调控莫尔势和层间耦合。在大扭曲角下，平移对称性破缺允许通过Umklapp过程发生常规谷间耦合。研究在扭曲二硫化钼双层中，通过检测来自高能层间杂化激子的强光致发光，直接观察到了K和-K谷之间的层间耦合现象，为莫尔物理研究提供了实验证据。","scd":null,"kp":[]},{"i":37253,"as":"针对多数手性连续域束缚态（BIC）架构依赖昂贵纳米加工工艺限制可扩展性的问题，研究采用软纳米压印光刻技术制备手性纳米结构。该结构使发射体能够产生手性激光，显著增强了光与物质的相互作用，克服了大多数材料固有的弱手性光学响应限制，为光学通信和量子计算等应用提供了高可扩展性方案。","scd":null,"kp":["[近统一圆偏振激光]: 由连续域准束缚态实现"]},{"i":37254,"as":"为解决糖尿病骨修复微环境中易感染和持续炎症的问题，研究开发了一种可溶的双响应（对谷胱甘肽和明胶酶敏感）微针贴片（CGF/PP@MN）。该系统在GelMA水凝胶核心包载浓缩生长因子，表面修饰抗炎肽和抗菌肽。其空间设计实现了病理触发的级联释放：首先由细菌明胶酶激活抗菌肽清除生物膜，随后释放其他因子促进组织修复。","scd":null,"kp":["[糖尿病骨再生微环境治疗]: 利用可溶解且对谷胱甘肽和明胶酶双重响应的微针贴片(CGF/PP@MN)进行时空控制治疗"]},{"i":37255,"as":"单齿配体铜碘杂化物表面配体易解离，产生Cu+离子引发非辐射复合，限制了其在LED中的应用。研究提出配位补偿稳定化策略，通过引入吡啶封端的半导体分子，利用吡啶强吸电子部分稳定Cu4I4单元，成功制备出高效的基于单齿配体铜碘杂化物的发光二极管，其外量子效率突破20%。","scd":null,"kp":["外量子效率[单齿配体铜碘化物发光二极管]: >20%"]},{"i":37256,"as":"在分子材料中，多米诺式相变与铁电性的耦合一直未被发现。研究表明，水能够触发混合卤化铜（Gua3Cu2I5）的多米诺式相变，提供了一种非热驱动方式获取极性分子铁电体。研究发现，常规方法无法达到极性α相，水分子的引入为通过局部刺激传播结构变化提供了新途径。","scd":null,"kp":["[水触发多米诺式相变]: 存在于杂化卤化铜(Gua3Cu2I5)分子铁电材料中"]},{"i":37257,"as":"针对钙钛矿-硅叠层电池埋底界面无序和残余应变导致的非辐射损耗问题，研究开发了一种硫取代的自组装单分子层（SAM）。该硫取代的咔唑基SAM能与钙钛矿晶格直接作用，在埋底界面形成Pb-S反键杂化态，重构了界面能级结构，形成化学增强的空穴选择性接触，有效提升了叠层电池的效率和长期运行稳定性。","scd":null,"kp":["[钙钛矿-硅叠层电池埋底界面调控]: 采用硫取代的自组装单分子层(SAMs)诱导产生Pb─S反键杂化，以提升效率与长期稳定性"]},{"i":37258,"as":"基于脱嵌机制的锂层状氧化物是锂离子电池的核心正极材料，但其结构演变不稳定、扩散动力学迟缓及界面寄生反应导致电化学性能衰退。利用p区元素独特的电子结构对其进行取代掺杂，可有效改善上述问题。该文章总结了p区元素在锂层状氧化物正极材料中的调控作用、最新研究进展及未来发展方向。","scd":null,"kp":["[锂离子电池富锂层状氧化物正极]: p区元素可调节其结构演变、扩散动力学及界面副反应等性能"]},{"i":37259,"as":"为精确控制金属-载体相互作用，研究开发了一种激光冲击瞬态合成技术，成功制备出双金属（CuNi、CuFe、CuCo）和中熵（CuFeCoNi）异质结构。这些异质结构中，结晶金属纳米颗粒锚定在非晶氢氧化物载体上，具有改善催化活性的界面电子分布。以CuNi为例，在硝酸盐还原反应中展现出优异的催化性能。","scd":null,"kp":["[硝酸根还原反应催化剂]: 激光冲击瞬态合成非晶层负载的双金属铜纳米晶异质结构"]},{"i":37260,"as":"有机π共轭分子的密集π-π堆叠限制了双折射材料的光学各向异性，而金属有机框架（MOFs）通过配位键可调节配体排列。研究通过利用MOFs实现层间电子解耦，解决了3D MOFs对称性高和2D MOFs共面堆叠的维度困境，成功在π共轭MOFs中解锁了巨大双折射（Δn > 1.0），满足了先进偏振光学的需求。","scd":null,"kp":["双折射率[π共轭金属有机框架材料]: >1.0"]},{"i":37261,"as":"为满足极端航空航天环境对超轻材料的需求，研究提出一种可扩展的粉末到纤维转化策略，构建了由纤维素衍生拓扑微卷增强的多级陶瓷气凝胶。该工艺将颗粒网络转化为缠结的纤维骨架，实现了协同变形和结构稳健性，克服了传统陶瓷系统的脆性，使其具备热稳定性、机械弹性和多功能性。","scd":null,"kp":["[多功能航空航天陶瓷气凝胶]: 采用可扩展的粉末原位纤维化技术构建分层结构，克服了本征脆性以实现热稳定性、机械韧性和多功能的结合"]},{"i":37262,"as":"针对冠心病和颈动脉疾病共发诊断延迟的问题，研究开发了一种可穿戴超声系统。该系统结合双可穿戴超声贴片、同步成像策略、基于AI的图像处理算法和人体电路模型，可自动提取并分析心率、脉搏率、心输出量和颈动脉血压等关键指标。该系统实现了心脏和颈动脉动力学的同步监测，用于共病评估和早期干预。","scd":null,"kp":["[冠心病与颈动脉并发早期检测系统]: 结合双可穿戴超声贴片、同步成像策略与人工智能图像处理实现同步监测"]},{"i":37263,"as":"针对传统神经形态设备忽略生物树突非线性整合与稀疏并行处理能力的缺陷，研究构建了一种集神经元、突触和树突于一体的人工神经元树突阵列。该阵列模拟了生物树突的时空脉冲整合特性，通过多栅极阈值调节，仅整合少量神经元信号即可执行精确的并行计算，实现了高效的视觉信息推理。","scd":null,"kp":["神经形态器件[传统]: 忽略非线性整合与稀疏并行处理，需感知所有完整神经元信号","树突计算机制[人工稀疏神经元树突]: 仅通过整合部分神经元信号即可有效执行视觉任务"]},{"i":37264,"as":"在有丝分裂的肥大细胞中，纺锤体组装前出现的周期性皮层波周期与细胞大小成正比。研究表明，有丝分裂波的周期受质膜上的磷脂酰肌醇3,4-二磷酸[PI(3,4)P2]转化调节，该过程依赖于INPP4B酶。通过遗传学手段消耗INPP4B可增加皮层波周期并延长纺锤体长度，揭示了Cdc42波通过PI(3,4)P2信号和高尔基体形态控制纺锤体尺寸缩放。","scd":null,"kp":[]},{"i":37265,"as":"针对射频陷阱中单离子空间扫描仅限于线性平移的问题，研究展示了一种仅使用静态场约束的单离子传感器，实现了三维位置扫描并隔离了外部噪声。该传感器在距离金属陷阱表面50至450微米、200×200微米的区域内测量静态和时变电磁场，成功绘制了电荷分布，为理解表面不完善产生的undesired场提供了新方法。","scd":null,"kp":["空间扫描维度[射频陷阱]: 仅限于一维线性平移","空间扫描维度[静态场约束单离子传感器]: 允许三维扫描探测"]},{"i":37266,"as":"着丝粒是确保细胞分裂忠实进行的大分子复合物。家蚕是一种缺乏典型着丝粒组蛋白CENP-A的全着丝粒昆虫。研究解析了家蚕的内着丝粒CCAN结构，发现其包含四个未表征的着丝粒亚基蛋白。这些蛋白在结构上与Dam1/DASH复合物相关，但在内着丝粒支架中起功能作用，揭示了全着丝粒生物着丝粒的结构组织和组装机制。","scd":null,"kp":[]},{"i":37267,"as":"一种新型靶向递送治疗蛋白的策略，利用多种病理状态下糖酵解升高引起的细胞外酸化作为导航信号。治疗蛋白被封装在pH响应聚合物外壳中，在生理pH值下保持电中性，在酸性病理环境中逐渐获得正电荷。这种不依赖受体的电荷动态调节机制，使纳米胶囊能够感知健康与病变组织间的pH梯度，实现远距离靶向，已在多种体内模型中得到验证。","scd":null,"kp":["聚合物外壳[生理pH值]: 保持近中性电荷","聚合物外壳[酸性微环境]: 逐渐获得正电荷","递送策略[糖酵解驱动的乳酸梯度]: 利用细胞外酸化作为蛋白治疗药物靶向递送的导航信号"]},{"i":37268,"as":"研究揭示了去乙酰化酶SIRT2与乙酰转移酶MOF在细胞G2-M期转换与有丝分裂进程中的功能拮抗机制。SIRT2对MOF的脱乙酰化作用调节了关键的组蛋白标记，包括H4K16ac的去乙酰化和H4K20me1的沉积，并影响凝缩蛋白II的加载。该发现阐明了染色质动力学与有丝分裂调节因子的整合机制。","scd":null,"kp":[]},{"i":37269,"as":"研究结合信息论与机器学习，优化化学基序的采样，设计了能够有效捕捉金属合金在整个组成和结构景观中行为的机器学习势（MLP）。该方法克服了成分变化导致化学排列复杂度差异的挑战，提高了材料建模的预测精度，成功预测了不同成分合金的材料行为。","scd":null,"kp":["机器学习势函数预测精度[跨越全成分合金]: 受限于对复杂性范围从完美有序到完全无序化学排列的精确捕捉能力"]},{"i":37270,"as":"利用磁镊技术发现，冠状病毒nsp13解旋酶驱动聚合酶的分子内模板转换，进而启动回拷贝RNA合成。该过程依赖nsp13的ATP酶活性及聚合酶下游的双链RNA。意外的是，抗病毒核苷类似物瑞德西韦和莫努匹拉韦在新生链中的整合不仅未抑制该过程，反而增加了回拷贝RNA的合成。","scd":null,"kp":[]},{"i":37271,"as":"在黄河三角洲进行的7年实验表明，降雨不足破坏了盐胁迫生态系统的稳定性。降雨减少导致土壤盐分显著增加，促进了耐盐物种的优势地位，降低了物种丰富度。在环境温度和增温条件下均观察到这种物种丰富度下降和群落稳定性衰退的一致趋势。","scd":null,"kp":["实验周期[黄河三角洲盐碱地夏秋降雨缺失模拟]: 7年","生态系统稳定性[降雨缺失]: 因破坏生物多样性而受损"]},{"i":37272,"as":"研究发现他汀类药物通过激活NLRP3炎症小体引发肌肉细胞自发性肌病。他汀类药物降低了肌肉细胞中的蛋白质异戊二烯化和糖酵解水平，导致YAP效应基因减少并促进FOXO的核积累，进而引起肌肉细胞死亡和Atrogin-1水平升高。阻断NLRP3或恢复异戊二烯水平可预防此类肌肉病变，而补充胆固醇无效。","scd":null,"kp":[]},{"i":37273,"as":"在阿尔茨海默病病理中，神经元YTHDF2蛋白发挥抑制先天免疫激活的作用。正常情况下，YTHDF2识别并降解带有m6A修饰的线粒体编码mRNA（如mt-Nd4），防止RIG-I-MAVS先天免疫通路异常激活。而在Aβ病理条件下，YTHDF2表达显著下调，导致胞质mt-mRNA增加并引发免疫异常。","scd":null,"kp":[]},{"i":37274,"as":"先进气候模型测试表明，格陵兰岛冰盖融化水加剧了21世纪及之后大西洋经向翻转环流（AMOC）的减弱。然而，即使在加入高物理合理性的融化水强迫下，直到2300年的AMOC变化在百年时间尺度上既不表现为突变，也具备可逆性。融化水对AMOC突变的临界点和不可逆性影响有限。","scd":null,"kp":[]},{"i":37275,"as":"斑马鱼中的微外显子剪接调节因子srrm3在维持觉醒稳态中发挥关键作用。srrm3突变体表现出睡眠减少、感觉过敏以及行为和神经元活动增加的持续过度觉醒表型。这一过程通过cAMP-cAMP依赖性蛋白激酶(PKA)-cAMP反应元件结合蛋白(CREB)途径进行调节，揭示了剪接事件在觉醒调节中的重要作用。","scd":null,"kp":[]},{"i":37276,"as":"通过糖组学、凝集素组织化学与高分辨率电镜分析发现，奶牛乳腺腺体富含N-连接和O-连接唾液酸(SA)聚糖，对H5N1 2.3.4.4b分支病毒表现出强结合亲和力。相反，牛气管仅含O-连接SA且缺乏N-连接SA，未检测到明显的病毒结合。这解释了H5N1在牛群中引起乳腺坏死性炎症而非呼吸道感染的特殊组织嗜性。","scd":null,"kp":[]},{"i":37277,"as":"研究使用微型化瓶子系统揭示了氧气进入葡萄酒瓶的物理和化学机制。发现氧转移包含四个主要机制与不同时间尺度：储存初期建立气液相快速平衡；前几个月氧气从软木塞细胞扩散至气相；随后酚类化合物从软木塞中析出，与密封系统释放到液相中的氧气发生化学反应。","scd":null,"kp":["氧气转移机制[葡萄酒瓶储存初期]: 在储存的前几天内发生快速平衡","氧气转移机制[通过瓶塞进入酒瓶]: 揭示了4种主要机制，且各发生在不同的时间尺度上"]},{"i":37278,"as":"柯萨奇病毒B（CVB）通过下调肠道上皮细胞的人类白细胞抗原I类分子和病毒肽段呈递，在体外逃避了CD8+ T细胞的免疫识别。然而，在CVB血清阳性个体中，病毒引发了强大的CD4+记忆性T细胞免疫反应。这揭示了CVB在肠道入口处调节抗原呈递及逃避免疫监控的具体机制。","scd":null,"kp":[]},{"i":37279,"as":"受攀缘植物螺旋缠绕力学启发，设计出一种具有拉胀特性的仿生电子生物纤维。该纤维通过将刚性芳纶纤维/聚二甲基硅氧烷螺旋缠绕在柔性胶原水基聚氨酯芯材上，实现了稳定的负泊松比（-0.47）。其非线性组件耦合放大了界面摩擦，具备高灵敏度、自供电输出和优良的柔性，可用于智能生物力学感知。","scd":null,"kp":["仿生纤维[结构特征]: 具有双模量螺旋约束的拉胀电子生物纤维","传感特性[拉胀电子生物基纤维]: 在保持柔性、自供电输出和分布式感知的同时实现对微弱机械刺激的高灵敏度"]},{"i":37280,"as":"","scd":null,"kp":[]},{"i":37281,"as":"先驱转录因子Grainy head的染色质稳定占据依赖于其序列特异性DNA结合域和固有无序N端结构域。无序N端不依赖特定氨基酸序列，而是通过整体组成支持其在闭合染色质上的稳定结合，从而驱动染色质可及性。这两个结构域共同协作，克服了染色质的限制性屏障，决定了其细胞命运规范活性。","scd":null,"kp":[]},{"i":37282,"as":"通过范德华堆叠六方氮化硼（hBN）并控制扭转角，可以在室温下调制量子发射体。密度泛函理论和实验证明，内嵌发射体的发光特性强烈依赖于顶层hBN的堆叠方式与扭转角度。通过机械扭转顶层hBN，成功实现了对内嵌量子发射体原位发射能量的连续可调。","scd":null,"kp":["量子发射体[六方氮化硼范德华堆叠]: 发射特性可通过改变扭转角进行调制且能在室温下工作"]},{"i":37283,"as":"","scd":null,"kp":[]},{"i":37284,"as":"","scd":null,"kp":[]},{"i":37285,"as":"开发出名为sFlex-Fold的柔性可切换生物电子系统，实现了对大脑皮层脑沟和脑回的无损三维大面积覆盖。该系统基于AI设计的液态金属合金，利用其在25°至37°C之间的相变特性实现机械响应的可调性。液态金属合金可被制成分辨率约为10微米的任意电路布局，从而在植入时保持刚性，在体温下转为柔性贴合。","scd":null,"kp":["神经接口[AI设计的液态金属合金sFlex-Fold]: 具有可切换的柔性，能够实现对皮层脑沟和脑回的三维无创大面积覆盖"]},{"i":37286,"as":"","scd":null,"kp":[]},{"i":37287,"as":"通过不良溶剂诱导的界面自组装策略制备出一种高导电、超强韧的弹性导体。该导体具有顶部弹性聚合物层和底部液态金属聚合物互穿导电层。在仅约15%的低液态金属体积负载下，实现了3.33×10^6 S/m的极高电导率，以及超过1400%的极限拉伸率和大于30 MPa的高韧性，有效克服了传统高填料浓度降低材料力学性能的缺陷。","scd":null,"kp":["导电率[弹性导电材料]: 3.33 × 10^（原文截断，代表极高导电率）","制备策略[不良溶剂诱导界面自组装]: 形成顶部聚合物保护域和底部液态金属互穿导电域以解决填料浓度与机械性能的矛盾"]},{"i":37288,"as":"双曲声子极化激元具有亚波长约束和各向异性色散特性，但室温下的声子散射损耗严重。通过低温纳米成像，研究证实了极化激元在低温下可延长传播距离。研究团队结合低温下的结构、振动和极化激元表征及非简谐晶格动力学分析，揭示了范德华α-三氧化钼（α-MoO3）和正钒酸钇（YVO4）中双曲声子极化激元的内在损耗通道与散射率机制。","scd":null,"kp":["[室温下双曲声子极化激元]: 存在显著的声子散射损耗","[极低温纳米成像]: 证明了极化激元的扩展传播"]},{"i":37289,"as":"碳酸锂缓慢的成核与分解动力学阻碍了锂二氧化碳电池电压间隙的缩小。研究人员突破仅关注阳离子的局限，开发了量化阴阳离子轨道耦合与重构能量的双Φ描述符。该描述符在金属硫化物中确立了与电压间隙的火山型相关性，证实阴离子在调节电荷和稳定中间体中起关键作用，解决了阴离子降解引发的活性与稳定性权衡难题。","scd":null,"kp":["[Li-CO2电池双向电催化剂]: 阴离子作为活性参与者调节电荷并稳定结构"]},{"i":37290,"as":"","scd":null,"kp":[]},{"i":37291,"as":"","scd":null,"kp":[]},{"i":37292,"as":"镜像神经元在动作执行与观察期间均处于活跃状态。在猕猴执行和观察抓取动作期间，记录了其前运动皮层的433个神经元。群体分析显示，抓取信息广泛分布于神经元中并随时间动态重构。动作执行和观察由共享且部分重叠的群体几何结构连接，这种特定时间且不断演变的群体代码支持了可靠的跨条件分类。","scd":null,"kp":["记录神经元数量[猕猴前运动皮层]: 433个","[镜像神经元]: 动态重配置并广泛分布抓取特定信息"]},{"i":37293,"as":"传统第一性原理方法无法描述声子时间反演对称性（T）破缺现象。研究基于分子贝里曲率（MBC）理论，开发了一种新型第一性原理计算框架，用于捕捉晶格动力学中由电子有序驱动的对称性破缺。以Co3Sn2S2作为模型系统，该框架成功计算出了同时打破T对称性的声子谱。","scd":null,"kp":["[晶格动力学对称性破缺的第一性原理框架]: 基于分子Berry曲率(MBC)理论捕捉电子序驱动的对称性破缺"]},{"i":37294,"as":"通过一步水热法合成了硫化锌/石墨二炔纳米吸附剂，用于高效捕获气态汞。该材料通过合理设计界面的sp杂化碳-硫-锌键，促使电荷转移并在硫缺陷附近生成高活性汞吸附位点。制备的吸附剂实现了98%的零价汞去除率，并在高达1500 ppm的高浓度复杂烟气环境中表现出优异的抗干扰性能。","scd":null,"kp":["合成工艺[ZnS/石墨二炔纳米吸附剂]: 一步水热法","气相汞捕获机制[复杂烟道气]: 界面sp C─S─Zn杂化促进电荷转移"]},{"i":37295,"as":"针对中枢神经系统损伤导致的手部运动与感觉功能障碍，研究人员开发了一种结合便携式外骨骼与靶向神经刺激的神经机器人系统。该系统通过定制的电子袖套在14名中枢神经损伤患者中进行了测试。证据表明，通过激活残余外周通路，该系统不仅恢复了患者的手指活动能力，还在临床完全丧失感觉的患者中恢复了触觉感知。","scd":null,"kp":["[神经机器人系统]: 结合便携式外骨骼与神经刺激以增强感觉运动功能"]},{"i":37296,"as":"","scd":null,"kp":[]},{"i":37297,"as":"","scd":null,"kp":[]},{"i":37298,"as":"Nature团队探讨了GLP-1类肥胖药物对男性生育力（睾酮和精子）影响的初步数据，并介绍了为期两年的脑机接口试验进展。","scd":null,"kp":["[脑机接口]: 两年期试验"]},{"i":37299,"as":"","scd":null,"kp":[]},{"i":37300,"as":"聚合物电解质（PEs）是实现高能量密度与高安全性全固态电池的重要平台。针对当前文献将液态凝胶、准固态和纯聚合物固态电解质混淆为固态聚合物电解质（SPE）的问题，研究建立了一个机制框架，将其明确划分为凝胶聚合物电解质（GPE）、准固态聚合物电解质等不同类别，以厘清其各自的离子传输机制与实际性能限制。","scd":null,"kp":["[固态电池聚合物电解质]: 离子传输机制存在显著差异，不能被无差别归类"]},{"i":37301,"as":"量子点微图案在实现微米级高分辨率与大面积均匀性方面存在技术瓶颈。研究开发了一种无模板直写策略，在约10平方厘米的区域内成功制备出线宽仅为2微米的量子点微图案。该策略利用周期性纳米级厚度差形成可区分的微线阵列，通过增强毛细管流加速量子点沉积，有效提升了量子点发光二极管的电致发光性能。","scd":null,"kp":["[量子点微图案制造瓶颈]: 难以同时实现微米级高分辨率与毫米/厘米级大面积均匀性"]},{"i":37302,"as":"水系锌离子电池受锌负极界面不稳定引发副反应的限制。研究以最低未占分子轨道（LUMO）能量和溶解度为双重标准，开发了高精度有机分子注意力预测图神经网络，用于高通量筛选有机添加剂。结合密度泛函理论计算，确立了羰基电子局域化是控制界面动力学的主导描述符。基于此筛选出的α-酮戊二酸（Ket）作为最优添加剂，实现了超稳定的锌金属负极。","scd":null,"kp":["高通量筛选模型[锌金属阳极电解液添加剂]: 有机分子注意力预测图神经网络","筛选标准[有机分子添加剂]: 最低未占分子轨道(LUMO)能量与溶解度"]},{"i":37303,"as":"有效诱导内质网应激以引发细胞焦亡是提升癌症免疫治疗的关键。研究提出了一种新型的电焦亡免疫疗法（EPI），利用超声激活的无线静电刺激（wES）引发内质网与线粒器的相互作用。该机制通过靶向内质网的压电纳米平台FAL&BaTiO3@AuNPs实现，其能够产生近400毫伏的电压进行局部无线静电刺激。","scd":null,"kp":[]},{"i":37304,"as":"聚四氟乙烯（PTFE）高频基板面临严重的散热难题。研究开发了一种可溶性含氟端基聚酰亚胺（FPI）前驱体，其两亲性结构促使疏水性六方氮化硼在水性PTFE乳液中均匀分散。在热酰亚胺化过程中，填料与基体界面处原位形成微相“铆钉”拓扑结构，取代了脆弱的范德华接触，构建了坚固的机械锚定区，从而显著提升了材料的热导率与尺寸稳定性。","scd":null,"kp":["热导率[PTFE复合材料/hBN填料]: 高热导率","表面能[PTFE]: 超低表面能","复合材料界面增强[PTFE复合材料]: 可溶性氟烷基封端聚酰亚胺(FPI)前驱体作为微相铆钉增强界面"]},{"i":37305,"as":"水系锌碘电池的发展受制于多碘化物穿梭、枝晶生长及析氢反应（HER）。研究设计了由TiO2涂覆的TiN纳米线阵列电极，结合了晶面工程与异质界面构建。该设计同时暴露了热力学稳定的TiO2(101)晶面与高能(001)晶面。其中，(001)晶面与水分子表现出比(101)晶面更强的相互作用，有效抑制了上述问题，实现了高度可逆的锌碘电池。","scd":null,"kp":["电极设计[水系锌碘电池]: TiO2包覆的TiN纳米线阵列电极","抑制机制[水系锌碘电池]: 同时抑制多碘化物穿梭、枝晶生长和析氢反应(HER)"]},{"i":37306,"as":"为解决铝金属负极存在的钝化、枝晶生长及结构退化等限制长循环寿命的问题，研究受海葵触手神经网启发，设计了仿生结构的Al@CNT负极。通过将亲铝的碳纳米管融入铝基体，形成均匀的类神经渗滤网络，建立连续传输路径。这均化了电荷分布，增强了铝沉积物与基体的机械附着力，有效抑制了“死铝”形成与结构退化。","scd":null,"kp":["负极设计[铝离子电池]: 仿生Al@CNT负极(掺入亲铝碳纳米管)"]},{"i":37307,"as":"电化学直接海洋捕获（e-DOC）技术面临反应器结构复杂、欧姆损耗大及严重矿物结垢等瓶颈。研究提出了一种紧凑的、膜集成的中空纤维电极组件架构，用于连续海洋碳矿化。该架构采用大孔不锈钢中空纤维，提供了巨大的电化学活性表面积，以及优异的机械坚固性和耐腐蚀性，并实现了膜与对电极的无缝集成。","scd":null,"kp":["电极组件架构[电化学海洋二氧化碳去除]: 紧凑的膜集成中空纤维电极组件架构"]},{"i":37308,"as":"为探明锂离子电池在快充条件下内部机械异质性的时空演化，研究采用原位分布式光纤传感技术，以毫米级分辨率重建了磷酸铁锂软芯电池内部的应变演化过程。重建结果显示，随着充放电倍率的增加，电池变形行为发生显著转变。在低倍率循环下，电极叠层在嵌锂和脱锂过程中发生较大程度的同步变形，而高倍率下则表现出几何驱动的动力学去同步化现象。","scd":null,"kp":["内部机械异质性检测[LiFePO4软包电池]: 原位分布式光纤传感技术"]},{"i":37309,"as":"通过激光驱动等离子体合成策略，构建了一种珠状CeO2桥接Ni纳米颗粒催化剂（Ni-CeO2-Ni）。该催化剂通过CeO2层桥接Ni纳米颗粒形成内聚键合界面。解决了传统负载型镍基光热催化剂在高温下CO2活化能力不足和Ni纳米颗粒易烧结的问题，在光热催化CO2甲烷化反应中表现出卓越的性能。","scd":null,"kp":["光热催化剂[CO2甲烷化]: 串珠状CeO2桥接的Ni纳米颗粒"]},{"i":37310,"as":"为解决锂有机硫属元素化物电池容量衰减快和倍率性能差的问题，通过将二硫化四甲基秋兰姆与熔融二硫化硒反应，设计合成了一种有机硒化物-硫化物杂化化合物。该化合物具有链状结构、高硫族元素原子比和增强的导电性。由硒-硫键协同作用形成的一维线性分子结构，使其成为该类电池的高容量、长循环正极材料。","scd":null,"kp":["正极材料[锂-有机硫族化物电池]: 线性键合的有机硒-硫化物杂化化合物"]},{"i":37311,"as":"针对凝胶聚合物电解质在锂金属电池中低温动力学差和高温稳定性不足的限制，提出了一种新型的温度响应型凝胶聚合物电解质（TRGPE）。通过精确调节Li+与溶剂分子之间的离子-偶极相互作用，利用多功能溶剂分子双醋酸乙二醇酯（EGD）与Li+的多模式配位能力，实现了宽温区溶剂化结构的设计，使准固态锂金属电池能够在-70°C至60°C的超宽温度范围内稳定运行。","scd":null,"kp":["工作温度[准固态锂电池]: -70°C至60°C超宽温","电解质材料[准固态锂电池]: 温度响应型凝胶聚合物电解质(TRGPE)"]},{"i":37312,"as":"","scd":null,"kp":[]},{"i":37313,"as":"","scd":null,"kp":[]},{"i":37314,"as":"","scd":null,"kp":[]},{"i":37315,"as":"","scd":null,"kp":[]},{"i":37316,"as":"","scd":null,"kp":[]},{"i":37317,"as":"","scd":null,"kp":[]},{"i":37318,"as":"","scd":null,"kp":[]},{"i":37319,"as":"","scd":null,"kp":[]},{"i":37320,"as":"","scd":null,"kp":[]},{"i":37321,"as":"研究揭示了低温环境对有机光伏（OPV）电池内在能量学和电荷动力学的影响。随着温度降低，态密度变窄且准费米能级分裂增加，从而提高了开路电压。然而，驱动力的减小限制了激子解离和电荷传输。研究指出，深空环境中的OPV电池需要具有增强驱动力的下一代有源层，以及能够通过界面偶极效应促进电荷提取的阴极界面层材料。","scd":null,"kp":["性能变化[深空环境有机光伏电池]: 低温重塑本征能量和电荷动力学，态密度变窄，准费米能级分裂增加"]},{"i":37322,"as":"针对低浓度中性介质中电化学硝酸盐还原产氨（NO3−RR）受限于传质缓慢和竞争性析氢反应（HER）的问题，提出了一种通过共蒸发少量Fe杂原子在Ni催化剂中引入晶格应变的策略。原位光谱和理论计算表明，应变效应优化了Ni活性位点的d带中心，从而调节了关键中间体（*NO3−）的吸附强度并调节了界面水网络，显著促进了低浓度硝酸盐的电还原。","scd":null,"kp":["催化剂设计[低浓度硝酸盐电还原]: 引入晶格应变的NiFe合金"]},{"i":37323,"as":"解决了多孔碳材料中孔隙拓扑结构确定性控制的难题。提出了一种焓驱动的拓扑编程范式，利用高能N-N'键的键焓作为定量标度，引导配位框架自蔓延重构为连续的三重周期极小曲面（TPMS）状双连续架构。这种可编程拓扑结构建立了阻抗匹配的多重散射路径，并通过涡旋状磁纹理集中异质界面，促进了介电和磁性的耦合耗散，实现了可预测的电磁衰减和耦合热功能。","scd":null,"kp":["拓扑编程范式[多孔碳网络]: 焓驱动","结构调控机制[配位框架自传播重构]: N-N'片段键焓定量控制"]},{"i":37324,"as":"利用液晶弹性体（LCE）弧形纤维作为附肢创建了一款高质心、多腿软体机器人。通过几何编码结合扭转和弯曲模式，该机器人能够通过自然升高的质心和增强的机动性克服表面约束，模拟生物附肢的复杂运动。利用纤维变形-恢复循环的动力学和热力学原理，将编码纤维集成到3D系统中，突破了无附肢软体机器人质心低和空间机动性受限的局限。","scd":null,"kp":["驱动材料[多足软体机器人]: 液晶弹性体(LCE)弧形纤维","运动特征[软体机器人]: 高质心与多模式空间机动性"]},{"i":37325,"as":"研究揭示了免疫抵抗是临床使用的三大类主要声敏剂在声动力疗法（SDT）中共同面临的机制问题。为此合理开发了一种负载卟啉-双胍的白蛋白纳米颗粒（POR-BG@Alb）作为自免疫调节纳米声敏剂。该声敏剂诱导线粒体功能障碍，激活AMPK并抑制c-MYC，同时下调PD-L1和CD47，从而增强T细胞杀伤力和巨噬细胞吞噬作用，克服了免疫抗性。","scd":null,"kp":[]},{"i":37326,"as":"首次提出将石墨二炔氧化物（GDYO）作为新型固态电解质应用于质子电池。通过构建GDYO与磷酸的三维氢键网络，制备出GDYO@H3PO4固态电解质，有效解决了传统固态电解质在室温下电导率低的问题。基于傅里叶变换红外光谱等表征，该质子电池展现出优异的倍率性能、高安全性、高功率密度和极佳的稳定性。","scd":null,"kp":["固态电解质[质子电池]: 石墨二炔氧化物(GDYO)","导电机理[石墨二炔氧化物固态电解质]: 三维氢键网络构建"]},{"i":37327,"as":"基于光驱动分子马达和液晶（LC）聚合物的相互作用，开发了一种由温度和光调控的智能窗。该智能窗能够根据环境温度和太阳光强度，在透明、反射和散射三种不同的工作状态之间动态切换。该设计利用简单且通用的分子材料，实现了在各种全天候条件下对太阳光和热量环境适应性的动态管理，有效降低了暖通空调能耗。","scd":null,"kp":["智能窗材料[全天候日光与太阳热量管理]: 温度与光双重调控液晶"]},{"i":37328,"as":"受基于镍的金属酶协同异金属作用启发，开发了一种包含钳形二酰胺-二氨基二膦配体的Ni-Zn双金属配合物。其中弱路易斯酸性的Zn(II)中心稳定了T型Ni(0)位点。该合成模型利用双金属协同作用，实现了对H2和CO2的双活化。其与H2反应分离出了一种罕见的Ni二氢化物络合物，能在Zn(μ-H)Ni(H)和反式结构间动态转换。","scd":null,"kp":["双金属催化剂[H2与CO2双活化]: 钳型Ni-Zn异双金属络合物"]},{"i":37329,"as":"在温和且无需过渡金属催化剂的条件下，实现了五元杂环化合物插入苯并环丁烯酮（BCBs）的C─C键。该反应有效合成了基于吲哚、7-氮杂吲哚、苯并噻吩、苯并呋喃和噻吩的稠合多环化合物，这些分子骨架具有生物活性。反应具备可扩展性且产物适用于各种后期衍生化。机理研究表明，碱在促进C─C键断裂产生活性中间体中起催化作用，随后与杂环发生脱芳环化加成。","scd":null,"kp":["反应条件[杂芳环插入苯并环丁烯酮C-C键]: 无需过渡金属催化且条件温和","产物特征[多环化合物合成]: 基于吲哚、苯并呋喃等的高效骨架融合"]},{"i":37330,"as":"提出了一种通过线性成对电解在温和、可持续条件下直接断裂酚类C(sp2)─OH键的电化学策略。这种方法无需额外预活化步骤或苛刻条件，即可实现未保护酚的加氢脱氧，并首次实现了与烯烃的脱氧烷基化。该反应兼容多种官能团，为木质素等可再生芳香族原料的惰性C(sp2)─OH键官能化提供了新途径。","scd":null,"kp":["电化学策略[未保护酚类C(sp2)-OH键断裂]: 线性配对电解"]},{"i":37331,"as":"报道了一种罕见的聚合物多晶型单晶到单晶（SCSC）转化序列。专为拓扑化学叠氮-炔环加成（TAAC）设计的肽类单体发生自发的SCSC聚合，形成1,4-三唑基连接的聚合物。结构与计算分析表明，叠氮和炔基团的大幅旋转实现了区域选择性。持续加热随后触发了罕见的SCSC多晶型转变，为原子级结构解析获取结构明确的聚合物多晶型提供了新方法。","scd":null,"kp":["聚合物多晶型物制备技术[原子级结构表征]: 序列单晶到单晶转化","聚合反应[拓扑化学叠氮-炔环加成]: 形成具有1,4-三唑基连接的聚合物"]},{"i":37332,"as":"为解决水凝胶在水合条件下团簇化触发发光（CTE）易被水淬灭的难题，开发了一种通过定向冷冻辅助冷冻聚合的简便通用策略。冰晶的各向异性生长在网络形成过程中施加空间限制，驱动高分子链致密堆积并稳定酰胺基发光团簇。这种结构限制抑制了非辐射衰减，使水凝胶在超高含水量（约90 wt%）下依然具备稳定的本征发光性能。","scd":null,"kp":["聚合策略[水凝胶本征发光]: 定向冷冻辅助冷冻聚合","发光稳定性机制[含水聚合物体系]: 冰晶各向异性生长产生的空间限域效应"]},{"i":37333,"as":"合成了一种带有含中型烷基链（戊基）的N-杂环卡宾配体的柔性铂(II)配合物[Pt(CN)2(C5im-Mepy)]。该配合物在堆积时表现出源自三重金属-金属到配体电荷转移态的高效刺激响应发光。通过外部蒸汽刺激，该单一系统克服了以往挑战，成功实现了从三重态发光机制调控的全彩色发光变化。","scd":null,"kp":["发光材料[全色发光铂(II)配合物]: 含N-杂环卡宾和柔性烷基链","发光调控机制[外部蒸汽刺激]: 三线态金属-金属到配体电荷转移态"]},{"i":37334,"as":"报道了首例通过光氢原子转移（HAT）/镍双催化系统实现的区域、立体和对映选择性的苄基C(sp3)─H单氟烯基化反应。该方案利用廉价易得的碳氢化合物和容易获取的偕二氟烯烃作为起始原料，实现了高度选择性的C(sp3)─H键官能化，为获取高附加值的手性分子提供了革命性策略，填补了不对称单氟烯基化领域的空白。","scd":null,"kp":["催化策略[光HAT/镍双催化]: 区域、立体和对映选择性C(sp3)-H单氟烷基化","底物[立体选择性官能化]: 烃类C(sp3)-H键"]},{"i":37335,"as":"通过在SrFe0.9Ti0.1O3-δ（STF）表面沉积V2O5层来工程化表面电子结构，成功抑制了固体氧化物电解池（SOEC）中乙烷电化学氧化脱氢（ODH）的过度氧化问题。V2O5的引入使得本征O 2p（-1.33 eV）和V 3d（-0.18 eV）态比STF更接近费米能级，打破了转化率与选择性之间的权衡限制，在不牺牲乙烷转化率的情况下实现了65%的乙烯收率。","scd":null,"kp":["乙烯产率[乙烷电化学氧化脱氢]: 65%","表面修饰材料[抑制乙烷过度氧化]: V2O5","调控机制[固体氧化物电解池]: 表面电子结构工程"]},{"i":37336,"as":"为有机太阳能电池（OSCs）开发了一种核心-机翼型混合二聚体巨型分子受体（GMA）策略。通过柔性酯键连接烷基链，耦合了BT和BZ核心受体单元，合成了三种GMA（BTZ-2-2、BTZ-2-6和BTZ-2-10）。该设计结合了两种单体的光谱特征实现互补吸收，同时保持了良好的结晶行为。其中，BTZ-2-6因其最佳的酯键连接烷基链长度，展现出最宽的红移吸收、增强的π-π堆积和最高的电子迁移率，实现了20.25%的光电转换效率。","scd":null,"kp":["能量转换效率[有机太阳能电池]: 20.25%","受体设计策略[二聚体大分子受体]: 由不同长度酯连接烷基链偶联的核-翼型混合策略"]},{"i":37337,"as":"采用多模式结构解析方法，揭示了硅酸盐钠离子电解质Na2(1-x)Mg1-xSi1+xO4中的相关无序结构。研究克服了固态材料结构无序表征的挑战，通过探测和描述不同尺度的局部结构，揭示了隐藏在结构无序中的相干有序。结果表明，这种相关无序特征显著促进了材料内部的离子迁移，为新型固态离子电解质的设计和局部结构解析提供了新视角。","scd":null,"kp":["电解质体系[钠离子电池]: 硅酸盐钠离子电解质","离子迁移促进机制[固态结构解析]: 相关无序结构特征"]},{"i":37338,"as":"富活性金属金属间化合物作为形成容纳间隙电子的多样化阳离子笼的平台。这源于活性金属的高原子密度（促进聚集成笼）和高价电子密度（促进电子限制在笼空隙中）。研究以10种富金属RE-T-Al/Mg三元化合物为例，密度泛函理论（DFT）计算揭示了这些化合物表现出独特的间隙电子态特性。","scd":null,"kp":["材料平台[间隙电子态形成]: 富含活性金属的金属间化合物","间隙电子状态[材料发现与催化]: 多样化阳离子笼容纳的间隙电子"]},{"i":37339,"as":"通过可共结晶的小分子受体，有机太阳能电池（OSCs）实现了20.5%的光电转换效率。单晶X射线衍射分析证实，常用受体L8-BO与新设计的苯并三唑基客体Y18-C3形成了明确的双分子共晶。Y18-C3具有与L8-BO相似的共轭骨架，并引入短烷基链以增强π-π堆叠和扩展吸收。主客体间的结构相似性促进了强分子间电子耦合，实现了能量的连续调节。","scd":null,"kp":["能量转换效率[有机太阳能电池]: 20.5%","受体材料[三元共结晶策略]: L8-BO与苯并三唑基客体Y18-C3形成的双分子共晶"]},{"i":37340,"as":"金属玻璃（MGs）在远低于玻璃化转变温度下展现出形状记忆效应（SME）。训练后的金属玻璃可恢复应变随训练温度、应力和时间的增加而增加。该效应是金属玻璃的内在现象，其中粘度约为10^10 Pa·s的局部类液区（LLRs）和周围的弹性基体分别充当开关和记忆片段。LLRs的激活受变形温度和时间的影响。","scd":null,"kp":["形状记忆效应[金属玻璃]: 由类液态原子的局域流动控制","转变温度[金属玻璃]: 远低于玻璃化转变温度"]},{"i":37341,"as":"针对现有商业聚合物粘合剂依赖石油基、不可生物降解且不耐低温的问题，研究人员合理设计并合成了三嵌段热塑性聚酯弹性体（聚(1,4-二氧杂环己烷-2-酮)-b-聚(γ-甲基-ε-己内酯)）。该新型聚酯基热熔胶具有抗低温性能和生物相容性，克服了传统聚酯粘合剂仅限室温使用的局限性，适用于极寒环境。","scd":null,"kp":["弹性体材料[热熔胶]: 三嵌段热塑性聚酯弹性体","环境耐受性[胶粘剂]: 耐低温且具有生物相容性"]},{"i":37342,"as":"为了解决水溶液中光敏剂（PS）系间窜越（ISC）速率和活性氧（ROS）产量严重降低的问题，研究利用水溶剂促进电荷转移的能力，构建了Cy5-PCZ光敏剂。该光敏剂能够自适应生成电荷转移单重态（1CT）和电荷转移三重态（3CT），有效促进了快速的系间窜越，提高了ROS产量，从而用于抑制肿瘤的光动力疗法（PDT）。","scd":null,"kp":["光敏剂设计[水溶液环境]: 自适应电荷转移态","性能促进机制[光动力疗法/肿瘤抑制]: 提高系间窜越速率和活性氧产率"]},{"i":37343,"as":"为解决海水直接电解中面临的活性-耐久性权衡和氯离子腐蚀问题，研究通过将层状双氢氧化物（LDH）催化剂层间成键由弱静电引力转变为强配位，设计了抗腐蚀、高选择性的催化剂。两亲性十二烷基苯磺酸盐（SDBS）与Fe活性中心配位形成Fe-O-S键。计算表明该配位上移了Fe的d带中心，降低了氧析出热力学势垒；同时疏水烷基尾重排了界面氢键网络。","scd":null,"kp":["层间配位键[海水电解]: 两亲性十二烷基苯磺酸盐(SDBS)与Fe活性中心形成稳固的Fe-O-S键","催化剂设计[抗腐蚀与高选择性海水氧化]: 层状双氢氧化物(LDH)","层间结合转变[催化剂微环境重塑]: 由弱静电吸引转变为强配位"]},{"i":37344,"as":"可充电Li-CO2电池受限于Li2CO3路径的迟缓动力学（放电电压低于2.0V，过电位超1.0V）。研究提出通过合金-载体相互作用工程化调节CO2还原路径以解锁高性能电池。设计了一种Ru2Cu4/NC催化剂，利用合金与载体间的相互作用改变了反应机理，有效提升了电池的动力学性能、放电电压和能量效率，实现了CO2利用与储能的双重功能。","scd":null,"kp":["放电电压[Li-CO2电池常规Li2CO3路径]: 低于2.0 V","过电势[Li-CO2电池常规Li2CO3路径]: 大"]},{"i":37345,"as":"","scd":null,"kp":[]},{"i":37346,"as":"","scd":null,"kp":[]},{"i":37347,"as":"","scd":null,"kp":[]},{"i":37348,"as":"","scd":null,"kp":[]},{"i":37349,"as":"通过完全的连接体去对称化，成功构建了一种具有eft拓扑结构的Zr(IV)基MOF（SJTU-24）。该MOF在计算模型中表现为三节点(3,4,8)连接网络，共存两种类型的Zr6次级结构单元（SBU），包括一种前所未有的4连接凹面配位结构。这种采用不对称有机连接体合成MOF的策略，突破了对称网状化学限制，被成功应用于氨气捕获。","scd":null,"kp":["连接体设计[合成eft拓扑Zr(IV)-MOF]: 完全去对称化"]},{"i":37350,"as":"锂-氮（Li-N2）电池结合了本征安全的储能与可持续的N2转化。在首篇报告发表约十年后，Li-N2电池的实际发展仍受限于较差的可逆性和有限的循环稳定性。研究指出了阻碍Li-N2电池发展的关键挑战，包括反应机制的限制，并规划了这种高创新性电池技术的未来发展方向和路线图。","scd":null,"kp":["可逆性[Li-N2电池]: 差"]},{"i":37351,"as":"研究开发了一种由Fe(TIBSPDP)催化的磺酰胺对映选择性NH2-胺化反应，用于合成手性亚磺脒。该方法适用于广泛的磺酰胺底物，能够直接构建多样的含氮手性硫中心分子结构。其实用性通过高效制备药物相关化合物得到验证，如药物候选物LY181984的氮杂类似物和PP2A调节剂，满足了药物发现和催化领域对手性硫骨架的需求。","scd":null,"kp":["催化剂[磺酰胺的不对称NH2-胺化反应]: Fe(TIBSPDP)","产物特征[磺酰胺的不对称NH2-胺化反应]: 手性亚磺脒"]},{"i":37352,"as":"","scd":null,"kp":[]},{"i":37353,"as":"工业尾气中的微量二氧化硫（SO2，10-400 ppm）杂质会导致二氧化碳电还原催化剂快速失活。研究引入了一种疏水性分子门策略，通过调节界面水溶剂化结构和质子转移途径，构建了一个缺水区来锁定动力学开关。这使得SO2与氢介导还原过程隔离，而CO2转化仍能高效进行，解决了催化剂硫中毒失活的问题。","scd":null,"kp":["杂质浓度[工业烟气SO2]: 10-400 ppm","抗毒化策略[耐硫CO2电还原]: 引入疏水性分子门解耦杂质传质与催化反应"]},{"i":37354,"as":"通过将[8]环对苯撑（[8]CPP）直接整合到聚对苯撑乙烯撑（PPV）骨架中，合成了一种新型径向-线性π共轭聚合物（[8]CPPV）。光物理分析揭示了刚性CPP与线性PPV π体系之间的弯曲驱动电子耦合，使吸收变宽、发射红移并获得高荧光量子产率。此外，[8]CPPV作为锂离子电池负极表现出优异性能，兼具高初始容量和稳定循环性能。","scd":null,"kp":["材料结构[增强光电与电化学性能的聚合物]: 将[8]环对苯撑直接整合到聚(对苯乙烯撑)骨架中形成[8]CPPV"]},{"i":37355,"as":"脱氧核糖环状二核苷酸（dCDN）前药的磷酸三酯手性会影响其稳定性、细胞渗透性和生物活性。研究分离并表征了三种炔烃共轭酯酶敏感dCDN前药的非对映异构体。在THP1细胞中，(Rp,Rp)非对映异构体展现出最高的STING通路激活水平（EC50值最低）。该前药有效激发了强烈的免疫激活和持久的抗肿瘤免疫反应。","scd":null,"kp":["影响特性[dCDN前药激活STING通路]: 磷酸三酯的手性会影响其稳定性、细胞渗透性、生物活性和持续时间"]},{"i":37356,"as":"利用稀土双氮配合物对白磷（P4）进行活化以产生较小的Pn单元一直是一项合成挑战。研究表明，稀土双氮配合物能够还原裂解P4，生成一系列同系列的磷阴离子，包括[P4]2-、[P2]2-以及形式上的P2-自由基。这一发现展示了稀土金属配合物在断裂白磷及构筑多磷化合物方面的独特能力。","scd":null,"kp":["活化产物[白磷的还原活化]: [P4]2–、[P2]2–和形式上的P2–自由基","催化剂[白磷的还原活化]: 稀土双氮配合物"]},{"i":37357,"as":"针对锡铅混合钙钛矿电池中埋底界面不稳定的问题，特别是PEDOT:PSS层易导致I-氧化及I2扩散降解，研究引入了6-氨基-2-硫脲嘧啶（ATU）作为多功能添加剂。ATU嵌入PEDOT:PSS层中，其相互作用有效缓解了I-的氧化，化学性地阻断了这一基础降解路径，从而大幅提升了全钙钛矿叠层太阳能电池的耐久性和商业化潜力。","scd":null,"kp":["转换效率[全钙钛矿叠层太阳能电池]: 超过30%","界面不稳定性来源[Sn-Pb混合钙钛矿埋底界面]: PEDOT:PSS层易促进I−氧化及腐蚀性I2的扩散"]},{"i":37358,"as":"大环内二酯的合成通常需要高稀释条件以抑制低聚反应，限制了效率和规模化。研究开发了一种限制催化方法，利用六聚间苯二酚[4]芳烃胶囊的空间限制和构象预组织特性。这种超分子限制使二醇和二酰氯能在非稀释条件下且无需缓慢滴加即可发生环化，成功合成18至32元环的大环二酯，解决了大环化合物的合成瓶颈。","scd":null,"kp":["催化策略[非稀释条件下合成大环内酯与大环四内酯]: 限制催化（利用空间限域和构象限制）"]},{"i":37359,"as":"为实现白光激发和长寿命近红外余辉，研究采用自下而上法，将刚性苯基咔唑主体（BMC）与骨架匹配的延伸共轭客体（PyC或BPC）结合，制备了晶格匹配的主客体纳米晶。掺杂晶体表现出以客体为主导的深红/近红外余辉，最长波长振动带达762nm，可被475nm可见光激活，寿命长达126.1ms，磷光量子产率高达2.7%，适用于高对比度活体成像。","scd":null,"kp":["有机余辉纳米颗粒[深部组织/高对比度生物成像]: 白光激发且具有长寿命近红外磷光","主体材料[刚性苯基咔唑]: BMC","客体材料[骨架匹配/延伸共轭]: PyC或BPC","合成路线[主客体纳米晶]: 自下而上的晶格匹配方法"]},{"i":37360,"as":"为解决工业稀释CO2直接电还原生成乙烯（C2H4）过程中反应物浓度和*CO中间体不足的问题，设计了一种具有Cu纳米颗粒和Ni单原子串联催化位点的有序空心球阵列纳米反应器（Cu-NP/Ni-NC OHSpA）。机理研究表明，Ni位点生成*CO并溢流至相邻的Cu位点发生二聚反应，有效提高了低浓度CO2转化为C2H4的选择性和电流密度。","scd":null,"kp":["电化学反应器[稀释CO2直接电还原]: 有序空心球阵列结构","目标产物[CO2电还原]: 乙烯(C2H4)"]},{"i":37361,"as":"为解决太阳能蒸发技术中性能、耐用性与经济性的协同难题，利用空心多壳结构（HoMS）的特性建立了一种可扩展策略。将聚合物分子链互锁穿插到HoMS的多孔壳层中，构建出三维光热纳米架构。基于Hansen溶解度参数选择溶剂实现了精准的高分子穿线，成功制备出经济高效且结构稳固的分布式太阳能海水淡化器件。","scd":null,"kp":["光热纳米结构[分布式太阳能海水淡化]: 互锁稳定的3D结构","结构特性[光热材料]: 利用空心多壳层结构的固有特性通过聚合物分子互锁构建"]},{"i":37362,"as":"混合锂离子/金属电池（LIB/LMBs）结合了锂离子嵌入和锂金属沉积/剥离机制，有效克服了传统碳基负极能量密度受限和纯锂金属负极循环寿命短的问题。然而，其实际应用仍面临库仑效率低、固体电解质界面（SEI）不稳定、枝晶生长和巨大体积波动等挑战。这些主要导致不可逆的锂损失和界面不稳定性，严重限制了电池的长期循环寿命和能量效率。","scd":null,"kp":["电池体系[碳基无负极]: 混合锂离子/锂金属电池(LIB/LMBs)","储能机制[碳负极]: 在单一框架内集成锂离子嵌入和锂金属沉积/剥离"]},{"i":37363,"as":"本研究在名义失配约为-1.0%的NdGaO3衬底上生长了高质量的PbTiO3/SrTiO3超晶格。研究发现，在压应变条件下，衬底与薄膜之间形成了失配位错阵列。令人意外的是，这些失配位错释放的失配量远超出了-1.0%的名义失配值，揭示了压应变下铁电薄膜极性拓扑结构的演化机制。","scd":null,"kp":["薄膜极性拓扑结构[压应变衬底]: 由过度应变弛豫状态和位错主导","超晶格体系[高质量薄膜]: PbTiO3/SrTiO3超晶格"]},{"i":37364,"as":"荧光碳点（CDs）具有环保、溶液可加工性和高光致发光效率等优点，但一直因缺乏合适的醇溶性主体材料而无法实现电致发光。为此，研究人员专门设计了一种名为2PCT的双极性主体材料，用于水/醇溶性碳点基电致发光LED。该材料通过引入供体-受体单元和二乙基膦酸基团，成功实现了碳点LED的电致发光。","scd":null,"kp":["碳点合成[水/醇溶性]: 水热法","发光二极管[碳点LED]: 缺乏合适的醇溶性主体材料"]},{"i":37365,"as":"在EUROfusion托卡马克开发计划下，JET完成了2022-2023年的最终实验活动（包括第三次氘-氚实验DTE3）。实验在反应堆相关条件下解决了等离子体、排气控制和氚管理的关键挑战，成功演示了包含杂质播种的类ITER综合方案，在3 MA D-T等离子体中实现了高约束（0.85）和部分偏滤器脱离。此外，还成功实现了准连续排气（QCE）和X点辐射器（XPR）等先进排气状态。","scd":null,"kp":["托卡马克装置[聚变实验]: 具备氘氚燃料运行能力的JET","实验活动[EUROfusion]: 2022-2023年终期及第三次氘氚实验活动(DTE3)"]},{"i":37366,"as":"同时最小化能量损失和优化电荷动力学是提升有机太阳能电池（OSCs）性能的关键挑战，这与薄膜形态和能量无序度密切相关。本研究合理设计了一系列卤化噻唑单元（2,4-2DCl、2Br-4Cl和2,4-DBr）作为固体添加剂以精确调控薄膜形态。其中，2,4-DBr表现出与活性层适度的分子相互作用，有效抑制了过度聚集，促进了具有良好互穿网络结构的有序堆叠，从而制备出光电转换效率超过21%的高效电池。","scd":null,"kp":["能量转换效率[有机太阳能电池]: 超过21%","固体添加剂[卤代噻唑单元]: 2,4-2DCl, 2Br-4Cl, 和 2,4-DBr","优化机制[薄膜形态调控]: 协同促进电荷动力学并抑制能量无序性"]},{"i":37367,"as":"","scd":null,"kp":[]},{"i":37368,"as":"","scd":null,"kp":[]},{"i":37369,"as":"本研究提出在SnO2的两个界面处使用功能化自组装单分子层（SAM）形成混合电子选择性层的策略。该SAM能够同时钝化SnO2和钙钛矿两侧的缺陷，改善能级对齐，增强电子提取并抑制非辐射复合。这种双界面调制策略显著提升了钙钛矿光伏器件的光伏性能和长期稳定性。","scd":null,"kp":["电子选择层[钙钛矿光伏]: 包覆自组装单分子的SnO2混合层","双界面调控[器件性能]: 钝化缺陷、改善能级排列、促进电子提取并抑制非辐射复合"]},{"i":37370,"as":"受生物矿物中无机单晶内部包裹有机相的启发，研究人员通过分子尺度纳米工程成功将单个DNA分子（宽2纳米）穿透嵌入到羟基磷灰石（HAP）的（002）晶面中，构建出“生物-地质材料”。无机晶体沿着相邻DNA碱基生长的机制，是由DNA和HAP之间共享的相同周期间距（0.34纳米）所控制的。","scd":null,"kp":["宽度[单分子DNA]: 2 nm","周期间距[单分子DNA与羟基磷灰石晶体]: 0.34 nm","晶体渗透面[羟基磷灰石]: (002)晶面","杂化结构[生物地质材料]: 晶内渗透的DNA-矿物杂化结构"]},{"i":37371,"as":"以瑞士莱茵河谷为测试平台，本研究对综合能源-碳网络进行建模，以确定2050年实现净零能源系统的成本最优解决方案。分析表明，跨部门协调规划能够通过提高系统效率和减少对化石燃料进口的依赖来降低长期系统成本。该研究为具有弹性的区域脱碳提供了可扩展的蓝图。","scd":null,"kp":["[净零排放能源系统(2050)]: 协调跨部门规划可降低长期系统成本、提高效率并减少化石燃料依赖","[脱碳测试床]: 瑞士莱茵河谷城市-工业集群"]},{"i":37372,"as":"随着电池在现代社会中发挥越来越重要的作用，确保其可靠性和安全性变得至关重要。尽管风险无法完全消除，商业电池单元诊断技术的最新进展有助于更早地检测故障、提高性能，并增强对这种快速发展的储能技术的信任。","scd":null,"kp":["[商业电池单元诊断技术]: 有助于更早检测故障、改善性能并建立对储能技术的信任"]},{"i":37373,"as":"为解决膀胱癌腔内化疗中肿瘤靶向性不足和药物组织穿透性差的问题，研究人员开发了具有分级纳米孔结构的生物混合磁性藻类微型机器人（algebot）。该方法利用机器智能图像反馈进行自主导航，结合磁性多模态控制实现可重构集群，并采用对流扩散实现按需药物释放，协同实现了靶向载体运输、选择性药物释放和超快组织渗透。","scd":null,"kp":["[腔内化疗微纳机器人]: 具有分级纳米孔结构的生物混合磁性藻类微型机器人（Algebot）","[靶向递送策略]: 非接触式对流传输整合了靶向载体运输和选择性药物释放"]},{"i":37374,"as":"为实现亚波长和亚周期尺度下的光时空控制，本研究利用高品质因子超表面中的共振光-物质相互作用，通过光学克尔效应（一种亚飞秒光电极化效应），实现了超快、可重构的光调制。该方法克服了传统基于电子跃迁的载流子弛豫导致的皮秒级响应延迟，成功实现了介电超表面折射率的亚波长全光调控。","scd":null,"kp":["[电子带间/带内跃迁光调制响应时间]: 皮秒级","[亚波长和亚周期尺度光时空控制]: 通过共振光-物质相互作用实现超快、可重构的全光束转向和空间光调制"]},{"i":37375,"as":"受人类呼吸系统气液界面启发，研究人员开发了一种用于仿生空气净化的静电开放式微流控（EOM）系统。该系统具有静电场辅助极化和偏转以及动态更新的气液界面。由于表面能差异和量身定制的润湿性，颗粒污染物在额外电场力的作用下在气液界面被优先捕获；极化气态污染物则被自由基和电子激活，由定制功能液体去除。","scd":null,"kp":["[仿生空气净化系统]: 静电开放式微流控(EOM)系统","[EOM系统工作原理]: 具有静电场辅助极化和偏转以及动态刷新的气-液界面，利用表面能差异和定制润湿性去除颗粒物"]},{"i":37376,"as":"本研究构建了全球混凝土骨料循环的综合框架，并引入“单位人类发展指数资源使用量”作为指标。对1990年至2018年184个经济体的数据分析显示，生产端的改进（如熟料替代或配方效率提升）仅带来微小的减排；相反，需求侧因素主导了资源效率的变化。延长建筑寿命、优化库存管理等需求侧杠杆是提升骨料循环资源效率的有效途径。","scd":null,"kp":["[全球混凝土骨料循环数据集]: 覆盖1990至2018年184个经济体","[资源利用强度指标]: 定义为每单位人类发展指数(HDI)的资源使用量"]},{"i":37377,"as":"为解决合成纺织品微塑料脱落和纳米颗粒毒性问题，研究人员报告了一种全丝纳米纺织品（SilkNT）。该织物采用费马螺旋线缠绕技术将丝纳米纤维包裹在丝纱线周围。SilkNT利用分层结构和材料固有的光学特性，实现了94.8%的太阳反射率和降低至8.19%的紫外线吸收。在实际应用中，该织物能提供高效日间辐射制冷，且完全不含合成聚合物和有毒添加剂。","scd":null,"kp":["[个人热管理纺织品]: 无合成聚合物和有毒添加剂的全丝纳米纺织品(SilkNT)","[辐射冷却性能]: 具有高性能日间辐射冷却能力且避免了微塑料脱落风险"]},{"i":37378,"as":"C-糖苷在药物化学中具有重要价值，因其能够抵抗酶水解，例如用于治疗2型糖尿病的SGLT2抑制剂。然而，C-芳基糖苷的可扩展合成传统上依赖于受保护的糖衍生物、冗长的步骤或选择性较差的常规交叉偶联反应。该研究聚焦于通过糖酰肼的自由基交叉偶联反应来合成C-糖苷，为复杂碳水化合物分子的构建提供了新的路径。","scd":null,"kp":["[C-糖苷药用特性]: 氧原子被碳取代，具有抵抗酶水解的特性","[C-糖苷合成方法]: 糖酰肼的自由基交叉偶联反应"]},{"i":37379,"as":"尽管C(sp3)-C(sp3)键交叉偶联方法日益普遍，但立体控制的成键仍是挑战。受经典的立体保持型库尔特重排启发，研究团队开发了一种催化策略。该策略通过类似的立体保持脱羰基步骤，从易得的α-氨基酸底物中形成用途广泛的手性烷基镍中间体，从而实现了对映专一性的C(sp3)-C(sp3)交叉偶联，克服了手性烷基亲电试剂立体专一性氧化加成受限的难题。","scd":null,"kp":["[对映体保留脱羰C(sp3)-C(sp3)交叉偶联]: 解决了立体控制成键的挑战，满足药物发现中对高sp3特征分子的需求"]},{"i":37380,"as":"对星际彗星3I/ATLAS的同位素测量显示，其元素组成与太阳系天体截然不同。3I/ATLAS的水高度富集氘，D/H比值达到（0.98 ± 0.06）%，比已知彗星高出一个数量级以上。同时，其12C/13C比值范围（CO2为141-191，CO为123-172）超出了太阳系及附近星际云和原行星盘的典型值。这些极端的同位素特征表明，该彗星形成于低于30K的寒冷遥远环境中。","scd":null,"kp":["水的氘氢比[D/H同位素丰度]: (0.98 ± 0.06)%","[星际彗星3I/ATLAS特征]: 同位素测量揭示其水高度富集氘且元素成分异于太阳系内天体，证实其起源于寒冷遥远区域"]},{"i":37381,"as":"Swift太空天文台正处于坠毁危机中，美国宇航局（NASA）正尝试对其进行救援。报道指出，成功救援Swift天文台或将为未来拯救哈勃太空望远镜提供良好预兆。","scd":null,"kp":["[航天器救援]: 斯威夫特太空观测台及哈勃太空望远镜实施救援策略"]},{"i":37382,"as":"","scd":null,"kp":[]},{"i":37383,"as":"","scd":null,"kp":[]},{"i":37384,"as":"人类首次在35开尔文温度下成功演示了超导现象。这一突破推动了数十年的材料研究，同时也引入了关于这种奇特物质状态的长期科学谜题。","scd":null,"kp":["超导转变温度[首次发现]: 35开尔文"]},{"i":37385,"as":"两个研究团队成功研发出一种全新的、期待已久的核钟（nuclear clocks）时间计量设备。","scd":null,"kp":["[时间测量仪器]: 研发成功首台核钟"]},{"i":37386,"as":"研究发现，细胞内的亚精胺（spermine）分子能够与铁结合，从而阻止铁引发铁死亡（ferroptosis，一种依赖于铁的细胞死亡方式）。这一发现揭示了癌细胞产生保护分子的新策略，为治疗组织损伤和癌症提供了新途径。","scd":null,"kp":["[细胞铁死亡抑制]: 精胺分子与铁结合"]},{"i":37387,"as":"风电和光伏等可再生能源技术在大多数国家的普及不符合传统的S型曲线（先加速后放缓）。可再生能源在经历不稳定的形成期后，初期的加速增长在较低的市场渗透率时达到峰值，随后增速在较慢和较快的扩张脉冲间交替。先发国家的增长率可作为未来全球部署速度的基准。","scd":null,"kp":["[政策驱动型能源技术]: 风能和太阳能的扩散偏离传统S型曲线"]},{"i":37388,"as":"研究人员提出一种用于有机太阳能电池的新型烷基相变介质概念。该介质在加工过程中短暂具有流动性，提供了一个短时间的分子重排窗口，从而改善薄膜的内部结构。该策略在二元和三元系统中均提升了器件效率，并在运行稳定性上优于传统高沸点添加剂，最终实现了20.75%的光电转换效率。","scd":null,"kp":["光电转换效率[有机太阳能电池]: 20.75%","[形态调控]: 采用烷基相变介质改善薄膜内部结构"]},{"i":37389,"as":"","scd":null,"kp":[]},{"i":37390,"as":"针对燃料电池应用中的质子交换膜，研究弥补了高性能无序系统与结构明确但导电性差的系统之间的结构-功能鸿沟。研究人员开发出一种结构明确的自组装材料，成功将分子设计与理想的电导率联系起来。","scd":null,"kp":["[质子传导]: 构建自组装的超分子质子通道网络"]},{"i":37391,"as":"为应对脱碳能源技术关键材料供应风险，研究评估了从非传统水源中回收关键材料的潜力。研究识别出镁和锂等有前景的回收目标，以及油田废水和酸性矿山废水等水流。此外，研究还概述了指导未来回收研究的技术和地理考量。","scd":null,"kp":["[关键材料回收目标]: 镁和锂","[非传统水资源来源]: 采出水和酸性矿山废水"]},{"i":37392,"as":"","scd":null,"kp":[]},{"i":37393,"as":"研究为超窄带多共振发光体建立了一个预测性设计框架，通过将分子拓扑结构作为控制结构弛豫的手段来预测光谱变窄。通过高通量筛选硼氮掺杂的三角烯融合模式，发现交替融合模式能最小化重组能。该框架指导下的OLED发光体实现了低于10纳米的光谱带宽和高效超窄发射。","scd":null,"kp":["发光半峰宽[多重共振发射体]: <10 nm","[分子设计框架]: 以分子拓扑结构为显性控制变量构建预测模型"]},{"i":37394,"as":"","scd":null,"kp":[]},{"i":37395,"as":"随着海平面上升和自然灾害加剧，全球历史遗迹正面临严重威胁。迫切需要采用新的方法来理解、保护和改造这些历史遗址，以应对不断变暖的世界带来的风险。","scd":null,"kp":[]},{"i":37396,"as":"对纳米受限水的直接探测表明，纳米尺度的空间限制会诱导水分子排序，并使水能够在室温下发生液-固相变。这一发现为以水为主导的反应提供了全新的研究范式。","scd":null,"kp":["[纳米限域水]: 限域效应诱导水分子排序，并使其在室温下发生液-固相变"]},{"i":37397,"as":"","scd":null,"kp":[]},{"i":37398,"as":"","scd":null,"kp":[]},{"i":37399,"as":"","scd":null,"kp":[]},{"i":37400,"as":"","scd":null,"kp":[]},{"i":37401,"as":"","scd":null,"kp":[]},{"i":37402,"as":"","scd":null,"kp":[]},{"i":37403,"as":"在相对论平均场模型下，利用贝叶斯推断分析INDRA数据中¹³⁶,¹²⁴Xe+¹²⁴,¹²Sn中心碰撞的轻核产额。研究成功估计了热力学参数以及轻原子团簇自能在介质中的修正，取得了极佳的数据拟合效果。","scd":null,"kp":["[重离子碰撞轻簇介质效应]: 使用贝叶斯推断在相对论平均场模型中分析轻核产额以估算热力学参数和簇自能的介质内修改"]},{"i":37404,"as":"通过束流γ射线能谱学技术，在¹¹⁸I中鉴定出两对具有相反宇称的双带。实验能级和约化跃迁概率表明，它们是完全基于侵入轨道的两个不同的手性双带。","scd":null,"kp":["[118I核素手性双带]: 通过束流γ射线谱学鉴定出两对完全基于侵入轨道的相反宇称手性双带"]},{"i":37405,"as":"针对水凝胶锌金属电池（ZMBs）在极端条件下的不稳定性，研究提出了多项策略：引入官能团调节氢键网络以提升耐低温性；集成热稳定和保水结构以增强耐高温性；设计动态聚合物网络实现机械强度、自愈合和均匀锌沉积。这些精细调控有效提升了电池在极端条件下的性能。","scd":null,"kp":["[水凝胶电解质锌金属电池]: 引入功能基团调节氢键网络以提升抗低温性能，并具备热稳定和水保留特性"]},{"i":37406,"as":"两个研究团队成功研发出首种“核钟”，这是一种新型计时器，其性能超越了传统的原子钟。此外，报道还涉及舆论抵制成功保全了一个受特朗普针对的海洋监测网络，以及气候变化对人类文化遗产构成的威胁。","scd":null,"kp":["[核钟]: 首次研发出超越原子钟的新型核钟"]},{"i":37407,"as":"结合美国本土约3600个观测数据，研究通过机器学习框架得出河流一氧化二氮（N2O）排放量为每年60.7 Gg N2O-N。分析表明，水文连通性的增强强烈调节了向溪流输送的氮和N2O，并在高流量时期驱动了排放的“热点时刻”，特别是在营养丰富的低阶溪流中。","scd":null,"kp":["河流N2O排放量[美国本土]: 60.7 Gg N2O-N y−1","观测数据样本量[美国本土]: 约3600个观测点"]},{"i":37408,"as":"","scd":null,"kp":[]},{"i":37409,"as":"研究利用新生代高分辨率碳同位素记录等数据，重新评估了全球埋藏为有机碳的总碳比例（f org）。结果显示，在始新世温室时期，由于水柱含氧且磷酸盐含量低，f org 受到抑制。随着海平面下降，高效有机碳沉积埋藏区域缩小，导致水柱环境发生变化，这揭示了入侵大陆架的低氧水域控制了新生代有机碳的埋藏率。","scd":null,"kp":["[新生代有机碳埋藏]: 利用高分辨率C同位素记录、P积累和粗组分I/Ca重新评估全球有机碳埋藏比例(forg)"]},{"i":37410,"as":"","scd":null,"kp":[]},{"i":37411,"as":"","scd":null,"kp":[]},{"i":37412,"as":"","scd":null,"kp":[]},{"i":37413,"as":"","scd":null,"kp":[]},{"i":37414,"as":"","scd":null,"kp":[]},{"i":37415,"as":"","scd":null,"kp":[]},{"i":37416,"as":"","scd":null,"kp":[]},{"i":37417,"as":"","scd":null,"kp":[]},{"i":37418,"as":"","scd":null,"kp":[]},{"i":37419,"as":"","scd":null,"kp":[]},{"i":37420,"as":"该研究提出了一种无需基因工程的纳米酶邻近标记技术（NPL）。该技术利用三价铁（Fe3+）的内在过氧化物酶活性，能够在不破坏天然蛋白冠的情况下，原位研究纳米载体与细胞机器之间的动态相互作用及细胞内实时转运机制。此方法克服了传统光学显微镜和蛋白质组学技术的局限性。","scd":null,"kp":["[非基因工程纳米酶邻近标记技术]: 揭示亚细胞原位相互作用组学及纳米颗粒转运路径，克服光学成像局限并保持原生蛋白冠"]},{"i":37421,"as":"","scd":null,"kp":[]},{"i":37422,"as":"","scd":null,"kp":[]},{"i":37423,"as":"","scd":null,"kp":[]},{"i":37424,"as":"研究开发了一种金属光催化脱羧基策略，能够将天冬氨酸、谷氨酸、同谷氨酸及其高级同系物转化为多种N-芳基赖氨酸及其类似物。赖氨酸是蛋白质结构中最丰富的氨基酸之一，将其转化为非 canonical 氨基酸（ncAAs）对于扩展氨基酸和肽的功能及结构多样性具有重要价值。该反应生成的 ncAAs 具有广泛的芳香族和杂芳香族取代基，为肽设计与修饰提供了新途径。","scd":null,"kp":["[氨基酸和多肽脱羧多样化编辑]: 开发金属光催化策略，实现对酸性残基（如天冬氨酸）的平滑脱羧转化"]},{"i":37425,"as":"","scd":null,"kp":[]},{"i":37426,"as":"研究者在无铅铁电卤化物钙钛矿CsGeI3的外延薄膜中发现了巨大的位移电流响应。这种由分子束外延生长的高质量薄膜表现出明显的位移电流特征，包括光谱符号反转、光偏振依赖性，以及与可切换铁电极化相关的可逆电场调制。该材料基于体光伏效应，通过打破反转对称性与波函数量子几何的耦合，展现出优异的光电功能。","scd":null,"kp":["Glass系数[无铅铁电卤化物钙钛矿CsGeI3外延薄膜]: 创纪录最高值"]},{"i":37427,"as":"","scd":null,"kp":[]},{"i":37428,"as":"","scd":null,"kp":[]},{"i":37429,"as":"沙漠角蜥利用皮肤微通道通过毛细作用从潮湿土壤中收集水分，但水分进入口腔的机制此前未知。研究揭示，沙漠角蜥利用特有的节律性下颌运动来实现有效的水分摄入。受此独特集水技术启发，研究人员设计并制造了一种人工土壤集水系统，用于解决沙漠环境中的严重缺水难题。","scd":null,"kp":["[沙漠角蜥皮肤集水]: 利用皮肤微通道通过毛细作用从雨滴和湿润土壤中吸水"]},{"i":37430,"as":"","scd":null,"kp":[]},{"i":37431,"as":"","scd":null,"kp":[]},{"i":37432,"as":"","scd":null,"kp":[]},{"i":37433,"as":"","scd":null,"kp":[]},{"i":37434,"as":"","scd":null,"kp":[]},{"i":37435,"as":"","scd":null,"kp":[]},{"i":37436,"as":"","scd":null,"kp":[]},{"i":37437,"as":"","scd":null,"kp":[]},{"i":37438,"as":"","scd":null,"kp":[]},{"i":37439,"as":"","scd":null,"kp":[]},{"i":37440,"as":"","scd":null,"kp":[]},{"i":37441,"as":"逆电渗析法在捕获盐差能时面临离子电流低和性能衰减的挑战。研究人员提出制备高通量二维粘土纳米流体膜的策略，该膜具有高密度的垂直传输通道以实现快速离子渗透，并带有充足的表面电荷以确保离子选择性。该膜从海水和河水之间的盐度梯度中实现了高达20.8 W m⁻²的最大功率输出。无机纳米片与有机交联剂之间的强化学键赋予了膜连续稳定的纳米流体构型。","scd":null,"kp":["膜材料[渗透能提取]: 具有高密度垂直传输通道和高表面电荷的二维粘土纳米流体膜"]},{"i":37442,"as":"可打印碳电极在商业化钙钛矿太阳能电池中具有广阔前景。在P-i-N结构的碳基钙钛矿太阳能电池中，碳作为电子收集触点面临较大的界面势垒障碍。研究通过增加电子传输层（ETL）的自由载流子密度，并在ETL和碳电极之间插入非导电金属薄层，成功消除了顽固的界面势垒。这种协同策略实现了高效的反转碳基钙钛矿太阳能电池。","scd":null,"kp":["电极[倒置碳钙钛矿太阳能电池]: 可印刷碳电极"]},{"i":37443,"as":"普鲁士白（Na2Fe[Fe(CN)6]·xH2O）是钠离子电池的低成本正极材料，但传统火法或湿法冶金回收技术与其氰基物骨架不兼容。研究报道了一种针对制造废料和报废钠离子电池中普鲁士白正极的闭环直接回收工艺。该工艺采用低能耗冰剥离技术对电极进行脱层，并使用80°C的温和水系补钠液对回收粉末进行再生处理，全程无需煅烧。","scd":null,"kp":["回收工艺[普鲁士白废旧钠离子电池]: 闭环直接回收工艺"]},{"i":37444,"as":"在不对称过渡金属催化中，利用配体与底物之间的静电吸引相互作用具有加速反应和扩大适用范围的优势。研究采用手性磺化配体sSPhos进行静电导向的钯催化，在温和条件下实现了邻位烯丙基苯胺的不对称氨基芳基化反应。多种取代芳基溴化物和苯胺均能以高对映选择性生成2-苄基二氢吲哚。研究揭示了两种偶联伙伴的电子特性与对映体过量之间的关系。","scd":null,"kp":["催化剂[烯烃不对称氨基芳基化反应]: 手性磺化膦配体(sSPhos)导向的钯催化剂"]},{"i":37445,"as":"铁离子溶解会导致镍铁层状双氢氧化物发生不可逆的结构坍塌和失活。通过还原共沉淀法合成Ni/NiFe LDH复合材料，调节镍纳米颗粒含量可调控Fe的t2g轨道占据状态，从而防止Fe-O键断裂。镍向Fe的t2g轨道发生大量电子转移，使低能量反键带分离，加固了该结构。该复合材料在安培级模拟海水氧化反应中表现出极高的稳定性。","scd":null,"kp":["[镍铁层状双氢氧化物]: 通过调节Ni纳米颗粒含量控制Fe t2g轨道占据以固化Fe-O键，实现安培级稳定海水分解"]},{"i":37446,"as":"P2型钠离子电池阴极在高电压循环过程中会发生严重的电压衰减，这源于不可逆的层间阳离子迁移和结构降解。研究通过在P2-Na0.7K0.04Li0.1Ni0.22Mn0.6Ti0.08O2中引入LiTiMn5超结构单元来调节局部超结构排列。这种超结构工程有效抑制了高压循环中的阳离子迁移和结构退化，从而显著缓解了高能量密度钠离子电池阴极材料的电压衰减问题。","scd":null,"kp":["[钠离子电池P2型正极材料]: 引入LiTiMn5超结构单元以抑制高压循环中的电压衰减"]},{"i":37447,"as":"六氟化硫（SF6）是一种强效温室气体。在痕量浓度下实现高SF6选择性、大吸附容量和长期稳定性具有挑战性。研究报道了一系列锌基金属有机框架，具备系统可调的孔径和电子微环境。通过对孔隙微环境进行协同工程改造，这些MOFs材料在抗湿条件下实现了优异的SF6/N2分离选择性及痕量SF6的高效捕获。","scd":null,"kp":["吸附剂[微量SF6捕集]: 锌金属有机框架(Zn-MOF)"]},{"i":37448,"as":"传统块体液相光催化体系受限于传质效率低和活性位点受限。研究引入静坐水微滴构建三相界面催化体系，使用共价有机框架作为光催化剂，显著提升了H2O2的生成速率。H2O2的产量强烈依赖于液滴尺寸。在空气氛围和1 µL液滴尺寸下，H2O2的产量得到大幅提升。该策略为太阳能绿色转换提供了新途径。","scd":null,"kp":["[光催化合成过氧化氢]: 在共价有机框架上引入静止水微滴，通过三相界面催化促进传质和活性位点可及性"]},{"i":37449,"as":"柔性有机晶体在光子学器件中输出波长通常固定。研究人员设计合成了一种近红外柔性有机晶体，通过协同利用光子重吸收和光热驱动的荧光失活，实现了波长和强度的双模波导输出调制。由于晶体吸收和发射光谱之间的显著重叠，其波导输出波长能够实现连续且可逆的调节，突破了单一晶体光学信号固定输出的限制。","scd":null,"kp":["[近红外柔性有机晶体]: 利用光子重吸收和光热效应实现双模波导输出的连续可逆调制"]},{"i":37450,"as":"开发同时具备短紫外截止边和大双折射率的材料极具挑战。研究人员通过温和水溶液法将过氧化氢引入4-羟基吡啶晶格中，制备出含有过氧化物的溶剂化晶体4HPO2。该晶体展现出日盲紫外透明特性，并通过过氧化物辅助溶剂工程实现了创纪录的高双折射率，解决了双折射材料在短波紫外截止和高光学各向异性之间难以兼顾的难题。","scd":null,"kp":["双折射率[过氧化物辅助溶剂化工程太阳能盲区透明晶体]: 创纪录高值","晶体材料[溶质工程]: 4HP·H2O2 (4HPO2)"]},{"i":37451,"as":"大多数金属氧化物在富氢环境中容易被还原降解。研究提出了一种“氧锚定”策略，通过构建富含氧的C-O骨架稳定的CuO/TiO2催化剂，用于腈类化合物选择性加氢耦合制备仲胺。C-O框架中的氧官能团作为锚定位点，有效稳定了CuO纳米颗粒，防止其在加氢反应条件下发生还原失活，使金属氧化物催化剂表现出优异的抗氢稳定性。","scd":null,"kp":["催化剂[耐氢气还原环境]: CuO/TiO2","[氧锚定策略]: 提升可还原金属氧化物在富氢环境下的结构稳定性"]},{"i":37452,"as":"利用C(sp3)-H键构建C(sp3)-C(sp2)键面临巨大挑战，以往基于PdII/PdIV催化体系的反应往往需要活化的烯基卤化物和强外部导向基团。研究报道了一种配体促进的立体选择性偶联反应，通过PdII/Pd0/PdII催化循环实现了亚甲基C(sp3)-H键与烯基溴化物的偶联。该方法无需外部强导向基团，为立体选择性碳碳键的构建提供了新途径。","scd":null,"kp":["[PdII/Pd0/PdII催化]: 配体参与的亚甲基C(sp3)-H键与烯基溴化物的立体选择性偶联"]},{"i":37453,"as":"液晶弹性体能够将微观分子重新取向可逆地转化为宏观形变和光学响应，是制造自适应智能系统的重要材料。这篇综述全面回顾了基于LCE的自适应系统的研究进展，包括其刺激响应机制、网络架构工程、先进制造技术及前沿应用。重点介绍了通过调节化学组成、动态共价 adaptable 网络及创新加工方法，将其驱动阈值降低至接近环境或人体温度的策略。","scd":null,"kp":["自适应材料[液晶弹性体]: 可逆将微观分子重新取向转化为宏观形变和光学响应"]},{"i":37454,"as":"研究提出一种N桥连双铁位点（≡Fe─N─Fe≡）催化剂，通过活化过硫酸盐（PMS）高效生成高活性的酚氧离子（PhO+）。原位光谱和理论计算表明，PMS通过两个过氧氧原子吸附在双铁位点上，形成特有的≡Fe-(μO-O)-Fe≡中间体。该催化剂有效克服了连续双电子转移的动力学和热力学挑战，实现了对酚类污染物的高效聚合与去除，在水质净化领域表现出显著效果。","scd":null,"kp":["催化剂[苯酚氧化聚合用于水净化]: N桥联双铁位点(≡Fe─N─Fe≡)","[苯酚双电子氧化]: 生成高活性苯氧鎓离子(PhO+)实现高效聚合与去除"]},{"i":37455,"as":"针对对称水系电池（SABs）中水分解反应限制电压窗口的问题，研究提出一种拓扑化学设计策略。通过在双极电极中引入电子缓冲（EB）机制来控制工作时的电子流，有效减弱了电压两端用于水分解的电子流向。实验证实该设计大幅降低了水分解的电流密度，理论计算也表明含EB的电极表面电子密度显著低于无EB电极，从而成功抑制了水分解副反应。","scd":null,"kp":["[对称水系电池双极电极]: 拓扑化学引入电子缓冲(EB)抑制水分解并拓宽电压窗口"]},{"i":37456,"as":"研究开发了一种名为BTDyA的有机材料，专为高温太阳能-热能转换设计。该材料通过乙炔基连接三苯胺供体和[1,2,5]噻二唑并[3,4-f]苯并三唑受体构建。BTDyA具备高摩尔吸光系数和宽带固态吸收特性，在聚光室外 sunlight 下温度可达330°C，创下有机光热材料最高纪录；在1064纳米激光照射下温度更升至377°C。该成果突破了有机材料在光热转换中的温度限制。","scd":null,"kp":["光热转换材料[高温太阳能-热能转换]: 有机材料BTDyA","[分子工程调控]: 通过乙炔基连接三苯胺供体和[1,2,5]噻二唑并[3,4-f]苯并三唑受体以调控振动耦合"]},{"i":37457,"as":"为解决增强酶活性的代谢工程挑战，研究构建了一套结合小样本学习和因果推断的计算预测与实验迭代工作流。研究确立了体内单位产量（产量/表达量）可作为水相环境下优化酶活性的有效替代指标。该工作流通过分析已发表的数据集，在计算指导下进行高效的实验验证，成功实现了目标产物产量的显著提升，为酶序列设计提供了新范式。","scd":null,"kp":["[酶活性增强]: 融合小样本学习和因果推断的计算与实验迭代工作流","[代谢工程目标参数]: 体内单位产量(产量/表达量)可作为有吸引力的优化指标"]},{"i":37458,"as":"研究开发了一种局部p-π共轭调节策略，用于定制共价有机框架（COFs）内的内建电场（BIEF），以提升光催化活性。通过温和条件下的Schiff碱反应，合成了NKU-191、NKU-191-OH和NKU-191-OMe三种高稳定性、高比表面积且耐酸碱的COFs。在不改变内在骨架结构的前提下，该策略有效增强了光生电荷的分离与转移，使光催化析氢活性从4.8 mmol g⁻¹ h⁻¹得到显著提升。","scd":null,"kp":["[共价有机框架提升光催化]: 局部p-π共轭调控策略增强内建电场(BIEF)"]},{"i":37459,"as":"针对光合系统II（PSII）中光驱动氧气形成的实验与计算模型差异，研究提出了新的水氧化机制。该机制明确了由组氨酸通过动态氢键配位的OEC独特氧O3为慢交换底物，并指出其与在S2态下Mn1位点上生成的O6氧发生耦合。这一新发现解决了O-O键形成过程及蛋白质环境作用方面的重大实验争议，深化了对维持生物圈运转的PSII锰簇结构的理解。","scd":null,"kp":["[光系统II中的水氧化机制]: 解决O-O键形成过程中的实验与计算模型争议","[释氧复合物结构]: Mn4CaO5簇"]},{"i":37460,"as":"针对电催化硝酸盐还原合成氨（ENRA）中中间体氢化缓慢和析氢副反应（HER）严重的问题，研究开发了拓扑工程设计的多金属氧酸盐（POM）限制双金属金属有机框架（MOF）电催化剂。柔性NH2-MIL-88(FeNi)紧密封装了[PW12O40]³⁻结构，通过松动水合层和调整电子重新分布，有效促进了硝酸盐电还原效率，并可应用于锌-硝酸盐电池的阴极反应。","scd":null,"kp":["[硝酸根电还原合成氨及锌-硝酸根电池]: 受限于迟缓的中间体加氢和严重的析氢副反应(HER)","催化剂[电催化硝酸根还原合成氨]: 拓扑工程同构多金属氧酸盐(POM)限制的双金属MOF"]},{"i":37461,"as":"为解决传统强腐蚀性超酸催化制备阴离子交换膜（AEM）带来的安全和量产挑战，研究提出了一种非超酸聚合策略。该策略使用甲磺酸（MSA，pKa=-1.9）作为催化剂，催化亲电氨基苯甲醛与富含电子的二苯并-18-冠醚-6发生Friedel-Crafts烷基化反应。冠醚结构的引入扩大了分子链间距，促进了连续水合通道的形成，从而制备出适用于高性能水电解槽的AEM膜。","scd":null,"kp":["[阴离子交换膜制备]: 采用非超强酸催化聚合路线，克服了传统三氟甲磺酸(TFSA)强腐蚀性带来的安全与规模化挑战"]},{"i":37462,"as":"本文通过联合实验与数值模拟，研究了具有钨（W）第一壁的托卡马克装置中长限制等离子体爬升阶段的物理过程，这对ITER的运行至关重要。使用SolEdge-HDG代码对平均等离子体量进行的模拟与硼化后三次连续WEST放电测量结果的比较表明，准确预测此阶段极具挑战性。模拟虽能重现赤道面的一般趋势和密度分布，但低估了核心温度，且高估了高场侧限制器的测量值，凸显了现有Bohm边界条件的局限性。","scd":null,"kp":["第一壁材料[W环境托卡马克装置]: 钨(W)"]},{"i":37463,"as":"研究针对具备高磁场、大电流和高拉长比能力的COMPASS Upgrade托卡马克装置，建立了用于完整等离子体启动（击穿和烧穿）及初始电流爬升阶段的开环极向场线圈电流方案。通过FIESTA代码推导并线性化了包含被动稳定板的完整电磁模型。优化算法计算出产生合适真空场所需的电流，并维持等离子体在其初始位置以抵抗杂散磁场，为低场和高场条件下的运行提供了理论指导。","scd":null,"kp":["磁场强度[低场条件]: 低场条件","磁场强度[高场条件]: 高场条件","等离子体 triangularity[COMPASS Upgrade]: 高三角性"]},{"i":37464,"as":"JT-60SA是全球正在运行的最大超导托卡马克装置，旨在解决高β值下的长脉冲稳态等离子体运行等技术挑战。该装置于2023年10月23日成功实现首次等离子体放电，并在运行初期（OP-1）实现了超过1兆安培的偏滤器等离子体。与ITER类似，JT-60SA在低平行电场条件下，通过捕获粒子机制快速实现了等离子体启动，为包括ITER在内的下一代大型超导托卡马克铺平了道路。","scd":null,"kp":["装置规模[超导托卡马克]: 目前世界上正在运行的最大的超导托卡马克","等离子体电流[偏滤器等离子体]: >1 MA","首次等离子体产生时间[JT-60SA]: 2023年10月23日"]},{"i":37465,"as":"多金属催化已成为现代有机合成中获取单金属催化剂无法实现的反应路径和选择性的强大策略。本文综述了金基多金属催化领域的最新进展，重点强调了其反应机理。金独特的π活化和氧化还原特性使其能够构建复杂的碳-碳键和碳-杂原子键。该综述全面展望了金基多金属催化在实现新型有机转化方面的潜力。","scd":null,"kp":["[金基多金属催化]: 利用金独特的π活化和氧化还原性质构建碳-碳和碳-杂原子键"]},{"i":37466,"as":"自然生物固碳将大气中的二氧化碳转化为高能碳水化合物，为替代化石燃料和恢复碳平衡提供了途径。本文系统分析了合成二氧化碳生物转化系统（SCBS）如何将多碳生物合成与光能、电能和化学能等不同能量转换方法整合，超越自然碳同化效率，实现从CO2到化学品的碳中性或碳负性生物制造。文章重点探讨了如何实现二氧化碳固定模块与能量系统的高效匹配。","scd":null,"kp":["[人工合成CO2生物转化系统]: 设计和重编程以超越自然碳同化效率，用于碳中和生物生产"]},{"i":37467,"as":"本教程提供了一条从分子到超分子系统研究圆偏振发光（CPL）的便捷途径，重点关注有机材料。文章介绍了手性光学响应的基本概念，总结了可靠测量CPL的细节要点，并简要概述了CPL的理论模型。此外，该教程还深入探讨了更具挑战性的圆偏振电致发光领域的相关内容。","scd":null,"kp":["[圆偏振发光材料]: 主要聚焦于有机材料和超分子系统"]},{"i":37468,"as":"","scd":null,"kp":[]},{"i":37469,"as":"","scd":null,"kp":[]},{"i":37470,"as":"文章探讨了美国电力需求与零售电价之间的关系。作者分析了为何历史上的电力需求增长通常伴随着电价下降，并对未来需求增长可能导致电价上升的论点进行了深入探讨。该评论阐明了需求增长对电力市场价格结构的具体影响机制。","scd":null,"kp":["[电力需求与电价关系]: 历史上需求增长通常与电价下降相关，但未来需求增长可能会导致电价上升"]},{"i":37471,"as":"","scd":null,"kp":[]},{"i":37472,"as":"","scd":null,"kp":[]},{"i":37473,"as":"研究发现，电池循环过程中残留的固体电解质界面层（rSEI）并非惰性副产物。这些残余层会逐渐具备导电性，将锂的沉积位置从集流体转移到rSEI表面。这种空间转移导致锂极易发生电断路，从而加速了电池的失效过程。该研究揭示了rSEI在驱动电池性能退化中的主动机制。","scd":null,"kp":["[锂金属电池老化失效机制]: 电池循环中遗留的残余固体电解质界面(rSEI)逐渐具备电子导电性，使锂沉积偏离集流体并易发生电断开，加速电池失效"]},{"i":37474,"as":"将硅添加到石墨负极中能提升电池能量密度，但硅的快速老化往往迫使系统采用保守的运行限制，导致容量未充分利用。研究证明，常规充电数据可用于识别硅主导的荷电状态窗口，并追踪其随电池老化的变化。基于此诊断，电池管理系统能够在硅活跃时应用基于老化信息的热控制策略，在不牺牲可用容量的前提下有效保护高能材料。","scd":null,"kp":["[硅负极老化监测]: 利用常规充电数据识别硅-dominant荷电状态区间并追踪其随老化的偏移","[电池热管理控制]: 基于老化信息的硅活跃期热控制，在不牺牲可用容量的前提下保护高能材料"]},{"i":37475,"as":"研究在层状铁电存储器中识别出一种不完全屏蔽的静电区域。通过结合Bi2O2Se、氮化硼和石墨烯，研究成功分离了极化控制、隧穿和屏蔽三个过程。这种范德华异质结构实现了超低漏电流和巨大的隧道电阻，同时揭示了依赖于石墨烯厚度的静电屏蔽规律，为高性能铁电存储器的设计提供了新思路。","scd":null,"kp":["[范德华异质结构]: 结合Bi2O2Se、氮化硼和石墨烯分离极化控制、隧穿和屏蔽","[铁电隧穿性能]: 实现超低漏电流和超大隧穿电阻","[屏蔽规则]: 依赖于石墨烯厚度的屏蔽规则"]},{"i":37476,"as":"针对2D和3D钙钛矿之间存在结构无序和界面缺陷的问题，研究提出了一种相干范德华跨维度外延策略，将3D MASnI3单晶直接生长在2D (3T)2SnI4模板上。该方法实现了对晶体畴取向、密度和覆盖率的确定性控制，获得了具有原子级锐利且结构相干的平面异质结构。低剂量像差校正透射电子显微镜证实了有序的间隔配体和均匀的界面钝化，显著减少了界面缺陷。","scd":null,"kp":["[2D-3D钙钛矿外延异质结构建]: 在2D (3T)2SnI4模板上直接生长3D MASnI3单晶","[界面与取向控制]: 实现对畴的取向、密度和覆盖率的确定性控制"]},{"i":37477,"as":"","scd":null,"kp":[]},{"i":37478,"as":"新技术通过向各个方向拉伸蛋白质样本，使分子间距扩大十亿倍。这一物理扩张方法使原本距离极近的氨基酸分子得以分离，从而允许研究人员仅使用普通的光学显微镜即可对蛋白质分子进行可视化观察与精确定位。","scd":null,"kp":["[蛋白质样本物理膨胀技术]: 向各方向拉伸蛋白质样本使分子相互分离，从而仅需光学显微镜即可实现可视化"]},{"i":37479,"as":"","scd":null,"kp":[]},{"i":37480,"as":"","scd":null,"kp":[]},{"i":37481,"as":"硅谷主导的全球人工智能战略存在局限性。随着人工智能技术在全球范围内的扩展，新兴经济体在电网能源供应和本土语言处理性能等方面暴露出该战略的缺陷。文章强调，每个国家需要根据自身情况制定独立的人工智能发展蓝图。","scd":null,"kp":[]},{"i":37482,"as":"回顾了20世纪70年代一项改变商业生物技术发展进程的重组DNA技术专利。科学界当时正对该专利及基于马勃菌麻醉剂的实验研究保持高度关注。这项历史性档案记录了早期生物技术领域的关键科学事件与突破。","scd":null,"kp":["[重组DNA技术]: 早期专利奠定了商业生物技术的基础"]},{"i":37483,"as":"","scd":null,"kp":[]},{"i":37484,"as":"","scd":null,"kp":[]},{"i":37485,"as":"该综述总结了可见光驱动下利用一氧化碳进行羰基化反应的最新研究进展。内容根据激活底物的不同方法进行分类。综述旨在启发新型可见光诱导羰基化反应的设计，从而推动一氧化碳在可持续有机合成中的高效利用与实际应用。","scd":null,"kp":["[可见光驱动羰基化反应]: 利用一氧化碳进行多样化羰基化反应，促进可持续有机合成中的CO利用"]},{"i":37486,"as":"以公平且可持续的方式满足全球人口对水、能源和食物日益增长的需求是一项紧迫挑战。这项研究通过量化跨国贸易中的物质流和虚拟流，绘制了这些相互依赖的核心资源系统在国际贸易中被利用的具体方式，揭示了全球贸易体系对物质平等的负面影响。","scd":null,"kp":[]},{"i":37487,"as":"全钒液流电池在早期极具潜力，但由于在扩大规模时出现的瓶颈，迟迟未能超越试点项目阶段。李先锋及其团队探讨了如何克服这些障碍，从而实现数百兆瓦规模、可靠且具有成本效益的长期储能技术的规模化应用。","scd":null,"kp":["[全钒液流电池规模化扩展]: 克服扩大规模时出现的瓶颈，实现数百兆瓦级别的长时储能"]},{"i":37488,"as":"光合作用依赖叶绿素和类胡萝卜素捕获光能并转移至反应中心。该研究在紫色光合细菌中发现了一种由单重态裂解介导的类胡萝卜素至细菌叶绿素的能量转移机制。高能单重态激子被分裂为相邻位点上的三重态激子，随后协同转移至细菌叶绿素，这是太阳能收集的基础。","scd":null,"kp":["[紫细菌光捕获能量传递机制]: 类胡萝卜素至细菌叶绿素的能量转移由单线态裂变介导"]},{"i":37489,"as":"巨噬细胞激活后会产生大量活性氮物质，导致结核分枝杆菌（Mtb）DNA发生烷基化损伤并抑制其复制。研究利用转座子插入测序鉴定了Mtb存活所需基因，发现tagA在Mtb于M1型巨噬细胞及小鼠体内的存活中发挥着关键的DNA损伤修复保护作用。","scd":null,"kp":["[巨噬细胞内结核分枝杆菌DNA损伤]: 由活性氮物质诱导烷基化损伤进而限制细菌复制"]},{"i":37490,"as":"双壳类传染性肿瘤（BTN）是一种可传播的癌症。名为MarBTN的单克隆亚型此前仅在北美东海岸以1%至5%的低水平流行。2022年，研究人员在华盛顿州普吉特海湾意外发现了MarBTN，且后续感染率迅速上升，2024年两个地点的患病率均超过75%。这标志着该地区正处于严重疾病爆发的早期阶段。","scd":null,"kp":["流行率[软壳蛤传染性肿瘤(MarBTN)]: 1至5%"]},{"i":37491,"as":"气候变化和人类活动加剧了氧化还原波动，威胁最肥沃黑土湿地的碳库稳定性。研究结合田间调查和机制实验表明，水稻种植从根本上重塑了控制氧化还原波动下碳脉冲温度敏感性的生物与非生物耦合过程。水稻种植增强了铁还原能力并改变了微生物群落的特征。","scd":null,"kp":["研究规模[黑土湿地野外调查]: 10种黑土"]},{"i":37492,"as":"分布式声学传感（DAS）是被动监测鲸鱼的强大工具，但传统方法高度依赖鲸鱼的发声。该研究开发了一种新方法，通过分析海底光缆中的低频DAS数据，检测鲸鱼游动引发流体运动的流体动力学压力和速度场。利用船只作为代理进行校准，该方法能够成功检测到未发声的沉默鲸鱼。","scd":null,"kp":["[分布式声学传感(DAS)新技术]: 探测静默鲸鱼的水动力学压力和速度"]},{"i":37493,"as":"","scd":null,"kp":[]},{"i":37494,"as":"","scd":null,"kp":[]},{"i":37495,"as":"","scd":null,"kp":[]},{"i":37496,"as":"","scd":null,"kp":[]},{"i":37497,"as":"","scd":null,"kp":[]},{"i":37498,"as":"","scd":null,"kp":[]},{"i":37499,"as":"","scd":null,"kp":[]},{"i":37500,"as":"","scd":null,"kp":[]},{"i":37501,"as":"","scd":null,"kp":[]},{"i":37502,"as":"","scd":null,"kp":[]},{"i":37503,"as":"","scd":null,"kp":[]},{"i":37504,"as":"","scd":null,"kp":[]},{"i":37505,"as":"","scd":null,"kp":[]},{"i":37506,"as":"针对无领导社会动物的觅食分工难题，研究提出了一种去中心化觅食模型。模型中的个体共享信息与回报，但需自行选择承担探索成本或保持静止。结果显示，去中心化集体能够匹敌中央控制组的效率：少数探索者承担低产时期的探索成本并持续收集信息，使多数个体能够同步利用有利条件，形成高效的劳动分工策略。","scd":null,"kp":["[去中心化觅集体]: 个体在承担探索成本或保持闲置之间进行分布式决策"]},{"i":37507,"as":"研究开发了一种无需表面活性剂的方法，通过在不互溶的水油界面捕获气泡，成功生成悬浮的浮油纳米膜。该薄膜厚度约100纳米，比表面积达到10^7 m^-1，具有紧密相邻的气/液和液/液界面，无固体基底。利用电化学结合有限元建模，研究定量表征了纳米膜的厚度，并揭示了纳米尺度限域几何结构引发自发氧化的化学机制。","scd":null,"kp":["膜厚度[悬浮油纳米膜]: 约100 nm","比表面积[悬浮油纳米膜]: 10^7"]},{"i":37508,"as":"单分散分子石墨烯纳米带的合成依赖于原子级精度的结构控制。由于现有的非迭代策略在边缘拓扑和长度上存在限制，未掺杂分子石墨烯纳米带的迭代合成方法进展缓慢。研究提出了一种新型迭代合成策略，成功合成了一系列未掺杂的分子石墨烯纳米带。该技术实现了特定边缘拓扑结构的精确构建，有助于确立材料的构效关系。","scd":null,"kp":["[分子石墨烯纳米带合成]: 需具备全原子精度的合成方法以确立结构与性质关系"]},{"i":37509,"as":"混合金属氧化物可有效通过氧化还原界面工程提升催化性能。研究制备了一种锚定在Co3O4尖晶石上的短程有序RhOx和CeOx物种的复合催化剂，用于氧化亚氮(N2O)分解。该催化剂对Co3O4的活性提升表现出非加性效应。RhOx与CeOx的协同作用优化了界面结构，为高效催化N2O分解提供了新的材料设计方案。","scd":null,"kp":["催化剂[N2O分解]: 锚定在Co3O4上的短程有序RhOx和CeOx协同氧化还原催化剂"]},{"i":37510,"as":"镁离子电池具有高理论体积容量(3833 mAh L^-1)，但循环过程中迟缓的脱溶剂化动力学延长了激活周期并损害倍率性能。为解决该瓶颈，研究在传统全苯基复合物(APC)电解液中引入4-乙基-4-甲基吗啉阳离子(EMM+)作为添加剂。密度泛函理论计算证实EMM+具有很强的溶剂化调节能力，实现了免激活的高性能镁离子电池。","scd":null,"kp":["体积理论比容量[镁金属]: 3833 mAh L^-1","电解液添加剂[镁离子电池]: 离子液体（实现免活化并克服迟缓的去溶剂化动力学）"]},{"i":37511,"as":"氟化策略常用于提升锂金属电池溶剂的电化学性能与循环稳定性。针对β-氟化1-乙氧基-2-甲氧基乙烷(FxEME)的优异抗氧化稳定性，研究采用密度泛函理论(DFT)、从头算分子动力学(AIMD)及机器学习力场(MLFF)-MD等多尺度建模手段，系统揭示了不对称醚氟化在原子尺度上提升抗氧化稳定性的微观机制。","scd":null,"kp":["溶剂[锂电池]: β-氟化1-乙氧基-2-甲氧基乙烷 (FxEME)","[F_xEME溶剂]: 表现出优异的氧化稳定性"]},{"i":37512,"as":"针对经典铂类抗癌药物缺乏肿瘤选择性且全身毒副作用大的问题，研究开发了一种基于铂(IV)的金属装订策略构建肿瘤特异性金属前药。该策略利用Pt(IV)络合物的双重作用，既作为化疗药物，又作为结构“装订钉”使表皮生长因子受体(EGFR)靶向配体发生构象刚性化。该大环金属前药实现了对EGFR高表达肿瘤的精准双重靶向治疗。","scd":null,"kp":["药物设计策略[克服经典金属药物局限性]: 铂(IV)金属钉合策略构建肿瘤特异性前药","治疗应用[靶向化学-免疫代谢癌症治疗]: 肿瘤特异性靶向与降低系统性毒性"]},{"i":37513,"as":"针对膜法直接空气捕获(m-DAC)在低二氧化碳浓度和高湿度下效率受限的问题，研究提出了“以水为帆”策略，将高湿度环境从阻力转化为传质动力。通过将氟化离子液体@UiO66作为多孔填料与新型聚合物PIM-1DFBP结合，构建出双氟化混合基质膜。丰富的氟位点通过路易斯酸碱相互作用高效捕获稀释气流中的CO2，实现了超渗透分离。","scd":null,"kp":["分离膜设计[高湿环境下直接空气捕集CO2]: 双氟化基元定制杂化膜","驱动机制[膜基直接空气捕集]: “顺风顺水”策略将湿度转化为传质驱动力"]},{"i":37514,"as":"研究成功合成了一种双金属节点占据的金属有机框架(CZPDC)，用作模拟糖苷水解酶的人工酶。X射线吸收近边结构证实金属簇节点中Ce和Zr共存。密度泛函理论(DFT)计算揭示了CZPDC对糖苷分子的特异性吸附行为。该材料凭借高度有序的结构与精准可控的活性位点，能够高效水解细菌生物膜中的糖苷分子，克服了天然酶的局限性。","scd":null,"kp":["人工酶催化剂[糖苷水解酶活性模拟]: 双金属节点占据的金属有机框架","催化应用[细菌生物膜清除]: 高效水解细菌生物膜"]},{"i":37515,"as":"手性季碳中心与邻位季/叔碳中心的构建是有机合成的长期挑战。研究报道了一种统一的瞬态硼基辅助催化对映选择性策略，成功实现了非环状季碳和邻位季/叔碳立体中心的构建。该策略核心在于利用高对映选择性的铜催化α,β-不饱和酯共轭硼化反应，形成硼基组织的立体定义非环状四取代烯醇酯，并实现其后续的立体选择性烷基化反应。","scd":null,"kp":["催化合成策略[无环四取代烯醇盐]: 瞬态硼辅助对映选择性催化","合成难点[有机合成不对称构建]: 无环季碳和相邻季/叔碳立体中心"]},{"i":37516,"as":"","scd":null,"kp":[]},{"i":37517,"as":"提升手性π体系的发射效率对材料科学应用具有重要意义。研究合成了一系列以环辛四苯撑(COTt)或环辛六苯撑为核心的高发射双π螺旋分子碳。通过二苯胺/咔唑融合引入氮原子，克服了传统衍生物不发光的特性，使荧光量子产率高达98%。从COTt到COTh的结构演变还使吸收和发射波长发生约3倍的红移，并成功实现了对映异构体的手性拆分。","scd":null,"kp":["分子碳材料[高发射率双π螺旋分子碳]: 氮集成（二芳基胺/咔唑融合）"]},{"i":37518,"as":"研究完成了大肠杆菌O29、志贺氏痢疾杆菌11型（S. dysenteriae serotype 11）和普通变形杆菌O12三种致病菌O-抗原十糖的首次全合成与免疫学评估。这些细菌是引发重症感染与死亡的主要病原体。通过化学合成获得结构精确的寡糖，为开发经济高效的抗细菌感染糖类合成疫苗提供了物质基础和关键的免疫学数据。","scd":null,"kp":["合成与评估目标[细菌O-抗原寡糖]: 大肠杆菌O29、痢疾志贺氏菌11型及普通变形杆菌O12"]},{"i":37519,"as":"","scd":null,"kp":[]},{"i":37520,"as":"","scd":null,"kp":[]},{"i":37521,"as":"","scd":null,"kp":[]},{"i":37522,"as":"","scd":null,"kp":[]},{"i":37523,"as":"","scd":null,"kp":[]},{"i":37524,"as":"研究评估了小鼠大脑单细胞RNA测序和单核测序图谱中细胞聚类的可复制性。这两个图谱均包含超过400万个细胞，并将其划分为5000多个聚类。利用转录组范围内的邻居投票法，识别出2009对具有一致空间定位和基因表达协调的相互匹配聚类对。这些相互匹配的聚类在小脑中高度富集，其较低的多样性有助于提高可复制性。","scd":null,"kp":["图谱规模[小鼠大脑单细胞/单核细胞图谱]: 超过400万个细胞和5000多个簇","算法应用[跨研究细胞簇可重复性评估]: 全转录组邻居投票法"]},{"i":37525,"as":"研究将气候驱动的叶片功能性状变化引入全球森林汞吸收模型，揭示了大气汞源和汇的跨大陆空间解耦现象。南美洲和非洲的非工业化的热带雨林展现出全球最高的大气汞积累率，固定了大量由工业化地区释放的汞。该模型将全球森林汞吸收量限定为每年1155 ± 422 Mg，大幅缩小了以往评估的不确定性。","scd":null,"kp":["汞汇特征[全球大气汞吸收的跨大陆失衡]: 南美和非洲热带雨林展现最高的大气汞累积率"]},{"i":37526,"as":"研究发现一个包含协同适应等位基因的巨大基因组簇，能够反复驱动鱼类复杂的生命史转变。支持海洋洄游型Galaxias鱼类陆地化的多数强离群基因座共同位于单条染色体上。八种独立陆封种群在多性状（如渗透压调节、肌肉、运动和繁殖）转变上表现出强烈的平行演化基础。至关重要的是，洄游种群中存在携带完整序列的个体，为快速的多性状转变提供了必要条件。","scd":null,"kp":[]},{"i":37527,"as":"富流体钻石内含有微米级流体包裹体，揭示钻石形成介质的性质。研究利用微电子衍射技术，鉴定并各向异性地精细测定了南非富流体钻石中纳米级镁黄长石包裹体的结构，并检测到了额外的纳米级钡/锶碳酸盐包裹体。傅里叶变换红外光谱分析揭示了钻石的高度聚合状态，为确定包裹体形成时的压力、温度和深度条件提供了重要依据。","scd":null,"kp":["包裹体特征[富流体钻石形成介质揭示]: 纳米至微米级矿物包裹体"]},{"i":37528,"as":"为实现深度除氧（氧含量≤1%）以抑制食品保鲜等应用中的氧化变质，传统工业多依赖变压吸附的氮气吹扫法，能耗巨大。研究提出一种电化学环境除氧系统，通过耦合氧还原和氧演化反应，将目标环境中的氧气选择性地转移到环境空气中。该系统有效避免了大量氮气吞吐和高功率输入，尤其适用于制冷成本占主导地位的冷链物流中的除氧需求。","scd":null,"kp":["脱氧参数[深度脱氧]: 氧气水平≤1%","技术机制[节能型环境脱氧]: 电化学选择性氧转移","替代工艺[工业脱氧现状]: 依赖变压吸附的氮气吹扫"]},{"i":37529,"as":"弛豫铁电体的特性源于极性纳米微区的动态响应，通常与破坏长程铁电有序的原子级成分无序有关。研究在完全阳离子有序的反铁电PbMg0.5W0.5O3外延薄膜中发现了弛豫特性，并识别出一种新的低能极性相。与典型弛豫体不同，该薄膜的B位阳离子展现出长程岩盐化学有序。其弛豫行为起源于低温下的自发相竞争。","scd":null,"kp":["弛豫铁电行为[岩盐结构阳离子有序材料]: 由(反)铁电相竞争诱导"]},{"i":37530,"as":"研究展示了一种使用变焦Alvarez超构透镜阵列的自适应光场成像系统。该阵列由两片紧密贴合的超表面组成，每片刻有24×20个立方相位子区域。通过相对横向位移，该超构透镜阵列实现了从3.33毫米到4.50毫米的连续焦距调节。将其集成到全景成像系统中，实现了动态聚焦和扩展的景深范围，克服了固定焦距超构透镜的限制。","scd":null,"kp":["阵列结构[变焦Alvarez超构透镜阵列]: 由两个紧密键合的超表面组成","阵列尺寸[超构透镜阵列]: 24 × 20个立方相位图案"]},{"i":37531,"as":"针对传统一次性空气过滤材料难以拦截超细颗粒物且不可降解的问题，研究提出了一种通用的多级分流静电纺丝策略，用于制备可生物降解的跨尺度纤维膜（TSFM）。由超细纳米纤维、纳米纤维和亚微米纤维交织堆叠构成的TSFM具有曲折的拦截网络，赋予其轻质特性。这种跨尺度纤维膜在实现可靠超防护的同时，有效缓解了废弃滤膜带来的环境负担。","scd":null,"kp":["材料特性[跨尺度纤维膜]: 可降解且能实现对超细颗粒物的超稳定防护"]},{"i":37532,"as":"氧掺杂BaSiN2被证实是一种空气稳定的表面电子器，具有约1.5 eV的超低功函数。其高活性表面能将浮动电子提供给吸附的氮气（N2），形成N2钝化表面。通过表面活化氮气的加氢反应，该表面可实现不断再生。在钌的辅助负载下，这种交替反应途径能够高效合成氨，解决了传统电子器对空气和湿度极度敏感的局限性。","scd":null,"kp":["功函数[氧掺杂BaSiN2表面电甾体]: 约1.5 eV","材料特性[氧掺杂BaSiN2]: 空气稳定且具有高活性表面(可提供电子)"]},{"i":37533,"as":"研究报道了一种单片三维集成电路，用于构建自供电的微型电子传感与处理系统。该电路顶层堆叠石墨烯晶体管用于低功耗化学传感；中间层采用基于n型单层二硫化钼（MoS2）和p型双层二硒化钨（WSe2）的互补逻辑电路进行低功耗处理。该系统利用片上器件从环境中收集能量，适用于边缘计算、物联网和遥感技术等无法更换电池的场景。","scd":null,"kp":["系统功能[单片三维异构集成微电子系统]: 支持自供电传感与处理(无需外部电源)"]},{"i":37534,"as":"航空航天局将执行一项卫星救援任务，计划将一颗轨道正在下降的卫星的轨道高度提升约200公里。此外，新闻简报还提及了欧洲努力成为与美国和中国并列的科技超级大国，以及反对取消远程办公的高管行为分析。","scd":null,"kp":["轨道提升高度[卫星救援任务]: 约200公里"]},{"i":37535,"as":"研究报道了一种单相三功能电催化剂Sr2CoRuO6-δ，其具有明确的超交换双钙钛矿结构。在碱性条件下，该催化剂能有效催化析氧、析氢和氧还原反应。作为液态可充电锌空气电池的空气电极，其峰值功率密度达216 mW cm−2，比容量达748 mAh g−1，寿命长达1000小时。该催化剂还赋予了固态柔性锌空气电池出色的温度和形变适应性。","scd":null,"kp":["催化剂结构[三功能电催化剂]: 单相超交换双钙钛矿结构的Sr2CoRuO6-δ","催化特性[碱性条件]: 高效催化析氧(OER)、析氢(HER)和氧还原(ORR)反应"]},{"i":37536,"as":"研究首次揭示分枝杆菌可通过VII型分泌系统（T7SS）分泌蛋白质毒素进行种间竞争。这些微生物分泌的GH183家族内切-D-阿拉伯聚糖酶效应物，能够靶向并裂解分枝杆菌细胞包被中的阿拉伯半乳聚糖层。研究人员利用结构生物学和生物化学手段描述了这种活性的分子基础，证实了分枝杆菌的特殊厚细胞壁无法完全抵御同类细菌的竞争攻击。","scd":null,"kp":["竞争机制[分支杆菌属]: 分泌GH183家族的endo-D-阿拉伯聚糖酶实现细菌间竞争"]},{"i":37537,"as":"","scd":null,"kp":[]},{"i":37538,"as":"","scd":null,"kp":[]},{"i":37539,"as":"","scd":null,"kp":[]},{"i":37540,"as":"","scd":null,"kp":[]},{"i":37541,"as":"大豆根瘤形成是由根皮层细胞在根瘤菌诱导下重新激活为干细胞引发的。研究鉴定出一种开花素同源物GmFT5b及其伴侣GmFDL23，两者在根瘤菌感染时于根皮层局部上调表达。该GmFT5b-GmFDL23模块直接抑制根皮层中GmCLV3-1的表达，从而解除其对结节干细胞基因的抑制，促进了豆科植物的结瘤固氮过程。","scd":null,"kp":["促结瘤机制[大豆根瘤诱导]: 根瘤菌诱导的FT-FD模块局部激活根结瘤干细胞基因"]},{"i":37542,"as":"","scd":null,"kp":[]},{"i":37543,"as":"","scd":null,"kp":[]},{"i":37544,"as":"针对高倍率和高压锂金属电池中准固态复合电解质（QSCE）面临的界面稳定性与离子传输挑战，研究开发了一种利用聚离子液体接枝多孔二氧化硅杂化分子刷作为多功能填料的高界面稳定性QSCE（PSI）。聚离子液体侧链中硼和氟的协同作用促进了高度稳定的固体电解质界面（SEI）和正极电解质界面（CEI）的形成，显著增强了电极界面的稳定性。","scd":null,"kp":["电解质设计[准固态复合电解质]: 采用聚离子液体接枝的多孔二氧化硅杂化分子刷定制界面","电池性能[锂金属电池]: 具备超高速率和高压特性"]},{"i":37545,"as":"该研究聚焦于利用二氧化碳（CO2）与二甲胺（DMA）的电化学偶联反应，高效合成被广泛用作“通用溶剂”的N,N-二甲基甲酰胺（DMF）。研究团队利用原位傅里叶变换红外光谱（FT-IR）和在线差分质谱（DEMS）技术进行机理探究，成功证实*COO是促进碳氮（C─N）偶联反应的关键中间体。该发现为电催化合成DMF的反应机理提供了微观层面的实证支撑，有助于指导高效催化剂的合理设计。","scd":null,"kp":["[CO2与二甲胺电化学耦合制DMF]: 受限的机理理解制约高效催化剂的合理设计","技术路线[N,N-二甲基甲酰胺电合成]: CO2与二甲胺的电化学偶联"]},{"i":37546,"as":"基于能量转移（EnT）的近红外（NIR）荧光探针在生物传感中具有光毒性低、穿透力强等优势，但缺乏有效的小分子猝灭剂（SMQs）。本研究首次对26,695个紧凑型候选分子结构（≤6个非氢原子）进行了高通量虚拟筛选（HTVS）。研究识别出─N═O、─C═S和─B─N═等具有前景的分子基团，并以─N═O基团为概念验证，实验构建了三个发射波长在590至820纳米之间的红光至近红外探针（P2–P4），成功验证了其有效性。","scd":null,"kp":["候选化合物数量[近红外荧光团小分子猝灭剂的高通量虚拟筛选]: 26,695个紧凑候选分子","[基于能量转移的近红外荧光探针]: 具有体内低光毒性、深光穿透和高信噪比特征"]},{"i":37547,"as":"复分解反应是重组不饱和键的重要有机合成工具，但传统方法高度依赖碳碳不饱和键及过渡金属催化剂，且难以直接引入杂原子。该研究提出了一种无过渡金属参与的硼杂烯烃/炔烃复分解策略。研究表明，硼杂烯烃可以作为非金属卡宾等价物发挥作用。这一全新方法不仅打破了传统对过渡金属催化剂的依赖，还将不饱和键重组与杂原子的直接结合融为一体，为合成环戊烯等复杂有机分子提供了新途径。","scd":null,"kp":["反应类型[无过渡金属体系]: 硼杂烯烃/硼杂炔烃复分解反应","[复分解转化方法学]: 从主要聚焦碳-碳不饱和键拓展至结合不饱和键重组与非碳不饱和键直接引入"]},{"i":37548,"as":"针对水系铵离子电池（AAIBs）缺乏高性能电极材料的问题，该研究利用快速微波法在40分钟内合成了具有多个C═O/C═N氧化还原活性中心的小有机分子DNQP（传统溶剂热法需72小时）。该方法在缩短合成时间的同时，引入了额外的C═N活性键并扩展了π共轭框架。得益于其多电子氧化还原特性，DNQP分子作为有机负极材料，成功实现了超稳定的水系铵离子（NH4+）存储。","scd":null,"kp":["有机分子电极材料[水系铵离子电池]: DNQP（具备多个C═O/C═N氧化还原活性位点的小分子）","合成工艺[DNQP小分子制备]: 快速微波合成法","[小有机分子电极应用痛点]: 合成繁琐、活性位点不足以及在电解液中易溶解"]},{"i":37549,"as":"该研究成功构建了首例由银簇介导的一维多钽酸盐分子异质结构（表示为1g、1y和1r）。该异质结构巧妙结合了作为通用发光单元的银簇和作为光传播单元的多钽酸盐。实验表明，这种组装体系在活性光波导设计中展现出极高的效率，其波导损耗系数极低，介于1.03～1.63 × 10^-3 dB/µm之间。该超低损耗特性使其在超低损耗有源光波导器件和信息编码技术中具有巨大的应用价值。","scd":null,"kp":["[一维银簇介导多钽酸盐分子异质结构]: 具备超低损耗有源光波导和信息编码特性","材料结构[一维分子异质结]: 银簇作为多功能发射体与多钽酸盐结合形成-[Ag9-Ta6]n-链"]},{"i":37550,"as":"分子电子自旋是极具潜力的量子比特候选者，但结构无序和声子耦合引起的快速弛豫与退相干是亟待解决的挑战。该研究通过将四硫富瓦烯（TTF）与一维B←N配位聚合物（CityU-65）共结晶，构建了一种主客体超晶格分子量子比特框架（MQF）。该方法将TTF自由基自旋囚禁在高度有序的晶格中，建立了刚性的磁稀释环境，有效抑制了自旋-晶格弛豫，并部分缓解了退相干效应，从而成功保存了量子相干性。","scd":null,"kp":["量子比特框架[空间隔离的四硫富瓦烯自旋量子比特阵列]: 主客体超晶格MQF（通过四硫富瓦烯与聚合物共结晶构建）","[分子自旋量子比特发展瓶颈]: 结构无序和声子耦合引起的快速弛豫和退相干"]},{"i":37551,"as":"该研究首次观测到单一短链自互补DNA寡核苷酸在热退火处理下，可自组装成长纤维和双层分子管两种截然不同的液晶结构。研究发现，这两种形态的演变由溶液中聚乙二醇（PEG）浓度调控的耗尽力决定。当PEG浓度较低（25-30 w/v %）时，双链间的耗尽力相对较弱，成核过程仅在低温下发生，导致DNA主要进行纵向生长从而形成细长的DNA纤维。小角X射线散射（SAXS）分析进一步揭示了其单晶结构特征。","scd":null,"kp":["[单条自互补DNA寡核苷酸]: 能够自组装形成长纤维和双层分子管两种不同的液晶结构","组装调控参数[成纤维形态]: 聚乙二醇(PEG)浓度处于25-30 w/v %","组装调控参数[成双层分子管形态]: 较高的PEG浓度","[形貌决定因素]: 由PEG浓度调节的耗尽力驱动"]},{"i":37552,"as":"该研究报道了一种通过光氧化还原、钴和布朗斯特酸协同催化，实现对烯丙基羧酸酯进行远程-马尔科夫尼科夫加成胺化的方法。该反应通过金属-氢化物氢原子转移（MHAT）和随后的1,2-自由基酰氧基迁移（1,2-RAM）机制进行。这一过程在远离原始烯烃的位点产生叔碳中心自由基，从而在广泛的底物范围内合成受保护的叔烷基氨基醇类化合物（也可合成仲胺化产物）。实验和计算研究均证实了其高区域选择性的碳氮键形成机制。","scd":null,"kp":["催化体系[烯烃远程马尔科夫尼科夫氨化]: 光氧化还原、钴和布朗斯特酸协同催化","反应机理[远程1,3-氢胺化]: 金属-氢化物氢原子转移(MHAT)后接1,2-自由基迁移及自由基配体转移(RLT)"]},{"i":37553,"as":"针对多孔材料在潮湿环境中因水分子竞争吸附导致六氟化硫（SF6）分离性能下降的问题，该研究提出“超疏水纳米陷阱”策略，设计出一种富氮超疏水多孔有机笼（POC），命名为IMUPOC-DA。该材料外部带有由异丁基链组成的超疏水阻湿层，其内腔则包含π系统和路易斯碱位点。这种特殊结构通过协同作用，在干燥和潮湿条件下均能保持结构稳定性，实现了对SF6/N2混合气体的高效捕获与分离。","scd":null,"kp":["[SF6高效捕集材料]: 超疏水纳米陷阱多孔有机笼","[潮湿环境捕集痛点]: 因水吸附竞争或结构不稳定性导致SF6/N2混合物分离性能下降"]},{"i":37554,"as":"具有三重态基态的发光双自由基在光磁领域极具应用前景，但其内在的高反应活性阻碍了合成并加剧了非辐射淬灭。该研究报道了首个具有明确三重态基态的发光Schlenk双自由基（2）。该分子以甲氧基苯为核心，带有四个多氯苯侧链，可在空气环境中通过常规硅胶色谱法直接分离纯化。其出色的空气稳定性归功于螺旋桨构象产生的空间位阻，该构象有效保护了两个碳自由基中心。全面表征揭示了其光物理特性。","scd":null,"kp":["[首个发光的Schlenk双自由基]: 具有三线态基态","基态属性[发光双自由基]: 三线态基态","[发光双自由基发展瓶颈]: 两个自旋平行的未成对电子带来的高反应性阻碍合成并加剧非辐射猝灭"]},{"i":37555,"as":"量子测温学旨在以极高精度测定量子状态下的温度。传统的平衡态测量方法受限于静态能量波动设定的量子费歇尔信息边界，在固定温度窗口外灵敏度显著下降。该研究提出一种非平衡策略，证明通过引入幺正驱动（Unitary Driving，操作前对系统进行“摇晃”处理），可以突破静态平衡测量的局限。该策略作为一种通用增强手段，显著拓宽了量子测温的高灵敏度范围。","scd":null,"kp":["灵敏度限制因素[标准平衡态量子测温]: 静态能量波动导致的量子Fisher信息"]},{"i":37556,"as":"提升测量精度是传感与计量技术的核心目标。非厄米简并系统（如异常点）具有独特的光谱响应，而压缩态等非经典资源也被广泛用于提升测量精度，但两者的结合极具挑战。该研究成功实现了两者的融合，通过在异常点处引入压缩态资源，获得了极高的光谱响应。实验证实，这种机制为传感器带来了超乎寻常的灵敏度增强，为突破传统测量精度的边界提供了新方案。","scd":null,"kp":["测量精度增强机制[非厄米简并结合非经典压缩资源]: 传感器在奇异点处的感知灵敏度得到非凡增强"]},{"i":37557,"as":"容错量子计算一直面临通用性与维度之间的权衡问题（如拓扑稳定码的Bravyi-König界限）。该研究将拓扑泡利稳定码扩展到更为广泛的n维克利福德层级稳定码体系。研究探讨了这一新体系下的非克利福德门的横向操作以及魔法态的制备。这一成果突破了传统拓扑稳定码在操作维度和门类型上的限制，为构建通用容错量子计算机提供了新的理论路径和编码方案。","scd":null,"kp":["容错量子计算架构[扩展拓扑泡利稳定子码]: n维Clifford层级稳定子码（支持通用的非Clifford门和魔法态）"]},{"i":37558,"as":"引力波数据分析需要从嘈杂的探测器信号中精确提取物理信息，随着观测事件的频率和复杂度不断增加，传统推断方法面临挑战。该研究提出一种基于Transformer架构的深度学习模型，用于实现灵活且高效的引力波参数估计。该方法克服了现有深度学习推断技术在灵活性方面的局限，能够更快速、准确地处理海量且复杂的引力波信号数据，为应对未来引力波天文学的分析需求提供了强大的替代工具。","scd":null,"kp":["参数估计模型[引力波数据分析]: 基于Transformer架构的深度学习模型"]},{"i":37559,"as":"在囚禁离子量子门操作中，由于寻址不精确引起的光学串扰会在目标离子及其相邻离子组合间产生多余的非局域纠缠，而标准量子纠错技术难以有效缓解此问题。该研究提出一种通过设计耦合矩阵来构建纠缠操作的新方法。该方法能够从物理层面精准调控离子间的相互作用，从而在执行纠缠门时使系统对光学串扰不敏感，大幅提高了囚禁离子纠缠操作的保真度与可靠性。","scd":null,"kp":["抗串扰机制[囚禁离子纠缠门]: 耦合矩阵工程（设计纠缠操作使量子纠错无需处理非局部串扰）"]},{"i":37560,"as":"室温铁磁体范德华材料Fe5GeTe2因其独特的磁性和输运性质备受关注，但其微观物理起源尚不明确。该研究利用角分辨光电子能谱（ARPES）等先进手段，直接观测到了该材料中依赖于晶格的磁有序现象。研究不仅揭示了其复杂的磁结构特征，还首次在实验上明确证实了Fe5GeTe2中存在强烈的电子-磁振子耦合效应，为理解该材料奇异磁性和输运现象的微观机理提供了关键实验证据。","scd":null,"kp":["材料属性[范德华Fe5GeTe2]: 室温铁磁性","微观机制[范德华Fe5GeTe2]: 子晶格依赖的磁有序与强电子-磁振子耦合"]},{"i":37561,"as":"识别量子自旋液体（QSLs）中的分数化激发是凝聚态物理的核心挑战之一。在偶极-八极（DO）烧绿石材料（如Ce2Zr2O7）中，理论预测存在π通量量子自旋冰（QSI）态。该研究利用光谱学手段，成功对这种候选态中的演生光子和自旋子进行了明确的光谱学划分与界定。实验清晰地分辨出这两种分数化激发的特征信号，为证明偶极-八极量子自旋液体态的存在提供了至关重要的直接实验证据。","scd":null,"kp":["激发态特征[偶极-八极烧绿石Ce2Zr2O7]: 涌现光子和自旋子的光谱学划分","候选量子态[偶极-八极烧绿石Ce2Zr2O7]: π通量量子自旋冰(QSI)态"]},{"i":37562,"as":"非布朗悬浮液（即颗粒-流体混合物）表现出复杂的非线性流变特性。该实验研究揭示了此类材料不仅能够“记忆”其经历过的流动幅度，还能同时记忆流动的方向。研究发现，这种关于流动幅度和方向的记忆机制在体系内共存且相互竞争。实验明确了这些悬浮液的力学响应高度依赖于其先前的剪切流动历史，极大加深了对复杂流体非平衡动力学及记忆效应的理解。","scd":null,"kp":["流体记忆行为[非布朗悬浮液]: 振幅和方向的记忆共存且相互竞争（依赖历史流动状态）"]},{"i":37563,"as":"该研究提出并探索了一种全新的三方克尔孤子伊辛机（Kerr Soliton Ising Machine），专门用于解决组合优化问题。该机器基于克尔谐振腔中的孤子系综，结合可编程的光电反馈电路，实现了全连接网络结构，并支持高达三方（三次）的交互作用。与传统的双体相互作用伊辛机相比，这种三方交互能力解锁了更高效的计算途径，为复杂组合优化问题的高速求解提供了创新的硬件架构。","scd":null,"kp":["网络连通性[Kerr孤子Ising机]: 全连接","相互作用[三部分Kerr孤子Ising机]: 最高达三部分（三次）相互作用","硬件架构[组合优化Ising机]: 具有可编程光电反馈回路的Kerr谐振器孤子系综"]},{"i":37564,"as":"活性润湿是一种真实的表面相变现象，在动力学转变路径上与平衡态临界润湿转变存在显著差异。该研究揭示了活性流体在润湿转变过程中的自发定向棘流现象及其非平衡动力学机制。研究证实，活性系统在发生相变时不仅打破了平衡态的限制，展现出被动流体无法实现的禁戒动力学路径，还形成了具有方向性的自发流动。这一发现为理解活性物质微观相变机理提供了新视角。","scd":null,"kp":["相变特征[活性润湿]: 具有自发棘轮电流及与平衡临界润湿不同的动力学转变路径"]},{"i":37565,"as":"研究了包含静态自旋超流湍流的原子玻色-爱因斯坦凝聚体（BEC）中集体振荡的阻尼现象。实验类比了经典流体中湍流增强动量传输并有效增加粘度的效应，证实了超流体中存在类似机制。","scd":null,"kp":["[超流体]: 含有静态自旋超流湍流的原子玻色-爱因斯坦凝聚体中集体振荡的阻尼增强"]},{"i":37566,"as":"","scd":null,"kp":[]},{"i":37567,"as":"","scd":null,"kp":[]},{"i":37568,"as":"","scd":null,"kp":[]},{"i":37569,"as":"针对可扩展光量子技术中对高纯度单光子的需求，解决了自发参量下转换（SPDC）光子对固有光谱相关性限制单光子纯度的问题。研究在芯片上实现了同偏振且光谱可分离的光子对生成。","scd":null,"kp":["[自发参量下转换(SPDC)光子对]: 同偏振且光谱可分离"]},{"i":37570,"as":"揭示了强无序超导体中的微波耗散是由罕见薄弱区域内局域化的低能集体模式驱动的。这一理论发现阐明了耗散机制，并为提升量子器件的相干时间提供了新的策略和理论依据。","scd":null,"kp":["微波耗散机制[强无序超导体]: 由罕见薄弱区域内的局域集体模式驱动","[量子器件]: 基于理论洞见提供延长相干时间的新策略"]},{"i":37571,"as":"利用确定性量子蒙特卡洛方法研究了半满Haldane-Holstein模型。研究发现，延迟的电子-声子相互作用会破坏陈绝缘体的拓扑稳定性，对拓扑相与电荷序的竞争关系进行了无偏的表征。","scd":null,"kp":["拓扑不稳定性[半满Haldane-Holstein模型]: 延迟的电子-声子相互作用破坏Chen拓扑"]},{"i":37572,"as":"在相关Kagome扁平能带金属CsCr6Sb6中，观察到了来自局域Cr-3d电子的近藤行为以及费米能级附近前所未有的能带扁平化。该材料展现出演生的动力学近藤相干性以及与之竞争的磁有序。","scd":null,"kp":["材料体系[Kagome平带金属]: CsCr6Sb6","量子现象[CsCr6Sb6]: 局域Cr-3d电子的近藤行为及费米能级附近前所未有的能带扁平化"]},{"i":37573,"as":"描述了一种使用超冷YbF分子的自旋干涉仪，并开发了用于测量电子电偶极矩的完整技术。分子在光学黏胶中冷却并被制备至单一内量子态，通过拉曼跃迁实现了干涉测量。","scd":null,"kp":["干涉仪类型[超冷分子束]: 使用超冷YbF分子的自旋干涉仪","[超冷YbF分子]: 在光学粘胶中冷却并制备于单一内部量子态"]},{"i":37574,"as":"研究了双光子泵浦的极化激元凝聚体中由暗激子诱导的玻色子受激辐射的时间特征。强耦合的激子-极化激元固态平台支持宏观量子凝聚现象，并证明了通过暗态相互作用实现光学控制的可能性。","scd":null,"kp":["[激子-极化激元凝聚体]: 通过与暗态的相互作用实现宏观量子凝聚现象的光学控制"]},{"i":37575,"as":"","scd":null,"kp":[]},{"i":37576,"as":"","scd":null,"kp":[]},{"i":37577,"as":"","scd":null,"kp":[]},{"i":37578,"as":"针对手性边缘态受拓扑保护而难以被暂停或空间局域化的挑战，在声子晶体中提出并实现了“拓扑槽”结构。该设计能够按需捕获或限制这些传输信息的声学载体，突破了拓扑保护带来的操控限制。","scd":null,"kp":["拓扑状态[声子晶体]: 实现手性边缘态的空间限制与按需暂停"]},{"i":37579,"as":"利用人工SU(2)规范场在声学系统中实现了非阿贝尔拓扑绝缘体。该系统不仅与粒子物理及自然界强弱相互作用相联系，还展示了具有非凡特性的拓扑现象，在人工非阿贝尔拓扑物态调控上取得重要进展。","scd":null,"kp":["拓扑绝缘体[人工SU(2)规范场]: 声学非阿贝尔拓扑绝缘体"]},{"i":37580,"as":"","scd":null,"kp":[]},{"i":37581,"as":"","scd":null,"kp":[]},{"i":37582,"as":"","scd":null,"kp":[]},{"i":37583,"as":"利用极化中子衍射技术在块体MnTe中观测到了交变磁有序的翻转现象。交变磁态由奈尔向量特征化，破坏了时间反演对称性。该研究直接观测了由时间反演对称性相连的反相畴，证实了宏观输运现象的内部抵消机制。","scd":null,"kp":[]},{"i":37584,"as":"利用BESIII探测器收集的约100.87亿个J/ψ事件，对J/ψ→ΛΛ¯衰变过程进行了全角分析。该研究通过测量Λ→nπ0及其反粒子的衰变参数，对中性Λ衰变中的电荷共轭与宇称（CP）对称性进行了精确检验。","scd":null,"kp":[]},{"i":37585,"as":"首次计算了电子-正电子湮灭中四喷流产生的次次领头阶（即α_s^4阶）产率。这是迄今为止在微扰精度下考虑的最高末态喷流多重性计算，且成功实现了红外奇异性的抵消。","scd":null,"kp":[]},{"i":37586,"as":"报道了首个基于有机光伏材料Y6的光电易失性单分子忆阻器。该器件通过电场诱导的结构弛豫实现可重现的电导开关，能够模拟突触行为的线性电导调制。在红光照射下，Y6结的电导率增加457%，且开关阈值显著降低。","scd":null,"kp":["忆阻器[神经形态应用]: 基于有机光伏材料Y6的首个光电易失性单分子忆阻器","器件特征[单分子器件]: 高集成密度与低能耗，并由电学驱动实现可重现的电导切换"]},{"i":37587,"as":"开发了一类新型π-扩展COUPY荧光染料。通过香豆素骨架外环双键的插烯改性，引发红移效应，实现了高效的远红光/近红外（NIR）性能。该染料有效克服了传统近红外探针光稳定性差、量子产率低等局限，适用于活细胞靶向近红外荧光及寿命成像。","scd":null,"kp":["[π-Extended COUPY染料]: 用于活细胞靶向近红外荧光和寿命成像","[传统近红外荧光探针]: 具有较差的光稳定性、较低的荧光量子产率和有限的化学通用性"]},{"i":37588,"as":"通过高温煅烧三金属层状双氢氧化物，合成了Co1.29Ni1.71O4/NiFe2O4异质结作为钠离子电池负极。结合密度泛函理论与分子动力学模拟，该设计有效调节了材料的电子结构，解决了固态电解质界面（SEI）不稳定性与降解机制不清的问题，提升了电池的倍率性能和循环寿命。","scd":null,"kp":["[钠离子电池负极材料]: 受到固体电解质界面(SEI)不稳定性及退化机制不清晰的限制","[Co1.29Ni1.71O4/NiFe2材料]: 用于解决SEI不稳定问题并实现稳定快速的钠存储"]},{"i":37589,"as":"研究了分别在630、670和700°C下生长的Ba0.7Ca0.3TiO3薄膜，建立了“生长-结构-性能”的定量关系。该研究解决了无铅铁电薄膜难以同时兼顾高介电可调谐性、稳定性及优异电卡性能的挑战，实现了无铅可调谐组件与固态制冷技术的功能协同优化。","scd":null,"kp":["[无铅铁电薄膜]: 面临难以同时实现高介电可调性、热/频率稳定性和高效电卡性能的挑战","[Ba0.7基薄膜]: 通过生长驱动的畴动力学实现高介电可调性和优异的电卡性能"]},{"i":37590,"as":"提出一种溶剂化重构策略，将极性碳酸酯引入基于NaTFSI-NMA的深共晶复合固体电解质中。碳酸酯分子优先进入Na+的溶剂化结构，解决了质子型深共晶电解质中活性氢与金属钠负极反应导致性能快速衰减的问题，有效稳定了固态钠电池的界面。","scd":null,"kp":["[质子型深共晶电解质(如N-甲基乙酰胺NMA)]: 其活性氢极易与金属钠负极反应导致性能迅速衰退","[固态钠电池(SSSBs)]: 受限于固态电解质低离子电导率和严重界面副反应"]},{"i":37591,"as":"选用具备优异高温与化学稳定性、无毒且低成本的CaTiO3作为光热电（PTE）材料。针对其本征绝缘性的缺陷，该工作成功将绝缘CaTiO3加工成高性能光热电材料，克服了传统主流PTE材料高温稳定性差的缺陷，适用于高温监测和工业废热检测等恶劣场景。","scd":null,"kp":["[光热电(PTE)材料]: 传统主流材料受限于较差的高温稳定性，难以应用于恶劣场景","[绝缘体CaTiO3]: 经工艺处理可转化为高性能光热电材料"]},{"i":37592,"as":"提出一种表面活性剂单层辅助的水面合成方法，实现了导电Ni-HHTP（2D c-MOF）薄膜层间取向的可控合成。该方法通过程序化控制薄膜的面朝向，克服了二维共轭金属有机框架结构与传输各向异性对器件性能的敏感影响，实现了高性能化学电阻传感器应用。","scd":null,"kp":["[二维共轭金属有机框架(2D c-MOFs)薄膜]: 其器件性能对层取向高度敏感","[水面表面合成策略]: 能够控制二维共轭金属有机框架薄膜的层取向以实现高性能化学电阻传感"]},{"i":37593,"as":"提出一种金属触发表面缺陷策略，以Au-ZnSnO3为模型，通过Au锚定自发诱导Zn空位形成，打破表面对称性并增强极化。该方法将表面金属锚定与缺陷形成相结合，增加了活性位点密度，解决了压电催化制氢中极化弱和活性位点不足的问题，实现了长期设备级的可持续制氢。","scd":null,"kp":["[压电催化产氢]: 现有研究多局限于材料层面，存在极化弱、活性位点不足及缺乏长期器件级验证等问题","[金属触发表面缺陷策略]: 通过金属锚定与自发对称性破缺实现耐久的压电催化析氢"]},{"i":37594,"as":"提出利用两性离子水凝胶蒸发器的离子渗透策略。该电荷平衡水凝胶网络允许离子向下渗透并抑制向上的水分对流，有效防止了界面结晶。该蒸发器构建了盐水对流与离子渗透的空间分离通道，在高盐度条件下仍能维持超过3.50 kg m−2的高蒸发速率，实现了稳定的太阳能海水淡化与盐度梯度发电。","scd":null,"kp":["[两性离子水凝胶蒸发器]: 实现向下离子渗透的同时抑制向上的水共渗透，用于稳定太阳能海水淡化和发电","[传统排盐策略]: 主要依赖被动扩散，在高盐度下通常失效"]},{"i":37595,"as":"证明了金属卤化物前驱体的配位几何结构对表面钝化效能具有重大影响。HgBr2的八面体几何结构促进了稳定的HgBr2(Olam)4复合物的形成，有效抑制了背景载流子密度，将其降低至约10^14 cm−3的内禀水平，克服了中波红外波段胶体量子点中表面陷阱诱导载流子掺杂的限制。","scd":null,"kp":["背景载流子密度[金属卤化物前驱体配位工程调控HgTe胶体量子点]: 抑制至本征水平(~10^1 cm^-3)","[表面陷阱诱导的载流子掺杂]: 阻碍了胶体量子点达到外延级半导体的电子纯度，尤其在MWIR(中波红外)波段"]},{"i":37596,"as":"发现在废旧磷酸铁锂（SLFP）直接再生过程中，各类有机分子均会生成大量碳点（CDs），这是SLFP再生的普遍规律。CDs在再生过程中发挥关键作用：不仅在水热过程中表现出还原效应，还在随后的烧结阶段重建了不均匀的碳层，使再生后的LiFePO4展现出优异的电化学性能。","scd":null,"kp":["[废旧磷酸铁锂(SLFP)直接再生]: 水热处理过程中各种有机分子生成的碳点(CDs)在结构缺陷修复中发挥关键作用"]},{"i":37597,"as":"提出了一种名为“Metaspire”的全新弹性超材料平台架构。该架构利用顺序旋转特性，解决了现有非局域超材料在扩展性上的限制，实现了多重非局域耦合和高维阵列。同时，该平台克服了弹性波中的模式耦合限制，支持对独立弹性波模式中独特非局域波动现象的清晰研究。","scd":null,"kp":["非局域超材料[波控制]: 通过与非相邻晶胞相互作用实现","非局域超材料[可扩展性与阵列]: 受限于难以实现多重非局域耦合和高维阵列","弹性非局域超材料[模式耦合]: 存在限制其性能的模式耦合问题"]},{"i":37598,"as":"开发出一种装载植酸/Zn2+的凝胶化巨噬细胞工程材料。该材料在室温下通过在活体巨噬细胞内聚合聚阳离子水凝胶并负载植酸/Zn2+制成，将完整巨噬细胞膜的天然免疫中和功能与水凝胶的特性相结合，实现了牙周炎治疗中毒素中和、病原体 eradication（根除）与促成骨的协同作用。","scd":null,"kp":[]},{"i":37599,"as":"提出了一种智能“纳米隔离”策略，结合具有聚集门控活性氧（ROS）生成特性的AIE-半花青光敏剂。通过将推进型AIE基元引入平面半花青衍生物构建扭曲的供体-π-受体结构，其中MTPAON表现出最大的构象扭曲和最高的ROS生成量，主要生成对氧气依赖性较低的I型ROS，解决了光动力治疗中高氧依赖和脱靶光毒性问题。","scd":null,"kp":[]},{"i":37600,"as":"构建了一种基于热响应工程化活体存储微球体的可再生“活体磁盘-驱动器”DNA数据存储系统。该系统将编码数据的细菌作为离散的文件级活体存储单元封装，每个微球体包含携带信息质粒（编码26×26像素图标载荷及荧光检索指数）和辅助质粒，通过CRISPR-Cas12a/λ-Red系统实现可重写功能。","scd":null,"kp":[]},{"i":37601,"as":"构建了一种将富电子钌纳米簇锚定在双金属磷化物界面的动态预催化剂架构。在碱性水电解中，富电子Ru纳米簇作为局域电势响应电子介体，有效调解了磷化物催化剂的表面重构过程，解决了传统过渡金属磷化物析氧反应（OER）中缓慢的原位高价态转化动力学矛盾，实现了高效水电解。","scd":null,"kp":["催化剂[析氢反应(HER)]: 电子富集的金属-磷骨架","催化剂[析氧反应(OER)]: 需要快速原位转化为高价金属(氢)氧化物","催化剂[重构悖论]: 富电子结构促进HER但阻碍OER所需的高价态转化"]},{"i":37602,"as":"引入一种偶极玻璃聚合物设计，通过柔性间隔基团将活性偶极侧基结合到刚性聚酰亚胺骨架中。刚性骨架提供了宽带隙和玻璃态基质，实现了高达964 MV m−1的超高击穿强度；活性乙酰侧基则实现了空间位阻最小化的可逆取向极化。该设计打破了高能量密度与高充放电效率之间的权衡。","scd":null,"kp":["聚合物电介质设计[偶极玻璃聚合物]: 通过柔性间隔基将活性偶极侧基并入刚性聚酰亚胺主链"]},{"i":37603,"as":"提出一种基于能量收集-管理-存储一体化策略的自充电动力纺织品。系统采用纤维状摩擦纳米发电机收集运动能量，结合能量管理模块，并利用钠藻酸盐/聚乙烯醇(SA/PVA)水凝胶电解质中Zn2+辅助的原位快速交联策略，实现了纤维状锌离子电池的规模化生产，该电池在100次循环后容量保持率为95.7%。","scd":null,"kp":["电源纺织品[系统策略]: 集成能量收集-管理-存储策略","摩擦纳米发电机[可穿戴织物]: 纤维状摩擦纳米发电机(F-TENGs)","锌离子纤维电池[交联策略]: Zn2+辅助海藻酸钠原位快速交联策略"]},{"i":37604,"as":"通过“全链延伸后冷却辅助组装”策略，制备了高质量的蓝相液晶弹性体（BPLCE）。该材料克服了低温（<0°C）柔性薄膜制造及热-光-机械-结构关系理解的挑战，展现出优异的光学特性和独特的胆甾螺旋结构，成功实现了在低温环境下的可视化机械传感能力。","scd":null,"kp":["材料体系[低温视觉机械传感]: 蓝相液晶(BPLCs)","视觉机械传感材料[极寒环境]: 适用于低温(<0°C)环境"]},{"i":37605,"as":"本文提出了一种可扩展的Cr(III)钝化策略，用于解决水系锌离子电池中锌负极的自腐蚀问题。该策略在锌表面构建了一层超薄（约100纳米）且致密的Cr2O3层。该材料具有高达6.96 eV的锌化学势，在多种商业钝化材料中最高。这种设计形成了陡峭的化学势梯度，显著提高了锌原子逃逸的能量势垒，从而有效抑制了静置条件下的自腐蚀现象。","scd":null,"kp":["表面钝化层厚度[锌负极Cr(III)钝化]: ~100 nm","钝化层成分[锌负极表面保护]: 致密的Cr2O3层","电池失效机理[水系锌离子电池阳极]: 锌原子逃逸和析氢反应引起的自腐蚀"]},{"i":37606,"as":"本文设计了一种软性隐形眼镜传感器，用于在家庭环境中连续监测夜间眼压（IOP），以解决青光眼管理中夜间眼压波动难以测量的难题。该传感器将基于柔性导体的电感-电容电路直接集成到商业软性隐形眼镜上，能够紧密贴合眼球。测试表明，该设计实现了迄今为止可穿戴设备中最高的眼压灵敏度，克服了现有设备在闭眼性能和整夜可穿戴性方面的限制。","scd":null,"kp":["传感器[夜间眼压监测]: 软性隐形眼镜传感器","可穿戴眼用传感器[闭眼及睡眠监测]: 克服了闭眼性能和夜间佩戴能力的局限性"]},{"i":37607,"as":"本文通过改进的静电纺丝方法，制备了一种柔性的超低密度HfO2-ZrO2-SiO2陶瓷气凝胶。该材料协同集成了辐射制冷、热绝缘、机械鲁棒性和超宽温度范围适应能力，克服了现有材料在工作温度和机械强度上的局限。实验结果表明，该陶瓷气凝胶能够实现98.0%的高太阳能反射率和高红外发射率，为降低全球制冷与供暖带来的能源消耗提供了有效的材料方案。","scd":null,"kp":["气凝胶材料特性[辐射制冷与热绝缘]: 柔性且超低密度","气凝胶材料成分[辐射制冷与热绝缘]: HfO2-ZrO2-SiO2体系"]},{"i":37608,"as":"本文提出利用发光咔唑连接位点异构策略来抑制非富勒烯受体（NFAs）的非辐射复合损失，以提升有机太阳能电池性能。研究设计合成了两种咔唑功能化受体QxCz-C和QxCz-N。理论计算表明，QxCz-C呈共面构象，而QxCz-N呈垂直构象。将QxCz-C作为微量客体掺入主体材料BTP-eC9后，制备的有机太阳能电池实现了21.10%的光电转换效率，并有效降低了非辐射复合损失。","scd":null,"kp":["能量转换效率[有机太阳能电池]: 21.10%","分子设计策略[非富勒烯受体]: 利用具发光性的咔唑连接位点异构来抑制非辐射复合"]},{"i":37609,"as":"本文提出了一种基于机器学习的高通量筛选框架，以加速高温电容储能材料的开发。研究发现，引入脂环族单元可以调节短程有序结构的形成，通过电子局域化显著抑制电荷传输。实验和模拟结果均表明，基于此机制制备的半芳香族聚酰亚胺薄膜展现出优异的储能性能，其放电能量密度达到6.74 J/cm³，满足了极端条件下稳定运行的要求。","scd":null,"kp":["材料研发框架[聚合物电介质电容器]: 机器学习驱动的高通量筛选框架","材料改性策略[高温储能性能调控]: 引入脂环族单元"]},{"i":37610,"as":"本文设计并合成了一系列具有D-A构型的共价有机框架化合物，通过优化分子内电荷分布，构建了可调的内置电场并降低了电荷载流子复合率，以解决光辅助锂气电池电极太阳光吸收窄和电荷分离不足的问题。实验表明，优化后的苯醌基COF-2展现出最低的光生载流子跃迁势垒，受强电子推拉效应和低跃迁势垒驱动，实现了光辅助锂-空气电池的超高倍率性能。","scd":null,"kp":["光电极[光辅助Li-气电池]: 非金属共价有机框架(COFs)","[充放电过电位]: 通过引入光电极降低过电位","[电荷分离与吸收]: 采用给体-受体(D-A)构型改善窄太阳能吸收和电荷分离不足"]},{"i":37611,"as":"本文利用大规模原子模拟，揭示了化学复杂性调节钨基多主元合金中氦气泡演化的原子尺度机制。研究发现，化学复杂合金中气泡压力的降低抑制了位错环冲孔（纯钨中表面起毛的主要驱动力），从而稳定了次表面微结构。这种抑制作用由两种协同机制主导：一是拓宽缺陷能量分布并降低团簇结合能的热力学非均匀性；二是相关物理效应，这解释了该材料具备卓越抗辐照损伤能力的原因。","scd":null,"kp":["结构材料[聚变反应堆应用]: 体心立方(BCC)多主元素合金(MPEAs)","[耐辐照损伤机制]: 化学复杂性降低气泡压力从而抑制氦气泡演化"]},{"i":37612,"as":"本文综述了涉及烯烃部分的碳碳（C-C）键选择断裂技术。由于C-C键强度高且极性低，其选择断裂极具挑战性。烯烃是化工领域的重要原料，对其破坏性官能化以构建复杂分子骨架备受关注。传统方法主要断裂双键，而最新进展开辟了两条互补途径：一是选择断裂双键相邻的坚固σ键；二是另一种新型断裂模式。该工具在分子解构和骨架编辑中发挥着强大作用。","scd":null,"kp":["[碳-碳键断裂]: 涉及烯烃部分的选择性解构功能化"]},{"i":37613,"as":"本文针对经典单调鞘层这一未探索领域，提出了一种解析经验模型，用于预测多发射磁化鞘层中逃逸的电子电流密度。在ITER边缘局域模期间，等离子体面向部件（PFCs）会通过场助热电子发射、二次电子发射（SEE）和电子背散射（EBS）释放电子。该模型结合了基于粒子轨道模拟的表面电场下快速再沉积的半经验描述，为评估ITER PFCs因宏观熔体运动造成的变形提供了关键物理量。","scd":null,"kp":["[等离子体面向部件变形评估]: 建立多发射磁化鞘逸出电流密度预测模型","[电子发射机制]: 场辅助热电子发射、二次电子发射(SEE)和电子背散射(EBS)"]},{"i":37614,"as":"本文利用冷冻电子显微镜技术，确定了Rad26/CSB-核小体复合物的结构。Rad26是转录耦合核苷酸切除修复的关键分子支架。结构表明，Rad26/CSB通过其ATP酶结构域以与Snf2和Ino80等其他重塑因子相反的方向结合核小体DNA，结合位点靠近核小体进出口区域（超螺旋位置±6）。这种独特的结合机制为其在DNA修复后帮助恢复转录的核小体重塑活性提供了结构基础。","scd":null,"kp":[]},{"i":37615,"as":"本文揭示了小鼠动眼神经核胆碱能神经元（nIIIChAT）的双重功能组织，它同时控制眼球运动和快速眼动睡眠（REMs）。其中，投射至腹外侧导水管周围灰质的nIIIChAT神经元亚群活性在REMs结束前进行性增加，光遗传学激活该亚群会抑制REMs但不影响眼球运动；而投射至眼外肌的nIIIChAT神经元能可靠地诱导眼球运动，却不改变睡眠-觉醒状态。这解释了REMs中运动抑制与眼球运动保留的协调机制。","scd":null,"kp":[]},{"i":37616,"as":"本文利用单细胞和空间转录组学，揭示了免疫性血小板减少症（ITP）中的中性粒细胞-巨核细胞轴。研究发现，中性粒细胞衍生的S100A8/A9结合TLR4并激活JNK/c-Jun信号通路，抑制巨核细胞主调控因子GATA1，从而限制其成熟。使用他喹莫德或抑制TLR4可部分恢复ITP血浆导致的巨核细胞多倍体化和血小板颗粒释放受损。在小鼠ITP模型中，他喹莫德有效促进了血小板恢复并改善了巨核细胞丰度。","scd":null,"kp":[]},{"i":37617,"as":"本文通过独立队列（28名健康受试者，121次前后赛洛西滨fMRI扫描），评估了13项评估致幻剂对大脑熵影响的指标。使用线性混合效应模型，结合两种分区策略和7种去噪管道，发现空间特征向量分布的香农熵、路径长度、瞬时相关性、大脑状态切换和短时间尺度样本熵与客观及主观致幻药效存在一致的显著正相关。研究未观察到部分其他熵指标具有一致性关联。","scd":null,"kp":[]},{"i":37618,"as":"本文发现Gα-GTP酶激活蛋白家族成员RGS22是后生动物特异性的放射辐条复合体RS1/2组分。缺失Rgs22的小鼠运动纤毛表现出超微结构缺陷，包括RS1变形和外动力蛋白臂紊乱。这些异常导致纤毛平面极性受损，表现为纤毛搏动不同步和室管膜基底体旋转极性破坏。这证实了RGS22在介导中心对与动力蛋白臂间机械信号转导及协调组织级纤毛定向流动中的关键作用。","scd":null,"kp":[]},{"i":37619,"as":"本文研究了III-D2型CRISPR-Cas系统的分子机制，该系统可能是III-A和III-E系统之间的进化中间体。研究通过冷冻电子显微镜确定了III-D2效应复合物在不同功能状态下的结构，展示了Cas10亚基如何识别SAM和ATP，并在响应靶标RNA时合成两种不同的第二信使：SAM-AMP和SAM-AMP2。生物学数据进一步表明，这两种第二信使均作用于CorA辅助效应器，诱导生长停滞。","scd":null,"kp":[]},{"i":37620,"as":"本文对66种与人类皮肤感染高度相关且普遍存在的真菌菌株进行了基因组测序和比较基因组学分析。研究探讨了不同分类群在基因组结构、代谢能力、分泌酶库、黏附素含量和预测毒力因子方面的差异。分析揭示了真菌基因组大小和基因内容的显著变异，表明随着真菌向皮肤相关的转变，发生了基因组紧缩现象。这为理解皮肤真菌的致病机制提供了重要数据。","scd":null,"kp":[]},{"i":37621,"as":"本文利用2255名强迫症（OCD）患者和2264名对照的大样本，通过9种皮质和4种皮质下表型（包括新开发的皮质下结构相似性网络表型），对OCD的脑形态学进行了多维表征。研究发现不同结构表型存在空间上不同的区域改变：默认模式和额顶网络的皮质曲率改变，感觉运动区域结构相似性网络节点度增加，以及与药物使用相关的广泛体积减少。预测模型进一步揭示了脑形态改变与行为之间的关联。","scd":null,"kp":[]},{"i":37622,"as":"本文通过宏基因组和代谢组学分析发现，具核梭杆菌在结直肠癌患者中显著富集，且与癸酸水平升高密切相关。单细胞转录组测序显示，肿瘤组织中存在特异性中性粒细胞富集。细胞实验证实，癸酸会诱导细胞晚期凋亡/坏死，并介导高水平表达CXCL8的中性粒细胞趋化作用，激活相关免疫通路。这揭示了具核梭杆菌通过癸酸驱动的中性粒细胞趋化促进结直肠肿瘤发生的具体机制。","scd":null,"kp":[]},{"i":37623,"as":"本文解析了线粒体核糖体小亚基的组装过程，该过程对线粒体翻译和细胞能量产生至关重要。研究从人类细胞中分离并表征了mtSSU的12种不同组装状态，详细揭示了mtSSU平台、解码中心及其最终成熟阶段的精细结构。研究发现假尿苷合成酶PUS1和起始因子mtIF2是mtSSU组装过程中的关键因子，为理解线粒体基因表达机制及相关人类疾病的致病机理提供了重要的结构基础。","scd":null,"kp":[]},{"i":37624,"as":"本文强调非洲在全球基因组研究中的代表性不足，指出其拥有无与伦比的遗传多样性。政治、资金和社会挑战阻碍了相关进展，需要提高公众认知、消除社会污名并与国家政策保持一致。非洲拥有大量高技能科学家和具备DNA分析能力的实验室，具备推动创新的机会。文章呼吁推进全球基因组公平，强调开展非洲国家基因组项目的重要性，并提出了可行的行动建议。","scd":null,"kp":[]},{"i":37625,"as":"研究团队在共生固氮的根瘤菌-豆科植物中，发现了一个能直接激活结瘤因子受体（GmNFR1ɑ）的信号模块。该模块由GmNIN1a、蛋白酶GmSBT1.2、肽类GmPSK4及其受体GmPSKR1组成。研究表明，GmNIN1a特异性激活蛋白酶，进而将GmPSK4切割为成熟形式以促进大豆结瘤。基因敲除实验证实，敲除该肽类基因会严重损害结瘤过程，且遗传学分析确认了该模块成员间的功能相互依赖性。","scd":null,"kp":[]},{"i":37626,"as":"为解决多组学数据整合中因数据缺失和异质性带来的信息丢失问题，研究提出了MIND（基于邻域感知分布的多模态整合）方法。该方法利用带数据驱动先验的多模态变分自编码器，直接从不完整的组学数据中学习患者特异性嵌入。通过注入观测数据集的邻域结构，MIND有效避免了填补或样本剔除等传统强假设方法带来的偏差，提升了癌症患者分层等任务的分类与预测性能。","scd":null,"kp":["[多模态数据整合]: 采用邻域感知分布(MIND)方法处理多组学数据的缺失和异质性问题"]},{"i":37627,"as":"针对癌症免疫治疗耐药性问题，研究利用多重技术对250名转移性黑色素瘤患者进行了基于血液的多模态蛋白质组学分析。研究在连续时间点上检测了超过2900种血浆蛋白，并结合外周血淋巴细胞的高维质谱流式技术。同时收集了92份匹配的单细胞肿瘤样本。该方法突破了以往扩展性不足和时间序列采样缺失的限制，通过无偏倚的血液蛋白分析揭示了免疫检查点阻断疗法的抗性机制。","scd":null,"kp":[]},{"i":37628,"as":"为解决固态锂金属电池的界面机电化学失效问题，研究开发了一种基于氢键聚氨酯基体的机械集成梯度电解质。该基体具有超5000%的断裂应变和高自愈性，支持高填料负载。通过构建空间梯度的Li1.3Al0.3Ti1.7(PO4)3（含量10-100 wt%）架构，电解质解耦了界面需求：既实现了与锂金属负极的共形接触，又保持了高离子传导，从而显著提升了固态电池的长循环性能。","scd":null,"kp":["粘弹性[聚氨酯基体]: >5000%","[固态锂金属电池]: 具有双链扩展剂的氢键聚氨酯基机械集成梯度电解质"]},{"i":37629,"as":"研究打破了时空光学涡旋（STOVs）中横向轨道角动量（OAM）生成的刚体对称性限制。通过对方位角相位梯度的非线性映射，研究实现了可编程的时空通量呼吸现象。理论与实验证实，局部相位梯度的变化会引发瞬时群速度各向异性，促使局部OAM密度自发重组为稳定的多瓣晶格结构。该技术在保持基础拓扑特征的同时，实现了对光波包内部动力学的精细调控。","scd":null,"kp":[]},{"i":37630,"as":"受果蝇视觉系统启发，研究开发了一种具备三级协同机制的柔性人工复眼相机。该相机由塑料光纤和曲面微透镜阵列构成，用于实时全景成像；两条系绳模拟头部肌肉运动，实现了高达270°视场角内对微弱信号的连续追踪；并集成神经回路机制以处理动态场景。该仿生系统克服了传统人工复眼的局限，为混合现实中的超广角连续追踪提供了理想方案。","scd":null,"kp":[]},{"i":37631,"as":"研究解决了固体自旋发射器中无法同时进行光学自旋控制和单次读出的难题。利用空穴混合机制在带负电的重空穴激子中构建了高不对称的Lambda系统。通过补偿由拉曼控制场引起的吉赫兹级差分斯塔克位移并执行核自旋冷却，成功在半导体量子点中实现了具有循环光学跃迁的自旋相干控制。这为量子通信中的量子存储与单光子接口提供了技术支撑。","scd":null,"kp":["收集效率[半导体量子点耦合光子结构]: 接近100%","[量子点自旋]: 采用循环光学跃迁实现相干控制以解决同时光学自旋控制和单次读出不兼容的问题"]},{"i":37632,"as":"研究提出了一种名为“二色性成像”（Dichography）的单衍射图样超快成像方法。利用X射线自由电子激光器发射的两种不同颜色、时间延迟的超短X射线脉冲，获取样品的时间延迟快照。该算法能有效分离探测器上重叠的衍射信号，独立重建两张图像。实验以20纳米的空间分辨率重建了氦纳米液滴的图像，证实在750飞秒延迟下样品未发生显著结构损伤。","scd":null,"kp":[]},{"i":37633,"as":"为推进光量子集成电路的大规模扩展，研究实现了位点可控的砷化镓量子点阵列与氮化硅单模波导阵列的主动对准和边缘耦合。在低温条件下，利用每个量子点周围自对准的纳米柱结构，将十个量子点成功耦合到十条波导中。这种高单光子产率的规则阵列被集成到片上，并通过片上分束器进行了功能验证，解决了量子光源随机性限制扩展性的问题。","scd":null,"kp":["光源阵列[集成硅氮化物波导]: 十个位置可控的砷化镓量子点阵列","[混合集成]: 采用主动对准和边缘耦合技术结合不同平台"]},{"i":37634,"as":"研究在理论和实验上展示了一种源于材料固有非局域性的全新电磁响应机制。通过在非局域响应的内禀尺度上对材料进行微结构化，复合材料的电磁特性被改变，从而显露出组成成分固有的非局域行为。这种本征非局域超材料在室温下的宏观有损材料中表现出强烈且易检测的本征非局域性，打破了传统超材料仅依赖有效介质参数的限制。","scd":null,"kp":["[电磁超材料]: 展现出源于固有材料非定域性的全新电磁响应机制"]},{"i":37635,"as":"为解决多相金属催化剂在无溶剂反应中润湿性差、活性低的问题，研究将亚纳米铑（Rh）团簇限制在自支撑沸石结构中，制备出一种无机多相催化剂。该设计稳定了Rh活性位点，并在无溶剂烯烃加氢甲酰化反应中实现了高效传质。得益于Rh团簇独特的电子特性和沸石载体的最佳形貌，该催化剂在广泛的反应中实现了超过110万的总转化数，表现出优异的催化性能。","scd":null,"kp":["[无溶剂有机转化催化剂]: 将亚纳米Rh团簇限制在自支撑沸石结构中的无机Rh催化剂","[催化特性]: 解决非均相金属催化剂的润湿性问题并提高稳定性和催化活性"]},{"i":37636,"as":"研究提出了一种基于脉冲神经网络（SNN）的解码框架，用于从高密度肌内微电极阵列中高效处理运动单元活动。该框架利用SNN的动力学特性，在15%最大自主收缩的等长收缩期间，实现了对单根手指力量的同时且成比例的解码。研究评估了不同SNN配置，对比了基于生理运动单元脉冲序列和脉冲编码肌电信号两种输入模式，实现了高精度、低延迟的运动意图解码。","scd":null,"kp":["解码框架[手指力量解码]: 基于脉冲神经网络的高密度肌内微电极阵列框架","[解码效果]: 实现连续、低延迟且高精度的手指力量比例解码"]},{"i":37637,"as":"针对石墨烯气凝胶纳米结构易在干燥中受损的挑战，研究开发了一种结合焦耳热与真空相变工程的电热真空升华干燥法。该方法使干燥速率提升了417倍，且耗电量仅为传统冷冻干燥的0.6%。高温低压的处理环境不仅增强了碳水相互作用，还在大规模合成中完好保留了气凝胶超轻、高孔隙率的精密纳米网络结构，展现出极高的效率与能源利用率。","scd":null,"kp":["合成工艺[石墨烯气凝胶]: 结合快速焦耳热的电热真空升华干燥法","[工艺特征]: 精确、可扩展且能保留脆弱纳米结构的干燥策略"]},{"i":37638,"as":"研究发现在具有共振频率的三耦合振荡器系统中，通过三边形超网络基元（第三个节点调制另外两个节点的相互作用）的耦合作用，可以诱导出一种稳定的三相位锁定状态，而此时并未观察到成对锁定现象。通过利用范式转换和相位降维方法，研究解析推导出了特定耦合函数如何诱导这种“超锁定”现象，并得到了实验验证，揭示了超网络独特的同步机制。","scd":null,"kp":[]},{"i":37639,"as":"针对传统自组装单分子层（SAM）酸性头基导致倒置钙钛矿太阳能电池界面不均和电荷传输受限的问题，研究开发了一系列基于碱金属的膦酸盐（2PACz-M）。通过对基准分子进行头基功能化，实现了化学中性化和电子离域的界面。离子膦酸基团增强了π电子共轭，改善了能级排列并强化了与金属氧化物电极的化学配位，从而形成了均匀稳定的覆盖，大幅提升了电池效率与操作稳定性。","scd":null,"kp":["界面材料[倒置钙钛矿太阳能电池]: 基于碱金属的膦酸盐（2PACz-M）自组装单分子层","[技术优势]: 消除传统酸性头部基团带来的界面不均匀性，实现中性界面和协同电荷提取"]},{"i":37640,"as":"研究利用冷冻电镜、电生理学和细胞死亡实验，阐明了小分子Necrocide 1（NC1）特异性激活人类TRPM4通道的分子机制。NC1通过结合特定位点导致通道持续开放，引发钠离子大量流入细胞，触发钠超载坏死（NECSO）。研究不仅鉴定了激活通道的关键分子决定因素，还解释了小鼠TRPM4对NC1不敏感的原因，并精准定位了决定其物种特异性的具体氨基酸残基。","scd":null,"kp":[]},{"i":37641,"as":"研究提出一种利用建筑自身大固有质量来产生高阻尼的结构响应控制方法，无需像传统阻尼器那样增加配重或进行频率调谐。在针对一栋300米高原型建筑的弹性风洞测试中，这种内置阻尼系统在极小差异位移下实现了超过70%的峰值加速度降低和50%以上的基底弯矩减少。该方法将高层建筑从传统的静态刚性实体转化为利用运动提升性能的动态系统。","scd":null,"kp":["减振技术[高层建筑结构响应控制]: 自身质量调动机制","[技术特点]: 无需额外增加质量块及频率调谐，利用建筑固有质量产生高可靠阻尼且减少差异运动"]},{"i":37642,"as":"研究开发了一类能在光照环境下实现机械检测可视化延迟的近红外应力记忆发射器。通过能带工程合成了Ca(Sr)ZnOS:Yb3+/Pb2+晶体，并在981纳米波长处实现了持续摩擦发光。结合同构主体混合与预设的紫外充电，可以精确调控持续发光的强度和持续时间。该技术直接记录机械应力，实现了延迟冲击的可视化，避免了传统相机的计算密集型分析和预测误差。","scd":null,"kp":["应力记忆发光材料[机械检测]: Ca(Sr)ZnOS:Yb3+/Pb2+晶体","[检测特性]: 近红外应力记忆发射体，可在环境光下实现快速可视化的延迟撞击检测"]},{"i":37643,"as":"为解决高温下芳香族聚合物电容器因电荷传输导致性能衰减的问题，研究提出了严格的电子迁移锁定策略。通过将强路易斯酸三（五氟苯基）硼烷引入路易斯碱性聚醚酰亚胺中，利用配位作用、氢键等协同效应，有效锁定了分子内和分子间的电荷载体传输。该方法抑制了高温高场下的电荷迁移，成功突破了高温介电储能的瓶颈，大幅提升了电容器的高温性能。","scd":null,"kp":["改性策略[高温介电储能聚合物]: 严格的电子限制（抑制电荷载体传输）","[应用优势]: 克服芳香族聚合物在高温高场下链内和链间电荷传输导致的电容性能恶化"]},{"i":37644,"as":"研究开发了一种紧凑的超表面器件，能够在四维希尔伯特空间中生成任意自旋-轨道混合状态。该器件采用四原子单元结构，能够精确控制光波的复振幅、相位和偏振。为实现高效表征，研究还引入了一种基于庞加莱超球面的干涉测量方案。该技术不仅能轻松扩展至更高维度，还为提升光通信、量子技术及计量学领域的信息容量和鲁棒性提供了核心工具。","scd":null,"kp":["光学器件[高维自旋轨道态生成与操控]: 紧凑型超构表面","[器件功能]: 能够在高维希尔伯特空间中生成任意混合自旋-轨道态"]},{"i":37645,"as":"扩散型忆阻器通过利用类似生物动力学的离子漂移与扩散，在混沌边缘（EOC）实现离子调控。在百纳安培级别电流下，该器件表现出由Ridley熵产生最小化跃迁增强的急剧负微分电阻（NDR），并伴随噪声放大和自发振荡动力学特性，为高效信息处理提供了新途径。","scd":null,"kp":["器件机制[混沌边缘(EOC)运行]: 利用离子漂移和扩散的扩散型忆阻器","[技术优势]: 具有类生物动力学特征且避免了传统电热相变的高功耗问题，实现节能信息处理"]},{"i":37646,"as":"分子形状决定了联芳基和低聚芳基等骨架的结构性质与分子间相互作用。针对目前高度缺乏合成双邻位取代类球形联芳基支架的方法，研究开发了一种基于环状砜环重塑的区域选择性亲核/亲电试剂偶联介导合成策略，实现了具有三维立体多样性的优势骨架的高效合成。","scd":null,"kp":["合成方法[联芳基和寡芳基骨架]: 环状砜环重构导向分子形状多样性的合成策略","[合成效果]: 突破传统线性及圆盘状结构限制，增加分子的三维空间形状多样性"]},{"i":37647,"as":"受自然界微区室化酶级联反应启发，研究开发了一种基于Pickering乳液的活细胞生物催化平台。通过将油基光催化剂接枝到过表达酶的大肠杆菌表面构建两亲性“超细菌”，使其在水油界面自组装。该平台有效加速了化学酶和多酶级联反应，反应速率比常规方法提升达45倍。","scd":null,"kp":["生物催化平台[流水线式生物合成]: 皮克林乳液活细胞催化平台","[工艺特点]: 利用可调超分子化学将光催化剂接枝到过表达酶的细胞表面，解决酶不相容性和底物转移效率低的问题"]},{"i":37648,"as":"为解决深紫外探测兼容性差的问题，研究设计制备了嵌入Cs3Cu2I5纳米晶的多带隙复合玻璃器件。通过Gd3+离子桥接宿主玻璃与纳米晶的带隙失配，实现了高效载流子级联冷却，将深紫外光子转换为可见光。该器件能量转移效率接近100%，光谱响应范围覆盖180至350纳米的超宽带紫外区域。","scd":null,"kp":["带隙工程[透明玻璃基宽带紫外探测器]: Gd3+离子桥接带隙失配","光谱响应[玻璃复合材料多带隙设计]: 克服深紫外波长兼容性差的问题实现超宽带"]},{"i":37649,"as":"Ascona B-DNA联盟的14个研究小组利用原子级分子动力学模拟，对2080种DNA六聚体进行了深入表征。在显式溶剂中进行了超过10微秒的重复模拟，生成了0.25 PB的数据，成功捕获了碱基对层级长达0.1秒的动力学特征，揭示了包含罕见瞬态的DNA序列依赖性物理隐藏密码。","scd":null,"kp":["模拟时长[DNA双链寡聚体分子动力学]: 至少10微秒","数据规模[208种DNA六聚体特征毫秒级集合]: 0.25 PB"]},{"i":37650,"as":"沿海开垦将自然潮滩生态系统转变为陆地景观，深刻影响碳动态。研究指出，开垦引起土壤脱盐和营养富集，使得各阶段土壤有机碳显著增加，且以矿物结合有机碳为主，稳定性不断增强；而无机碳在开垦影响下保持相对稳定状态。土地利用方式对土壤碳组分具有显著的调节作用。","scd":null,"kp":["土壤理化性质[沿海围垦自然演替]: 逐渐脱盐与表层脱碱","碳动力学[围垦土地利用方式]: 有机碳与无机碳呈现分歧响应"]},{"i":37651,"as":"研究利用OSCAR简化复杂地球系统模型，基于150种情景预测了21世纪各国土地利用变化（LULCC）的碳排放轨迹。森林砍伐和再生是排放变化的主导因素。若2030年停止森林砍伐，到2100年可移除约300亿亿吨碳；而实现净森林面积平衡仍会排放4至9拍吨碳。预计中国和印尼将成为最强碳汇。","scd":null,"kp":["碳排放轨迹[150种社会经济情景下21世纪国家LULCC]: 预测至2100年","气候缓解[2030年前终止总森林砍伐]: 产生巨大且持久的碳减排效益"]},{"i":37652,"as":"全球对矿产的需求加剧了保护区森林的丧失。评估显示，2001至2020年间，约11%的采矿导致森林损失发生在保护区内，且2016至2020年该比例上升至19%。此外，采矿的影响延伸至保护区边界之外，其外围10公里缓冲区内的森林损失量约是保护区内部的三倍，高达4113平方公里。","scd":null,"kp":["森林损失[全球采矿活动（2001-2020）]: 约11%（~1372平方公里）发生在保护区","保护区占比[采矿致森林损失（2016-2020）]: 上升至约19%"]},{"i":37653,"as":"视觉概括能力要求将多样输入映射为统一推断并转化为多种行为。研究记录了两只猕猴在执行三维物体曲率估计及不同眼动任务时的视觉皮层神经元活动。结果显示，V1和V4区域存在一种通用的、基于形状的稳定神经读取机制来解释感知判断，而非依赖特定形状策略，V4群体活动还编码了即将发生的动作。","scd":null,"kp":[]},{"i":37654,"as":"刺参（Oplopanax elatus）能够积累达玛二烯醇，这是RK型人参皂苷的前体骨架。结合基因组测序与生化分析，研究鉴定出特化的达玛二烯醇合酶OeOSC14，该酶由祖先多功能萜烯合酶复制与新功能化演变而来。其中单个N260Y氨基酸替换即可使其逆转为多功能酶。该研究为重建RK型人参皂苷生物合成提供了关键基础。","scd":null,"kp":["关键酶[刺参合成RK型人参皂苷前提]: 达玛二烯醇合酶（通过OeOSC14进化与新功能化）"]},{"i":37655,"as":"三维全息显示技术中的传统计算机生成全息（CGH）算法在倾斜角谱表示、离焦模糊处理及计算资源消耗上存在局限。研究提出一种基于网格表示和学习赋能的新型全息图合成框架，克服了现有基于层、点云或启发式编码算法的缺点，旨在为三维全息显示提供更准确且高效的计算方案。","scd":null,"kp":[]},{"i":37656,"as":"研究展示了一种2D/3D范德华钙钛矿异质结构的相干外延生长策略。该方法能够实现原子级尖锐的界面，直接观察有序配体钝化，并成功制备出具有光学活性的螺旋结构。该技术可扩展至宏观单晶薄膜，为先进光电器件研发建立了多功能平台。","scd":null,"kp":[]},{"i":37657,"as":"标准宇宙学模型假设宇宙在足够大的尺度上是统计均匀和各向同性的。研究通过星系红移巡天数据绘制了宇宙网结构，以此观测检验这一宇宙学原理。研究探讨了在非线性结构形成阶段之外，宇宙大尺度结构与空洞的复杂网络是否包含不均匀和各向异性的特征，从而对现有宇宙学模型提出挑战。","scd":null,"kp":[]},{"i":37658,"as":"研究构建了Carnegie第6阶段（受孕后约13-14天）人类胚胎的高分辨率空间转录组图谱。此时原条尚未可见，也未检测到中胚层/内胚层祖细胞。研究鉴定了前内脏内胚层样下胚层群体，揭示了上胚层向羊膜、原条及轴向中胚层的三大发育轨迹。研究结果进一步挑战了现有的血液形成范式。","scd":null,"kp":[]},{"i":37659,"as":"为探究尼安德特人群体间的连通性，研究从比利时和法国的10个考古遗址中提取了27名生活在约5.25万年前的尼安德特人的遗传数据。基因组分析表明，这些个体之间的亲缘关系比与其他同时代的晚期尼安德特人更为密切。研究还包括了一名来自比利时戈耶的4.5万年前的个体高覆盖率基因组。","scd":null,"kp":[]},{"i":37660,"as":"黑洞视界以旋转频率和表面引力为特征，落入物体的发射信号会因引力红移以特定速率呈指数衰减。理论研究预测双黑洞合并产生的引力波包含合并残差视界属性的“直接波”印记。研究在引力波事件GW250114中报告了观测到这种以2倍旋转频率振荡并以表面引力特征速率衰减的直接波证据。","scd":null,"kp":[]},{"i":37661,"as":"环形激光陀螺仪（RLG）在低转速下存在阻碍其应用的“锁相现象”。现有的机械抖动或磁光非互易性消除技术依赖外部组件，限制了设备小型化。研究提出一种自偏置方法，在不插入任何元件的氦氖RLG中，通过手性自发对称性破缺和非线性频率牵引成功打破了锁相极限。","scd":null,"kp":["技术突破[环形激光陀螺仪突破闭锁效应限制]: 采用手激光技术替代外部线圈等机械偏转或磁光非互易技术"]},{"i":37662,"as":"深度学习在设计结合小分子的蛋白质时面临序列、结构和配体构型同步优化的挑战。研究提出一种迭代设计算法，将配体感知序列工程消息传递神经网络（LASErMPNN）与结构预测器相结合，实现了从小分子出发的高精度零样本（从零开始）结合蛋白设计，克服了现有深度学习算法的局限性。","scd":null,"kp":[]},{"i":37663,"as":"研究分析了超1000个人类样本的深度蛋白质组学、转录组学和基因组学数据，以探究由替代翻译引起的氨基酸取代的作用。分析鉴定出8746个独特的蛋白质取代，部分取代具有强烈的组织类型和癌症特异性。值得注意的是，在数百个基因中，替代翻译产生的蛋白质丰度高于其经典翻译的对应物。","scd":null,"kp":["蛋白质变异[1000+人类样本替代翻译]: 鉴定出8746种导致稳定且丰富蛋白质的独特替代"]},{"i":37664,"as":"链霉菌属编码的高度保守生物合成巨型簇能够产生四个结构独特的天然产物家族以及链霉亲和素。这些代谢物通过包括生物素代谢抑制在内的互补机制协同作用。该发现揭示了微生物可编码协调的多代谢物系统，突破了以往将生物合成基因簇视为单一活性分子来源的传统认知。","scd":null,"kp":["合成架构[链霉菌抗生素协同多代谢物系统]: 编码高度保守的生物合成巨簇"]},{"i":37665,"as":"","scd":null,"kp":[]},{"i":37666,"as":"通过激光照射堆叠的二维材料层，可在层间产生超过100开尔文的温差。该技术利用激光控制实现了超薄结构中热流的开启与调控。","scd":null,"kp":["温差产生[2D材料堆叠层激光照射]: 可创造100开尔文以上的温差以实现热流控制"]},{"i":37667,"as":"从尼安德特人骨骼残骸中提取的大量基因组数据，推翻了科学界先前的一些假设，并为研究这一古人类群体的种群动态和消亡原因提出了新的问题。","scd":null,"kp":[]},{"i":37668,"as":"","scd":null,"kp":[]},{"i":37669,"as":"链霉菌可产生包含四种抗生素化合物的混合物。这四种化合物通过协同作用，同时攻击细菌必需代谢途径的多个关键靶点，从而有效杀灭具有耐药性的超级细菌。","scd":null,"kp":["抗菌机制[链霉菌产生的抗生素组合]: 靶向单一必需代谢途径的多个部分","有效成分数量[抗生素组合]: 四种化合物"]},{"i":37670,"as":"无需加热或选择性涂层，廉价的多孔聚合物膜即可实现原油分离。原油中的重质碳氢化合物在膜孔内自组装，形成宽度小于2纳米的通道。长链碳氢化合物沉积在孔壁上使通道变窄，仅允许较小分子通过。该方法成功将产出物富集为轻质石蜡烃，且能耗和二氧化碳排放量均比传统蒸馏法降低30%。","scd":null,"kp":["孔道尺寸[原油自分离多孔聚合物膜]: 小于2纳米","节能降碳率[无热原原油膜分离vs传统蒸馏]: 能耗和二氧化碳排放减少30%","分离机制[无热原原油多孔聚合物膜]: 重质烃自组装形成亚2纳米通道且无需选择性涂层"]},{"i":37671,"as":"β-抑制蛋白（β-arrestins）负责调节G蛋白偶联受体（GPCR）超家族的信号传导。目前已发现三种小分子，它们通过直接结合β-抑制蛋白来阻断其与GPCR蛋白的结合。这些小分子抑制剂是探明该类蛋白生物学功能的首批化学工具，为开发针对特定通路的GPCR靶向疗法开辟了新途径。","scd":null,"kp":["抑制剂数量[β-抑制蛋白小分子]: 三种","抑制剂作用机制[小分子靶向β-抑制蛋白]: 阻断β-抑制蛋白与GPCR蛋白的结合","应用前景[β-抑制蛋白小分子抑制剂]: 首个用于探索其生物学功能并开启转导靶向GPCR疗法的化学工具"]},{"i":37672,"as":"","scd":null,"kp":[]},{"i":37673,"as":"科研人员结合卫星图像与机器学习技术，成功绘制了首张全球海草生态系统综合分布图。这一成果为海草草甸的生态保护工作提供了重要的数据支持与助力。","scd":null,"kp":["技术方法[海草生态系统全球制图]: 结合卫星图像与机器学习"]},{"i":37674,"as":"二维材料科学面临的主要挑战不在于缺乏潜在的发展可能，而在于缺乏系统性的实验记录与组织。将已合成材料、制备方法以及它们与计算预测之间的关联整合起来，将有助于塑造和指导该领域未来的发现。","scd":null,"kp":["发展瓶颈[二维材料科学]: 缺乏将已合成材料、制备工艺与计算预测关联的结构化记忆库"]},{"i":37675,"as":"土壤抗生素抗性基因（ARGs）是全球健康的新威胁。基于2009至2022年间2243份中国宏基因组样本，研究构建了中国土壤ARGs的时空分布图谱。与2015年前相比，2016年至2020年国家抗微生物药物耐药（AMR）控制政策实施期间，农田总ARGs和一级ARGs丰度分别显著下降52.6%和77.0%。全球对比显示，相似的农业压力导致各区域农田抗性组趋于同化。","scd":null,"kp":["样本数据量[中国土壤宏基因组]: 2,243个","时间跨度[中国土壤抗生素抗性基因时空分布]: 14年（2009-2022年）","总ARGs相对丰度降幅[2015年后vs 2015年前农田土壤]: 下降52.6%","Rank I ARGs相对丰度降幅[2015年后vs 2015年前农田土壤]: 下降77.0%"]},{"i":37676,"as":"太阳极区冕洞中快速太阳风的加速和加热机制一直是空间物理学难题。利用太阳轨道飞行器的高分辨率极紫外成像数据，研究团队在太阳极区日冕羽流中识别出此前未被观测到的高频磁流体动力学（MHD）波。分析表明，超过三分之一的传播扭折波周期短于100秒，这一携带巨大能量的高频波群的发现弥补了理论与观测之间的关键空白。","scd":null,"kp":["观测对象[太阳极区日冕]: 具有显著能量的高频磁流体力学波"]},{"i":37677,"as":"研究构建了基于吲哚[2,3-c]咔唑中心构建块的新型四硼多重共振（MR）框架ICZ4B。该结构采用邻位B-π-B模式，通过一步高效四重硼化反应合成。ICZ4B表现出明亮的黄色发光（半峰宽仅为24纳米），并实现了4.7×10^4 s^-1的逆向系间窜越（RISC）速率。基于该材料的非敏化OLED器件实现了高达36%的外部量子效率。","scd":null,"kp":["分子骨架[新型高効黄光窄带OLED]: 采用邻位B-π-B模式的四硼MR骨架","核心构建单元[ICZ4B分子框架]: 吲哚[2,3-c]咔唑"]},{"i":37678,"as":"","scd":null,"kp":[]},{"i":37679,"as":"研究开发了一种含有烷基侧链的聚双芴基阴离子交换膜（PBFA-QA）。在零间隙CO2电还原电解槽中，该膜实现了331.7 mA cm^-2的CO局部电流密度，显著优于商用膜。在200 mA cm^-2的电流密度下，该电解槽稳定运行200小时，法拉第效率保持在92.3%以上，且未出现阴极水浸或盐沉淀现象。","scd":null,"kp":["CO部分电流密度[PBFA-QA阴离子交换膜]: 331.7 mA cm−2","运行稳定性[200 mA cm−2电流密度下的PBFA-QA电池]: 稳定运行200小时","FECO[200 mA cm−2下运行200小时]: 维持在92.3%以上","膜材料特点[CO2RR零间隙电解槽]: 含有烷基链的聚(双芴)基阴离子交换膜"]},{"i":37680,"as":"Erdil等人的研究表明，钙钛矿太阳能电池在长期户外运行后会同时出现电极腐蚀、边缘特定形态图案和相分离现象。通过使用光强度和电偏压作为关键应力源，该研究在实验室成功复现了这些空间上的非均匀降解模式，将实际场地退化与加速老化测试联系起来，指明了针对特定机制的测试方向。","scd":null,"kp":["降解模式[钙钛矿太阳能电池户外长期老化]: 电极腐蚀、边缘图案和相分离共存","加速老化应力源[模拟钙钛矿电池户外降解]: 光强和电偏压"]},{"i":37681,"as":"土壤细菌能够合成由多种分子组成的混合物，这些分子通过协同作用有效抑制微生物病原体的生长。这一机制为应对抗生素耐药性感染提供了新的治疗策略。","scd":null,"kp":["抗生素混合物[土壤细菌]: 由“巨型基因簇”协同合成的复合分子混合物","作用机制[协同抑菌]: 分子间协同抑制微生物病原体生长"]},{"i":37682,"as":"核苷修饰的mRNA-脂质纳米颗粒（LNP）疫苗通过引发强大的先天和适应性免疫反应，对重症COVID-19提供了高度保护。尽管近期研究揭示了其驱动免疫保护的部分机制，但关于免疫系统如何感知LNP并发挥佐剂活性的关键知识仍存在空白，深入探究这些机制对开发兼具良好免疫原性和耐受性的下一代mRNA疫苗至关重要。","scd":null,"kp":["疫苗平台[核苷酸修饰的mRNA-脂质纳米颗粒(mRNA-LNP)]: 具有极高的重症COVID-19保护效力","免疫机制[mRNA-LNP疫苗]: 驱动强大且协调的先天性和适应性免疫反应"]},{"i":37683,"as":"现有的数字相机和显示器像素只能单一地检测或发射光强度。为突破双向光场控制的限制，研究团队基于傅里叶光学开发了一种由微型衍射元件组成的通用平台。该平台利用等离子体表面波，首次实现了在单个像素上同时具备传感和生成光波前功能，并能够对光波的振幅、相位和偏振进行完全控制。","scd":null,"kp":["多功能像素[傅里叶像素]: 能够以完全协调的方式同时感知并生成光学波前"]},{"i":37684,"as":"医疗人工智能模型在提升诊断质量的同时，面临着患者信息隐私泄露的风险。研究针对医疗诊断AI模型进行了患者级别的隐私审计，重点考察了成员推理攻击（MIAs），即推断特定个人数据是否被用于模型训练。研究强调了理解提供多份相似记录的个体患者所面临的差异化隐私风险的重要性。","scd":null,"kp":["[医疗AI模型]: 个体患者由于向训练集贡献多条相似记录，面临着不均等且容易被聚合攻击量化的隐私泄露风险"]},{"i":37685,"as":"研究开发了一种可溶液加工的二维层状铜铟硒（CuIn5Se8）半导体。基于空气稳定的溶液油墨配方，可在环境空气中沉积4英寸大小的薄膜。通过研究可逆水吸附过程对电学性能的影响，研究采用适度的退火步骤清除了表面水分子。最终制备的晶圆级二维半导体展现出极高的载流子迁移率，解决了传统溶液法制备材料电学性能低的问题。","scd":null,"kp":["薄膜形态[可溶液加工的二维半导体]: 晶圆级二维层状硒化铜铟(CuIn5Se8)","核心特性[空气稳定溶液油墨]: 兼具高迁移率值与大面积低成本制造的潜力"]},{"i":37686,"as":"随着晶体管横向微缩停滞、三维堆叠技术发展以及二维纳米材料的引入，栅极介电层的可靠性评估变得尤为关键。介电层必须承受高电场并阻止电荷传输以确保器件正常工作。该研究探讨了如何以符合工业标准的方式评估介电材料的可靠性，填补了学术界现有测试方法与工业实际需求之间的差距。","scd":null,"kp":["核心要求[新型晶体管栅极介电材料]: 必须承受高电场并有效阻断电荷传输以保证器件正常工作"]},{"i":37687,"as":"","scd":null,"kp":[]},{"i":37688,"as":"","scd":null,"kp":[]},{"i":37689,"as":"","scd":null,"kp":[]},{"i":37690,"as":"全球混凝土产量极高，约为钢铁的20倍、木材的40倍，主要依赖本地资源。巨大的资源消耗引发局部资源短缺及生态与健康问题。研究确定了全球混凝土生产消耗的矿物、能源和水资源。结果显示，2019年全球直接用于制造混凝土和硅酸盐水泥产品的这三类资源总量达300亿吨，若计入资源损耗，该数值将更高。","scd":null,"kp":["产量对比[全球混凝土]: 产量是钢材的约20倍，是实木制品的约40倍"]},{"i":37691,"as":"β-阻滞蛋白是调控G蛋白偶联受体(GPCR)信号传导的关键多功能调节因子。目前针对GPCR的药理学研究较多，但一直缺乏直接调节β-阻滞蛋白活性的化学工具。研究筛选出可选择性与β-阻滞蛋白结合的小分子抑制剂。这些抑制剂能够阻断β-阻滞蛋白与激活态GPCR的结合，从而削弱受体的脱敏、内吞作用及依赖于β-阻滞蛋白的生理反应。","scd":null,"kp":["调节靶点[β-抑制蛋白]: 鉴定出可选择性调控G蛋白偶联受体(GPCR)信号传导中β-抑制蛋白活性的小分子抑制剂"]},{"i":37692,"as":"研究通过利用严重的晶格畸变，成功制备出兼具超高强度和延展性的马氏体钢。这种晶格畸变能够激活马氏体内部的双晶作为塑性载体，从而改善了传统超高强度钢的力学性能。","scd":null,"kp":["核心特征[超高强韧马氏体钢]: 利用晶格畸变激发形变孪晶作为塑性载体，实现超强与高延展性的结合"]},{"i":37693,"as":"","scd":null,"kp":[]},{"i":37694,"as":"大多数材料的圆二色性通常较弱且光谱范围窄。研究在磁场强制的外尔半金属Mn(Bi,Sb)2Te4中发现了由极端粒子-空穴对称性破缺驱动的巨型红外圆二色性。螺旋度分辨磁红外光谱显示，其圆二色性超过3000毫度（约130毫度/纳米），且在6至13微米的宽广光谱范围内具有超过1度的响应。这种光学共振通过第二类外尔色散的朗道能级固有的强能带嵌套效应得到显著增强。","scd":null,"kp":["核心机制[磁场强制外尔半导体Mn(Bi,Sb)2Te4]: 极端的粒子-空穴对称性破缺","物理效应[中远红外波段]: 产生巨大且宽频带的圆二色性（左右旋圆偏振光差异吸收）"]},{"i":37695,"as":"","scd":null,"kp":[]},{"i":37696,"as":"","scd":null,"kp":[]},{"i":37697,"as":"","scd":null,"kp":[]},{"i":37698,"as":"研究揭示了人工智能训练数据存在易受攻击的漏洞，可能导致患者的医疗记录等敏感信息被泄露。分析指出，在AI训练数据中代表性不足的群体面临更为严重的身份识别风险。此外，同期科学新闻还报道了关于宇宙均匀度低于原有假设的最新观测证据。","scd":null,"kp":["[AI模型训练数据泄露]: 训练数据中代表性不足的群体面临更严重的身份识别风险"]},{"i":37699,"as":"淋病奈瑟菌已对目前大多数治疗用抗生素产生抗药性。为应对这一临床挑战，研究人员利用机器学习技术进行药物筛选，成功发现并鉴定出具有潜力的新型抗生素疗法，为治疗耐药性淋病感染提供了新的解决方案。","scd":null,"kp":["[机器学习药物筛选]: 发现能够对抗耐药性淋病的新潜在抗生素疗法"]},{"i":37700,"as":"","scd":null,"kp":[]},{"i":37701,"as":"","scd":null,"kp":[]},{"i":37702,"as":"全球超7亿人面临热量饥饿，超20亿人遭受微量营养素缺乏的“隐性饥饿”。为实现零饥饿，农业需同步实现增产、提升维矿物质密度（多重生物强化）及增强气候变化适应力。气候变化已被证实会降低农作物多种微量营养素密度。研究指出，CRISPR-Cas等基因组编辑技术提供了高精度的工具，能够在当前气候变化的背景下有效改良作物的基因组，从而提升作物的营养价值。","scd":null,"kp":["[全球零饥饿农业目标]: 增加产量、提高维生素和矿物质密度以维持每日推荐摄入量、增强气候变化适应性"]},{"i":37703,"as":"肝低密度脂蛋白受体(LDLR)的代谢是决定胆固醇稳态的关键因素。研究揭示了一条由Ral GTP酶调控的新路径，将细胞外胆固醇信号与控制LDLR更新的胞内转运机制相联系。长期高膳食胆固醇摄入会通过增加RAS活性激活Ral蛋白，将LDLR导向溶酶体降解并抑制其循环，且此过程不依赖转录调节或PCSK9。在肝细胞中通过RalGAPB基因缺失持续激活Ral，会直接导致LDLR水平降低。","scd":null,"kp":[]},{"i":37704,"as":"海草生态系统对沿海生物多样性及气候缓解至关重要，但缺乏精细测绘。研究基于475万张Sentinel-2卫星影像，利用深度学习分类器，首次绘制了全球浅海清澈水域10米空间分辨率的海草分布及变化地图。结果确认全球海草总面积为148,506平方公里（潮间带5,961平方公里，潮下带142,545平方公里），其中69%的区域已获得详实分析数据。","scd":null,"kp":[]},{"i":37705,"as":"海洋浮游植物产生的二甲基硫(DMS)氧化后生成硫酸(SA)和甲磺酸(MSA)。在低于零下10摄氏度的大气条件下，MSA能够与氨气(NH3)协同发生成核作用，成核率与SA-NH3相当。MSA与SA在低温下表现出协同效应，与NH3形成多酸分子团簇。即使在氨气浓度极低的环境中，MSA也能有效驱动新颗粒的生成与生长，促使其成为云凝结核(CCN)。","scd":null,"kp":[]},{"i":37706,"as":"镍催化交叉偶联反应在化学合成中至关重要，但针对镍(II)催化剂转金属化步骤的速率数据因分析困难而十分匮乏。为此，研究开发了一种基于核磁共振(NMR)波谱的简便分析方法。该方法通过生成一种不饱和偶联产物并结合到镍(0)上，有效防止了其与残留镍(II)的歧化作用以及有害镍(I)物质的生成，为研究反应机制和反应设计提供了可靠的速率与机制分析手段。","scd":null,"kp":["[Ni(II)催化转金属化反应动力学分析]: 采用核磁共振(NMR)光谱的用户友好型分析方法"]},{"i":37707,"as":"将硝酸根电催化还原为氨是一种可持续的废物转化技术。然而，真实废水中硝酸根浓度低且存在多种干扰离子，严重影响催化剂的选择性与稳定性。研究首次提出采用脉冲设计技术，成功在真实稀释废水中实现了高效的氨电合成。以石墨烯生产厂的稀释废水（约5mM硝酸根及多种干扰离子）为实验对象，该工艺展现了优异的催化效能。","scd":null,"kp":["[真实废水中硝酸盐电还原制氨]: 脉冲设计策略有效克服低硝酸盐浓度及干扰离子的影响，实现高效催化选择性和稳定性"]},{"i":37708,"as":"生物正交反应（如SPAAC）在复杂生物环境中标记大分子具有优势，但其动力学缓慢且需洗脱多余荧光探针。为解决此问题，研究开发了一类由光触发、反应快速且具有荧光发生性的噻吩基环炔烃探针。该探针能够在无需洗脱的条件下，对标记有1,3-偶极体的分子进行精准的生物正交荧光标记，有效推动了低浓度目标分子的实时成像应用。","scd":null,"kp":["[无洗涤条件下的生物正交荧光标记]: 开发光触发、快速且具有荧光性的噻吩基环炔烃探针以克服SPAAC动力学缓慢的问题"]},{"i":37709,"as":"感染预后的性别差异机制尚未明确。以果蝇肠道感染为模型的研究表明，肠道氧化还原过程的性别差异导致雌性更易受感染。雌性无法克服病原体诱导的氧化应激，引发排便受阻、病原体持续存在及宿主死亡。相反，雄性果蝇表现出增强的碳水化合物代谢和磷酸戊糖途径活性，这是一种关键的抗氧化防御系统，使雄性能够抵御氧化应激引发的排便受阻并成功清除病原体。","scd":null,"kp":[]},{"i":37710,"as":"新皮层神经元和回路能够放大对意外刺激变化的反应（即偏差检测，DD）。研究提出了一种新机制，认为DD并非专属于特定细胞类型或特定脑区，而是由局部网络层面的内在交互作用自发产生的。这种偏差驱动的神经动力学由具有基础抑制性连接基序的兴奋性和抑制性神经元集群生成，主要表现为在正向选择（去）抑制的调节下，相互连接的神经表征之间产生竞争性抑制。","scd":null,"kp":[]},{"i":37711,"as":"植物不对称细胞分裂依赖于前期带(PPB)的形成，该过程对细胞壁的机械性质高度敏感。在玉米气孔发育过程中，研究人员鉴定出一种类受体蛋白KAI1。KAI1作为气孔副卫细胞形成的主调节因子，通过机械化学信号控制副卫母细胞的分裂面取向：它通过果胶相互作用感知细胞壁的刚性，进而调控PPB的准确定位与不对称分裂。","scd":null,"kp":[]},{"i":37712,"as":"SARS-CoV-2等正冠状病毒的基因组具有高度灵活性。研究系统性地探索了SARS-CoV-2的额外基因编码能力，通过在其基因组各个基因间区插入报告基因，绘制了完整的额外基因表达图谱。研究成功筛选出一个能够稳定表达外源基因且保持野生型病毒表型的基因组位点。基于此发现，研究团队开发了一系列表达荧光蛋白的重组病毒，构建了可用于体外和体内应用研究的病毒载体平台。","scd":null,"kp":[]},{"i":37713,"as":"","scd":null,"kp":[]},{"i":37714,"as":"","scd":null,"kp":[]},{"i":37715,"as":"","scd":null,"kp":[]},{"i":37716,"as":"","scd":null,"kp":[]},{"i":37717,"as":"","scd":null,"kp":[]},{"i":37718,"as":"","scd":null,"kp":[]},{"i":37719,"as":"","scd":null,"kp":[]},{"i":37720,"as":"研究利用深度学习从13,254张多品种犬类图像中，使用ResNet和ViT模型自动提取了256维图像特征嵌入。经过UMAP降维后，结合品种级别的基因型数据进行了全基因组关联研究(GWAS)。该方法有效克服了传统表型分析难以捕捉复杂视觉特征的缺陷，成功识别出15个此前已报道的基因。","scd":null,"kp":["[全基因组关联分析图像特征嵌入]: 利用包含13254张多品种犬类图像的数据集，结合ResNet和ViT模型深度学习自动提取复杂表型特征"]},{"i":37721,"as":"环境条件下氮环结构（如叠氮阴离子）晶体的高能不稳定性是储能材料领域的关键挑战。基于第一性原理结构研究，报告了一种在环境条件下稳定的聚氮晶体Li4(N5)2。在其晶胞中，锂原子向N5环发生电子转移并占据其离域轨道，从而形成稳定的结构，为高能量密度材料的开发提供了新途径。","scd":null,"kp":["[环境条件下的稳定超原子氮环晶体]: 成功合成环境条件下稳定的聚氮晶体Li4(N5)"]},{"i":37722,"as":"研究开发了一种无线智能隐形眼镜，能够实时、无创地监测泪液尿酸(TUA)，作为血液尿酸检测的替代方案。通过在人体（含高尿酸血症和痛风患者）和兔子中进行相关性分析，验证了设备的有效性。基于TUA与血清尿酸(SUA)之间强烈的线性关系，开发了回归模型，实现了个性化尿酸水平的预测。","scd":null,"kp":["[个性化无创尿酸预测]: 基于无线智能隐形眼镜实时监测泪液尿酸(TUA)构建数字孪生模型，作为传统血液尿酸(SUA)检测的替代方案"]},{"i":37723,"as":"","scd":null,"kp":[]},{"i":37724,"as":"受固氮酶启发，研究设计了单原子铁掺杂氧化钨(WO3)亚纳米线作为仿生动态集成催化平台，用于光电化学合成氨。扭曲晶格和不对称位点形成了动态响应催化中心，光诱导的价态-晶格振荡驱动电子离域，改变了氮气的常规吸附模式和反应路径，有效克服了顽固的N≡N键和竞争性界面反应动力学的限制。","scd":null,"kp":["[仿生光电化学合成氨催化剂]: 单原子铁掺杂氧化钨(WO3)亚纳米线（受固氮酶启发）"]},{"i":37725,"as":"","scd":null,"kp":[]},{"i":37726,"as":"","scd":null,"kp":[]},{"i":37727,"as":"","scd":null,"kp":[]},{"i":37728,"as":"实现二维亚铁磁体的多步磁化切换对高密度存储器件意义重大。研究成功合成了具有室温强亚铁磁性的二维Fe0.875S(1-x)Sex合金家族。通过调整硫族元素的比例，该材料的关键磁性和电学性质得到了有效调控，克服了现有二维铁磁体居里温度低且缺乏可调多磁态的阻碍。","scd":null,"kp":["磁状态[二维亚铁磁体]: 可调多步磁化翻转","居里温度[现有二维亚铁磁体]: 偏低（限制应用）","[材料体系]: 成功合成室温磁性二维金属亚铁磁体家族"]},{"i":37729,"as":"现有水凝胶在生物粘附、抗纤维化和刚度之间存在固有权衡。研究通过引入聚合物刷涂层，开发出一种模块化水凝胶系统，实现了功能性和刚度的独立控制。通过调整涂层化学、厚度和网络拓扑，该系统在软组织全刚度范围内保持了一致的生物粘附（约100 J/m²）和抗纤维化特性，实现了稳定的组织粘附。","scd":null,"kp":["水凝胶性能[传统体系]: 功能与刚度存在内在权衡限制","[水凝胶改性]: 引入聚合物刷涂层实现粘附、纤维化与刚度的独立控制"]},{"i":37730,"as":"","scd":null,"kp":[]},{"i":37731,"as":"磁场通常通过破坏库珀对抑制超导性，但在特定条件下也可稳定超导态。研究在(110)取向的LaTiO3-KTaO3外延异质界面观测到了重入超导现象。这是在莫尔石墨烯之外，首次在二维系统中发现这种与磁场相关的反直觉现象，暗示了该体系中存在非常规的超导机制。","scd":null,"kp":["磁场效应[二维材料]: 首次探索并实现磁场稳定非常规超导电性（再入超导现象）"]},{"i":37732,"as":"纳米受限水的反应活性备受争议。研究利用机器学习势函数结合增强采样分子动力学，以石墨烯和六方氮化硼为模型，探究了二维狭缝孔和纳米液滴中水的解离行为。结果表明，水的反应性对密度、几何形状和表面化学极其敏感。尽管复杂，化学势和界面相互作用共同主导了纳米尺度下水的解离过程。","scd":null,"kp":["水分子解离行为[纳米限域环境]: 表现出增强或抑制的双向反应性","[研究方法]: 采用第一性原理精度训练的机器学习势函数结合增强采样分子动力学"]},{"i":37733,"as":"从单一前体构建三维多环骨架是有机合成的长期挑战。受海洋天然产物生物合成途径启发，研究通过酸触发的Dieckmann型环化级联反应，从特定前体简洁仿生合成了目标产物。在密度泛函理论(DFT)计算指导下，进一步利用光诱导骨架重排机制，高效生成了难以获取的多环结构，实现了复杂骨架的多样化构建。","scd":null,"kp":["[有机合成策略]: 仿生与光化学重塑策略构建三维多环骨架","[关键化学反应]: 酸触发的狄克曼型环化级联反应"]},{"i":37734,"as":"","scd":null,"kp":[]},{"i":37735,"as":"研究发现了一个以GLK为中心的分子模块调控水稻光合作用和产量。OsGLK1和OsGLK2在光合作用调控中起部分冗余作用，双突变体致死，单突变体出现叶片褪色和白穗。转录组测序表明OsGLK调控碳水化合物代谢和光合作用相关基因表达，过表达OsGLK1影响水稻光合作用和产量。","scd":null,"kp":["植物表型[Osglk1 Osglk2双突变体]: 幼苗致死","植物表型[Osglk2单突变体]: 叶片褪色且穗部白化","分子机制[OsGLK1/2-DGP1/2/3]: 形成反馈调节模块控制水稻光合作用与产量"]},{"i":37736,"as":"","scd":null,"kp":[]},{"i":37737,"as":"","scd":null,"kp":[]},{"i":37738,"as":"","scd":null,"kp":[]},{"i":37739,"as":"复合固体电解质在固态电池中具有潜力，但石榴石型LLZTO表面的碳酸锂钝化层导致界面相容性差。为此，研究通过化学转化方法处理LLZTO表面钝化层，构建了多氢键桥接的复合固体电解质，实现了连续的锂离子传输路径，有效解决了陶瓷颗粒分布不均和高含量下离子传输中断的问题。","scd":null,"kp":["成分[石榴石型复合固态电解质]: Li6.4La3Zr1.7Ta0.3O12","界面缺陷[石榴石型固态电解质]: 表面存在Li2CO3钝化层导致相容性差","[固态电解质改性]: 构建多氢键桥连网络以形成连续的Li+传输路径"]},{"i":37740,"as":"盐胁迫下植物根部富含假单胞菌，有助于提升大豆的耐盐性。这些假单胞菌携带钠离子转运体等独特基因组特征。实验表明，从盐胁迫植物中分离的假单胞菌能稳固定殖于大豆根部，通过增强植物木质素生物合成介导耐盐性，在温室和田间条件下均显著提高了大豆的耐盐能力。","scd":null,"kp":["耐盐机制[假单胞菌辅助大豆]: 通过增强植物木质素生物合成促进盐胁迫适应","[微生物群落特征]: 盐胁迫下植物根部高度富集具有高盐耐受基因特征的假单胞菌"]},{"i":37741,"as":"为解决长链DNA数据存储稳定性差的问题，研究提出长链异种核酸-环状单链DNA（XNA-cssDNA）混合策略。在极端条件下筛选出2'-氟阿拉伯糖核酸（FANA）作为最佳存储材料。通过温度引导语言模型进化出FANA聚合酶Tgo mut，合成速度比Tgo D4K快4.4倍，可合成超过7500个核苷酸的链。","scd":null,"kp":["存储介质[极端条件长链XNA-cssDNA嵌合体]: 2'-氟-阿拉伯核酸(FANA)为最优材料","[DNA数据存储策略]: 长链异种核酸-环状单链DNA杂合策略以提升存储鲁棒性"]},{"i":37742,"as":"","scd":null,"kp":[]},{"i":37743,"as":"","scd":null,"kp":[]},{"i":37744,"as":"","scd":null,"kp":[]},{"i":37745,"as":"","scd":null,"kp":[]},{"i":37746,"as":"","scd":null,"kp":[]},{"i":37747,"as":"","scd":null,"kp":[]},{"i":37748,"as":"","scd":null,"kp":[]},{"i":37749,"as":"","scd":null,"kp":[]},{"i":37750,"as":"","scd":null,"kp":[]},{"i":37751,"as":"肌动觉接口（MKkI）通过远程振动植入截肢者前臂肌肉的永磁体来恢复动觉。参与者报告了手部开合的协调手指运动感，符合生理范围且具有典型构型。研究揭示了引发动觉的振动频率下的感知灵敏度，表明单块前臂肌肉的刺激能引发复杂的抓握感。","scd":null,"kp":["[感知恢复机制]: 植入永磁体的肌动觉接口(MKkI)通过远程振动恢复动觉","[动觉反馈特征]: 受试者感受到受限于生理边界且具有典型构象与动力学的协调手指运动"]},{"i":37752,"as":"利用毅力号火星车的拉曼光谱仪，研究在杰泽罗陨石坑古河谷的泥岩中发现了高度非均匀分布的有机碳。两次测量发现了数百次有机物信号，包括大分子碳。光谱显示有机物与次生碳酸盐、硫酸盐或原生硅酸盐基质相关。尽管无法确定来源，但这些有机物与沉积和成岩事件的关联为火星潜在的生命迹象提供了线索。","scd":null,"kp":["[火星古代河谷新闻泥岩]: 检测到数百处有机碳非均质分布信号且首次在自然岩石表面发现大分子碳","探测仪器[火星耶泽罗陨石坑]: 搭载于毅力号火星车的拉曼光谱仪"]},{"i":37753,"as":"","scd":null,"kp":[]},{"i":37754,"as":"","scd":null,"kp":[]},{"i":37755,"as":"电化学水分解制氢受限于阳极析氧反应（OER）的缓慢动力学和高过电位。研究通过将OER替换为甲醇氧化反应（MOR），开发了一种界面工程构建的自活化催化剂RuOx@Mo(Mn)Ox，其具有不对称的Ru─O位点。该催化剂在安培级电流密度下实现了高活性、高选择性和长期稳定性，为工业规模制氢提供了节能方案。","scd":null,"kp":["[替代OER的阳极反应]: 采用甲醇氧化反应(MOR)以降低制氢能耗并提升能量效率","催化剂设计目标[电化学甲醇氧化与工业级制氢]: 兼具高催化活性、高选择性及长循环稳定性"]},{"i":37756,"as":"研究提出了一种名为全基因组脱氨测序的技术，用于在超高深度覆盖下生成酵母的定量光足迹。该技术将紫外线照射诱导的嘧啶二聚体光产物转化为突变，从而揭示蛋白质结合位点。通过比较细胞DNA与裸露DNA，该技术能够以高分辨率解析蛋白质占用情况，且无序列偏好性，解决了在活细胞内研究蛋白质-DNA相互作用的挑战。","scd":null,"kp":["[全基因组去氨基测序技术]: 结合UV诱导的光产物(嘧啶二聚体)在活细胞内全基因组水平探测蛋白质-DNA相互作用"]},{"i":37757,"as":"","scd":null,"kp":[]},{"i":37758,"as":"","scd":null,"kp":[]},{"i":37759,"as":"研究开发了一种用于抑郁症管理的AI三方分类框架，以识别介于正常与疾病之间的“疾病前状态”（可逆转阶段）。通过复杂系统理论分析临界转变的预警信号，连续监测九种电生理、行为和生物多模态生物标志物。借助超柔性神经接口获取多模态数据，AI智能体对疾病状态进行分类的准确率达到95.2%。","scd":null,"kp":[]},{"i":37760,"as":"","scd":null,"kp":[]},{"i":37761,"as":"","scd":null,"kp":[]},{"i":37762,"as":"研究提出了一种基于自力形式论的模块化框架，适用于一大类引力有效场理论。该框架旨在利用如LISA等即将到来的天基引力波探测器，通过双黑洞合并事件来测试广义相对论，为在广义相对论之外开展相关测试提供了关键技术支持。","scd":null,"kp":["广义相对论测试框架[双黑洞合并]: 提出适用于引力有效场理论的自力模块化框架以适配LISA等空间引力波探测器"]},{"i":37763,"as":"研究通过干涉测量等因果无关的测量方法，赋予了任意时空区域上的多部分量子态一种操作层面的物理意义。建立一种在空间和时间上一致适用的量子态概念，是构建相对论性量子理论的关键步骤，该工作为此提供了重要理论基础。","scd":null,"kp":["[时空量子态探测]: 建立因果无关的测量机制以在任意时空区域内赋予多体量子态操作层面的物理意义"]},{"i":37764,"as":"近期微波屏蔽技术提升了对大量极性分子的稳定性和控制能力，实现了分子玻色-爱因斯坦凝聚。研究指出，受屏蔽的极性分子表现出SU(N)对称性。在此背景下，研究探讨了在吸引型SU(3)费米-哈伯德模型中，三重态的形成及其排列有序化过程。","scd":null,"kp":["[SU(3) Fermi-Hubbard模型]: 实现了三子(Trion)的形成与有序排列","微波屏蔽技术[极性分子控制]: 提升了大量极性分子的稳定性并首次实现分子玻色-爱因斯坦凝聚"]},{"i":37765,"as":"研究将黑洞力学第一定律扩展至动态视界，使该定律适用于任意远离平衡态的黑洞。这一基础性成果在形式上证明了黑洞的热力学描述超越了通常的稳态静态解，进一步完善了黑洞热力学理论。","scd":null,"kp":["黑洞力学第一定律[动态视界非平衡态]: 扩展至可适用于任意远离热力学平衡态的黑洞"]},{"i":37766,"as":"研究在壳模型框架内，从现实的N3LO相互作用中推导出一种新的有效相互作用。该框架用于精确描述$^{132}$Sn质量区域内（质子和中子数满足$50≤Z, N≤82$）的偶偶核结构性质，为该质量区原子核的理论研究提供了经过验证的框架。","scd":null,"kp":["有效相互作用[132Sn质量区原子核结构]: 基于现实N3LO相互作用在壳模型框架下推导得出并适用于50≤Z, N≤82的偶偶核"]},{"i":37767,"as":"研究提出了通过挤压诱导的两个腔体之间的对称性破缺，作为指数级放大储层介导的非互易性的指导原则。该机制并非简单缩放耦合作用，而是通过这种特殊的对称性破缺机制，有效增强了储层工程中的单向能量和信号流。","scd":null,"kp":["[增强非互易性物理机制]: 利用两个腔体间的压缩诱导对称性破缺，实现对库介导非互易性的指数级放大"]},{"i":37768,"as":"新合成的三角晶格磁体${\\mathrm{TmZn}}_{2}{\\mathrm{GaO}}_{5}$表现出一种独特的量子相，具有强伊辛各向异性、赝双峰晶体电场基态以及K点处的低能隙激发。与其同系物不同，该材料的特性表明其极其接近量子相变临界点。","scd":null,"kp":["[TmZn2GaO5量子相特征]: 表现出强伊辛各向异性、赝双峰晶体电场基态及K点低能间隙激发","新材料合成[三角晶格磁体]: TmZn2GaO5首次成功合成并证实逼近量子相变临界点"]},{"i":37769,"as":"铁硫族化合物${\\mathrm{K}}_{3}{\\mathrm{Fe}}_{2}{\\mathrm{Se}}_{4}$具有准一维的单链结构。研究发现该材料表现出一种不寻常的块型反铁磁性。这种一维结构为研究相关的量子相互作用、非常规磁性以及超导态相变等物理现象提供了独特的平台。","scd":null,"kp":["[单链准一维K3Fe2Se4]: 展现出反常的块状反铁磁性"]},{"i":37770,"as":"新近发现的交变磁体具有独特的双重空间特性：在动量空间中具有类似铁磁体的自旋劈裂电子能带，而在实空间中保持类似反铁磁体的完全补偿磁化。研究在MnTe中观察到了超快磁光指纹特征，这些特征直接源于其晶体对称性固有的交变磁性本质。","scd":null,"kp":["[交变磁性(MnTe)]: 具有类似铁磁体的自旋劈裂能带和完全补偿的反铁磁体磁化特性"]},{"i":37771,"as":"受保护的量子态因其固有的抗噪能力在量子技术中极具前景，但往往仅存在于参数空间的离散点或狭小区域。研究提出一种机器学习方法，通过探测量子态的噪声韧性，成功在复杂的参数空间中寻找并调控至这些拓扑保护状态。","scd":null,"kp":["[受保护态的机器学习调优]: 利用内在抗噪性解决实验中难以在参数空间定位受保护态的问题"]},{"i":37772,"as":"研究利用实空间密度矩阵重正化群方法，在巨正则和正则系综下，研究了包含Kanamori-Hubbard相互作用的Bernevig-Hughes-Zhang模型中的量子自旋霍尔绝缘体。研究详细阐述了在二维系统中由相互作用驱动的边缘重构现象。","scd":null,"kp":["[量子自旋霍尔绝缘体]: 发生由相互作用驱动的边缘重构"]},{"i":37773,"as":"铜氧化物中超导相关性的频率结构为理解配对机制提供了深刻见解。研究采用细胞动力学平均场理论，对二维哈伯德模型进行了系统性研究。通过量化方法，详细分析了该模型中二维超导配对的动态频率结构及其物理特性。","scd":null,"kp":[]},{"i":37774,"as":"研究提出了一种针对生成S矩阵元素的泛函的重整化群流方程。该方程捕捉了与著名的Wetterich和Polchinski方程的相似性。后两者分别涉及等效作用量和Schwinger泛函（属离壳物理量），而本工作建立的是一种非微扰的S矩阵重整化方法。","scd":null,"kp":[]},{"i":37775,"as":"尽管粒子物理学中时空超对称性的实验证据依然缺乏，但凝聚态系统为量子临界点出现超对称性提供了重要平台。研究探讨了在二维分数化量子临界性中，时空超对称性作为一种全新的物理现象而自然涌现的机制。","scd":null,"kp":[]},{"i":37776,"as":"本研究探讨了a-LaAlO3/KTaO3界面的超导性。基于KTaO3的氧化物界面超导转变温度(Tc)对晶体学取向表现出显著依赖性。研究团队发现并报道了Tc与单一几何参数（即特定角度）之间存在线性比例关系，为理解该界面的超导机制提供了新的视角。","scd":null,"kp":["[a-LaAlO3/KTaO3界面超导]: 超导转变温度(Tc)与晶体取向几何参数（角度）呈线性比例关系"]},{"i":37777,"as":"本文研究了斜漂移不稳定性对太阳风加热的影响及其对观测分布的限制。基于线性理论得出的离子驱动等离子体不稳定性阈值，确定了稳定等离子体参数的边界。当超出这些阈值时，能量会从粒子转移到相干电磁波中，这限制了太阳风在参数空间中的观测分布。","scd":null,"kp":[]},{"i":37778,"as":"科学界普遍假设当环境变化速度超过物种适应能力时会导致物种灭绝。本研究通过构建一个通用模型对该假设进行了验证。研究填补了全球变化尺度下适应率分布未知的空白，探讨了全球变化速率、进化适应和物种灭绝之间的关系。","scd":null,"kp":[]},{"i":37779,"as":"研究探讨了化学活性乳液中发生相分离的流体混合物。这类系统在化学反应的驱动下偏离热力学平衡状态。研究展示了在化学活性乳液中，化学反应、相分离和流体动力学的相互作用导致了复杂的自组织现象和时空混沌行为。","scd":null,"kp":[]},{"i":37780,"as":"研究在相干驱动的双稳态光学腔的随机切换中证实了热力学不可逆性。研究人员测量了相空间概率流，证明了与热力学不可逆性相关的细致平衡被打破。此外，研究还估算了相关的物理量大小，证实了光学双稳态过程中的不可逆热力学特征。","scd":null,"kp":[]},{"i":37781,"as":"手性物体通常对光的两种圆偏振态表现出不同的消光特性，研究人员常利用圆二色性光谱测量这种消光差异来检测物体的手性。本研究提出了一种全新的手性光谱检测技术，用于探测和识别物体的手性特征，为手性物质的光谱分析提供了新方法。","scd":null,"kp":["[手性检测]: 提出一种新型手性光谱检测技术"]},{"i":37782,"as":"本研究提出了一种时间依赖密度泛函理论(TDDFT)的几何重构公式。这种几何重构方法能够更准确地描述处于非平衡状态的系统，解决了原有理论在处理非平衡动态系统时的局限性，提升了相关物理化学计算的有效性。","scd":null,"kp":[]},{"i":37783,"as":"量子自旋冰中U(1)量子自旋液体相的确切实验证实一直是一个突出挑战。本研究提出将杂散场磁力测量作为探测量子自旋冰中涌现光子（即无间隙激发态）的直接探针，为实验验证量子自旋冰的量子自旋液体相提供了可行方案。","scd":null,"kp":["[量子自旋冰]: 提出利用杂散场磁力测量作为涌现光子的直接探测手段"]},{"i":37784,"as":"本简报涵盖了多项科学发现：地中海不同区域的抹香鲸使用不同的咔嗒声和停顿模式，形成了不同的“方言”；科学家发明了一种可将蛋白质样本放大十亿倍的技术；此外还探讨了关于悲伤情绪的科学研究。","scd":null,"kp":[]},{"i":37785,"as":"针对低铱负载下质子交换膜水电解(PEMWE)中酸性水氧化耐久性差的问题，研究提出了一种限域工程策略。该策略利用层状共价有机框架的纳米通道和层间间隙限域铱前驱体，制备出具有2.68 Å收缩 Ir─Ir 双位点几何构型的超薄孪晶 Ir-IrO2 界面。原位光谱分析证实其成功激活了氢键介导的氧化物路径机制(OPM)，有效克服了传统催化剂的限制。","scd":null,"kp":["[高阳极电位下的Ir双原子位点]: 晶格不稳定极限尺寸为2.9 Å","[质子交换膜水电解(PEMWE)]: 面临低铱负载下酸性氧析出反应耐久性不足的瓶颈","[限制工程化Ir-IrO2界面]: 激活氢键介导的氧化物路径机制(OPM)实现耐久酸性水氧化"]},{"i":37786,"as":"针对钾离子电池在低温下解溶动力学缓慢和界面不稳定的问题，研究通过耦合高浓度电解质与氟苯(FB)和碳酸丙烯酯(PC)之间的“拖拽效应”（非溶剂化相互作用），设计了具有快速离子迁移率的PC基电解质。优化后的电解液富含接触离子对和聚集体，粘度降低了三倍，离子电导率提高了40%，成功使电池在-50°C下稳定运行。","scd":null,"kp":["[碳酸丙烯酯(PC)电解液]: K+的斯托克斯半径为3.6 Å","[氟苯介导效应]: 促进体相和界面离子传输，实现钾离子电池在-50°C下的长期运行"]},{"i":37787,"as":"利用可再生电力将碳酸氢盐直接电合成多碳(C2+)产物（如乙烯）受限于有限的二氧化碳可用性和不利的反应环境。现有的电解质工程等方法在提高选择性时往往以增加全电池电压为代价。本研究引入了一种新型电极设计，通过调控局部微环境，实现了碳酸氢盐向多碳产物的高效、高选择性转化。","scd":null,"kp":["[局部环境调控]: 实现碳酸氢根高选择性转化为多碳(C2+)产物"]},{"i":37788,"as":"研究通过热力学与电子结构分析结合颗粒自组装技术，成功构建了具有分级多孔结构的纳米孪晶高熵合金气凝胶。其晶格畸变产生了局部微应变场和纳米孪晶界，破坏了原子周期性，导致不饱和的Pd配位环境并增加活性位点密度。同时，电子从3d金属(Cu, Ni, Co)转移至4d金属，优化了多d轨道杂化，显著提升了锌空气电池的氧还原催化性能。","scd":null,"kp":["[高熵合金气凝胶]: 具有分级多孔结构，结合热力学与电子结构分析及颗粒自组装技术构建，具有缺陷Pd配位和多d轨道杂化特征","[原子尺度缺陷与电子性质调控]: 高熵合金电催化应用中仍存在实现精确控制的挑战"]},{"i":37789,"as":"针对质子陶瓷燃料电池(PCFC)中质子传输受限和表面阳离子偏析的问题，研究提出了一种基于原子层沉积(ALD)的反向原子捕获策略。该策略在钙钛矿阴极（如PrBa0.5Sr0.5Co1.5Fe0.5O）表面原位构建了质子导体，有效提升了阴极的质子电导率和氧还原反应动力学。","scd":null,"kp":["[三导电PCFC阴极]: 面临质子传输受限和表面阳离子偏析的商业化挑战","[原子层沉积]: 实现原位反向原子捕获策略以提升质子传导和氧还原动力学"]},{"i":37790,"as":"研究提出了一种手性立体锚定策略来调控FAPbI3钙钛矿的胶体结晶过程。通过引入一对对映体添加剂(R)-Pye和(S)-Pye作为手性选择性结晶调节剂，发现由于具有更佳的空间位阻可及性，R-Pye在钙钛ite表面表现出比S-Pye更有利的吸附几何构型，从而显著提高了钙钛矿太阳能电池的长期稳定性和光电性能。","scd":null,"kp":["[钙钛矿结晶调控]: 采用手性立体锚合策略通过立体化学分子设计调控FAPbI3的胶体结晶"]},{"i":37791,"as":"为实现钠离子电池在宽温域下的快速充电，研究采用了一种包含四丁基铵(TBA+)阳离子和高氯酸根(ClO4-)阴离子的多功能电解质添加剂，构建了环保的无氟电解质体系。TBA+阳离子因其低还原电位诱导产生静电屏蔽效应，结合阴离子增强的溶剂化化学，显著提升了电池的耐温性和快充性能。","scd":null,"kp":["[钠离子电池电解液添加剂]: 含有四丁基铵(TBA+)阳离子和高氯酸(ClO4-)阴离子的多功能添加剂，实现协同阴离子增强溶剂化化学和阳离子静电屏蔽"]},{"i":37792,"as":"嵌段共聚物可通过微相分离形态实现机械可编程网络，但重复单元序列与溶剂环境的具体作用尚不明确。研究合成了一系列基于CO2的聚碳酸酯共聚物，包含可交联的硬段聚乙烯基环己烯碳酸酯和不可交联的软段聚碳酸丙烯酯。通过调控聚合物序列和溶剂选择性溶胀，成功实现了对光固化3D打印器件力学性能的精细调节。","scd":null,"kp":["[嵌段共聚物]: 通过微相分离形态和固化过程中的动力学捕获，为立体光固化制造提供可机械编程的网络结构"]},{"i":37793,"as":"为解决锂离子电池准固态电解质(QSSEs)中离子传输与热安全难以兼顾的问题，研究开发了一种喷涂辅助原位组装策略。在玻璃纤维基底上直接构建唑类杂化框架(AHFs)并进行热聚合，获得化学整合的QSSE。该框架提供有序的亲锂位点和连续离子通道，在实现高效锂离子迁移的同时具备出色的热稳定性，显著提升了高安全锂电池的阻燃性能。","scd":null,"kp":["[准固态电解质制备]: 喷雾辅助原位组装策略，在玻璃纤维基底上构建唑酸盐混合框架","[锂电池安全性]: 兼具快速离子传输和内在热安全性的阻燃准固态电解质"]},{"i":37794,"as":"为开发具有可编程动力学和功能的自适应材料，研究提出了一种氧化还原响应策略，结合化学氧化还原与电化学势来引导苝二酰亚胺-组氨酸的自组装。通过连二亚硫酸钠的化学还原过程，可将分子内氢键稳定的动力学捕获二聚体快速转化为热力学有利的螺旋纳米纤维，实现了动力学控制下的超分子聚合。","scd":null,"kp":["[超分子聚合]: 结合化学氧化还原反应和电化学电势的氧化还原响应策略，调控苝二酰亚胺-组氨酸的动力学自组装"]},{"i":37795,"as":"针对可充电电池中钙金属阳极表面钝化导致Ca2+传输受阻和沉积不均的问题，研究在Ca[B(hfip)4]2/DME电解液中引入约139 ppm的痕量水。研究证实，痕量水并未引发有害的体相副反应，而是稳定地进入Ca2+溶剂化壳层，引导了受控的电化学水解途径，原位构建了水介导的固体电解质界面膜(SEI)，实现了钙金属电池的长循环寿命。","scd":null,"kp":["微量水掺杂浓度[Ca[B(hfip)4]电解液]: ~139 ppm","[金属钙负极]: 引入微量水从根本上改善界面化学，克服阻碍Ca2+传输的表面钝化及不均匀沉积问题"]},{"i":37796,"as":"La3-xTe4材料因其优异的热电性能和高温稳定性，成为下一代放射性同位素热电发生器的理想候选材料。传统的替代掺杂或空位调制方法仅能调节载流子浓度，无法优化传导带结构或降低晶格热导率。研究引入间隙掺杂策略打破僵局，实现电子和热学调节且互不干扰。目前已合成一系列Cu掺杂的La3-xTe4材料。","scd":null,"kp":["[La3-xTe4热电材料]: 采用间隙铜掺杂和热激活“ rattling ”效应替代传统替代掺杂或空位调制，以增强热电性能"]},{"i":37797,"as":"研究提出一种合成多孔有机聚合物（POPs）的新方法，通过间苯二胺对线性聚亚胺进行交联，胺与亚胺发生亲核加成形成胺醛键连接。所得聚合物成本极低（约16美元/公斤），比表面积高达650 m²/g，且富含微孔结构，远超传统材料约100 m²/g的比表面积，在C2烃/甲烷分离领域具有应用价值。","scd":null,"kp":["[多孔有机聚合物合成]: 通过间苯二胺将线性聚亚胺交联，经胺类对亚胺类的亲核加成反应形成胺连键的交联结构，用于C2烃/甲烷分离"]},{"i":37798,"as":"富锂锰基层状氧化物（LRMOs）因高容量和低成本成为高能量密度锂电池的正极材料，但面临晶格氧释放和表面结构退化问题。研究将硼异质配位结构引入富锂材料，形成厚度约4纳米的BO3富集表面层，同时体相内部保留BO4单元。四面体BO4和三角BO3结构协同作用，实现了高度稳定的阴离子氧化还原反应。","scd":null,"kp":["富锂锰基层状氧化物[阴极材料]: 存在晶格氧释放和表面驱动结构退化导致初始库仑效率低及循环稳定性差的问题","表面BO3构型[富锂阴极材料]: 引入硼异质配位结构实现高稳定阴离子氧化还原反应"]},{"i":37799,"as":"","scd":null,"kp":[]},{"i":37800,"as":"研究开发了一种名为FLIP的DNA“力锁定”探针系统，用于高通量记录细胞间累积的分子张力。FLIP利用膜锚定DNA发夹作为传感器，当其展开时，荧光标记的锁定链会选择性杂交形成稳定的双链，在单细胞水平保留受力历史。通过细胞内吞作用，该系统将膜张力信号转化为全细胞荧光，实现了单分子级别的长期累积检测。","scd":null,"kp":["力锁定积分探针(FLIP)[细胞间分子张力检测]: 基于膜锚定DNA发夹结构作为受力传感器，记录随时间累积的分子张力事件","锁链[FLIP系统]: 荧光团标记，在发夹受力展开时选择性杂交进行记录"]},{"i":37801,"as":"水系锌离子电池中锌金属负极因析氢和腐蚀等水引起的副反应导致寿命受限。研究提出在锌表面原位聚合构建基于聚丙烯酰胺（PAM）并包含聚乙二醇（PEG）和高浓度ZnCl2的 hydrogel 涂层。该多功能层能够通过氢键抑制水活性，同时调节Zn²⁺溶剂化结构，从而稳定锌金属负极。","scd":null,"kp":["水凝胶涂层[锌金属阳极界面工程]: 原位聚合的聚丙烯酰胺(PAM)基水凝胶层，掺入聚乙二醇(PEG)和高浓度ZnCl2","涂层作用[水系电解液]: 通过氢键和调节溶剂化结构抑制水活性，解决析氢和腐蚀等副反应"]},{"i":37802,"as":"研究设计了Ir/NiFe层状双氢氧化物异质结构界面，用于碱性海水高效稳定电解。金属Ir向NiFe LDH的自发界面电荷转移形成内建电场，调节Ni/Fe活性中心电子结构，双路径加速析氧反应（OER）动力学。同时，异质界面具备氯化物缓冲效应，有效抑制寄生氯化物氧化反应，解决了OER活性、选择性和耐久性之间的矛盾。","scd":null,"kp":["催化剂[碱性海水氧化]: Ir/NiFe层状双氢氧化物异质结构","异质界面[海水氧化反应]: 产生内建电场并具备Ir-Cl基元，通过双路径促进OER动力学并产生氯离子汇效应以抑制寄生反应"]},{"i":37803,"as":"欧洲原子能共同体为国际热核聚变实验堆（ITER）提供了约四分之一的核心测量系统，包括八个等离子体诊断系统、六个端口插件及大量容器内电气系统。这些系统旨在避免部件损伤、控制等离子体并探索物理机制。目前这些系统的设计阶段已基本完成，部分系统已进入制造阶段。","scd":null,"kp":["诊断系统[ITER项目]: 欧洲实物贡献提供八套诊断系统和六个端口塞","系统贡献比例[ITER项目第一壁和等离子体诊断]: 提供约四分之一的主要测量需求"]},{"i":37804,"as":"蛋白质作为动态分子机器，其运动方式决定了其生理功能。研究人员利用核磁共振波谱和分子动力学模拟，揭示了GB1蛋白结构域的运动如何受到周围分子环境的影响。研究表明，通过调节蛋白质的结构可塑性，可以实现对蛋白质功能的控制。","scd":null,"kp":["蛋白质动力学[结构可塑性调控]: 核磁共振波谱和分子动力学模拟揭示了GB1蛋白结构域的运动如何受周围分子环境影响"]},{"i":37805,"as":"研究评估了美国3至8级车辆的动力系统温室气体排放情况。相比传统柴油车，混合动力车可减排1%至26%；天然气制氢燃料电池车减排12%至51%；电网充电纯电动车减排44%至68%；可再生能源电解水制氢燃料电池车减排72%至82%；可再生能源充电纯电动车减排效果最佳，达87%至92%。","scd":null,"kp":["替代动力系统[3-8类中重型汽车脱碳]: 电池和燃料电池技术能够显著减少温室气体排放"]},{"i":37806,"as":"研究开发了一种一步法制备的乙基纤维素涂层，成功克服了辐射制冷材料中着色与高太阳能反射率之间的矛盾。该涂层能够产生鲜艳的结构色，同时对太阳光的吸收极低，并具备高超的长波红外发射率。在阳光直射下，该涂层可实现低于环境温度多达9℃的日间辐射制冷效果。","scd":null,"kp":["辐射制冷涂层[乙基纤维素涂层]: 一步法制备，具有高太阳反射率、可忽略的太阳吸收和高长波红外发射率","日间降温[亚环境温度光照条件]: 最高可达9℃"]},{"i":37807,"as":"针对钙钛矿太阳能电池对热和湿度敏感的问题，研究开发了一种级联空穴转移策略。该策略应用于混合钙钛矿/有机太阳能电池中，能够有效抑制电荷复合现象，同时为电池器件提供本征的防潮稳定性，从而提升其在实际应用中的稳定性。","scd":null,"kp":["空穴转移策略[钙钛矿/有机太阳能电池]: 级联空穴转移策略，旨在抑制电荷复合并提供本征的防潮稳定性"]},{"i":37808,"as":"研究在一种层状铜铁矿材料中成功结合了低电阻率和高电荷-自旋转换效率。该极性金属通过极性畸变打破了反演对称性，同时保留了优异的金属导电性，从而实现了高效的电荷-自旋转换。这一发现有助于提升自旋源材料的能量效率。","scd":null,"kp":["极性金属[电荷-自旋转换材料]: 层状铜铁矿材料，通过极性畸变打破反演对称性同时保持高金属导电性","自旋源材料[能量效率优化]: 在单一材料中同时实现低电阻率和高电荷-自旋转换效率"]},{"i":37809,"as":"使火星变得宜居的设想正逐渐受到科学界的关注。《自然》杂志邀请了相关领域的核心科学家，将这一实验性探索过程设计成了一款名为“自然游戏”的互动项目，旨在探讨火星地球化的可能性。","scd":null,"kp":[]},{"i":37810,"as":"研究开发了一种基于配体促进的钯催化策略，用于无偏脂肪族羧酸（如脂肪酸和环酸）的远端C(sp3)-H键活化。通过使用专门设计的O-烯丙基酰胺基酯（OAAE）配体，成功实现了γ-亚甲基和次甲基C-H位点的高区域选择性激活，促使脂肪族羧酸直接转化为远端脱饱和产物，解决了远程C-H键官能化困难的问题。","scd":null,"kp":["[脂肪族酸远程C(sp3)-H键官能化]: 采用配体促进策略，利用设计的O-烯丙基酰胺配体实现远端脱饱和内酯化"]},{"i":37811,"as":"研究首次将腺嘌呤碱基编辑技术（ABE8e）应用于人类胚胎，以探究早期发育机制。该技术通过精确定向外显子剪接供体位点引发剪接缺陷，实现了关键转录因子NANOG的功能性敲除。这一突破克服了传统核酸酶基因组编辑方法产生的基因毒性，为研究人类胚胎发生中的细胞谱系提供了新途径。","scd":null,"kp":[]},{"i":37812,"as":"","scd":null,"kp":[]},{"i":37813,"as":"","scd":null,"kp":[]},{"i":37814,"as":"中国联速超级计算机凭借其创新的芯片设计，在全球超级计算机排名中登顶。该超级计算机具备强大的计算能力，每秒可执行超过200京（2乘以10的18次方）次计算，展现了极高的运算性能。","scd":null,"kp":["计算性能[超级计算机创新芯片设计]: 大于2百亿亿次/秒"]},{"i":37815,"as":"Yuan等人开发了一套具有偏振分辨能力的高场磁红外光谱系统，并利用该系统在二型外尔半金属Mn(Bi1-xSbx)2Te4中首次观察到了巨大的宽带红外圆二色性现象。这一发现揭示了外尔半金属中的巨大红外手性特征。","scd":null,"kp":["物理现象[II型外尔半金属Mn(Bi1-xSbx)2Te4]: 首次观察到巨大的宽带红外圆二色性","检测仪器[高场磁红外光谱系统]: 具有偏振分辨率"]},{"i":37816,"as":"","scd":null,"kp":[]},{"i":37817,"as":"","scd":null,"kp":[]},{"i":37818,"as":"","scd":null,"kp":[]},{"i":37819,"as":"研究开发了一种液相生长和退火（LPGA）策略，以解决极低剂量X射线成像中由于光子统计稀疏和垂直传输不均匀性导致的信号放大瓶颈。该技术消除了传统方法中的热学和质传递不稳定性，成功制备出垂直均匀的钙钛矿薄膜。这一突破满足了人工智能时代对可靠低光子通量探测与成像的迫切需求。","scd":null,"kp":["[X射线成像探测器]: 垂直均匀钙钛矿薄膜可实现超低剂量/低光子通量下有效操作"]},{"i":37820,"as":"自然界中的许多旋转分子马达能够根据外部环境的变化反转其旋转方向。近期发表的两项独立研究展示了全新的技术途径，成功在完全人工合成的分子马达中实现了旋转方向的逆转。这一成果为人工分子机械的定向控制提供了重要方法。","scd":null,"kp":["[全合成分子旋转马达]: 开发出可响应环境反转旋转方向的新方法"]},{"i":37821,"as":"将脂肪族醛转化为酮类自由基常用于构建碳-碳键，但相关酮类的转化反应此前尚未实现。本研究采用自由基转移策略，利用酮衍生的甲硅烷基氰醇成功实现了上述转化，有效拓展了碳-碳键构建的反应途径与底物范围。","scd":null,"kp":["[酮类衍生物制备羰基自由基]: 采用自由基转移策略从酮衍生的甲硅烷基氰醇成功生成类羰基自由基"]},{"i":37822,"as":"","scd":null,"kp":[]},{"i":37823,"as":"","scd":null,"kp":[]},{"i":37824,"as":"纳米科学在力学生物学领域中发挥了关键的桥梁作用。它提供了必要的概念与技术支撑，成功将物理学与生物学的视角统一起来，从而深化了在力学生物学层面对生物物理机制的交叉学科理解与研究。","scd":null,"kp":["[纳米技术与力学生物学交叉融合]: 纳米科学提供了统一物理与生物学视角的概念和技术桥梁"]},{"i":37825,"as":"光辅助锂氧电池受限于光生载流子与Li2O2化学反应的耦合效率。研究开发了氟代石墨二炔（FGDY）作为光响应阴极，通过光诱导分子内电荷重排调控Li+和氧中间体的吸附，促使Li2O2沿纤维网络形成膜状结构而非绝缘盘状晶体。该策略抑制了寄生反应，使电池在光照下的往返效率达到97.5%。","scd":null,"kp":["光电阴极[光辅助锂氧电池]: 氟取代石墨二炔(FGDY)","[FGDY光电阴极调控生长]: 光诱导分子内电荷重排调控Li+和氧中间体吸附，促使Li2O2沿纤维网络呈膜状生长而非绝缘盘状晶体"]},{"i":37826,"as":"全固态锂电池中的界面接触失效通常归因于纯锂金属在界面处产生空洞。研究表明，锂负极内部的绝缘杂质在剥离过程中会在界面处积聚，形成一层多孔且机械稳定的阻挡层。该杂质层会直接阻断锂离子进入电解质的通量，从而导致电池接触不良。","scd":null,"kp":["[全固态锂电池界面接触失效机制]: 锂负极中的绝缘杂质在剥离过程中于界面处积聚，形成机械稳定的多孔层阻断锂进入电解质"]},{"i":37827,"as":"研究表明，全球塑料行业若要在2050年实现温室气体净零排放，必须依赖生物基材料、碳捕获与利用（CCU）结合清洁氢能。前瞻性生命周期评估显示，届时氢气需求量将激增至目前的14倍，总量达1.26至1.45亿吨。结合生物基与电基制氢工艺，塑料行业可有效平衡多种地球生态边界。","scd":null,"kp":["氢气需求量[2050年全球净零排放塑料产业]: 126-145 Mt","需求增幅[2050全球净零排放塑料产业]: 增加至14倍"]},{"i":37828,"as":"细菌能够通过细胞间的协同作用来提升在抗生素环境下的存活率。研究发现，细菌通过分泌和利用膜囊泡在细胞间共享特定的蛋白质。这种基于膜囊泡的细胞间合作机制有效增强了细菌群体对抗生素的持久耐受性。","scd":null,"kp":[]},{"i":37829,"as":"","scd":null,"kp":[]},{"i":37830,"as":"","scd":null,"kp":[]},{"i":37831,"as":"","scd":null,"kp":[]},{"i":37832,"as":"RNA套索分支由脱支酶DBR1降解，DBR1功能受损会导致植物发育停滞。研究发现，DBR1介导的降解可阻止21和22个核苷酸的套索衍生小干扰RNA（lasiRNAs）的产生，防止有害外显子siRNA爆发。当病原体感染且DBR1功能失常时，套索RNA被DCL4和DCL2加工成siRNA，特异性靶向免疫基因，破坏植物防御。","scd":null,"kp":["lasiRNA尺寸[RNA干扰]: 21-和22-核苷酸"]},{"i":37833,"as":"研究开发了一种表面制备与沉积方法，成功在有机晶体表面观测到了单个分子的傅里叶极限电子跃迁。通过在液氦温度下进行光谱和超分辨显微镜测量，彻底消除了退相干效应，使跃迁线宽完全由激发态寿命决定。该成果为深入研究表面吸附分子的光谱与空间特征提供了全新途径。","scd":null,"kp":["光谱分辨率[表面吸附分子]: 傅里叶极限/由激发态寿命决定"]},{"i":37834,"as":"","scd":null,"kp":[]},{"i":37835,"as":"","scd":null,"kp":[]},{"i":37836,"as":"为纪念首届人工智能研讨会举办70周年，相关文章回顾并反思了人工智能技术在过去半个多世纪的发展历程，及其对人类社会和科技领域产生的深远影响与广泛遗产。","scd":null,"kp":[]},{"i":37837,"as":"","scd":null,"kp":[]},{"i":37838,"as":"研究构建了多层方形平面镍酸盐（Nd_{n+1}Ni_nO_{2n+2}）的超导相图。方形平面镍酸盐超导性的发现为探索高温超导起源提供了重要的材料平台。以往实验研究多局限于无限层镍酸盐，该相图的建立填补了多层结构镍酸盐超导相变特性的实验空白。","scd":null,"kp":[]},{"i":37839,"as":"","scd":null,"kp":[]},{"i":37840,"as":"","scd":null,"kp":[]},{"i":37841,"as":"","scd":null,"kp":[]},{"i":37842,"as":"","scd":null,"kp":[]},{"i":37843,"as":"","scd":null,"kp":[]},{"i":37844,"as":"","scd":null,"kp":[]},{"i":37845,"as":"随着公司和美国政府围绕AI安全展开博弈，研究人员陷入了交火之中。Fable 5模型 tumultuous 的下架事件引发了人们对开放研究前景的担忧。","scd":null,"kp":[]},{"i":37846,"as":"随着构建更大、更先进的聊天机器人变得越来越困难，AI研究人员开始转向开发能够在模拟世界中学习的智能体。研究重点正从纯语言模型转向模拟世界的探索。","scd":null,"kp":[]},{"i":37847,"as":"","scd":null,"kp":[]},{"i":37848,"as":"","scd":null,"kp":[]},{"i":37849,"as":"三位国际可再生能源先驱被授予Mani L. Bhaumik年度突破奖。这标志着可再生能源技术迎来了充满阳光的广阔发展前景。","scd":null,"kp":[]},{"i":37850,"as":"","scd":null,"kp":[]},{"i":37851,"as":"","scd":null,"kp":[]},{"i":37852,"as":"I类组蛋白去乙酰化酶（HDACs）是DNA损伤反应（DDR）的关键调节因子。抑制HDAC（如使用entinostat）会使H3K27乙酰化转移至基因间区域，转移BRD4和RNA聚合酶II，从而抑制DDR基因表达。HDAC抑制通过转录机制的全局重分布，增加了胰腺肿瘤对DNA损伤的敏感性。","scd":null,"kp":["靶向调控机制[胰腺癌(PDAC)DNA损伤响应]: 抑制I类组蛋白去乙酰化酶(HDACs)"]},{"i":37853,"as":"","scd":null,"kp":[]},{"i":37854,"as":"","scd":null,"kp":[]},{"i":37855,"as":"","scd":null,"kp":[]},{"i":37856,"as":"","scd":null,"kp":[]},{"i":37857,"as":"","scd":null,"kp":[]},{"i":37858,"as":"","scd":null,"kp":[]},{"i":37859,"as":"","scd":null,"kp":[]},{"i":37860,"as":"","scd":null,"kp":[]},{"i":37861,"as":"","scd":null,"kp":[]},{"i":37862,"as":"","scd":null,"kp":[]},{"i":37863,"as":"","scd":null,"kp":[]},{"i":37864,"as":"利用冷冻电镜技术在1.8至2.2埃分辨率下解析了金色藻类管状鞭毛丝的结构。除了高甘露糖型和复合型N-聚糖外，研究还在AND基序上发现了一种非典型N-聚糖。表面密集的O-聚糖覆盖在PSXX四肽重复序列上，每个重复序列中均有两个聚糖连接在三羟基化脯氨酸上，一个连接在丝氨酸上。结构中还包含水分子和阳离子。","scd":null,"kp":["结构分辨率[冷冻电镜解析管状鞭毛糖链]: 1.8至2.2埃","特殊糖基化位点[金藻管状鞭毛]: 在Ala-Asn位点发现非经典N-聚糖"]},{"i":37865,"as":"细胞形态变化主要由质膜下的动态肌动蛋白细胞骨架网络控制。部分细胞能形成由细胞膜敏感蛋白调节的、不受细胞外基质支撑的独立突起。研究探讨了活性凝胶在波动膜上生长时的曲率不稳定性，该成果发表于《物理评论快报》。","scd":null,"kp":["[细胞膜波动上的活性凝胶]: 活性凝胶生长表现出曲率不稳定性"]},{"i":37866,"as":"","scd":null,"kp":[]},{"i":37867,"as":"","scd":null,"kp":[]},{"i":37868,"as":"层状过渡金属二硫属化物1T-TiSe2在形成电荷密度波（CDW）时，常伴随激子凝聚、轨道序和手性出现等奇特现象。为了解释这些物理效应，研究重新审视了该材料的电荷密度波超晶格结构。","scd":null,"kp":["[1T-TiSe2的电荷密度波超晶格]: 重新审视并揭示了其电荷密度波形成的微观机制"]},{"i":37869,"as":"暴露在微波环境下的磁性薄膜中，微小的凸起结构能够引发具有精确频率间隔的自旋波，这一现象被称为曲率诱导的磁振子频率梳。该成果探讨了微观几何结构对磁振子特性的影响。","scd":null,"kp":["[磁性薄膜曲率效应]: 微小的凸起在微波照射下能产生具有精确等间距频率的自旋波"]},{"i":37870,"as":"反铁轴态是凝聚态物理体系中一种重要的铁性序。研究建立了反铁轴交变磁性机制，指出反铁轴反向旋转畸变能够诱导产生交变磁性，这是一种广泛存在、具有微观基础的多铁性机制。","scd":null,"kp":["[反铁轴向交变磁性]: 建立为一种广泛存在、微观基础扎实的多铁性机制"]},{"i":37871,"as":"","scd":null,"kp":[]},{"i":37872,"as":"研究展示了在手性二维钙钛矿中，通过全光控制实现载流子-应变介导的自旋分裂巨大增强（达100 meV）。利用超快圆二色性测量技术，证实了自旋分裂与应变相互作用能够有效提升热载流子的寿命。","scd":null,"kp":["自旋分裂增强[手性二维钙钛矿材料中的载流子-应变相互作用]: 100 meV"]},{"i":37873,"as":"通过将钼箔限制在两块蓝宝石基板之间，开发出一种低成本的界面外延策略，成功合成了高质量单斜相钼酸铝（Al2(MoO4)3）单晶薄层。该单晶材料中强的声子-光子耦合作用催生了双曲声子极化激元，其传播特性可通过激发频率和晶体取向进行精确调控。","scd":null,"kp":["[钼酸铝(Al2(MoO4)3)薄层单晶]: 开发了具有成本效益的界面外延合成策略"]},{"i":37874,"as":"采用空化介导的声化学策略，在环境条件下几分钟内实现了氧化钌的均相取代硼掺杂。硼掺杂取代晶格钌位点并形成强共价键，通过优化含氧中间体吸附和抑制晶格氧参与，增强了内在活性与稳定性。掺杂后的催化剂在10 mA cm−2下表现出180 mV的低过电位，且耐久性超过3000小时。","scd":null,"kp":["[环境条件下氧化钌内的硼掺杂]: 采用空化介导的声化学策略实现均匀的取代硼掺杂（耗时数分钟）"]},{"i":37875,"as":"开发出一种能够直观比较介电泳和声泳作用力的电致发光显示器。该装置结合了交流电致发光与由这两种力控制的导电微粒自组装技术。在交流电场下，介电泳力驱动微粒自组装产生光信号；而在声波传输时则产生声泳相关的发光响应，实现了双重力学的动态可视化。","scd":null,"kp":["[介电泳与声泳双传感电致发光显示器]: 利用介电泳和声泳力控制导电微粒自组装，实现动态可视化"]},{"i":37876,"as":"针对锌离子电池中锌枝晶生长的难题，提出用无量纲常数K来量化电化学反应动力学与传质速率之间的平衡。研究发现，通过N,N-二甲基脲等尿素衍生物调节Zn2+电镀，实现两者的更好平衡是有效抑制枝晶的关键。具有最高K值的N,N-二甲基脲电解液表现出优异的稳定性。","scd":null,"kp":["[锌负极电化学反应动力学与传质]: 尿素衍生物可实现电化学反应动力学与传质过程的平衡，抑制枝晶形成"]},{"i":37877,"as":"利用硬件高效的量子电路和原生多量子比特操作，在硅基供体自旋中成功制备了所有九个标准族的四量子比特纠缠态。通过重叠层析成像和多方面验证，确认了真正的多粒子纠缠，解析了纠缠结构，评估了量子比特丢失时的鲁棒性，并观察到多粒子贝尔不等式的显著违背。","scd":null,"kp":["[硅基核自旋多粒子纠缠]: 设计硬件高效量子电路，成功制备四比特纠缠的所有九个典型族"]},{"i":37878,"as":"利用时温叠加原理指导金属有机框架（MOF）晶体-玻璃复合膜的制备，解决了加工中填料易热降解的难题。以玻璃态ZIF-62为连续相，结晶UiO-66等为分散相，通过低温重熔策略成功制备了具有最小热分解的薄膜。该膜对CO2/N2等混合气体表现出高分离效率。","scd":null,"kp":["[MOF晶体-玻璃复合膜制备]: 采用时温等效(TTS)原理指导以解决加工过程中填料热降解难题","连续相[MOF晶体-玻璃复合膜]: 玻璃态ZIF-62","分散相[MOF晶体-玻璃复合膜]: 晶态UiO-66、Mg-MOF-74和MOF-801"]},{"i":37879,"as":"报道了一种工程化修饰密集吡嗪基团的sp2碳共轭共价有机框架。该材料实现了高效的二氧化硫捕获，在25℃和1.0 bar下达到19.4 mmol/g的超高吸附容量，且对二氧化硫具有精确的选择性梯度。经过50次吸附-解吸循环后性能无明显下降，展现出卓越的稳定性和实际应用潜力。","scd":null,"kp":["SO2吸附容量[DpTb-COF]: 19.4 mmol/g","吸附剂结构[SO2捕集]: 具有密集排列有序哒嗪基团的sp2碳共轭共价有机框架"]},{"i":37880,"as":"利用仲氢增强的自旋选择核磁共振方法研究丙酮酸盐的结合过程。研究重塑了对可逆交换信号放大技术（SABRE）的认知：分子内氢化物的交换速度快于丙酮酸盐的交换，该过程可在数秒内实现底物快速极化，而无需对底物进行化学修饰。","scd":null,"kp":["极化建立时间[SABRE技术]: 数秒内","[SABRE技术]: 使用仲氢(pH2)和铱络合物实现底物无需化学修饰的快速超极化"]},{"i":37881,"as":"探讨可逆固体氧化物电池（rSOC）技术在欧洲脱碳框架下的长期储能应用。研究表明rSOC技术实现了60%的长时储能往返效率，具备即期的环境与经济优势。在2050年欧洲能源场景中，各国对rSOC系统的储能容量需求差异显著，范围为54至680 kWh/kW，且能实现最低的储能平准化成本。","scd":null,"kp":["往返效率[可逆固体氧化物电池长期储能]: 60%"]},{"i":37882,"as":"","scd":null,"kp":[]},{"i":37883,"as":"研究人员利用基于从头算无核壳模型（采用Daejeon16核子-核子相互作用及库仑相互作用）得出的$^{4}\\mathrm{He}$和$^{6}\\mathrm{He}$基态波函数，计算了两体空间关联。通过评估这些成对关联，研究表征了两种核系统的内部结构，特别是用于分析$^{6}\\mathrm{He}$的晕核结构。","scd":null,"kp":[]},{"i":37884,"as":"FOOT合作组测量了400 MeV/核子的$^{16}\\mathrm{O}$离子束轰击聚乙烯和氢靶的核碎裂截面。获取人体内轻元素（如H、C、O）的核碎裂数据对于粒子治疗（PT）、太空辐射防护（RPS）以及宇宙射线物理学的发展具有极其重要的基础性意义。","scd":null,"kp":[]},{"i":37885,"as":"为探究弱束缚弹核反应中$\\alpha$粒子的高产额机制，研究团队测量了库仑势垒附近能量下$^{6}\\mathrm{Li}+^{93}\\mathrm{Nb}$系统发射$\\alpha$粒子的能量-角度关联。实验结果表明，三体蒙特卡罗断裂模拟结果与测量数据高度吻合，揭示了$\\alpha$粒子的具体产生机制。","scd":null,"kp":[]},{"i":37886,"as":"BGOegg合作组在总能量从$\\eta^{\\prime}$介子产生阈值至2.32 GeV范围内，对质子上的$\\eta^{\\prime}$光生反应进行了全面测量。通过分析$\\eta^{\\prime}$的两种衰变模式，研究测量了该反应的光束不对称性以及总截面和微分截面，为核子共振谱学提供了实验数据。","scd":null,"kp":[]},{"i":37887,"as":"阴离子氧化还原反应（ARR）是支撑下一代高能量密度电池的关键机制。本研究探讨了决定Li₁.₁₇Ti₀.₅₈Ni₀.₂₅O₂（LTNO）体系中ARR工作电压的关键因素。该系统在2.0V附近具有独立的ARR电压平台，研究表明充放电之间的电压迟滞会导致较差的能量效率，这是限制其实际应用的核心因素。","scd":null,"kp":["[阴离子氧化还原反应(ARR)]: 充放电之间的电压滞后导致能量效率差，是限制其实际应用的关键因素"]},{"i":37888,"as":"针对水系锌电池中传统隔膜无法控制枝晶生长和副反应的问题，研究人员设计了一种超薄、坚韧的不对称MOF基隔膜。该隔膜在亲水细菌纤维素膜（宏孔结构）上原位生长了导电Ni基金属有机框架微孔层。基底层提供机械强度和吸液能力，微孔c-MOF层则用于调节锌离子的传输。","scd":null,"kp":["[水系锌离子电池隔膜]: 异质结构工程设计的超薄、坚韧且具有导电Ni-MOF微孔层的非对称隔膜","[隔膜应用效果]: 能够实现快速选择性离子传输并抑制不受控制的枝晶生长和副反应"]},{"i":37889,"as":"为提升钠离子电池的体积能量密度，研究系统评估了不同Sn/P原子比的Sn-P合金作为负极材料的性能。结果表明，SnP₃合金在成本、体积容量和循环稳定性之间取得了最佳平衡。在钠化过程中，晶态SnP₃会转化为非晶态并在后续循环中保持非晶态，展现出固溶体类型的反应特征，有效提升了材料的稳定性和能量密度。","scd":null,"kp":["[钠离子电池负极材料]: 系统评估不同Sn/P原子比的Sn-P合金","综合最优性能[Sn-P合金负极]: SnP3在成本、体积容量和循环稳定性之间提供最佳平衡"]},{"i":37890,"as":"下一代核聚变装置的面向等离子体部件（PFCs）必须承受10-15 MW/m²的稳态热负荷及瞬态事件带来的多重热应力。研究团队在WEST和AUG托卡马克装置上对钨（W）PFCs进行了广泛测试。WEST超导托卡马克提供了稳态条件，以验证这些部件在数千小时等离子体辐照下的可靠热排气能力和使用寿命。","scd":null,"kp":["稳态功率通量[面向等离子体部件(PFC)]: 10–15 MW m−2","[PFCs性能要求]: 在全寿命周期内需承受数千小时等离子体辐照并保持可靠的排热能力和抗热应力韧性"]},{"i":37891,"as":"$\\pi$共轭自由基因其含有未配对电子，在过去125年中推动了电子结构理论的发展。这类自由基被积极用作单组分有机导体、场效应晶体管半导体、有机磁体、电致发光和量子材料等功能材料。本综述提供了必要的量子化学背景和设计稳定$\\pi$自由基的实践经验，探讨了其反应性的根本原因。","scd":null,"kp":["[π共轭自由基]: 带有未配对电子，作为功能性材料应用于单组分有机导体、场效应晶体管半导体和有机磁体等"]},{"i":37892,"as":"直接不纯水电解（DIWE）技术使得在淡水和可再生能源地理位置不匹配的地区生产绿色氢气成为可能。本综述评估了海水和废水中存在的各种杂质及其对电解性能的具体影响，特别是性能退化带来的挑战。文章提出了一条基于杂质诱导相互作用的工业化路径，并评估了将DIWE整合到现有工业工作流程中的技术和经济可行性。","scd":null,"kp":["[直接不纯水电解(DIWE)]: 无需依赖淡水，利用海水和废水直接电解，但面临杂质导致性能衰减的工业化挑战"]},{"i":37893,"as":"聚烯烃占全球塑料产量的一半以上，其短使用寿命引发了环境问题。催化增值是一种将废聚烯烃转化为高附加值化学品和燃料的有效策略。本综述从催化剂设计、工艺工程和反应器选择的多尺度视角，描述了聚烯烃催化增值的最新进展，指出实际部署取决于从分子级活性位点到反应器设计的协同创新。","scd":null,"kp":["[聚烯芬废弃物的催化高值化]: 依赖催化剂-工艺-反应器链的协同创新"]},{"i":37894,"as":"","scd":null,"kp":[]},{"i":37895,"as":"","scd":null,"kp":[]},{"i":37896,"as":"神经形态电子学通过模拟大脑原理提供低功耗存内计算，但其实际能力受限于非理想性、训练精度和适应性等挑战。本研究探讨了数字、混合信号及新兴神经形态电子器件的训练方法，分析了片外训练与片上推理、片上训练和混合离线-在线训练策略的特点与优势，并提出需在硬件软件协同设计方面解决现有挑战。","scd":null,"kp":["[类脑电子系统]: 孕算一体且具备低功耗","[类脑电子系统训练]: 面临器件非理想性、训练精度有限和适应性不足的挑战"]},{"i":37897,"as":"色散器件和模拟计算领域的最新进展，正在推动光谱仪向微型化方向发展。这些技术的结合有效缩小了光谱仪的物理尺寸，使其能够在更紧凑的形态因子下实现光谱分析功能。","scd":null,"kp":["[微型光谱仪]: 色散器件与模拟计算技术共同推动尺寸缩减"]},{"i":37898,"as":"针对多元素掺杂无铅(K,Na)NbO₃压电陶瓷研发中的复杂掺杂趋势和繁琐试错问题，研究提出了一种人在回路的人工智能指导材料设计框架。利用大语言模型提取文献中的隐式构效关系以提出新成分，结合专家干预加速实验验证。合成的随机成分压电电荷常数d33达440-500 pC/N，经微观织构优化后进一步提升至600-620 pC/N。","scd":null,"kp":["[无铅(K,Na)NbO₃压电陶瓷]: 多元素掺杂且具有复杂的掺杂趋势","[人机协同材料设计框架]: 结合大语言模型提取隐性构效关系并辅以专家干预与材料科学原理"]},{"i":37899,"as":"锰掺杂的硒化镉量子点能够通过一种超快自旋交换介导的电子转移路径，在常规能带边缘能量不利于电荷转移的情况下实现甲基紫精的还原。飞秒瞬态吸收光谱表明，锰掺杂使电子转移动力学加速了一个数量级以上，并开辟了热激子还原通道，通过锰离子的自旋弛豫驱动电荷分离和分子还原。","scd":null,"kp":["催化剂[碳镉矿量子点]: 锰掺杂","[界面自旋交换]: 实现超快电子转移并加速甲基紫精还原","[量子限域半导体]: 通过自旋活性掺杂剂控制界面氧化还原化学"]},{"i":37900,"as":"有机分子氧化反应是替代析氧反应（OER）的节能制氢方案，但难以匹配大电流密度。本研究提出了一种气泡辅助策略，以苄胺氧化反应（BOR）为探针，通过激活OER产生氧气气泡，及时将不溶性产物苯甲腈从电极表面带走。该策略克服了传质限制，实现了与安培级大电流密度制氢相耦合的稳定氧化过程。","scd":null,"kp":["[耦联氧化反应]: 适用于安培级大电流密度制氢且伴随气泡辅助清洗"]},{"i":37901,"as":"未活化烷基卤化物和炔基卤化物之间的交叉电偶联反应长期面临反应活性不匹配和化学选择性差的挑战。研究报道了一种由三齿配体控制的镍催化交叉电偶联反应，实现了直接构建炔基-烷基键。该配体强制执行不寻常的顺序活化路径：Ni(0)催化剂先结合烷基卤化物，再进行炔基卤化物的氧化加成，反应具有广泛的官能团耐受性。","scd":null,"kp":["[未活化烷基卤化物和炔基卤化物]: 克服反应性不匹配和化学选择性差的挑战","催化剂[交叉电偶联反应]: 镍催化配合三齿配体","[配体控制策略]: 控制电偶联活化的顺序以直接构建炔基-烷基键"]},{"i":37902,"as":"研究探讨了非线性对非厄米趋肤效应的影响，这是一种由非厄米系统特有的点隙拓扑引起的现象。研究发现，非线性会引发点隙拓扑相变，并伴随着趋肤模式局域化的反转。该现象在非线性微波超材料中得到实验证实，系统中的电磁波在非线性作用下被局域在链的一端，随后转移到另一端，证明了局域化反转及谐波的产生。","scd":null,"kp":["[非线性非厄米趋肤效应]: 引发局域化反转与谐波产生现象"]},{"i":37903,"as":"贝叶斯神经网络（BNN）通过量化预测不确定性实现可信边缘智能，但硬件实现受限于数字方法的高延迟或忆阻器电导与噪声间的固有耦合。研究报道了一种基于离子凝胶/氧化锌异质结构的耦合双通道忆阻器（CDCM）。该器件利用垂直离子门控建立两个突触通道，以差分电导作为突触权重，实现了硬件原生状态下对权重均值（μ）和标准差（σ）的正交控制。","scd":null,"kp":["[硬件原生贝叶斯智能]: 利用耦合双通道忆阻器打破电导均值与随机噪声间的内禀耦合限制","器件结构[耦合双通道忆阻器]: 离子凝胶/氧化锌异质结"]},{"i":37904,"as":"研究发现多孔金属有机框架（MOFs）材料ZIF-4(Zn)具有巨大的压卡效应，可用于制冷和加热。该材料通过气体吸附可高度调节起始温度，并实现宽温区内的压力可逆驱动。在约1 kbar压力下，负载氮气的ZIF-4(Zn)等温熵变（|∆Sit|）大于38 J K-1 kg-1，绝热温度变化（|∆Tad|）大于10 K。此外，脱溶剂的ZIF-4(Zn)展现出更大的压卡效应，|∆Sit|高达210 J K-1 kg-1，|∆Tad|达60 K。","scd":null,"kp":["[ZIF-4(Zn)金属有机框架]: 客体分子吸附可巨大调节压卡效应并拓宽温度范围"]},{"i":37905,"as":"微波合成器在众多领域应用广泛，但现有技术面临频率可调性与光谱纯度之间的权衡限制。电光分频（eOFD）是一种将光学纯度转移到微波领域的新兴技术。研究提出一种前馈eOFD架构，通过消除微波源的相位噪声，在保留频率可调性的同时实现了光学光谱纯度的下分频，且无需下游电子频率合成，成功克服了传统eOFD合成器因反馈稳定要求而导致的可调性受限问题。","scd":null,"kp":["[电光分频(eOFD)微波合成器]: 解决微波源频率可调谐性与光谱纯度之间的权衡限制"]},{"i":37906,"as":"单光子发射器是量子技术的核心组件，但常受到宿主材料中体声子的干扰。研究发现在纳米金刚石中发现了一种与体声子环境强烈解耦的单色心。该色心在室温下展现出低至0.3纳米的创纪录极窄线宽，饱和发射率超过10 Mcps。体声子侧带几乎被完全抑制，并在金刚石声子带外出现了单一局域振动模式。这表明在宽禁带材料中存在独特的声子解耦机制。","scd":null,"kp":["线宽[室温下单光子发射体(纳米金刚石色心)]: 低至0.3 nm","[单光子发射体(纳米金刚石色心)]: 与宽带体声子环境强解耦，具备稳定明亮的发射特征"]},{"i":37907,"as":"电化学直接空气捕集（eDAC）面临捕集率低和再生能耗高等挑战。研究构建了一种新型eDAC平台，在三维空气-电极界面局部生成氢氧化物以提升吸收动力学和碱性利用率。随后通过质子耦合电子转移介体释放CO2，实现低能耗再生和高纯度气体输出。此外，该架构采用多孔隔板等关键创新设计，有效提升了系统的稳定性与可扩展性。","scd":null,"kp":["[电化学直接空气捕获(eDAC)平台]: 通过三维界面局部碱度生成实现系统架构创新"]},{"i":37908,"as":"丙二烯C(sp)–C(sp2)和C(sp3)–C(sp2)键的自由基介导断裂是合成化学中的一大难题。研究利用硅基取代策略，以空气为氧化剂，通过廉价金属催化成功实现了对上述双键和单键的化学与区域选择性断裂。该转化由丙二烯C(sp2)–H键的氢原子抽象引发，可生成多种远程官能化酮、烷基化杂芳烃、烷基化腈和氘代产物。","scd":null,"kp":["[丙二烯C(sp)–C(sp2)和C(sp3)–C(sp2)键断裂]: 碱金属催化实现的自由基介导断裂"]},{"i":37909,"as":"针对钠硫族电池动力学迟缓和穿梭效应的限制，研究提出一种酸性粘结剂诱导腐蚀策略，成功激活了块状S/Se/Te正极材料。富含羧酸的粘结剂在加工中形成酸性微环境（pH≈3），促使铜集流体上自发形成铜硫族化合物中间层。该中间层在循环中重构为活性Cu2X催化剂。在Na-Se电池中，Cu2Se使液固转化势垒降低了约24.1%，加速了多硒化物的转化，有效抑制了穿梭效应。","scd":null,"kp":["pH[钠硫族电池加工过程微环境]: ≈3","[大块S/Se/Te正电极]: 酸性粘结剂诱导铜腐蚀自发形成铜硫族化合物中间层"]},{"i":37910,"as":"研究展示了在缺乏资源的史前海洋环境中，通过两亲性分子和微小分子的极小结构差异来控制原细胞浮力，实现可编程的空间分层。两亲分子（如异构体、烷基链长、反离子等）的结构差异决定了凝聚层在水柱中的垂直分布。此外，浓度和温度等环境因素可动态调节液滴的空间定位。这种垂直分层机制源于分子海绵状结构的吸水性。","scd":null,"kp":["[原始凝聚层液滴]: 两亲分子和微小分子结构变化决定浮力并控制垂直分层"]},{"i":37911,"as":"研究利用磁光谱μSQUID-EPR技术，在基于钆（Gd）的单离子分子磁体[160GdPc₂]⁻中直接探测了量子隧穿现象。实验通过在横向磁场下用微波照射单晶，成功解析了自旋流形（S = 7/2）并观察到明显的几何相位干涉（Berry相位），实现了对隧穿分裂的精确映射。这一发现证明了分子磁子平台可以通过拓扑性质来抑制量子隧穿，从而保持量子相干性。","scd":null,"kp":["[镧系单离子分子磁体(4f): 直接探测到几何相位干涉(Berry相位)"]},{"i":37912,"as":"","scd":null,"kp":[]},{"i":37913,"as":"","scd":null,"kp":[]},{"i":37914,"as":"","scd":null,"kp":[]},{"i":37915,"as":"为推动太阳能研究发展，研究人员整合了超过800GB的高分辨率太阳能塔式发电厂运行数据，建立了一个符合FAIR数据原则的开放获取数据库PAINT。该数据库通过向公众提供高度结构化的实际运行数据，降低了数据获取门槛，旨在加速太阳能塔式发电领域数据驱动型解决方案的开发与相关研究。","scd":null,"kp":["数据量[太阳能塔式光热电站(PAINT数据库)]: >800 GB"]},{"i":37916,"as":"自由空间衍射光学系统能够通过将非线性函数的串行链路压缩到单个光学阶段中，实现复杂的逻辑电路。研究展示了利用这种可重构的衍射光学系统并行执行非线性逻辑运算。该技术成功实现了所有基本逻辑门，并演示了并行半加器和全加器等复杂的逻辑电路，为快速、高并行度且低能耗的全光计算提供了新途径。","scd":null,"kp":["[自由空间衍射光学系统]: 可重构架构并行执行非线性逻辑运算"]},{"i":37917,"as":"三线态通常是非常短寿命的瞬态中间体。但最新研究通过对空间位阻较大的单线态锗烯进行光激发，成功在室温下捕获并表征了一种异常稳定的三线态锗烯。这种三线态物质的半衰期长达14小时，打破了常规认知，为深入研究高反应活性中间体提供了重要基础。","scd":null,"kp":["半衰期[室温下三重态锗烯]: 14小时"]},{"i":37918,"as":"","scd":null,"kp":[]},{"i":37919,"as":"多家初创企业正在开发下一代基于表观基因组编辑的疾病疗法。这些疗法通过CRISPR等技术靶向特定的表观遗传标记，在不改变底层DNA序列的情况下调控基因表达，目前正被测试用于治疗高胆固醇到罕见肌肉萎缩等多种疾病。","scd":null,"kp":["[疾病治疗]: 靶向特定表观遗传标记的基因编辑疗法（用于治疗高胆固醇和罕见肌肉疾病等）"]},{"i":37920,"as":"","scd":null,"kp":[]},{"i":37921,"as":"研究开发了一种简洁可扩展的策略，可从易得的前体高效合成桥头取代的[2]-梯形烷。该含能骨架是发生可编程、区域选择性桥头官能团化和张力释放环加成的理想中间体，可与缺电子烯烃反应生成多种多取代双环[2.2.2]辛烷（BCO）。这些BCO分子支架可进一步实现定点多样化修饰，并作为饱和的生物电子等排体应用。","scd":null,"kp":["[桥头取代[2]-梯形烷]: 简洁且可扩展的高效合成策略","[功能化衍生物]: 可作为可编程的多功能化中间体"]},{"i":37922,"as":"赫什菲尔德原子精修（HAR）技术成为一种有效可视化化学键共价性的实验手段。研究将该方法应用于含有钍-钍多中心键的三钍簇合物体系。实验结果与计算模拟高度吻合，证实了HAR技术在表征和可视化锕系元素复杂化学键方面的巨大潜力，为实现化学键的实验级常规可视化铺平了道路。","scd":null,"kp":["[化学键共价性的实验可视化]: 基于Hirshfeld原子精修(HAR)的方法","[钍键合测试体系]: 包含多中心钍的三钍簇分子"]},{"i":37923,"as":"Nature团队探讨了挠痒痒黑猩猩所发出的笑声节奏如何帮助人类了解语言的进化过程。此外，播客还讨论了人工智能在医学和计算机科学领域的广泛使用，可能会导致从业者在专业技能上出现退化的现象。","scd":null,"kp":["[AI技术应用的负面影响]: AI的使用可能会导致医学和计算机科学领域人类技能的退化"]},{"i":37924,"as":"针对锂金属电池内部界面不稳定的问题，研究人员设计了一种具有空间工程界面的准固态聚合物电解质。这种聚醚电解质界面能够同时保护锂金属负极和高压正极，有效提升了电池的安全性。该策略使电池能够在较宽的温度范围内稳定工作，并兼容多种正极材料，为实现高能量密度可充电电池提供了实用路径。","scd":null,"kp":["[准固态聚合物电解质]: 采用空间工程化界面设计以保护锂金属负极和高压正极","[高能可充电电池]: 具备高电压、宽温度范围适应性和高安全性"]},{"i":37925,"as":"针对高电压有机正极在钾双离子电池中氧化还原电位不足、结构稳定性差和动力学缓慢的问题，提出硫介导电荷离域设计策略。将硫原子引入吩嗪骨架，扩展π共轭并实现电荷与电子高效离域，从而提高电子导电性与氧化还原电位。基于此开发了硫取代的p型共轭聚合物正极材料。","scd":null,"kp":["[高电压p型聚合物正极]: 硫介导的电荷离域设计策略","[超低温钾双离子电池]: 克服了氧化还原电位不足、结构稳定性差和动力学迟缓的极端条件限制"]},{"i":37926,"as":"为解决质子交换膜水电解中阳极析氧反应的低铱负载与高活性稳定性难以兼顾的问题，设计了具有“动脉-毛细血管”质量转移网络的超细IrRuCu三元合金纳米海绵催化剂。其梯度核壳结构中的晶格失配引发外层活性Ir壳产生显著拉伸应变，诱导非破坏性动态表面交换，提升催化性能。","scd":null,"kp":["[PEM水电解阳极OER催化剂]: 超细IrRuCu三元合金纳米海绵","[催化剂结构特征]: 具备“动脉-毛细血管”层级传质网络","[PEM水电解应用优势]: 实现低铱负载量下保持高催化活性与稳定性"]},{"i":37927,"as":"为克服天然葡萄糖氧化酶不稳定且昂贵的缺陷，开发出一种具有双仿生结构的锰基单宁酸单原子纳米酶（TA-Mn SA）。该纳米酶在专为葡萄糖识别设计的单宁酸衍生分子口袋内嵌有原子级分散的Mn催化位点，具备优异的催化效率和高度底物选择性，可用于精确连续的汗液葡萄糖监测。","scd":null,"kp":["[汗液葡萄糖监测纳米酶]: 锰基单宁酸单原子纳米酶(TA-Mn SA)","[纳米酶结构设计]: 具有底物口袋的双重仿生架构","[替代天然葡萄糖氧化酶]: 解决天然酶内在不稳定性、高成本以及普通纳米酶缺乏底物特异性的问题"]},{"i":37928,"as":"针对三阴性乳腺癌高度异质性且缺乏可靶向分子的问题，开发出PEI/siENPP1@Mn-ZIF-8（PEMZ）基因-化学动力学-免疫纳米复合物。该复合物能够高效包载siENPP1并保护其免受降解，实现酸响应的胞质释放。PEMZ通过三重激活机制有效激活cGAS-STING通路，实现协同的三阴性乳腺癌治疗。","scd":null,"kp":["[三阴性乳腺癌治疗纳米复合物]: PEI/siENPP1@Mn-ZIF-8 (PEMZ)双金属MOF纳米复合物","[治疗机制]: 基因-化学动力学-免疫联合激活cGAS-STING通路"]},{"i":37929,"as":"提出基于手性与超分子协同作用的有机机械发光（ML）材料设计策略。利用手性打破对称性，定向超分子相互作用放大非中心对称晶体的宏观极性。该材料中的机械发光活性由净宏观极性主导，实现了兼具耐久性、高灵敏度、耐热性和偏振控制的高性能机械发光。","scd":null,"kp":["[高性能有机机械发光材料]: 具有明显宏观极性的非中心对称晶体设计策略","[机械发光材料特性]: 结合了耐久性、高灵敏度、热容差和圆偏振控制"]},{"i":37930,"as":"传统颜料易褪色且可能有毒，而仿生结构色颜料由微观结构调控光线产生强烈虹彩与金属光泽，具有安全、可持续的特点。该综述聚焦通过胶体纳米粒子、纤维素纳米晶体和嵌段共聚物等不同聚合物结构单元的受限自组装技术，制备聚合物光子颜料的光学性质及新兴应用。","scd":null,"kp":["[结构色色素]: 由微观结构调控光线产生，具有高耐久性且不易褪色"]},{"i":37931,"as":"利用空间限域化学气相沉积（CVD）策略，成功合成了厚度可调、低缺陷密度且具有严格化学计量比的高质量二维FeS纳米片。该合成方法克服了将FeS厚度降至二维极限的挑战，为深入探究二维FeS的交变磁阻和超高导电率等本征物理性质及其在自旋电子学中的应用提供了基础。","scd":null,"kp":["[2D FeS制备]: 空间限域化学气相沉积(CVD)","[2D FeS物理特性]: 交叉磁阻效应与超高导电性"]},{"i":37932,"as":"为突破能量间隙定律对近红外二区/三区（1500-2000 nm）高发光量子产率材料的限制，提出极化子工程策略。通过将Nd³⁺掺入CdTe量子点晶格，增加电荷局域化使辐射复合率提高150倍。该材料在1730 nm处实现宽带发射，水溶液中的光致发光量子产率达11.34±0.79%，斯托克斯位移超过900 nm。","scd":null,"kp":["[NIR-IIb/c荧光发射波长]: 1730 nm","[发光增强策略]: 极化子工程加速辐射复合速率","[辐射复合速率提升倍数]: 150倍"]},{"i":37933,"as":"为解决锂金属电池中枝晶生长、界面不稳定及离子电导率低的问题，构建了一种三层复合固体电解质。其外层为PEO/LiTFSI，内层由PEO/LiTFSI基质与聚多巴胺包覆的Li7La3Zr2O12（PDA@LLZO）及聚酯纤维增强。该设计结合了界面工程与机械增强，有效抑制了锂枝晶并实现了高效的离子传导。","scd":null,"kp":["[复合固态电解质结构]: 包含PEO/LiTFSI外层的三层结构","[固态电解质功能]: 抑制枝晶生长与实现高效离子传导"]},{"i":37934,"as":"针对可逆质子陶瓷电池空气电极反应迟缓以及传统煅烧温度带来的表面钝化或结晶不完全问题，采用热限制煅烧工艺在选定温度下动力学保留亚稳态纳米相，构建了富含异质界面的电极结构。通过控制煅烧温度诱导Ce选择性掺入Ba(Co)宿主晶格，大幅提升了析氧/氧还原（ORR/OER）反应的电催化活性。","scd":null,"kp":[]},{"i":37935,"as":"深入研究了有机电化学晶体管（OECTs）中核酸与共轭聚合物之间的相互作用。研究发现，带负电的核糖核酸（RNA）能够与共轭聚合物发生紧密的相互作用。这一发现阐明了有机半导体与生物分子在水溶液中的界面结合机制，为开发用于大流行病预防和健康监测的超灵敏生物传感器提供了理论基础。","scd":null,"kp":["[OCT生物传感]: 利用核酸与共轭聚合物在有机电化学晶体管中的紧密相互作用实现超灵敏生物标志物检测"]},{"i":37936,"as":"针对钙钛矿太阳能电池中四足自组装单分子层（SAMs）难以兼顾表面覆盖、效率和稳定性的问题，设计合成了两种新型芘中心四足SAMs（4PACz-Py-C2和4PACz-Py-C4）。通过间隔基工程调节分子堆积，促进空穴提取并抑制非辐射复合。基于4PACz-Py-C2优化的倒置钙钛矿太阳能电池实现了高效率与长期稳定性。","scd":null,"kp":["[倒置钙钛矿电池空穴传输层]: 基于芘的新型四足型自组装单分子层(SAM)"]},{"i":37937,"as":"针对高盐度下零液体排放（ZLD）太阳能蒸发技术的挑战，开发出一种包含熔融核-壳碳-聚合物纳米球多孔光热层的分层水凝胶蒸发器。表面光热层确保了有效热限域和丰富的液-汽界面，底层水凝胶基质维持连续的水分补给。该设计实现了定向排盐结晶和高效的零液体排放运行。","scd":null,"kp":["[太阳能蒸发器光热层]: 由融合的核-壳碳-聚合物纳米球组成的多孔界面光热层","[高盐水处理应用]: 定向盐结晶与零废液排放(ZLD)"]},{"i":37938,"as":"提出通过构建混合对称性铁电极化畸变态以稳定本征晶格贡献的设计策略，解决压电材料高压电性能与高温稳定性难以共存的问题。在Pb(Zr0.53Ti0.47)O3-xNb陶瓷体系中验证了该策略，优化后的N3组分展现出高压电系数d33，同时具备卓越的高温温度稳定性，适用于高温环境下的压电器件应用。","scd":null,"kp":["[高压电与高热稳定性设计策略]: 构建混合对称铁电畸变态以稳定本征晶格贡献","[材料体系]: Pb(Zr0.53)基铁电材料"]},{"i":37939,"as":"发现了在超润滑滑动界面（摩擦系数0.008）形成金刚石的现象，打破了机械运动界面碳物质倾向于石墨化的传统规律。通过在涂有MoS2的无定形碳表面滑动Al2O3球，利用范德华力封装碳磨损碎屑实现了金刚石的逆向演化。原子模拟揭示了该过程的微观机制，克服了传统金刚石生长的高压高温激活能壁垒。","scd":null,"kp":["[传统界面金刚石生长条件]: 压力5-6 GPa且温度900°C-1400°C","[超滑滑动界面摩擦系数]: 0.008","[超滑界面现象]: 发生金刚石形成"]},{"i":37940,"as":"报道了一种通过光触发自由基反应在聚合物主链中动态构建硫代羰基（C=S）基元，实现聚集诱导发光（AIE）的平台。该策略将非发光聚合物前体转化为AIE活性材料，设计了两种动力学可编程模块：开关1产生具有可逆“写-读-擦”特性的亚稳态C=S基元；开关2产生更稳定的C=S基元，成功实现了时间与序列依赖的4D发光加密。","scd":null,"kp":["[AIE聚合物制备]: 光触发自由基反应动态构建聚合物主链硫代羰基(C=S)基序","[应用特征]: 实现可编程的4D(时间/顺序依赖性)荧光加密"]},{"i":37941,"as":"开发出一种作为“活性氢储存库”的PdSb亚纳米片（PdSb ene）电催化材料。Sb的引入诱导p-d轨道杂化，调节了Pd的电子结构，促进水分解并有效抑制高电流密度下的竞争性析氢反应（HER）。该催化剂在大电流密度下实现了炔醇的高效电催化半加氢生成烯醇，显著提升了整体反应效率。","scd":null,"kp":["催化剂[电催化炔醇半加氢反应]: PdSb金属烯 (p-d轨道杂化)","[大电流密度]: 抑制竞争性析氢反应并维持高反应效率"]},{"i":37942,"as":"针对无负极锂金属电池（AFLMBs）因不均匀沉积导致的锂枝晶生长问题，提出分子界面工程策略。利用5-甲基-1H-四唑（MTZ）在铜箔表面形成化学键合的自组装单分子层。强Cu-N键不仅精确引入高密度成核位点，还促进电解液中LiNO3优先分解形成稳定的固态电解质界面，实现了能量密度达600 Wh/kg的无负极电池稳定运行。","scd":null,"kp":["能量密度[无负极锂金属电池]: 600 Wh/kg","[无负极锂金属电池]: 基于5-甲基-1H-四唑(MTZ)分子的化学键合自组装单分子层界面工程"]},{"i":37943,"as":"受金属硫蛋白动态金属平衡机制启发，提出一种基于β-羟基醚的离子调节网络涂层。该网络通过设定具有不同动力学和热力学偏好的竞争性结合位点，在静态材料中植入内在的“功能时钟”。以银离子为例，该涂层在植入早期释放金属离子实现感染触发的杀菌作用，后期则提供长效的抗生物膜和防垢保护。","scd":null,"kp":["涂层材料[植入支架抗感染与防污]: 仿金属硫蛋白的β-羟基硫醚离子调控网络","[双阶离子调控涂层]: 早期感染触发杀菌且具备长期抗生物矿化防污保护"]},{"i":37944,"as":"针对倒置钙钛矿太阳能电池埋底界面结晶行为难以控制的问题，提出一种N-杂环活化配位策略。将咪唑衍生物分子引入自组装单分子层（SAMs），与相邻的铅多卤化物建立π协同配位相互作用。该机制重塑了前驱体局部环境，有效稳定了SAM结构，同时精准调控了SAM-钙钛ite界面的成核与晶体生长，显著提升了器件的结构稳定性。","scd":null,"kp":["[倒置钙钛矿太阳能电池]: 采用N-杂环活化配位策略稳定埋底界面自组装单分子层并调控结晶行为"]},{"i":37945,"as":"具有聚集诱导发光（AIE）特性的近红外光激活I型光敏剂在深层肿瘤光动力治疗中极具应用潜力。然而，现有的D-A-D型苯并双噻二唑衍生物因内在能隙极小，严重限制了活性氧的生成，多仅用于生物成像与光热治疗。该研究提出了一种一氧化氮（NO）偶联策略，成功将广泛应用的D-A-D型近红外激活剂转化为有效的I型光敏剂，从而克服了活性氧生成的限制。","scd":null,"kp":["光敏剂[近红外二区聚集诱导发光]: 偶联一氧化氮转化为耐缺氧的I型光敏剂"]},{"i":37946,"as":"在传统的盐水蒸发系统中，盐溶质会遵循拉乌尔定律严重抑制水分蒸发，阻碍太阳能驱动蒸发。为解决此问题，研究提出了一种由配体场诱导的静电极化策略，通过在海藻酸钠水凝胶网络中共配位Fe3+和Co2+，在聚合物框架中引起显著的电子重排。这种极化配位环境破坏了水分子的协同氢键网络，从热力学角度激活水分子，打破了拉乌尔定律的限制，实现了高性能的太阳能蒸发。","scd":null,"kp":[]},{"i":37947,"as":"","scd":null,"kp":[]},{"i":37948,"as":"活体微血管网络中的单细胞动态可视化面临时空分辨率和灵敏度不足的挑战。该研究开发了一种优化的细胞标记方案，利用近红外染料吲哚菁绿（ICG）和DiR，分别为红细胞和中性粒细胞生成具有光谱差异的光声特征。该技术结合光声追踪与磁驱动，实现了对活体小鼠体内不同循环细胞群的非侵入性同时多重成像追踪，突破了光学显微镜穿透深度的限制。","scd":null,"kp":["[活体多路复用成像]: 结合光声追踪与磁 actuation 实现多重循环细胞群标记与监测"]},{"i":37949,"as":"膝关节负荷直接影响软骨的再生与退化，但现有非生物降解传感器需二次手术取出，阻碍了体内负荷的精确测量。该研究研发了一种全可降解的植入式压电压力传感器。该传感器采用生物相容性材料与单电极单端结构设计。在模拟体内环境的离体研究中，该传感器保持了超过2个月的稳定性能，是迄今报道的功能寿命最长的可降解压力传感器之一，为骨关节炎管理提供了新的监测手段。","scd":null,"kp":["传感器[膝关节骨关节炎监测]: 可降解单端压电压力传感器","[无线植入监测]: 生物可降解且无需二次手术取出"]},{"i":37950,"as":"精确排列“粘性基团”的缔合聚合物能够以分子精度编程材料属性。通过开发具有氢键粘性基团的非缠结聚合物模型，研究发现随机分布的粘性基团既不形成团簇也不改变流动特性；而位于链端的粘性基团即使在低浓度下也能驱动纳米团簇的形成。增加端基粘性基团数量会产生跨越八个数量度频率的橡胶平台，并表现出两个不同的弛豫时间尺度，证明了粘性基团分布决定了缔合聚合物的网络拓扑与宏观流变性质。","scd":null,"kp":["[缔合聚合物动力学]: 精确放置在链端的 stickers 驱动纳米簇形成并改变材料流变性质"]},{"i":37951,"as":"光声计算断层成像（PACT）的性能受限于超声检测孔径与灵敏度之间的权衡。为解决此问题，研究引入了三维孔径驱动光声断层成像（3D-ADPAT）技术。该方法将高数值孔径聚焦超声换能器（HNA-FUT）与相位反转聚焦等效重建（PIFER）算法相结合。该技术使空间分辨率提升了约2.21倍，对比噪声比提高了约10倍，有效克服了传统光声成像的限制，增强了体内可视化的图像对比度与穿透深度。","scd":null,"kp":["成像技术[光声计算断层扫描]: 三维孔径驱动光声断层扫描 (3D-ADPAT)","[技术特点]: 克服超声检测孔径与灵敏度之间的权衡限制"]},{"i":37952,"as":"","scd":null,"kp":[]},{"i":37953,"as":"骨质疏松性骨折愈合受限于以TH1/M1为主的失衡炎症微环境。研究发现，细胞外镁离子（Mg2+）以剂量和时间依赖的方式重塑骨免疫微环境。短期适量的Mg2+抑制TRPM7介导的钙离子峰及NFATc1驱动的促炎轴，从而促进TH2/M2免疫反应；然而，持续过量的Mg2+则会通过抑制Orai1/CaV依赖的钙离子通路，削弱TH2/M2反应。这表明镁离子的时间免疫调节对骨质疏松性骨折愈合至关重要。","scd":null,"kp":["[骨质疏松性骨折愈合]: 细胞外镁离子呈剂量和时间依赖性重塑骨免疫微环境","[免疫调控机制]: Mg²⁺ 抑制 TRPM7 介导的 Ca²⁺ 峰并调节 CD4+ T 细胞的时间免疫"]},{"i":37954,"as":"针对季节性流感、新冠病毒和呼吸道合胞病毒（RSV）通常需单独接种疫苗的现状，研究开发了一种基于纳米脂质体的多价亚单位疫苗平台。该平台共展示了三种季节性流感毒株的重组血凝素胞外域、新冠病毒受体结合域以及预融合状态的RSV F蛋白胞外域。在小鼠、雪貂和棉鼠模型中，接种该疫苗成功激发了对这三大主要呼吸道病毒的保护性免疫，其抗体反应水平与单一病毒疫苗相当甚至更好。","scd":null,"kp":["疫苗平台[多呼吸道病毒防控]: 纳米脂质体递送系统(共展示重组血凝素)","亚单位疫苗[靶向病原体]: 季节性流感病毒、SARS-CoV-2及呼吸道合胞病毒(RSV)"]},{"i":37955,"as":"NLRP3炎症小体与心血管、代谢、神经退行性疾病等多种与年龄相关的疾病密切相关。尽管完全敲除Nlrp3可预防这些疾病，但这并非可行的临床治疗策略，目前药物研发多集中于部分抑制NLRP3。研究发现，在更接近临床部分抑制表型的Nlrp3单倍体不足小鼠中，会出现NLRP1与NLRP3的补偿性相互作用，这种机制反而加速了小鼠的衰老。这一反直觉现象揭示了部分抑制NLRP3可能存在的潜在副作用。","scd":null,"kp":["药理靶点[年龄相关退行性疾病]: NLRP3炎症小体","[NLRP3单倍剂量不足]: 暴露NLRP1-NLRP3代偿性相互作用并加速小鼠衰老","[完全消除NLRP3策略]: 不适用于退行性疾病的广泛临床治疗"]},{"i":37956,"as":"尽管铪锆氧化物（HZO）作为铁电材料已广泛应用于CMOS器件，但其机电响应特性尚未被充分发掘。该研究证明，在24千伏/厘米的临界电场以上，外延HZO薄膜中由电致伸缩驱动的相不稳定性触发了非极性相与极性相之间的转变。这种转变激活了约1000皮米/伏的极高外在压电响应，并在偏压稳定下产生了超过10000皮米/伏的巨大准压电应变。","scd":null,"kp":["临界电场强度[铪锆氧化物(HZO)薄膜产生巨准压电响应]: 24 kV/cm","[电致伸缩驱动相不稳定性]: 诱发外延HZO薄膜的巨准压电效应"]},{"i":37957,"as":"为推进功能性精准肿瘤学，研究开发了泛癌患者来源的类器官（PDO）平台，包含来自15种癌症的191例患者的220个PDO。综合表征显示，该平台与亲本肿瘤高度一致：组织病理学一致性达93%，驱动突变中位基因组一致性为80%，基因表达相关性达0.85。传代10次后表达谱依然稳定，且85%的主要肿瘤克隆得以保留。功能检测表明，即使一致性较低的PDO也保留了关键的致癌驱动因子，证实了其作为疾病模型和药敏筛选工具的可靠性。","scd":null,"kp":["类器官平台(PDO)[泛癌种及样本规模]: 涵盖15种癌症类型191例患者的220个PDO","组织病理学一致性[PDO与亲本肿瘤对比]: 93%","基因组中位一致性[驱动突变]: 80%","中位基因表达相关性[PDO与亲本肿瘤对比]: 0.85","[基因表达谱稳定性]: 连续10次传代后保持稳定，确保长期药物筛选重现性"]},{"i":37958,"as":"RNA修饰通路在多种癌症中失调，其中METTL3作为m6A甲基转移酶复合物的核心成分，不仅在肿瘤进展中发挥m6A依赖性作用，还具有非m6A依赖的促癌机制。研究发现，在乳腺癌患者的肿瘤细胞中，METTL3发生错误定位而转移至细胞质，从而促进了致癌表型。在细胞质中，METTL3与胞吐作用的关键调节因子EXOC7直接相互作用，从而促进肿瘤细胞的物质胞吐过程，这一机制完全独立于其m6A甲基转移酶活性。","scd":null,"kp":["METTL3功能[m6A非依赖性]: 调节细胞胞吐作用","核心分子[m6A甲基转移酶复合物]: 甲基转移酶样3 (METTL3)","[癌症进展与转移关键修饰]: N6-甲基腺苷(m6A)"]},{"i":37959,"as":"干细胞微环境的老化如何影响干细胞维持尚不清楚。利用果蝇睾丸模型研究发现，微环境细胞衍生的骨形态发生蛋白（BMP）信号水平随年龄增长而下降，导致生殖干细胞中转录共抑制因子Hairless表达增加。高水平的Hairless减少了RNA结合蛋白Imp的含量，进而引起干细胞因子Chinmo丢失，最终引发细胞外基质异常积累、干细胞位置偏移以及微环境退化。通过在微环境中过表达BMP信号或上调Imp，可以延缓这些衰老表型。","scd":null,"kp":["转录辅阻遏物[果蝇睾丸干细胞衰老]: Hairless表达量随年龄增加","[微环境衰老机制]: 骨形态发生蛋白(BMP)信号水平随年龄下降"]},{"i":37960,"as":"多梳（PcG）蛋白聚集形成的PcG小体与发育和分化过程中的基因调控相关。利用酪胺信号放大测序技术，研究发现PcG小体关联的基因组区域包含特定的着丝粒和端粒位点。这些区域富含抑制性标记H3K27me3和H3K9me3，缺乏活性标记H3K4me3，且染色质可及性低。此外，PcG小体周围存在高密度的复制起点，这与复制起始识别复合物相关蛋白（ORCA/LRWD1）定位于此有关，表明PcG介导的三维基因组组织直接控制DNA复制的时机。","scd":null,"kp":["基因组3D结构[PcG小体(多梳蛋白体)结合区域]: 富集特定着丝粒和端粒位点","组蛋白修饰特征[PcG小体相关基因组区域]: 富集抑制性标记H3K27me3和H3K9me3","[多梳蛋白介导的3D基因组组织]: 控制DNA复制时机"]},{"i":37961,"as":"全球气候变化下，二氧化碳浓度升高、气候变暖和干旱对生态系统的交互作用至关重要。基于长期草地实验的研究表明，虽然单独的二氧化碳浓度升高（eCO2）或气候变暖对生态系统水分利用效率和碳利用效率的影响有限，但这二者的交互作用却产生了强烈的协同效应。这种协同效应显著放大了生态系统呼吸作用，进一步加剧了干旱对草地碳通量和水通量的负面影响，削弱了生态系统对未来气候极端事件的韧性。","scd":null,"kp":["增温与CO2升高协同效应[草地碳水和通量]: 加剧干旱对生态功能的负面影响"]},{"i":37962,"as":"细胞在迁移过程中能感知并对多种物理线索做出反应。研究发现，细胞长时间暴露于与生理或病理相关的静水压升高环境中，会显著降低其对基底刚度、流体粘度、流体作用力及流体阻力的迁移敏感性。这种降低的机械敏感性在高压刺激移除后仍可持续数天，表明细胞具有静水压“记忆”。机制上，高压下调了Rho/MRTF/SRF通路，激活了不依赖于肌球蛋白II的机械传感机制，从而改变了细胞的迁移响应。","scd":null,"kp":["静水压影响[细胞迁移机制]: 降低细胞对基底刚度、流体黏度等机械力的迁移敏感性"]},{"i":37963,"as":"现有的机械超表面在交互式显示领域应用时，常面临易碎、响应慢及难以集成功能系统等问题。该研究开发了一种坚固、响应迅速且多功能的软超表面。该系统通过磁驱动技术实现表面形状重构，为人机交互提供同步的视觉和触觉反馈。软表面包含一个6×6的弹性体像素阵列，每个像素由磁引力单独驱动，实现了直观的物理人机交互，克服了传统系统脆弱和延迟的缺点。","scd":null,"kp":["软超表面[人机交互功能特性]: 坚固耐用、快速响应且支持多功能双向有形交互"]},{"i":37964,"as":"豆科植物根瘤中的共生固菌会分化为类菌体。在一年生豆科植物（如IRLC分支）中，类菌体由结节特异性富含半胱氨酸（NCR）多肽诱导发生不可逆的终末分化，这增强了固氮作用但限制了根瘤寿命。而在具有不定根瘤的多年生豆科植物中，共生体系必须长期维持，因此类菌体不能发生终末分化。该研究鉴定出一类结节特异性多肽家族，它们能够调节根瘤菌生理功能并促进固氮，同时不导致类菌体的终末分化，从而适应了多年生植物的长期共生需求。","scd":null,"kp":["[共生固氮策略]: 不可逆末端分化程序适合一年生豆科植物并增强固氮作用，但限制根瘤寿命","分化状态[根瘤菌]: 分化为类菌体（可保持存活或经历末端分化）"]},{"i":37965,"as":"","scd":null,"kp":[]},{"i":37966,"as":"","scd":null,"kp":[]},{"i":37967,"as":"","scd":null,"kp":[]},{"i":37968,"as":"研究开发了一种光诱导锰催化平台，用于[1.1.1]螺桨烃的顺序双官能团化反应，实现多官能团化磺酰基双环[1.1.1]戊烷(BCPs)的模块化合成。BCPs是药物化合物中芳香环的生物电子等排体，但传统合成方法受限于底物范围窄和官能团兼容性差。该催化平台克服了这些限制，能够构建多种磺酰基-BCP衍生物，包括引入─Cl、─Br、─I、─CN、─SCD3等官能团，为药物合成提供了实用新策略。","scd":null,"kp":["核心反应物[[1.1.1]螺桨烷]: 双环[1.1.1]戊烷(BCP)衍生物","技术痛点[磺酰基BCP衍生物合成路线]: 底物范围窄且官能团耐受性受限","[合成平台特性]: 光诱导锰催化双官能化通用平台"]},{"i":37969,"as":"研究发现水稻钙调蛋白样蛋白OsCML27通过OsMRLK63-OsCML27-OsRbohB模块调节水稻耐旱性。OsCML27作为OsRbohB介导活性氧(ROS)产生的灵活制动器。OsCML27负调控水稻耐旱性，过表达株系水分流失率快且干旱下存活率低，而突变体脱水速率较慢。机制上，受体激酶OsMRLK63能够与OsCML27相互作用并使其磷酸化，从而精细调控ROS信号以响应干旱胁迫。","scd":null,"kp":["调控模块[水稻耐旱机制]: OsMRLK63-OsCML27-OsRbohB","调控蛋白[水稻]: 类钙调蛋白OsCML27（作为OsRbohB介导的活性氧ROS产生的柔性制动器）","技术特征[OsCML27过表达株系]: 负向调节水稻耐旱性，失水速度更快"]},{"i":37970,"as":"","scd":null,"kp":[]},{"i":37971,"as":"研究报道了一种铁催化脱羧羰基烷基化胺化策略，用于合成复杂的脂肪族胺类。该反应以醛、胺和羧酸为原料，在室温温和光照及HFIP溶剂中进行，无需额外添加剂，副产物仅为环境友好的二氧化碳和水。该合成方法表现出极高的实用性和绿色环保特征，对具有空间位阻的底物和广泛的官能团具有出色的兼容性，为从廉价易得原料合成生物活性分子中的脂肪胺提供了理想的新途径。","scd":null,"kp":["催化剂[脂肪胺合成]: 铁催化","反应底物[脱羧羰基化烷基胺化]: 醛类、胺类和羧酸","反应溶剂[脱羧羰基化烷基胺化]: HFIP（六氟异丙醇）","反应条件[脱羧羰基化烷基胺化]: 室温温和光照射"]},{"i":37972,"as":"研究通过在钯掺杂的氧化铟(In2O3)纳米催化剂中引入氧 vacancy (Ov)，成功实现了芳基卤化物单氨基羰基化(MC)和双氨基羰基化(DC)选择性的完全反转。氧空位调节了钯原子的第二外层配位域(SBCSs)。该纳米催化剂在合成多种酰胺和α-酮酰胺（130个实例）中展现出优异的活性、选择性和可重复使用性。这一新策略解决了长期困扰学术界和工业界对MC和DC反应选择性难以精确控制的难题。","scd":null,"kp":["催化剂[芳基卤化物氨基羰基化]: 掺钯的In2O3纳米催化剂","调控机制[化学发散性氨基羰基化]: 引入氧空位可完全实现从单羰基化(MC)到双羰基化(DC)的选择性反转"]},{"i":37973,"as":"研究利用原子分辨率扫描透射电子显微镜（包括HAADF成像、EDX和EELS）探究了LSAT（La0.24Sr0.76Al0.62Ta0.38O3）晶界处的巨柔性电特性。结果显示，钽元素在晶界处发生偏析，形成了独特的化学有序结构。这种晶界处原子尺度的有序结构是产生巨大挠曲电效应（即应变梯度产生极化响应的机电耦合机制）的关键原因，为高性能柔性电材料的结构设计提供了原子层面的依据。","scd":null,"kp":["材料体系[晶界挠曲电效应研究]: La0.24Sr0.76Al0.62Ta0.38O3 (LSAT)","效应机制[挠曲电效应]: 利用原子尺度的晶界有序化结构实现巨大的机电耦合（极化对应变梯度的响应）"]},{"i":37974,"as":"研究揭示了拟南芥耐盐性的分子机制：磷脂酶D（PLDα1和PLDδ）与细胞壁传感器FERONIA(FER)发生物理相互作用。PLD衍生的磷脂酸(PA)能够稳定FER在质膜上的定位并增强其激酶活性。PA驱动的FER激活促进了CC1蛋白的磷酸化，从而加速了盐胁迫下CC1的回收和微管重组。遗传分析证实了PLDα与相关基因在调控植物细胞壁重塑和耐盐适应性中具有协同功能。","scd":null,"kp":["底物互作[FERONIA受体激活]: 磷脂酶Dα1(PLDα1)和PLDδ与FER发生物理相互作用","激活机制[质膜定位与激酶活性增强]: PLD衍生的磷脂酸(PA)稳定质膜上的FER并增强其激酶活性"]},{"i":37975,"as":"研究开发了一种异质模态表皮液态金属贴片(HELP)，用于可穿戴心肺监测。通过铟驱动的银纳米线合金化锚定液态金属消除了信号漂移。该传感器采用分级半球形突起作为模拟渐进应变门控，实现了0.998的线性度、小于0.4%的迟滞、0.01%的应变检测限以及超过50万次循环的耐用性。双通道设计允许同步实现对应变不敏感的心电图监测和超灵敏呼吸感知，解决了慢性呼吸疾病家庭持续监测的工具短缺问题。","scd":null,"kp":["技术特性[可穿戴应变传感器]: 结合了高精度、线性度与稳定性","合金化机制[液态金属贴片]: 铟驱动的银纳米线合金化锚定液态金属以消除漂移","微观结构设计[模拟压缩门控]: 分级半球形凸起作为渐进式模拟应变门控"]},{"i":37976,"as":"研究阐明了机械应力导致椎间盘血管化及退变(IDD)的机制。机械应力激活Hippo信号通路并诱导髓核(NP)细胞中YAP蛋白降解。NP特异性敲除Yap的小鼠表现出椎间盘血管化加剧。机制上，YAP通过液-液相分离形成生物分子凝聚物，招募并隔离转录因子SNAI1。当机械应力破坏YAP凝聚物并释放SNAI1时，SNAI1介导的转录得以恢复，导致血管化相关基因上调，引发椎间盘退变和腰背痛。","scd":null,"kp":["致病机制[椎间盘退变血管化]: 机械应力诱导Hippo信号传导，促进髓核细胞中YAP降解","表型特征[髓核特异性YAP条件性敲除小鼠]: 椎间盘血管化增强"]},{"i":37977,"as":"研究开发了一种名为“极化衍生摩擦显微镜”的纳米尺度成像新技术，用于观察铁电体的极化。利用扫描探针显微镜针尖施加高接触力产生不对称摩擦响应，结合多场耦合连续介质力学模拟，证实该摩擦不对称性源于挠曲电效应诱导的极化与铁电极化的竞争或增强。该技术通过机械摩擦信息直接探测铁电极化方向，实现了快速、低成本且无需外加电压的铁电畴空间分辨成像。","scd":null,"kp":["探测机制[铁电极化可视化]: 扫描探针显微镜尖端施加高接触力诱导的不对称摩擦响应","微观成因[摩擦不对称性]: 由翻转/相变等微观行为导致"]},{"i":37978,"as":"","scd":null,"kp":[]},{"i":37979,"as":"研究确认了一种名为SCumPo的宇宙微小球粒新亚型，其特征为堆晶结构、贫氧-16(16O)同位素特征、贫镍橄榄石斑晶、频繁的铁镍硫液滴以及异常富硫的基质。这些含有磁铁矿缺乏的特征表明，其小行星母体在剧烈碰撞熔融期间处于极度还原条件。该发现证实了部分具有异常氧同位素组成的微陨石来源于近地CY球粒陨石小行星，填补了陨石收藏中缺失的小行星源类型。","scd":null,"kp":["异常氧同位素组成的宇宙球粒比例[地球附近CY球粒陨石小行星来源]: 约10%","新鉴定微陨石亚类[富硫橄榄石堆积型宇宙球粒]: 具有证明橄榄石晶体沉降的堆积结构"]},{"i":37980,"as":"研究开发了一种掺杂Mn2+的氮化铝(AlN:Mn2+)发光材料，展现出明亮的橙色光致发光、长余辉发光、热释光及摩擦/声波/冲击等多模式机械发光(ML)特性。该多模态发光材料能够响应多种外部机械和声学刺激，将机械作用与声波直接转化为可见光。这为新一代应力传感、结构健康监测及光电器件提供了一种能够可视化机械信号的多功能前沿材料。","scd":null,"kp":["发光材料[声波和机械力刺激下]: 锰离子掺杂氮化铝(AlN:Mn2+)","发光特性[AlN:Mn2+材料]: 明亮的橙色光致发光和机械发光"]},{"i":37981,"as":"","scd":null,"kp":[]},{"i":37982,"as":"通过Arase卫星对2024年5月超级地磁风暴期间近地环电流离子的原位测量，发现源于地球的重离子在承载环电流中占据绝对主导地位。尽管当时太阳风密度很高，但太阳风对环电流能量密度的贡献微乎其微。这一观测结果证实，地球自身的离子向外供给及磁层内的输运过程在超级地磁暴环电流的增强中起到了决定性作用。同时，超强环电流甚至渗透到了极为靠近地球的磁层区域。","scd":null,"kp":["环电流主要离子来源[2024年5月超级地磁暴期间近地空间]: 呈现前所未有的地球起源重离子绝对优势","太阳风离子贡献率[超级地磁暴期间环电流]: 极少"]},{"i":37983,"as":"","scd":null,"kp":[]},{"i":37984,"as":"","scd":null,"kp":[]},{"i":37985,"as":"研究以多环芳烃芘的衍生物为模型系统，系统揭示了分子轨道节点工程对化学活性和室温磷光(RTP)的决定性影响。实验发现，在分子轨道节点位置进行Sonogashira偶联反应的产率显著低于反节点位置，这源于节点处分子轨道振幅的抑制。光谱表征显示，节点与反节点取代产生的光物理性质存在显著差异。该研究将基础量子力学规则与实验反应性及发光性能直接关联，为新型RTP材料设计提供了精确指导。","scd":null,"kp":["化学反应性与物理性质调控机制[多环芳烃衍生物模型系统]: 节点和反节点位置的取代基支配作用","系统研究空白[共轭芳族化合物节点和反节点取代基实验规律]: 缺乏系统性的量子力学实验验证"]},{"i":37986,"as":"《自然·电子学》发表的研究介绍了一种基于MXene与压敏胶复合材料制成的高密度、低漂移干式电极阵列。该新型电极技术能够对植物受环境刺激产生的电信号波进行实时、高分辨率的可视化监测。该成果为植物电生理学研究及植物与环境的交互响应监测提供了强有力的前沿电子学工具。","scd":null,"kp":["电极阵列特征[基于MXene-压敏胶复合材料的植物电信号监测]: 低漂移、高密度、干式电极","应用功能[MXene电极阵列]: 实现环境刺激下植物电波的可视化"]},{"i":37987,"as":"《科学进展》发表文章，报道了一种MXene网格架构。该架构提供了一个贴合、透明且高效的天线平台，适用于可穿戴设备和柔性超表面。","scd":null,"kp":["天线平台特征[MXene网格架构]: 保形、透明且高效","适用场景[MXene柔性透明天线]: 可穿戴设备和柔性超表面"]},{"i":37988,"as":"","scd":null,"kp":[]},{"i":37989,"as":"研究证明人参胚胎原表皮能够高效生产人参皂苷，其积累水平与林下参相当。单细胞转录组和质谱成像分析表明，胚胎愈伤组织（EC）产生皂苷的能力与基因位点组蛋白乙酰化升高和染色质可及性增强有关。提高组蛋白乙酰化水平可促进人参皂苷代谢。","scd":null,"kp":["人参皂苷高效合成天然区室[人参胚胎原生分生组织]: 具有与人参主体可比拟的皂苷积累水平","技术解析方法[人参胚胎原生分生组织]: 单细胞转录组与质谱成像分析"]},{"i":37990,"as":"研究提出了SMURF，一种利用深度学习将mRNA映射到附近细胞核的跨平台软分割算法。该算法能将细胞投影到笛卡尔坐标系以揭示复杂的组织架构。SMURF在分配mRNA到单细胞的准确度上优于现有方法，能稳健地揭示多种组织中的转录程序和细胞类型组织结构。","scd":null,"kp":["算法特征[空间转录组学数据分配]: 跨平台软分割算法(SMURF)，利用深度学习将mRNA映射至附近细胞核","架构分析功能[SMURF算法]: 通过将细胞投影至笛卡尔坐标展开复杂组织架构，分析细胞类型组织和基因表达梯度"]},{"i":37991,"as":"研究提出了一种粗粒度RNA计算模型PlanarFold。该模型结合二维分子动力学模拟与动态规划，探索RNA的动态行为，速度比全原子模型快四个数量级。在二级结构层面上，PlanarFold能定量重现天然二级结构、热力学、动力学和机械特性等实验结果。","scd":null,"kp":["计算模型特征[二维空间RNA动力学]: 粗粒度分子动力学模型结合动态规划","模拟加速倍数[与全原子模型相比]: 超过四个数量级"]},{"i":37992,"as":"研究揭示了CRISPR-Cas13a系统与HicAB毒素-抗毒素模块之间的功能协同作用。生化和结构分析表明，抗毒素HicB具有毒性，Cas13a直接激活HicB从而抑制细胞生长并保护细菌免受噬菌体感染。结构分析显示，Cas13a结合促进了HicB四聚体的空间邻近性。","scd":null,"kp":["免疫系统协同机制[CRISPR-Cas13a与HicAB毒素-抗毒素模块]: 潜在的功能协同抗病毒防御作用","毒素激活效应[典型毒素-抗毒素系统]: 通过诱导生长停滞或降低细胞适应性来限制噬菌体繁殖"]},{"i":37993,"as":"研究报道了 Camelina sativa 参考基因组的改进组装，以及 Camelina microcarpa 的三个额外基因组组装（一个四倍体，两个染色体数量发散的六倍体）。研究发现了 Camelina 属的第四个亚基因组（Type 2），其具有独特的染色体重排。在该物种中，第二个亚基因组表现出基因表达显性。","scd":null,"kp":["染色体数目[C. microcarpa Type 1六倍体]: 2n = 40","染色体数目[C. microcarpa Type 2六倍体]: 2n = 38","基因组特征[骆驼属]: 揭示第四亚基因组"]},{"i":37994,"as":"研究结合神经成像和多变量模式分析，以国际象棋为模型揭示了专家大脑的三个原则：1. 表征内容从表面视觉特征向高级关系信息转变；2. 表征结构转变为低维和优化状态，代码更紧凑且组织更有序；3. 保留了精确评估所需的细节信息。","scd":null,"kp":["[专家大脑信息表征]: 采用低维和优化的形式编码高水平领域知识以实现高效利用"]},{"i":37995,"as":"基于对法国国家森林清查中超50万棵树的分析，研究发现树木死亡率在主要物种中均有上升。集成建模表明，树木大小、竞争和季节性气候异常是主要死亡驱动因素。温暖的冬春两季是最常见且最有影响力的气候预测因素，温暖夏季同样具有影响力。","scd":null,"kp":["样本规模[法国国家森林清查]: >500,000棵树","时间跨度[法国国家森林清查]: 2015-2023年","[树木死亡驱动因素]: 树木尺寸、竞争和季节性气候异常（温暖的冬春季节）"]},{"i":37996,"as":"研究提出了一种基于拓扑声学的几何相位传感方法，用于火山监测。该方法通过整合台阵信号，利用几何相位变化（Δη）捕获波路径积分介质扰动。在基拉韦厄火山的应用表明，Δη能够准确追踪2018年喷发周期中的岩浆加压前兆和同喷发火山口坍塌。","scd":null,"kp":["[火山监测技术]: 基于拓扑声学的几何相位传感方法","[几何相位传感原理]: 编码地震波场的内在几何结构并整合台站阵列信号"]},{"i":37997,"as":"研究利用卫星总初级生产力数据，绘制了分辨率为0.05度的水稻、大豆、玉米和小麦全球温度最适点地图。研究发现作物温度最适点存在普遍的空间异质性，在亚热带地区达到峰值。这种热驯化受当地温度、水分可用性和太阳辐射影响，提升了气候变暖下预测的准确性。","scd":null,"kp":["空间分辨率[全球作物最适温度图]: 0.05度","最适温度[水稻]: 28.63 ± 2.65 °C","最适温度[大豆]: 27.34 ± 2.34 °C","最适温度[玉米]: 26.12 ± 3.46 °C","最适温度[小麦]: 24.73 ± 3.41 °C"]},{"i":37998,"as":"Kongming防御系统由KomB和KomC组成，在噬菌体感染时被dITP激活。结构与功能分析表明，KomBC组装成由4:4重复单元构成的螺旋丝状体。dITP与KomB结合会引发构象重排，重塑丝状体架构，使KomC转变为具有NADase活性的构象，从而发挥抗噬菌体作用。","scd":null,"kp":["[孔明抗噬菌体防御系统]: 由非典型信号核苷酸dITP（噬菌体感染时产生）激活","效应复合物[KomBC]: 组装成螺旋丝状结构","复合物组成[效应复合物KomBC]: 包含KomB（非经典嘌呤NTP焦磷酸酶）和KomC（含SIR2结构域蛋白）"]},{"i":37999,"as":"通过对撒哈拉以南非洲60,558个农业地块的估算，研究发现女性小农户受高温影响导致的作物减产是男性的2至2.5倍。家庭内部在劳动力调整和补偿性投资方面存在异质性和不同的适应策略。极端高温每增加一个度日，会对女性农户的产量造成更大的损失。","scd":null,"kp":["样本规模[撒哈拉以南非洲农业地块]: 60,558个地块","[女性小农热暴露风险]: 承受不成比例的作物损害和粮食不安全风险"]}]);